/* Conversation topics — one entry per topic-level. Same scene at every
   level; the French gets harder, not the shop. Built from the spec in
   docs/french-expansion-spec.md. */
"use strict";

const TOPIC_ORDER = ["clothes", "restaurant", "bar", "festival", "breakfast", "hotel", "restaurant-pro", "trip", "rent", "interview"];
const TOPIC_LEVELS = ["A1", "A2", "B1", "B2", "C1", "C2"];

const TOPICS = {
  "clothes-A2": {"slug": "clothes", "level": "A2", "title": "Acheter des vêtements", "place": "C&A, rue Neuve, Bruxelles", "register": "vous", "registerNote": "Vous with shop staff, always — even if the assistant looks twenty. In a Belgian shop you also say « Bonjour » out loud when you walk in and « Merci, bonne journée » when you leave; skipping the greeting is read as rude. Tu is only for friends your own age.", "vocab": [{"id": "fvc-clothes-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pull", "en": "the jumper / sweater", "format": "fr2en", "options": ["the jumper / sweater", "the cardigan", "the coat", "the shirt"], "a": 0, "trap": "le gilet — a cardigan, which buttons up the front; a pull goes over your head", "expl": "« Un pull » (short for pull-over) is anything you pull on over your head. If it opens at the front it is « un gilet »."}, {"id": "fvc-clothes-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pantalon", "en": "the trousers", "format": "fr2en", "options": ["the trousers", "the shorts", "the tights", "the belt"], "a": 0, "trap": "le short — shorts, which really are short", "expl": "French keeps it singular: « un pantalon » = one pair of trousers. « Des pantalons » means several pairs."}, {"id": "fvc-clothes-A2-03", "level": "A2", "pos": "noun", "gender": "f", "fr": "la chemise", "en": "the shirt (button-up)", "format": "fr2en", "options": ["the button-up shirt", "the T-shirt", "the nightdress", "the jacket"], "a": 0, "trap": "le chemisier — the women's blouse, same root, different garment", "expl": "« La chemise » has buttons and a collar. A T-shirt stays « le t-shirt »; a woman's blouse is « le chemisier »."}, {"id": "fvc-clothes-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le manteau", "en": "the coat", "format": "en2fr", "options": ["le manteau", "le blouson", "le gilet", "le tablier"], "a": 0, "trap": "le blouson — a short casual jacket, not a long winter coat", "expl": "« Le manteau » is the long coat you need from November in Brussels. « Le tablier » is an apron."}, {"id": "fvc-clothes-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la veste", "en": "the jacket", "format": "fr2en", "options": ["the jacket", "the waistcoat", "the dressing gown", "the vest / undershirt"], "a": 0, "trap": "le gilet — the waistcoat or cardigan, sleeveless or buttoned", "expl": "« La veste » is a jacket, suit or casual. Careful: English 'vest' is a false friend — that is « le maillot de corps »."}, {"id": "fvc-clothes-A2-06", "level": "A2", "pos": "noun", "gender": "f", "fr": "la robe", "en": "the dress", "format": "en2fr", "options": ["la robe", "la jupe", "la blouse", "la chemise"], "a": 0, "trap": "la jupe — a skirt, only the bottom half", "expl": "« La robe » is one piece, top and bottom together. « La blouse » is a work overall, not a nice blouse."}, {"id": "fvc-clothes-A2-07", "level": "A2", "pos": "noun", "gender": "f", "fr": "la jupe", "en": "the skirt", "format": "fr2en", "options": ["the skirt", "the dress", "the apron", "the hem"], "a": 0, "trap": "la robe — a dress; learners swap the two constantly", "expl": "Jupe = skirt only. Remember « la mini-jupe » and you will not confuse it with « la robe »."}, {"id": "fvc-clothes-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "les chaussures", "en": "the shoes", "format": "en2fr", "options": ["les chaussures", "les chaussettes", "les chaussons", "les bottes"], "a": 0, "trap": "les chaussettes — socks; two syllables apart, a whole layer of clothing apart", "expl": "Chaussures = shoes, chaussettes = socks, chaussons = slippers, bottes = boots. Same family, say them out loud until they separate."}, {"id": "fvc-clothes-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "les chaussettes", "en": "the socks", "format": "fr2en", "options": ["the socks", "the shoes", "the slippers", "the tights"], "a": 0, "trap": "les chaussures — shoes", "expl": "« Une paire de chaussettes » is how they are sold. Tights are « un collant », singular."}, {"id": "fvc-clothes-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "le t-shirt", "en": "the T-shirt", "format": "en2fr", "options": ["le t-shirt", "le débardeur", "le maillot", "le pull"], "a": 0, "trap": "le débardeur — a sleeveless top", "expl": "Borrowed straight from English and pronounced « tee-shirt ». « Le maillot » is a sports jersey or a swimsuit."}, {"id": "fvc-clothes-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le training", "en": "the tracksuit (Belgium)", "format": "fr2en", "options": ["the tracksuit", "the trainers (shoes)", "the training course", "the sports bag"], "a": 0, "trap": "English 'training' — in Belgian French the word is the garment, not the course", "note": "Belgian French. In France a tracksuit is « un survêtement » or « un jogging »; « un training » would just be understood as a training session.", "expl": "In a Brussels shop « les trainings sont au deuxième étage » sends you to tracksuits."}, {"id": "fvc-clothes-A2-12", "level": "A2", "pos": "noun", "gender": "f", "fr": "la taille", "en": "the size (clothing)", "format": "fr2en", "options": ["the size of clothing", "the shoe size", "the price", "the fitting room"], "a": 0, "trap": "la pointure — the size, but only for shoes", "expl": "« Quelle taille ? » for a jumper, « quelle pointure ? » for shoes. « La taille » also means the waist: « ce pantalon me serre à la taille »."}, {"id": "fvc-clothes-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pointure", "en": "the shoe size", "format": "fr2en", "options": ["the shoe size", "the clothing size", "the shop counter", "the heel"], "a": 0, "trap": "la taille — the clothing size", "expl": "Only shoes have « une pointure ». Belgium and France both use European numbers: 36 to 47."}, {"id": "fvc-clothes-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la cabine d'essayage", "en": "the fitting room", "format": "en2fr", "options": ["la cabine d'essayage", "la caisse", "la vitrine", "la réserve"], "a": 0, "trap": "la caisse — the till, where you pay, not where you change", "expl": "Staff usually shorten it: « les cabines sont au fond ». « La réserve » is the stockroom out the back."}, {"id": "fvc-clothes-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "la caisse", "en": "the till / checkout", "format": "fr2en", "options": ["the till / checkout", "the changing room", "the shop window", "the shelf"], "a": 0, "trap": "la cabine — the changing room", "expl": "« Je vous encaisse à la caisse » = I'll ring you up at the till. In a Delhaize the sign says « caisses »."}, {"id": "fvc-clothes-A2-16", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tirette", "en": "the zip (Belgium)", "format": "fr2en", "options": ["the zip", "the drawer", "the light switch cord", "the button"], "a": 0, "trap": "le tiroir — a drawer; the two words look related but are not", "note": "Belgian French. In France a zip is « une fermeture éclair » or « un zip »; « une tirette » there is a small pull-tab or a pull-out shelf.", "expl": "« La tirette est cassée » is exactly what you say when the zip breaks — and what you say to get it exchanged."}, {"id": "fvc-clothes-A2-17", "level": "A2", "pos": "noun", "gender": "f", "fr": "la poche", "en": "the pocket", "format": "en2fr", "options": ["la poche", "la manche", "la doublure", "la couture"], "a": 0, "trap": "la doublure — the lining, also inside the garment", "expl": "« Ce pantalon a des poches profondes. » Note « la couture » = the seam, and also 'fashion' as in haute couture."}, {"id": "fvc-clothes-A2-18", "level": "A2", "pos": "noun", "gender": "f", "fr": "la manche", "en": "the sleeve", "format": "fr2en", "options": ["the sleeve", "the handle", "the collar", "the cuff"], "a": 0, "trap": "le manche (masculine) — a handle; only the gender separates them", "expl": "« Une chemise à manches longues » = a long-sleeved shirt. Masculine « le manche » is the handle of a knife."}, {"id": "fvc-clothes-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le col", "en": "the collar", "format": "en2fr", "options": ["le col", "le coude", "le bouton", "le pli"], "a": 0, "trap": "le cou — the neck itself; le col is what goes round it", "expl": "« Un pull à col roulé » is a polo-neck. « Le col » is also a mountain pass."}, {"id": "fvc-clothes-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bouton", "en": "the button", "format": "fr2en", "options": ["the button", "the buttonhole", "the badge", "the hook"], "a": 0, "trap": "la boutonnière — the buttonhole the button goes through", "expl": "« Il manque un bouton » = a button is missing — a good reason to ask for a reduction."}, {"id": "fvc-clothes-A2-21", "level": "A2", "pos": "noun", "gender": "f", "fr": "la laine", "en": "wool", "format": "en2fr", "options": ["la laine", "la soie", "la toile", "la fourrure"], "a": 0, "trap": "la soie — silk", "expl": "« Un pull en laine » — the material takes « en ». « La fourrure » is fur, « la toile » is canvas."}, {"id": "fvc-clothes-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "le coton", "en": "cotton", "format": "fr2en", "options": ["cotton", "linen", "corduroy", "polyester"], "a": 0, "trap": "le lin — linen, the other summer fabric", "expl": "« 100 % coton » on the label. Linen is « le lin », corduroy « le velours côtelé »."}, {"id": "fvc-clothes-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le cuir", "en": "leather", "format": "en2fr", "options": ["le cuir", "le daim", "le velours", "le tissu"], "a": 0, "trap": "le daim — suede, which is leather but needs a different word", "expl": "« Une veste en cuir ». Do not confuse « le cuir » with « la cuisse » (thigh) — the vowel matters."}, {"id": "fvc-clothes-A2-24", "level": "A2", "pos": "noun", "gender": "f", "fr": "la couleur", "en": "the colour", "format": "cloze", "q": "Vous l'avez dans une autre ___ ?", "options": ["couleur", "taille", "matière", "pointure"], "a": 0, "trap": "taille — also fits the sentence perfectly, but asks a different question", "expl": "All four are feminine nouns that fit grammatically; only the meaning tells you which one you want. If you like the fit but not the blue, you ask for « une autre couleur »."}, {"id": "fvc-clothes-A2-25", "level": "A2", "pos": "verb", "fr": "essayer", "en": "to try on", "format": "fr2en", "options": ["to try on", "to wipe", "to exchange", "to wring out"], "a": 0, "trap": "essuyer — to wipe; one vowel away and you are drying the counter", "expl": "« Je peux l'essayer ? » is the sentence you need. « Essayer de + infinitif » means to try to do something."}, {"id": "fvc-clothes-A2-26", "level": "A2", "pos": "noun", "fr": "le gilet", "en": "the cardigan", "format": "en2fr", "options": ["le gilet", "le pull", "le blouson", "le maillot"], "a": 0, "trap": "le pull — the one you pull over your head; le gilet opens at the front", "expl": "« Un gilet » buttons or zips up the front. « Un gilet sans manches » is a waistcoat, and « un gilet jaune » is the fluorescent one in your car.", "gender": "m"}, {"id": "fvc-clothes-A2-27", "level": "A2", "pos": "verb", "fr": "porter", "en": "to wear / to carry", "format": "fr2en", "options": ["to wear", "to bring", "to take away", "to push"], "a": 0, "trap": "apporter — to bring something to someone", "expl": "« Je porte du 40 » = I take a 40. Same verb as 'to carry': « je porte les sacs »."}, {"id": "fvc-clothes-A2-28", "level": "A2", "pos": "verb", "fr": "aller", "en": "to suit / to fit (someone)", "format": "en2fr", "options": ["aller", "plaire", "convenir", "aimer"], "a": 0, "trap": "plaire — to please: « ça me plaît » is 'I like it', not 'it fits me'", "expl": "« Ça vous va très bien » = it really suits you. The shop assistant will say this whatever you try on."}, {"id": "fvc-clothes-A2-29", "level": "A2", "pos": "verb", "fr": "plaire", "en": "to please (to like)", "format": "cloze", "q": "Ce modèle me ___ beaucoup, je vais le prendre.", "options": ["plaît", "va", "porte", "coûte"], "a": 0, "trap": "va — grammatically fine, but « ça me va » means it fits me, not that I like it", "expl": "All four are correct third-person forms, so grammar cannot decide. « Plaire à quelqu'un » = to appeal to someone: « ce modèle me plaît »."}, {"id": "fvc-clothes-A2-30", "level": "A2", "pos": "verb", "fr": "coûter", "en": "to cost", "format": "cloze", "q": "Ce manteau ___ nonante euros.", "options": ["coûte", "paie", "achète", "vend"], "a": 0, "trap": "paie — the coat does not pay, you do", "expl": "All four fit grammatically after « ce manteau », so you must think about who is doing what. Only « coûter » takes the price as its object."}, {"id": "fvc-clothes-A2-31", "level": "A2", "pos": "verb", "fr": "payer", "en": "to pay", "format": "collocation", "q": "Une seule de ces phrases se dit dans un magasin belge. Laquelle ?", "options": ["Je peux payer par Bancontact ?", "Je peux payer avec la carte bleue ?", "Je peux payer en Bancontact ?", "Je peux payer le Bancontact ?"], "a": 0, "trap": "« la carte bleue » — correct in France, meaningless in Belgium", "note": "Belgian French. In France you'd hear « je paie par carte bleue » or « par CB »; in Belgium the debit system is Bancontact (Payconiq for the phone app).", "expl": "The preposition is « par » for a payment method: payer par Bancontact, par carte, par virement — but « en espèces / en liquide » for cash."}, {"id": "fvc-clothes-A2-32", "level": "A2", "pos": "noun", "gender": "f", "fr": "la réduction", "en": "the discount", "format": "fr2en", "options": ["the discount", "the refund", "the receipt", "the deposit"], "a": 0, "trap": "le remboursement — a refund, money coming back after you paid", "expl": "« Vingt pour cent de réduction » on the sign. A refund is « un remboursement »."}, {"id": "fvc-clothes-A2-33", "level": "A2", "pos": "noun", "gender": "m", "fr": "les soldes", "en": "the sales (period)", "format": "en2fr", "options": ["les soldes", "les achats", "les dépenses", "les factures"], "a": 0, "trap": "les promotions — offers that run any week; « les soldes » are the legally fixed sale periods", "note": "Belgian detail: « les soldes » are legally limited to January and July, and shops may not discount in the weeks before (« la période d'attente »). France has similar but not identical dates.", "expl": "« Les soldes » is masculine plural: « les soldes d'été ». « Les achats » are purchases, « les dépenses » spending."}, {"id": "fvc-clothes-A2-34", "level": "A2", "pos": "noun", "gender": "m", "fr": "le ticket de caisse", "en": "the receipt", "format": "fr2en", "options": ["the receipt", "the loyalty card", "the price tag", "the bank card"], "a": 0, "trap": "l'étiquette — the price tag stuck to the garment", "expl": "Keep it: without « le ticket de caisse » you cannot exchange anything. Also called « le reçu »."}, {"id": "fvc-clothes-A2-35", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'étiquette", "en": "the label / price tag", "format": "fr2en", "options": ["the label / price tag", "the receipt", "the shop sign", "the till"], "a": 0, "trap": "le ticket — the receipt you get after paying", "expl": "« Le prix est sur l'étiquette. » The label also tells you « 100 % laine » and the washing instructions."}, {"id": "fvc-clothes-A2-36", "level": "A2", "pos": "noun", "gender": "f", "fr": "la vitrine", "en": "the shop window", "format": "en2fr", "options": ["la vitrine", "la caisse", "la cabine", "l'enseigne"], "a": 0, "trap": "l'enseigne — the sign above the shop, and also the chain itself", "expl": "« Le pull qui est en vitrine » = the jumper in the window. Useful when you cannot find it on the rails."}, {"id": "fvc-clothes-A2-37", "level": "A2", "pos": "noun", "gender": "m", "fr": "le rayon", "en": "the department / section", "format": "fr2en", "options": ["the department of a shop", "the checkout", "the fitting room", "the stockroom"], "a": 0, "trap": "la réserve — the stockroom staff disappear into", "expl": "« Le rayon hommes est au premier étage. » In a Delhaize, « le rayon frais » is the chilled section."}, {"id": "fvc-clothes-A2-38", "level": "A2", "pos": "adj", "fr": "cher", "en": "expensive", "format": "fr2en", "options": ["expensive", "cheap", "free of charge", "second-hand"], "a": 0, "trap": "bon marché — cheap, the opposite, and just as short a phrase", "expl": "« C'est trop cher pour moi. » The same word means 'dear' in a letter: « Cher Monsieur »."}, {"id": "fvc-clothes-A2-39", "level": "A2", "pos": "adj", "fr": "bon marché", "en": "cheap / good value", "format": "en2fr", "options": ["bon marché", "cher", "gratuit", "soldé"], "a": 0, "trap": "gratuit — free, costing nothing at all", "expl": "« Bon marché » never changes form: « une veste bon marché ». Avoid « pas cher » in a shop if you do not want to sound rude about the goods."}, {"id": "fvc-clothes-A2-40", "level": "A2", "pos": "adj", "fr": "serré", "en": "tight", "format": "fr2en", "options": ["tight", "loose", "short", "warm"], "a": 0, "trap": "large — loose or wide, the exact opposite", "expl": "« C'est un peu serré aux épaules. » For the opposite say « c'est trop large »."}, {"id": "fvc-clothes-A2-41", "level": "A2", "pos": "adj", "fr": "large", "en": "loose / too big", "format": "en2fr", "options": ["trop large", "trop serré", "trop court", "trop long"], "a": 0, "trap": "« large » looks like English 'large' but means wide or loose, not big in size", "expl": "For a size that is simply too big you say « c'est trop grand » or « c'est trop large ». Never « c'est trop large » meaning 'it's a large'."}, {"id": "fvc-clothes-A2-42", "level": "A2", "pos": "adj", "fr": "court", "en": "short", "format": "cloze", "q": "Les manches sont trop ___ , j'ai les poignets à l'air.", "options": ["courtes", "longues", "larges", "serrées"], "a": 0, "trap": "longues — same grammar, opposite problem", "expl": "All four agree correctly with « les manches » (feminine plural), so only the second half of the sentence decides. Wrists showing = sleeves too short."}, {"id": "fvc-clothes-A2-43", "level": "A2", "pos": "noun", "gender": "f", "fr": "la sacoche", "en": "the handbag (Belgium)", "format": "fr2en", "options": ["the handbag", "the backpack", "the suitcase", "the wallet"], "a": 0, "trap": "le sac à dos — a backpack", "note": "Belgian French. In France « une sacoche » is a satchel or a bike pannier; a woman's handbag there is « un sac à main ».", "expl": "In Brussels « ma sacoche » is simply the bag you carry your keys and your GSM in."}, {"id": "fvc-clothes-A2-44", "level": "A2", "pos": "noun", "gender": "m", "fr": "le Bancontact", "en": "Belgian debit-card payment", "format": "fr2en", "options": ["the Belgian bank-card payment system", "a Belgian bank", "a cash machine only", "a shop loyalty scheme"], "a": 0, "trap": "learners assume it is a bank; it is the payment network on almost every Belgian debit card", "note": "Belgian French. France says « la carte bleue » or « la CB »; say Bancontact there and nobody will know what you mean.", "expl": "« Bancontact ou cash ? » is the standard question at a Belgian till. Contactless is « sans contact »."}, {"id": "fvc-clothes-A2-45", "level": "A2", "pos": "verb", "fr": "échanger", "en": "to exchange (an item)", "format": "en2fr", "options": ["échanger", "changer", "rendre", "rembourser"], "a": 0, "trap": "changer — to change in general; you need the é- for swapping goods in a shop", "expl": "« Je peux l'échanger si la taille ne va pas ? » Belgian shops usually give you 14 to 30 days with the ticket."}, {"id": "fvc-clothes-A2-46", "level": "A2", "pos": "verb", "fr": "rendre", "en": "to take back / return an item", "format": "fr2en", "options": ["to take an item back to the shop", "to go home", "to come back to the shop", "to change your mind"], "a": 0, "trap": "rentrer — to go home; « rendre » is what you do with the jumper, « rentrer » is what you do at six o'clock", "expl": "« Je voudrais rendre ce pull. » If you only want a different size, ask to « échanger » instead."}, {"id": "fvc-clothes-A2-47", "level": "A2", "pos": "expr", "fr": "faire du 40", "en": "to take a size 40", "format": "collocation", "q": "Comment dit-on que vous faites du 40 ?", "options": ["Je fais du 40", "Je fais le 40", "Je suis 40", "J'ai 40 de taille"], "a": 0, "trap": "« je suis 40 » — the literal English 'I am a 40', which does not exist in French", "expl": "« Faire du + numéro » for clothes: je fais du 40, du M, du L. For shoes: « je chausse du 43 » or « je fais du 43 »."}, {"id": "fvc-clothes-A2-48", "level": "A2", "pos": "expr", "fr": "essayer un vêtement", "en": "to try a garment on", "format": "collocation", "q": "Laquelle de ces expressions ne se dit PAS ?", "options": ["essayer la caisse", "essayer un pull", "essayer une taille plus grande", "essayer dans la cabine"], "a": 0, "trap": "« essayer la caisse » looks like the others but you cannot try on a till", "expl": "You try on garments and sizes, and you do it in the cabine. At the caisse you pay."}], "phrases": [{"id": "ph-clothes-A2-01", "fr": "Bonjour, je cherche un pull en laine.", "en": "Hello, I'm looking for a wool jumper.", "note": "Always open with Bonjour before the request. Material takes « en »: en laine, en coton, en cuir."}, {"id": "ph-clothes-A2-02", "fr": "Je regarde seulement, merci.", "en": "I'm just looking, thanks.", "note": "The polite brush-off when an assistant offers help. « Je regarde, merci » on its own is enough."}, {"id": "ph-clothes-A2-03", "fr": "Vous avez ce modèle en taille M ?", "en": "Do you have this one in a medium?", "note": "« Ce modèle » is what staff call a particular item. Sizes are said as letters (M, L) or numbers (38, 40)."}, {"id": "ph-clothes-A2-04", "fr": "Je fais du 40.", "en": "I take a 40.", "note": "« Faire du + size » is the fixed formula. Never « je suis un 40 »."}, {"id": "ph-clothes-A2-05", "fr": "Je chausse du 43.", "en": "I take a size 43 shoe.", "note": "Shoes get their own verb, « chausser », and their own noun, « la pointure »."}, {"id": "ph-clothes-A2-06", "fr": "Est-ce que je peux l'essayer ?", "en": "Can I try it on?", "note": "The object pronoun goes before the infinitive: l'essayer, les essayer."}, {"id": "ph-clothes-A2-07", "fr": "Où sont les cabines d'essayage, s'il vous plaît ?", "en": "Where are the fitting rooms, please?", "note": "Staff will answer « au fond », « à droite », « au premier étage » — learn those three."}, {"id": "ph-clothes-A2-08", "fr": "C'est un peu trop serré, vous avez la taille au-dessus ?", "en": "It's a bit too tight, do you have the next size up?", "note": "« La taille au-dessus » = one size up, « la taille en dessous » = one size down."}, {"id": "ph-clothes-A2-09", "fr": "Vous l'avez dans une autre couleur ?", "en": "Do you have it in another colour?", "note": "« Dans une autre couleur » — the preposition is dans, not en, when you ask about the range."}, {"id": "ph-clothes-A2-10", "fr": "Ça coûte combien ?", "en": "How much is it?", "note": "Neutral and fine in any shop. « C'est combien ? » is shorter and just as normal."}, {"id": "ph-clothes-A2-11", "fr": "Est-ce que c'est en promotion ?", "en": "Is it on offer?", "note": "« En promotion » (often just « en promo ») is any offer; « en solde » only during the January and July sale periods."}, {"id": "ph-clothes-A2-12", "fr": "Ça fait septante-cinq euros ?", "en": "That's seventy-five euros?", "note": "Belgian French: septante = 70, nonante = 90. France says soixante-quinze and quatre-vingt-dix. Belgians say quatre-vingts for 80, like France."}, {"id": "ph-clothes-A2-13", "fr": "Je peux payer par Bancontact ?", "en": "Can I pay by debit card?", "note": "In Belgium the terminal is « Bancontact »; « la carte bleue » is the French term and will get you a blank look."}, {"id": "ph-clothes-A2-14", "fr": "Je vais le prendre.", "en": "I'll take it.", "note": "Present tense of aller + infinitive. Match the pronoun to the garment: le pull → je vais le prendre; la veste → je vais la prendre."}, {"id": "ph-clothes-A2-15", "fr": "Je vais réfléchir, merci.", "en": "I'll think about it, thanks.", "note": "The standard polite way to leave without buying. No apology needed."}, {"id": "ph-clothes-A2-16", "fr": "Vous pouvez me le garder cinq minutes ?", "en": "Could you hold it for me for five minutes?", "note": "Two pronouns in order: me le. Useful while you check another shop on the rue Neuve."}, {"id": "ph-clothes-A2-17", "fr": "Je peux l'échanger si la taille ne va pas ?", "en": "Can I exchange it if the size isn't right?", "note": "« La taille ne va pas » = the size doesn't work. Ask before paying; you will need the ticket de caisse."}, {"id": "ph-clothes-A2-18", "fr": "Il me faut un sac, s'il vous plaît.", "en": "I need a bag, please.", "note": "« Il me faut » = I need. Belgian shops charge for bags, usually a few cents, and will ask « avec un sac ? »."}, {"id": "ph-clothes-A2-19", "fr": "Voilà, s'il vous plaît.", "en": "Here you go.", "note": "Belgian French: « s'il vous plaît » is also said while handing something over, where France would say « voilà » or « tenez ». Belgians say it in both directions."}, {"id": "ph-clothes-A2-20", "fr": "Merci beaucoup, bonne journée !", "en": "Thanks very much, have a good day!", "note": "Never leave a Belgian shop silently. After about 5 p.m. switch to « bonne soirée »."}], "dialogue": [{"who": "seller", "fr": "Bonjour ! Je peux vous aider ?", "en": "Hello! Can I help you?", "gloss": {"aider": "to help"}}, {"who": "you", "fr": "Bonjour. Oui, je cherche un pull en laine.", "en": "Hello. Yes, I'm looking for a wool jumper.", "gloss": {"cherche": "am looking for", "laine": "wool"}, "accept": ["bonjour oui je cherche un pull en laine", "bonjour je cherche un pull en laine", "je cherche un pull en laine", "bonjour je voudrais un pull en laine", "je voudrais un pull en laine", "j'aimerais un pull en laine", "bonjour je cherche un pull en laine s'il vous plaît"]}, {"who": "seller", "fr": "Les pulls sont au fond du magasin, à droite. Vous faites quelle taille ?", "en": "The jumpers are at the back of the shop, on the right. What size are you?", "gloss": {"fond": "back / far end", "taille": "size"}}, {"who": "you", "fr": "Je fais du M.", "en": "I take a medium.", "gloss": {"fais": "take (lit. do)"}, "accept": ["je fais du m", "je fais du medium", "du m", "je fais une taille m", "je fais du m s'il vous plaît", "taille m"]}, {"who": "seller", "fr": "Voilà. Ce modèle bleu est en promotion cette semaine.", "en": "Here we are. This blue one is on offer this week.", "gloss": {"modèle": "style / item", "promotion": "special offer"}}, {"who": "you", "fr": "Il coûte combien ?", "en": "How much is it?", "gloss": {"coûte": "costs"}, "accept": ["il coûte combien", "il coute combien", "c'est combien", "ça coûte combien", "combien il coûte", "combien coûte-t-il", "il fait combien"]}, {"who": "seller", "fr": "Septante-cinq euros au lieu de nonante.", "en": "Seventy-five euros instead of ninety.", "gloss": {"Septante": "70 (Belgium; France: soixante-dix)", "nonante": "90 (Belgium; France: quatre-vingt-dix)", "au lieu de": "instead of"}}, {"who": "you", "fr": "D'accord. Est-ce que je peux l'essayer ?", "en": "OK. Can I try it on?", "gloss": {"essayer": "to try on"}, "accept": ["est-ce que je peux l'essayer", "je peux l'essayer", "d'accord est-ce que je peux l'essayer", "puis-je l'essayer", "je peux essayer", "est-ce que je peux essayer"]}, {"who": "seller", "fr": "Bien sûr. Les cabines sont là-bas, à gauche.", "en": "Of course. The fitting rooms are over there, on the left.", "gloss": {"cabines": "fitting rooms", "là-bas": "over there"}}, {"who": "you", "fr": "Merci beaucoup.", "en": "Thank you very much.", "accept": ["merci beaucoup", "merci", "merci bien", "je vous remercie"]}, {"who": "seller", "fr": "Alors, ça va ? La taille est bonne ?", "en": "So, all right? Is the size good?", "gloss": {"Alors": "so / well then"}}, {"who": "you", "fr": "C'est un peu trop serré. Vous l'avez en L ?", "en": "It's a bit too tight. Do you have it in a large?", "gloss": {"serré": "tight"}, "accept": ["c'est un peu trop serré vous l'avez en l", "c'est un peu trop serré", "il est un peu trop serré vous l'avez en l", "c'est trop serré vous avez la taille au-dessus", "c'est un peu serré vous l'avez en l", "vous l'avez en l", "vous avez la taille au-dessus"]}, {"who": "seller", "fr": "Oui, tenez, un L en bleu. Voilà, ça vous va très bien.", "en": "Yes, here you are, a large in blue. There, that suits you very well.", "gloss": {"tenez": "here you are", "va": "suits"}}, {"who": "you", "fr": "Parfait, je le prends.", "en": "Perfect, I'll take it.", "gloss": {"prends": "take"}, "accept": ["parfait je le prends", "je le prends", "d'accord je le prends", "très bien je le prends", "je vais le prendre", "parfait je vais le prendre", "oui je le prends"]}, {"who": "seller", "fr": "Très bien. Je vous encaisse à la caisse. Vous payez comment ?", "en": "Very good. I'll ring you up at the till. How are you paying?", "gloss": {"encaisse": "ring up / take payment from", "caisse": "till"}}, {"who": "you", "fr": "Par Bancontact, s'il vous plaît.", "en": "By debit card, please.", "gloss": {"Bancontact": "Belgian debit-card system"}, "accept": ["par bancontact s'il vous plaît", "par bancontact", "bancontact", "par bancontact svp", "je paie par bancontact", "par carte"]}, {"who": "seller", "fr": "Introduisez votre carte et tapez votre code... C'est bon. Voilà votre ticket, s'il vous plaît.", "en": "Insert your card and enter your PIN... That's fine. Here's your receipt.", "gloss": {"Introduisez": "insert", "tapez": "type / enter", "s'il vous plaît": "here you go (Belgian use when handing something over)"}}, {"who": "you", "fr": "Merci, bonne journée !", "en": "Thanks, have a good day!", "gloss": {"journée": "day"}, "accept": ["merci bonne journée", "merci beaucoup bonne journée", "merci bonne soirée", "merci au revoir", "merci et bonne journée", "au revoir bonne journée"]}], "exercises": [{"id": "ex-clothes-A2-01", "level": "A2", "format": "fr2en", "q": "la pointure", "options": ["the shoe size", "the clothing size", "the fitting room", "the price tag"], "a": 0, "expl": "Shoes only. Clothes take « la taille »."}, {"id": "ex-clothes-A2-02", "level": "A2", "format": "en2fr", "q": "the fitting room", "options": ["la cabine", "la caisse", "la vitrine", "la réserve"], "a": 0, "expl": "« Les cabines sont au fond. » La caisse is the till; la réserve the stockroom."}, {"id": "ex-clothes-A2-03", "level": "A2", "format": "cloze", "q": "Je cherche un ___ en laine pour l'hiver.", "options": ["pull", "manteau", "gilet", "training"], "a": 0, "expl": "All four are masculine and fit the grammar; a wool one you pull over your head is « un pull »."}, {"id": "ex-clothes-A2-04", "level": "A2", "format": "cloze", "q": "Vous faites quelle ___ ?", "options": ["taille", "pointure", "couleur", "matière"], "a": 0, "expl": "All four are feminine nouns and grammatical here. For a jumper the assistant asks « quelle taille ? »; « quelle pointure ? » is for shoes."}, {"id": "ex-clothes-A2-05", "level": "A2", "format": "en2fr", "q": "the receipt", "options": ["le ticket de caisse", "le reçu de banque", "le billet", "le bon de commande"], "a": 0, "expl": "« Le ticket de caisse » is what the till prints. « Le billet » is a banknote or a ticket for an event."}, {"id": "ex-clothes-A2-06", "level": "A2", "format": "fr2en", "q": "la tirette", "options": ["the zip", "the drawer", "the button", "the sleeve"], "a": 0, "expl": "Belgian French; France says « une fermeture éclair »."}, {"id": "ex-clothes-A2-07", "level": "A2", "format": "collocation", "q": "Laquelle de ces phrases se dit à la caisse en Belgique ?", "options": ["Vous payez comment ?", "Vous payez quoi ?", "Vous payez quand ?", "Vous payez lequel ?"], "a": 0, "expl": "« Vous payez comment ? » or « Bancontact ou cash ? » is what you will actually hear."}, {"id": "ex-clothes-A2-08", "level": "A2", "format": "cloze", "q": "Ce pantalon est trop ___ , vous avez la taille en dessous ?", "options": ["large", "serré", "court", "cher"], "a": 0, "expl": "All four are adjectives that fit. Asking for a smaller size only makes sense if the trousers are too big — « trop large »."}, {"id": "ex-clothes-A2-09", "level": "A2", "format": "fr2en", "q": "essayer", "options": ["to try on", "to wipe", "to exchange", "to wear"], "a": 0, "expl": "« Essuyer » (to wipe) is the lookalike. Watch the vowel."}, {"id": "ex-clothes-A2-10", "level": "A2", "format": "en2fr", "q": "wool", "options": ["la laine", "la soie", "la toile", "la fourrure"], "a": 0, "expl": "« Un pull en laine ». Silk is « la soie »."}, {"id": "ex-clothes-A2-11", "level": "A2", "format": "collocation", "q": "Vous voulez la même veste, une taille plus grande. Que dites-vous ?", "options": ["Vous avez la taille au-dessus ?", "Vous avez la taille en dessous ?", "Vous avez une autre couleur ?", "Vous avez une autre matière ?"], "a": 0, "expl": "« Au-dessus » = up a size, « en dessous » = down a size."}, {"id": "ex-clothes-A2-12", "level": "A2", "format": "fr2en", "q": "les soldes", "options": ["the twice-yearly official sale periods", "any special offer at any time", "the balance of a bank account", "last season's clearance stock"], "a": 0, "expl": "In Belgium « les soldes » run in January and July only, and shops may not discount in the weeks before. Offers outside those windows are « des promotions »."}, {"id": "ex-clothes-A2-13", "level": "A2", "format": "fr2en", "q": "la sacoche", "options": ["the handbag (Belgium)", "the backpack", "the suitcase", "the shopping trolley"], "a": 0, "expl": "In France « une sacoche » is a satchel or bike bag; a handbag there is « un sac à main »."}]},
  "clothes-B1": {"slug": "clothes", "level": "B1", "title": "Acheter des vêtements — taille épuisée", "place": "C&A, rue Neuve, Bruxelles", "register": "vous", "registerNote": "Vous throughout, as at A2 — but at B1 you also soften your requests: « est-ce que vous pourriez… », « ce serait possible de… », « je préférerais… ». That conditional layer is what separates a polite adult customer from a tourist. Tu stays for friends only.", "vocab": [{"id": "fvc-clothes-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "la rupture de stock", "en": "being out of stock", "format": "fr2en", "options": ["being out of stock", "a break in the supply chain", "a cancelled order", "a stock clearance"], "a": 0, "trap": "le déstockage — a clearance sale, when there is too much stock, not too little", "expl": "« On est en rupture de stock dans cette taille. » The everyday version is « on n'en a plus »."}, {"id": "fvc-clothes-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la réserve", "en": "the stockroom", "format": "fr2en", "options": ["the stockroom", "the reservation", "the reserve price", "the deposit"], "a": 0, "trap": "la réservation — the booking; « la réserve » is the room out the back", "expl": "« Je vais voir en réserve » is what the assistant says before disappearing for four minutes."}, {"id": "fvc-clothes-B1-03", "level": "B1", "pos": "verb", "fr": "commander", "en": "to order (goods)", "format": "en2fr", "options": ["commander", "ordonner", "demander", "réclamer"], "a": 0, "trap": "ordonner — to order someone about; goods are « commandés », people are « ordonnés »", "expl": "« Je peux vous le faire commander. » Note the causative: faire commander = to have it ordered in."}, {"id": "fvc-clothes-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "la commande", "en": "the order", "format": "cloze", "q": "Votre ___ arrivera jeudi ou vendredi au plus tard.", "options": ["commande", "livraison", "réserve", "facture"], "a": 0, "trap": "livraison — the delivery itself also arrives, so grammar cannot help you here", "expl": "All four are feminine nouns that fit. What you placed at the till is « la commande »; the act of bringing it is « la livraison »."}, {"id": "fvc-clothes-B1-05", "level": "B1", "pos": "verb", "fr": "réserver", "en": "to put aside / reserve", "format": "fr2en", "options": ["to put aside for a customer", "to reserve a table only", "to hold back an opinion", "to refuse politely"], "a": 0, "trap": "garder — to hold something for five minutes; « réserver » is formal and goes in the system", "expl": "« Vous pourriez me le réserver ? » works for a garment in another branch as well as for a table."}, {"id": "fvc-clothes-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la livraison", "en": "the delivery", "format": "en2fr", "options": ["la livraison", "la commande", "la remise", "la réception"], "a": 0, "trap": "la remise — a discount, despite looking like 'remit / hand over'", "expl": "« La livraison prend deux jours ouvrables. » « Un jour ouvrable » is a working day — Saturday counts in Belgium, Sunday does not."}, {"id": "fvc-clothes-B1-07", "level": "B1", "pos": "verb", "fr": "livrer", "en": "to deliver", "format": "fr2en", "options": ["to deliver", "to free someone", "to hand in a book", "to unload a lorry"], "a": 0, "trap": "libérer — to free; « livrer » only shares the first three letters", "expl": "« On vous livre à domicile ? » = shall we deliver to your home? « Se livrer à » means to devote oneself to something — a different verb entirely."}, {"id": "fvc-clothes-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le délai", "en": "the waiting time / lead time", "format": "fr2en", "options": ["the waiting time before something is ready", "a delay caused by a problem", "the deadline for a refund only", "the opening hours"], "a": 0, "trap": "English 'delay' — « un délai » is the normal time something takes, not a hold-up. A hold-up is « un retard ».", "expl": "« Le délai de livraison est de trois jours » is neutral. « Il y a du retard » means something has gone wrong."}, {"id": "fvc-clothes-B1-09", "level": "B1", "pos": "noun", "gender": "f", "fr": "la retouche", "en": "the alteration", "format": "fr2en", "options": ["the alteration to a garment", "the retouching of a photo only", "the final touch of a decoration", "the repair of a zip"], "a": 0, "trap": "la réparation — a repair, for something broken; « une retouche » adjusts a garment that is fine but the wrong shape", "expl": "« Vous faites les retouches ici ? » Many Belgian shops send you to a « retoucherie » nearby; count on €10–15 for a hem."}, {"id": "fvc-clothes-B1-10", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'ourlet", "en": "the hem", "format": "en2fr", "options": ["l'ourlet", "le pli", "le revers", "le pan"], "a": 0, "trap": "le revers — the turn-up or lapel, also at the bottom of a trouser leg", "expl": "« Faire un ourlet » = to take the hem up. « Le pli » is a crease or a pleat."}, {"id": "fvc-clothes-B1-11", "level": "B1", "pos": "verb", "fr": "raccourcir", "en": "to shorten", "format": "en2fr", "options": ["raccourcir", "rallonger", "rétrécir", "resserrer"], "a": 0, "trap": "rétrécir — to shrink, which is what the washing machine does without being asked", "expl": "« Il faudrait raccourcir le pantalon de trois centimètres. » « Rallonger » is to lengthen, « resserrer » to take in at the waist."}, {"id": "fvc-clothes-B1-12", "level": "B1", "pos": "noun", "gender": "f", "fr": "la doublure", "en": "the lining", "format": "fr2en", "options": ["the lining inside a garment", "the stand-in actor only", "the double seam", "the spare button"], "a": 0, "trap": "the word also means 'understudy' in the theatre, which is where learners meet it first", "expl": "« La doublure est décousue » — the lining has come unstitched, a classic reason to ask for a reduction."}, {"id": "fvc-clothes-B1-13", "level": "B1", "pos": "noun", "gender": "f", "fr": "la couture", "en": "the seam", "format": "fr2en", "options": ["the seam", "the fold", "the hem", "the sewing needle"], "a": 0, "trap": "l'ourlet — the hem, which is one particular seam at the bottom", "expl": "« La couture » also means sewing and, capitalised in fashion, haute couture. « Sur mesure » = made to measure."}, {"id": "fvc-clothes-B1-14", "level": "B1", "pos": "adj", "fr": "décousu", "en": "coming apart at the seam", "format": "en2fr", "options": ["décousu", "déchiré", "taché", "troué"], "a": 0, "trap": "déchiré — torn, where the fabric itself has ripped, not the stitching", "expl": "Four different defects: décousu (unstitched), déchiré (torn), taché (stained), troué (with a hole). Naming the right one gets you the right remedy."}, {"id": "fvc-clothes-B1-15", "level": "B1", "pos": "adj", "fr": "taché", "en": "stained", "format": "cloze", "q": "Je ne peux pas le prendre : il est ___ au niveau du col.", "options": ["taché", "serré", "ajusté", "doublé"], "a": 0, "trap": "serré — perfectly grammatical, but a tight collar is not a reason to refuse the garment outright", "expl": "All four are masculine singular adjectives that fit. « Au niveau de » = around / in the area of, very common in shop French."}, {"id": "fvc-clothes-B1-16", "level": "B1", "pos": "adj", "fr": "troué", "en": "with a hole in it", "format": "fr2en", "options": ["with a hole in it", "worn thin but intact", "faded", "creased"], "a": 0, "trap": "usé — worn, which is not yet a hole", "expl": "« Une chaussette trouée » is the classic example. « Un trou » = a hole."}, {"id": "fvc-clothes-B1-17", "level": "B1", "pos": "verb", "fr": "rétrécir", "en": "to shrink", "format": "fr2en", "options": ["to shrink in the wash", "to stretch out", "to fade", "to be taken in by a tailor"], "a": 0, "trap": "resserrer — to take in, which a tailor does deliberately; rétrécir is what happens by accident at 60 degrees", "expl": "« Est-ce que ça rétrécit au lavage ? » is a fair question about a wool jumper. Answer on the label: « lavage à 30° »."}, {"id": "fvc-clothes-B1-18", "level": "B1", "pos": "verb", "fr": "déteindre", "en": "to run (of colour)", "format": "fr2en", "options": ["to lose its colour into the wash", "to fade in the sun", "to stain permanently", "to be dyed a second time"], "a": 0, "trap": "se décolorer — to fade; « déteindre » is the colour leaving and landing on your other clothes", "expl": "« Ce jean risque de déteindre au premier lavage. » Wash the new dark jeans alone the first time."}, {"id": "fvc-clothes-B1-19", "level": "B1", "pos": "noun", "gender": "f", "fr": "la coupe", "en": "the cut (of a garment)", "format": "fr2en", "options": ["the cut / shape of a garment", "the fabric quality", "the size chart", "the discount"], "a": 0, "trap": "la taille — the size; two jackets in the same taille can have a completely different coupe", "expl": "« J'aime bien la coupe, mais pas la couleur. » Same word as a haircut: « une coupe de cheveux »."}, {"id": "fvc-clothes-B1-20", "level": "B1", "pos": "adj", "fr": "ajusté", "en": "fitted / close-fitting", "format": "en2fr", "options": ["ajusté", "ample", "moulant", "évasé"], "a": 0, "trap": "moulant — skin-tight, which is a step beyond fitted and not usually a compliment", "expl": "The scale runs ample (loose) → droit (straight) → ajusté (fitted) → moulant (clingy). « Évasé » flares out at the bottom."}, {"id": "fvc-clothes-B1-21", "level": "B1", "pos": "adj", "fr": "ample", "en": "loose-fitting, roomy", "format": "cloze", "q": "Je préférerais une coupe plus ___ , je n'aime pas quand ça colle.", "options": ["ample", "ajustée", "moulante", "courte"], "a": 0, "trap": "ajustée — grammatically identical, but it is the opposite of what the second half of the sentence asks for", "expl": "All four are feminine singular adjectives agreeing with « coupe ». « Quand ça colle » (when it clings) tells you which one."}, {"id": "fvc-clothes-B1-22", "level": "B1", "pos": "noun", "gender": "m", "fr": "le cintre", "en": "the coat hanger", "format": "en2fr", "options": ["le cintre", "le portant", "le crochet", "le casier"], "a": 0, "trap": "le portant — the rail the hangers hang on", "expl": "« Vous pouvez le remettre sur le cintre ? » is what you hear when you come out of the fitting room empty-handed."}, {"id": "fvc-clothes-B1-23", "level": "B1", "pos": "expr", "fr": "faire la file", "en": "to queue (Belgium)", "format": "fr2en", "options": ["to queue up", "to file paperwork", "to walk in single file on a hike", "to take a numbered ticket"], "a": 0, "trap": "France says « faire la queue »; a Belgian who says « faire la queue » is understood, but « la file » is the local word", "note": "Belgian French. In France it is « faire la queue » and « une file » is mainly a lane of traffic. In Belgium the road sign for a traffic jam even says « file ».", "expl": "« Il y a la file à la caisse » = there's a queue at the till. Also « prendre la file »."}, {"id": "fvc-clothes-B1-24", "level": "B1", "pos": "noun", "gender": "f", "fr": "la carte de fidélité", "en": "the loyalty card", "format": "en2fr", "options": ["la carte de fidélité", "la carte bancaire", "la carte d'identité", "la carte de crédit"], "a": 0, "trap": "la carte bancaire — your actual bank card, which they will also ask for thirty seconds later", "expl": "« Vous avez la carte de fidélité ? » comes before « vous payez comment ? ». Answer « non, mais je veux bien la faire » if you want one."}, {"id": "fvc-clothes-B1-25", "level": "B1", "pos": "noun", "gender": "m", "fr": "un avoir", "en": "a credit note", "format": "fr2en", "options": ["a credit note to spend in the shop", "an asset you own", "an advance payment", "a cash refund"], "a": 0, "trap": "le remboursement — actual money back; « un avoir » is money you may only spend there", "expl": "Belgian shops often offer « un avoir » instead of cash. You may insist on « un remboursement » only if the item is faulty."}, {"id": "fvc-clothes-B1-26", "level": "B1", "pos": "noun", "gender": "m", "fr": "le remboursement", "en": "the refund", "format": "en2fr", "options": ["le remboursement", "l'avoir", "l'échange", "le rabais"], "a": 0, "trap": "l'avoir — a credit note, which is what they will offer you first", "expl": "« Je souhaiterais un remboursement, pas un avoir. » Polite, firm, and the exact wording that works."}, {"id": "fvc-clothes-B1-27", "level": "B1", "pos": "verb", "fr": "rembourser", "en": "to refund", "format": "cloze", "q": "Si l'article est défectueux, on vous ___ intégralement.", "options": ["rembourse", "échange", "livre", "commande"], "a": 0, "trap": "échange — a genuine option in real life, but « intégralement » (in full) only works with money", "expl": "All four are grammatical third-person forms. « Intégralement » = in full, and only a sum of money can be repaid in full."}, {"id": "fvc-clothes-B1-28", "level": "B1", "pos": "noun", "gender": "m", "fr": "un geste commercial", "en": "a goodwill gesture (discount)", "format": "fr2en", "options": ["a discount offered to keep a customer happy", "a business handshake", "an advertising campaign", "a formal complaint"], "a": 0, "trap": "learners read « geste » literally and expect a movement, not money off", "expl": "« Vous pourriez faire un geste commercial ? » is the polite Belgian way to ask for something off a damaged item."}, {"id": "fvc-clothes-B1-29", "level": "B1", "pos": "noun", "gender": "f", "fr": "la facture", "en": "the invoice", "format": "fr2en", "options": ["the invoice", "the till receipt", "the factory", "the bill in a restaurant"], "a": 0, "trap": "la fabrique — a factory; « facture » looks like it but is the piece of paper", "expl": "Ask for « une facture » (with your name and VAT details) rather than « un ticket » if you need it for expenses."}, {"id": "fvc-clothes-B1-30", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'antivol", "en": "the security tag", "format": "en2fr", "options": ["l'antivol", "l'étiquette", "le cadenas", "le portique"], "a": 0, "trap": "le portique — the security gate at the door that beeps, not the tag on the garment", "expl": "« La vendeuse a oublié d'enlever l'antivol » is the sentence for when the portique goes off in the rue Neuve."}, {"id": "fvc-clothes-B1-31", "level": "B1", "pos": "noun", "gender": "f", "fr": "la collection", "en": "the season's range", "format": "fr2en", "options": ["the season's range of clothes", "a collection of objects you own", "a charity collection", "the rubbish collection"], "a": 0, "trap": "in French « la collecte » is the charity or rubbish collection; « la collection » in a shop means the new season", "expl": "« C'est la nouvelle collection, il n'y a pas encore de réduction dessus. »"}, {"id": "fvc-clothes-B1-32", "level": "B1", "pos": "noun", "gender": "f", "fr": "la remise", "en": "the discount (money off)", "format": "fr2en", "options": ["the discount", "the handing over of goods", "the shed", "the re-sale"], "a": 0, "trap": "« la remise » does also mean a shed, and « remettre » means to hand over — context decides", "expl": "« Une remise de 20 % » = 20% off. Interchangeable with « une réduction »; « un rabais » suggests the goods are slightly flawed."}, {"id": "fvc-clothes-B1-33", "level": "B1", "pos": "verb", "fr": "hésiter", "en": "to hesitate / to be torn", "format": "cloze", "q": "J'___ entre le bleu et le gris, les deux me plaisent.", "options": ["hésite", "choisis", "préfère", "réfléchis"], "a": 0, "trap": "préfère — grammatical, but you cannot prefer between two things, you prefer one of them", "expl": "All four are correct first-person forms. « Hésiter entre A et B » is the fixed pattern; « choisir entre » exists too but « les deux me plaisent » says you have not chosen."}, {"id": "fvc-clothes-B1-34", "level": "B1", "pos": "verb", "fr": "convenir", "en": "to suit / to be acceptable", "format": "fr2en", "options": ["to suit someone's needs", "to agree with someone loudly", "to convene a meeting", "to admit a mistake"], "a": 0, "trap": "convenir de = to admit or to agree on something; convenir à = to suit", "expl": "« Si cette date vous convient » = if that date works for you. More formal than « ça vous va ? »."}, {"id": "fvc-clothes-B1-35", "level": "B1", "pos": "verb", "fr": "valoir", "en": "to be worth", "format": "collocation", "q": "Vous dites que l'attente en vaut la peine. Quelle phrase est correcte ?", "options": ["Ça vaut la peine d'attendre la commande", "Ça vaut la peine attendre la commande", "Ça vaut la peine pour attendre la commande", "Ça vaut le coup la peine d'attendre"], "a": 0, "trap": "« ça vaut le coup » is the other correct expression, but not mixed with « la peine »", "expl": "Two fixed forms: « ça vaut la peine de + infinitif » and « ça vaut le coup de + infinitif ». Both need « de » before the verb."}, {"id": "fvc-clothes-B1-36", "level": "B1", "pos": "verb", "fr": "savoir (= pouvoir)", "en": "to be able to (Belgium)", "format": "fr2en", "options": ["to be able to / to manage to", "to know a fact", "to know a person", "to find out"], "a": 0, "trap": "standard « savoir » means to know; in Belgium it doubles as « pouvoir »", "note": "Belgian French. « Je ne sais pas venir samedi » = I can't come on Saturday. In France that sentence means 'I don't know how to come', so use « je ne peux pas » with French speakers.", "expl": "You will hear a Brussels shop assistant say « je ne sais pas vous le réserver ». They are not confessing ignorance — they simply cannot do it."}, {"id": "fvc-clothes-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "une drache", "en": "a downpour (Belgium)", "format": "fr2en", "options": ["a sudden heavy downpour", "a light drizzle", "a hailstorm", "a cold snap"], "a": 0, "trap": "la bruine — drizzle; a drache soaks you in ninety seconds", "note": "Belgian French, from Flemish. France says « une averse » or « il tombe des cordes ». « La drache nationale » is the rain that traditionally falls on 21 July.", "expl": "« Il drache » is the verb. A perfectly good reason to buy the coat today rather than think about it."}, {"id": "fvc-clothes-B1-38", "level": "B1", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile phone (Belgium)", "format": "fr2en", "options": ["the mobile phone", "the SIM card", "the phone network", "the phone shop"], "a": 0, "trap": "learners assume it means the network, as in 'the GSM standard'", "note": "Belgian French, said 'gé-esse-em'. France says « le portable » or « le mobile »; « le GSM » there sounds dated or technical.", "expl": "« On vous envoie un SMS sur votre GSM quand la commande arrive. » Belgian mobile numbers start 04."}, {"id": "fvc-clothes-B1-39", "level": "B1", "pos": "verb", "fr": "patienter", "en": "to wait (politely)", "format": "en2fr", "options": ["patienter", "attendre", "espérer", "supporter"], "a": 0, "trap": "attendre — correct but neutral; « patienter » is the polite form staff use to you", "expl": "« Si vous voulez bien patienter deux minutes. » You would rarely say it about yourself: « j'attends », not « je patiente »."}, {"id": "fvc-clothes-B1-40", "level": "B1", "pos": "noun", "gender": "m", "fr": "le vendeur", "en": "the shop assistant", "format": "en2fr", "options": ["le vendeur", "le caissier", "le client", "le gérant"], "a": 0, "trap": "le caissier — the person on the till specifically", "expl": "Feminine « la vendeuse ». « Le gérant » is the manager, the person to ask for when a geste commercial is refused."}, {"id": "fvc-clothes-B1-41", "level": "B1", "pos": "noun", "gender": "m", "fr": "le retour", "en": "the return (of goods)", "format": "cloze", "q": "Les ___ sont acceptés pendant trente jours avec le ticket.", "options": ["retours", "achats", "articles", "échanges"], "a": 0, "trap": "échanges — also accepted for thirty days in real life, but the sentence is the standard wording for bringing goods back", "expl": "All four are masculine plural nouns that fit. « La politique de retour » is the shop's returns policy."}, {"id": "fvc-clothes-B1-42", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'article", "en": "the item (in a shop)", "format": "fr2en", "options": ["the item for sale", "the newspaper article only", "the clause of a contract only", "the shelf"], "a": 0, "trap": "learners know « un article » from newspapers and miss the retail meaning", "expl": "« Cet article n'est plus disponible en magasin. » One word covers everything the shop sells."}, {"id": "fvc-clothes-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "le tissu", "en": "the fabric", "format": "en2fr", "options": ["le tissu", "le fil", "le vêtement", "le mouchoir"], "a": 0, "trap": "le mouchoir — a handkerchief, and « un tissu » in English-influenced heads wrongly suggests a paper tissue", "expl": "English 'tissue' (paper) is « un mouchoir en papier ». « Le fil » is the thread."}, {"id": "fvc-clothes-B1-44", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fermeture éclair", "en": "the zip (standard French)", "format": "fr2en", "options": ["the zip", "the press stud", "the buckle", "the closing time"], "a": 0, "trap": "« la fermeture » alone means closing time — « le magasin ferme à 19h »", "note": "This is the France-wide word. In Belgium everyone says « une tirette »; use « fermeture éclair » when you are writing or speaking to French people.", "expl": "« La fermeture éclair est coincée » = the zip is stuck. Also « un zip », increasingly common on both sides of the border."}, {"id": "fvc-clothes-B1-45", "level": "B1", "pos": "expr", "fr": "être en promotion", "en": "to be on special offer", "format": "collocation", "q": "Le pull est réduit parce que la tirette est abîmée. Comment le dites-vous ?", "options": ["Il est soldé à cause d'un défaut", "Il est en solde à cause d'un défaut de fabrique", "Il est réduit par un défaut", "Il est baissé pour un défaut"], "a": 0, "trap": "« en solde » is only correct during the legal January and July sale periods; a damaged item is « soldé » or « démarqué » at any time", "expl": "« À cause de » introduces a negative cause. For a positive one use « grâce à »."}, {"id": "fvc-clothes-B1-46", "level": "B1", "pos": "expr", "fr": "au plus tard", "en": "at the latest", "format": "cloze", "q": "La commande arrivera vendredi au plus ___ .", "options": ["tard", "tôt", "vite", "loin"], "a": 0, "trap": "tôt — « au plus tôt » exists and is grammatical, but it means 'at the earliest', the opposite promise", "expl": "Both « au plus tard » and « au plus tôt » are real. Ask which one the shop means before you plan your Saturday."}], "phrases": [{"id": "ph-clothes-B1-01", "fr": "J'étais déjà passé la semaine dernière, mais vous n'aviez plus ma taille.", "en": "I came in last week, but you didn't have my size any more.", "note": "Plus-que-parfait (j'étais passé) for the earlier visit, imparfait (vous n'aviez plus) for the state of the stock. This pairing is very B1."}, {"id": "ph-clothes-B1-02", "fr": "Est-ce que vous pourriez vérifier en réserve, s'il vous plaît ?", "en": "Could you check in the stockroom, please?", "note": "« Pourriez » (conditional) is the polite register. « Pouvez-vous » is fine but flatter."}, {"id": "ph-clothes-B1-03", "fr": "Il vous en reste en L, ou vous êtes en rupture de stock ?", "en": "Do you have any left in a large, or are you out of stock?", "note": "« Il vous en reste ? » — the pronoun « en » replaces the item; you cannot leave it out."}, {"id": "ph-clothes-B1-04", "fr": "Ce serait possible de le faire venir d'un autre magasin ?", "en": "Would it be possible to have it brought in from another branch?", "note": "« Faire venir » = to have something brought. Belgian chains transfer stock between branches within a few days."}, {"id": "ph-clothes-B1-05", "fr": "Vous pourriez me le réserver jusqu'à samedi ?", "en": "Could you put it aside for me until Saturday?", "note": "« Jusqu'à + day » sets the limit. Shops rarely hold anything more than 48 hours, so name a day."}, {"id": "ph-clothes-B1-06", "fr": "Le délai de livraison est de combien de jours ouvrables ?", "en": "How many working days is the delivery time?", "note": "« Un jour ouvrable » includes Saturday in Belgium; « un jour ouvré » is Monday to Friday only."}, {"id": "ph-clothes-B1-07", "fr": "Si je le commande, est-ce que je dois payer maintenant ou au retrait ?", "en": "If I order it, do I pay now or on collection?", "note": "« Le retrait » = collection in store — you will see « Click & Collect / retrait en magasin » on Belgian websites."}, {"id": "ph-clothes-B1-08", "fr": "Vous me préviendrez quand il sera arrivé ?", "en": "Will you let me know when it has arrived?", "note": "After « quand » about the future, French uses the future or futur antérieur — « quand il sera arrivé », never the present."}, {"id": "ph-clothes-B1-09", "fr": "Je préférerais un remboursement plutôt qu'un avoir.", "en": "I'd rather have a refund than a credit note.", "note": "« Plutôt que » = rather than. Conditional « préférerais » keeps it polite while being firm."}, {"id": "ph-clothes-B1-10", "fr": "La doublure est décousue au niveau de l'épaule.", "en": "The lining has come unstitched at the shoulder.", "note": "« Au niveau de » is the standard way to locate a defect. Naming the exact fault is what gets it fixed or discounted."}, {"id": "ph-clothes-B1-11", "fr": "Est-ce que vous pourriez faire un geste commercial ?", "en": "Could you knock something off the price?", "note": "The accepted way to ask for a discount without haggling, which is not done in Belgian shops."}, {"id": "ph-clothes-B1-12", "fr": "J'hésite entre le bleu marine et le gris chiné.", "en": "I'm torn between the navy and the marl grey.", "note": "« Hésiter entre A et B ». « Bleu marine » and « gris chiné » never agree: « des pulls bleu marine »."}, {"id": "ph-clothes-B1-13", "fr": "Est-ce que ça rétrécit au lavage ?", "en": "Does it shrink in the wash?", "note": "« Au lavage » = in the wash. For wool the answer is usually « lavage à la main » or « à 30 degrés »."}, {"id": "ph-clothes-B1-14", "fr": "Vous faites les retouches ici, ou il faut aller ailleurs ?", "en": "Do you do alterations here, or do I have to go elsewhere?", "note": "« Il faut » + infinitive for an impersonal obligation. Big chains usually say « ailleurs »."}, {"id": "ph-clothes-B1-15", "fr": "Il faudrait raccourcir les manches de deux centimètres.", "en": "The sleeves would need shortening by two centimetres.", "note": "« Il faudrait » (conditional of il faut) softens an instruction into a suggestion. Measurements take « de »."}, {"id": "ph-clothes-B1-16", "fr": "Je le prends, mais je voudrais garder l'étiquette au cas où.", "en": "I'll take it, but I'd like to keep the label just in case.", "note": "« Au cas où » can end a sentence on its own in speech, exactly like English 'just in case'."}, {"id": "ph-clothes-B1-17", "fr": "Quel est le délai pour un échange, et est-ce que le ticket suffit ?", "en": "How long do I have to exchange it, and is the receipt enough?", "note": "Two questions in one breath is natural here. Belgian shops typically allow 14 to 30 days with the ticket."}, {"id": "ph-clothes-B1-18", "fr": "Il drache dehors, je vais prendre le manteau tout de suite.", "en": "It's pouring outside, I'll wear the coat straight away.", "note": "Belgian French: « il drache » = it's bucketing down. In France you would say « il pleut des cordes » or « quelle averse ! »."}, {"id": "ph-clothes-B1-19", "fr": "Je ne sais pas repasser avant lundi, mon GSM a mon numéro si besoin.", "en": "I can't come back before Monday; you have my mobile number if you need it.", "note": "Two Belgicisms: « savoir » used for « pouvoir », and « GSM » for a mobile. In France: « je ne peux pas repasser » and « mon portable »."}, {"id": "ph-clothes-B1-20", "fr": "Merci d'avoir vérifié, c'est gentil. Bonne fin de journée !", "en": "Thanks for checking, that's kind of you. Have a good rest of the day!", "note": "« Merci d'avoir + participe passé » thanks for something already done. « Bonne fin de journée » works from about 3 p.m."}], "dialogue": [{"who": "seller", "fr": "Bonjour monsieur, qu'est-ce que je peux faire pour vous ?", "en": "Hello sir, what can I do for you?", "gloss": {"qu'est-ce que": "what"}}, {"who": "you", "fr": "Bonjour. J'étais déjà passé la semaine dernière : je cherche ce pull bleu, mais en L.", "en": "Hello. I came in last week: I'm looking for this blue jumper, but in a large.", "gloss": {"J'étais déjà passé": "I had already come in (plus-que-parfait)"}, "accept": ["bonjour j'étais déjà passé la semaine dernière je cherche ce pull bleu mais en l", "bonjour je cherche ce pull bleu mais en l", "je cherche ce pull bleu en l", "bonjour j'étais passé la semaine dernière je cherche ce pull bleu en l", "je voudrais ce pull bleu en l", "bonjour je voudrais ce pull bleu mais en taille l", "je cherche ce pull bleu en taille l"]}, {"who": "seller", "fr": "En bleu... je crains qu'on soit en rupture de stock dans cette taille. Je vais vérifier en réserve, un instant.", "en": "In blue... I'm afraid we're out of stock in that size. I'll check in the stockroom, one moment.", "gloss": {"je crains": "I'm afraid / I fear", "rupture de stock": "out of stock", "réserve": "stockroom"}}, {"who": "you", "fr": "Merci, je vous attends.", "en": "Thanks, I'll wait.", "gloss": {"attends": "am waiting for"}, "accept": ["merci je vous attends", "je vous attends", "merci j'attends", "pas de problème je vous attends", "merci beaucoup je vous attends", "d'accord je vous attends"]}, {"who": "seller", "fr": "C'est confirmé : il ne nous reste que du M et du XL. Par contre, le magasin de Woluwe en a encore trois.", "en": "It's confirmed: we've only got mediums and extra-larges left. On the other hand, the Woluwe store still has three.", "gloss": {"il ne nous reste que": "we only have ... left", "Par contre": "on the other hand"}}, {"who": "you", "fr": "Est-ce que vous pourriez me le réserver là-bas ? Je passerai samedi.", "en": "Could you put one aside for me over there? I'll come by on Saturday.", "gloss": {"pourriez": "could (conditional)", "passerai": "will come by (future)"}, "accept": ["est-ce que vous pourriez me le réserver là-bas je passerai samedi", "vous pourriez me le réserver là-bas", "est-ce que vous pourriez me le réserver", "vous pouvez me le réserver là-bas je passerai samedi", "ce serait possible de me le réserver là-bas", "est-ce que vous pouvez me le réserver là-bas", "vous pourriez me le garder là-bas je passerai samedi"]}, {"who": "seller", "fr": "Je peux aussi vous le faire commander ici, si vous préférez. La livraison prend deux à trois jours ouvrables.", "en": "I can also have it ordered in here, if you prefer. Delivery takes two to three working days.", "gloss": {"faire commander": "have it ordered in", "jours ouvrables": "working days (Saturday included in Belgium)"}}, {"who": "you", "fr": "Et si je le commande, est-ce que je dois payer maintenant ?", "en": "And if I order it, do I have to pay now?", "gloss": {"dois": "must / have to"}, "accept": ["et si je le commande est-ce que je dois payer maintenant", "si je le commande je dois payer maintenant", "est-ce que je dois payer maintenant", "je dois payer maintenant ou au retrait", "et si je le commande je dois payer tout de suite", "si je commande est-ce que je paie maintenant"]}, {"who": "seller", "fr": "Non, vous payez au retrait. On vous envoie un SMS sur votre GSM dès qu'il arrive.", "en": "No, you pay when you collect it. We send you a text on your mobile as soon as it arrives.", "gloss": {"au retrait": "on collection", "GSM": "mobile phone (Belgium; France: le portable)", "dès qu'il arrive": "as soon as it arrives"}}, {"who": "you", "fr": "D'accord, alors commandez-le, s'il vous plaît.", "en": "OK, then order it, please.", "gloss": {"commandez-le": "order it (imperative + pronoun)"}, "accept": ["d'accord alors commandez-le s'il vous plaît", "commandez-le s'il vous plaît", "d'accord commandez-le", "très bien commandez-le s'il vous plaît", "oui commandez-le s'il vous plaît", "d'accord je préfère la commande", "alors commandez-le"]}, {"who": "seller", "fr": "Très bien. Il me faut votre nom et un numéro de téléphone pour la commande.", "en": "Very good. I need your name and a phone number for the order.", "gloss": {"Il me faut": "I need"}}, {"who": "you", "fr": "Pas de problème. Je vous épelle mon nom, il est un peu compliqué.", "en": "No problem. I'll spell my name for you, it's a bit complicated.", "gloss": {"épelle": "spell out"}, "accept": ["pas de problème je vous épelle mon nom il est un peu compliqué", "je vous épelle mon nom", "pas de problème je vous épelle mon nom", "bien sûr je vous épelle mon nom il est un peu compliqué", "d'accord je vous épelle mon nom de famille", "je peux vous l'épeler"]}, {"who": "seller", "fr": "Allez-y... voilà, c'est noté. Ah, une dernière chose : celui de la vitrine a une tirette abîmée, donc il est soldé à cinquante euros.", "en": "Go ahead... there, it's written down. Oh, one last thing: the one in the window has a damaged zip, so it's marked down to fifty euros.", "gloss": {"Allez-y": "go ahead", "tirette": "zip (Belgium; France: fermeture éclair)", "abîmée": "damaged", "soldé": "marked down"}}, {"who": "you", "fr": "C'est tentant, mais je préfère un pull sans défaut, merci.", "en": "It's tempting, but I'd rather have one with no fault, thanks.", "gloss": {"tentant": "tempting", "défaut": "fault / flaw"}, "accept": ["c'est tentant mais je préfère un pull sans défaut merci", "c'est tentant mais je préfère un pull sans défaut", "merci mais je préfère un pull sans défaut", "non merci je préfère un pull sans défaut", "c'est gentil mais je préfère attendre la commande", "je préfère un pull sans défaut merci"]}, {"who": "seller", "fr": "Je comprends tout à fait. Alors on part sur la commande.", "en": "I completely understand. So we'll go with the order then.", "gloss": {"on part sur": "we'll go with (colloquial)"}}, {"who": "you", "fr": "Oui. Et si la taille ne me va pas, je peux l'échanger ?", "en": "Yes. And if the size doesn't fit me, can I exchange it?", "gloss": {"ne me va pas": "doesn't fit me"}, "accept": ["oui et si la taille ne me va pas je peux l'échanger", "et si la taille ne me va pas je peux l'échanger", "si la taille ne me va pas je peux l'échanger", "et si ça ne me va pas je peux l'échanger", "je peux l'échanger si la taille ne va pas", "et si la taille ne convient pas je peux l'échanger"]}, {"who": "seller", "fr": "Bien sûr, vous avez trente jours avec le ticket de caisse. On vous rembourse ou on vous fait un avoir, comme vous voulez.", "en": "Of course, you have thirty days with the receipt. We refund you or give you a credit note, as you like.", "gloss": {"rembourse": "refund", "un avoir": "a credit note"}}, {"who": "you", "fr": "Parfait. Merci d'avoir vérifié, c'est gentil. Bonne fin de journée !", "en": "Perfect. Thanks for checking, that's kind. Have a good rest of the day!", "gloss": {"Merci d'avoir vérifié": "thanks for having checked"}, "accept": ["parfait merci d'avoir vérifié c'est gentil bonne fin de journée", "merci d'avoir vérifié bonne fin de journée", "parfait merci beaucoup bonne fin de journée", "merci beaucoup bonne journée", "merci d'avoir vérifié c'est gentil bonne journée", "parfait merci bonne fin de journée", "merci bonne fin de journée"]}], "exercises": [{"id": "ex-clothes-B1-01", "level": "B1", "format": "fr2en", "q": "être en rupture de stock", "options": ["to be out of stock", "to be having a clearance sale", "to have broken a delivery contract", "to be closed for stocktaking"], "a": 0, "expl": "The shop has none left. « Le déstockage » is the opposite problem."}, {"id": "ex-clothes-B1-02", "level": "B1", "format": "cloze", "q": "Je ___ un remboursement plutôt qu'un avoir.", "options": ["préférerais", "préfère", "préférais", "préférerai"], "a": 0, "expl": "All four are real forms of préférer. The conditional « préférerais » is the polite one to use with staff; the imparfait and future would sound odd in a live request."}, {"id": "ex-clothes-B1-03", "level": "B1", "format": "en2fr", "q": "the alteration (to a garment)", "options": ["la retouche", "la réparation", "la correction", "la modification"], "a": 0, "expl": "« Faire une retouche » on clothes. « Une réparation » is for something broken."}, {"id": "ex-clothes-B1-04", "level": "B1", "format": "cloze", "q": "Vous me préviendrez quand il ___ arrivé ?", "options": ["sera", "est", "serait", "soit"], "a": 0, "expl": "After « quand » pointing at the future, French needs the future — here the futur antérieur « sera arrivé ». English gets away with the present; French does not."}, {"id": "ex-clothes-B1-05", "level": "B1", "format": "fr2en", "q": "un avoir", "options": ["a credit note usable in that shop", "a cash refund", "a deposit paid in advance", "a gift receipt"], "a": 0, "expl": "Shops offer « un avoir » first; « un remboursement » is money back."}, {"id": "ex-clothes-B1-06", "level": "B1", "format": "collocation", "q": "Le pull a un petit défaut. Comment demandez-vous poliment une réduction ?", "options": ["Vous pourriez faire un geste commercial ?", "Vous pourriez baisser le prix pour moi ?", "Vous pourriez me faire un prix d'ami ?", "Vous pourriez me faire un cadeau ?"], "a": 0, "expl": "« Un geste commercial » is the neutral, professional formula. « Un prix d'ami » implies you know the seller personally."}, {"id": "ex-clothes-B1-07", "level": "B1", "format": "fr2en", "q": "faire la file", "options": ["to queue (Belgium)", "to file a complaint", "to walk in single file", "to sort paperwork"], "a": 0, "expl": "In France: « faire la queue ». On Belgian motorway signs, « file » also means a traffic jam."}, {"id": "ex-clothes-B1-08", "level": "B1", "format": "cloze", "q": "La doublure est ___ , il faudrait la recoudre.", "options": ["décousue", "déchirée", "tachée", "rétrécie"], "a": 0, "expl": "All four are feminine adjectives that fit the grammar. « Recoudre » (to sew back up) tells you the stitching has come undone — décousue."}, {"id": "ex-clothes-B1-09", "level": "B1", "format": "en2fr", "q": "loose-fitting, roomy", "options": ["ample", "ajusté", "moulant", "serré"], "a": 0, "expl": "The scale: ample → droit → ajusté → moulant."}, {"id": "ex-clothes-B1-10", "level": "B1", "format": "fr2en", "q": "le délai de livraison", "options": ["the normal time delivery takes", "a delivery that is running late", "the delivery charge", "the last day to return goods"], "a": 0, "expl": "« Un délai » is a normal lead time. A hold-up is « un retard »."}, {"id": "ex-clothes-B1-11", "level": "B1", "format": "collocation", "q": "Quelle phrase demande poliment de vérifier le stock ?", "options": ["Est-ce que vous pourriez vérifier en réserve ?", "Vérifiez en réserve, s'il vous plaît", "Vous devez vérifier en réserve", "Il faut que vous vérifiiez en réserve"], "a": 0, "expl": "The conditional question is the polite register. The imperative and « vous devez » both give an order to someone serving you."}, {"id": "ex-clothes-B1-12", "level": "B1", "format": "fr2en", "q": "Je ne sais pas passer avant samedi.", "options": ["I can't come by before Saturday (Belgium)", "I don't know whether to come by before Saturday", "I don't know the way before Saturday", "I mustn't come by before Saturday"], "a": 0, "expl": "Belgicism: savoir = pouvoir. Say « je ne peux pas passer » to a French speaker to avoid confusion."}, {"id": "ex-clothes-B1-13", "level": "B1", "format": "cloze", "q": "Il ne nous ___ que du M et du XL.", "options": ["reste", "manque", "faut", "sert"], "a": 0, "expl": "All four take this impersonal structure. « Il reste » = there is ... left; « il manque » would mean the M and XL are the ones missing — the opposite."}, {"id": "ex-clothes-B1-14", "level": "B1", "format": "en2fr", "q": "the security tag on a garment", "options": ["l'antivol", "le portique", "l'étiquette", "le cadenas"], "a": 0, "expl": "« Le portique » is the gate at the door; « l'antivol » is the tag that sets it off."}]},
  "restaurant-A2": {"slug": "restaurant", "level": "A2", "title": "Commander au restaurant", "place": "Une brasserie de la place Fernand Cocq, Ixelles, Bruxelles", "register": "vous", "registerNote": "Vous with the waiter from start to finish, whatever his age — restaurant service in Belgium stays formal. You say « bonjour » on arriving, « merci » every time a plate lands, and « bonne soirée » on the way out. Tu is only for the friend sitting opposite you.", "vocab": [{"id": "fvc-restaurant-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte", "en": "the menu (the full list)", "format": "fr2en", "options": ["the full list of dishes", "the fixed-price meal", "the wine list only", "the bill"], "a": 0, "trap": "le menu — in French that is a fixed-price set meal, not the list of everything", "expl": "« La carte, s'il vous plaît » gets you the big list. « Manger à la carte » = to choose freely rather than take a set meal."}, {"id": "fvc-restaurant-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le menu", "en": "the set meal at a fixed price", "format": "fr2en", "options": ["the set meal at a fixed price", "the list of all dishes", "the daily special", "the menu board outside"], "a": 0, "trap": "English 'menu' — the list is « la carte »; « le menu » is a deal", "expl": "« Le menu à 25 euros » usually means starter + main + dessert. Belgian brasseries advertise it on a board by the door."}, {"id": "fvc-restaurant-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plat du jour", "en": "the dish of the day", "format": "en2fr", "options": ["le plat du jour", "le menu du jour", "le jour du plat", "le plat de la journée"], "a": 0, "trap": "« le menu du jour » exists too, but it is a whole set meal, not one dish", "expl": "Lunchtime staple, usually €14–18 in Ixelles, often chalked on a slate. « Quel est le plat du jour ? »"}, {"id": "fvc-restaurant-A2-04", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'entrée", "en": "the starter", "format": "fr2en", "options": ["the starter", "the main course", "the way in", "the side dish"], "a": 0, "trap": "English 'entrée' means the main course in America — in French it is always the first course", "expl": "The order is: l'entrée, le plat, le dessert. « L'entrée » also means the entrance to a building, but never the main dish."}, {"id": "fvc-restaurant-A2-05", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plat", "en": "the main course / the dish", "format": "cloze", "q": "Comme ___ , je vais prendre les carbonnades.", "options": ["plat", "entrée", "dessert", "apéritif"], "a": 0, "trap": "entrée — grammatically identical, but carbonnades are not a starter", "expl": "All four are course names that fit after « comme ». « Comme plat » = for my main. « Un plat » is also the physical dish."}, {"id": "fvc-restaurant-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le dessert", "en": "the dessert", "format": "en2fr", "options": ["le dessert", "le désert", "le service", "le digestif"], "a": 0, "trap": "le désert — one s, and it is the Sahara. Two s's for the sweet course.", "expl": "Remember: dessert has two s's because you want two helpings. « Un digestif » is the drink after it."}, {"id": "fvc-restaurant-A2-07", "level": "A2", "pos": "noun", "gender": "f", "fr": "la boisson", "en": "the drink", "format": "fr2en", "options": ["the drink", "the food", "the meal", "the glass"], "a": 0, "trap": "le boisseau and « la boîte » look similar but are unrelated; the real confusion is with « le verre », the glass it comes in", "expl": "« Et comme boisson ? » is the waiter's standard follow-up question once the food is ordered."}, {"id": "fvc-restaurant-A2-08", "level": "A2", "pos": "noun", "gender": "m", "fr": "le serveur", "en": "the waiter", "format": "en2fr", "options": ["le serveur", "le service", "le cuisinier", "le patron"], "a": 0, "trap": "le service — the service or the service charge, not the person", "expl": "Feminine « la serveuse ». Never call him « garçon » — that has been rude for fifty years. Catch his eye and say « s'il vous plaît »."}, {"id": "fvc-restaurant-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la terrasse", "en": "the terrace / outside tables", "format": "fr2en", "options": ["the outside tables", "the roof", "the back room", "the pavement itself"], "a": 0, "trap": "le trottoir — the pavement the terrace stands on", "expl": "« En terrasse » (no article) = outside: « on peut s'installer en terrasse ? » In Belgium terraces are heated and used all winter."}, {"id": "fvc-restaurant-A2-10", "level": "A2", "pos": "noun", "gender": "f", "fr": "la réservation", "en": "the booking", "format": "en2fr", "options": ["la réservation", "la commande", "la réserve", "la table"], "a": 0, "trap": "la réserve — the stockroom or the reserve, not a booking", "expl": "« Vous avez réservé ? » — « Non, on n'a pas de réservation. » On a Saturday night in Ixelles, book."}, {"id": "fvc-restaurant-A2-11", "level": "A2", "pos": "verb", "fr": "prendre", "en": "to have (food or drink)", "format": "fr2en", "options": ["to have (a dish or drink)", "to eat quickly", "to bring to the table", "to choose from a list"], "a": 0, "trap": "manger — to eat; you order with « prendre », not « manger »", "expl": "« Je vais prendre les moules. » This is the ordering verb in French, exactly like English 'I'll have'."}, {"id": "fvc-restaurant-A2-12", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'addition", "en": "the bill", "format": "fr2en", "options": ["the bill", "the sum in maths only", "the tip", "the receipt"], "a": 0, "trap": "le pourboire — the tip, which is a different thing and optional", "expl": "« L'addition, s'il vous plaît ! » In Belgium you ask for it; it will not arrive on its own."}, {"id": "fvc-restaurant-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pourboire", "en": "the tip", "format": "en2fr", "options": ["le pourboire", "le service", "la monnaie", "l'addition"], "a": 0, "trap": "le service — already included in the price in Belgium, unlike the tip", "note": "Belgian custom: service and VAT are always included, so a tip is genuinely optional. Rounding up or leaving a euro or two is normal; 15% is not expected, unlike in the US.", "expl": "Literally 'for drinking'. « Gardez la monnaie » is how you leave one."}, {"id": "fvc-restaurant-A2-14", "level": "A2", "pos": "noun", "gender": "m", "fr": "le service", "en": "the service charge", "format": "collocation", "q": "Quelle phrase entend-on dans un restaurant belge ?", "options": ["Le service est compris", "Le service est à part", "Le service est en plus obligatoire", "Le service est à quinze pour cent"], "a": 0, "trap": "in the US the service is added on top; in Belgium it is always inside the printed price", "note": "Belgium and France both include service in the price by law. Menus often print « service et TVA compris ».", "expl": "« Compris » = included. So the total at the bottom of the addition is really the total."}, {"id": "fvc-restaurant-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "les frites", "en": "the chips", "format": "fr2en", "options": ["the chips / fries", "the crisps", "the fried onions", "the roast potatoes"], "a": 0, "trap": "les chips — in French that means crisps in a packet, not hot chips", "note": "Belgian pride: proper frites are fried twice, in beef fat, and come in « un cornet » from a « friterie » or « fritkot ».", "expl": "« Moules-frites » and « steak-frites » are written with a hyphen and ordered as one thing."}, {"id": "fvc-restaurant-A2-16", "level": "A2", "pos": "noun", "gender": "f", "fr": "les moules", "en": "the mussels", "format": "en2fr", "options": ["les moules", "les huîtres", "les crevettes", "les palourdes"], "a": 0, "trap": "les huîtres — oysters, the other thing that arrives in a shell", "expl": "« Les moules-frites » are the national dish; the season traditionally runs from September. « Moules marinières » is the white-wine version."}, {"id": "fvc-restaurant-A2-17", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carbonnade", "en": "beef stewed in beer", "format": "fr2en", "options": ["beef stewed in brown beer", "a grilled steak", "a coal-fired pizza", "a pork sausage"], "a": 0, "trap": "learners see « carbon » and think grilled over coals", "note": "Belgian classic, « les carbonnades flamandes », usually served with frites and a spoonful of mustard. Rarely found on a French menu.", "expl": "Cooked slowly in brown beer with a slice of gingerbread. Almost always plural on the menu."}, {"id": "fvc-restaurant-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "le waterzooi", "en": "creamy Ghent stew", "format": "fr2en", "options": ["a creamy chicken or fish stew", "a cold beer soup", "a Flemish beef stew", "a seafood platter"], "a": 0, "trap": "la carbonnade — the other big Belgian stew, but brown, beefy and made with beer", "note": "Belgian and Flemish in origin (Ghent). Waterzooi is cream-based; carbonnade is beer-based. Neither appears on a normal French menu.", "expl": "« Un waterzooi de poulet » or « de poisson ». The word is Dutch, pronounced roughly 'wa-ter-zoy'."}, {"id": "fvc-restaurant-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chicon", "en": "chicory / endive (Belgium)", "format": "fr2en", "options": ["the white chicory head", "the curly green salad", "the cabbage", "the leek"], "a": 0, "trap": "in France the same vegetable is « une endive » — and « la chicorée » there is something else again", "note": "Belgian French. « Les chicons au gratin » (wrapped in ham, baked with cheese sauce) is a menu staple you will not see in France.", "expl": "Grown in the dark so it stays white. Ask for « des chicons » in a Delhaize; « endives » will also be understood but is the French word."}, {"id": "fvc-restaurant-A2-20", "level": "A2", "pos": "noun", "gender": "f", "fr": "les boulettes", "en": "the meatballs", "format": "en2fr", "options": ["les boulettes", "les croquettes", "les saucisses", "les côtelettes"], "a": 0, "trap": "les croquettes — breadcrumbed and fried, often filled with shrimp or cheese in Belgium", "expl": "« Les boulettes sauce tomate » or, in Liège, « boulets sauce lapin ». « Une croquette aux crevettes grises » is the great Belgian starter."}, {"id": "fvc-restaurant-A2-21", "level": "A2", "pos": "noun", "gender": "f", "fr": "la sauce", "en": "the sauce", "format": "cloze", "q": "Les carbonnades sont servies avec une ___ à la bière brune.", "options": ["sauce", "salade", "assiette", "boisson"], "a": 0, "trap": "salade — grammatically fine, and stews do come with a side salad, but « à la bière brune » describes the liquid", "expl": "All four are feminine nouns that fit after « une ». « À la + ingredient » names what something is made with."}, {"id": "fvc-restaurant-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "le potage", "en": "the soup (menu word)", "format": "fr2en", "options": ["the soup, as written on a menu", "a thick stew", "a hot pot of tea", "the vegetable side dish"], "a": 0, "trap": "la soupe — the same thing, but « potage » is what Belgian menus and canteens print", "note": "In Belgium « le potage du jour » is on almost every lunch menu and in every school canteen. In France « soupe » is at least as common as « potage ».", "expl": "« Le potage du jour, c'est quoi ? » — usually tomato, leek or « potage aux légumes »."}, {"id": "fvc-restaurant-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pain", "en": "the bread", "format": "en2fr", "options": ["le pain", "le pot", "le pané", "le poivre"], "a": 0, "trap": "le poivre — pepper; both short p-words that come with the bread basket", "expl": "« Vous pouvez apporter encore du pain ? » In a brasserie bread comes free with the meal; in a friterie nothing does."}, {"id": "fvc-restaurant-A2-24", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'eau pétillante", "en": "sparkling water", "format": "en2fr", "options": ["l'eau pétillante", "l'eau plate", "l'eau du robinet", "l'eau chaude"], "a": 0, "trap": "l'eau plate — still water, the other half of the question the waiter asks", "expl": "« Plate ou pétillante ? » is the standard question. Belgian brands: Spa Reine (plate), Spa Barisart (pétillante), Chaudfontaine."}, {"id": "fvc-restaurant-A2-25", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carafe d'eau", "en": "a jug of tap water", "format": "fr2en", "options": ["a jug of tap water", "a decanter of wine", "a bottle of mineral water", "a large glass"], "a": 0, "trap": "learners assume it is free everywhere because it is in France", "note": "Important difference: in France restaurants must serve free tap water on request. In Belgium there is no such rule — many places refuse, or charge €1–2. Expect to buy bottled Spa.", "expl": "You can still ask: « une carafe d'eau, c'est possible ? » Just be ready for « on ne fait pas, désolé »."}, {"id": "fvc-restaurant-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "le verre", "en": "the glass", "format": "fr2en", "options": ["the glass", "the green colour", "the worm", "the direction 'towards'"], "a": 0, "trap": "vert / ver / vers all sound identical — only spelling and context separate them", "expl": "« Un verre de vin rouge » = a glass of red. « Prendre un verre » = to go for a drink."}, {"id": "fvc-restaurant-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "la bouteille", "en": "the bottle", "format": "cloze", "q": "On prend une ___ de rouge pour deux ?", "options": ["bouteille", "carafe", "assiette", "tasse"], "a": 0, "trap": "carafe — a real option in a French bistro, but Belgian brasseries sell wine by the glass or the bottle, rarely by the carafe", "expl": "All four are feminine containers that fit. « Un demi-litre », « une demi-bouteille » (37,5 cl) also exist."}, {"id": "fvc-restaurant-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'assiette", "en": "the plate", "format": "en2fr", "options": ["l'assiette", "la tasse", "la soucoupe", "la casserole"], "a": 0, "trap": "la soucoupe — the saucer under the cup", "expl": "« Une assiette de fromages » = a cheese plate. « La casserole » is the pan it was cooked in."}, {"id": "fvc-restaurant-A2-29", "level": "A2", "pos": "noun", "gender": "f", "fr": "la fourchette", "en": "the fork", "format": "en2fr", "options": ["la fourchette", "la cuillère", "la spatule", "la pince"], "a": 0, "trap": "la cuillère — the spoon, the other thing you may be missing", "expl": "The set is « les couverts »: une fourchette, un couteau, une cuillère. « Il me manque une fourchette » = I'm missing a fork."}, {"id": "fvc-restaurant-A2-30", "level": "A2", "pos": "noun", "gender": "m", "fr": "le couteau", "en": "the knife", "format": "fr2en", "options": ["the knife", "the elbow", "the neck", "the coat"], "a": 0, "trap": "le manteau — rhymes exactly and is one of the first nouns you learn", "expl": "Plural « les couteaux ». For mussels you get « une pince » and an empty shell instead."}, {"id": "fvc-restaurant-A2-31", "level": "A2", "pos": "noun", "gender": "f", "fr": "la serviette", "en": "the napkin", "format": "fr2en", "options": ["the napkin", "the tea towel", "the tablecloth", "the tray"], "a": 0, "trap": "la nappe — the tablecloth; and in Belgium « un essuie » is a towel, where France says « une serviette »", "note": "Belgian French: a bath or kitchen towel is « un essuie » (essuie de bain, essuie de vaisselle). In France all of those are « une serviette ».", "expl": "« Une serviette » at the table is a napkin; the same word means a briefcase in an office."}, {"id": "fvc-restaurant-A2-32", "level": "A2", "pos": "adj", "fr": "saignant", "en": "rare (of steak)", "format": "fr2en", "options": ["rare", "medium", "well done", "raw"], "a": 0, "trap": "bleu — even rarer than saignant, barely warmed through", "expl": "The scale: bleu, saignant, à point, bien cuit. « À point » means medium here, not 'perfect'."}, {"id": "fvc-restaurant-A2-33", "level": "A2", "pos": "adj", "fr": "bien cuit", "en": "well done", "format": "en2fr", "options": ["bien cuit", "à point", "saignant", "bleu"], "a": 0, "trap": "à point — medium, which is what most Belgian kitchens serve if you say nothing", "expl": "« Quelle cuisson ? » is the waiter asking how you want it cooked. Answer with one of the four."}, {"id": "fvc-restaurant-A2-34", "level": "A2", "pos": "adj", "fr": "délicieux", "en": "delicious", "format": "en2fr", "options": ["délicieux", "délicat", "dégoûtant", "doux"], "a": 0, "trap": "délicat — delicate or tricky, not tasty", "expl": "« C'était délicieux, merci. » Feminine « délicieuse ». « Dégoûtant » means disgusting — do not mix them up."}, {"id": "fvc-restaurant-A2-35", "level": "A2", "pos": "verb", "fr": "goûter", "en": "to taste (something)", "format": "fr2en", "options": ["to taste something", "to drip", "to enjoy an evening", "to cost"], "a": 0, "trap": "coûter — one letter apart from goûter, and both come up over dinner", "note": "Belgian French: « ça goûte ! » means 'that tastes good'. In France that is not said — they would say « c'est bon » or « c'est délicieux ».", "expl": "« Vous voulez goûter ? » = would you like a taste? « Le goût » is the flavour."}, {"id": "fvc-restaurant-A2-36", "level": "A2", "pos": "verb", "fr": "apporter", "en": "to bring (something)", "format": "en2fr", "options": ["apporter", "emporter", "amener", "rapporter"], "a": 0, "trap": "emporter — to take away, the opposite direction; « à emporter » means takeaway", "expl": "« Vous pouvez m'apporter du pain ? » Things are apportés, people are amenés."}, {"id": "fvc-restaurant-A2-37", "level": "A2", "pos": "verb", "fr": "choisir", "en": "to choose", "format": "cloze", "q": "On n'a pas encore ___ , vous pouvez repasser dans cinq minutes ?", "options": ["choisi", "commandé", "mangé", "payé"], "a": 0, "trap": "commandé — also grammatical and almost true, but you order after you have chosen", "expl": "All four are past participles that fit with « on n'a pas encore ». « Repasser » here means to come back round."}, {"id": "fvc-restaurant-A2-38", "level": "A2", "pos": "expr", "fr": "avoir faim", "en": "to be hungry", "format": "collocation", "q": "Vous arrivez au restaurant affamé. Quelle phrase est correcte ?", "options": ["J'ai très faim", "Je suis très faim", "J'ai très faim de", "Je suis affamé de faim"], "a": 0, "trap": "« je suis faim » is the direct translation of 'I am hungry' and is always wrong", "expl": "Hunger, thirst, cold and heat all use avoir: j'ai faim, j'ai soif, j'ai froid, j'ai chaud. Intensify with « très », never « beaucoup »."}, {"id": "fvc-restaurant-A2-39", "level": "A2", "pos": "noun", "gender": "f", "fr": "les toilettes", "en": "the toilets", "format": "fr2en", "options": ["the toilets", "the washbasin", "the cloakroom", "the changing room"], "a": 0, "trap": "le vestiaire — the cloakroom where you leave your coat", "note": "In Belgium the toilets in a brasserie are usually free for customers, but in stations and some cafés there is a « dame-pipi » and a €0.50 saucer.", "expl": "Always plural: « les toilettes sont où ? » or the more polite « où sont les toilettes, s'il vous plaît ? »."}, {"id": "fvc-restaurant-A2-40", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'apéritif", "en": "the pre-dinner drink", "format": "fr2en", "options": ["a drink before the meal", "a small starter served free", "the strong drink after coffee", "a wine tasting"], "a": 0, "trap": "le digestif — the drink at the other end of the meal", "expl": "Shortened to « l'apéro » in speech. « Prendre l'apéro » is a whole social event, not just one glass."}, {"id": "fvc-restaurant-A2-41", "level": "A2", "pos": "expr", "fr": "à emporter", "en": "to take away", "format": "en2fr", "options": ["à emporter", "sur place", "à la carte", "à point"], "a": 0, "trap": "sur place — eating in, the exact opposite answer to the same question", "expl": "« Sur place ou à emporter ? » is asked at every counter in Belgium. Answer with one of the two, nothing else needed."}, {"id": "fvc-restaurant-A2-42", "level": "A2", "pos": "noun", "gender": "f", "fr": "la nappe", "en": "the tablecloth", "format": "cloze", "q": "Le serveur a changé la ___ avant de nous installer.", "options": ["nappe", "chaise", "carte", "porte"], "a": 0, "trap": "carte — feminine and perfectly grammatical, but the menu is not changed between two lunches", "expl": "All four are feminine nouns that fit. « Une nappe en papier » is the brasserie standard; « une nappe blanche » means you are paying more."}, {"id": "fvc-restaurant-A2-43", "level": "A2", "pos": "noun", "gender": "f", "fr": "la cuisson", "en": "how it is cooked", "format": "fr2en", "options": ["the degree to which meat is cooked", "the kitchen", "the cook", "the cooker"], "a": 0, "trap": "la cuisine — the kitchen or the cooking as an art", "expl": "« Quelle cuisson pour la viande ? » = how would you like it done? Answer: saignant, à point, bien cuit."}, {"id": "fvc-restaurant-A2-44", "level": "A2", "pos": "expr", "fr": "en espèces", "en": "in cash", "format": "collocation", "q": "Comment dit-on que vous payez en argent liquide ?", "options": ["Je paie en espèces", "Je paie par espèces", "Je paie en cash-argent", "Je paie de l'espèce"], "a": 0, "trap": "« par » is right for a card (par Bancontact) but wrong for cash", "expl": "Cash: « en espèces » or « en liquide » (or simply « cash », which Belgians say too). Cards: « par carte / par Bancontact »."}, {"id": "fvc-restaurant-A2-45", "level": "A2", "pos": "noun", "gender": "f", "fr": "la note", "en": "the bill (in a hotel or café)", "format": "fr2en", "options": ["the bill you settle", "a written note to a friend", "a school mark only", "a musical note only"], "a": 0, "trap": "l'addition — the same idea in a restaurant; « la note » belongs to hotels and cafés", "expl": "« La note » also means a mark at school and a note in music. In a brasserie, ask for « l'addition »."}, {"id": "fvc-restaurant-A2-46", "level": "A2", "pos": "adj", "fr": "compris", "en": "included", "format": "cloze", "q": "Le service est ___ dans le prix.", "options": ["compris", "gratuit", "obligatoire", "cher"], "a": 0, "trap": "gratuit — an adjective that fits the slot, but you cannot say the service is free when it is inside the price you pay", "expl": "All four are masculine singular adjectives. « Compris » = included; « TVA comprise » = VAT included, agreeing with the feminine TVA."}], "phrases": [{"id": "ph-restaurant-A2-01", "fr": "Bonsoir, une table pour deux, s'il vous plaît.", "en": "Good evening, a table for two, please.", "note": "« Bonsoir » from about 6 p.m. Say the number of people first — that is all the waiter needs."}, {"id": "ph-restaurant-A2-02", "fr": "On n'a pas réservé, c'est possible quand même ?", "en": "We haven't booked, is it still possible?", "note": "« Quand même » = all the same. « On » is how everyone says 'we' in speech."}, {"id": "ph-restaurant-A2-03", "fr": "On peut s'installer en terrasse ?", "en": "Can we sit outside?", "note": "« En terrasse » with no article. « S'installer » is the natural verb for taking a table."}, {"id": "ph-restaurant-A2-04", "fr": "La carte, s'il vous plaît.", "en": "The menu, please.", "note": "« La carte » is the full list. Asking for « le menu » gets you the fixed-price deal instead."}, {"id": "ph-restaurant-A2-05", "fr": "Quel est le plat du jour ?", "en": "What's the dish of the day?", "note": "Usually the best value at lunch, €14–18 in Ixelles. « C'est quoi, le plat du jour ? » is the spoken version."}, {"id": "ph-restaurant-A2-06", "fr": "On n'a pas encore choisi, vous pouvez repasser ?", "en": "We haven't chosen yet, could you come back?", "note": "« Repasser » = to come back round. Buys you two minutes without any awkwardness."}, {"id": "ph-restaurant-A2-07", "fr": "Je vais prendre les carbonnades, s'il vous plaît.", "en": "I'll have the carbonnades, please.", "note": "« Je vais prendre » is the standard ordering formula. « Je veux » sounds blunt to the point of rude."}, {"id": "ph-restaurant-A2-08", "fr": "Comme entrée, une croquette aux crevettes grises.", "en": "For a starter, a grey shrimp croquette.", "note": "« Comme + course » introduces each choice. « Les crevettes grises » from the North Sea are a Belgian speciality."}, {"id": "ph-restaurant-A2-09", "fr": "Pour moi, un steak à point, s'il vous plaît.", "en": "For me, a medium steak, please.", "note": "« À point » is medium, not 'perfectly done'. The four levels: bleu, saignant, à point, bien cuit."}, {"id": "ph-restaurant-A2-10", "fr": "Et comme boisson, une eau pétillante.", "en": "And to drink, a sparkling water.", "note": "The waiter will ask « plate ou pétillante ? ». Spa and Chaudfontaine are the Belgian brands."}, {"id": "ph-restaurant-A2-11", "fr": "Une carafe d'eau, c'est possible ?", "en": "Could we have a jug of tap water?", "note": "In France free tap water is a legal right; in Belgium it is not, so many places say no or charge a euro or two. Ask politely, expect either answer."}, {"id": "ph-restaurant-A2-12", "fr": "Est-ce qu'il y a des frites avec ?", "en": "Does it come with chips?", "note": "« Avec » can end the sentence, exactly like English 'with it'. In Belgium the answer is usually yes."}, {"id": "ph-restaurant-A2-13", "fr": "Vous pouvez m'apporter du pain, s'il vous plaît ?", "en": "Could you bring me some bread, please?", "note": "« Apporter » brings things towards you; « emporter » takes them away."}, {"id": "ph-restaurant-A2-14", "fr": "Il me manque une fourchette.", "en": "I'm missing a fork.", "note": "« Il me manque » + thing = I'm short of. Never « je manque une fourchette », which means something else entirely."}, {"id": "ph-restaurant-A2-15", "fr": "C'était vraiment délicieux, merci.", "en": "That was really delicious, thank you.", "note": "Imparfait « c'était » for the meal as a whole. In Brussels you may also hear « ça goûtait bien », which is Belgian only."}, {"id": "ph-restaurant-A2-16", "fr": "Les toilettes sont où, s'il vous plaît ?", "en": "Where are the toilets, please?", "note": "Always plural. In a brasserie they are free for customers; in a station expect a €0.50 saucer."}, {"id": "ph-restaurant-A2-17", "fr": "Deux cafés, s'il vous plaît.", "en": "Two coffees, please.", "note": "A Belgian coffee costs about €2.80 and arrives with a biscuit or a small chocolate. Ask for « un allongé » if you want it longer."}, {"id": "ph-restaurant-A2-18", "fr": "L'addition, s'il vous plaît.", "en": "The bill, please.", "note": "It will never come unasked — that would be hurrying you out. Catch his eye or raise a hand slightly."}, {"id": "ph-restaurant-A2-19", "fr": "On peut payer par Bancontact ?", "en": "Can we pay by debit card?", "note": "Almost everywhere yes, but small brasseries and friteries can still be cash-only — check before you order if you have no cash."}, {"id": "ph-restaurant-A2-20", "fr": "Gardez la monnaie, merci. Bonne soirée !", "en": "Keep the change, thanks. Have a good evening!", "note": "Service is already included in Belgium, so this is how a tip is left: round up and say it. « Bonne soirée » on the way out."}], "dialogue": [{"who": "waiter", "fr": "Bonsoir ! Vous avez réservé ?", "en": "Good evening! Have you booked?", "gloss": {"réservé": "booked"}}, {"who": "you", "fr": "Bonsoir, non. Une table pour deux, s'il vous plaît.", "en": "Good evening, no. A table for two, please.", "gloss": {"table": "table"}, "accept": ["bonsoir non une table pour deux s'il vous plaît", "non une table pour deux s'il vous plaît", "bonsoir non on n'a pas réservé une table pour deux", "une table pour deux s'il vous plaît", "bonsoir une table pour deux s'il vous plaît", "non mais on voudrait une table pour deux"]}, {"who": "waiter", "fr": "Pas de souci, installez-vous près de la fenêtre. Voici la carte.", "en": "No problem, take a seat by the window. Here's the menu.", "gloss": {"Pas de souci": "no problem", "installez-vous": "take a seat", "carte": "menu (the full list)"}}, {"who": "you", "fr": "Merci. Quel est le plat du jour ?", "en": "Thank you. What's the dish of the day?", "gloss": {"plat du jour": "dish of the day"}, "accept": ["merci quel est le plat du jour", "quel est le plat du jour", "merci c'est quoi le plat du jour", "et le plat du jour c'est quoi", "merci quel est le plat du jour s'il vous plaît", "c'est quoi le plat du jour"]}, {"who": "waiter", "fr": "Ce soir, c'est du waterzooi de poulet, à seize euros, avec des frites ou des croquettes.", "en": "Tonight it's chicken waterzooi, sixteen euros, with chips or croquettes.", "gloss": {"waterzooi": "creamy Ghent-style stew", "frites": "chips", "croquettes": "potato croquettes"}}, {"who": "you", "fr": "On n'a pas encore choisi. Vous pouvez repasser dans cinq minutes ?", "en": "We haven't chosen yet. Could you come back in five minutes?", "gloss": {"choisi": "chosen", "repasser": "come back round"}, "accept": ["on n'a pas encore choisi vous pouvez repasser dans cinq minutes", "on n'a pas encore choisi", "on n'a pas encore choisi vous pouvez revenir dans cinq minutes", "est-ce que vous pouvez repasser dans cinq minutes", "on a besoin de cinq minutes", "vous pouvez repasser dans cinq minutes s'il vous plaît"]}, {"who": "waiter", "fr": "Bien sûr, je vous laisse regarder. Je reviens.", "en": "Of course, I'll let you look. I'll come back.", "gloss": {"je vous laisse": "I'll let you"}}, {"who": "you", "fr": "C'est bon, on a choisi. Comme entrée, une croquette aux crevettes grises.", "en": "We're ready, we've chosen. For a starter, a grey shrimp croquette.", "gloss": {"Comme entrée": "for a starter", "crevettes grises": "North Sea grey shrimp"}, "accept": ["c'est bon on a choisi comme entrée une croquette aux crevettes grises", "on a choisi comme entrée une croquette aux crevettes grises", "comme entrée une croquette aux crevettes grises", "comme entrée je vais prendre une croquette aux crevettes grises", "je voudrais une croquette aux crevettes grises en entrée", "comme entrée une croquette aux crevettes grises s'il vous plaît"]}, {"who": "waiter", "fr": "Très bien. Et comme plat ?", "en": "Very good. And for the main?", "gloss": {"comme plat": "for the main course"}}, {"who": "you", "fr": "Je vais prendre les carbonnades flamandes, s'il vous plaît.", "en": "I'll have the Flemish beef stew, please.", "gloss": {"carbonnades flamandes": "beef stewed in brown beer"}, "accept": ["je vais prendre les carbonnades flamandes s'il vous plaît", "je vais prendre les carbonnades flamandes", "je prends les carbonnades flamandes", "pour moi les carbonnades flamandes", "je voudrais les carbonnades flamandes", "les carbonnades flamandes s'il vous plaît", "je vais prendre les carbonnades"]}, {"who": "waiter", "fr": "Avec des frites, comme d'habitude ? Et comme boisson ?", "en": "With chips, as usual? And to drink?", "gloss": {"comme d'habitude": "as usual"}}, {"who": "you", "fr": "Oui, avec des frites. Et une eau pétillante, s'il vous plaît.", "en": "Yes, with chips. And a sparkling water, please.", "gloss": {"pétillante": "sparkling"}, "accept": ["oui avec des frites et une eau pétillante s'il vous plaît", "oui avec des frites et une eau pétillante", "avec des frites et une eau pétillante s'il vous plaît", "oui et une eau pétillante s'il vous plaît", "oui avec des frites et de l'eau pétillante", "une eau pétillante s'il vous plaît"]}, {"who": "waiter", "fr": "Une grande ou une petite ?", "en": "A large one or a small one?", "gloss": {"grande": "large"}}, {"who": "you", "fr": "Une grande, pour partager.", "en": "A large one, to share.", "gloss": {"partager": "to share"}, "accept": ["une grande pour partager", "une grande", "une grande bouteille pour partager", "une grande s'il vous plaît", "une grande merci", "plutôt une grande pour partager"]}, {"who": "waiter", "fr": "C'est noté. Bon appétit ! ... Alors, ça vous a plu ?", "en": "Got it. Enjoy your meal! ... So, did you enjoy it?", "gloss": {"C'est noté": "got it / written down", "ça vous a plu": "did you like it"}}, {"who": "you", "fr": "C'était vraiment délicieux, merci.", "en": "It was really delicious, thank you.", "gloss": {"C'était": "it was (imparfait)", "délicieux": "delicious"}, "accept": ["c'était vraiment délicieux merci", "c'était délicieux merci", "oui c'était très bon merci", "c'était excellent merci", "c'était vraiment très bon merci", "oui c'était délicieux merci beaucoup"]}, {"who": "waiter", "fr": "Je vous mets un dessert, un café ?", "en": "Can I get you a dessert, a coffee?", "gloss": {"Je vous mets": "shall I put you down for"}}, {"who": "you", "fr": "Juste deux cafés, et l'addition, s'il vous plaît.", "en": "Just two coffees, and the bill, please.", "gloss": {"addition": "bill"}, "accept": ["juste deux cafés et l'addition s'il vous plaît", "deux cafés et l'addition s'il vous plaît", "juste deux cafés et l'addition", "deux cafés et puis l'addition s'il vous plaît", "pas de dessert juste deux cafés et l'addition", "deux cafés s'il vous plaît et l'addition"]}, {"who": "waiter", "fr": "Voilà, quarante et un euros cinquante. Vous payez comment ?", "en": "Here we are, forty-one euros fifty. How are you paying?", "gloss": {"quarante et un": "41"}}, {"who": "you", "fr": "Par Bancontact. Gardez la monnaie, merci. Bonne soirée !", "en": "By debit card. Keep the change, thanks. Have a good evening!", "gloss": {"Gardez la monnaie": "keep the change", "Bancontact": "Belgian debit-card system"}, "accept": ["par bancontact gardez la monnaie merci bonne soirée", "par bancontact merci bonne soirée", "par bancontact s'il vous plaît bonne soirée", "par bancontact gardez la monnaie merci", "on paie par bancontact merci bonne soirée", "par bancontact merci beaucoup bonne soirée"]}], "exercises": [{"id": "ex-restaurant-A2-01", "level": "A2", "format": "fr2en", "q": "l'entrée", "options": ["the starter", "the main course", "the dessert", "the drink"], "a": 0, "expl": "False friend: American English 'entrée' is the main course. In French it is always the first course."}, {"id": "ex-restaurant-A2-02", "level": "A2", "format": "en2fr", "q": "the full list of dishes", "options": ["la carte", "le menu", "la note", "la commande"], "a": 0, "expl": "« Le menu » is a fixed-price deal; « la carte » is everything they do."}, {"id": "ex-restaurant-A2-03", "level": "A2", "format": "cloze", "q": "Comme ___ , je vais prendre le waterzooi.", "options": ["plat", "dessert", "apéritif", "digestif"], "a": 0, "expl": "All four are masculine course words that fit after « comme ». A waterzooi is a main."}, {"id": "ex-restaurant-A2-04", "level": "A2", "format": "fr2en", "q": "les chicons", "options": ["chicory / endives (Belgium)", "chickpeas", "chicken pieces", "spring onions"], "a": 0, "expl": "France says « des endives ». « Les chicons au gratin » is a Belgian classic."}, {"id": "ex-restaurant-A2-05", "level": "A2", "format": "collocation", "q": "Le serveur demande la cuisson de votre steak. Que répondez-vous pour 'medium' ?", "options": ["À point", "Bien cuit", "Saignant", "Bleu"], "a": 0, "expl": "The scale runs bleu → saignant → à point → bien cuit. « À point » does not mean 'perfect'."}, {"id": "ex-restaurant-A2-06", "level": "A2", "format": "cloze", "q": "Vous pouvez m'___ du pain, s'il vous plaît ?", "options": ["apporter", "emporter", "amener", "rapporter"], "a": 0, "expl": "All four are grammatical infinitives here. « Apporter » brings a thing to you; « emporter » takes it away; « amener » is for people."}, {"id": "ex-restaurant-A2-07", "level": "A2", "format": "fr2en", "q": "une carafe d'eau", "options": ["a jug of tap water", "a bottle of mineral water", "a decanter of wine", "a large beer glass"], "a": 0, "expl": "Free by law in France, but not in Belgium — many Brussels places charge or refuse."}, {"id": "ex-restaurant-A2-08", "level": "A2", "format": "en2fr", "q": "the bill (in a restaurant)", "options": ["l'addition", "la note", "la facture", "le ticket"], "a": 0, "expl": "« L'addition » in a restaurant, « la note » in a hotel, « la facture » when you need it for expenses."}, {"id": "ex-restaurant-A2-09", "level": "A2", "format": "collocation", "q": "Vous voulez savoir si le plat est servi avec des frites. Que demandez-vous ?", "options": ["Est-ce qu'il y a des frites avec ?", "Est-ce qu'il y a des frites dedans ?", "Est-ce qu'il y a frites avec ?", "Est-ce que c'est avec de frites ?"], "a": 0, "expl": "« Avec » can stand at the end of the sentence, exactly like English 'with it'. « Dedans » would mean the chips are inside the stew."}, {"id": "ex-restaurant-A2-10", "level": "A2", "format": "cloze", "q": "Le service est ___ , mais on peut laisser un petit pourboire.", "options": ["compris", "gratuit", "interdit", "possible"], "a": 0, "expl": "All four are masculine adjectives that fit. In Belgium service is always « compris » in the printed price, which is why a tip is optional."}, {"id": "ex-restaurant-A2-11", "level": "A2", "format": "fr2en", "q": "les frites", "options": ["hot chips", "crisps in a packet", "fried onions", "roast potatoes"], "a": 0, "expl": "« Les chips » in French are crisps. Belgian frites are fried twice and served in « un cornet »."}, {"id": "ex-restaurant-A2-12", "level": "A2", "format": "en2fr", "q": "sparkling water", "options": ["l'eau pétillante", "l'eau plate", "l'eau du robinet", "l'eau minérale"], "a": 0, "expl": "« Plate ou pétillante ? » — still or sparkling. Spa Reine is plate, Spa Barisart pétillante."}, {"id": "ex-restaurant-A2-13", "level": "A2", "format": "cloze", "q": "Il me ___ une fourchette.", "options": ["manque", "faut", "reste", "plaît"], "a": 0, "expl": "All four work in impersonal « il me ___ » structures. « Il me manque » = I'm missing it; « il me faut » = I need it, which is also usable but less precise here."}, {"id": "ex-restaurant-A2-14", "level": "A2", "format": "fr2en", "q": "ça goûte bien", "options": ["it tastes good (Belgium)", "it smells good", "it looks good", "it is good value"], "a": 0, "expl": "Belgicism. In France you would say « c'est bon » or « c'est délicieux »; « ça goûte » would sound strange there."}]},
  "restaurant-B1": {"slug": "restaurant", "level": "B1", "title": "Au restaurant — terrasse complète et plat épuisé", "place": "Une brasserie de la place Fernand Cocq, Ixelles, Bruxelles", "register": "vous", "registerNote": "Vous with the waiter, as always. At B1 the skill is complaining without being unpleasant: « excusez-moi », a conditional (« vous pourriez… »), and a reason. Belgian service reacts very badly to a raised voice and very well to « désolé de vous embêter ». Tu stays for the friend you are eating with.", "vocab": [{"id": "fvc-restaurant-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "la salle", "en": "the dining room (inside)", "format": "fr2en", "options": ["the indoor dining area", "the kitchen", "the private room upstairs", "the entrance hall"], "a": 0, "trap": "la salle de bains, la salle de classe — the word alone in a restaurant means the room where guests sit", "expl": "« En salle ou en terrasse ? » is the first question of the evening. « Le service en salle » is the front-of-house team."}, {"id": "fvc-restaurant-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la banquette", "en": "the bench seat", "format": "en2fr", "options": ["la banquette", "la chaise", "le tabouret", "le fauteuil"], "a": 0, "trap": "le tabouret — a stool, at the bar rather than at a table", "expl": "Brussels brasseries are full of leather « banquettes » along the wall. « La banquette près de la fenêtre » is the good table."}, {"id": "fvc-restaurant-B1-03", "level": "B1", "pos": "noun", "gender": "m", "fr": "le comptoir", "en": "the bar counter", "format": "fr2en", "options": ["the counter you stand at", "the accountant", "the till", "the wine cellar"], "a": 0, "trap": "le comptable — the accountant; same root, very different job", "expl": "« Au comptoir » costs less than « en salle » in some cafés, a rule that survives in Belgium and France alike."}, {"id": "fvc-restaurant-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'attente", "en": "the wait", "format": "cloze", "q": "Il y a une ___ d'environ vingt minutes pour la terrasse.", "options": ["attente", "avance", "heure", "pause"], "a": 0, "trap": "heure — grammatically fine and about time, but it names a clock time rather than a delay", "expl": "All four are feminine nouns that fit. « Le temps d'attente » is the standard phrase; « une liste d'attente » is a waiting list."}, {"id": "fvc-restaurant-B1-05", "level": "B1", "pos": "adj", "fr": "épuisé", "en": "sold out / all gone", "format": "fr2en", "options": ["sold out", "expensive", "reheated", "spoiled"], "a": 0, "trap": "the same word means 'exhausted' about a person — « je suis épuisé »", "expl": "« Le plat du jour est épuisé. » The friendlier spoken version is « il n'y en a plus »."}, {"id": "fvc-restaurant-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la suggestion", "en": "the chef's special", "format": "fr2en", "options": ["the dish the kitchen suggests today", "a customer's complaint", "the wine pairing", "a booking request"], "a": 0, "trap": "learners hear 'suggestion' as an idea; on a menu « les suggestions » are extra dishes not printed on the carte", "expl": "« Les suggestions du chef » are usually on a blackboard and change daily. Often the best thing in the house."}, {"id": "fvc-restaurant-B1-07", "level": "B1", "pos": "noun", "gender": "f", "fr": "la spécialité", "en": "the house speciality", "format": "en2fr", "options": ["la spécialité", "la particularité", "la nouveauté", "la préférence"], "a": 0, "trap": "la particularité — a distinguishing feature, not a dish", "expl": "« C'est la spécialité de la maison. » « De la maison » = house-made, as in « fait maison »."}, {"id": "fvc-restaurant-B1-08", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'ardoise", "en": "the blackboard menu", "format": "fr2en", "options": ["the slate board the specials are written on", "the wine list", "the paper placemat", "the bill"], "a": 0, "trap": "« boire à l'ardoise » means to drink on credit, which is where learners meet the word", "expl": "Literally a slate. « C'est sur l'ardoise » = it's on the board — look up before you ask."}, {"id": "fvc-restaurant-B1-09", "level": "B1", "pos": "adj", "fr": "tiède", "en": "lukewarm", "format": "en2fr", "options": ["tiède", "chaud", "frais", "brûlant"], "a": 0, "trap": "frais — cool or fresh; « tiède » is the temperature nothing should be", "expl": "The scale: froid, frais, tiède, chaud, brûlant. « Mes frites sont tièdes » is a complaint any Belgian kitchen takes seriously."}, {"id": "fvc-restaurant-B1-10", "level": "B1", "pos": "verb", "fr": "réchauffer", "en": "to reheat", "format": "fr2en", "options": ["to warm something up again", "to heat for the first time", "to keep warm under a lamp", "to cool down"], "a": 0, "trap": "chauffer — to heat; the ré- means it has gone cold once already", "expl": "« Vous pourriez me les réchauffer ? » For chips, a good kitchen will make you fresh ones instead."}, {"id": "fvc-restaurant-B1-11", "level": "B1", "pos": "verb", "fr": "renvoyer", "en": "to send back", "format": "fr2en", "options": ["to send a dish back", "to send someone away for good", "to postpone", "to forward a message"], "a": 0, "trap": "renvoyer quelqu'un also means to sack someone — tone and context keep them apart", "expl": "« Je ne veux pas le renvoyer, mais... » softens the blow. Sending food back is rare in Belgium; be gentle about it."}, {"id": "fvc-restaurant-B1-12", "level": "B1", "pos": "verb", "fr": "se plaindre", "en": "to complain", "format": "en2fr", "options": ["se plaindre", "plaindre", "se plaire", "supplier"], "a": 0, "trap": "se plaire — to enjoy being somewhere: « je me plais à Bruxelles ». One letter apart from complaining.", "expl": "« Je ne voudrais pas me plaindre, mais... » is the standard opener. « Se plaindre de quelque chose »."}, {"id": "fvc-restaurant-B1-13", "level": "B1", "pos": "noun", "gender": "m", "fr": "le malentendu", "en": "the misunderstanding", "format": "fr2en", "options": ["the misunderstanding", "the bad hearing", "the argument", "the mistake in the bill"], "a": 0, "trap": "l'erreur — a plain mistake; « un malentendu » is nobody's fault", "expl": "« Il doit y avoir un malentendu » is the diplomatic way to say the order is wrong."}, {"id": "fvc-restaurant-B1-14", "level": "B1", "pos": "adj", "fr": "allergique", "en": "allergic", "format": "cloze", "q": "Je suis ___ aux fruits de mer, c'est grave pour moi.", "options": ["allergique", "sensible", "attentif", "habitué"], "a": 0, "trap": "sensible — a false friend meaning 'sensitive'; it fits the grammar and half the meaning, but it will not stop the kitchen using shellfish", "expl": "All four are adjectives taking « à ». If it matters medically, say « allergique » and say « c'est grave » — otherwise it may be treated as a preference."}, {"id": "fvc-restaurant-B1-15", "level": "B1", "pos": "adj", "fr": "sans gluten", "en": "gluten-free", "format": "en2fr", "options": ["sans gluten", "sans lactose", "sans sel", "sans sucre"], "a": 0, "trap": "sans lactose — dairy-free, the other one people ask about", "expl": "Invariable: « des plats sans gluten ». Belgian carbonnades contain « du pain d'épices », so they are not gluten-free."}, {"id": "fvc-restaurant-B1-16", "level": "B1", "pos": "adj", "fr": "végétarien", "en": "vegetarian", "format": "fr2en", "options": ["vegetarian", "vegan", "organic", "raw"], "a": 0, "trap": "végétalien / vegan — no animal products at all, one syllable away from végétarien", "expl": "« Vous avez un plat végétarien ? » Note the pair: végétarien (no meat) vs végétalien (nothing animal)."}, {"id": "fvc-restaurant-B1-17", "level": "B1", "pos": "noun", "gender": "f", "fr": "la portion", "en": "the portion", "format": "en2fr", "options": ["la portion", "la part", "la ration", "la tranche"], "a": 0, "trap": "la part — a share or a slice of a cake, used for splitting a bill too", "expl": "« Une petite portion, c'est possible ? » « Une part de tarte » is a slice of tart; « une tranche » is a slice of ham."}, {"id": "fvc-restaurant-B1-18", "level": "B1", "pos": "adj", "fr": "copieux", "en": "generous, filling", "format": "fr2en", "options": ["generous in quantity", "rich and creamy", "copied from another recipe", "shared between two"], "a": 0, "trap": "riche — rich in fat or flavour; « copieux » is only about how much is on the plate", "expl": "« C'est très copieux » is the warning that you will not need a starter. Feminine « copieuse »."}, {"id": "fvc-restaurant-B1-19", "level": "B1", "pos": "adj", "fr": "fade", "en": "bland, tasteless", "format": "en2fr", "options": ["fade", "doux", "léger", "amer"], "a": 0, "trap": "doux — mild or sweet, which is not the same as having no taste at all", "expl": "« C'est un peu fade » is a real but polite criticism. « Amer » is bitter, « léger » light."}, {"id": "fvc-restaurant-B1-20", "level": "B1", "pos": "adj", "fr": "relevé", "en": "well-seasoned, spicy", "format": "fr2en", "options": ["well-seasoned and a bit hot", "raised up on the plate", "reheated", "sour"], "a": 0, "trap": "épicé — spiced; « relevé » is closer to 'has a kick'", "expl": "« Une sauce bien relevée. » The same participle means 'picked up' or 'noted' elsewhere."}, {"id": "fvc-restaurant-B1-21", "level": "B1", "pos": "noun", "gender": "m", "fr": "le supplément", "en": "the extra charge", "format": "cloze", "q": "Les croquettes sont à deux euros de ___ .", "options": ["supplément", "réduction", "pourboire", "service"], "a": 0, "trap": "réduction — a masculine-free trap: it fits after « de » and is about money, but it takes two euros off rather than adding them", "expl": "« Avec supplément » is printed all over Belgian menus — usually for croquettes, extra sauce or a bigger portion of frites."}, {"id": "fvc-restaurant-B1-22", "level": "B1", "pos": "noun", "gender": "f", "fr": "la garniture", "en": "the side / accompaniment", "format": "fr2en", "options": ["what comes on the plate alongside the meat", "the decoration on a cake", "the sauce", "the herb garnish only"], "a": 0, "trap": "English 'garnish' — in French it is the whole side dish, not a sprig of parsley", "expl": "« Quelle garniture avec ? Frites, croquettes ou salade ? » is a question you will be asked most weeks."}, {"id": "fvc-restaurant-B1-23", "level": "B1", "pos": "noun", "gender": "f", "fr": "la mayonnaise", "en": "mayonnaise", "format": "collocation", "q": "Vous commandez des frites avec de la mayonnaise. Que dites-vous ?", "options": ["Avec une petite mayo, s'il vous plaît", "Avec de la mayonnaise dedans", "Avec la mayonnaise à part de la sauce", "Avec du mayo"], "a": 0, "trap": "« du mayo » — mayonnaise is feminine, so « de la mayo »", "note": "Belgian custom: frites come with a sauce, and mayonnaise is the default. In a fritkot it is served in a small tub and usually costs €0.80–1. Ketchup is for children.", "expl": "« Une petite mayo » is exactly what people say. The other Belgian sauces: andalouse, samouraï, brasil, pickles."}, {"id": "fvc-restaurant-B1-24", "level": "B1", "pos": "noun", "gender": "m", "fr": "le cornet", "en": "the paper cone of chips", "format": "fr2en", "options": ["the paper cone chips are served in", "the ice-cream cone only", "the musical horn", "the paper napkin"], "a": 0, "trap": "« un cornet de glace » is an ice-cream cone — same word, different filling", "note": "Belgian French. Ordering « un cornet de frites » at a fritkot is standard; in France you would ask for « une barquette » or « un cône de frites ».", "expl": "« Je vous refais un cornet » = I'll make you a fresh portion."}, {"id": "fvc-restaurant-B1-25", "level": "B1", "pos": "adv", "fr": "séparément", "en": "separately", "format": "en2fr", "options": ["séparément", "ensemble", "également", "directement"], "a": 0, "trap": "également — 'equally' in the sense of 'also', not 'in equal parts'", "expl": "« On peut payer séparément ? » Belgian brasseries will usually split a card payment without complaint; large groups are another matter."}, {"id": "fvc-restaurant-B1-26", "level": "B1", "pos": "verb", "fr": "arrondir", "en": "to round up (a sum)", "format": "fr2en", "options": ["to round a number up or down", "to give change", "to share out", "to add a service charge"], "a": 0, "trap": "ajouter — to add; arrondir moves the total to the nearest round figure", "expl": "« On arrondit à quarante ? » is how a tip is left in Belgium, since service is already included."}, {"id": "fvc-restaurant-B1-27", "level": "B1", "pos": "noun", "gender": "f", "fr": "la TVA", "en": "VAT", "format": "fr2en", "options": ["value added tax", "the service charge", "the tourist tax", "the tip"], "a": 0, "trap": "le service — also included in the price, but a completely different line", "note": "Belgian rates: 12% on restaurant food, 21% on drinks and most goods. Menu prices are always shown TVA comprise.", "expl": "Pronounced « té-vé-a ». « TVA comprise » = VAT included."}, {"id": "fvc-restaurant-B1-28", "level": "B1", "pos": "noun", "gender": "m", "fr": "le couvert", "en": "the place setting / cover", "format": "fr2en", "options": ["one person's place setting", "the lid of a dish", "the bill", "the cloakroom"], "a": 0, "trap": "le couvercle — the lid; « le couvert » is the knife-fork-plate set", "expl": "« Mettre le couvert » = to lay the table. « Un couvert supplémentaire » = an extra place setting."}, {"id": "fvc-restaurant-B1-29", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'ambiance", "en": "the atmosphere", "format": "en2fr", "options": ["l'ambiance", "l'ambition", "l'assiette", "l'attitude"], "a": 0, "trap": "l'ambition — the lookalike that shares five letters and no meaning", "expl": "« Il y a une bonne ambiance ici. » Belgians also use « c'est convivial » and, from Dutch, « c'est gezellig » in Flanders."}, {"id": "fvc-restaurant-B1-30", "level": "B1", "pos": "adj", "fr": "bruyant", "en": "noisy", "format": "cloze", "q": "C'est un peu ___ ici, on pourrait changer de table ?", "options": ["bruyant", "sombre", "étroit", "calme"], "a": 0, "trap": "calme — an adjective that fits perfectly and says the opposite of what would make you move", "expl": "All four are masculine adjectives that fit. « Changer de table » takes no article after « de »."}, {"id": "fvc-restaurant-B1-31", "level": "B1", "pos": "verb", "fr": "déranger", "en": "to disturb / to bother", "format": "fr2en", "options": ["to bother someone", "to tidy up", "to rearrange furniture", "to annoy on purpose"], "a": 0, "trap": "ranger — to tidy away; « déranger » is the opposite in form but not in meaning", "expl": "« Désolé de vous déranger » opens any request to a busy waiter. « Ça ne me dérange pas » = I don't mind."}, {"id": "fvc-restaurant-B1-32", "level": "B1", "pos": "verb", "fr": "prévenir", "en": "to let someone know in advance", "format": "en2fr", "options": ["prévenir", "prévoir", "avertir", "informer"], "a": 0, "trap": "prévoir — to plan or foresee, one letter apart and constantly confused", "expl": "« Je vous préviens tout de suite : il n'y a plus de plat du jour. » Also « prévenir » = to prevent, in medicine."}, {"id": "fvc-restaurant-B1-33", "level": "B1", "pos": "verb", "fr": "mijoter", "en": "to simmer slowly", "format": "fr2en", "options": ["to cook gently for a long time", "to fry quickly", "to marinate overnight", "to keep warm"], "a": 0, "trap": "mariner — to marinate, the other slow preparation", "expl": "« Les carbonnades mijotent depuis ce matin. » Figuratively: « qu'est-ce que tu mijotes ? » = what are you up to?"}, {"id": "fvc-restaurant-B1-34", "level": "B1", "pos": "verb", "fr": "conseiller", "en": "to recommend", "format": "cloze", "q": "Qu'est-ce que vous nous ___ , comme plat ?", "options": ["conseillez", "commandez", "servez", "préparez"], "a": 0, "trap": "servez — grammatically perfect, but asking what he serves you gets a list, not an opinion", "expl": "All four are correct vous-forms. « Conseiller quelque chose à quelqu'un » — that is why « nous » comes before the verb."}, {"id": "fvc-restaurant-B1-35", "level": "B1", "pos": "verb", "fr": "se décider", "en": "to make up one's mind", "format": "fr2en", "options": ["to make up your mind", "to decide someone else's fate", "to change your mind", "to be decisive by nature"], "a": 0, "trap": "décider — to decide something; « se décider » is the internal struggle before you do", "expl": "« Vous vous êtes décidés ? » is the waiter's polite return. Answer « oui, on a choisi »."}, {"id": "fvc-restaurant-B1-36", "level": "B1", "pos": "verb", "fr": "se régaler", "en": "to really enjoy a meal", "format": "en2fr", "options": ["se régaler", "se rassasier", "se resservir", "se réjouir"], "a": 0, "trap": "se réjouir — to be delighted about something in general, not about food on your plate", "expl": "« On s'est régalés » is the warmest compliment you can pay a Belgian kitchen. Note the agreement: régalés, régalées."}, {"id": "fvc-restaurant-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "la brasserie", "en": "the brasserie (all-day restaurant)", "format": "fr2en", "options": ["a café-restaurant serving food all day", "a beer factory only", "a fast-food outlet", "a wine bar"], "a": 0, "trap": "« la brasserie » does also mean a brewery — Brasserie Cantillon in Anderlecht brews, it does not serve lunch", "expl": "The Brussels brasserie serves from noon to late, no booking needed on a weekday, paper on the tables."}, {"id": "fvc-restaurant-B1-38", "level": "B1", "pos": "noun", "gender": "m", "fr": "le fritkot", "en": "the chip stand (Belgium)", "format": "fr2en", "options": ["the wooden chip stand on a square", "a small flat above a shop", "a food truck selling burgers", "a corner shop"], "a": 0, "trap": "« un kot » on its own is a student room in Belgium — same second half, entirely different building", "note": "Belgian French, from Flemish. France says « une baraque à frites ». The polite written form is « une friterie ». Places Flagey and Jourdan have famous ones.", "expl": "« On va au fritkot ? » A cornet with mayo runs about €4.50 in 2026."}, {"id": "fvc-restaurant-B1-39", "level": "B1", "pos": "noun", "gender": "m", "fr": "le tarif", "en": "the rate / price list", "format": "en2fr", "options": ["le tarif", "le prix", "le montant", "le coût"], "a": 0, "trap": "le montant — the total amount of a particular bill, not the published rate", "expl": "« Le tarif du midi » is the lunchtime rate. « Le montant » is what you owe today."}, {"id": "fvc-restaurant-B1-40", "level": "B1", "pos": "noun", "gender": "f", "fr": "la carte des vins", "en": "the wine list", "format": "fr2en", "options": ["the wine list", "the wine map of a region", "the vineyard's business card", "the sommelier's badge"], "a": 0, "trap": "learners translate 'carte' as map and expect a map of vineyards", "expl": "« Je peux voir la carte des vins ? » In a Belgian brasserie the beer list is usually longer and more interesting."}, {"id": "fvc-restaurant-B1-41", "level": "B1", "pos": "verb", "fr": "remplacer", "en": "to replace / swap", "format": "cloze", "q": "Est-ce qu'on peut ___ les frites par une salade ?", "options": ["remplacer", "changer", "échanger", "enlever"], "a": 0, "trap": "changer — grammatical, but « changer les frites » sounds like changing them for identical ones; the pattern « remplacer A par B » is the precise one", "expl": "All four are infinitives that fit. « Remplacer X par Y » — the preposition is « par », not « avec »."}, {"id": "fvc-restaurant-B1-42", "level": "B1", "pos": "noun", "gender": "f", "fr": "la dame blanche", "en": "vanilla ice cream with hot chocolate sauce", "format": "fr2en", "options": ["vanilla ice cream with hot chocolate sauce", "a white wine cocktail", "a meringue dessert", "a cream cheese starter"], "a": 0, "trap": "learners expect something to do with a white lady or a ghost story", "note": "Belgian dessert, on almost every brasserie menu, about €7–9. Ask for it in France and you may get a puzzled look or a different dish entirely.", "expl": "The hot chocolate arrives in a little jug so you pour it yourself. Its sibling is « une coupe brésilienne »."}, {"id": "fvc-restaurant-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "un américain préparé", "en": "seasoned raw minced beef (Belgium)", "format": "fr2en", "options": ["seasoned raw minced beef, like steak tartare", "a burger with cheese and bacon", "a large filter coffee", "an imported cut of beef"], "a": 0, "trap": "the name suggests a burger, and « un américain » is exactly what it is not", "note": "Belgian French. In France the same thing is « un steak tartare ». Belgians eat it cold with frites, or in a « sandwich américain » from the bakery.", "expl": "« Un américain frites » is a standard brasserie order. If you do not eat raw meat, this is the one to avoid."}, {"id": "fvc-restaurant-B1-44", "level": "B1", "pos": "expr", "fr": "chacun sa part", "en": "each pays their share", "format": "collocation", "q": "Vous voulez payer moitié-moitié. Quelle phrase est correcte ?", "options": ["On paie chacun sa part", "On paie chacun sa partie", "On paie chacun son part", "On paie chacun de sa part"], "a": 0, "trap": "« sa partie » = his part of a game or a piece of music, not his share of a bill", "expl": "« Chacun » is masculine but the possessive agrees with « part » (feminine): chacun sa part. Also usable: « on partage » or « séparément »."}, {"id": "fvc-restaurant-B1-45", "level": "B1", "pos": "expr", "fr": "il n'y en a plus", "en": "there's none left", "format": "cloze", "q": "Désolé, du waterzooi, il n'y ___ a plus.", "options": ["en", "y", "le", "lui"], "a": 0, "trap": "y — it is already in « il y a »; the pronoun replacing « du waterzooi » must be « en »", "expl": "All four are pronouns, but only « en » replaces a partitive (du / de la / des). Word order in this frozen phrase: il n'y en a plus."}], "phrases": [{"id": "ph-restaurant-B1-01", "fr": "Est-ce qu'il y aurait moyen d'avoir une table en terrasse ?", "en": "Would there be any way of getting a table outside?", "note": "« Il y aurait moyen de » is very Belgian and very polite — softer than « c'est possible ? ». France prefers « serait-il possible de »."}, {"id": "ph-restaurant-B1-02", "fr": "On n'est pas pressés, on peut attendre vingt minutes.", "en": "We're not in a hurry, we can wait twenty minutes.", "note": "« Être pressé » = to be in a rush. Agreement: on n'est pas pressés (two people)."}, {"id": "ph-restaurant-B1-03", "fr": "Qu'est-ce que vous nous conseillez, comme plat ?", "en": "What would you recommend as a main?", "note": "Asking for a recommendation flatters the house and usually gets you the freshest dish. « Comme plat » = as a main."}, {"id": "ph-restaurant-B1-04", "fr": "Le plat du jour est épuisé ? Alors je vais me laisser tenter par les carbonnades.", "en": "The dish of the day is finished? Then I'll be tempted by the carbonnades.", "note": "« Se laisser tenter par » is a fixed, slightly playful way of choosing. Very natural in a brasserie."}, {"id": "ph-restaurant-B1-05", "fr": "Est-ce qu'il y a du gluten dans la sauce ?", "en": "Is there gluten in the sauce?", "note": "Worth asking about carbonnades: the traditional recipe thickens the sauce with « du pain d'épices »."}, {"id": "ph-restaurant-B1-06", "fr": "Je suis allergique aux fruits de mer, c'est vraiment important.", "en": "I'm allergic to seafood, it really matters.", "note": "Add « c'est vraiment important » or « c'est grave » — otherwise an allergy can be heard as a preference."}, {"id": "ph-restaurant-B1-07", "fr": "Est-ce qu'on peut remplacer les frites par une salade ?", "en": "Could we swap the chips for a salad?", "note": "« Remplacer A par B » — the preposition is par. Expect « avec un petit supplément »."}, {"id": "ph-restaurant-B1-08", "fr": "Désolé de vous déranger, mais les frites sont tièdes.", "en": "Sorry to bother you, but the chips are lukewarm.", "note": "Open with the apology, state the fact flatly, and stop. That is the whole recipe for complaining successfully in Belgium."}, {"id": "ph-restaurant-B1-09", "fr": "Vous pourriez me les réchauffer, s'il vous plaît ?", "en": "Could you warm them up for me, please?", "note": "Conditional + double pronoun (me les). A good kitchen will bring a fresh cornet rather than reheat."}, {"id": "ph-restaurant-B1-10", "fr": "Ce n'est pas grave, ça arrive.", "en": "Never mind, these things happen.", "note": "Defuses the moment once they have apologised. « Ça arrive » = it happens."}, {"id": "ph-restaurant-B1-11", "fr": "Je crois qu'il y a un malentendu : j'avais commandé le waterzooi.", "en": "I think there's been a misunderstanding: I'd ordered the waterzooi.", "note": "Plus-que-parfait « j'avais commandé » places your order before the mistake. « Un malentendu » blames nobody."}, {"id": "ph-restaurant-B1-12", "fr": "C'est très copieux, on va partager une entrée.", "en": "It's very filling, we'll share a starter.", "note": "Perfectly normal in a brasserie. « Partager » + noun, no preposition."}, {"id": "ph-restaurant-B1-13", "fr": "La sauce est un peu fade à mon goût.", "en": "The sauce is a bit bland for my taste.", "note": "« À mon goût » turns a criticism into an opinion, which is the difference between a comment and a complaint."}, {"id": "ph-restaurant-B1-14", "fr": "On peut avoir un couvert supplémentaire, s'il vous plaît ?", "en": "Could we have an extra place setting, please?", "note": "« Un couvert » is one full set: plate, knife, fork. Useful when someone joins you."}, {"id": "ph-restaurant-B1-15", "fr": "C'est un peu bruyant ici, on pourrait changer de table ?", "en": "It's a bit noisy here, could we move table?", "note": "« Changer de + noun » takes no article. Ask before the food arrives, not after."}, {"id": "ph-restaurant-B1-16", "fr": "On s'est vraiment régalés, félicitations au chef.", "en": "We really enjoyed it, our compliments to the chef.", "note": "« Se régaler » agrees in the passé composé: régalés. « Félicitations au chef » will actually be passed on."}, {"id": "ph-restaurant-B1-17", "fr": "Est-ce qu'on peut payer séparément ?", "en": "Can we pay separately?", "note": "Two card payments are normally fine in Belgium. For a big group, warn them at the start of the meal."}, {"id": "ph-restaurant-B1-18", "fr": "Ça fait septante-huit euros en tout ? On arrondit à quatre-vingts.", "en": "That's seventy-eight euros in total? We'll round it up to eighty.", "note": "Belgian French: septante = 70. Note that 80 stays « quatre-vingts » in Belgium, unlike Switzerland's « huitante ». Rounding up is how you tip."}, {"id": "ph-restaurant-B1-19", "fr": "Vous auriez une facture au nom de la société ?", "en": "Could we have an invoice in the company's name?", "note": "« Vous auriez » (conditional) is softer than « vous avez ». Needed if you are claiming the meal back at work."}, {"id": "ph-restaurant-B1-20", "fr": "Merci pour tout, on reviendra avec plaisir. Bonne soirée !", "en": "Thanks for everything, we'll be back with pleasure. Have a good evening!", "note": "« On reviendra » (future) is the standard leaving compliment, and much appreciated in a neighbourhood brasserie."}], "dialogue": [{"who": "waiter", "fr": "Bonsoir ! Vous êtes deux ? J'ai une table à l'intérieur, la terrasse est complète.", "en": "Good evening! Two of you? I have a table inside, the terrace is full.", "gloss": {"complète": "full / fully taken"}}, {"who": "you", "fr": "Bonsoir. Il n'y aurait pas moyen d'attendre une table en terrasse ? On n'est pas pressés.", "en": "Good evening. Would there be any way of waiting for a table outside? We're not in a hurry.", "gloss": {"moyen": "way / means", "pressés": "in a hurry"}, "accept": ["bonsoir il n'y aurait pas moyen d'attendre une table en terrasse on n'est pas pressés", "il n'y aurait pas moyen d'attendre une table en terrasse", "bonsoir est-ce qu'on peut attendre une table en terrasse", "on préférerait la terrasse on n'est pas pressés", "est-ce qu'on pourrait attendre une place en terrasse", "bonsoir on peut attendre une table en terrasse on n'est pas pressés", "serait-il possible d'attendre une table en terrasse"]}, {"who": "waiter", "fr": "Je peux vous noter, mais il faudrait compter vingt minutes d'attente. Sinon, il y a la banquette près de la fenêtre.", "en": "I can put you down, but you'd have to allow twenty minutes' wait. Otherwise there's the bench seat by the window.", "gloss": {"il faudrait compter": "you'd have to allow", "attente": "wait", "banquette": "bench seat"}}, {"who": "you", "fr": "On va prendre la banquette, ce sera plus simple.", "en": "We'll take the bench seat, it'll be simpler.", "gloss": {"ce sera": "it will be (future)"}, "accept": ["on va prendre la banquette ce sera plus simple", "on va prendre la banquette", "on prend la banquette ce sera plus simple", "d'accord on va prendre la banquette", "alors on va prendre la banquette près de la fenêtre", "on préfère la banquette ce sera plus simple"]}, {"who": "waiter", "fr": "Parfait, installez-vous. Je vous préviens tout de suite : le plat du jour est épuisé.", "en": "Perfect, make yourselves comfortable. I'll tell you straight away: the dish of the day is finished.", "gloss": {"préviens": "warn / let you know", "épuisé": "sold out"}}, {"who": "you", "fr": "Ah, dommage. Qu'est-ce que vous nous conseillez, alors ?", "en": "Ah, that's a shame. What would you recommend then?", "gloss": {"dommage": "a shame", "conseillez": "recommend"}, "accept": ["ah dommage qu'est-ce que vous nous conseillez alors", "qu'est-ce que vous nous conseillez", "dommage qu'est-ce que vous nous conseillez alors", "qu'est-ce que vous nous conseillez alors", "et qu'est-ce que vous nous recommandez", "ah dommage vous nous conseillez quoi"]}, {"who": "waiter", "fr": "Le waterzooi est notre spécialité, et les carbonnades mijotent depuis ce matin.", "en": "The waterzooi is our speciality, and the carbonnades have been simmering since this morning.", "gloss": {"spécialité": "house speciality", "mijotent": "are simmering"}}, {"who": "you", "fr": "Je vais me laisser tenter par les carbonnades. Est-ce qu'il y a du gluten dans la sauce ?", "en": "I'll let myself be tempted by the carbonnades. Is there gluten in the sauce?", "gloss": {"me laisser tenter": "let myself be tempted", "gluten": "gluten"}, "accept": ["je vais me laisser tenter par les carbonnades est-ce qu'il y a du gluten dans la sauce", "je vais prendre les carbonnades est-ce qu'il y a du gluten dans la sauce", "je vais me laisser tenter par les carbonnades", "alors les carbonnades est-ce qu'il y a du gluten dans la sauce", "je prends les carbonnades est-ce qu'il y a du gluten dedans", "je vais prendre les carbonnades y a-t-il du gluten dans la sauce"]}, {"who": "waiter", "fr": "Alors là, il y a du pain d'épices dedans, donc oui. Je peux demander en cuisine de le remplacer.", "en": "Ah, there's gingerbread in it, so yes. I can ask the kitchen to replace it.", "gloss": {"pain d'épices": "gingerbread", "remplacer": "to replace"}}, {"who": "you", "fr": "Ce n'est pas grave, ce n'est pas une allergie. Je les prends comme elles sont.", "en": "It's fine, it's not an allergy. I'll have them as they are.", "gloss": {"allergie": "allergy", "comme elles sont": "as they are"}, "accept": ["ce n'est pas grave ce n'est pas une allergie je les prends comme elles sont", "ce n'est pas grave ce n'est pas une allergie", "pas de souci ce n'est pas une allergie je les prends comme elles sont", "ce n'est pas une allergie je les prends comme elles sont", "ce n'est pas grave je les prends comme elles sont", "pas de problème ce n'est pas une allergie"]}, {"who": "waiter", "fr": "Très bien, je note. ... Et voilà, deux carbonnades, bon appétit !", "en": "Very good, I'll note that down. ... Here we are, two carbonnades, enjoy!", "gloss": {"je note": "I'll write it down"}}, {"who": "you", "fr": "Merci. Excusez-moi, désolé de vous déranger, mais les frites sont un peu tièdes.", "en": "Thank you. Excuse me, sorry to bother you, but the chips are a bit lukewarm.", "gloss": {"déranger": "to bother", "tièdes": "lukewarm"}, "accept": ["merci excusez-moi désolé de vous déranger mais les frites sont un peu tièdes", "excusez-moi désolé de vous déranger mais les frites sont un peu tièdes", "excusez-moi les frites sont un peu tièdes", "désolé de vous déranger mais les frites sont tièdes", "excusez-moi mais les frites sont un peu tièdes", "pardon les frites sont un peu tièdes"]}, {"who": "waiter", "fr": "Ah, je suis désolé. Je vous en refais un cornet tout de suite.", "en": "Oh, I'm sorry. I'll make you a fresh portion right away.", "gloss": {"cornet": "paper cone of chips (Belgium)", "tout de suite": "right away"}}, {"who": "you", "fr": "C'est gentil, merci beaucoup. Ce n'est pas grave, ça arrive.", "en": "That's kind, thank you very much. Never mind, these things happen.", "gloss": {"ça arrive": "these things happen"}, "accept": ["c'est gentil merci beaucoup ce n'est pas grave ça arrive", "c'est gentil merci beaucoup", "merci beaucoup ce n'est pas grave ça arrive", "merci c'est gentil ça arrive", "c'est très gentil merci", "merci beaucoup c'est gentil"]}, {"who": "waiter", "fr": "Voilà, elles sortent de la friteuse. Ça ira comme ça ?", "en": "There you go, straight out of the fryer. Will that be all right?", "gloss": {"friteuse": "deep fryer", "Ça ira": "will that be OK"}}, {"who": "you", "fr": "Parfait, c'est bien mieux comme ça. Merci.", "en": "Perfect, that's much better. Thanks.", "gloss": {"bien mieux": "much better"}, "accept": ["parfait c'est bien mieux comme ça merci", "parfait c'est bien mieux merci", "c'est bien mieux comme ça merci", "oui c'est parfait merci beaucoup", "parfait merci beaucoup", "c'est nickel merci"]}, {"who": "waiter", "fr": "Je vous apporte la carte des desserts ? On fait une dame blanche maison.", "en": "Shall I bring you the dessert menu? We do a house dame blanche.", "gloss": {"dame blanche": "vanilla ice cream with hot chocolate sauce (Belgian dessert)", "maison": "house-made"}}, {"who": "you", "fr": "Volontiers, une dame blanche. Et est-ce qu'on peut payer séparément ?", "en": "Gladly, one dame blanche. And can we pay separately?", "gloss": {"Volontiers": "gladly", "séparément": "separately"}, "accept": ["volontiers une dame blanche et est-ce qu'on peut payer séparément", "une dame blanche et est-ce qu'on peut payer séparément", "volontiers une dame blanche", "oui une dame blanche et on peut payer séparément", "je veux bien une dame blanche et est-ce qu'on peut payer séparément", "avec plaisir une dame blanche et on peut payer chacun sa part"]}, {"who": "waiter", "fr": "Bien sûr. Ça fait septante-huit euros en tout, donc trente-neuf chacun.", "en": "Of course. That's seventy-eight euros in total, so thirty-nine each.", "gloss": {"septante-huit": "78 (Belgium; France: soixante-dix-huit)", "chacun": "each"}}, {"who": "you", "fr": "Parfait. Chacun par Bancontact, alors. On arrondit à quarante. Merci, c'était très bon !", "en": "Perfect. Each by debit card then. We'll round it up to forty. Thanks, it was very good!", "gloss": {"arrondit": "round up", "Bancontact": "Belgian debit-card system"}, "accept": ["parfait chacun par bancontact alors on arrondit à quarante merci c'était très bon", "chacun par bancontact on arrondit à quarante merci", "parfait chacun par bancontact merci c'était très bon", "on paie chacun par bancontact on arrondit à quarante", "chacun par bancontact alors merci c'était très bon", "parfait on arrondit à quarante chacun merci"]}], "exercises": [{"id": "ex-restaurant-B1-01", "level": "B1", "format": "fr2en", "q": "Le plat du jour est épuisé.", "options": ["The dish of the day has sold out.", "The dish of the day is very filling.", "The dish of the day has been reheated.", "The dish of the day is finished cooking."], "a": 0, "expl": "« Épuisé » = used up. Of a person it means exhausted."}, {"id": "ex-restaurant-B1-02", "level": "B1", "format": "cloze", "q": "Est-ce qu'on peut remplacer les frites ___ une salade ?", "options": ["par", "avec", "pour", "de"], "a": 0, "expl": "All four prepositions are common after verbs, but the pattern is fixed: remplacer A par B."}, {"id": "ex-restaurant-B1-03", "level": "B1", "format": "en2fr", "q": "lukewarm", "options": ["tiède", "frais", "brûlant", "doux"], "a": 0, "expl": "froid → frais → tiède → chaud → brûlant."}, {"id": "ex-restaurant-B1-04", "level": "B1", "format": "collocation", "q": "Comment se plaindre poliment de frites froides ?", "options": ["Désolé de vous déranger, mais les frites sont tièdes", "Les frites sont froides, c'est inacceptable", "Vous m'avez donné des frites froides", "Il faut me changer ces frites"], "a": 0, "expl": "Apology first, fact second, no accusation. That is what gets a fresh cornet in Belgium."}, {"id": "ex-restaurant-B1-05", "level": "B1", "format": "fr2en", "q": "la garniture", "options": ["what comes with the main course", "the parsley on top", "the sauce", "the table decoration"], "a": 0, "expl": "« Quelle garniture ? Frites, croquettes ou salade ? »"}, {"id": "ex-restaurant-B1-06", "level": "B1", "format": "cloze", "q": "Je crois qu'il y a un malentendu : j'___ commandé le waterzooi.", "options": ["avais", "ai", "aurais", "avait"], "a": 0, "expl": "Your order came before the mistake, so the plus-que-parfait « j'avais commandé » is the precise tense. « J'ai commandé » is not wrong, but it flattens the sequence."}, {"id": "ex-restaurant-B1-07", "level": "B1", "format": "fr2en", "q": "une dame blanche", "options": ["vanilla ice cream with hot chocolate sauce", "a white wine spritzer", "a meringue with cream", "a soft goat's cheese"], "a": 0, "expl": "Belgian dessert on every brasserie menu, €7–9. Not standard in France."}, {"id": "ex-restaurant-B1-08", "level": "B1", "format": "en2fr", "q": "to make up your mind", "options": ["se décider", "décider", "se plaindre", "se régaler"], "a": 0, "expl": "« Vous vous êtes décidés ? » is what the waiter asks when he comes back."}, {"id": "ex-restaurant-B1-09", "level": "B1", "format": "cloze", "q": "Vous pourriez ___ réchauffer, s'il vous plaît ?", "options": ["me les", "les me", "me leur", "leur les"], "a": 0, "expl": "Two object pronouns before the infinitive, and the order is fixed: me/te/nous/vous come before le/la/les. So « me les réchauffer »."}, {"id": "ex-restaurant-B1-10", "level": "B1", "format": "fr2en", "q": "un américain préparé", "options": ["seasoned raw minced beef (Belgium)", "a cheeseburger", "an American-style filter coffee", "an imported steak"], "a": 0, "expl": "France calls it « un steak tartare ». Belgians also eat it in a sandwich from the bakery."}, {"id": "ex-restaurant-B1-11", "level": "B1", "format": "en2fr", "q": "the extra charge on a menu", "options": ["le supplément", "la réduction", "le service", "le pourboire"], "a": 0, "expl": "« Les croquettes sont à deux euros de supplément. » « Le service » is already inside the price in Belgium."}, {"id": "ex-restaurant-B1-12", "level": "B1", "format": "cloze", "q": "Il ___ compter vingt minutes d'attente.", "options": ["faudrait", "faut", "fallait", "faudra"], "a": 0, "expl": "All four are real forms of falloir. The conditional « il faudrait » is what a waiter uses to soften bad news; « il faut » would sound like an order."}, {"id": "ex-restaurant-B1-13", "level": "B1", "format": "fr2en", "q": "le fritkot", "options": ["the wooden chip stand (Belgium)", "a student room", "a food truck selling burgers", "a fried-chicken shop"], "a": 0, "expl": "France: « une baraque à frites ». Written politely, « une friterie »."}, {"id": "ex-restaurant-B1-14", "level": "B1", "format": "en2fr", "q": "to really enjoy a meal", "options": ["se régaler", "se réjouir", "se rassasier", "se resservir"], "a": 0, "expl": "« On s'est régalés » — the best compliment you can leave with."}]},
  "bar-A2": {"slug": "bar", "level": "A2", "title": "Commander au bar", "place": "Café Belga, place Flagey, Ixelles, Bruxelles", "register": "tu", "registerNote": "Tu, because this is a young neighbourhood café and everyone here is roughly your age: your friends obviously, and the barman, who will open with « salut, vous prenez quoi ? » and expect « s'il te plaît » back. Two rules keep you safe: mirror whatever the other person uses first, and switch to vous with anyone visibly older, with the patron of a traditional estaminet, or in a hotel bar. If in doubt, « on se tutoie ? » settles it in three words.", "vocab": [{"id": "fvc-bar-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la bière", "en": "the beer", "format": "fr2en", "options": ["the beer", "the cider", "the barrel", "the pint glass"], "a": 0, "trap": "le cidre — the other fermented drink, and « la bière » looks nothing like English 'beer' to a beginner's eye", "expl": "Belgium has around 1,500 beers. « Une bière » on its own gets you whatever is on tap, usually a Jupiler."}, {"id": "fvc-bar-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pinte", "en": "a 25cl draught lager (Belgium)", "format": "fr2en", "options": ["a small draught lager, 25cl", "a British pint, 57cl", "a half-litre glass", "a bottle of lager"], "a": 0, "trap": "English 'pint' — a Belgian pinte is a small glass, less than half the British measure", "note": "Belgian French. In France you ask for « un demi » (25cl) and « une pinte » there means 50cl. Order « une pinte » in Brussels and you get a small Jupiler.", "expl": "« Deux pintes, s'il te plaît » is the most-used sentence in any Belgian café. About €3.00–3.50 in Ixelles."}, {"id": "fvc-bar-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "le demi", "en": "a 25cl beer (France)", "format": "fr2en", "options": ["a 25cl glass of draught beer in France", "half a litre of beer", "half a bottle of wine", "a half measure of spirits"], "a": 0, "trap": "« demi » means half, so learners expect half a litre — it is in fact half of an old-fashioned litre glass", "note": "This is the French word. Say « un demi » in Brussels and you will be understood but marked as coming from France; Belgians say « une pinte ».", "expl": "Same quantity as a Belgian pinte, different word. Useful for a weekend in Lille or Paris."}, {"id": "fvc-bar-A2-04", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pression", "en": "draught (beer)", "format": "en2fr", "options": ["la pression", "la bouteille", "la canette", "la mousse"], "a": 0, "trap": "la mousse — the foam on top, and slang for a beer, but not the way it is served", "expl": "« Une bière à la pression » or just « une pression ». The opposite is « en bouteille »."}, {"id": "fvc-bar-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la trappiste", "en": "a Trappist beer", "format": "fr2en", "options": ["a beer brewed by monks", "a beer flavoured with cherries", "a very old beer", "a wheat beer"], "a": 0, "trap": "la trappe — a trapdoor; the beer is named after the Trappist order, not a trap", "note": "Belgian speciality. Six of the world's Trappist breweries are Belgian: Chimay, Orval, Rochefort, Westmalle, Westvleteren, Achel. Around €4.50 a glass in a Brussels café.", "expl": "Strong, 6–10%. They arrive in their own branded glass — Belgians take this seriously."}, {"id": "fvc-bar-A2-06", "level": "A2", "pos": "noun", "gender": "f", "fr": "la gueuze", "en": "a sour Brussels lambic blend", "format": "fr2en", "options": ["a sour beer blended from young and old lambics", "a sweet cherry beer", "a strong blond abbey beer", "a dark stout"], "a": 0, "trap": "la kriek — also a lambic, but sweetened with cherries; gueuze is the dry, sour one", "note": "Brussels' own beer, fermented with wild yeasts from the Senne valley. Cantillon in Anderlecht still brews it; the museum tour ends with a glass.", "expl": "Sometimes spelt « geuze ». Bone dry, very sour, closer to cider than to lager."}, {"id": "fvc-bar-A2-07", "level": "A2", "pos": "noun", "gender": "f", "fr": "la kriek", "en": "a cherry beer", "format": "en2fr", "options": ["la kriek", "la gueuze", "la blanche", "la brune"], "a": 0, "trap": "la gueuze — same lambic base, no cherries, and sour rather than sweet", "note": "Belgian, from the Flemish word for cherry. Traditional ones (Cantillon, Boon) are sour; supermarket brands like Belle-Vue are sweet.", "expl": "« Une kriek » is what people order when they say they do not like beer."}, {"id": "fvc-bar-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la blanche", "en": "a wheat beer", "format": "fr2en", "options": ["a cloudy wheat beer", "a white wine", "a clear spirit", "a light lager"], "a": 0, "trap": "le blanc — « un blanc » in a café is a glass of white wine, not a beer", "expl": "Hoegaarden is the original. Served cloudy, often with a slice of lemon and around 5%."}, {"id": "fvc-bar-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la canette", "en": "the can (of drink)", "format": "en2fr", "options": ["la canette", "la bouteille", "la carafe", "la boîte"], "a": 0, "trap": "la boîte — a box or tin, and also a nightclub in slang: « on va en boîte ? »", "expl": "« Une canette de 33 cl ». Cafés serve bottles and draught; cans belong to the Delhaize and the park."}, {"id": "fvc-bar-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "le sous-bock", "en": "the beer mat", "format": "fr2en", "options": ["the cardboard beer mat", "the wooden bar top", "the coaster tray", "the bar bill kept on paper"], "a": 0, "trap": "in some cafés the barman does keep your tab in pencil on the sous-bock — but the word means the mat itself", "expl": "Literally 'under the bock'. Belgian cafés give a fresh one with each beer, printed with the brewery's name."}, {"id": "fvc-bar-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bar", "en": "the bar (counter)", "format": "cloze", "q": "On commande au ___ , il n'y a pas de service en terrasse.", "options": ["bar", "café", "coin", "fond"], "a": 0, "trap": "café — masculine and grammatical, but « commander au café » says nothing about where you stand", "expl": "All four are masculine nouns that fit after « au ». In many Brussels cafés you order and pay at the bar and carry the glasses out yourself."}, {"id": "fvc-bar-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le barman", "en": "the barman", "format": "en2fr", "options": ["le barman", "le serveur", "le patron", "le client"], "a": 0, "trap": "le serveur — the one who comes to your table; the barman stays behind the counter", "expl": "Feminine « la barmaid » or « la serveuse ». Get his attention with a look and « salut ! », never by clicking your fingers."}, {"id": "fvc-bar-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "le patron", "en": "the owner / boss", "format": "fr2en", "options": ["the owner of the café", "the customer", "the regular", "the pattern or template"], "a": 0, "trap": "English 'patron' means a customer — in French it is the owner. The customer is « le client ».", "expl": "« C'est le patron qui offre » = it's on the house. Say vous to the patron of an old estaminet even if you tutoie the young staff."}, {"id": "fvc-bar-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tournée", "en": "the round (of drinks)", "format": "fr2en", "options": ["the round of drinks", "the tour of a city", "the turn you take", "the tip"], "a": 0, "trap": "le tour — a turn or a trip; « la tournée » with -ée is specifically the round you pay for", "expl": "« C'est ma tournée ! » = my round. Rounds are normal among friends in Belgium; nobody counts too closely."}, {"id": "fvc-bar-A2-15", "level": "A2", "pos": "verb", "fr": "trinquer", "en": "to clink glasses", "format": "fr2en", "options": ["to clink glasses in a toast", "to drink too much", "to pour a drink", "to buy a round"], "a": 0, "trap": "boire — simply to drink; trinquer is the clink and the eye contact before it", "expl": "Look people in the eye as you clink — in Belgium as in France, looking away is genuinely bad form."}, {"id": "fvc-bar-A2-16", "level": "A2", "pos": "expr", "fr": "Santé !", "en": "Cheers!", "format": "collocation", "q": "Vous trinquez avec un ami. Quelle formule est correcte ?", "options": ["À la tienne !", "À la tienne santé !", "À ta santé de toi !", "Pour ta santé !"], "a": 0, "trap": "mixing « à la tienne » and « à ta santé » into one — each works alone, never together", "expl": "Three interchangeable options: « Santé ! », « À la tienne ! » (tu), « À la vôtre ! » (vous). « Tchin-tchin ! » is the playful one."}, {"id": "fvc-bar-A2-17", "level": "A2", "pos": "verb", "fr": "offrir", "en": "to buy (someone) a drink", "format": "en2fr", "options": ["offrir", "donner", "payer", "inviter"], "a": 0, "trap": "inviter — to invite; « je t'invite » also means 'it's on me', which is why the two get tangled", "expl": "« Je t'offre un verre ? » = can I get you a drink? « C'est offert par la maison » = it's on the house."}, {"id": "fvc-bar-A2-18", "level": "A2", "pos": "expr", "fr": "avoir soif", "en": "to be thirsty", "format": "collocation", "q": "Vous avez très soif. Quelle phrase est correcte ?", "options": ["J'ai super soif", "Je suis très soif", "J'ai beaucoup soif", "Je fais soif"], "a": 0, "trap": "« je suis soif » copies English 'I am thirsty' and is always wrong", "expl": "Avoir soif, avoir faim, avoir chaud. « Super » before the noun is informal and very common among young people."}, {"id": "fvc-bar-A2-19", "level": "A2", "pos": "noun", "gender": "f", "fr": "la mousse", "en": "the head (foam) on a beer", "format": "fr2en", "options": ["the foam on top of a beer", "the moss on a wall", "the mousse dessert only", "the bubbles in sparkling water"], "a": 0, "trap": "« une mousse au chocolat » is a dessert, and « la mousse » is also moss — three meanings, one word", "expl": "Belgian beer is poured with a proper head, deliberately. « Une petite mousse » is also slang for a beer."}, {"id": "fvc-bar-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le fût", "en": "the barrel / keg", "format": "fr2en", "options": ["the keg the draught beer comes from", "the beer tap", "the cellar", "the wooden bar"], "a": 0, "trap": "la pompe — the tap itself; « le fût » is the container behind it", "expl": "« Le fût est vide » = the keg's empty, which is why your beer is taking so long. Pronounced 'fu', the t is silent."}, {"id": "fvc-bar-A2-21", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte des bières", "en": "the beer list", "format": "en2fr", "options": ["la carte des bières", "la liste des prix", "la carte des vins", "la carte du jour"], "a": 0, "trap": "la carte des vins — the wine list, and in a Belgian café much the shorter of the two", "expl": "In a specialist café like the Délirium the beer list runs to dozens of pages. « Je peux voir la carte des bières ? »"}, {"id": "fvc-bar-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'alcool", "en": "alcohol", "format": "fr2en", "options": ["alcohol", "a spirit measure", "a hangover", "a drunk person"], "a": 0, "trap": "l'alcoolique — an alcoholic person; « l'alcool » is the substance", "expl": "Pronounced 'al-kol' — the two o's make one sound. « Une bière sans alcool » = an alcohol-free beer."}, {"id": "fvc-bar-A2-23", "level": "A2", "pos": "adj", "fr": "sans alcool", "en": "alcohol-free", "format": "cloze", "q": "Je conduis ce soir, donc je vais prendre une bière ___ .", "options": ["sans alcool", "à la pression", "bien fraîche", "de saison"], "a": 0, "trap": "à la pression — grammatically fine, but it says nothing about the fact that you are driving", "expl": "All four are phrases that fit after « une bière ». « Je conduis » is the clue. Belgian limit: 0,5 g/l, and police controls are frequent."}, {"id": "fvc-bar-A2-24", "level": "A2", "pos": "noun", "gender": "m", "fr": "le soft", "en": "a soft drink (Belgium)", "format": "fr2en", "options": ["a non-alcoholic drink", "a soft cheese", "a light beer", "a comfortable seat"], "a": 0, "trap": "learners read the English adjective 'soft' and miss that in Belgium it is a noun", "note": "Belgian French. « Un soft » covers cola, lemonade, juice. In France you would say « une boisson sans alcool » or name the drink; « un soft » there is not used.", "expl": "« Et pour toi, une bière ou un soft ? » is a question you will be asked every Friday."}, {"id": "fvc-bar-A2-25", "level": "A2", "pos": "noun", "gender": "m", "fr": "le jus d'orange", "en": "the orange juice", "format": "en2fr", "options": ["le jus d'orange", "le sirop d'orange", "le nectar d'orange", "le jus de fruits"], "a": 0, "trap": "le sirop — a cordial you dilute, sold in every Belgian café as « un sirop de grenadine »", "expl": "Often shortened to « un jus d'orange » or, on a board, « JO ». « Pressé » means freshly squeezed and costs more."}, {"id": "fvc-bar-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "le genièvre", "en": "juniper spirit (Belgian gin)", "format": "fr2en", "options": ["a juniper grain spirit drunk in small glasses", "a herbal liqueur", "a cherry brandy", "a mulled wine"], "a": 0, "trap": "le gin — related, but genièvre is grainier, drunk ice-cold and neat, never with tonic", "note": "Belgian speciality, called « peket » in Liège and Wallonia, « jenever » in Flanders. Not part of ordinary café life in France.", "expl": "« Un petit genièvre » after a beer is a Belgian winter habit — Hasselt has a whole museum for it."}, {"id": "fvc-bar-A2-27", "level": "A2", "pos": "noun", "gender": "m", "fr": "le cocktail", "en": "the cocktail", "format": "cloze", "q": "Ils font des ___ , mais c'est plus cher qu'une bière.", "options": ["cocktails", "softs", "verres", "glaçons"], "a": 0, "trap": "verres — masculine plural and perfectly grammatical, but « des verres » does not explain why it costs more", "expl": "All four are masculine plural nouns that fit. A cocktail in Ixelles runs €10–13, against €3.20 for a pinte."}, {"id": "fvc-bar-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "les cacahuètes", "en": "the peanuts", "format": "en2fr", "options": ["les cacahuètes", "les noix", "les olives", "les chips"], "a": 0, "trap": "les noix — walnuts; « les chips » are crisps, the other free bar snack", "expl": "A small bowl usually comes free with a beer in Belgium — « des cacahuètes » or « un ballotin de chips »."}, {"id": "fvc-bar-A2-29", "level": "A2", "pos": "noun", "gender": "m", "fr": "les glaçons", "en": "the ice cubes", "format": "fr2en", "options": ["the ice cubes", "the icing on a cake", "the frozen ground", "the freezer"], "a": 0, "trap": "la glace — ice as a substance, and also ice cream and a mirror", "expl": "« Avec ou sans glaçons ? » Beer never gets any; a soft drink usually does."}, {"id": "fvc-bar-A2-30", "level": "A2", "pos": "noun", "gender": "f", "fr": "la paille", "en": "the straw", "format": "fr2en", "options": ["the drinking straw", "the pile of papers", "the doormat", "the stirrer"], "a": 0, "trap": "the same word means straw as in hay — « un toit de paille » is a thatched roof", "expl": "« Avec une paille ? » Since 2021 Belgian bars use paper or reusable ones; plastic is banned."}, {"id": "fvc-bar-A2-31", "level": "A2", "pos": "noun", "gender": "m", "fr": "le tabouret", "en": "the stool", "format": "en2fr", "options": ["le tabouret", "le fauteuil", "le banc", "le siège"], "a": 0, "trap": "le siège — a seat in general, including a car seat and a company's head office", "expl": "« Il reste deux tabourets au bar. » « Un banc » is a bench, « un fauteuil » an armchair."}, {"id": "fvc-bar-A2-32", "level": "A2", "pos": "verb", "fr": "fumer", "en": "to smoke", "format": "fr2en", "options": ["to smoke", "to steam", "to fumigate a room", "to be furious"], "a": 0, "trap": "fumer also means to be seething with anger in slang, which is where the confusion starts", "note": "Smoking has been banned inside Belgian cafés since 2011 — everyone smokes on the terrace, in all weathers, which is why terraces are heated.", "expl": "« Je vais fumer dehors, je reviens. » « Une clope » is a cigarette in slang."}, {"id": "fvc-bar-A2-33", "level": "A2", "pos": "verb", "fr": "boire", "en": "to drink", "format": "cloze", "q": "Tu ___ quoi ? Je vais au bar.", "options": ["bois", "prends", "veux", "commandes"], "a": 0, "trap": "prends — completely natural French and just as usable here; « bois » is the one that names the act of drinking", "expl": "All four are correct tu-forms and all four are heard in cafés. « Tu bois quoi ? » and « tu prends quoi ? » are the two everyone actually says."}, {"id": "fvc-bar-A2-34", "level": "A2", "pos": "verb", "fr": "sortir", "en": "to go out (for the evening)", "format": "fr2en", "options": ["to go out for the evening", "to leave a room", "to take something out", "to come out of a shop"], "a": 0, "trap": "all the literal meanings are real — « sortir la poubelle » is to take the bin out — but « on sort ce soir ? » is the social one", "expl": "« On sort ce soir ? » = shall we go out tonight? Note it takes être in the passé composé: « je suis sorti »."}, {"id": "fvc-bar-A2-35", "level": "A2", "pos": "verb", "fr": "se retrouver", "en": "to meet up", "format": "en2fr", "options": ["se retrouver", "retrouver", "se rencontrer", "se revoir"], "a": 0, "trap": "se rencontrer — to meet for the first time; « se retrouver » is meeting up with people you already know", "expl": "« On se retrouve à Flagey à huit heures ? » The standard way to fix a place and a time."}, {"id": "fvc-bar-A2-36", "level": "A2", "pos": "adj", "fr": "bondé", "en": "packed, crowded", "format": "fr2en", "options": ["packed with people", "closed", "booked out in advance", "noisy"], "a": 0, "trap": "complet — full in the sense of no places left; « bondé » is about bodies, not bookings", "expl": "« C'est bondé à l'intérieur, on reste en terrasse. » On a Friday at Flagey, expect it."}, {"id": "fvc-bar-A2-37", "level": "A2", "pos": "noun", "gender": "m", "fr": "le concert", "en": "the gig / concert", "format": "en2fr", "options": ["le concert", "le spectacle", "la fête", "le festival"], "a": 0, "trap": "le spectacle — a show in general: theatre, circus, cabaret", "expl": "« Il y a un concert gratuit ce jeudi. » Flagey and the Botanique both run them all year."}, {"id": "fvc-bar-A2-38", "level": "A2", "pos": "adj", "fr": "gratuit", "en": "free (of charge)", "format": "fr2en", "options": ["free of charge", "free as in available", "cheap", "included in the price"], "a": 0, "trap": "libre — free as in unoccupied: « cette place est libre ? »", "expl": "Two different words for English 'free': gratuit = costs nothing, libre = not taken."}, {"id": "fvc-bar-A2-39", "level": "A2", "pos": "expr", "fr": "encore une", "en": "another one (drink)", "format": "collocation", "q": "Tu veux une deuxième bière. Que dis-tu au barman ?", "options": ["La même, s'il te plaît", "Encore de la même", "Une autre fois, s'il te plaît", "Un autre encore"], "a": 0, "trap": "« une autre fois » means 'another time', i.e. not now — the opposite of what you want", "expl": "« La même » or « encore une, s'il te plaît » both work. « Encore » here means 'another', not 'again'."}, {"id": "fvc-bar-A2-40", "level": "A2", "pos": "noun", "gender": "f", "fr": "la monnaie", "en": "the change (coins)", "format": "fr2en", "options": ["the change you get back", "money in general", "the currency market", "the wallet"], "a": 0, "trap": "l'argent — money in general, not the coins that come back", "expl": "« Garde la monnaie » = keep the change. « Tu as de la monnaie ? » asks for small coins."}, {"id": "fvc-bar-A2-41", "level": "A2", "pos": "expr", "fr": "en liquide", "en": "in cash", "format": "en2fr", "options": ["en liquide", "en billet", "en pièce", "en carte"], "a": 0, "trap": "« en carte » — payment by card takes « par », not « en »: par carte, par Bancontact", "note": "Practical Belgian point: small cafés often have a €10 minimum for Bancontact, or take cash only. Carry a note.", "expl": "« En liquide » or « en espèces » or simply « cash », which Belgians say in French without blinking."}, {"id": "fvc-bar-A2-42", "level": "A2", "pos": "verb", "fr": "fermer", "en": "to close", "format": "cloze", "q": "Ils ___ à deux heures du matin le week-end.", "options": ["ferment", "ouvrent", "servent", "commencent"], "a": 0, "trap": "ouvrent — grammatical and about the same clock, but no café in Ixelles opens at two in the morning", "expl": "All four are correct ils-forms. Brussels cafés have no fixed closing hour by law; many simply close when the room empties."}, {"id": "fvc-bar-A2-43", "level": "A2", "pos": "expr", "fr": "On se tutoie ?", "en": "Shall we use tu?", "format": "fr2en", "options": ["Shall we switch to first names and tu?", "Shall we speak more quietly?", "Shall we split the bill?", "Shall we sit down?"], "a": 0, "trap": "« on se voit ? » — shall we meet; one syllable apart, completely different proposal", "expl": "The person who is older or senior offers it. Answer « oui, avec plaisir ». The opposite verb is « vouvoyer »."}, {"id": "fvc-bar-A2-44", "level": "A2", "pos": "noun", "gender": "f", "fr": "la place", "en": "the free seat / room", "format": "fr2en", "options": ["a free seat or space", "the town square only", "the position in a queue", "the terrace"], "a": 0, "trap": "the same word is the square outside — « la place Flagey » — which is why learners hesitate", "expl": "« Il y a de la place en terrasse ? » = is there room outside? « Cette place est libre ? » = is this seat taken?"}, {"id": "fvc-bar-A2-45", "level": "A2", "pos": "adj", "fr": "frais", "en": "cool, chilled", "format": "en2fr", "options": ["frais", "froid", "tiède", "glacé"], "a": 0, "trap": "froid — cold; a beer should be « bien fraîche », not « froide »", "expl": "Feminine « fraîche »: « une bière bien fraîche ». « Frais » also means fresh, as in « du pain frais »."}], "phrases": [{"id": "ph-bar-A2-01", "fr": "Salut ! Ça va ? On se retrouve à Flagey à huit heures ?", "en": "Hi! How's it going? Shall we meet at Flagey at eight?", "note": "« Salut » is the tu greeting; « bonjour » works with everyone. Belgians say the hour as « huit heures », never 'eight o'clock pm'."}, {"id": "ph-bar-A2-02", "fr": "Tu bois quoi ?", "en": "What are you drinking?", "note": "Question by intonation, subject first — the everyday spoken form. « Qu'est-ce que tu bois ? » is the tidier version."}, {"id": "ph-bar-A2-03", "fr": "Deux pintes, s'il te plaît.", "en": "Two small draught beers, please.", "note": "« Une pinte » in Belgium is 25cl, not a British pint. In France ask for « un demi »."}, {"id": "ph-bar-A2-04", "fr": "Je vais prendre une trappiste, plutôt.", "en": "I'll have a Trappist beer instead.", "note": "« Plutôt » at the end = rather / instead. Trappist beers are strong: 6 to 10%."}, {"id": "ph-bar-A2-05", "fr": "Qu'est-ce que vous avez à la pression ?", "en": "What have you got on draught?", "note": "Vous here is plural (the bar), not formal. The answer is usually « Jupiler et une blanche »."}, {"id": "ph-bar-A2-06", "fr": "Une bière sans alcool, je conduis.", "en": "An alcohol-free beer, I'm driving.", "note": "The Belgian limit is 0,5 g/l and police controls are common, especially at weekends. « Je conduis » is all the explanation anyone needs."}, {"id": "ph-bar-A2-07", "fr": "Il y a de la place en terrasse ?", "en": "Is there room outside?", "note": "« De la place » = room. « Une place » = one particular seat."}, {"id": "ph-bar-A2-08", "fr": "Cette place est libre ?", "en": "Is this seat taken?", "note": "« Libre » = free as in unoccupied. « Gratuit » would mean it costs nothing."}, {"id": "ph-bar-A2-09", "fr": "On commande au bar ou il y a du service ?", "en": "Do we order at the bar or is there table service?", "note": "Worth asking: at Café Belga you order at the bar, in a classic estaminet a waiter comes to you."}, {"id": "ph-bar-A2-10", "fr": "C'est combien, la pinte ?", "en": "How much is a beer?", "note": "Dislocation — noun after the question — is how people really speak. Expect €3.00–3.50 in Ixelles, more on the Grand-Place."}, {"id": "ph-bar-A2-11", "fr": "Tiens, voilà dix euros. Garde la monnaie.", "en": "Here, ten euros. Keep the change.", "note": "« Tiens » (tu) / « tenez » (vous) is what you say as you hand something over. Rounding up is the normal tip at a bar."}, {"id": "ph-bar-A2-12", "fr": "Vous prenez le Bancontact ?", "en": "Do you take debit cards?", "note": "Ask before ordering: small Brussels cafés often have a €10 minimum or take cash only."}, {"id": "ph-bar-A2-13", "fr": "Santé ! À la tienne.", "en": "Cheers! Here's to you.", "note": "« À la tienne » with tu, « à la vôtre » with vous. Look people in the eye as you clink — not doing so is genuinely rude."}, {"id": "ph-bar-A2-14", "fr": "C'est ma tournée !", "en": "This round's on me!", "note": "« Une tournée » is a round. Among friends in Belgium the rounds go round; nobody keeps a tally."}, {"id": "ph-bar-A2-15", "fr": "Je t'offre un verre ?", "en": "Can I get you a drink?", "note": "« Offrir » = to treat someone. « Je t'invite » means the same thing at the end of a meal."}, {"id": "ph-bar-A2-16", "fr": "La même chose, s'il te plaît.", "en": "The same again, please.", "note": "Or simply « la même ». « Encore une » works too — « encore » here means 'another', not 'again'."}, {"id": "ph-bar-A2-17", "fr": "Je vais fumer dehors, je reviens.", "en": "I'm going out for a cigarette, I'll be back.", "note": "Smoking indoors has been banned in Belgian cafés since 2011, which is why every terrace has heaters."}, {"id": "ph-bar-A2-18", "fr": "C'est bondé à l'intérieur, on reste dehors ?", "en": "It's packed inside, shall we stay outside?", "note": "« Bondé » = crammed with people. On a Friday at Flagey this sentence gets used a lot."}, {"id": "ph-bar-A2-19", "fr": "On se tutoie, hein ?", "en": "We can use tu, right?", "note": "« Hein » softens it into a friendly check. Normal between people of the same age; let an older person offer it first."}, {"id": "ph-bar-A2-20", "fr": "Je vais y aller, j'ai le dernier tram. Bonne soirée !", "en": "I'm going to head off, I've got the last tram. Have a good evening!", "note": "« Je vais y aller » is the standard way to announce you are leaving. STIB trams stop around midnight; then it's the Noctis night buses at weekends."}], "dialogue": [{"who": "friend", "fr": "Salut ! Ça va ? Tu bois quoi ?", "en": "Hi! How's it going? What are you drinking?", "gloss": {"Salut": "hi (informal)", "bois": "drink"}}, {"who": "you", "fr": "Salut ! Ça va, et toi ? Moi, je prends une pinte.", "en": "Hi! I'm good, and you? I'll have a small draught beer.", "gloss": {"pinte": "25cl draught lager (Belgium; France: un demi)"}, "accept": ["salut ça va et toi moi je prends une pinte", "salut ça va et toi je prends une pinte", "ça va et toi je prends une pinte", "salut ça va moi je prends une pinte", "salut je prends une pinte", "ça va bien et toi moi je vais prendre une pinte"]}, {"who": "friend", "fr": "Nickel. On commande au bar, il n'y a pas de service en terrasse ici.", "en": "Great. We order at the bar, there's no table service outside here.", "gloss": {"Nickel": "great / perfect (slang)", "service": "table service"}}, {"who": "you", "fr": "D'accord, je te suis.", "en": "OK, I'll follow you.", "gloss": {"je te suis": "I'll follow you"}, "accept": ["d'accord je te suis", "ok je te suis", "d'accord je viens avec toi", "je te suis", "ok j'arrive", "d'accord on y va"]}, {"who": "barman", "fr": "Salut ! Vous prenez quoi ?", "en": "Hi! What are you having?", "gloss": {"Vous": "you (plural — the two of you, not formal)"}}, {"who": "you", "fr": "Deux pintes, s'il te plaît.", "en": "Two small draught beers, please.", "gloss": {"s'il te plaît": "please (tu form)"}, "accept": ["deux pintes s'il te plaît", "deux pintes", "deux pintes s'il vous plaît", "deux pintes stp", "on va prendre deux pintes s'il te plaît", "deux pintes merci"]}, {"who": "barman", "fr": "Jupiler, ça va ? On a aussi de la Chimay à la pression.", "en": "Jupiler, all right? We've also got Chimay on draught.", "gloss": {"Jupiler": "the standard Belgian lager", "Chimay": "a Trappist beer", "à la pression": "on draught"}}, {"who": "you", "fr": "Alors une Jupiler et une Chimay. C'est combien ?", "en": "One Jupiler and one Chimay then. How much is it?", "gloss": {"Alors": "in that case"}, "accept": ["alors une jupiler et une chimay c'est combien", "une jupiler et une chimay c'est combien", "alors une jupiler et une chimay", "une jupiler et une chimay s'il te plaît c'est combien", "du coup une jupiler et une chimay c'est combien", "une jupiler et une chimay combien ça fait"]}, {"who": "barman", "fr": "Trois vingt et quatre cinquante, ça fait sept euros septante.", "en": "Three twenty and four fifty, that's seven euros seventy.", "gloss": {"septante": "70 (Belgium; France: soixante-dix)", "ça fait": "that comes to"}}, {"who": "you", "fr": "Tiens, voilà huit euros. Garde la monnaie.", "en": "Here, eight euros. Keep the change.", "gloss": {"Tiens": "here (as you hand it over)", "monnaie": "change (coins)"}, "accept": ["tiens voilà huit euros garde la monnaie", "voilà huit euros garde la monnaie", "tiens huit euros garde la monnaie", "voilà huit euros", "tiens voilà huit euros", "huit euros garde la monnaie"]}, {"who": "barman", "fr": "Merci ! Les voilà, bien fraîches. Bonne soirée !", "en": "Thanks! Here they are, nice and cold. Have a good evening!", "gloss": {"fraîches": "chilled", "Bonne soirée": "have a good evening"}}, {"who": "you", "fr": "Merci ! Santé, à la tienne !", "en": "Thanks! Cheers, here's to you!", "gloss": {"Santé": "cheers", "à la tienne": "here's to you (tu)"}, "accept": ["merci santé à la tienne", "santé à la tienne", "merci santé", "santé", "merci tchin à la tienne", "à la tienne santé"]}, {"who": "friend", "fr": "Tchin ! Dis, tu veux qu'on aille en terrasse ? Il y a de la place.", "en": "Cheers! Say, shall we go outside? There's room.", "gloss": {"Tchin": "cheers (playful)", "qu'on aille": "for us to go (subjunctive)", "de la place": "room / space"}}, {"who": "you", "fr": "Oui, allons-y. Il fait bon ce soir.", "en": "Yes, let's go. It's mild this evening.", "gloss": {"allons-y": "let's go", "Il fait bon": "the weather's mild"}, "accept": ["oui allons-y il fait bon ce soir", "oui allons-y", "d'accord allons-y il fait bon ce soir", "oui bonne idée il fait bon ce soir", "avec plaisir allons-y", "oui on y va il fait bon ce soir"]}, {"who": "friend", "fr": "Tu veux grignoter un truc ? Ils donnent des cacahuètes avec.", "en": "Do you want a nibble? They give you peanuts with it.", "gloss": {"grignoter": "to nibble", "truc": "thing (informal)", "cacahuètes": "peanuts"}}, {"who": "you", "fr": "Volontiers, j'ai un petit creux.", "en": "Gladly, I'm a bit peckish.", "gloss": {"Volontiers": "gladly", "un petit creux": "a bit peckish"}, "accept": ["volontiers j'ai un petit creux", "oui volontiers j'ai un petit creux", "avec plaisir j'ai un petit creux", "oui j'ai un petit creux", "volontiers j'ai faim", "je veux bien j'ai un petit creux"]}, {"who": "friend", "fr": "Et la prochaine, c'est ma tournée, hein.", "en": "And the next one's my round, OK?", "gloss": {"tournée": "round of drinks", "hein": "right? (softener)"}}, {"who": "you", "fr": "Merci ! Alors je prendrai une gueuze.", "en": "Thanks! I'll have a gueuze then.", "gloss": {"prendrai": "will have (future)", "gueuze": "sour Brussels lambic beer"}, "accept": ["merci alors je prendrai une gueuze", "merci alors je prends une gueuze", "merci je prendrai une gueuze", "alors je prendrai une gueuze", "merci beaucoup je prendrai une gueuze", "super je prendrai une gueuze"]}], "exercises": [{"id": "ex-bar-A2-01", "level": "A2", "format": "fr2en", "q": "une pinte (en Belgique)", "options": ["a 25cl draught lager", "a British pint of 57cl", "a half-litre glass", "a bottle of beer"], "a": 0, "expl": "In France « une pinte » is 50cl and 25cl is « un demi ». In Belgium the pinte is the small one."}, {"id": "ex-bar-A2-02", "level": "A2", "format": "en2fr", "q": "on draught", "options": ["à la pression", "en bouteille", "en canette", "au fût"], "a": 0, "expl": "« Une bière à la pression » or simply « une pression »."}, {"id": "ex-bar-A2-03", "level": "A2", "format": "cloze", "q": "Je conduis, je vais prendre un ___ .", "options": ["soft", "cocktail", "genièvre", "demi"], "a": 0, "expl": "All four are masculine drinks that fit. « Un soft » is Belgian for a non-alcoholic drink — the only one compatible with driving."}, {"id": "ex-bar-A2-04", "level": "A2", "format": "fr2en", "q": "C'est ma tournée !", "options": ["This round's on me!", "It's my turn to speak!", "I'm going on tour!", "It's my table!"], "a": 0, "expl": "« Une tournée » is a round of drinks; « un tour » is a turn or a trip."}, {"id": "ex-bar-A2-05", "level": "A2", "format": "collocation", "q": "Vous trinquez avec un ami. Que dites-vous ?", "options": ["À la tienne !", "À la vôtre !", "À la sienne !", "À la mienne !"], "a": 0, "expl": "« À la tienne » with tu, « à la vôtre » with vous — and never « à la mienne », which toasts yourself."}, {"id": "ex-bar-A2-06", "level": "A2", "format": "fr2en", "q": "la gueuze", "options": ["a dry, sour Brussels lambic", "a sweet cherry beer", "a strong abbey blond", "a wheat beer with lemon"], "a": 0, "expl": "Brussels' own beer, made with wild yeast. The cherry version is « la kriek »."}, {"id": "ex-bar-A2-07", "level": "A2", "format": "en2fr", "q": "the change (coins you get back)", "options": ["la monnaie", "l'argent", "la pièce", "le billet"], "a": 0, "expl": "« Garde la monnaie. » « L'argent » is money in general."}, {"id": "ex-bar-A2-08", "level": "A2", "format": "cloze", "q": "C'est ___ à l'intérieur, on reste en terrasse.", "options": ["bondé", "libre", "gratuit", "fermé"], "a": 0, "expl": "All four are masculine adjectives that fit. Only « bondé » (packed) explains staying outside."}, {"id": "ex-bar-A2-09", "level": "A2", "format": "fr2en", "q": "le patron", "options": ["the owner of the café", "the customer", "the regular drinker", "the sponsor"], "a": 0, "expl": "False friend: English 'patron' is a customer, French « le patron » is the boss."}, {"id": "ex-bar-A2-10", "level": "A2", "format": "en2fr", "q": "to buy someone a drink", "options": ["offrir", "inviter", "donner", "payer"], "a": 0, "expl": "« Je t'offre un verre ? » « Je t'invite » means the same at the end of a meal; « donner » and « payer » do not carry the idea of treating someone."}, {"id": "ex-bar-A2-11", "level": "A2", "format": "en2fr", "q": "free of charge", "options": ["gratuit", "libre", "ouvert", "compris"], "a": 0, "expl": "« Gratuit » costs nothing; « libre » means unoccupied. « Cette place est libre ? »"}, {"id": "ex-bar-A2-12", "level": "A2", "format": "cloze", "q": "Une bière bien ___ , s'il te plaît.", "options": ["fraîche", "froide", "chaude", "tiède"], "a": 0, "expl": "All four are feminine temperature adjectives. Beer is « bien fraîche »; « froide » sounds like it came out of a freezer."}, {"id": "ex-bar-A2-13", "level": "A2", "format": "fr2en", "q": "un soft", "options": ["a non-alcoholic drink (Belgium)", "a soft cheese", "a low-alcohol beer", "an armchair"], "a": 0, "expl": "Belgicism. In France you would name the drink or say « une boisson sans alcool »."}, {"id": "ex-bar-A2-14", "level": "A2", "format": "collocation", "q": "Vous voulez savoir si le bar accepte les cartes. Que demandez-vous ?", "options": ["Vous prenez le Bancontact ?", "Vous prenez la carte bleue ?", "Vous acceptez le liquide de carte ?", "Vous payez par Bancontact ?"], "a": 0, "expl": "« La carte bleue » is French, not Belgian, and « vous payez » would be asking the barman how he pays. Small cafés often have a €10 minimum."}]},
  "bar-B1": {"slug": "bar", "level": "B1", "title": "Au bar — une tournée et une carte refusée", "place": "Café Belga, place Flagey, Ixelles, Bruxelles", "register": "tu", "registerNote": "Tu with your friends and with the barman, who is your age and started with tu. At B1 the informal register gets its own grammar: dropped ne (« ça passe pas »), « t'inquiète » for « ne t'inquiète pas », « ouais », « du coup ». Keep vous for the patron of an old estaminet, for anyone clearly older, and for the police officer at a roadside check — that one matters.", "vocab": [{"id": "fvc-bar-B1-01", "level": "B1", "pos": "noun", "gender": "m", "fr": "le terminal de paiement", "en": "the card machine", "format": "fr2en", "options": ["the card machine", "the airport terminal", "the cash register", "the receipt printer"], "a": 0, "trap": "la caisse — the till the terminal sits next to", "expl": "Everyday speech shortens it: « le terminal ne marche pas » or simply « le Bancontact est en panne »."}, {"id": "fvc-bar-B1-02", "level": "B1", "pos": "verb", "fr": "refuser", "en": "to decline / reject", "format": "cloze", "q": "Ta carte a été ___ , tu veux réessayer ?", "options": ["refusée", "acceptée", "utilisée", "perdue"], "a": 0, "trap": "acceptée — the same shape, the same grammar, the opposite evening", "expl": "All four are feminine past participles agreeing with « carte ». Spoken version: « ça ne passe pas » or, with the ne dropped, « ça passe pas »."}, {"id": "fvc-bar-B1-03", "level": "B1", "pos": "noun", "gender": "m", "fr": "le distributeur", "en": "the cash machine", "format": "fr2en", "options": ["the cash machine / ATM", "the vending machine only", "the wholesaler", "the card reader"], "a": 0, "trap": "the same word means a vending machine — « un distributeur de boissons » — so add « de billets » if it matters", "note": "In Belgium people also just say « un Bancontact »: « il y a un Bancontact au coin ». That use of the brand name for the machine is Belgian only.", "expl": "« Il y a un distributeur près d'ici ? » Belgian banks have thinned them out; Batopin machines are the shared network."}, {"id": "fvc-bar-B1-04", "level": "B1", "pos": "verb", "fr": "retirer", "en": "to withdraw (cash)", "format": "en2fr", "options": ["retirer", "tirer", "prendre", "sortir"], "a": 0, "trap": "tirer — to pull; only « retirer » is used for money out of a machine", "expl": "« Je vais retirer vingt euros. » The noun is « un retrait », the same word used for collecting an order in a shop."}, {"id": "fvc-bar-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le montant minimum", "en": "the minimum spend", "format": "fr2en", "options": ["the smallest amount you may pay by card", "the minimum wage", "the smallest coin accepted", "the cover charge"], "a": 0, "trap": "le salaire minimum — the minimum wage, a completely different figure", "note": "Very Belgian problem: small cafés and fritkots often post « Bancontact à partir de 10 € » or take cash only. Legally they must state it before you order.", "expl": "« Il y a un montant minimum pour la carte ? » Ask before the round, not after."}, {"id": "fvc-bar-B1-06", "level": "B1", "pos": "noun", "gender": "m", "fr": "le solde", "en": "the bank balance", "format": "fr2en", "options": ["the money left in your account", "the sale period in the shops", "the outstanding debt", "the overdraft limit"], "a": 0, "trap": "les soldes (masculine plural) — the January and July sales; « le solde » singular is your balance", "expl": "« Je vais vérifier mon solde sur l'appli. » Same word, two meanings, separated only by the plural."}, {"id": "fvc-bar-B1-07", "level": "B1", "pos": "noun", "gender": "m", "fr": "le code secret", "en": "the PIN", "format": "en2fr", "options": ["le code secret", "le mot de passe", "le numéro de compte", "le code postal"], "a": 0, "trap": "le mot de passe — a password, for an account you log into, not for a card terminal", "expl": "Belgian terminals say « Introduisez votre code » or « Tapez votre code secret ». Four digits."}, {"id": "fvc-bar-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le sans contact", "en": "contactless payment", "format": "fr2en", "options": ["contactless payment", "a card with no chip", "a payment made online", "a transfer between friends"], "a": 0, "trap": "le virement — a bank transfer, the other cashless option", "expl": "« En sans contact, ça passe ? » Belgian cards allow it up to €50, and ask for the PIN every few payments."}, {"id": "fvc-bar-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "Payconiq", "en": "the Belgian pay-by-QR-code app", "format": "fr2en", "options": ["the phone app that pays by scanning a QR code", "an online bank", "a loyalty scheme", "a money transfer service for abroad"], "a": 0, "trap": "learners assume it is a bank; it is the payment app most Belgian cafés display on a little sticker", "note": "Belgian only, now merged into Bancontact's app. France uses Lydia or Paylib instead; a French phone will not have it.", "expl": "« Tu peux payer par Payconiq, si tu as l'appli. » You scan the QR code taped to the bar and confirm on your GSM."}, {"id": "fvc-bar-B1-10", "level": "B1", "pos": "verb", "fr": "dépanner", "en": "to help someone out of a fix", "format": "fr2en", "options": ["to help someone out of a jam", "to repair a car", "to lend money permanently", "to break down"], "a": 0, "trap": "tomber en panne — to break down; « dépanner » is the rescue, not the breakdown", "expl": "« Tu peux me dépanner de dix euros ? » is how you ask a friend for a small loan without making it heavy."}, {"id": "fvc-bar-B1-11", "level": "B1", "pos": "verb", "fr": "avancer", "en": "to lend / front (money)", "format": "cloze", "q": "Je peux t'___ le cash, tu me rembourseras demain.", "options": ["avancer", "prêter", "donner", "offrir"], "a": 0, "expl": "« Prêter » is also perfectly correct here — but « avancer » says the money is only moving forward in time, which is exactly what « tu me rembourseras demain » confirms. « Offrir » would mean you never get it back.", "trap": "offrir — to treat someone, i.e. no repayment; the second half of the sentence rules it out"}, {"id": "fvc-bar-B1-12", "level": "B1", "pos": "verb", "fr": "devoir", "en": "to owe", "format": "fr2en", "options": ["to owe someone money", "to have to do something", "to be obliged by law", "to be worth"], "a": 0, "trap": "the same verb means 'must' — « je dois partir ». With a sum and a person it means 'owe'.", "expl": "« Je te dois combien ? » = how much do I owe you? Answer: « tu me dois six euros » or « laisse tomber »."}, {"id": "fvc-bar-B1-13", "level": "B1", "pos": "expr", "fr": "une tournée générale", "en": "a round for everyone in the bar", "format": "fr2en", "options": ["a round for the whole café", "a round for your own table", "a tour of several bars", "the last round before closing"], "a": 0, "trap": "« une tournée » alone is just your table's round; « générale » widens it to the room and to your overdraft", "expl": "« Tournée générale ! » is shouted, rarely, by someone celebrating. Expect to pay for twenty beers."}, {"id": "fvc-bar-B1-14", "level": "B1", "pos": "noun", "gender": "m", "fr": "le videur", "en": "the bouncer", "format": "en2fr", "options": ["le videur", "le gardien", "le portier", "le vigile"], "a": 0, "trap": "le vigile — a security guard, in a shop or an office; « le videur » stands at the door of a club", "expl": "From « vider », to empty. « Le videur ne m'a pas laissé entrer » — usually about shoes or ID."}, {"id": "fvc-bar-B1-15", "level": "B1", "pos": "noun", "gender": "f", "fr": "la carte d'identité", "en": "the ID card", "format": "fr2en", "options": ["the national identity card", "the bank card", "the membership card", "the driving licence"], "a": 0, "trap": "le permis de conduire — the driving licence, which is not accepted as ID everywhere in Belgium", "note": "In Belgium everyone over 12 carries an « eID », and you are legally required to have it on you. Doors, pharmacies and parcel points all ask for it.", "expl": "« Tu as ta carte d'identité ? » Spirits are 18+, beer and wine 16+ in Belgium."}, {"id": "fvc-bar-B1-16", "level": "B1", "pos": "adj", "fr": "mineur", "en": "under age", "format": "en2fr", "options": ["mineur", "majeur", "jeune", "adolescent"], "a": 0, "trap": "majeur — of age, the exact opposite, and only one letter different at the front", "expl": "« Être majeur » = to be 18. In Belgium beer and wine are legal at 16, spirits at 18."}, {"id": "fvc-bar-B1-17", "level": "B1", "pos": "noun", "gender": "m", "fr": "le monde", "en": "the crowd / people", "format": "cloze", "q": "Il y a un ___ fou ce soir, on ne trouvera jamais de table.", "options": ["monde", "bruit", "public", "groupe"], "a": 0, "trap": "public — masculine and grammatical, but « un public fou » would describe an audience, not a packed café", "expl": "All four are masculine nouns that fit. « Il y a du monde » = it's busy; « un monde fou » = absolutely heaving."}, {"id": "fvc-bar-B1-18", "level": "B1", "pos": "noun", "gender": "f", "fr": "la dégustation", "en": "the tasting", "format": "fr2en", "options": ["a tasting session", "a large helping", "a disgusting taste", "the aftertaste"], "a": 0, "trap": "« dégoûtant » means disgusting — the two words look related and mean opposite things", "expl": "« Une dégustation de trappistes » is a paid flight of small glasses. The verb is « déguster »."}, {"id": "fvc-bar-B1-19", "level": "B1", "pos": "noun", "gender": "m", "fr": "le degré", "en": "the alcohol strength", "format": "fr2en", "options": ["the percentage of alcohol", "the temperature of the beer", "the level of the glass", "the grade of the barley"], "a": 0, "trap": "« un degré » is also a temperature degree — context and the number decide", "expl": "« Elle fait combien de degrés ? » Chimay Bleue is 9°, so two of them count as four pintes."}, {"id": "fvc-bar-B1-20", "level": "B1", "pos": "adj", "fr": "amer", "en": "bitter", "format": "en2fr", "options": ["amer", "acide", "doux", "sec"], "a": 0, "trap": "acide — sour, which is what a gueuze is; « amer » is the hop bitterness of an IPA", "expl": "Feminine « amère ». « Une bière assez amère » = a fairly bitter beer."}, {"id": "fvc-bar-B1-21", "level": "B1", "pos": "adj", "fr": "houblonné", "en": "hoppy", "format": "fr2en", "options": ["strongly flavoured with hops", "aged in oak", "brewed with wheat", "flavoured with fruit"], "a": 0, "trap": "maltée — malty, the other half of the flavour", "expl": "« Une IPA bien houblonnée. » Belgian craft brewers use the word constantly."}, {"id": "fvc-bar-B1-22", "level": "B1", "pos": "noun", "gender": "m", "fr": "le houblon", "en": "hops", "format": "en2fr", "options": ["le houblon", "l'orge", "le malt", "la levure"], "a": 0, "trap": "l'orge — barley, the grain rather than the flower", "expl": "The h is aspirate: « le houblon », not « l'houblon ». Poperinge in West Flanders is the Belgian hop capital."}, {"id": "fvc-bar-B1-23", "level": "B1", "pos": "noun", "gender": "m", "fr": "le lambic", "en": "spontaneously fermented Brussels beer", "format": "fr2en", "options": ["a beer fermented by wild yeasts from the air", "a beer brewed with lamb stock", "a beer aged in a lambskin", "a very light table beer"], "a": 0, "trap": "learners hear 'lamb' — the name comes from Lembeek, a village south of Brussels", "note": "The base beer of the Brussels region. Blended it becomes gueuze; with cherries, kriek; sweetened, faro. Not brewed anywhere in France.", "expl": "Left in open vats so wild yeasts from the Senne valley get in. Cantillon in Anderlecht still does it the old way."}, {"id": "fvc-bar-B1-24", "level": "B1", "pos": "noun", "gender": "m", "fr": "le brasseur", "en": "the brewer", "format": "en2fr", "options": ["le brasseur", "le boulanger", "le bouilleur", "le buveur"], "a": 0, "trap": "le buveur — the drinker; both start with b and end up in the same room", "expl": "« Un brasseur artisanal » = a craft brewer. The place is « une brasserie », which also means the café you drink in."}, {"id": "fvc-bar-B1-25", "level": "B1", "pos": "adj", "fr": "artisanal", "en": "craft, small-batch", "format": "fr2en", "options": ["made in small batches by hand", "made in a factory", "sold only locally", "traditional in style but industrial"], "a": 0, "trap": "« industriel » is the opposite, and « traditionnel » says nothing about the scale", "expl": "« Une bière artisanale ». Plural « artisanaux » for masculine, « artisanales » for feminine."}, {"id": "fvc-bar-B1-26", "level": "B1", "pos": "noun", "gender": "f", "fr": "la gorgée", "en": "the mouthful / sip", "format": "fr2en", "options": ["a mouthful of drink", "the throat", "a large glass", "a gulp of air"], "a": 0, "trap": "la gorge — the throat it goes down; « une gorgée » is the quantity", "expl": "« Tu veux une gorgée ? » = do you want a sip? « D'une seule gorgée » = in one go."}, {"id": "fvc-bar-B1-27", "level": "B1", "pos": "expr", "fr": "la gueule de bois", "en": "the hangover", "format": "fr2en", "options": ["a hangover", "a wooden mask", "a bad mood", "a dry mouth from illness"], "a": 0, "trap": "« faire la gueule » means to sulk — same noun, different misery", "expl": "Literally 'wooden mouth'. « J'ai une gueule de bois terrible. » Informal but not rude."}, {"id": "fvc-bar-B1-28", "level": "B1", "pos": "adj", "fr": "pompette", "en": "tipsy", "format": "en2fr", "options": ["pompette", "bourré", "ivre", "sobre"], "a": 0, "trap": "bourré — properly drunk, and much coarser; « pompette » is affectionate and mild", "expl": "The ladder: sobre → pompette → éméché → bourré → ivre mort. « Pompette » is invariable-ish and always light-hearted."}, {"id": "fvc-bar-B1-29", "level": "B1", "pos": "expr", "fr": "avec modération", "en": "in moderation", "format": "cloze", "q": "« L'abus d'alcool est dangereux pour la santé, à consommer avec ___ . »", "options": ["modération", "prudence", "attention", "précaution"], "a": 0, "trap": "prudence — a sensible-sounding noun that fits the grammar but is not the legal wording", "expl": "All four are feminine nouns that fit after « avec ». This exact sentence is printed on every alcohol advert in Belgium and France."}, {"id": "fvc-bar-B1-30", "level": "B1", "pos": "noun", "gender": "m", "fr": "le taux d'alcoolémie", "en": "the blood alcohol level", "format": "fr2en", "options": ["the level of alcohol in your blood", "the alcohol percentage of a drink", "the alcohol tax", "the number of drinks served"], "a": 0, "trap": "le degré — the strength of the drink itself, not of the driver", "note": "Belgian limit: 0,5 g/l (0,2 g/l for professional drivers). Fines start around €179 and rise steeply. Checks are routine on weekend nights.", "expl": "« Contrôle d'alcoolémie » is the roadside test. Say vous to the officer."}, {"id": "fvc-bar-B1-31", "level": "B1", "pos": "expr", "fr": "souffler dans le ballon", "en": "to take a breathalyser test", "format": "fr2en", "options": ["to blow into the breathalyser", "to blow up a balloon", "to lose your temper", "to give up"], "a": 0, "trap": "learners take « le ballon » literally and picture a party balloon", "expl": "« La police m'a fait souffler dans le ballon. » The device is « un éthylotest »; nobody calls it that out loud."}, {"id": "fvc-bar-B1-32", "level": "B1", "pos": "expr", "fr": "être Bob", "en": "to be the designated driver (Belgium)", "format": "fr2en", "options": ["to be the one who stays sober and drives", "to be the one who pays", "to be the one who chooses the bar", "to be the first to leave"], "a": 0, "trap": "nothing about the phrase suggests driving until you know the campaign — it is a proper name used as a role", "note": "Belgian only, from a national road-safety campaign running since 1995. « Bob » is now an ordinary word here. In France the equivalent is « le capitaine de soirée » or « SAM ».", "expl": "« C'est moi le Bob ce soir » = I'm driving, so I'm not drinking. Nobody will press you after that."}, {"id": "fvc-bar-B1-33", "level": "B1", "pos": "noun", "gender": "m", "fr": "le Noctis", "en": "the Brussels night bus", "format": "fr2en", "options": ["the STIB night bus network", "the last metro", "a taxi company", "a night tram to the airport"], "a": 0, "trap": "le dernier tram — the last normal tram, which is a different and earlier thing", "note": "Brussels-specific. STIB Noctis buses run Friday and Saturday nights from about midnight to 3 a.m., all leaving from De Brouckère. A normal STIB ticket is valid.", "expl": "« Je vais prendre le Noctis. » Line numbers start with N: N04, N06, N08."}, {"id": "fvc-bar-B1-34", "level": "B1", "pos": "verb", "fr": "rentrer", "en": "to go home", "format": "cloze", "q": "Tu ___ comment ? Le dernier tram est à minuit.", "options": ["rentres", "pars", "reviens", "montes"], "a": 0, "trap": "pars — grammatical, and « tu pars comment ? » is said too, but « rentrer » is specifically getting yourself home", "expl": "All four are correct tu-forms. « Rentrer » takes être: « je suis rentré à deux heures »."}, {"id": "fvc-bar-B1-35", "level": "B1", "pos": "verb", "fr": "raccompagner", "en": "to walk / drive someone home", "format": "en2fr", "options": ["raccompagner", "accompagner", "reconduire", "ramener"], "a": 0, "trap": "accompagner — to go with someone; the rac- adds 'back home'", "expl": "« Je te raccompagne ? » is offered late at night and is simple politeness, not a proposition."}, {"id": "fvc-bar-B1-36", "level": "B1", "pos": "noun", "gender": "m", "fr": "le vestiaire", "en": "the cloakroom", "format": "fr2en", "options": ["the cloakroom where you leave your coat", "the changing room in a shop", "the wardrobe at home", "the toilets"], "a": 0, "trap": "la cabine d'essayage — the changing room in a clothes shop", "expl": "« Il y a un vestiaire ? » — usually €1 to €2 in a Brussels club, free in a café (i.e. there isn't one)."}, {"id": "fvc-bar-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "la soirée", "en": "the evening / the party", "format": "fr2en", "options": ["the evening as an event or a party", "the whole night until dawn", "the sunset", "the evening meal"], "a": 0, "trap": "le soir — the evening as a point in time; « la soirée » is its whole length, or a party", "expl": "« Une soirée chez Marie » = a party at Marie's. « Bonne soirée ! » wishes someone a good one."}, {"id": "fvc-bar-B1-38", "level": "B1", "pos": "verb", "fr": "prévoir", "en": "to plan / allow for", "format": "en2fr", "options": ["prévoir", "prévenir", "préparer", "prédire"], "a": 0, "trap": "prévenir — to warn someone; one letter apart and endlessly confused", "expl": "« Prévois du cash, leur Bancontact est capricieux. » « C'était prévu » = it was planned."}, {"id": "fvc-bar-B1-39", "level": "B1", "pos": "noun", "gender": "m", "fr": "le pote", "en": "the mate (informal)", "format": "en2fr", "options": ["le pote", "l'ami", "le collègue", "le voisin"], "a": 0, "trap": "l'ami — correct but neutral; « un pote » is what you say among friends your own age", "expl": "« Un pote à moi » = a mate of mine. Feminine « une pote ». Fine in a café, wrong in an email to work."}, {"id": "fvc-bar-B1-40", "level": "B1", "pos": "expr", "fr": "être partant", "en": "to be up for it", "format": "fr2en", "options": ["to be up for something", "to be about to leave", "to be a starter in a race only", "to be in favour of a law"], "a": 0, "trap": "« partir » — to leave; « je suis partant » does not mean you are going, it means you are in", "expl": "« Concert jeudi, tu es partant ? » — « Carrément ! » Feminine « partante »."}, {"id": "fvc-bar-B1-41", "level": "B1", "pos": "expr", "fr": "avoir la flemme", "en": "to not be bothered", "format": "fr2en", "options": ["to not be able to face doing something", "to be exhausted", "to be ill", "to be broke"], "a": 0, "trap": "être fatigué — genuinely tired; « la flemme » is pure reluctance", "expl": "« J'ai la flemme de bouger. » Very common, mildly informal, never rude."}, {"id": "fvc-bar-B1-42", "level": "B1", "pos": "expr", "fr": "ça marche", "en": "that works / OK then", "format": "cloze", "q": "— On se retrouve à Flagey à huit heures ? — Ça ___ .", "options": ["marche", "va", "roule", "tient"], "a": 0, "trap": "« ça roule » and « ça tient » both exist and both agree to a plan — but « ça marche » is the neutral everyday one and works everywhere", "expl": "All four are real replies. « Ça marche » is safest; « ça roule » is more slangy; « ça va » alone would answer a different question."}, {"id": "fvc-bar-B1-43", "level": "B1", "pos": "noun", "gender": "f", "fr": "la clope", "en": "the cigarette (informal)", "format": "fr2en", "options": ["a cigarette", "a lighter", "an ashtray", "a cigar"], "a": 0, "trap": "le briquet — the lighter you need to go with it", "expl": "« Tu as une clope ? » Informal but universal. The neutral word is « une cigarette »."}, {"id": "fvc-bar-B1-44", "level": "B1", "pos": "noun", "gender": "m", "fr": "le briquet", "en": "the lighter", "format": "en2fr", "options": ["le briquet", "l'allumette", "le cendrier", "le mégot"], "a": 0, "trap": "l'allumette — a match, the other way to light it", "expl": "« Tu as du feu ? » is the question people actually ask — literally 'have you got fire?'."}, {"id": "fvc-bar-B1-45", "level": "B1", "pos": "expr", "fr": "t'inquiète", "en": "don't worry about it", "format": "collocation", "q": "Ton ami te dit de ne pas t'en faire pour l'argent. Que dit-il ?", "options": ["T'inquiète, on verra ça demain", "Tu t'inquiètes, on verra ça demain", "T'inquiètes pas, on verra ça demain", "Ne t'inquiètes pas, on verra ça demain"], "a": 0, "trap": "adding an s — the imperative of an -er verb has no s: « inquiète-toi », « ne t'inquiète pas »", "expl": "« T'inquiète » is the clipped spoken form of « ne t'inquiète pas », with both the ne and the pas gone. Informal speech only — never write it in an email."}], "phrases": [{"id": "ph-bar-B1-01", "fr": "On est quatre maintenant, tu veux bien aller commander ?", "en": "There are four of us now, do you mind going to order?", "note": "« Tu veux bien + infinitif » is the friendly way to ask a favour. « On est quatre » — never « nous sommes quatre personnes » in speech."}, {"id": "ph-bar-B1-02", "fr": "Qu'est-ce que vous prenez ? Je note.", "en": "What are you all having? I'm making a note.", "note": "Vous here is plural, not formal. « Je note » = I'm writing it down / keeping track."}, {"id": "ph-bar-B1-03", "fr": "Il vous reste de la kriek, ou il n'y en a plus ?", "en": "Have you got any kriek left, or is it finished?", "note": "« Il vous reste de la... » with the partitive. « Il n'y en a plus » is the answer you get at 11 p.m."}, {"id": "ph-bar-B1-04", "fr": "Elle fait combien de degrés, la Chimay Bleue ?", "en": "How strong is the Chimay Bleue?", "note": "Dislocation (noun at the end) is normal speech. The answer here is 9° — treat it accordingly."}, {"id": "ph-bar-B1-05", "fr": "Tu me conseilles quoi, si j'aime les bières bien houblonnées ?", "en": "What would you recommend if I like really hoppy beers?", "note": "« Si + présent » for a real condition. Belgian barmen enjoy this question and will genuinely advise you."}, {"id": "ph-bar-B1-06", "fr": "Il y a un montant minimum pour le Bancontact ?", "en": "Is there a minimum for card payments?", "note": "Ask before ordering. Many small Brussels cafés set €10, and a few still take cash only."}, {"id": "ph-bar-B1-07", "fr": "Bizarre, ma carte ne passe pas.", "en": "Odd, my card isn't going through.", "note": "« Ça passe / ça ne passe pas » is what everyone says about a card terminal. « Refusée » is the machine's word, not yours."}, {"id": "ph-bar-B1-08", "fr": "J'ai dû atteindre ma limite journalière.", "en": "I must have hit my daily limit.", "note": "« Devoir » in the passé composé = 'must have'. Belgian debit cards have a daily ceiling you can raise in the banking app."}, {"id": "ph-bar-B1-09", "fr": "Je réessaie en sans contact ?", "en": "Shall I try again contactless?", "note": "« Réessayer » = to try again. Contactless works up to €50 in Belgium, but asks for the PIN every few payments."}, {"id": "ph-bar-B1-10", "fr": "Il y a un distributeur près d'ici ?", "en": "Is there a cash machine near here?", "note": "Belgians also say « un Bancontact » for the machine itself. Batopin is the shared network you will find on the squares."}, {"id": "ph-bar-B1-11", "fr": "Tu peux me dépanner de dix euros ? Je te rends ça demain.", "en": "Can you spot me ten euros? I'll pay you back tomorrow.", "note": "« Dépanner » keeps it light. « Je te rends ça » is friendlier than « je te rembourse », which sounds like a transaction."}, {"id": "ph-bar-B1-12", "fr": "Je te dois combien pour la tournée ?", "en": "How much do I owe you for the round?", "note": "« Devoir » + amount + person. Expect « laisse tomber » or « t'inquiète » as the answer."}, {"id": "ph-bar-B1-13", "fr": "T'inquiète, tu paieras la prochaine.", "en": "Don't worry, you'll get the next one.", "note": "« T'inquiète » is spoken French with ne and pas both dropped. Note the future « tu paieras » — rounds are a running account."}, {"id": "ph-bar-B1-14", "fr": "Ce soir c'est moi le Bob, je ne bois pas.", "en": "I'm the designated driver tonight, I'm not drinking.", "note": "Belgian only: « Bob » is the national road-safety mascot and now an ordinary noun. France says « je suis SAM » or « capitaine de soirée »."}, {"id": "ph-bar-B1-15", "fr": "Je préfère y aller doucement, j'ai eu une gueule de bois terrible samedi.", "en": "I'd rather take it easy, I had a terrible hangover on Saturday.", "note": "« Y aller doucement » = to go easy. « Une gueule de bois » is informal but perfectly acceptable in company."}, {"id": "ph-bar-B1-16", "fr": "Il y a un monde fou, on ne trouvera jamais de table.", "en": "It's absolutely heaving, we'll never find a table.", "note": "« Un monde fou » = a huge crowd. Note the future « on ne trouvera » for a prediction."}, {"id": "ph-bar-B1-17", "fr": "Tu rentres comment ? Le dernier tram est à minuit.", "en": "How are you getting home? The last tram is at midnight.", "note": "STIB trams stop around midnight; the Noctis night buses run from De Brouckère on Friday and Saturday nights."}, {"id": "ph-bar-B1-18", "fr": "Je vais prendre le Noctis, ou alors je rentre à pied.", "en": "I'll get the night bus, or else I'll walk home.", "note": "« Ou alors » = or else / alternatively. Noctis lines are numbered N01 to N18 and take an ordinary STIB ticket."}, {"id": "ph-bar-B1-19", "fr": "Je te raccompagne, c'est sur mon chemin.", "en": "I'll walk you home, it's on my way.", "note": "« Raccompagner » = to see someone home. « C'est sur mon chemin » removes any obligation from the offer."}, {"id": "ph-bar-B1-20", "fr": "Concert gratuit jeudi au Botanique, tu es partant ?", "en": "Free gig at the Botanique on Thursday, are you up for it?", "note": "« Être partant » = to be in. The Botanique and Flagey both run cheap or free concerts all year."}], "dialogue": [{"who": "friend", "fr": "On est quatre maintenant. Tu veux bien aller commander ? Je garde la table.", "en": "There are four of us now. Do you mind going to order? I'll keep the table.", "gloss": {"Tu veux bien": "do you mind (friendly request)", "garde": "keep / hold"}}, {"who": "you", "fr": "Pas de souci, j'y vais. Vous prenez quoi ?", "en": "No problem, I'll go. What are you all having?", "gloss": {"j'y vais": "I'll go", "Vous": "you (plural — the group)"}, "accept": ["pas de souci j'y vais vous prenez quoi", "pas de problème j'y vais vous prenez quoi", "ok j'y vais vous prenez quoi", "pas de souci vous prenez quoi", "j'y vais vous prenez quoi", "d'accord j'y vais qu'est-ce que vous prenez"]}, {"who": "friend", "fr": "Deux Jupiler, une kriek, et pour Sarah un soft, elle conduit.", "en": "Two Jupilers, a kriek, and for Sarah a soft drink, she's driving.", "gloss": {"kriek": "cherry lambic beer", "soft": "non-alcoholic drink (Belgium)", "conduit": "is driving"}}, {"who": "barman", "fr": "Salut ! Tu prends quoi ?", "en": "Hi! What are you having?", "gloss": {"Salut": "hi (informal)"}}, {"who": "you", "fr": "Deux pintes, une kriek et un soft, s'il te plaît.", "en": "Two draught beers, a kriek and a soft drink, please.", "gloss": {"pintes": "25cl draught lagers (Belgium)"}, "accept": ["deux pintes une kriek et un soft s'il te plaît", "deux pintes une kriek et un soft", "salut deux pintes une kriek et un soft s'il te plaît", "deux jupiler une kriek et un soft s'il te plaît", "deux pintes une kriek et un soft merci", "je voudrais deux pintes une kriek et un soft"]}, {"who": "barman", "fr": "Ah, désolé, il ne me reste plus de kriek. J'ai de la gueuze ou de la blanche.", "en": "Ah, sorry, I've no kriek left. I've got gueuze or wheat beer.", "gloss": {"il ne me reste plus": "I've none left", "gueuze": "dry sour lambic blend", "blanche": "wheat beer"}}, {"who": "you", "fr": "Alors une blanche, ce sera plus doux pour elle.", "en": "A wheat beer then, it'll be milder for her.", "gloss": {"doux": "mild / sweet", "ce sera": "it will be"}, "accept": ["alors une blanche ce sera plus doux pour elle", "alors une blanche", "du coup une blanche ce sera plus doux pour elle", "alors une blanche plutôt", "on va dire une blanche ce sera plus doux", "une blanche alors s'il te plaît"]}, {"who": "barman", "fr": "Ça marche. Ça fait treize euros nonante.", "en": "Right you are. That comes to thirteen euros ninety.", "gloss": {"Ça marche": "right you are / OK", "nonante": "90 (Belgium; France: quatre-vingt-dix)"}}, {"who": "you", "fr": "Je paie par Bancontact, c'est bon ?", "en": "I'll pay by debit card, is that OK?", "gloss": {"Bancontact": "Belgian debit-card system"}, "accept": ["je paie par bancontact c'est bon", "je paie par bancontact", "je peux payer par bancontact", "par bancontact c'est bon", "je paye par bancontact c'est possible", "est-ce que je peux payer par bancontact"]}, {"who": "barman", "fr": "Vas-y... Ah, ta carte a été refusée. Tu veux réessayer ?", "en": "Go ahead... Ah, your card's been declined. Do you want to try again?", "gloss": {"Vas-y": "go ahead", "refusée": "declined", "réessayer": "to try again"}}, {"who": "you", "fr": "Bizarre. J'ai dû atteindre ma limite journalière. Je réessaie en sans contact ?", "en": "Odd. I must have hit my daily limit. Shall I try again contactless?", "gloss": {"J'ai dû": "I must have", "limite journalière": "daily limit", "sans contact": "contactless"}, "accept": ["bizarre j'ai dû atteindre ma limite journalière je réessaie en sans contact", "bizarre je réessaie en sans contact", "j'ai dû atteindre ma limite journalière je réessaie en sans contact", "bizarre ça ne passe pas je réessaie en sans contact", "je réessaie en sans contact", "c'est bizarre je peux réessayer en sans contact"]}, {"who": "barman", "fr": "Essaie. ... Non, ça ne passe toujours pas, désolé.", "en": "Try. ... No, it's still not going through, sorry.", "gloss": {"toujours pas": "still not", "ça ne passe toujours pas": "it's still not going through"}}, {"who": "you", "fr": "Désolé pour l'attente. Il y a un distributeur près d'ici ?", "en": "Sorry for the wait. Is there a cash machine near here?", "gloss": {"distributeur": "cash machine (Belgians also say 'un Bancontact')"}, "accept": ["désolé pour l'attente il y a un distributeur près d'ici", "il y a un distributeur près d'ici", "désolé il y a un distributeur près d'ici", "pardon pour l'attente il y a un distributeur près d'ici", "est-ce qu'il y a un distributeur près d'ici", "il y a un bancontact près d'ici"]}, {"who": "barman", "fr": "Oui, à l'angle, devant la banque. Mais tu peux aussi payer par Payconiq, si tu as l'appli.", "en": "Yes, on the corner, in front of the bank. But you can also pay by Payconiq, if you've got the app.", "gloss": {"à l'angle": "on the corner", "Payconiq": "Belgian pay-by-QR-code app", "l'appli": "the app"}}, {"who": "you", "fr": "Je l'ai ! Je scanne le QR code... Voilà, c'est parti.", "en": "I've got it! I'll scan the QR code... There we go, it's gone through.", "gloss": {"scanne": "scan", "c'est parti": "there it goes / done"}, "accept": ["je l'ai je scanne le qr code voilà c'est parti", "je l'ai je scanne le qr code", "oui je l'ai je scanne le qr code", "parfait je l'ai je scanne le qr code", "je l'ai je vais scanner le qr code", "super je l'ai je scanne"]}, {"who": "barman", "fr": "Nickel, c'est bon. Les voilà, bonne soirée !", "en": "Great, that's fine. Here they are, have a good evening!", "gloss": {"Nickel": "great (slang)"}}, {"who": "friend", "fr": "Alors, ça a marché ? Je pouvais t'avancer le cash, tu sais.", "en": "So, did it work? I could have fronted you the cash, you know.", "gloss": {"avancer": "to front / lend", "cash": "cash (used in French in Belgium)"}}, {"who": "you", "fr": "C'est gentil, mais Payconiq m'a sauvé. Tu me diras ce que je te dois pour la prochaine tournée.", "en": "That's kind, but Payconiq saved me. Tell me what I owe you for the next round.", "gloss": {"m'a sauvé": "saved me", "je te dois": "I owe you", "tournée": "round of drinks"}, "accept": ["c'est gentil mais payconiq m'a sauvé tu me diras ce que je te dois pour la prochaine tournée", "c'est gentil mais payconiq m'a sauvé", "merci c'est gentil mais payconiq m'a sauvé", "c'est gentil mais ça a fini par passer avec payconiq", "merci mais payconiq m'a sauvé tu me diras ce que je te dois", "c'est sympa mais payconiq m'a sauvé"]}, {"who": "friend", "fr": "T'inquiète. Dis, tu rentres comment ? Le dernier tram est à minuit.", "en": "Don't worry about it. Say, how are you getting home? The last tram's at midnight.", "gloss": {"T'inquiète": "don't worry (clipped from « ne t'inquiète pas »)", "rentres": "are getting home"}}, {"who": "you", "fr": "Je vais prendre le Noctis, ou alors je rentre à pied, ce n'est pas loin.", "en": "I'll get the night bus, or else I'll walk, it's not far.", "gloss": {"Noctis": "STIB night bus (Brussels)", "ou alors": "or else", "à pied": "on foot"}, "accept": ["je vais prendre le noctis ou alors je rentre à pied ce n'est pas loin", "je vais prendre le noctis ou alors je rentre à pied", "je prends le noctis ou je rentre à pied", "je vais prendre le noctis", "je rentre à pied ce n'est pas loin", "je vais prendre le noctis ou je rentre à pied ce n'est pas loin"]}], "exercises": [{"id": "ex-bar-B1-01", "level": "B1", "format": "fr2en", "q": "Ma carte ne passe pas.", "options": ["My card is being declined.", "My card is out of date.", "My card is not in my wallet.", "My card is contactless only."], "a": 0, "expl": "« Ça passe / ça ne passe pas » is the everyday phrase for a card terminal."}, {"id": "ex-bar-B1-02", "level": "B1", "format": "cloze", "q": "J'___ dû atteindre ma limite journalière.", "options": ["ai", "avais", "aurais", "avais eu"], "a": 0, "expl": "« J'ai dû + infinitif » = I must have. The other forms are real but change the meaning to 'I had to' or 'I would have had to'."}, {"id": "ex-bar-B1-03", "level": "B1", "format": "fr2en", "q": "le solde", "options": ["the balance of your bank account", "the January sales", "the outstanding debt", "the overdraft limit"], "a": 0, "expl": "Singular « le solde » = balance; plural « les soldes » = the sales."}, {"id": "ex-bar-B1-04", "level": "B1", "format": "en2fr", "q": "to help someone out of a fix (with money)", "options": ["dépanner", "réparer", "offrir", "prêter"], "a": 0, "expl": "« Tu peux me dépanner de dix euros ? » « Prêter » is right too but flatter and more transactional."}, {"id": "ex-bar-B1-05", "level": "B1", "format": "fr2en", "q": "être Bob", "options": ["to be the designated driver (Belgium)", "to be the one paying", "to be the odd one out", "to be first at the bar"], "a": 0, "expl": "From the Belgian road-safety campaign. France says « SAM » or « capitaine de soirée »."}, {"id": "ex-bar-B1-06", "level": "B1", "format": "collocation", "q": "Ton ami dit de ne pas t'en faire. Quelle phrase est correcte ?", "options": ["T'inquiète, tu paieras la prochaine", "T'inquiètes, tu paieras la prochaine", "Ne t'inquiètes pas, tu paieras la prochaine", "T'inquiète pas de la prochaine tu paieras"], "a": 0, "expl": "No s on the imperative of an -er verb, and « t'inquiète » already contains the negative sense."}, {"id": "ex-bar-B1-07", "level": "B1", "format": "en2fr", "q": "the bouncer on the door", "options": ["le videur", "le vigile", "le gardien", "le portier"], "a": 0, "expl": "From « vider », to empty. « Un vigile » guards a shop or an office; « un portier » belongs to a hotel."}, {"id": "ex-bar-B1-08", "level": "B1", "format": "fr2en", "q": "le Noctis", "options": ["the STIB night bus network in Brussels", "the last metro of the night", "a late-opening bar", "a night taxi service"], "a": 0, "expl": "Friday and Saturday nights, from De Brouckère, on a normal STIB ticket."}, {"id": "ex-bar-B1-09", "level": "B1", "format": "en2fr", "q": "hoppy (of beer)", "options": ["houblonné", "malté", "fruité", "sucré"], "a": 0, "expl": "« Le houblon » is hops — note the aspirate h: « le houblon », not « l'houblon »."}, {"id": "ex-bar-B1-10", "level": "B1", "format": "fr2en", "q": "pompette", "options": ["tipsy", "properly drunk", "stone cold sober", "hungover"], "a": 0, "expl": "The ladder: sobre → pompette → éméché → bourré. « Pompette » is affectionate and mild."}, {"id": "ex-bar-B1-11", "level": "B1", "format": "fr2en", "q": "souffler dans le ballon", "options": ["to take a breathalyser test", "to blow up a balloon", "to lose your temper", "to run out of energy"], "a": 0, "expl": "Belgian limit 0,5 g/l, checks routine at weekends. The device is « un éthylotest »."}, {"id": "ex-bar-B1-12", "level": "B1", "format": "collocation", "q": "Vous voulez savoir s'il y a un minimum pour payer par carte. Que demandez-vous ?", "options": ["Il y a un montant minimum pour le Bancontact ?", "Il y a un salaire minimum pour le Bancontact ?", "Il y a un minimum de monnaie pour le Bancontact ?", "Il y a un prix minimum de la carte ?"], "a": 0, "expl": "« Un montant minimum » — many small Brussels cafés set it at €10 and must tell you before you order."}, {"id": "ex-bar-B1-13", "level": "B1", "format": "fr2en", "q": "j'ai la flemme", "options": ["I can't be bothered", "I'm exhausted", "I'm broke", "I'm feeling ill"], "a": 0, "expl": "Reluctance, not tiredness. « J'ai la flemme de bouger. »"}, {"id": "ex-bar-B1-14", "level": "B1", "format": "en2fr", "q": "to walk someone home", "options": ["raccompagner", "accompagner", "ramener", "reconduire"], "a": 0, "expl": "« Je te raccompagne ? » — the rac- carries 'back home'."}]},
  "festival-A2": {"slug": "festival", "level": "A2", "title": "Acheter des tickets et des jetons", "place": "Couleur Café, parc d'Osseghem, Laeken, Bruxelles", "register": "tu", "registerNote": "Tu, because a Belgian festival runs on volunteers and punters who are all roughly your age — the person at the ticket window will say « salut, c'est pour aujourd'hui ? » and expect tu back. Two exceptions where you switch to vous: the security staff searching your bag, and anyone in a police or first-aid uniform. Mirror whoever speaks first and you will never get it wrong.", "vocab": [{"id": "fvc-festival-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le festival", "en": "the festival", "format": "fr2en", "options": ["the music festival", "the public holiday", "the funfair", "the street party"], "a": 0, "trap": "la fête — a party or a public celebration, not a ticketed music event", "expl": "Plural « les festivals », with an s and no x. Belgium's big ones: Couleur Café and Brussels Summer Festival in the city, Dour, Tomorrowland and Rock Werchter elsewhere."}, {"id": "fvc-festival-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le billet", "en": "the ticket", "format": "fr2en", "options": ["the ticket for an event", "the shop receipt", "the wristband", "the programme"], "a": 0, "trap": "the same word means a banknote — « un billet de vingt euros »", "expl": "« Un billet » for a concert or a train; « un ticket » for the tram or a car park. Belgians use both fairly loosely."}, {"id": "fvc-festival-A2-03", "level": "A2", "pos": "noun", "gender": "f", "fr": "la prévente", "en": "the advance sale", "format": "fr2en", "options": ["tickets sold in advance and cheaper", "the resale of second-hand tickets", "the sale of drinks before the gates open", "the pre-order of merchandise"], "a": 0, "trap": "la revente — reselling a ticket, which at Belgian festivals is heavily restricted", "expl": "« J'ai pris mon billet en prévente » — usually €10 to €20 cheaper than at the gate."}, {"id": "fvc-festival-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le guichet", "en": "the ticket window", "format": "en2fr", "options": ["le guichet", "le comptoir", "le stand", "le portail"], "a": 0, "trap": "le stand — a stall selling food or merchandise, not tickets", "expl": "Same word at the station and the bank. « Le guichet est là-bas, à gauche. »"}, {"id": "fvc-festival-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la caisse du jour", "en": "the box office on the day", "format": "fr2en", "options": ["where you buy a ticket on the day itself", "the cash desk for drinks", "the daily takings", "the cloakroom"], "a": 0, "trap": "la prévente — the opposite end of the same process, and cheaper", "expl": "« Il reste des places à la caisse du jour ? » Answer at a sold-out festival: « non, c'est complet »."}, {"id": "fvc-festival-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le jeton", "en": "the token", "format": "fr2en", "options": ["the plastic token you pay with inside", "the coin of the realm", "the entry stamp", "the wristband"], "a": 0, "trap": "la pièce — an actual coin; a jeton has no value outside the festival gates", "note": "Belgian festivals traditionally run on « jetons » — at Couleur Café one costs about €2.60 and a beer is two of them. Many events are switching to a cashless wristband, but the word survives.", "expl": "« Je prends dix jetons. » Buy fewer than you think: leftover jetons are often refundable only online, or not at all."}, {"id": "fvc-festival-A2-07", "level": "A2", "pos": "noun", "gender": "f", "fr": "la consigne", "en": "the deposit (on a cup)", "format": "fr2en", "options": ["the deposit you get back when you return the cup", "the left-luggage office", "the instruction given by staff", "the extra charge for a large drink"], "a": 0, "trap": "the same word means left luggage at a station, and « les consignes » (plural) means instructions", "note": "Since 2019 Brussels events must use reusable cups, so every drink carries « une consigne » of €1–2. In France the système exists but is not compulsory everywhere.", "expl": "« Il y a une consigne d'un euro sur le gobelet. » Keep the cup, get the euro back."}, {"id": "fvc-festival-A2-08", "level": "A2", "pos": "noun", "gender": "m", "fr": "le gobelet", "en": "the (reusable) cup", "format": "en2fr", "options": ["le gobelet", "le verre", "le bol", "le pot"], "a": 0, "trap": "le verre — glass is banned inside a Belgian festival for safety, so it is always « un gobelet »", "expl": "Hard plastic, printed with the festival's name, and worth its consigne back at any bar on site."}, {"id": "fvc-festival-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bracelet", "en": "the wristband", "format": "fr2en", "options": ["the wristband that gets you in", "the bracelet you wear as jewellery only", "the arm of a seat", "the lanyard round your neck"], "a": 0, "trap": "le collier — a necklace; and « un badge » on a lanyard is what staff wear", "expl": "« Ne l'enlève pas » — take the bracelet off and you have thrown away your ticket. Waterproof, so you can shower in it."}, {"id": "fvc-festival-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "le contrôle", "en": "the ticket check", "format": "cloze", "q": "Il y a un ___ à l'entrée, prépare ton bracelet.", "options": ["contrôle", "guichet", "stand", "bracelet"], "a": 0, "trap": "guichet — masculine and grammatical, but the ticket window is where you buy, not where you get checked", "expl": "All four are masculine nouns that fit. « Contrôler » = to check; « un contrôleur » is the inspector on the STIB tram."}, {"id": "fvc-festival-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la fouille", "en": "the bag search", "format": "fr2en", "options": ["the search of your bag at the gate", "the crowd pushing forward", "the excavation of a site", "the queue"], "a": 0, "trap": "the archaeological meaning is the one dictionaries give first — « des fouilles » are a dig", "expl": "« Ouvre ton sac, s'il te plaît » is what you hear. No glass, no bottles over 50cl, no professional cameras."}, {"id": "fvc-festival-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le sac à dos", "en": "the backpack", "format": "en2fr", "options": ["le sac à dos", "le sac à main", "le sac de couchage", "le sac poubelle"], "a": 0, "trap": "le sac de couchage — a sleeping bag, which you also need if you are camping", "expl": "Most Belgian festivals limit backpacks to A4 size on the main site. « Un petit sac » gets in faster."}, {"id": "fvc-festival-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "le camping", "en": "the campsite", "format": "fr2en", "options": ["the campsite", "the act of camping only", "the caravan", "the campfire"], "a": 0, "trap": "le camp — a camp in the military or holiday sense", "expl": "« Le camping ouvre le jeudi à midi. » Couleur Café is a city festival with no campsite; Dour and Werchter have huge ones."}, {"id": "fvc-festival-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tente", "en": "the tent", "format": "en2fr", "options": ["la tente", "la tante", "la toile", "la bâche"], "a": 0, "trap": "la tante — your aunt, pronounced exactly the same", "expl": "« Monter la tente » = to put the tent up. Identical sound to « ma tante », so context does all the work."}, {"id": "fvc-festival-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "la scène", "en": "the stage", "format": "fr2en", "options": ["the stage", "the scene of a film only", "the audience area", "the backstage area"], "a": 0, "trap": "la salle — the room or the auditorium where the audience stands", "expl": "« La grande scène » and « la petite scène ». « Sur scène » = on stage, with no article."}, {"id": "fvc-festival-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le groupe", "en": "the band", "format": "cloze", "q": "Le ___ joue à vingt heures sur la grande scène.", "options": ["groupe", "concert", "public", "festival"], "a": 0, "trap": "concert — masculine and grammatical, but a concert does not play, a band does", "expl": "All four are masculine nouns that fit. « Un groupe » is a band; a solo artist is « un artiste » or « un chanteur »."}, {"id": "fvc-festival-A2-17", "level": "A2", "pos": "noun", "gender": "m", "fr": "le programme", "en": "the line-up / schedule", "format": "fr2en", "options": ["the list of who plays when", "the TV programme only", "the computer program", "the festival map"], "a": 0, "trap": "le plan — the site map, the other thing you get at the gate", "expl": "« Tu as regardé le programme ? » On the app at Couleur Café, on paper almost nowhere any more."}, {"id": "fvc-festival-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'horaire", "en": "the timetable", "format": "en2fr", "options": ["l'horaire", "l'heure", "le retard", "le délai"], "a": 0, "trap": "l'heure — the time on the clock, not the printed schedule", "expl": "Masculine despite the -e: « un horaire chargé ». Also the word for STIB timetables."}, {"id": "fvc-festival-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pass", "en": "the multi-day pass", "format": "fr2en", "options": ["the ticket valid for several days", "the corridor between stages", "the security check", "the backstage access badge"], "a": 0, "trap": "le passe-partout and « le passage » look similar; a festival « pass » is simply a multi-day ticket", "expl": "« Le pass trois jours » costs about €135 at Couleur Café against €65 for a single day. Pronounced 'pass', English-style."}, {"id": "fvc-festival-A2-20", "level": "A2", "pos": "noun", "gender": "f", "fr": "la navette", "en": "the shuttle bus", "format": "en2fr", "options": ["la navette", "la voiture", "la remorque", "la camionnette"], "a": 0, "trap": "la camionnette — a small van, not a shuttle service", "expl": "« Il y a une navette gratuite depuis la gare. » At Couleur Café you take the metro to Heysel instead — line 6."}, {"id": "fvc-festival-A2-21", "level": "A2", "pos": "noun", "gender": "m", "fr": "le métro", "en": "the metro", "format": "cloze", "q": "On prend le ___ jusqu'à Heysel, c'est la ligne 6.", "options": ["métro", "tram", "bus", "train"], "a": 0, "trap": "tram — masculine and entirely grammatical; the clue is « la ligne 6 », a metro line", "expl": "All four are masculine forms of transport that fit. STIB runs metro lines 1, 2, 5 and 6; Heysel/Heizel is on line 6, at the Atomium."}, {"id": "fvc-festival-A2-22", "level": "A2", "pos": "noun", "gender": "f", "fr": "la borne", "en": "the top-up terminal", "format": "fr2en", "options": ["the machine where you buy or top up tokens", "the boundary marker", "the electricity pylon", "the information desk"], "a": 0, "trap": "the original meaning is a milestone or boundary stone, which is what the dictionary gives you", "expl": "« Les bornes sont juste après la fouille. » Also « une borne de recharge » for an electric car."}, {"id": "fvc-festival-A2-23", "level": "A2", "pos": "verb", "fr": "recharger", "en": "to top up", "format": "en2fr", "options": ["recharger", "charger", "remplir", "ajouter"], "a": 0, "trap": "charger — to load or to charge for the first time; the re- means adding more", "expl": "« Je vais recharger mon bracelet. » Same verb for a phone, a transport card, or a cashless wristband."}, {"id": "fvc-festival-A2-24", "level": "A2", "pos": "verb", "fr": "attendre", "en": "to wait", "format": "fr2en", "options": ["to wait", "to expect a baby only", "to attend an event", "to listen"], "a": 0, "trap": "English 'to attend' — a classic false friend. To attend is « assister à ».", "expl": "« J'attends depuis vingt minutes. » Note: no preposition — « attendre le bus », not « attendre pour le bus »."}, {"id": "fvc-festival-A2-25", "level": "A2", "pos": "noun", "gender": "m", "fr": "le stand", "en": "the stall", "format": "fr2en", "options": ["the stall selling food or goods", "the grandstand seating", "the standing area", "the standstill"], "a": 0, "trap": "learners read the English verb; « un stand » is always a stall or a booth", "expl": "« Le stand des t-shirts » = the merch stall. Same word at a trade fair."}, {"id": "fvc-festival-A2-26", "level": "A2", "pos": "noun", "gender": "f", "fr": "la buvette", "en": "the drinks stand", "format": "en2fr", "options": ["la buvette", "la cantine", "la brasserie", "la cafétéria"], "a": 0, "trap": "la cantine — a canteen serving meals, in a school or a workplace", "expl": "From « boire ». « La buvette la plus proche » is the sentence you need at hour four."}, {"id": "fvc-festival-A2-27", "level": "A2", "pos": "noun", "gender": "m", "fr": "le foodtruck", "en": "the food truck", "format": "fr2en", "options": ["a van selling food", "a delivery lorry", "a supermarket trolley", "a picnic table"], "a": 0, "trap": "le camion — a lorry in general; the borrowed English word is what everyone says", "expl": "Couleur Café's whole identity is its food trucks — Congolese, Moroccan, Vietnamese. « Un camion-restaurant » is the official French, used by nobody."}, {"id": "fvc-festival-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "la mitraillette", "en": "a baguette with meat and chips (Belgium)", "format": "fr2en", "options": ["a half-baguette filled with meat, chips and sauce", "a machine gun only", "a portion of small sausages", "a mixed grill platter"], "a": 0, "trap": "the word literally means a submachine gun, which is exactly how learners translate it and exactly not what arrives", "note": "Belgian street food, also called « un français » in some places. Around €7–9. Order it in France and you will be met with confusion.", "expl": "« Une mitraillette américain-samouraï » = baguette, raw minced beef, chips and spicy sauce. A whole meal in one hand."}, {"id": "fvc-festival-A2-29", "level": "A2", "pos": "noun", "gender": "f", "fr": "les bottes", "en": "the wellies / boots", "format": "en2fr", "options": ["les bottes", "les baskets", "les sandales", "les pantoufles"], "a": 0, "trap": "les baskets — trainers, which will not survive a Belgian festival field", "expl": "« Des bottes en caoutchouc » = rubber boots. In Belgium, bring them in July."}, {"id": "fvc-festival-A2-30", "level": "A2", "pos": "noun", "gender": "m", "fr": "le K-way", "en": "the rain jacket", "format": "fr2en", "options": ["a light waterproof jacket", "a rucksack", "a folding chair", "a poncho"], "a": 0, "trap": "le poncho — the plastic cape they sell at the gate for €5", "note": "The brand name became the everyday word in both Belgium and France. Pronounced 'ka-way'.", "expl": "« Prends ton K-way, il va dracher. » Belgian festival wisdom in one sentence."}, {"id": "fvc-festival-A2-31", "level": "A2", "pos": "noun", "gender": "f", "fr": "la boue", "en": "the mud", "format": "fr2en", "options": ["the mud", "the dust", "the puddle", "the grass"], "a": 0, "trap": "la flaque — a puddle; the mud is what the puddle becomes after 20,000 people", "expl": "« Il y a de la boue partout. » Pronounced like 'boo'. Adjective: « boueux »."}, {"id": "fvc-festival-A2-32", "level": "A2", "pos": "noun", "gender": "f", "fr": "la sécurité", "en": "the security staff", "format": "cloze", "q": "Demande à la ___ , ils ont un objet perdu.", "options": ["sécurité", "buvette", "borne", "scène"], "a": 0, "trap": "buvette — feminine and grammatical, but the bar staff do not keep lost property", "expl": "All four are feminine nouns that fit. « La sécurité » means both the concept and the people in yellow jackets. Say vous to them."}, {"id": "fvc-festival-A2-33", "level": "A2", "pos": "noun", "gender": "m", "fr": "le poste de secours", "en": "the first-aid point", "format": "en2fr", "options": ["le poste de secours", "le poste de police", "le point de rencontre", "le bureau des objets trouvés"], "a": 0, "trap": "le bureau des objets trouvés — lost property, a different tent entirely", "expl": "Croix-Rouge de Belgique volunteers run it. « Où est le poste de secours ? » is worth knowing before you need it."}, {"id": "fvc-festival-A2-34", "level": "A2", "pos": "verb", "fr": "perdre", "en": "to lose", "format": "fr2en", "options": ["to lose something", "to waste time only", "to let go of a rope", "to break"], "a": 0, "trap": "perdre son temps does mean to waste time — but the core meaning is to lose", "expl": "« J'ai perdu mon portefeuille. » Reflexive « se perdre » = to get lost."}, {"id": "fvc-festival-A2-35", "level": "A2", "pos": "noun", "gender": "m", "fr": "le portefeuille", "en": "the wallet", "format": "en2fr", "options": ["le portefeuille", "le portemonnaie", "le portable", "le porte-clés"], "a": 0, "trap": "le portemonnaie — a purse for coins only; the portefeuille holds notes and cards", "expl": "Four « porte- » words: portefeuille (wallet), portemonnaie (coin purse), portable (mobile/laptop), porte-clés (keyring)."}, {"id": "fvc-festival-A2-36", "level": "A2", "pos": "verb", "fr": "danser", "en": "to dance", "format": "cloze", "q": "On va ___ devant la grande scène ?", "options": ["danser", "manger", "attendre", "payer"], "a": 0, "trap": "attendre — grammatical, and you will do plenty of it, but not in front of the main stage", "expl": "All four are infinitives that fit after « on va ». « Aller + infinitif » is the near future."}, {"id": "fvc-festival-A2-37", "level": "A2", "pos": "noun", "gender": "f", "fr": "la sono", "en": "the sound system", "format": "fr2en", "options": ["the PA / sound system", "the soundcheck", "the sound engineer", "the volume knob"], "a": 0, "trap": "le son — the sound itself; « la sono » is the equipment", "expl": "Short for « la sonorisation ». « La sono est trop forte » = the sound's too loud."}, {"id": "fvc-festival-A2-38", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'affiche", "en": "the poster / line-up", "format": "fr2en", "options": ["the poster listing who plays", "the noticeboard", "the ticket", "the stage backdrop"], "a": 0, "trap": "le panneau — the board the poster is stuck on", "expl": "« Il y a du beau monde à l'affiche cette année » = there's a great line-up. « Afficher » = to display."}, {"id": "fvc-festival-A2-39", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tête d'affiche", "en": "the headliner", "format": "en2fr", "options": ["la tête d'affiche", "la première partie", "la scène principale", "la programmation"], "a": 0, "trap": "la première partie — the support act, the opposite end of the evening", "expl": "Literally 'head of the poster'. « La tête d'affiche joue à vingt-trois heures. »"}, {"id": "fvc-festival-A2-40", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bénévole", "en": "the volunteer", "format": "fr2en", "options": ["the unpaid volunteer", "the well-wisher", "the benefactor who donates money", "the seasonal employee"], "a": 0, "trap": "le bienfaiteur — a benefactor, who gives money rather than time", "expl": "Belgian festivals run on them: work three shifts and you get in free. « Je suis bénévole cette année. »"}, {"id": "fvc-festival-A2-41", "level": "A2", "pos": "verb", "fr": "récupérer", "en": "to get back", "format": "en2fr", "options": ["récupérer", "reprendre", "retrouver", "recevoir"], "a": 0, "trap": "retrouver — to find something again after losing it; « récupérer » is collecting what is owed to you", "expl": "« Je récupère la consigne à la fin. » Also « récupérer » = to recover, after a long night."}, {"id": "fvc-festival-A2-42", "level": "A2", "pos": "adj", "fr": "réduit", "en": "reduced (rate)", "format": "fr2en", "options": ["at a reduced rate", "shrunk in size", "cancelled", "sold out"], "a": 0, "trap": "épuisé — sold out, the other word on a ticket page", "expl": "« Tarif réduit » for students, under-26s and job-seekers in Belgium. Bring the card that proves it."}, {"id": "fvc-festival-A2-43", "level": "A2", "pos": "noun", "gender": "m", "fr": "le cashless", "en": "the cashless payment system", "format": "fr2en", "options": ["a wristband loaded with credit instead of tokens", "payment by bank card at the bar", "a discount for paying online", "the token refund desk"], "a": 0, "note": "Belgian festivals have moved this way fast — Dour, Tomorrowland and now most of Brussels' events. The word is used in French exactly as in English, masculine.", "trap": "sans contact — contactless card payment, which is a different technology and works outside the gates too", "expl": "« Le festival est en cashless cette année. » You top up the wristband at a borne or in the app."}, {"id": "fvc-festival-A2-44", "level": "A2", "pos": "noun", "gender": "f", "fr": "la foule", "en": "the crowd", "format": "en2fr", "options": ["la foule", "la file", "la bande", "l'équipe"], "a": 0, "trap": "la file — a queue, a crowd in an orderly line", "expl": "« Il y a une foule énorme devant la scène. » « Se perdre dans la foule » = to get lost in the crowd."}, {"id": "fvc-festival-A2-45", "level": "A2", "pos": "expr", "fr": "combien de jetons", "en": "how many tokens", "format": "collocation", "q": "Vous voulez savoir le prix d'une bière en jetons. Que demandez-vous ?", "options": ["Une bière, c'est combien de jetons ?", "Une bière, c'est combien des jetons ?", "Une bière, combien de jetons c'est ?", "Une bière, c'est quel jeton ?"], "a": 0, "trap": "« combien des jetons » — after « combien » the partitive collapses to « de », never « des »", "expl": "« Combien de + noun » always, with no article. At Couleur Café a beer is two jetons at €2.60 each."}], "phrases": [{"id": "ph-festival-A2-01", "fr": "Tu as pris ton billet en prévente ?", "en": "Did you get your ticket in advance?", "note": "« Prendre un billet » is the normal verb, not « acheter ». Advance tickets are usually €10–20 cheaper."}, {"id": "ph-festival-A2-02", "fr": "Il reste des places pour aujourd'hui ?", "en": "Are there any tickets left for today?", "note": "« Il reste » is impersonal and never changes. The answer you fear is « non, c'est complet »."}, {"id": "ph-festival-A2-03", "fr": "Un billet pour aujourd'hui, s'il te plaît.", "en": "One ticket for today, please.", "note": "Tu with a volunteer your own age at the window. A day ticket at Couleur Café runs about €65."}, {"id": "ph-festival-A2-04", "fr": "C'est combien, le pass trois jours ?", "en": "How much is the three-day pass?", "note": "Dislocation puts the important word at the end — that is how the question really gets asked. Expect about €135."}, {"id": "ph-festival-A2-05", "fr": "Est-ce qu'il y a un tarif réduit pour les étudiants ?", "en": "Is there a student rate?", "note": "In Belgium reductions usually cover students, under-26s and job-seekers. Bring the card."}, {"id": "ph-festival-A2-06", "fr": "Je paie par Bancontact, c'est possible ?", "en": "Can I pay by debit card?", "note": "Yes at the ticket window; inside the site you will need jetons or a cashless wristband instead."}, {"id": "ph-festival-A2-07", "fr": "Où est-ce qu'on achète les jetons ?", "en": "Where do you buy the tokens?", "note": "« On » for people in general. The answer is « à la borne » — usually just past the bag search."}, {"id": "ph-festival-A2-08", "fr": "Je voudrais dix jetons, s'il te plaît.", "en": "I'd like ten tokens, please.", "note": "Buy fewer than you think. Leftover jetons are often refundable only online, or not at all."}, {"id": "ph-festival-A2-09", "fr": "Une bière, c'est combien de jetons ?", "en": "How many tokens is a beer?", "note": "« Combien de » with no article. Two jetons at €2.60 each, plus one for the cup deposit."}, {"id": "ph-festival-A2-10", "fr": "Il y a une consigne sur le gobelet ?", "en": "Is there a deposit on the cup?", "note": "Reusable cups have been compulsory at Brussels events since 2019, so the answer is always yes — €1 to €2."}, {"id": "ph-festival-A2-11", "fr": "Je récupère la consigne à la fin ?", "en": "Do I get the deposit back at the end?", "note": "« Récupérer » = to get back what is yours. Hand the cup in at any bar on site."}, {"id": "ph-festival-A2-12", "fr": "Ne l'enlève pas, c'est ton entrée pour la journée.", "en": "Don't take it off, it's your ticket for the day.", "note": "Negative imperative with a pronoun: ne + le + verb + pas. Wristbands are waterproof and non-transferable."}, {"id": "ph-festival-A2-13", "fr": "On se retrouve où, si on se perd ?", "en": "Where do we meet if we get separated?", "note": "Agree this before you go in. « Se perdre » = to get lost; phone signal at a Belgian festival is not to be trusted."}, {"id": "ph-festival-A2-14", "fr": "Le groupe joue à quelle heure ?", "en": "What time is the band on?", "note": "« À quelle heure » at the end is the spoken order. Answer: « à vingt heures », using the 24-hour clock."}, {"id": "ph-festival-A2-15", "fr": "C'est où, la grande scène ?", "en": "Where's the main stage?", "note": "« C'est où » is how the question is really asked. Written French would be « où se trouve la grande scène ? »."}, {"id": "ph-festival-A2-16", "fr": "Il y a un poste de secours par ici ?", "en": "Is there a first-aid point around here?", "note": "Run by Croix-Rouge volunteers. « Par ici » = around here, vaguer and more natural than « ici »."}, {"id": "ph-festival-A2-17", "fr": "J'ai perdu mon portefeuille, il faut aller où ?", "en": "I've lost my wallet, where do I need to go?", "note": "« Il faut aller où ? » is impersonal and easier than « où dois-je aller ? ». Ask la sécurité — and use vous with them."}, {"id": "ph-festival-A2-18", "fr": "Prends ton K-way, il va pleuvoir.", "en": "Bring your rain jacket, it's going to rain.", "note": "In Brussels the Belgian version is « il va dracher ». A K-way weighs nothing and saves the evening."}, {"id": "ph-festival-A2-19", "fr": "On prend le métro jusqu'à Heysel, c'est la ligne 6.", "en": "We'll take the metro to Heysel, it's line 6.", "note": "STIB line 6 stops at Heysel/Heizel, at the Atomium, right by the parc d'Osseghem. Buy the ticket before you get on."}, {"id": "ph-festival-A2-20", "fr": "C'était génial ! On revient l'année prochaine ?", "en": "That was brilliant! Shall we come back next year?", "note": "« Génial » is the everyday superlative among young people. « L'année prochaine » — no preposition needed."}], "dialogue": [{"who": "friend", "fr": "Salut ! Tu as pris ton billet en prévente ?", "en": "Hi! Did you get your ticket in advance?", "gloss": {"billet": "ticket", "prévente": "advance sale"}}, {"who": "you", "fr": "Non, je vais l'acheter à la caisse du jour.", "en": "No, I'm going to buy it at the box office today.", "gloss": {"caisse du jour": "box office on the day"}, "accept": ["non je vais l'acheter à la caisse du jour", "non je vais l'acheter sur place", "non je l'achète à la caisse du jour", "non je vais le prendre à la caisse du jour", "pas encore je vais l'acheter à la caisse du jour", "non je vais acheter mon billet à la caisse du jour"]}, {"who": "friend", "fr": "Ok, le guichet est là-bas, à gauche. Il y a un peu de file.", "en": "OK, the ticket window is over there, on the left. There's a bit of a queue.", "gloss": {"guichet": "ticket window", "file": "queue (Belgium; France: la queue)"}}, {"who": "you", "fr": "Ce n'est pas grave, j'attends.", "en": "That's fine, I'll wait.", "gloss": {"attends": "will wait"}, "accept": ["ce n'est pas grave j'attends", "pas grave j'attends", "ce n'est pas grave je vais attendre", "pas de souci j'attends", "ce n'est pas grave j'attends un peu", "d'accord j'attends"]}, {"who": "seller", "fr": "Salut ! C'est pour aujourd'hui ou tu prends le pass trois jours ?", "en": "Hi! Is it for today or are you taking the three-day pass?", "gloss": {"pass": "multi-day ticket"}}, {"who": "you", "fr": "Juste pour aujourd'hui, s'il te plaît. C'est combien ?", "en": "Just for today, please. How much is it?", "gloss": {"Juste": "just / only"}, "accept": ["juste pour aujourd'hui s'il te plaît c'est combien", "juste pour aujourd'hui c'est combien", "pour aujourd'hui s'il te plaît c'est combien", "juste aujourd'hui s'il te plaît c'est combien", "un billet pour aujourd'hui s'il te plaît c'est combien", "juste pour aujourd'hui merci c'est combien"]}, {"who": "seller", "fr": "Soixante-cinq euros. Tu as une carte étudiant ? Il y a un tarif réduit.", "en": "Sixty-five euros. Have you got a student card? There's a reduced rate.", "gloss": {"tarif réduit": "reduced rate"}}, {"who": "you", "fr": "Non, je n'en ai pas. Je paie par Bancontact.", "en": "No, I haven't got one. I'll pay by debit card.", "gloss": {"je n'en ai pas": "I haven't got one", "Bancontact": "Belgian debit-card system"}, "accept": ["non je n'en ai pas je paie par bancontact", "non je n'en ai pas", "non je n'ai pas je paie par bancontact", "non je n'en ai pas je paye par bancontact", "non malheureusement je paie par bancontact", "non je n'en ai pas est-ce que je peux payer par bancontact"]}, {"who": "seller", "fr": "Voilà ton bracelet. Ne l'enlève pas, c'est ton entrée pour toute la journée.", "en": "Here's your wristband. Don't take it off, it's your ticket for the whole day.", "gloss": {"bracelet": "wristband", "enlève": "take off"}}, {"who": "you", "fr": "Merci. Où est-ce qu'on achète les jetons ?", "en": "Thanks. Where do you buy the tokens?", "gloss": {"jetons": "tokens"}, "accept": ["merci où est-ce qu'on achète les jetons", "où est-ce qu'on achète les jetons", "merci et où on achète les jetons", "merci où on achète les jetons", "et les jetons on les achète où", "merci où est-ce que j'achète les jetons"]}, {"who": "seller", "fr": "Aux bornes, juste après la fouille. Un jeton, c'est deux euros soixante.", "en": "At the terminals, just after the bag search. One token is two euros sixty.", "gloss": {"bornes": "top-up terminals", "fouille": "bag search"}}, {"who": "you", "fr": "D'accord, merci beaucoup ! Bonne journée.", "en": "OK, thanks a lot! Have a good day.", "gloss": {"Bonne journée": "have a good day"}, "accept": ["d'accord merci beaucoup bonne journée", "merci beaucoup bonne journée", "d'accord merci beaucoup", "ok merci beaucoup bonne journée", "super merci beaucoup bonne journée", "merci bonne journée"]}, {"who": "friend", "fr": "Alors, tu as ton bracelet ? On prend des jetons ?", "en": "So, have you got your wristband? Shall we get some tokens?", "gloss": {"Alors": "so / well then"}}, {"who": "you", "fr": "Oui, j'en prends dix. Une bière, c'est combien de jetons ?", "en": "Yes, I'll get ten. How many tokens is a beer?", "gloss": {"j'en prends dix": "I'll take ten of them", "combien de": "how many"}, "accept": ["oui j'en prends dix une bière c'est combien de jetons", "oui j'en prends dix", "oui une bière c'est combien de jetons", "j'en prends dix une bière c'est combien de jetons", "oui je vais en prendre dix une bière c'est combien de jetons", "oui j'en prends dix et une bière c'est combien de jetons"]}, {"who": "friend", "fr": "Deux jetons, plus un pour la consigne du gobelet.", "en": "Two tokens, plus one for the deposit on the cup.", "gloss": {"consigne": "deposit", "gobelet": "reusable cup"}}, {"who": "you", "fr": "Et je récupère la consigne à la fin ?", "en": "And do I get the deposit back at the end?", "gloss": {"récupère": "get back"}, "accept": ["et je récupère la consigne à la fin", "je récupère la consigne à la fin", "et on récupère la consigne à la fin", "et je récupère le jeton à la fin", "est-ce que je récupère la consigne à la fin", "et la consigne je la récupère à la fin"]}, {"who": "friend", "fr": "Oui, tu rends le gobelet et on te rend le jeton. Bon, ça commence sur la grande scène !", "en": "Yes, you hand the cup back and they give you the token. Right, it's starting on the main stage!", "gloss": {"rends": "hand back", "grande scène": "main stage"}}, {"who": "you", "fr": "Allons-y ! Qui joue en premier ?", "en": "Let's go! Who's on first?", "gloss": {"Allons-y": "let's go", "en premier": "first"}, "accept": ["allons-y qui joue en premier", "allons-y", "on y va qui joue en premier", "allons-y qui est-ce qui joue en premier", "super allons-y qui joue en premier", "d'accord allons-y qui joue en premier"]}], "exercises": [{"id": "ex-festival-A2-01", "level": "A2", "format": "fr2en", "q": "le jeton", "options": ["the token you pay with inside the festival", "a coin of the realm", "the entry stamp", "the wristband"], "a": 0, "expl": "About €2.60 at Couleur Café. Worthless outside the gates."}, {"id": "ex-festival-A2-02", "level": "A2", "format": "en2fr", "q": "the deposit on the cup", "options": ["la consigne", "la caution", "la commission", "la contribution"], "a": 0, "expl": "« La consigne » — also the word for left luggage at a station and for instructions in the plural."}, {"id": "ex-festival-A2-03", "level": "A2", "format": "cloze", "q": "Il y a une ___ à l'entrée : ouvre ton sac.", "options": ["fouille", "borne", "buvette", "scène"], "a": 0, "expl": "All four are feminine nouns that fit. Only « la fouille » involves opening your bag."}, {"id": "ex-festival-A2-04", "level": "A2", "format": "fr2en", "q": "la mitraillette", "options": ["a baguette with meat, chips and sauce (Belgium)", "a machine gun", "a plate of small sausages", "a fast queue"], "a": 0, "expl": "Belgian street food, €7–9. In France the word only means the weapon."}, {"id": "ex-festival-A2-05", "level": "A2", "format": "fr2en", "q": "la prévente", "options": ["tickets sold in advance, usually cheaper", "tickets resold second-hand", "the pre-show soundcheck", "the merchandise pre-order"], "a": 0, "expl": "« J'ai pris mon billet en prévente » — €10 to €20 cheaper than at the gate. Reselling is « la revente »."}, {"id": "ex-festival-A2-06", "level": "A2", "format": "fr2en", "q": "attendre", "options": ["to wait", "to attend an event", "to expect a result", "to listen out for"], "a": 0, "expl": "False friend. To attend is « assister à »."}, {"id": "ex-festival-A2-07", "level": "A2", "format": "en2fr", "q": "the wristband", "options": ["le bracelet", "le collier", "le badge", "le ruban"], "a": 0, "expl": "« Ne l'enlève pas » — the bracelet is the ticket."}, {"id": "ex-festival-A2-08", "level": "A2", "format": "cloze", "q": "On prend le métro jusqu'à ___ , c'est la ligne 6.", "options": ["Heysel", "Flagey", "Châtelain", "Boondael"], "a": 0, "expl": "All four are Brussels place names that fit grammatically. Only Heysel/Heizel is on a metro line — Flagey, Châtelain and Boondael are served by trams or trains, not the metro."}, {"id": "ex-festival-A2-09", "level": "A2", "format": "fr2en", "q": "la tête d'affiche", "options": ["the headline act", "the support act", "the main stage", "the festival poster"], "a": 0, "expl": "Literally 'head of the poster'. The support act is « la première partie »."}, {"id": "ex-festival-A2-10", "level": "A2", "format": "en2fr", "q": "to get (something) back", "options": ["récupérer", "retrouver", "reprendre", "recevoir"], "a": 0, "expl": "« Je récupère la consigne. » « Retrouver » is finding something you had lost."}, {"id": "ex-festival-A2-11", "level": "A2", "format": "cloze", "q": "Prends ton ___ , il va pleuvoir toute la journée.", "options": ["K-way", "billet", "jeton", "programme"], "a": 0, "expl": "All four are masculine nouns you might carry. Only a K-way helps with rain."}, {"id": "ex-festival-A2-12", "level": "A2", "format": "fr2en", "q": "le bénévole", "options": ["the unpaid volunteer", "the benefactor who gives money", "the seasonal worker", "the season-ticket holder"], "a": 0, "expl": "Work a few shifts at a Belgian festival and you get in free."}, {"id": "ex-festival-A2-13", "level": "A2", "format": "collocation", "q": "Vous avez perdu votre portefeuille. À qui parlez-vous, et comment ?", "options": ["À la sécurité, avec « vous »", "À la sécurité, avec « tu »", "Au barman, avec « vous »", "À un bénévole, avec « vous » obligatoirement"], "a": 0, "expl": "Tu is the festival default among punters and young volunteers, but security staff are doing an official job — use vous with them."}, {"id": "ex-festival-A2-14", "level": "A2", "format": "en2fr", "q": "the crowd", "options": ["la foule", "la file", "la bande", "le groupe"], "a": 0, "expl": "« Une foule énorme. » « La file » is an orderly queue."}]},
  "festival-B1": {"slug": "festival", "level": "B1", "title": "Au festival — complet, et tout en cashless", "place": "Couleur Café, parc d'Osseghem, Laeken, Bruxelles", "register": "tu", "registerNote": "Tu with your friends and with the young volunteers on the gate, exactly as at A2 — but at B1 you also handle the awkward conversations in it: the ticket is sold out, the terminal is broken, you want your money back. Informal grammar comes with it (« ça marche », « laisse tomber », dropped ne). Switch to vous the moment you are talking to security, first aid or police — a Belgian steward hearing tu from a stranger during an incident will not take it well.", "vocab": [{"id": "fvc-festival-B1-01", "level": "B1", "pos": "adj", "fr": "complet", "en": "sold out / full", "format": "cloze", "q": "Désolé, pour aujourd'hui c'est ___ , il n'y a plus un seul billet.", "options": ["complet", "gratuit", "réduit", "ouvert"], "a": 0, "trap": "ouvert — a masculine adjective that fits the slot and describes the gates rather than the ticket situation", "expl": "All four are masculine adjectives. « C'est complet » = we're full. On the website you will see « SOLD OUT » or « épuisé »."}, {"id": "fvc-festival-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la bourse d'échange", "en": "the official ticket exchange", "format": "fr2en", "options": ["the official platform where fans resell tickets at face value", "the stock exchange", "the student grant office", "the merchandise stand"], "a": 0, "trap": "« une bourse » is also a grant and a stock exchange — the third meaning is a swap market", "note": "Belgian law caps ticket resale at the original price, so festivals run their own « bourse d'échange » or « ticket swap ». Buying from a stranger on Facebook is both illegal to overpay for and usually a scam.", "expl": "« Passe par la bourse d'échange officielle » — the ticket is re-issued in your name, so the QR code actually scans."}, {"id": "fvc-festival-B1-03", "level": "B1", "pos": "verb", "fr": "revendre", "en": "to resell", "format": "en2fr", "options": ["revendre", "vendre", "rendre", "racheter"], "a": 0, "trap": "racheter — to buy back, the same transaction seen from the other side", "expl": "« Des gens revendent leur billet au prix d'origine. » Reselling above face value is illegal in Belgium."}, {"id": "fvc-festival-B1-04", "level": "B1", "pos": "noun", "gender": "m", "fr": "le QR code", "en": "the QR code", "format": "fr2en", "options": ["the square barcode scanned at the gate", "the reference number of a booking", "the security chip in a wristband", "the app's login code"], "a": 0, "trap": "le code secret — your card PIN, a different four digits entirely", "expl": "Said 'ku-erre code' in French. « Ton QR code ne passe pas » = your code won't scan — usually a screen-brightness problem."}, {"id": "fvc-festival-B1-05", "level": "B1", "pos": "expr", "fr": "à ton nom", "en": "in your name", "format": "collocation", "q": "Le billet doit être enregistré au nom de l'acheteur. Quelle phrase est correcte ?", "options": ["Il faut que le billet soit à ton nom", "Il faut que le billet est à ton nom", "Il faut que le billet soit sur ton nom", "Il faut que le billet soit au ton nom"], "a": 0, "trap": "« sur ton nom » — the preposition is à, and « il faut que » forces the subjunctive « soit »", "expl": "Belgian festivals put the buyer's name on the ticket to kill the black market. « Mettre le billet à son nom » = to register it in your name."}, {"id": "fvc-festival-B1-06", "level": "B1", "pos": "verb", "fr": "annuler", "en": "to cancel", "format": "fr2en", "options": ["to cancel", "to postpone", "to confirm", "to reimburse"], "a": 0, "trap": "reporter — to postpone; a festival can « reporter » a set without « annuler » it", "expl": "« Ton bracelet est annulé » = your wristband has been deactivated. The noun is « une annulation »."}, {"id": "fvc-festival-B1-07", "level": "B1", "pos": "verb", "fr": "ressortir", "en": "to go back out", "format": "fr2en", "options": ["to go back out of a place you have entered", "to stand out visually", "to come out again in a new version", "to take something out of a bag"], "a": 0, "trap": "sortir — simply to go out; the re- means you had already gone in", "expl": "« Si tu ressors, tu ne peux plus rentrer. » Most Belgian one-day festivals have no re-entry — plan around it."}, {"id": "fvc-festival-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le chapiteau", "en": "the marquee / big top", "format": "en2fr", "options": ["le chapiteau", "le kiosque", "l'abri", "le hangar"], "a": 0, "trap": "l'abri — any shelter; « un chapiteau » is specifically the big circus-style tent", "expl": "« On se met sous le chapiteau » is what you say the moment it starts raining, which in Brussels is most Julys."}, {"id": "fvc-festival-B1-09", "level": "B1", "pos": "expr", "fr": "en panne", "en": "out of order", "format": "cloze", "q": "La borne à jetons est en ___ , il faut passer par l'appli.", "options": ["panne", "route", "service", "travaux"], "a": 0, "trap": "service — « en service » is a real phrase meaning working, i.e. the opposite", "expl": "All four follow « en » in real phrases. « En panne » = broken down; « en travaux » = under repair; « en route » = on the way."}, {"id": "fvc-festival-B1-10", "level": "B1", "pos": "noun", "gender": "f", "fr": "la recharge", "en": "the top-up", "format": "fr2en", "options": ["adding credit to a card or wristband", "a refill of a drink", "a second charge on your bank account", "a spare battery"], "a": 0, "trap": "la charge — a load or a burden; only « recharge » is the top-up", "expl": "« Il y a un minimum de recharge ? » — usually €10 at a Belgian festival. The verb is « recharger »."}, {"id": "fvc-festival-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "les frais", "en": "the fees / charges", "format": "fr2en", "options": ["the administrative charges", "the fresh produce", "the expenses claimed back from work", "the cool weather"], "a": 0, "trap": "« frais » is also the adjective meaning fresh or cool — identical spelling, different word", "expl": "Always plural: « des frais de dossier », « des frais de remboursement ». Festival refunds typically cost €2 in frais."}, {"id": "fvc-festival-B1-12", "level": "B1", "pos": "noun", "gender": "m", "fr": "le crédit", "en": "the credit left on the wristband", "format": "en2fr", "options": ["le crédit", "le solde", "la dette", "l'avoir"], "a": 0, "trap": "le solde — the balance, which means the same thing in a bank app but not on a festival wristband", "expl": "« Il me reste douze euros de crédit. » Unused credit is refunded online, minus fees, in the weeks after."}, {"id": "fvc-festival-B1-13", "level": "B1", "pos": "noun", "gender": "f", "fr": "la somme", "en": "the amount of money", "format": "fr2en", "options": ["the amount of money", "the nap", "the summary", "the total of a maths problem only"], "a": 0, "trap": "« un somme » (masculine) is a nap and « une somme » is a sum — the gender is the only clue", "expl": "« Une somme importante » = a large amount. « En somme » = in short."}, {"id": "fvc-festival-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'appli", "en": "the app", "format": "fr2en", "options": ["the smartphone app", "the application form", "the applied science", "the applause"], "a": 0, "trap": "« une application » means both the app and a formal application — « appli » only ever means the phone one", "expl": "Short for « l'application ». « Télécharge l'appli du festival » — the line-up, the map and your cashless credit all live in it."}, {"id": "fvc-festival-B1-15", "level": "B1", "pos": "noun", "gender": "m", "fr": "le réseau", "en": "the (phone) network / signal", "format": "en2fr", "options": ["le réseau", "le signal", "la connexion", "la couverture"], "a": 0, "trap": "la connexion — your internet connection, which can fail even with perfect réseau", "expl": "« Je n'ai pas de réseau » = I've got no signal. Proximus, Orange and Base are the three Belgian operators."}, {"id": "fvc-festival-B1-16", "level": "B1", "pos": "verb", "fr": "capter", "en": "to get a signal", "format": "fr2en", "options": ["to pick up a phone signal", "to capture an animal", "to understand quickly", "to record a sound"], "a": 0, "trap": "in slang « je capte pas » also means 'I don't get it' — same verb, two lives", "expl": "« Ça capte mal ici. » Twenty thousand people in one field will finish your signal off."}, {"id": "fvc-festival-B1-17", "level": "B1", "pos": "noun", "gender": "f", "fr": "la batterie", "en": "the battery", "format": "cloze", "q": "Ma ___ est à cinq pour cent, je vais couper le wifi.", "options": ["batterie", "connexion", "appli", "recharge"], "a": 0, "trap": "recharge — feminine and grammatical, but a top-up cannot be at five per cent", "expl": "All four are feminine nouns that fit. « Je n'ai plus de batterie » = my phone's dead — the phone, not the battery, is what dies in English."}, {"id": "fvc-festival-B1-18", "level": "B1", "pos": "noun", "gender": "f", "fr": "la batterie externe", "en": "the power bank", "format": "en2fr", "options": ["la batterie externe", "la prise électrique", "la rallonge", "le chargeur"], "a": 0, "trap": "le chargeur — the charger, which is useless in a field with no socket", "expl": "Also « un powerbank », used in French in Belgium. Essential if your ticket and your money are both on your GSM."}, {"id": "fvc-festival-B1-19", "level": "B1", "pos": "noun", "gender": "m", "fr": "le point de rencontre", "en": "the meeting point", "format": "fr2en", "options": ["the agreed spot where you find each other", "the intersection of two paths", "the information desk", "the moment two acts overlap"], "a": 0, "trap": "le point info — the information stand, which is where you go for a map, not for your friends", "expl": "Agree one before you go in. « On se donne rendez-vous au point de rencontre à minuit. »"}, {"id": "fvc-festival-B1-20", "level": "B1", "pos": "expr", "fr": "se donner rendez-vous", "en": "to arrange to meet", "format": "en2fr", "options": ["se donner rendez-vous", "prendre rendez-vous", "avoir rendez-vous", "donner un rendez-vous"], "a": 0, "trap": "prendre rendez-vous — to book an appointment, with a doctor or a bank, not with friends", "expl": "« On se donne rendez-vous où ? » Between friends it is « se donner rendez-vous »; with a professional, « prendre rendez-vous »."}, {"id": "fvc-festival-B1-21", "level": "B1", "pos": "noun", "gender": "m", "fr": "le créneau", "en": "the time slot", "format": "fr2en", "options": ["the slot in a timetable", "the gap in a wall", "the parking manoeuvre only", "the stage barrier"], "a": 0, "trap": "« faire un créneau » is to parallel-park, which is where most learners meet the word", "expl": "« Leur créneau est de vingt et une heures à vingt-deux heures. » Also used for meetings and appointments."}, {"id": "fvc-festival-B1-22", "level": "B1", "pos": "verb", "fr": "se chevaucher", "en": "to overlap / clash", "format": "fr2en", "options": ["to overlap in time", "to ride a horse together", "to compete for the same prize", "to follow one after the other"], "a": 0, "trap": "se suivre — to follow one another, which is the happy version of the same schedule", "expl": "« Les deux concerts se chevauchent, il va falloir choisir. » From « le cheval » by way of riding one thing over another."}, {"id": "fvc-festival-B1-23", "level": "B1", "pos": "verb", "fr": "rater", "en": "to miss (an act, a train)", "format": "cloze", "q": "Si on part maintenant, on va ___ la fin du concert.", "options": ["rater", "manquer", "perdre", "quitter"], "a": 0, "trap": "manquer — genuinely correct here too, but « manquer » is the more formal register and « rater » is what everyone says", "expl": "All four are infinitives that fit. « Rater » is informal and universal: rater le train, rater un examen, rater une photo."}, {"id": "fvc-festival-B1-24", "level": "B1", "pos": "noun", "gender": "f", "fr": "la première partie", "en": "the support act", "format": "en2fr", "options": ["la première partie", "la tête d'affiche", "la répétition", "l'ouverture"], "a": 0, "trap": "la tête d'affiche — the headliner, the other end of the bill", "expl": "« Qui fait la première partie ? » Often the best discovery of the evening, and nobody is there yet."}, {"id": "fvc-festival-B1-25", "level": "B1", "pos": "noun", "gender": "m", "fr": "le rappel", "en": "the encore", "format": "fr2en", "options": ["the encore", "the reminder email only", "the recall of a faulty product only", "the repeat of a song within a set"], "a": 0, "trap": "the word does mean a reminder and a product recall — the concert meaning is a third life", "expl": "The crowd shouts « une autre ! » in French, not « encore ! ». « Ils sont revenus pour un rappel. »"}, {"id": "fvc-festival-B1-26", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fosse", "en": "the pit (standing area at the front)", "format": "fr2en", "options": ["the standing area right in front of the stage", "the orchestra's sunken area only", "the ditch around the site", "the space between two stages"], "a": 0, "trap": "la foule — the crowd; « la fosse » is the physical area it stands in", "expl": "« Descendre dans la fosse » = to get down the front. Also « la fosse d'orchestre » in a theatre."}, {"id": "fvc-festival-B1-27", "level": "B1", "pos": "noun", "gender": "f", "fr": "la barrière", "en": "the crash barrier", "format": "en2fr", "options": ["la barrière", "la clôture", "le portail", "la rambarde"], "a": 0, "trap": "la clôture — a fence around a field, and also the closing of an event", "expl": "« Être à la barrière » = to be right at the front. Get there two acts early."}, {"id": "fvc-festival-B1-28", "level": "B1", "pos": "noun", "gender": "m", "fr": "les bouchons d'oreilles", "en": "the earplugs", "format": "fr2en", "options": ["the earplugs", "the traffic jams", "the corks of bottles", "the headphones"], "a": 0, "trap": "« un bouchon » alone is a cork or a traffic jam — « d'oreilles » is doing all the work", "note": "Belgian festivals must offer earplugs by law and hand them out free at the info point; the sound limit is 100 dB(A) averaged.", "expl": "« Tu as des bouchons ? » Everyone under thirty in Brussels now wears them at gigs."}, {"id": "fvc-festival-B1-29", "level": "B1", "pos": "adj", "fr": "assourdissant", "en": "deafening", "format": "en2fr", "options": ["assourdissant", "bruyant", "sourd", "silencieux"], "a": 0, "trap": "sourd — deaf, the result rather than the cause", "expl": "« Une sono assourdissante ». From « sourd » (deaf) — literally 'deafening'."}, {"id": "fvc-festival-B1-30", "level": "B1", "pos": "verb", "fr": "évacuer", "en": "to evacuate / clear an area", "format": "fr2en", "options": ["to clear people out of an area", "to escape from danger yourself", "to empty a container", "to cancel an event"], "a": 0, "trap": "s'échapper — to escape; « évacuer » is what the organisers do to you, not what you do", "expl": "« On doit évacuer la zone » is the announcement during a storm. Follow the stewards and say vous to them."}, {"id": "fvc-festival-B1-31", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'orage", "en": "the thunderstorm", "format": "fr2en", "options": ["the thunderstorm", "the strong wind", "the heavy shower without thunder", "the fog"], "a": 0, "trap": "une averse — a shower; « une drache » in Belgium. An orage has lightning, which is why festivals stop the music for it.", "expl": "« Un orage est annoncé pour ce soir. » Belgian summer festivals have a written storm protocol; the stages go dark and everyone goes to the chapiteau."}, {"id": "fvc-festival-B1-32", "level": "B1", "pos": "verb", "fr": "s'abriter", "en": "to take shelter", "format": "en2fr", "options": ["s'abriter", "se cacher", "se protéger", "s'installer"], "a": 0, "trap": "se cacher — to hide, which is about not being seen rather than not being rained on", "expl": "« On va s'abriter sous le chapiteau. » The noun is « un abri »."}, {"id": "fvc-festival-B1-33", "level": "B1", "pos": "adj", "fr": "trempé", "en": "soaked through", "format": "cloze", "q": "Je suis ___ jusqu'aux os, j'aurais dû prendre mon K-way.", "options": ["trempé", "mouillé", "humide", "gelé"], "a": 0, "trap": "mouillé — simply wet, and grammatically identical; « trempé jusqu'aux os » is the fixed phrase", "expl": "All four are masculine adjectives that fit. « Trempé » is beyond « mouillé »: nothing left dry."}, {"id": "fvc-festival-B1-34", "level": "B1", "pos": "adj", "fr": "glissant", "en": "slippery", "format": "fr2en", "options": ["slippery", "sticky", "muddy", "uneven"], "a": 0, "trap": "boueux — muddy, which is the cause; glissant is the consequence", "expl": "« Attention, c'est glissant. » From « glisser », to slip or to slide."}, {"id": "fvc-festival-B1-35", "level": "B1", "pos": "noun", "gender": "m", "fr": "le covoiturage", "en": "car sharing / lift sharing", "format": "fr2en", "options": ["sharing a car journey with others", "renting a car by the hour", "a car park reserved for the festival", "a taxi collective"], "a": 0, "trap": "la location de voiture — car hire, which is a company transaction rather than a shared lift", "expl": "« Je cherche un covoiturage pour rentrer à Ixelles. » Festivals run Facebook groups for it; Blablacar is the app."}, {"id": "fvc-festival-B1-36", "level": "B1", "pos": "noun", "gender": "m", "fr": "les transports en commun", "en": "public transport", "format": "en2fr", "options": ["les transports en commun", "les transports publics", "les moyens de transport", "les déplacements"], "a": 0, "trap": "« les transports publics » is understandable and used in Switzerland, but Belgium and France say « en commun »", "expl": "« Viens en transports en commun, il n'y a pas de parking. » Covers STIB metro, tram and bus, plus SNCB trains and De Lijn/TEC."}, {"id": "fvc-festival-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "la STIB", "en": "the Brussels transport company", "format": "fr2en", "options": ["the Brussels metro, tram and bus operator", "the Belgian national railway", "the Flemish regional bus company", "the Brussels taxi federation"], "a": 0, "trap": "la SNCB — the national railway; De Lijn and TEC are the Flemish and Walloon bus companies", "note": "Brussels-specific and bilingual: STIB in French, MIVB in Dutch, and both names appear on every vehicle. A single ticket is about €2.60; the Noctis night buses use the same fare.", "expl": "Pronounced as a word, 'stib'. « Il y a une grève à la STIB » is a sentence you will need one day."}, {"id": "fvc-festival-B1-38", "level": "B1", "pos": "noun", "gender": "m", "fr": "le tri", "en": "waste sorting", "format": "fr2en", "options": ["separating rubbish into the right bins", "the selection of the line-up", "the sorting of a queue by ticket type", "the choice between two stages"], "a": 0, "note": "Belgium takes this seriously: blue bags for plastic and metal (PMC), yellow for paper, white for the rest. Festival bins are colour-coded the same way and stewards will correct you.", "trap": "le triage — sorting in a railway or medical sense, not household waste", "expl": "« Fais le tri, les poubelles sont juste là. » The verb is « trier »."}, {"id": "fvc-festival-B1-39", "level": "B1", "pos": "noun", "gender": "m", "fr": "le vol", "en": "the theft", "format": "fr2en", "options": ["the theft", "the flight of a bird only", "the volume", "the volunteer"], "a": 0, "trap": "the same word means a flight — « le vol Bruxelles-Athènes ». Context is everything.", "expl": "« Il y a eu des vols près de la scène. » « Se faire voler son GSM » = to have your phone stolen."}, {"id": "fvc-festival-B1-40", "level": "B1", "pos": "noun", "gender": "m", "fr": "le pickpocket", "en": "the pickpocket", "format": "en2fr", "options": ["le pickpocket", "le voleur", "le cambrioleur", "le brigand"], "a": 0, "trap": "le cambrioleur — a burglar, who breaks into houses rather than pockets", "expl": "Borrowed straight from English and masculine. « Attention aux pickpockets » is written on signs at Bruxelles-Midi."}, {"id": "fvc-festival-B1-41", "level": "B1", "pos": "verb", "fr": "se méfier", "en": "to be wary of", "format": "fr2en", "options": ["to be wary of someone or something", "to distrust yourself", "to mistrust the news only", "to avoid a place"], "a": 0, "trap": "se fier à — to trust, the same root with the exact opposite meaning", "expl": "« Méfie-toi des pickpockets dans la fosse. » Always « se méfier de »."}, {"id": "fvc-festival-B1-42", "level": "B1", "pos": "noun", "gender": "f", "fr": "la banane", "en": "the bum bag", "format": "fr2en", "options": ["the bag worn round your waist", "the banana only", "the shoulder bag", "the money belt worn under clothes"], "a": 0, "trap": "the fruit meaning is the one you know; « une banane » is also a bum bag and a quiff hairstyle", "expl": "« Mets ton portefeuille dans ta banane. » The festival-proof alternative to a back pocket."}, {"id": "fvc-festival-B1-43", "level": "B1", "pos": "expr", "fr": "tant pis", "en": "never mind / too bad", "format": "fr2en", "options": ["never mind, too bad", "so much the better", "even worse than that", "at least"], "a": 0, "trap": "tant mieux — so much the better, the exact positive twin of the same structure", "expl": "The pair to learn together: « tant pis » (bad news accepted) and « tant mieux » (good news welcomed)."}, {"id": "fvc-festival-B1-44", "level": "B1", "pos": "expr", "fr": "laisse tomber", "en": "forget it / don't bother", "format": "cloze", "q": "— Je te rends les deux euros ? — Non, ___ , ça n'en vaut pas la peine.", "options": ["laisse tomber", "vas-y", "attends", "reprends"], "a": 0, "trap": "vas-y — a real imperative that fits the slot but tells him to go ahead and pay you", "expl": "All four are imperatives. « Laisse tomber » literally 'let it fall' — informal, friendly, and not at all rude between friends."}, {"id": "fvc-festival-B1-45", "level": "B1", "pos": "expr", "fr": "au fait", "en": "by the way", "format": "collocation", "q": "Vous changez de sujet dans une conversation. Quelle formule est correcte ?", "options": ["Au fait, tu as rechargé ton bracelet ?", "En fait, tu as rechargé ton bracelet ?", "Au faite, tu as rechargé ton bracelet ?", "De fait, tu as rechargé ton bracelet ?"], "a": 0, "trap": "« en fait » means 'actually / in fact' and corrects what was just said — it does not introduce a new topic", "expl": "« Au fait » opens a new subject; « en fait » corrects one. Different words, one letter apart, and learners swap them constantly."}], "phrases": [{"id": "ph-festival-B1-01", "fr": "Il n'y a vraiment plus rien à la caisse du jour ?", "en": "Is there really nothing left at the box office?", "note": "« Ne ... plus rien » = nothing left at all. Worth asking once; releases do happen an hour before the gates."}, {"id": "ph-festival-B1-02", "fr": "Est-ce qu'il y a une bourse d'échange officielle ?", "en": "Is there an official ticket exchange?", "note": "Belgian law caps resale at face value, so festivals run their own platform. Anything else is a scam or a fake QR code."}, {"id": "ph-festival-B1-03", "fr": "Il faut que le billet soit à mon nom, c'est ça ?", "en": "The ticket has to be in my name, is that right?", "note": "« Il faut que » + subjunctive « soit ». « C'est ça ? » is the standard way to check you have understood."}, {"id": "ph-festival-B1-04", "fr": "Si j'en trouve un, je peux entrer directement avec le QR code ?", "en": "If I find one, can I go straight in with the QR code?", "note": "« Si + présent, présent » for a real, likely condition. Turn your screen brightness up before you reach the scanner."}, {"id": "ph-festival-B1-05", "fr": "Est-ce que je peux ressortir et revenir plus tard ?", "en": "Can I go out and come back later?", "note": "Usually no at a one-day Belgian festival: the wristband is deactivated on exit. Ask before you go in, not after."}, {"id": "ph-festival-B1-06", "fr": "La borne est en panne, comment on fait ?", "en": "The terminal's out of order, what do we do?", "note": "« Comment on fait ? » is the everyday spoken form of « que faire ? ». Direct, not rude."}, {"id": "ph-festival-B1-07", "fr": "Tout est en cashless cette année, il faut recharger dans l'appli.", "en": "It's all cashless this year, you have to top up in the app.", "note": "« En cashless » is used exactly like that in Belgian French. Download the app on the tram, not in the field — the signal dies at the gate."}, {"id": "ph-festival-B1-08", "fr": "Il y a un minimum de recharge ?", "en": "Is there a minimum top-up?", "note": "Usually €10. Top up in small amounts: you will not get the last few euros back without effort."}, {"id": "ph-festival-B1-09", "fr": "Le crédit qui reste, je me le fais rembourser comment ?", "en": "The credit that's left, how do I get it refunded?", "note": "« Se faire + infinitif » = to have something done to you. Refunds are claimed online in the two weeks after, minus about €2 of fees."}, {"id": "ph-festival-B1-10", "fr": "Ça vaut la peine, ou il y a trop de frais ?", "en": "Is it worth it, or are the fees too high?", "note": "« Ça vaut la peine de + infinitif ». « Les frais » is always plural."}, {"id": "ph-festival-B1-11", "fr": "On se donne rendez-vous où, si on se perd ?", "en": "Where shall we meet if we get separated?", "note": "Fix a physical landmark, not a phone plan — with 20,000 people the network goes down. « Se donner rendez-vous » is for friends; « prendre rendez-vous » is for the dentist."}, {"id": "ph-festival-B1-12", "fr": "Je ne capte plus rien, ma batterie est presque vide.", "en": "I've got no signal at all any more, my battery's nearly dead.", "note": "« Capter » = to get a signal. Bring a power bank if your ticket and your money both live on your GSM."}, {"id": "ph-festival-B1-13", "fr": "Leurs deux créneaux se chevauchent, il va falloir choisir.", "en": "Their two slots clash, we'll have to choose.", "note": "« Il va falloir » = we're going to have to — the near future of « il faut »."}, {"id": "ph-festival-B1-14", "fr": "Si on part maintenant, on va rater le rappel.", "en": "If we leave now, we'll miss the encore.", "note": "« Rater » is the everyday verb for missing something; « manquer » is its more formal twin. French crowds shout « une autre ! », not 'encore'."}, {"id": "ph-festival-B1-15", "fr": "Tu as des bouchons d'oreilles en trop ?", "en": "Have you got any spare earplugs?", "note": "« En trop » = spare, extra. Belgian festivals must provide them free at the info point."}, {"id": "ph-festival-B1-16", "fr": "Un orage est annoncé, ils vont peut-être évacuer la zone.", "en": "A thunderstorm is forecast, they might clear the area.", "note": "« Être annoncé » for weather forecasts. If the stewards do evacuate, switch to vous with them and just follow instructions."}, {"id": "ph-festival-B1-17", "fr": "Je suis trempé jusqu'aux os, j'aurais dû prendre mon K-way.", "en": "I'm soaked to the skin, I should have brought my rain jacket.", "note": "« J'aurais dû + infinitif » = I should have. In Brussels the local verb for this weather is « il drache »."}, {"id": "ph-festival-B1-18", "fr": "Méfie-toi des pickpockets dans la fosse.", "en": "Watch out for pickpockets in the pit.", "note": "« Se méfier de » — always with de. Front pocket or a bum bag, never a back pocket."}, {"id": "ph-festival-B1-19", "fr": "Je rentre en transports en commun, le dernier métro est à minuit.", "en": "I'm getting home by public transport, the last metro's at midnight.", "note": "STIB metro line 6 from Heysel. After midnight, Noctis night buses from De Brouckère on Friday and Saturday."}, {"id": "ph-festival-B1-20", "fr": "Au fait, tu as rechargé ton bracelet ? Sinon, tant pis, je t'offre la première.", "en": "By the way, did you top up your wristband? If not, never mind, the first one's on me.", "note": "« Au fait » changes the subject; « en fait » would correct what was just said. « Tant pis » accepts a small setback."}], "dialogue": [{"who": "seller", "fr": "Salut ! Désolé, pour aujourd'hui c'est complet, on n'a plus rien à la caisse du jour.", "en": "Hi! Sorry, today's sold out, we've nothing left at the box office.", "gloss": {"complet": "sold out", "caisse du jour": "box office on the day"}}, {"who": "you", "fr": "Ah zut. Il n'y a vraiment aucune possibilité ? Même en tarif réduit ?", "en": "Oh no. Is there really no way at all? Even at the reduced rate?", "gloss": {"zut": "damn (mild)", "aucune": "no ... at all", "tarif réduit": "reduced rate"}, "accept": ["ah zut il n'y a vraiment aucune possibilité même en tarif réduit", "il n'y a vraiment aucune possibilité", "ah zut il n'y a vraiment plus rien", "il n'y a vraiment plus rien même en tarif réduit", "ah dommage il n'y a vraiment aucune possibilité", "et il n'y a vraiment aucune possibilité même en tarif réduit"]}, {"who": "seller", "fr": "Non, tout est parti. Par contre, il y a une bourse d'échange officielle sur le site : des gens revendent leur billet au prix d'origine.", "en": "No, it's all gone. On the other hand, there's an official ticket exchange on the website: people resell their ticket at the original price.", "gloss": {"tout est parti": "it's all gone", "bourse d'échange": "official ticket exchange", "revendent": "resell"}}, {"who": "you", "fr": "Je regarde tout de suite. Si j'en trouve un, je peux entrer directement avec le QR code ?", "en": "I'll look right now. If I find one, can I go straight in with the QR code?", "gloss": {"Si j'en trouve un": "if I find one of them", "QR code": "QR code"}, "accept": ["je regarde tout de suite si j'en trouve un je peux entrer directement avec le qr code", "je regarde tout de suite si j'en trouve un je peux entrer avec le qr code", "si j'en trouve un je peux entrer directement avec le qr code", "je vais regarder si j'en trouve un je peux entrer avec le qr code", "d'accord je regarde si j'en trouve un je peux entrer directement", "je regarde et si j'en trouve un je peux entrer avec le qr code"]}, {"who": "seller", "fr": "Oui, mais il faut que le billet soit à ton nom, sinon ça ne passera pas au contrôle.", "en": "Yes, but the ticket has to be in your name, otherwise it won't scan at the check.", "gloss": {"il faut que": "it's necessary that (+ subjunctive)", "soit": "be (subjunctive of être)", "sinon": "otherwise"}}, {"who": "you", "fr": "D'accord. Ça y est, j'en ai trouvé un ! Je le mets à mon nom et je reviens.", "en": "OK. There we go, I've found one! I'll put it in my name and come back.", "gloss": {"Ça y est": "there we go / done", "à mon nom": "in my name"}, "accept": ["d'accord ça y est j'en ai trouvé un je le mets à mon nom et je reviens", "ça y est j'en ai trouvé un je le mets à mon nom et je reviens", "j'en ai trouvé un je le mets à mon nom et je reviens", "super j'en ai trouvé un je le mets à mon nom", "d'accord j'en ai trouvé un je reviens", "ça y est j'en ai trouvé un merci je reviens"]}, {"who": "seller", "fr": "Parfait. Passe par la file de droite, elle avance plus vite.", "en": "Perfect. Go through the right-hand queue, it moves faster.", "gloss": {"file": "queue (Belgium; France: la queue)", "avance": "moves along"}}, {"who": "you", "fr": "Merci du conseil. Encore une chose : est-ce que je peux ressortir et revenir ?", "en": "Thanks for the tip. One more thing: can I go out and come back?", "gloss": {"Merci du conseil": "thanks for the tip", "ressortir": "go back out"}, "accept": ["merci du conseil encore une chose est-ce que je peux ressortir et revenir", "merci encore une chose est-ce que je peux ressortir et revenir", "est-ce que je peux ressortir et revenir", "merci du conseil est-ce que je peux ressortir et revenir", "merci une dernière question est-ce que je peux ressortir et revenir", "merci du conseil est-ce qu'on peut ressortir et revenir"]}, {"who": "seller", "fr": "Non, une fois entré, c'est définitif. Si tu ressors, ton bracelet est annulé.", "en": "No, once you're in, that's it. If you go back out, your wristband is cancelled.", "gloss": {"une fois entré": "once you're in", "définitif": "final", "annulé": "cancelled"}}, {"who": "you", "fr": "Bon à savoir. J'irai chercher mon K-way avant d'entrer, alors.", "en": "Good to know. I'll go and get my rain jacket before going in, then.", "gloss": {"Bon à savoir": "good to know", "J'irai": "I'll go (future)", "K-way": "light rain jacket"}, "accept": ["bon à savoir j'irai chercher mon k-way avant d'entrer alors", "bon à savoir j'irai chercher mon k-way avant d'entrer", "d'accord j'irai chercher mon k-way avant d'entrer", "bon à savoir je vais chercher mon k-way avant d'entrer", "merci bon à savoir j'irai chercher mon k-way d'abord", "bon à savoir alors je prends mon k-way avant d'entrer"]}, {"who": "friend", "fr": "Tu as fini ? Il commence à dracher, on se met sous le chapiteau ?", "en": "Are you done? It's starting to pour, shall we get under the marquee?", "gloss": {"dracher": "to pour with rain (Belgium; France: pleuvoir des cordes)", "chapiteau": "marquee / big top"}}, {"who": "you", "fr": "Oui, allons-y. Au fait, la borne à jetons est en panne, tu sais comment on fait ?", "en": "Yes, let's go. By the way, the token terminal's out of order, do you know what we do?", "gloss": {"Au fait": "by the way", "borne": "top-up terminal", "en panne": "out of order"}, "accept": ["oui allons-y au fait la borne à jetons est en panne tu sais comment on fait", "oui allons-y la borne à jetons est en panne tu sais comment on fait", "allons-y au fait la borne est en panne tu sais comment on fait", "oui au fait la borne à jetons est en panne comment on fait", "oui allons-y et la borne à jetons est en panne tu sais comment on fait", "d'accord allons-y au fait la borne est en panne comment on fait"]}, {"who": "friend", "fr": "Tout est en cashless cette année : tu recharges ton bracelet dans l'appli.", "en": "It's all cashless this year: you top up your wristband in the app.", "gloss": {"cashless": "cashless system", "recharges": "top up", "appli": "app"}}, {"who": "you", "fr": "Il y a un minimum de recharge ? Je ne voudrais pas mettre cinquante euros pour rien.", "en": "Is there a minimum top-up? I wouldn't want to put fifty euros on for nothing.", "gloss": {"recharge": "top-up", "pour rien": "for nothing"}, "accept": ["il y a un minimum de recharge je ne voudrais pas mettre cinquante euros pour rien", "il y a un minimum de recharge", "est-ce qu'il y a un minimum de recharge", "il y a un minimum de recharge je ne veux pas mettre cinquante euros pour rien", "et il y a un montant minimum de recharge", "est-ce qu'il y a un minimum je ne voudrais pas mettre cinquante euros pour rien"]}, {"who": "friend", "fr": "Dix euros minimum. Et ce qui reste, tu te le fais rembourser en ligne après le festival.", "en": "Ten euros minimum. And whatever's left, you claim it back online after the festival.", "gloss": {"ce qui reste": "whatever's left", "tu te le fais rembourser": "you have it refunded to you"}}, {"who": "you", "fr": "Ça vaut la peine ? Il y a des frais ?", "en": "Is it worth it? Are there fees?", "gloss": {"Ça vaut la peine": "is it worth it", "frais": "fees / charges"}, "accept": ["ça vaut la peine il y a des frais", "ça vaut la peine", "et il y a des frais", "ça vaut la peine est-ce qu'il y a des frais", "il y a des frais ça vaut la peine", "est-ce que ça vaut la peine il y a des frais"]}, {"who": "friend", "fr": "Deux euros de frais. Donc si tu as moins de deux euros dessus, laisse tomber.", "en": "Two euros in fees. So if you've got less than two euros on it, forget it.", "gloss": {"dessus": "on it", "laisse tomber": "forget it / don't bother"}}, {"who": "you", "fr": "Compris. Je vais recharger vingt euros pour commencer, on verra bien.", "en": "Got it. I'll top up twenty euros to start with, we'll see how it goes.", "gloss": {"Compris": "got it", "on verra bien": "we'll see"}, "accept": ["compris je vais recharger vingt euros pour commencer on verra bien", "compris je vais recharger vingt euros pour commencer", "d'accord je vais recharger vingt euros pour commencer", "je vais recharger vingt euros pour commencer on verra bien", "ok je recharge vingt euros pour commencer", "compris je recharge vingt euros pour commencer on verra bien"]}, {"who": "friend", "fr": "Ça marche. La tête d'affiche joue à vingt-trois heures, on a largement le temps.", "en": "Sounds good. The headliner's on at eleven, we've got plenty of time.", "gloss": {"Ça marche": "sounds good", "tête d'affiche": "headliner", "largement": "plenty / easily"}}, {"who": "you", "fr": "Parfait. Je te paie la première tournée, tu m'avais dépanné la dernière fois.", "en": "Perfect. I'll get the first round, you bailed me out last time.", "gloss": {"tournée": "round of drinks", "tu m'avais dépanné": "you'd bailed me out (plus-que-parfait)"}, "accept": ["parfait je te paie la première tournée tu m'avais dépanné la dernière fois", "parfait je te paie la première tournée", "je te paie la première tournée tu m'avais dépanné la dernière fois", "parfait c'est ma tournée tu m'avais dépanné la dernière fois", "super je te paie la première tournée", "parfait je t'offre la première tournée tu m'avais dépanné la dernière fois"]}], "exercises": [{"id": "ex-festival-B1-01", "level": "B1", "format": "cloze", "q": "Il faut que le billet ___ à ton nom.", "options": ["soit", "est", "sera", "était"], "a": 0, "expl": "« Il faut que » always takes the subjunctive. All four are real forms of être, but only « soit » survives after that trigger."}, {"id": "ex-festival-B1-02", "level": "B1", "format": "fr2en", "q": "la bourse d'échange", "options": ["the official ticket resale platform", "the stock exchange", "the student grant", "the merchandise stall"], "a": 0, "expl": "Belgian law caps resale at face value, so festivals run their own. Anything else is usually a fake QR code."}, {"id": "ex-festival-B1-03", "level": "B1", "format": "en2fr", "q": "out of order", "options": ["en panne", "en service", "en travaux", "en route"], "a": 0, "expl": "« En service » is the opposite; « en travaux » means under repair."}, {"id": "ex-festival-B1-04", "level": "B1", "format": "fr2en", "q": "le créneau", "options": ["the slot in a timetable", "the parking space", "the gap in a wall", "the chance to speak"], "a": 0, "expl": "« Leur créneau est de vingt et une à vingt-deux heures. » « Faire un créneau » is to parallel-park — the meaning most learners meet first."}, {"id": "ex-festival-B1-05", "level": "B1", "format": "fr2en", "q": "se chevaucher", "options": ["to overlap in time", "to follow one another", "to compete", "to be cancelled"], "a": 0, "expl": "« Leurs créneaux se chevauchent » — you will have to pick one."}, {"id": "ex-festival-B1-06", "level": "B1", "format": "cloze", "q": "Je suis ___ jusqu'aux os, il a draché toute la soirée.", "options": ["trempé", "mouillé", "humide", "gelé"], "a": 0, "expl": "All four are masculine adjectives that fit. « Trempé jusqu'aux os » is the fixed phrase; « mouillé » is merely wet. And « dracher » is the Belgian verb for it."}, {"id": "ex-festival-B1-07", "level": "B1", "format": "fr2en", "q": "Je ne capte plus rien.", "options": ["I've got no phone signal any more.", "I don't understand any more.", "I can't hear anything any more.", "I've got no battery left."], "a": 0, "expl": "« Capter » = to pick up a signal. In slang it can also mean to understand, which is the trap."}, {"id": "ex-festival-B1-08", "level": "B1", "format": "en2fr", "q": "to take shelter", "options": ["s'abriter", "se cacher", "s'installer", "se protéger"], "a": 0, "expl": "« On s'abrite sous le chapiteau. » The noun is « un abri »."}, {"id": "ex-festival-B1-09", "level": "B1", "format": "cloze", "q": "Le crédit qui reste, je me le fais ___ en ligne.", "options": ["rembourser", "remboursé", "rembourse", "remboursant"], "a": 0, "expl": "« Se faire + infinitif » = to have something done to you, so the infinitive « rembourser » is the only possible form here."}, {"id": "ex-festival-B1-10", "level": "B1", "format": "fr2en", "q": "tant pis", "options": ["never mind, too bad", "so much the better", "even less", "at last"], "a": 0, "expl": "Learn it with its twin: « tant mieux » = so much the better."}, {"id": "ex-festival-B1-11", "level": "B1", "format": "en2fr", "q": "the earplugs", "options": ["les bouchons d'oreilles", "les écouteurs", "les casques", "les boules Quies"], "a": 0, "expl": "« Les boules Quies » is a brand name used generically in France; in Belgium the neutral term is « des bouchons d'oreilles », handed out free at the info point."}, {"id": "ex-festival-B1-12", "level": "B1", "format": "collocation", "q": "Vous voulez fixer un lieu de retrouvailles avec un ami. Que dites-vous ?", "options": ["On se donne rendez-vous où ?", "On prend rendez-vous où ?", "On a rendez-vous quoi ?", "On donne un rendez-vous où ?"], "a": 0, "expl": "« Se donner rendez-vous » between friends; « prendre rendez-vous » with a dentist or a bank."}, {"id": "ex-festival-B1-13", "level": "B1", "format": "fr2en", "q": "la STIB", "options": ["the Brussels metro, tram and bus operator", "the Belgian national railway", "the Walloon bus company", "the Brussels traffic police"], "a": 0, "expl": "MIVB in Dutch, on the same vehicles. The trains are SNCB/NMBS."}, {"id": "ex-festival-B1-14", "level": "B1", "format": "cloze", "q": "Si on part maintenant, on va ___ le rappel.", "options": ["rater", "quitter", "perdre", "sortir"], "a": 0, "expl": "All four are infinitives after « on va ». « Rater » is the everyday verb for missing something; « manquer » is its more formal twin."}]},
  "breakfast-A2": {"slug": "breakfast", "level": "A2", "title": "Acheter le petit-déjeuner", "place": "Une boulangerie de la chaussée d'Ixelles, Bruxelles", "register": "vous", "registerNote": "Vous with the baker, every time — a Belgian boulangerie is a formal little world, however early it is and however often you go. The full ritual is « Bonjour madame », your order, « merci », « bonne journée ». Note that the baker will say « s'il vous plaît » as she hands you the bag: in Belgium that means 'here you go', not 'please'. Tu is for the friend waiting outside.", "vocab": [{"id": "fvc-breakfast-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le petit-déjeuner", "en": "breakfast", "format": "fr2en", "options": ["breakfast", "lunch", "a light snack at any hour", "an early dinner"], "a": 0, "trap": "in Belgium « le déjeuner » on its own means breakfast, not lunch — see the next card", "expl": "« Le petit-déjeuner » is understood everywhere and is the safe word. The verb is « petit-déjeuner » or « prendre son petit-déjeuner »."}, {"id": "fvc-breakfast-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le déjeuner", "en": "breakfast (Belgium)", "format": "fr2en", "options": ["breakfast, in Belgian usage", "lunch, in Belgian usage", "dinner, in Belgian usage", "a business lunch only"], "a": 0, "trap": "in France « le déjeuner » is lunch — the single most confusing word between the two countries", "note": "Belgian French shifts every meal one place: déjeuner = breakfast, dîner = lunch, souper = evening meal. In France: petit-déjeuner, déjeuner, dîner. If someone invites you « à dîner » in Brussels, ask what time.", "expl": "Older Belgians use the local system without thinking; younger city people often use the French one. Confirm the hour and you cannot go wrong."}, {"id": "fvc-breakfast-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "le dîner", "en": "lunch (Belgium)", "format": "en2fr", "options": ["le dîner", "le souper", "le déjeuner", "le goûter"], "a": 0, "trap": "le souper — the evening meal in Belgium, and the answer a French speaker would give here", "note": "Belgian French: dîner = the midday meal. In France dîner is the evening meal. « Le goûter » is the afternoon snack in both countries.", "expl": "« On dîne à midi » in Belgium. Same verb, three hours' difference depending on which side of the border you are on."}, {"id": "fvc-breakfast-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le souper", "en": "the evening meal (Belgium)", "format": "fr2en", "options": ["the evening meal", "a light late-night snack", "a soup course", "Sunday lunch"], "a": 0, "trap": "in France « un souper » is a very late supper after the theatre, not the normal evening meal", "note": "Belgian French. In France the evening meal is « le dîner »; « souper » there sounds old-fashioned or specifically after-midnight.", "expl": "« Tu viens souper à la maison ? » = come round for dinner. Verb and noun are the same word."}, {"id": "fvc-breakfast-A2-05", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pistolet", "en": "a round bread roll (Belgium)", "format": "fr2en", "options": ["a round crusty bread roll", "a small pistol only", "a long thin loaf", "a sweet bun"], "a": 0, "trap": "the word does mean a pistol — which is exactly why a French visitor's face changes when you order six of them", "note": "Belgian French, and the Sunday-morning institution: you buy a bagful, split them and fill them. In France you would ask for « un petit pain » — « un pistolet » there means only the weapon.", "expl": "About €0.60 each. « Six pistolets, s'il vous plaît » is the most Belgian sentence in this deck."}, {"id": "fvc-breakfast-A2-06", "level": "A2", "pos": "noun", "gender": "f", "fr": "la couque au chocolat", "en": "a pain au chocolat (Belgium)", "format": "fr2en", "options": ["a chocolate-filled pastry", "a chocolate cake", "a hot chocolate", "a chocolate biscuit"], "a": 0, "trap": "« une couque » alone is any sweet pastry — it is the « au chocolat » that pins it down", "note": "Belgian French. France argues between « pain au chocolat » (north) and « chocolatine » (south-west); Belgium calmly says « une couque au chocolat ». About €1.70.", "expl": "« Une couque suisse » has custard and raisins. The word comes from Dutch koek, cake."}, {"id": "fvc-breakfast-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "le croissant", "en": "the croissant", "format": "en2fr", "options": ["le croissant", "le beignet", "le chausson", "le friand"], "a": 0, "trap": "le chausson — an apple turnover, the other flaky thing in the window", "expl": "« Un croissant au beurre » is the good one; « un croissant ordinaire » is made with margarine. About €1.50 in Ixelles."}, {"id": "fvc-breakfast-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la cramique", "en": "raisin brioche loaf (Belgium)", "format": "fr2en", "options": ["a soft loaf studded with raisins", "a dry biscuit", "a cream-filled cake", "a savoury cheese bread"], "a": 0, "trap": "le craquelin — its twin, made with pearl sugar instead of raisins", "note": "Belgian speciality. The nearest French thing is « du pain aux raisins » or a brioche, but the word « cramique » is not used there.", "expl": "Sliced, toasted, buttered. « Une demi-cramique » is enough for two people."}, {"id": "fvc-breakfast-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "le craquelin", "en": "pearl-sugar brioche loaf (Belgium)", "format": "fr2en", "options": ["a soft loaf studded with pearl sugar", "a crispy cracker", "a caramel biscuit", "a savoury crispbread"], "a": 0, "trap": "la cramique — the same loaf with raisins instead of sugar", "note": "Belgian speciality, sold side by side with the cramique in every boulangerie. Unknown under that name in France.", "expl": "The sugar melts into little pockets when you toast it. « Cramique ou craquelin ? » is a genuine Sunday decision."}, {"id": "fvc-breakfast-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pain français", "en": "a baguette (Belgium)", "format": "fr2en", "options": ["a long thin white loaf", "any bread imported from France", "wholemeal bread", "a large round loaf"], "a": 0, "trap": "learners take it literally as 'French bread' and assume it is a category, not a specific shape", "note": "Belgian French: what France calls « une baguette », many Belgian bakeries list as « un pain français ». Both words are understood in Brussels.", "expl": "« Un pain français, pas trop cuit » = a baguette, not too well done. « Bien cuit » if you like it dark."}, {"id": "fvc-breakfast-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la baguette", "en": "the baguette", "format": "en2fr", "options": ["la baguette", "la ficelle", "la flûte", "la couronne"], "a": 0, "trap": "la ficelle — a thinner version, half the weight, and a real thing on the price list", "expl": "The family: une ficelle (thin), une baguette (standard), une flûte (fatter), une couronne (ring-shaped)."}, {"id": "fvc-breakfast-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pain gris", "en": "brown bread", "format": "cloze", "q": "Je prends un ___ , c'est meilleur pour la santé.", "options": ["pain gris", "pain blanc", "croissant", "craquelin"], "a": 0, "trap": "pain blanc — masculine, grammatical, and precisely the thing that is not better for you", "expl": "All four are masculine nouns that fit. « Le pain gris » is the Belgian everyday brown loaf; « le pain complet » is wholemeal, « le pain d'épeautre » is spelt."}, {"id": "fvc-breakfast-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tartine", "en": "a slice of bread with something on it", "format": "fr2en", "options": ["a slice of bread with butter or spread on it", "a small tart", "a whole loaf", "a sandwich with two slices"], "a": 0, "trap": "la tarte — a tart, the pastry; « une tartine » is bread", "expl": "« Des tartines de confiture. » In Belgium « une boîte à tartines » is the lunchbox every schoolchild carries."}, {"id": "fvc-breakfast-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la confiture", "en": "the jam", "format": "en2fr", "options": ["la confiture", "la compote", "la gelée", "la marmelade"], "a": 0, "trap": "la compote — stewed fruit eaten with a spoon, not spread on bread", "expl": "« De la confiture d'abricots. » « La gelée » is a clear jelly; « la marmelade » is specifically citrus."}, {"id": "fvc-breakfast-A2-15", "level": "A2", "pos": "noun", "gender": "m", "fr": "le beurre", "en": "the butter", "format": "fr2en", "options": ["the butter", "the drink", "the barrel", "the cream"], "a": 0, "trap": "boire / le beurre — learners mishear the vowel; « la crème » is cream", "expl": "« Un croissant au beurre » is a quality label, not a topping. Belgian butter is usually « demi-sel » or « doux »."}, {"id": "fvc-breakfast-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le miel", "en": "the honey", "format": "en2fr", "options": ["le miel", "le sirop", "la mélasse", "le caramel"], "a": 0, "trap": "le sirop — cordial or syrup; in Belgium « le sirop de Liège » is a dark apple-and-pear spread, not honey", "expl": "« Une tartine de miel. » Note « le sirop de Liège », a Walloon speciality eaten on bread with cheese."}, {"id": "fvc-breakfast-A2-17", "level": "A2", "pos": "noun", "gender": "m", "fr": "le fromage", "en": "the cheese", "format": "fr2en", "options": ["the cheese", "the dairy shop", "the cream", "the fromage frais only"], "a": 0, "trap": "la fromagerie — the cheese shop; « le fromage » is the food", "expl": "« Du fromage sur ma tartine. » Belgian names to know: le Herve, le Passendale, le Chimay."}, {"id": "fvc-breakfast-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "le jambon", "en": "the ham", "format": "en2fr", "options": ["le jambon", "le lard", "le saucisson", "le pâté"], "a": 0, "trap": "le lard — bacon or fatty pork; « le jambon » is the sliced ham you put on a pistolet", "expl": "« Du jambon blanc » is cooked ham, « du jambon d'Ardenne » the Belgian smoked one."}, {"id": "fvc-breakfast-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'œuf", "en": "the egg", "format": "cloze", "q": "Je prends un ___ à la coque avec mes tartines.", "options": ["œuf", "yaourt", "café", "croissant"], "a": 0, "trap": "yaourt — masculine and grammatical, but « à la coque » only describes a boiled egg", "expl": "All four are masculine breakfast nouns that fit. « À la coque » = soft-boiled in the shell; « dur » = hard-boiled; « brouillé » = scrambled. Singular « un œuf » sounds the f, plural « des œufs » does not."}, {"id": "fvc-breakfast-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le yaourt", "en": "the yoghurt", "format": "en2fr", "options": ["le yaourt", "le fromage blanc", "la crème fraîche", "le lait caillé"], "a": 0, "trap": "le fromage blanc — thicker and less sour, sold right next to it in the Delhaize", "expl": "Also spelt « yogourt ». « Un yaourt nature » is plain, « aux fruits » is with fruit."}, {"id": "fvc-breakfast-A2-21", "level": "A2", "pos": "noun", "gender": "m", "fr": "le café", "en": "the coffee", "format": "fr2en", "options": ["the coffee", "the cafeteria only", "the coffee bean plant", "the caffeine"], "a": 0, "trap": "the same word is the place — « on se voit au café » — so only context separates drink from venue", "expl": "About €2.80 in Brussels, served with a little biscuit or a speculoos. « Un café » on its own means an espresso."}, {"id": "fvc-breakfast-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'allongé", "en": "a long black coffee", "format": "fr2en", "options": ["an espresso lengthened with hot water", "a coffee with milk", "a double espresso", "a very small strong coffee"], "a": 0, "trap": "le serré — the opposite: an extra-short, extra-strong espresso", "expl": "« Un allongé, s'il vous plaît. » The scale: un serré, un café/expresso, un allongé, un café au lait."}, {"id": "fvc-breakfast-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le lait", "en": "the milk", "format": "en2fr", "options": ["le lait", "la crème", "le beurre", "le yaourt"], "a": 0, "trap": "la crème — cream; and in a café « un crème » is a coffee with milk, which muddles the two further", "expl": "« Avec un peu de lait » = with a drop of milk. « Du lait demi-écrémé » is semi-skimmed."}, {"id": "fvc-breakfast-A2-24", "level": "A2", "pos": "noun", "gender": "m", "fr": "le thé", "en": "the tea", "format": "fr2en", "options": ["the tea", "the herbal infusion", "the teapot", "the letter T"], "a": 0, "trap": "une tisane / une infusion — a herbal infusion, which French keeps strictly separate from thé", "expl": "« Un thé au lait » will get you a strange look and a jug anyway. « Un thé vert », « un thé noir »."}, {"id": "fvc-breakfast-A2-25", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chocolat chaud", "en": "the hot chocolate", "format": "en2fr", "options": ["le chocolat chaud", "le chocolat noir", "le cacao", "la praline"], "a": 0, "trap": "la praline — in Belgium that means a filled chocolate, not a caramelised almond as in France", "note": "Belgian point: « une praline » is one individual filled chocolate from a ballotin. In France « une praline » is a sugared almond — order accordingly.", "expl": "« Un chocolat chaud » is often made with real melting chocolate in Brussels, at around €3.50."}, {"id": "fvc-breakfast-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "le sucre", "en": "the sugar", "format": "fr2en", "options": ["the sugar", "the sweetener", "the syrup", "the sweet taste"], "a": 0, "trap": "l'édulcorant / le sucrette — artificial sweetener, which is what you get if you say « du sucre light »", "expl": "« Avec ou sans sucre ? » Belgian coffee comes with a wrapped lump and a biscuit on the saucer."}, {"id": "fvc-breakfast-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "la tasse", "en": "the cup", "format": "en2fr", "options": ["la tasse", "la soucoupe", "la théière", "la cuillère"], "a": 0, "trap": "la soucoupe — the saucer it sits on", "expl": "« Une tasse de café ». « Un mug » is used in French too, for the big handled one."}, {"id": "fvc-breakfast-A2-28", "level": "A2", "pos": "adj", "fr": "croustillant", "en": "crusty, crisp", "format": "fr2en", "options": ["crusty and crisp", "soft and springy", "stale", "buttery"], "a": 0, "trap": "moelleux — soft and springy inside, the opposite texture", "expl": "« Un pain bien croustillant » = a properly crusty loaf. Pair it with « moelleux » for the inside."}, {"id": "fvc-breakfast-A2-29", "level": "A2", "pos": "adj", "fr": "moelleux", "en": "soft, springy", "format": "en2fr", "options": ["moelleux", "croustillant", "dur", "sec"], "a": 0, "trap": "croustillant — crisp, its exact opposite, and the two are always mentioned together", "expl": "Pronounced 'mwa-leu'. « Une cramique bien moelleuse. »"}, {"id": "fvc-breakfast-A2-30", "level": "A2", "pos": "expr", "fr": "sur place", "en": "to eat in", "format": "collocation", "q": "On vous demande « sur place ou à emporter ? ». Vous mangez à la boulangerie. Que répondez-vous ?", "options": ["Sur place, s'il vous plaît", "En place, s'il vous plaît", "À la place, s'il vous plaît", "Dans la place, s'il vous plaît"], "a": 0, "trap": "« à la place » means 'instead', which answers a completely different question", "expl": "« Sur place ou à emporter ? » is asked at every Belgian counter. Note that eating in sometimes costs a little more, because of the VAT rate."}, {"id": "fvc-breakfast-A2-31", "level": "A2", "pos": "noun", "gender": "m", "fr": "le sachet", "en": "the paper bag", "format": "fr2en", "options": ["the small paper bag", "the shopping basket", "the cardboard box", "the wrapping paper"], "a": 0, "trap": "le sac — a bag in general, bigger; « un sachet » is the small one your croissants go in", "expl": "« Dans deux sachets, s'il vous plaît. » Also « un sachet de thé » = a tea bag."}, {"id": "fvc-breakfast-A2-32", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plateau", "en": "the tray", "format": "en2fr", "options": ["le plateau", "l'assiette", "le plat", "le panier"], "a": 0, "trap": "le plat — a serving dish or a main course, not the tray you carry it on", "expl": "« Un plateau de viennoiseries » = a tray of pastries, what you order for a Sunday brunch or an office meeting."}, {"id": "fvc-breakfast-A2-33", "level": "A2", "pos": "noun", "gender": "m", "fr": "le boulanger", "en": "the baker", "format": "fr2en", "options": ["the baker", "the butcher", "the pastry chef", "the miller"], "a": 0, "trap": "le pâtissier — the pastry chef; many Belgian shops are « boulangerie-pâtisserie » and do both", "expl": "Feminine « la boulangère », which is who you will actually be talking to at the counter."}, {"id": "fvc-breakfast-A2-34", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pâtisserie", "en": "the cake shop / a cake", "format": "fr2en", "options": ["the cake shop, and also an individual cake", "the bakery for bread only", "the icing", "the biscuit tin"], "a": 0, "trap": "la boulangerie — the bread half of the same business", "expl": "Both meanings live in one word: « une pâtisserie » is a shop and « des pâtisseries » are cakes."}, {"id": "fvc-breakfast-A2-35", "level": "A2", "pos": "noun", "gender": "f", "fr": "la viennoiserie", "en": "breakfast pastries (as a category)", "format": "fr2en", "options": ["the family of buttery breakfast pastries", "a bakery from Vienna", "a cream cake", "a bread roll"], "a": 0, "trap": "la pâtisserie — cakes; viennoiseries are croissants, couques and the like", "expl": "« Un assortiment de viennoiseries » is what you order for four people on a Sunday."}, {"id": "fvc-breakfast-A2-36", "level": "A2", "pos": "verb", "fr": "couper", "en": "to slice / cut", "format": "cloze", "q": "Je vous le ___ en tranches ?", "options": ["coupe", "prends", "mets", "donne"], "a": 0, "trap": "mets — grammatical, but « je vous le mets en tranches » is not how it is said", "expl": "All four are correct first-person forms. The baker asks « je vous le coupe ? » about a loaf — say « oui, s'il vous plaît » or « non, entier »."}, {"id": "fvc-breakfast-A2-37", "level": "A2", "pos": "noun", "gender": "m", "fr": "le matin", "en": "the morning", "format": "en2fr", "options": ["le matin", "la matinée", "le midi", "le lever"], "a": 0, "trap": "la matinée — the morning seen as a stretch of time: « j'ai travaillé toute la matinée »", "expl": "« Le matin » = mornings in general or a point in the morning; « la matinée » is its whole length."}, {"id": "fvc-breakfast-A2-38", "level": "A2", "pos": "adv", "fr": "tôt", "en": "early", "format": "fr2en", "options": ["early", "soon", "late", "immediately"], "a": 0, "trap": "bientôt — soon, which contains the same word and means something else", "expl": "« Ils ouvrent tôt, dès six heures et demie. » The opposite is « tard »."}, {"id": "fvc-breakfast-A2-39", "level": "A2", "pos": "verb", "fr": "ouvrir", "en": "to open", "format": "cloze", "q": "La boulangerie ___ à six heures et demie.", "options": ["ouvre", "ferme", "commence", "arrive"], "a": 0, "trap": "ferme — the same grammar, and a Belgian bakery does also close, just not at half past six in the morning", "expl": "All four are correct third-person forms. « Ouvrir » is irregular: j'ouvre, tu ouvres, il ouvre — like an -er verb in the present."}, {"id": "fvc-breakfast-A2-40", "level": "A2", "pos": "noun", "gender": "m", "fr": "le dimanche", "en": "Sunday", "format": "fr2en", "options": ["Sunday", "Saturday", "Monday", "the weekend"], "a": 0, "trap": "samedi — the other weekend day, and the one on which many Belgian bakeries are busiest", "note": "Belgian bakeries open on Sunday morning and usually close on Monday instead. Sunday is the big pistolet day; expect a queue at ten.", "expl": "« Le dimanche » with the article = every Sunday. « Dimanche » alone = this coming Sunday."}, {"id": "fvc-breakfast-A2-41", "level": "A2", "pos": "noun", "gender": "f", "fr": "la douzaine", "en": "a dozen", "format": "en2fr", "options": ["la douzaine", "la dizaine", "la quinzaine", "la vingtaine"], "a": 0, "trap": "la dizaine — about ten, an approximate number, where « une douzaine » is exactly twelve at the baker's", "expl": "« Une douzaine de pistolets » for a family Sunday. The -aine ending makes approximate numbers: une dizaine = about ten."}, {"id": "fvc-breakfast-A2-42", "level": "A2", "pos": "noun", "gender": "m", "fr": "le morceau", "en": "the piece", "format": "fr2en", "options": ["the piece", "the mouthful", "the slice of bread", "the crumb"], "a": 0, "trap": "la tranche — a slice, which is a piece of a particular shape", "expl": "« Un morceau de cramique. » Plural « des morceaux »."}, {"id": "fvc-breakfast-A2-43", "level": "A2", "pos": "adj", "fr": "sucré", "en": "sweet", "format": "en2fr", "options": ["sucré", "salé", "amer", "acide"], "a": 0, "trap": "salé — savoury or salty, the other half of the breakfast question", "expl": "« Vous préférez sucré ou salé ? » is a real question about breakfast in Belgium — jam or ham."}, {"id": "fvc-breakfast-A2-44", "level": "A2", "pos": "adj", "fr": "salé", "en": "savoury / salty", "format": "fr2en", "options": ["savoury or salty", "sweet", "spicy", "dirty"], "a": 0, "trap": "sale (without the accent) means dirty — one accent apart and a very different sandwich", "expl": "« Du beurre salé » is salted butter. « Sale » = dirty; « salé » = salty. Watch the accent."}, {"id": "fvc-breakfast-A2-45", "level": "A2", "pos": "noun", "gender": "m", "fr": "le spéculoos", "en": "the Belgian spiced biscuit", "format": "fr2en", "options": ["a thin spiced caramel biscuit", "a chocolate truffle", "a waffle", "a sugared almond"], "a": 0, "trap": "la praline — in Belgium a filled chocolate, which also arrives with coffee sometimes", "note": "Belgian and Dutch. It comes free on the saucer with your coffee, and as « la pâte de spéculoos » in every Delhaize. France knows the biscuit but rarely serves it with coffee.", "expl": "Traditionally baked for Saint-Nicolas on 6 December, now eaten all year. Also spelt « spéculoos » or « speculoos »."}], "phrases": [{"id": "ph-breakfast-A2-01", "fr": "Bonjour madame, six pistolets, s'il vous plaît.", "en": "Good morning, six bread rolls, please.", "note": "Add « madame » or « monsieur » — leaving it out sounds curt in a Belgian bakery. « Un pistolet » is a round roll; ask for « un petit pain » in France."}, {"id": "ph-breakfast-A2-02", "fr": "Je voudrais deux couques au chocolat.", "en": "I'd like two pains au chocolat.", "note": "« Je voudrais » is the polite conditional. « Une couque au chocolat » is the Belgian word; France says pain au chocolat or chocolatine."}, {"id": "ph-breakfast-A2-03", "fr": "Vous avez encore des croissants ?", "en": "Have you still got any croissants?", "note": "« Encore » = still. By eleven on a Sunday the answer is often « non, désolée »."}, {"id": "ph-breakfast-A2-04", "fr": "Un pain gris, pas trop cuit, s'il vous plaît.", "en": "A brown loaf, not too well done, please.", "note": "Bakers really do ask « bien cuit ou pas trop cuit ? ». « Le pain gris » is the Belgian everyday brown bread."}, {"id": "ph-breakfast-A2-05", "fr": "Vous pouvez me le couper en tranches ?", "en": "Could you slice it for me?", "note": "Most Belgian bakeries have a slicing machine behind the counter and will ask before you do."}, {"id": "ph-breakfast-A2-06", "fr": "Il me faut aussi une demi-cramique.", "en": "I also need half a raisin loaf.", "note": "« Il me faut » = I need. Half loaves are normal: « un demi-pain », « une demi-cramique »."}, {"id": "ph-breakfast-A2-07", "fr": "C'est tout, merci.", "en": "That's everything, thanks.", "note": "The answer to « avec ceci ? » (anything else?). « Ce sera tout » is the slightly fuller version."}, {"id": "ph-breakfast-A2-08", "fr": "Un café à emporter, s'il vous plaît.", "en": "A coffee to take away, please.", "note": "About €2.80. « À emporter » — you'll be asked « sur place ou à emporter ? » before you finish the sentence."}, {"id": "ph-breakfast-A2-09", "fr": "Un allongé, avec un peu de lait.", "en": "A long black coffee, with a drop of milk.", "note": "« Un allongé » is an espresso lengthened with hot water. « Un serré » is the short strong one."}, {"id": "ph-breakfast-A2-10", "fr": "Sur place, s'il vous plaît.", "en": "To eat in, please.", "note": "The other half of « sur place ou à emporter ? ». Eating in can cost slightly more because of the VAT rate."}, {"id": "ph-breakfast-A2-11", "fr": "Est-ce que vous avez du pain sans gluten ?", "en": "Do you have gluten-free bread?", "note": "« Du pain sans gluten » — partitive « du » for an uncountable. Larger Belgian chains do; a small artisan bakery usually does not."}, {"id": "ph-breakfast-A2-12", "fr": "Vous ouvrez à quelle heure le dimanche ?", "en": "What time do you open on Sundays?", "note": "« Le dimanche » with the article means every Sunday. Most Brussels bakeries open around 7 a.m. and close Monday instead."}, {"id": "ph-breakfast-A2-13", "fr": "Deux sachets, s'il vous plaît, c'est pour offrir.", "en": "Two bags please, it's a gift.", "note": "« C'est pour offrir » tells the shop to wrap it nicely — the phrase to use for a ballotin of pralines."}, {"id": "ph-breakfast-A2-14", "fr": "Ça fait combien en tout ?", "en": "How much is that altogether?", "note": "« En tout » = in total. Or wait: she will say « ça fait douze euros nonante »."}, {"id": "ph-breakfast-A2-15", "fr": "Vous prenez les cartes, ou c'est cash uniquement ?", "en": "Do you take cards, or is it cash only?", "note": "Worth asking in a small bakery: some still take cash only, or set a minimum for Bancontact. « Cash » is used in French in Belgium without a second thought."}, {"id": "ph-breakfast-A2-16", "fr": "Je n'ai qu'un billet de cinquante, ça va ?", "en": "I've only got a fifty-euro note, is that OK?", "note": "« Ne ... que » = only. At 7 a.m. the till has almost no change, so this is worth asking before she rings it up."}, {"id": "ph-breakfast-A2-17", "fr": "Tenez, voilà cinquante euros, s'il vous plaît.", "en": "Here, fifty euros for you.", "note": "Belgian French: « s'il vous plaît » is said while handing something over, in both directions. France would say « tenez » or « voilà » on its own."}, {"id": "ph-breakfast-A2-18", "fr": "Vous préférez sucré ou salé ?", "en": "Do you prefer sweet or savoury?", "note": "A real breakfast question in Belgium: jam and cramique, or ham and cheese on a pistolet."}, {"id": "ph-breakfast-A2-19", "fr": "Je passe au Delhaize après pour le lait.", "en": "I'll stop at the Delhaize afterwards for the milk.", "note": "« Passer à + shop » = to drop in. Delhaize, Carrefour Express and Colruyt are the Belgian chains; a small one is « un Proxy Delhaize »."}, {"id": "ph-breakfast-A2-20", "fr": "Merci beaucoup, bonne journée madame !", "en": "Thank you very much, have a good day!", "note": "Never leave without it. Add « madame » or « monsieur » and you sound like a regular rather than a tourist."}], "dialogue": [{"who": "baker", "fr": "Bonjour monsieur ! Qu'est-ce que ce sera ?", "en": "Good morning sir! What will it be?", "gloss": {"Qu'est-ce que ce sera": "what would you like (lit. what will it be)"}}, {"who": "you", "fr": "Bonjour madame. Je voudrais quatre pistolets, s'il vous plaît.", "en": "Good morning. I'd like four bread rolls, please.", "gloss": {"pistolets": "round bread rolls (Belgium; France: petits pains)"}, "accept": ["bonjour madame je voudrais quatre pistolets s'il vous plaît", "bonjour je voudrais quatre pistolets s'il vous plaît", "bonjour madame quatre pistolets s'il vous plaît", "je voudrais quatre pistolets s'il vous plaît", "bonjour je vais prendre quatre pistolets", "bonjour madame quatre pistolets merci"]}, {"who": "baker", "fr": "Quatre pistolets, voilà. Avec ceci ?", "en": "Four rolls, there we are. Anything else?", "gloss": {"Avec ceci": "anything else? (the standard bakery phrase)"}}, {"who": "you", "fr": "Deux couques au chocolat, aussi.", "en": "Two pains au chocolat as well.", "gloss": {"couques au chocolat": "chocolate pastries (Belgium)"}, "accept": ["deux couques au chocolat aussi", "deux couques au chocolat", "oui deux couques au chocolat s'il vous plaît", "et deux couques au chocolat", "je voudrais aussi deux couques au chocolat", "deux couques au chocolat s'il vous plaît"]}, {"who": "baker", "fr": "Il me reste des croissants tout chauds, si vous voulez.", "en": "I've got some croissants still warm, if you'd like.", "gloss": {"Il me reste": "I've got ... left", "tout chauds": "still warm"}}, {"who": "you", "fr": "Alors un croissant en plus. Et vous avez de la cramique ?", "en": "One croissant as well then. And do you have any cramique?", "gloss": {"en plus": "as well / on top", "cramique": "raisin brioche loaf (Belgium)"}, "accept": ["alors un croissant en plus et vous avez de la cramique", "alors un croissant en plus", "oui un croissant en plus et vous avez de la cramique", "un croissant en plus s'il vous plaît et vous avez de la cramique", "alors je prends un croissant et vous avez de la cramique", "volontiers un croissant et vous avez de la cramique"]}, {"who": "baker", "fr": "Oui, il en reste une. Je vous la coupe en tranches ?", "en": "Yes, there's one left. Shall I slice it for you?", "gloss": {"il en reste une": "there's one left", "coupe": "slice"}}, {"who": "you", "fr": "Non merci, entière, c'est très bien.", "en": "No thanks, whole is fine.", "gloss": {"entière": "whole"}, "accept": ["non merci entière c'est très bien", "non merci entière", "non merci pas besoin", "non merci je la prends entière", "non entière c'est très bien merci", "non merci entière ça ira"]}, {"who": "baker", "fr": "Très bien. Ce sera tout ?", "en": "Very well. Will that be everything?", "gloss": {"Ce sera tout": "will that be everything"}}, {"who": "you", "fr": "Oui. Ah, et un café à emporter, s'il vous plaît.", "en": "Yes. Oh, and a coffee to take away, please.", "gloss": {"à emporter": "to take away"}, "accept": ["oui ah et un café à emporter s'il vous plaît", "oui et un café à emporter s'il vous plaît", "oui et un café à emporter", "oui un café à emporter s'il vous plaît", "c'est tout ah et un café à emporter s'il vous plaît", "oui merci et un café à emporter"]}, {"who": "baker", "fr": "Un allongé ou un expresso ?", "en": "A long one or an espresso?", "gloss": {"allongé": "espresso lengthened with hot water"}}, {"who": "you", "fr": "Un allongé, avec un peu de lait.", "en": "A long one, with a drop of milk.", "gloss": {"un peu de lait": "a little milk"}, "accept": ["un allongé avec un peu de lait", "un allongé s'il vous plaît avec un peu de lait", "un allongé", "un allongé avec un peu de lait s'il vous plaît", "plutôt un allongé avec un peu de lait", "un allongé avec du lait"]}, {"who": "baker", "fr": "Voilà. Ça fait douze euros nonante.", "en": "There you go. That comes to twelve euros ninety.", "gloss": {"nonante": "90 (Belgium; France: quatre-vingt-dix)", "Ça fait": "that comes to"}}, {"who": "you", "fr": "Je peux payer par Bancontact ?", "en": "Can I pay by debit card?", "gloss": {"Bancontact": "Belgian debit-card system"}, "accept": ["je peux payer par bancontact", "est-ce que je peux payer par bancontact", "je paie par bancontact", "je peux payer par bancontact s'il vous plaît", "par bancontact c'est possible", "est-ce que vous prenez le bancontact"]}, {"who": "baker", "fr": "Bien sûr. Tapez votre code... C'est bon. Voilà votre ticket, s'il vous plaît.", "en": "Of course. Enter your PIN... That's fine. Here's your receipt.", "gloss": {"Tapez": "type / enter", "s'il vous plaît": "here you go (Belgian use when handing something over)"}}, {"who": "you", "fr": "Merci beaucoup. Bonne journée madame !", "en": "Thank you very much. Have a good day!", "gloss": {"Bonne journée": "have a good day"}, "accept": ["merci beaucoup bonne journée madame", "merci beaucoup bonne journée", "merci bonne journée madame", "merci beaucoup madame bonne journée", "merci bonne journée", "merci beaucoup au revoir bonne journée"]}], "exercises": [{"id": "ex-breakfast-A2-01", "level": "A2", "format": "fr2en", "q": "un pistolet (en Belgique)", "options": ["a round bread roll", "a small pistol", "a baguette", "a sweet bun"], "a": 0, "expl": "In France ask for « un petit pain » — « un pistolet » there is only the weapon."}, {"id": "ex-breakfast-A2-02", "level": "A2", "format": "en2fr", "q": "a pain au chocolat (in Belgium)", "options": ["une couque au chocolat", "une chocolatine", "un pain chocolaté", "une viennoiserie chocolat"], "a": 0, "expl": "Belgium says « une couque au chocolat »; « chocolatine » belongs to south-west France."}, {"id": "ex-breakfast-A2-03", "level": "A2", "format": "fr2en", "q": "le déjeuner (en Belgique)", "options": ["breakfast", "lunch", "dinner", "the afternoon snack"], "a": 0, "expl": "Belgium: déjeuner / dîner / souper = breakfast / lunch / dinner. France shifts them all one place."}, {"id": "ex-breakfast-A2-04", "level": "A2", "format": "cloze", "q": "Je prends une ___ , celle avec les raisins.", "options": ["cramique", "baguette", "tartine", "couque"], "a": 0, "expl": "All four are feminine bakery nouns that fit. The raisin loaf is « la cramique »; with pearl sugar it becomes « le craquelin »."}, {"id": "ex-breakfast-A2-05", "level": "A2", "format": "fr2en", "q": "les viennoiseries", "options": ["the family of buttery breakfast pastries", "cream cakes", "bread rolls", "biscuits served with coffee"], "a": 0, "expl": "Croissants, couques, pains aux raisins. « Un assortiment de viennoiseries » is the Sunday order for four."}, {"id": "ex-breakfast-A2-06", "level": "A2", "format": "en2fr", "q": "a long black coffee", "options": ["un allongé", "un serré", "un crème", "un cappuccino"], "a": 0, "expl": "« Un serré » is the short strong one. A Brussels coffee costs about €2.80 and comes with a speculoos."}, {"id": "ex-breakfast-A2-07", "level": "A2", "format": "cloze", "q": "Un pain gris, pas trop ___ , s'il vous plaît.", "options": ["cuit", "coupé", "chaud", "grand"], "a": 0, "expl": "All four are masculine adjectives or participles that fit. Bakers really do ask « bien cuit ou pas trop cuit ? » about how dark the crust should be."}, {"id": "ex-breakfast-A2-08", "level": "A2", "format": "fr2en", "q": "Avec ceci ?", "options": ["Anything else?", "With this one?", "Is that with you?", "Shall I add it up?"], "a": 0, "expl": "The fixed bakery phrase. Answer « c'est tout, merci » or name the next thing."}, {"id": "ex-breakfast-A2-09", "level": "A2", "format": "en2fr", "q": "crusty, crisp", "options": ["croustillant", "moelleux", "sec", "dur"], "a": 0, "expl": "The pair to learn: croustillant outside, moelleux inside."}, {"id": "ex-breakfast-A2-10", "level": "A2", "format": "fr2en", "q": "le spéculoos", "options": ["a thin spiced caramel biscuit", "a filled chocolate", "a waffle", "a sugared almond"], "a": 0, "expl": "Comes free with your coffee in Belgium, and as a spread in every Delhaize."}, {"id": "ex-breakfast-A2-11", "level": "A2", "format": "cloze", "q": "Il ne me ___ qu'un billet de cinquante euros.", "options": ["reste", "manque", "faut", "sert"], "a": 0, "expl": "All four work in impersonal « il me ___ » structures. « Il ne me reste que » = all I have left is."}, {"id": "ex-breakfast-A2-12", "level": "A2", "format": "collocation", "q": "Vous voulez que la boulangère emballe joliment un cadeau. Que dites-vous ?", "options": ["C'est pour offrir", "C'est pour donner", "C'est pour un cadeau à offrir de moi", "C'est pour offrir un cadeau à quelqu'un d'autre"], "a": 0, "expl": "« C'est pour offrir » is the fixed phrase — say it and out comes the ribbon."}, {"id": "ex-breakfast-A2-13", "level": "A2", "format": "fr2en", "q": "Voilà, s'il vous plaît.", "options": ["Here you go. (Belgium)", "There it is, please give it to me.", "Please wait a moment.", "Yes please."], "a": 0, "expl": "Belgian usage: « s'il vous plaît » also accompanies handing something over. France would say « voilà » or « tenez »."}, {"id": "ex-breakfast-A2-14", "level": "A2", "format": "en2fr", "q": "savoury / salty", "options": ["salé", "sale", "sucré", "amer"], "a": 0, "expl": "« Salé » with the accent is salty; « sale » without it means dirty."}]},
  "breakfast-B1": {"slug": "breakfast", "level": "B1", "title": "Le petit-déjeuner — plus de croissants, et un billet de cinquante", "place": "Une boulangerie de la chaussée d'Ixelles, Bruxelles", "register": "vous", "registerNote": "Vous with the baker, exactly as at A2 — but at B1 you can also negotiate inside it: « est-ce que je pourrais avoir… plutôt que… », « ça vous embête si… », « vous auriez… ». Those conditionals are what let you change an order or hand over a fifty-euro note at eight in the morning without sounding demanding. Tu stays outside the shop.", "vocab": [{"id": "fvc-breakfast-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fournée", "en": "the batch out of the oven", "format": "fr2en", "options": ["a batch of bread baked at the same time", "the oven itself", "the delivery of flour", "the day's total production"], "a": 0, "trap": "le four — the oven; « la fournée » is what comes out of it", "expl": "« La fournée de dix heures vient de sortir. » Figuratively: « la première fournée d'étudiants » = the first intake."}, {"id": "fvc-breakfast-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "le four", "en": "the oven", "format": "en2fr", "options": ["le four", "la poêle", "la casserole", "le fourneau"], "a": 0, "trap": "le fourneau — an old-fashioned cooking range, not the baker's oven", "expl": "« Ils sortent du four » = they're straight out of the oven. « Un four à bois » is a wood-fired one."}, {"id": "fvc-breakfast-B1-03", "level": "B1", "pos": "expr", "fr": "d'ici un quart d'heure", "en": "within the next quarter of an hour", "format": "collocation", "q": "La boulangère aura d'autres croissants dans quinze minutes. Comment le dit-elle ?", "options": ["J'en aurai d'autres d'ici un quart d'heure", "J'en aurai d'autres depuis un quart d'heure", "J'en aurai d'autres dès un quart d'heure", "J'en aurai d'autres il y a un quart d'heure"], "a": 0, "trap": "« depuis » looks back into the past; « d'ici » looks forward from now", "expl": "« D'ici + duration » = between now and then. « Dans un quart d'heure » also works and means exactly fifteen minutes from now."}, {"id": "fvc-breakfast-B1-04", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'appoint", "en": "the exact change", "format": "fr2en", "options": ["the exact money, so no change is needed", "the change you receive back", "an extra charge", "a tip"], "a": 0, "trap": "la monnaie — the change she gives you; « l'appoint » is the coins you supply yourself", "expl": "« Si vous avez l'appoint, ça m'arrange. » « Faire l'appoint » = to give the exact amount, gratefully received before nine in the morning."}, {"id": "fvc-breakfast-B1-05", "level": "B1", "pos": "expr", "fr": "rendre la monnaie", "en": "to give change", "format": "cloze", "q": "Je n'ai pas de quoi vous ___ la monnaie sur cinquante euros.", "options": ["rendre", "donner", "prendre", "payer"], "a": 0, "trap": "donner — grammatically fine, but « rendre la monnaie » is the fixed phrase: you give back what is over", "expl": "All four are infinitives that fit. « Rendre » carries 'back' — she is returning the surplus that was already yours."}, {"id": "fvc-breakfast-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la coupure", "en": "the note (denomination)", "format": "fr2en", "options": ["a banknote of a given value", "a cut on your hand only", "a power cut only", "the change"], "a": 0, "trap": "the same word means a cut and a power cut — « une coupure de courant »", "expl": "« Vous n'avez pas plus petit comme coupure ? » = have you got anything smaller? Belgian shops rarely take €200 or €500 notes at all."}, {"id": "fvc-breakfast-B1-07", "level": "B1", "pos": "noun", "gender": "f", "fr": "la formule", "en": "the set deal", "format": "fr2en", "options": ["a fixed combination sold at one price", "a mathematical formula only", "a polite phrase only", "the recipe"], "a": 0, "trap": "la recette — the recipe; « une formule » is a commercial package", "expl": "« La formule petit-déjeuner à douze euros » — hot drink, juice, bread and an egg. Cheaper than ordering the parts separately."}, {"id": "fvc-breakfast-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le brunch", "en": "brunch", "format": "en2fr", "options": ["le brunch", "le goûter", "l'en-cas", "le casse-croûte"], "a": 0, "trap": "le goûter — the afternoon snack around four o'clock, which is a different institution entirely", "expl": "Borrowed from English, masculine, and very Brussels: most Ixelles cafés do one from 10 a.m. to 3 p.m. at weekends, around €25."}, {"id": "fvc-breakfast-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "le buffet", "en": "the buffet", "format": "fr2en", "options": ["a spread you serve yourself from", "the sideboard furniture only", "the station café only", "the waiter's station"], "a": 0, "trap": "« le buffet » is also a piece of furniture and, in a station, the café — three meanings in one word", "expl": "« Un buffet à volonté » = all you can eat. « Le buffet de la gare » is a whole genre of Belgian restaurant."}, {"id": "fvc-breakfast-B1-10", "level": "B1", "pos": "expr", "fr": "à volonté", "en": "as much as you like", "format": "fr2en", "options": ["unlimited, as much as you want", "optional", "on request only", "at your own risk"], "a": 0, "trap": "« au choix » — a choice between options, which is not the same as unlimited", "expl": "« Café à volonté » is common at a Belgian brunch. « À volonté » never changes form."}, {"id": "fvc-breakfast-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "le pain perdu", "en": "French toast", "format": "fr2en", "options": ["stale bread soaked in egg and fried", "a loaf that has gone missing from the order", "bread thrown away at closing time", "a bread pudding baked in the oven"], "a": 0, "trap": "learners translate it literally as 'lost bread' and expect something to do with waste", "expl": "'Lost' because the bread was going stale. « Du pain perdu » is a Belgian breakfast and dessert staple."}, {"id": "fvc-breakfast-B1-12", "level": "B1", "pos": "noun", "gender": "f", "fr": "la gaufre", "en": "the waffle", "format": "fr2en", "options": ["the waffle", "the pancake", "the wafer biscuit", "the doughnut"], "a": 0, "trap": "la crêpe — a pancake, and what French cafés serve where Belgian ones serve gaufres", "note": "Two Belgian waffles, never to be confused: « la gaufre de Bruxelles » is rectangular, light, eaten with sugar or cream; « la gaufre de Liège » is dense, uneven and caramelised with pearl sugar, eaten warm in the hand. What tourists call a 'Belgian waffle' is usually the Brussels one.", "expl": "About €2.50 from a stand, more with toppings. Belgians eat them in the afternoon, rarely for breakfast."}, {"id": "fvc-breakfast-B1-13", "level": "B1", "pos": "noun", "gender": "m", "fr": "le sirop de Liège", "en": "Liège fruit spread", "format": "fr2en", "options": ["a dark thick apple-and-pear spread", "a sugar syrup for cocktails", "a cough syrup", "a caramel sauce"], "a": 0, "trap": "« le sirop » alone is cordial or syrup; the « de Liège » makes it a completely different food", "note": "Walloon speciality, sold in every Delhaize. Eaten on bread with butter, and traditionally with strong cheese or with boulets à la liégeoise. Unknown in France.", "expl": "Not sweet the way jam is — much darker and slightly tart. Worth trying once, on a slice of cramique."}, {"id": "fvc-breakfast-B1-14", "level": "B1", "pos": "noun", "gender": "m", "fr": "le fromage blanc", "en": "fresh soft white cheese", "format": "en2fr", "options": ["le fromage blanc", "le fromage frais", "la crème fraîche", "le yaourt nature"], "a": 0, "trap": "« le fromage frais » is a genuinely close cousin sold in the same fridge; « fromage blanc » is the thicker spoonable one", "expl": "Eaten with sugar, honey or radishes. In Brussels you will also see « du plattekaas », the Flemish name, on menus."}, {"id": "fvc-breakfast-B1-15", "level": "B1", "pos": "noun", "gender": "f", "fr": "les céréales", "en": "the breakfast cereal", "format": "fr2en", "options": ["breakfast cereal", "the cereal crops in a field only", "muesli specifically", "wholegrain flour"], "a": 0, "trap": "« les céréales » does also mean crops — context puts them in a bowl or in a field", "expl": "Always plural for the breakfast sense: « des céréales avec du lait »."}, {"id": "fvc-breakfast-B1-16", "level": "B1", "pos": "noun", "gender": "m", "fr": "le pain complet", "en": "wholemeal bread", "format": "en2fr", "options": ["le pain complet", "le pain gris", "le pain blanc", "le pain de mie"], "a": 0, "trap": "le pain gris — the Belgian everyday brown loaf, which is not the same as full wholemeal", "expl": "The scale in a Belgian bakery: pain blanc, pain gris, pain complet, pain d'épeautre. « Le pain de mie » is soft sliced sandwich bread."}, {"id": "fvc-breakfast-B1-17", "level": "B1", "pos": "noun", "gender": "m", "fr": "le levain", "en": "the sourdough starter", "format": "fr2en", "options": ["natural sourdough starter", "baker's yeast in a packet", "the dough itself", "the rising time"], "a": 0, "trap": "la levure — commercial yeast; « au levain » on a label means the slow natural method", "expl": "« Un pain au levain » keeps for days and costs more. Artisan Brussels bakeries advertise it on the window."}, {"id": "fvc-breakfast-B1-18", "level": "B1", "pos": "noun", "gender": "f", "fr": "la croûte", "en": "the crust", "format": "en2fr", "options": ["la croûte", "la mie", "la tranche", "la miette"], "a": 0, "trap": "la mie — the soft inside, the exact other half of the loaf", "expl": "« J'aime la croûte bien cuite. » « Une croûte » is also a scab, and « casser la croûte » means to have a bite to eat."}, {"id": "fvc-breakfast-B1-19", "level": "B1", "pos": "noun", "gender": "f", "fr": "la mie", "en": "the soft inside of bread", "format": "fr2en", "options": ["the soft part inside the crust", "the crumb that falls on the table", "the crust", "the slice"], "a": 0, "trap": "la miette — a crumb that has fallen; « la mie » is still inside the loaf", "expl": "« Le pain de mie » is the soft square sandwich loaf, named after it."}, {"id": "fvc-breakfast-B1-20", "level": "B1", "pos": "adj", "fr": "rassis", "en": "stale", "format": "cloze", "q": "Le pain d'hier est déjà ___ , on va faire du pain perdu.", "options": ["rassis", "frais", "moelleux", "chaud"], "a": 0, "trap": "frais — a masculine adjective that fits perfectly and says the opposite; the second half of the sentence gives it away", "expl": "All four are masculine adjectives that fit. Stale bread is exactly what pain perdu is for. Feminine « rassie »."}, {"id": "fvc-breakfast-B1-21", "level": "B1", "pos": "noun", "gender": "f", "fr": "la date de péremption", "en": "the use-by date", "format": "fr2en", "options": ["the date after which food should not be eaten", "the date it was made", "the delivery date", "the sell-by date for the shop only"], "a": 0, "trap": "la date de fabrication — the date it was made, printed right next to it", "expl": "On Belgian packaging: « à consommer avant le… » (use by) or « à consommer de préférence avant le… » (best before)."}, {"id": "fvc-breakfast-B1-22", "level": "B1", "pos": "verb", "fr": "congeler", "en": "to freeze", "format": "en2fr", "options": ["congeler", "refroidir", "geler", "glacer"], "a": 0, "trap": "geler — to freeze in the natural sense: « il gèle dehors ». Food you put in the freezer is « congelé ».", "expl": "« Je congèle la moitié du pain. » Note the accent change: je congèle, nous congelons."}, {"id": "fvc-breakfast-B1-23", "level": "B1", "pos": "verb", "fr": "décongeler", "en": "to defrost", "format": "fr2en", "options": ["to bring back from frozen", "to cool something down", "to reheat in an oven", "to keep chilled"], "a": 0, "trap": "réchauffer — to reheat something already thawed", "expl": "« Laissez décongeler une heure à température ambiante. » Also « faire décongeler »."}, {"id": "fvc-breakfast-B1-24", "level": "B1", "pos": "verb", "fr": "griller", "en": "to toast", "format": "cloze", "q": "Est-ce que vous pouvez me ___ les tartines, s'il vous plaît ?", "options": ["griller", "chauffer", "cuire", "brûler"], "a": 0, "trap": "brûler — to burn, which is what happens if she forgets them", "expl": "All four are infinitives that fit. « Griller » is what a toaster does; « cuire » is baking or cooking through."}, {"id": "fvc-breakfast-B1-25", "level": "B1", "pos": "noun", "gender": "m", "fr": "le grille-pain", "en": "the toaster", "format": "en2fr", "options": ["le grille-pain", "le four", "la plaque", "le mixeur"], "a": 0, "trap": "la plaque — the hob, or a baking tray", "expl": "Invariable in the plural: « des grille-pain ». Verb + noun compounds usually are."}, {"id": "fvc-breakfast-B1-26", "level": "B1", "pos": "expr", "fr": "à l'avance", "en": "in advance", "format": "fr2en", "options": ["ahead of time", "in front", "early in the morning", "at the front of the queue"], "a": 0, "trap": "en avance — means 'early', i.e. before the expected time: « je suis en avance »", "expl": "« Commander à l'avance » = to order ahead. « Être en avance » = to arrive early. Different phrases, one letter apart."}, {"id": "fvc-breakfast-B1-27", "level": "B1", "pos": "adv", "fr": "environ", "en": "about, approximately", "format": "en2fr", "options": ["environ", "à peine", "presque", "environs"], "a": 0, "trap": "presque — 'almost', which points at just under the number rather than around it", "expl": "« Environ quinze minutes. » Note « les environs » (plural noun) means the surrounding area."}, {"id": "fvc-breakfast-B1-28", "level": "B1", "pos": "noun", "gender": "m", "fr": "le tampon", "en": "the stamp (on a loyalty card)", "format": "fr2en", "options": ["the rubber stamp mark", "the till receipt", "the discount voucher", "the plug"], "a": 0, "trap": "le timbre — a postage stamp; « un tampon » is the inked one a shop presses on your card", "expl": "« Dix tampons et le onzième café est offert. » Small Brussels bakeries still run paper cards."}, {"id": "fvc-breakfast-B1-29", "level": "B1", "pos": "noun", "gender": "m", "fr": "le wifi", "en": "the wifi", "format": "cloze", "q": "Vous auriez le mot de passe du ___ , s'il vous plaît ?", "options": ["wifi", "code", "réseau", "compte"], "a": 0, "trap": "réseau — masculine and grammatical, but « le mot de passe du réseau » is what a technician says, not a customer", "expl": "All four are masculine nouns that fit. Pronounced 'wee-fee' in French, not 'why-fye'."}, {"id": "fvc-breakfast-B1-30", "level": "B1", "pos": "noun", "gender": "m", "fr": "le mot de passe", "en": "the password", "format": "en2fr", "options": ["le mot de passe", "le code secret", "l'identifiant", "le surnom"], "a": 0, "trap": "le code secret — your card PIN, four digits, a different thing entirely", "expl": "« Le mot de passe est sur l'ardoise. » Your username is « l'identifiant »; « un surnom » is a nickname."}, {"id": "fvc-breakfast-B1-31", "level": "B1", "pos": "noun", "gender": "f", "fr": "la prise", "en": "the power socket", "format": "fr2en", "options": ["the electrical socket", "the plug on the cable only", "the grip you take on something", "the photograph"], "a": 0, "trap": "the same word means a grip and a catch — « une prise de judo », « une prise de sang »", "expl": "« Il y a une prise près de la fenêtre. » Belgium uses type E sockets with a protruding earth pin — a French plug fits, a UK one does not."}, {"id": "fvc-breakfast-B1-32", "level": "B1", "pos": "verb", "fr": "s'installer", "en": "to settle in / take a seat", "format": "fr2en", "options": ["to sit yourself down somewhere", "to install software only", "to move house", "to stand still"], "a": 0, "trap": "installer — to install something; the reflexive puts you in the chair", "expl": "« Installez-vous, je vous apporte ça. » The single most useful welcoming verb in Belgian hospitality."}, {"id": "fvc-breakfast-B1-33", "level": "B1", "pos": "noun", "gender": "m", "fr": "le coin", "en": "the corner", "format": "en2fr", "options": ["le coin", "l'angle", "le bout", "le côté"], "a": 0, "trap": "l'angle — the geometric corner, and also the street corner outside; « le coin » is the cosy inside one", "expl": "« Une petite table dans le coin. » « Du coin » = local: « la boulangerie du coin »."}, {"id": "fvc-breakfast-B1-34", "level": "B1", "pos": "verb", "fr": "emballer", "en": "to wrap up", "format": "fr2en", "options": ["to wrap something for a customer", "to load a van", "to pack a suitcase", "to seal a letter"], "a": 0, "trap": "emporter — to take away; she emballe it so that you can emporter it", "expl": "« Je vous les emballe ? » In slang « ça m'emballe » means 'I love it'."}, {"id": "fvc-breakfast-B1-35", "level": "B1", "pos": "noun", "gender": "m", "fr": "le ballotin", "en": "the box of pralines (Belgium)", "format": "fr2en", "options": ["the small cone-shaped box Belgian chocolates are sold in", "a bundle of letters", "a bale of straw", "a gift bag"], "a": 0, "trap": "la boîte — a box in general; « un ballotin » is the specific Belgian chocolate box", "note": "Belgian, invented in Brussels in 1915 by the Neuhaus family. Chocolates are sold by weight and packed into it. The word is barely used in France.", "expl": "« Un ballotin de deux cent cinquante grammes » is the standard house-gift. Say « c'est pour offrir » and out comes the ribbon."}, {"id": "fvc-breakfast-B1-36", "level": "B1", "pos": "noun", "gender": "f", "fr": "la praline", "en": "a filled chocolate (Belgium)", "format": "fr2en", "options": ["one individual filled chocolate", "a caramelised almond", "a praline paste", "a chocolate bar"], "a": 0, "trap": "in France « une praline » is a caramelised almond — order pralines in Lille and you will not get chocolates", "note": "Belgian usage, and a real cross-border trap. Belgium: praline = filled chocolate (Neuhaus, Leonidas, Pierre Marcolini). France: praline = sugared almond; a filled chocolate there is « un chocolat » or « un bonbon de chocolat ».", "expl": "« Un ballotin de pralines assorties » — a mixed box. Around €10 for 250g at Leonidas."}, {"id": "fvc-breakfast-B1-37", "level": "B1", "pos": "expr", "fr": "sur commande", "en": "made to order", "format": "fr2en", "options": ["only made if you order it in advance", "delivered to your door", "available every day", "sold at the counter only"], "a": 0, "trap": "« à la commande » is not the phrase; and « sur place » is about where you eat it", "expl": "« Les grands pains au levain, c'est sur commande. » Order the day before and collect in the morning."}, {"id": "fvc-breakfast-B1-38", "level": "B1", "pos": "verb", "fr": "se dépêcher", "en": "to hurry", "format": "en2fr", "options": ["se dépêcher", "se presser", "s'empresser", "se précipiter"], "a": 0, "trap": "se presser — also correct and very close; « s'empresser de » means to be eager to do something, which is different", "expl": "« Dépêche-toi ! » Reflexive always: never « je dépêche »."}, {"id": "fvc-breakfast-B1-39", "level": "B1", "pos": "expr", "fr": "être en retard", "en": "to be late", "format": "cloze", "q": "Je suis un peu ___ , je dois repartir vers onze heures.", "options": ["en retard", "en avance", "à l'heure", "en avant"], "a": 0, "trap": "en avance — 'early', the same structure and the opposite situation", "expl": "The trio: en avance (early), à l'heure (on time), en retard (late). Note « un retard » (a delay) versus « un délai » (a normal lead time)."}, {"id": "fvc-breakfast-B1-40", "level": "B1", "pos": "adv", "fr": "d'habitude", "en": "usually", "format": "fr2en", "options": ["usually, as a rule", "as a one-off", "from now on", "for the first time"], "a": 0, "trap": "« comme d'habitude » = as usual, a fixed phrase; « d'habitude » alone opens a sentence", "expl": "« D'habitude je passe vers huit heures. » The regulars' word — say it and you become « un habitué »."}, {"id": "fvc-breakfast-B1-41", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'habitué", "en": "the regular customer", "format": "en2fr", "options": ["l'habitué", "le client", "le fidèle", "le voisin"], "a": 0, "trap": "le client — any customer; « un habitué » comes every week and gets greeted by name", "expl": "Feminine « une habituée ». « C'est un habitué de la maison » is a compliment."}, {"id": "fvc-breakfast-B1-42", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trajet", "en": "the journey / route", "format": "fr2en", "options": ["the journey from one point to another", "the traffic", "the ticket", "the timetable"], "a": 0, "trap": "le voyage — a trip, usually longer and with a purpose; « un trajet » is the commute", "expl": "« Le trajet dure vingt minutes en bus. » « Le trajet domicile-travail » is the commute in official Belgian language."}, {"id": "fvc-breakfast-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "le bus", "en": "the bus", "format": "en2fr", "options": ["le bus", "le car", "le tram", "la navette"], "a": 0, "trap": "le car — a coach for long distances, which is what English speakers assume means 'car'", "expl": "The 71 runs the length of the chaussée d'Ixelles. « Un car » goes to Paris; « un bus » goes to Flagey."}, {"id": "fvc-breakfast-B1-44", "level": "B1", "pos": "noun", "gender": "m", "fr": "le pain d'épices", "en": "gingerbread", "format": "fr2en", "options": ["a dense spiced honey loaf", "a spicy savoury bread", "a peppercorn roll", "a cinnamon bun"], "a": 0, "trap": "le spéculoos — the thin spiced biscuit, a different texture and a different job", "note": "Belgian cooking uses it as an ingredient: a slice of pain d'épices with mustard thickens carbonnades flamandes. Dinant makes a famous hard version, « la couque de Dinant ».", "expl": "Sweet, soft, made with honey and rye. Sold in a loaf and sliced like bread."}, {"id": "fvc-breakfast-B1-45", "level": "B1", "pos": "expr", "fr": "ça vous embête si", "en": "do you mind if", "format": "collocation", "q": "Vous n'avez qu'un billet de cinquante euros. Comment demandez-vous poliment ?", "options": ["Ça vous embête si je paie avec un billet de cinquante ?", "Ça vous embête que je paie avec un billet de cinquante ?", "Ça vous embête de je paie avec un billet de cinquante ?", "Ça vous embête si je paierai avec un billet de cinquante ?"], "a": 0, "trap": "« ça vous embête de + infinitif » and « ça vous embête que + subjonctif » both exist, but only « si + présent » lets you keep the simple verb form", "expl": "« Ça vous embête si + présent » is the simplest safe pattern. « Ça vous dérange si… » is identical; « cela vous ennuierait-il de… » is the formal written version."}], "phrases": [{"id": "ph-breakfast-B1-01", "fr": "J'étais venu pour des croissants, mais il n'en reste plus ?", "en": "I'd come for croissants, but there are none left?", "note": "Plus-que-parfait « j'étais venu » for the plan that preceded the bad news. « Il n'en reste plus » with the pronoun « en »."}, {"id": "ph-breakfast-B1-02", "fr": "La prochaine fournée sort dans combien de temps ?", "en": "How long until the next batch is out?", "note": "« Dans combien de temps ? » = how long from now. « La fournée » is a batch out of the oven."}, {"id": "ph-breakfast-B1-03", "fr": "Ce n'est pas grave, je peux attendre un quart d'heure.", "en": "That's fine, I can wait a quarter of an hour.", "note": "« Un quart d'heure », « une demi-heure », « trois quarts d'heure » — learn the three together."}, {"id": "ph-breakfast-B1-04", "fr": "Est-ce que je peux m'installer et prendre un petit-déjeuner en attendant ?", "en": "Can I sit down and have breakfast while I wait?", "note": "« En attendant » = meanwhile. « S'installer » is the standard verb for taking a seat."}, {"id": "ph-breakfast-B1-05", "fr": "Qu'est-ce que comprend la formule à douze euros ?", "en": "What does the twelve-euro deal include?", "note": "« Comprendre » = to include as well as to understand. « La formule » is a set combination at one price."}, {"id": "ph-breakfast-B1-06", "fr": "Est-ce que je pourrais avoir du pain gris plutôt que du blanc ?", "en": "Could I have brown bread rather than white?", "note": "« Pourrais » + « plutôt que » is the polite way to change a set item. Nine times out of ten the answer is « sans problème »."}, {"id": "ph-breakfast-B1-07", "fr": "Vous pouvez me les griller, s'il vous plaît ?", "en": "Could you toast them for me, please?", "note": "Two pronouns before the infinitive, in order: me les. « Griller » is what the toaster does."}, {"id": "ph-breakfast-B1-08", "fr": "Je n'en ai jamais goûté, c'est comment ?", "en": "I've never tried it, what's it like?", "note": "« En » replaces « du sirop de Liège ». « C'est comment ? » is the everyday way to ask what something is like."}, {"id": "ph-breakfast-B1-09", "fr": "Vous auriez le mot de passe du wifi ?", "en": "Would you have the wifi password?", "note": "« Vous auriez » (conditional) is softer than « vous avez ». In a Belgian café it is often chalked on the ardoise."}, {"id": "ph-breakfast-B1-10", "fr": "Il y a une prise quelque part ? Mon GSM est à dix pour cent.", "en": "Is there a socket anywhere? My phone's at ten per cent.", "note": "Belgicism: « GSM » for a mobile — France says « portable ». Belgian sockets are type E, with a pin."}, {"id": "ph-breakfast-B1-11", "fr": "Je suis un peu en retard, je dois repartir vers onze heures.", "en": "I'm running a bit late, I have to leave around eleven.", "note": "« En retard » = late; « en avance » = early. « Vers » + time = around."}, {"id": "ph-breakfast-B1-12", "fr": "J'en prendrai quatre à emporter, si c'est possible.", "en": "I'll take four to go, if that's possible.", "note": "Future « je prendrai » for something you will do in a minute. « En » is obligatory when the noun is dropped."}, {"id": "ph-breakfast-B1-13", "fr": "Vous pouvez me les emballer séparément ?", "en": "Could you wrap them separately?", "note": "« Emballer » is wrapping; « emporter » is carrying away. Useful if half of them are a gift."}, {"id": "ph-breakfast-B1-14", "fr": "Je n'ai qu'un billet de cinquante, ça vous embête ?", "en": "I've only got a fifty, do you mind?", "note": "« Ne ... que » = only. Before nine in the morning a Belgian till has almost nothing in it — ask first."}, {"id": "ph-breakfast-B1-15", "fr": "Attendez, j'ai peut-être l'appoint.", "en": "Hang on, I might have the exact change.", "note": "« Faire l'appoint » = to give the exact money. Saying this out loud will make the baker's morning."}, {"id": "ph-breakfast-B1-16", "fr": "Je vais plutôt payer par Bancontact, ce sera plus simple.", "en": "I'll pay by card instead, it'll be simpler.", "note": "« Plutôt » = rather / instead. « Ce sera » (future) for what is about to happen."}, {"id": "ph-breakfast-B1-17", "fr": "Est-ce que le pain au levain se fait sur commande ?", "en": "Is the sourdough loaf made to order?", "note": "« Se faire » as a passive: « ça se fait sur commande » = it's made to order. Order the day before."}, {"id": "ph-breakfast-B1-18", "fr": "Le pain d'hier est rassis, je vais faire du pain perdu.", "en": "Yesterday's bread is stale, I'll make French toast.", "note": "That is exactly what « pain perdu » is for — 'lost' bread rescued with egg and milk."}, {"id": "ph-breakfast-B1-19", "fr": "D'habitude je passe vers huit heures, avant de prendre le 71.", "en": "I usually come by around eight, before getting the 71.", "note": "« D'habitude » opens the sentence; « comme d'habitude » = as usual. Bus 71 runs the length of the chaussée d'Ixelles."}, {"id": "ph-breakfast-B1-20", "fr": "Merci beaucoup, c'était délicieux. À dimanche prochain !", "en": "Thank you very much, it was delicious. See you next Sunday!", "note": "« À + time » = see you then: à demain, à lundi, à tout à l'heure. Belgian bakeries open Sunday morning and close Monday."}], "dialogue": [{"who": "baker", "fr": "Bonjour monsieur ! Vous avez de la chance, la fournée de dix heures vient de sortir.", "en": "Good morning sir! You're in luck, the ten o'clock batch has just come out.", "gloss": {"fournée": "batch out of the oven", "vient de sortir": "has just come out"}}, {"who": "you", "fr": "Bonjour madame. Justement, j'étais venu pour des croissants — il en reste ?", "en": "Good morning. As it happens, I'd come for croissants — are there any left?", "gloss": {"Justement": "as it happens", "j'étais venu": "I had come (plus-que-parfait)", "il en reste": "are there any left"}, "accept": ["bonjour madame justement j'étais venu pour des croissants il en reste", "bonjour j'étais venu pour des croissants il en reste", "bonjour madame est-ce qu'il vous reste des croissants", "bonjour je venais pour des croissants il en reste", "bonjour madame j'étais venu pour des croissants est-ce qu'il en reste", "bonjour il vous reste des croissants"]}, {"who": "baker", "fr": "Ah, les croissants sont partis vers neuf heures. J'en aurai d'autres d'ici un quart d'heure.", "en": "Ah, the croissants went around nine. I'll have more within a quarter of an hour.", "gloss": {"sont partis": "have gone / sold out", "d'ici un quart d'heure": "within the next quarter of an hour"}}, {"who": "you", "fr": "Ce n'est pas grave, je peux attendre. Est-ce que je peux m'installer et prendre un petit-déjeuner ?", "en": "That's fine, I can wait. Can I sit down and have breakfast?", "gloss": {"m'installer": "sit myself down", "petit-déjeuner": "breakfast"}, "accept": ["ce n'est pas grave je peux attendre est-ce que je peux m'installer et prendre un petit-déjeuner", "ce n'est pas grave je peux attendre", "pas de souci je peux attendre est-ce que je peux m'installer et prendre un petit-déjeuner", "ce n'est pas grave est-ce que je peux m'installer et prendre un petit-déjeuner", "je peux attendre est-ce que je peux m'installer pour prendre un petit-déjeuner", "pas grave je peux attendre je peux m'installer et prendre un petit-déjeuner"]}, {"who": "baker", "fr": "Bien sûr, installez-vous. On fait une formule à douze euros cinquante : boisson chaude, jus, deux tartines et un œuf.", "en": "Of course, take a seat. We do a twelve-fifty deal: hot drink, juice, two slices of bread and an egg.", "gloss": {"formule": "set deal at one price", "tartines": "slices of bread with a topping"}}, {"who": "you", "fr": "Ça me va très bien. Est-ce que je pourrais avoir du pain gris grillé plutôt que du blanc ?", "en": "That suits me very well. Could I have toasted brown bread rather than white?", "gloss": {"pourrais": "could (conditional)", "grillé": "toasted", "plutôt que": "rather than"}, "accept": ["ça me va très bien est-ce que je pourrais avoir du pain gris grillé plutôt que du blanc", "est-ce que je pourrais avoir du pain gris grillé plutôt que du blanc", "ça me va est-ce que je pourrais avoir du pain gris plutôt que du blanc", "parfait est-ce que je pourrais avoir du pain gris grillé plutôt que du blanc", "ça me va très bien je pourrais avoir du pain gris grillé", "très bien est-ce que je peux avoir du pain gris grillé plutôt que du blanc"]}, {"who": "baker", "fr": "Sans problème. Confiture, miel, ou sirop de Liège ?", "en": "No problem. Jam, honey, or Liège syrup?", "gloss": {"sirop de Liège": "dark apple-and-pear spread (Wallonia)"}}, {"who": "you", "fr": "Du sirop de Liège, je n'en ai jamais goûté.", "en": "Liège syrup, I've never tried it.", "gloss": {"je n'en ai jamais goûté": "I've never tasted any of it"}, "accept": ["du sirop de liège je n'en ai jamais goûté", "du sirop de liège", "du sirop de liège s'il vous plaît je n'en ai jamais goûté", "je vais essayer le sirop de liège je n'en ai jamais goûté", "alors du sirop de liège je n'en ai jamais goûté", "du sirop de liège je voudrais essayer"]}, {"who": "baker", "fr": "Vous m'en direz des nouvelles ! Et comme boisson chaude ?", "en": "You'll tell me what you think! And as a hot drink?", "gloss": {"Vous m'en direz des nouvelles": "you'll tell me what you think (fixed phrase)"}}, {"who": "you", "fr": "Un allongé, s'il vous plaît. Vous auriez le mot de passe du wifi ?", "en": "A long black coffee, please. Would you have the wifi password?", "gloss": {"allongé": "espresso lengthened with hot water", "Vous auriez": "would you have (polite conditional)"}, "accept": ["un allongé s'il vous plaît vous auriez le mot de passe du wifi", "un allongé s'il vous plaît", "un allongé et vous auriez le mot de passe du wifi", "un allongé s'il vous plaît est-ce que vous auriez le mot de passe du wifi", "un café allongé s'il vous plaît vous auriez le mot de passe du wifi", "un allongé merci vous avez le mot de passe du wifi"]}, {"who": "baker", "fr": "C'est écrit sur l'ardoise derrière vous. Il y a aussi une prise près de la fenêtre.", "en": "It's written on the blackboard behind you. There's also a socket by the window.", "gloss": {"ardoise": "blackboard", "prise": "power socket"}}, {"who": "you", "fr": "Parfait, merci. Je suis un peu en retard, je dois repartir vers onze heures.", "en": "Perfect, thanks. I'm running a bit late, I have to leave around eleven.", "gloss": {"en retard": "late", "vers": "around (a time)"}, "accept": ["parfait merci je suis un peu en retard je dois repartir vers onze heures", "parfait merci je suis un peu en retard", "merci je suis un peu en retard je dois repartir vers onze heures", "parfait merci je dois repartir vers onze heures", "très bien merci je suis un peu en retard je dois partir vers onze heures", "merci beaucoup je dois repartir vers onze heures"]}, {"who": "baker", "fr": "Vous serez servi bien avant, ne vous en faites pas. ... Voilà, et vos croissants sortent du four.", "en": "You'll be served well before then, don't worry. ... There we are, and your croissants are coming out of the oven.", "gloss": {"Vous serez servi": "you'll be served (future passive)", "ne vous en faites pas": "don't worry"}}, {"who": "you", "fr": "Ils sentent très bon. J'en prendrai quatre à emporter, si c'est possible.", "en": "They smell wonderful. I'll take four to go, if that's possible.", "gloss": {"sentent": "smell", "J'en prendrai": "I'll take (some of them)"}, "accept": ["ils sentent très bon j'en prendrai quatre à emporter si c'est possible", "ils sentent très bon j'en prendrai quatre à emporter", "j'en prendrai quatre à emporter si c'est possible", "ils sentent très bon je vais en prendre quatre à emporter", "j'en prends quatre à emporter s'il vous plaît", "ils sentent bon j'en prendrai quatre à emporter"]}, {"who": "baker", "fr": "Je vous les emballe. Ça fera dix-huit euros cinquante en tout.", "en": "I'll wrap them for you. That'll be eighteen euros fifty altogether.", "gloss": {"emballe": "wrap up", "en tout": "altogether"}}, {"who": "you", "fr": "Je n'ai qu'un billet de cinquante, ça vous embête ?", "en": "I've only got a fifty-euro note, do you mind?", "gloss": {"Je n'ai qu'un": "I've only got one", "ça vous embête": "do you mind"}, "accept": ["je n'ai qu'un billet de cinquante ça vous embête", "je n'ai qu'un billet de cinquante", "je n'ai qu'un billet de cinquante euros ça vous embête", "j'ai seulement un billet de cinquante ça vous embête", "je n'ai qu'un billet de cinquante ça vous dérange", "désolé je n'ai qu'un billet de cinquante"]}, {"who": "baker", "fr": "À cette heure-ci, ça va être juste. Si vous avez l'appoint, ça m'arrange.", "en": "At this hour it'll be tight. If you've got the exact change, that would help me.", "gloss": {"l'appoint": "the exact change", "ça m'arrange": "that suits me / helps me out"}}, {"who": "you", "fr": "Attendez... je n'ai que cinquante centimes. Je vais plutôt payer par Bancontact.", "en": "Hang on... I've only got fifty cents. I'll pay by card instead.", "gloss": {"plutôt": "instead / rather", "Bancontact": "Belgian debit-card system"}, "accept": ["attendez je n'ai que cinquante centimes je vais plutôt payer par bancontact", "je n'ai que cinquante centimes je vais plutôt payer par bancontact", "attendez je n'ai pas l'appoint je vais payer par bancontact", "je vais plutôt payer par bancontact", "attendez non je n'ai pas l'appoint je paie par bancontact", "désolé je n'ai pas l'appoint je vais payer par bancontact"]}, {"who": "baker", "fr": "Parfait, c'est plus simple pour tout le monde. ... C'est bon, voilà votre ticket, s'il vous plaît.", "en": "Perfect, that's easier for everyone. ... That's fine, here's your receipt.", "gloss": {"s'il vous plaît": "here you go (Belgian use when handing something over)"}}, {"who": "you", "fr": "Merci beaucoup, c'était délicieux. À dimanche prochain !", "en": "Thank you very much, it was delicious. See you next Sunday!", "gloss": {"À dimanche prochain": "see you next Sunday"}, "accept": ["merci beaucoup c'était délicieux à dimanche prochain", "merci beaucoup c'était délicieux", "merci beaucoup à dimanche prochain", "merci c'était délicieux à dimanche prochain", "merci beaucoup c'était très bon à dimanche", "merci bonne journée à dimanche prochain"]}], "exercises": [{"id": "ex-breakfast-B1-01", "level": "B1", "format": "fr2en", "q": "la fournée", "options": ["a batch of bread out of the oven", "the oven", "the flour delivery", "the day's takings"], "a": 0, "expl": "« La fournée de dix heures vient de sortir. » Also used for a group of people arriving together."}, {"id": "ex-breakfast-B1-02", "level": "B1", "format": "cloze", "q": "J'___ venu pour des croissants, mais il n'en restait plus.", "options": ["étais", "ai", "aurais", "serai"], "a": 0, "expl": "Venir takes être, and the plus-que-parfait « j'étais venu » places your arrival before the discovery. « J'ai venu » does not exist."}, {"id": "ex-breakfast-B1-03", "level": "B1", "format": "fr2en", "q": "faire l'appoint", "options": ["to give the exact change", "to make an appointment", "to round the price up", "to pay a deposit"], "a": 0, "expl": "Gratefully received in any Belgian shop before nine in the morning."}, {"id": "ex-breakfast-B1-04", "level": "B1", "format": "en2fr", "q": "made to order", "options": ["sur commande", "sur place", "à emporter", "à volonté"], "a": 0, "expl": "« Le pain au levain, c'est sur commande » — order the day before."}, {"id": "ex-breakfast-B1-05", "level": "B1", "format": "collocation", "q": "Vous voulez du pain gris au lieu du blanc dans la formule. Que dites-vous ?", "options": ["Est-ce que je pourrais avoir du pain gris plutôt que du blanc ?", "Est-ce que je pourrais avoir du pain gris plutôt du blanc ?", "Je veux du pain gris et pas du blanc", "Il faut me donner du pain gris à la place"], "a": 0, "expl": "Conditional + « plutôt que » is the polite way to swap an item in a set deal. « Je veux » is grammatical but blunt with someone serving you."}, {"id": "ex-breakfast-B1-06", "level": "B1", "format": "fr2en", "q": "une praline (en Belgique)", "options": ["a filled chocolate", "a caramelised almond", "a praline paste", "a chocolate bar"], "a": 0, "expl": "In France « une praline » is a sugared almond. Belgium: Neuhaus, Leonidas, Marcolini, sold by weight in a ballotin."}, {"id": "ex-breakfast-B1-07", "level": "B1", "format": "cloze", "q": "Le pain d'hier est ___ , je vais faire du pain perdu.", "options": ["rassis", "frais", "moelleux", "croustillant"], "a": 0, "expl": "All four are masculine adjectives that fit. Pain perdu exists precisely to use up stale bread."}, {"id": "ex-breakfast-B1-08", "level": "B1", "format": "en2fr", "q": "to freeze (food)", "options": ["congeler", "geler", "refroidir", "glacer"], "a": 0, "expl": "« Geler » is what the weather does; food in a freezer is « congelé »."}, {"id": "ex-breakfast-B1-09", "level": "B1", "format": "fr2en", "q": "le sirop de Liège", "options": ["a dark apple-and-pear spread", "a sugar syrup for drinks", "a cough syrup", "a caramel sauce"], "a": 0, "expl": "Walloon speciality, eaten on bread with butter or with strong cheese. Not found in France."}, {"id": "ex-breakfast-B1-10", "level": "B1", "format": "cloze", "q": "Vous pouvez ___ griller, s'il vous plaît ?", "options": ["me les", "les me", "me leur", "leur les"], "a": 0, "expl": "Two object pronouns before the infinitive, in the fixed order: me/te/nous/vous first, then le/la/les."}, {"id": "ex-breakfast-B1-11", "level": "B1", "format": "fr2en", "q": "à l'avance", "options": ["ahead of time", "early, before the expected time", "at the front", "immediately"], "a": 0, "expl": "« Commander à l'avance » = to order ahead; « être en avance » = to arrive early. Different phrases."}, {"id": "ex-breakfast-B1-12", "level": "B1", "format": "en2fr", "q": "the crust of a loaf", "options": ["la croûte", "la mie", "la miette", "la tranche"], "a": 0, "expl": "« La mie » is the soft inside; « une miette » is a crumb on the table."}, {"id": "ex-breakfast-B1-13", "level": "B1", "format": "collocation", "q": "Quelle phrase décrit correctement les deux gaufres belges ?", "options": ["La gaufre de Liège est dense et caramélisée, celle de Bruxelles est légère et rectangulaire", "La gaufre de Liège est légère et rectangulaire, celle de Bruxelles est dense et caramélisée", "Les deux sont identiques, seul le nom change selon la ville", "La gaufre de Bruxelles se mange chaude à la main, celle de Liège avec une fourchette"], "a": 0, "expl": "Liège: pearl sugar, uneven edges, eaten warm in the hand. Bruxelles: rectangular, airy, eaten with sugar or cream on a plate."}, {"id": "ex-breakfast-B1-14", "level": "B1", "format": "fr2en", "q": "un habitué", "options": ["a regular customer", "an ordinary customer", "someone with a habit to break", "a resident of the neighbourhood"], "a": 0, "expl": "« C'est un habitué de la maison. » From « avoir l'habitude de »."}]},
  "hotel-A2": {"slug": "hotel", "level": "A2", "title": "Trouver une chambre sans réservation", "place": "Hôtel du Sablon, rue de Rollebeek, Bruxelles", "register": "vous", "registerNote": "Vous throughout. Hotel reception is a service relationship between strangers: the receptionist says vous to you and you say vous back, even in a small family hotel and even if the person looks your age. Tu here would sound either rude or oddly intimate.", "vocab": [{"id": "fvc-hotel-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la réception", "en": "the reception desk", "format": "fr2en", "options": ["the reception desk", "the recipe", "the receipt", "the takings"], "a": 0, "trap": "la recette — a recipe (and, for a shop, the day's takings)", "expl": "« Je vais à la réception » = I'm going to the front desk. The person there is « le réceptionniste » / « la réceptionniste »."}, {"id": "fvc-hotel-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "la chambre", "en": "the bedroom / hotel room", "format": "fr2en", "options": ["the bedroom / hotel room", "the hall or large public room", "the flat", "the floor of a building"], "a": 0, "trap": "la salle — a room you do something in (salle de bains, salle à manger), never a bedroom", "expl": "A room you sleep in is « une chambre ». « Une salle » is a functional room. Belgian flats are advertised by bedrooms: « un appartement deux chambres »."}, {"id": "fvc-hotel-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "le lit", "en": "the bed", "format": "en2fr", "options": ["le lit", "le lieu", "le linge", "le drap"], "a": 0, "trap": "le lieu — the place; one letter away and constantly confused", "expl": "« un grand lit » = a double bed, « des lits séparés » = twin beds. « le linge » is the linen/laundry, « le drap » the sheet."}, {"id": "fvc-hotel-A2-04", "level": "A2", "pos": "adj", "fr": "double", "en": "double (room, bed)", "format": "cloze", "q": "Je voudrais une chambre ___, pour deux personnes.", "options": ["double", "simple", "seule", "unique"], "a": 0, "trap": "simple — a single room, exactly the opposite of what two people need", "expl": "« une chambre double » sleeps two; « une chambre simple » sleeps one. All four adjectives fit grammatically after « chambre » — only « double » fits « pour deux personnes »."}, {"id": "fvc-hotel-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la clé", "en": "the key", "format": "fr2en", "options": ["the key", "the lock", "the door handle", "the key card slot"], "a": 0, "trap": "la serrure — the lock the key goes into", "expl": "Spelt « la clé » or « la clef », same word, same sound. Hotels now hand you « une carte magnétique » but everyone still says « la clé »."}, {"id": "fvc-hotel-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'ascenseur", "en": "the lift", "format": "fr2en", "options": ["the lift", "the staircase", "the escalator", "the corridor"], "a": 0, "trap": "l'escalier — the stairs; « l'escalator » is the moving one (also « l'escalier roulant »)", "expl": "« L'ascenseur est au fond du couloir. » In old Brussels town houses converted into hotels there often isn't one — worth asking if you have a big suitcase."}, {"id": "fvc-hotel-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'étage", "en": "the floor / storey", "format": "fr2en", "options": ["the floor / storey", "the internship", "the shelf", "the stage of a race"], "a": 0, "trap": "le stage — an internship; the classic false friend for English 'stage'", "expl": "« au troisième étage » = on the third floor. Careful: « le premier étage » is one floor above street level, as in the UK, not the ground floor."}, {"id": "fvc-hotel-A2-08", "level": "A2", "pos": "noun", "gender": "m", "fr": "le rez-de-chaussée", "en": "the ground floor", "format": "en2fr", "options": ["le rez-de-chaussée", "le sous-sol", "le dernier étage", "le palier"], "a": 0, "trap": "le sous-sol — the basement, which is below the ground floor", "expl": "Written « rez-de-chaussée », often abbreviated « rez » or « RDC » in lifts. Pronounced ré-de-cho-ssé, the z is silent."}, {"id": "fvc-hotel-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la salle de bains", "en": "the bathroom", "format": "en2fr", "options": ["la salle de bains", "la salle à manger", "la salle d'attente", "la salle de séjour"], "a": 0, "trap": "la salle de séjour — the living room, not the bathroom", "expl": "All four are « la salle de/à … ». Note the s: « salle de bains » (the plural is traditional). The toilet alone is « les toilettes » or « le WC »."}, {"id": "fvc-hotel-A2-10", "level": "A2", "pos": "noun", "gender": "f", "fr": "la douche", "en": "the shower", "format": "cloze", "q": "La chambre a une ___, mais pas de baignoire.", "options": ["douche", "baignoire", "piscine", "terrasse"], "a": 0, "trap": "la baignoire — the bathtub; the sentence rules it out by meaning, not by grammar", "expl": "All four are feminine nouns that fit after « une ». Only « douche » makes sense against « mais pas de baignoire »."}, {"id": "fvc-hotel-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la serviette", "en": "the towel", "format": "fr2en", "options": ["the towel", "the bedsheet", "the tablecloth", "the blanket"], "a": 0, "trap": "le drap — the sheet; and « la serviette » also means napkin and briefcase, so context decides", "expl": "In a hotel « une serviette » is a towel: « Est-ce que je peux avoir une serviette de plus ? » At table the same word is the napkin."}, {"id": "fvc-hotel-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le petit déjeuner", "en": "breakfast", "format": "fr2en", "options": ["breakfast", "lunch", "the evening meal", "a mid-morning snack"], "a": 0, "trap": "le déjeuner — lunch in France, but breakfast in Belgian usage; the single most confusing meal word here", "expl": "Belgian French: déjeuner = breakfast, dîner = lunch, souper = evening meal. France: petit-déjeuner, déjeuner, dîner. Hotels write « petit déjeuner » on the sign, which is safe everywhere."}, {"id": "fvc-hotel-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "le souper", "en": "the evening meal (Belgian French)", "format": "fr2en", "options": ["the evening meal", "a light snack", "lunch", "a dinner party"], "a": 0, "trap": "le dîner — the evening meal in France, but lunch in Belgium", "expl": "Belgian: « On soupe à sept heures. » In France « souper » sounds old-fashioned or means a very late supper after the theatre. Say « le repas du soir » if you want to be neutral.", "note": "Belgian French. France uses dîner for the evening meal."}, {"id": "fvc-hotel-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la nuit", "en": "the night", "format": "cloze", "q": "Nous restons trois ___, du lundi au jeudi.", "options": ["nuits", "semaines", "heures", "minutes"], "a": 0, "trap": "les semaines — weeks; grammatically perfect, but Monday to Thursday is three nights", "expl": "Hotels count nights, not days: « trois nuits » = check in Monday, check out Thursday. « Le prix est par nuit et par chambre. »"}, {"id": "fvc-hotel-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "la taxe de séjour", "en": "the city / tourist tax", "format": "fr2en", "options": ["the city tax on each night", "the tourist office", "the security deposit", "the service charge"], "a": 0, "trap": "la caution — the refundable deposit, which is a different thing entirely", "expl": "In Brussels the city tax is charged per room per night — around 5 € in 2026 — and is often added at the desk, not shown in the online price.", "note": "Belgian detail: Brussels charges per room per night. In France the taxe de séjour is per person per night."}, {"id": "fvc-hotel-A2-16", "level": "A2", "pos": "noun", "gender": "f", "fr": "la caution", "en": "the deposit / guarantee", "format": "fr2en", "options": ["the refundable deposit", "the tip", "the fine", "the receipt"], "a": 0, "trap": "le pourboire — the tip, money you give and don't get back", "expl": "« Une caution » is held and returned. In hotels it is usually « une empreinte de carte » — a card pre-authorisation rather than real money taken."}, {"id": "fvc-hotel-A2-17", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte d'identité", "en": "the ID card", "format": "en2fr", "options": ["la carte d'identité", "la carte de fidélité", "la carte postale", "la carte de crédit"], "a": 0, "trap": "la carte de crédit — the credit card, asked for in the same breath at check-in", "expl": "Belgian hotels are legally required to record ID for every guest, so « votre carte d'identité, s'il vous plaît » is routine, not suspicion."}, {"id": "fvc-hotel-A2-18", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte de crédit", "en": "the credit card", "format": "collocation", "q": "Which card will a Brussels hotel NOT normally accept as the guarantee for your room?", "options": ["une carte Bancontact (débit)", "une carte Visa", "une carte Mastercard", "une carte American Express"], "a": 0, "trap": "Bancontact pays for almost everything in Belgium, which is exactly why learners assume it works here too", "expl": "Bancontact is a debit scheme: it cannot be pre-authorised, so hotels ask for a real credit card for the guarantee — or ask you to pay the whole stay up front.", "note": "Belgian detail: Bancontact is the Belgian debit network. France uses 'carte bleue' / CB, which is usually credit-capable."}, {"id": "fvc-hotel-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le mot de passe", "en": "the password", "format": "fr2en", "options": ["the password", "the motto", "the message", "the watchword of a party"], "a": 0, "trap": "la devise — a motto; and « le mot » alone is just 'the word'", "expl": "« Quel est le mot de passe du wifi ? » Hotel wifi passwords are often the phone number or the hotel name plus the year."}, {"id": "fvc-hotel-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le parking", "en": "the car park", "format": "fr2en", "options": ["the car park", "the parking fine", "the parking meter", "the parking space marking"], "a": 0, "trap": "l'amende — the fine; « le parking » never means the act of parking", "expl": "In French « un parking » is the place. The act is « le stationnement » — which is what the blue street signs say in Brussels."}, {"id": "fvc-hotel-A2-21", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'annulation", "en": "the cancellation", "format": "en2fr", "options": ["l'annulation", "la réservation", "la réclamation", "la résiliation"], "a": 0, "trap": "la résiliation — cancelling a contract or subscription, not a booking", "expl": "All four are feminine. « L'annulation est gratuite jusqu'à dix-huit heures. » The verb is « annuler »."}, {"id": "fvc-hotel-A2-22", "level": "A2", "pos": "noun", "gender": "f", "fr": "la valise", "en": "the suitcase", "format": "en2fr", "options": ["la valise", "la sacoche", "la poche", "la housse"], "a": 0, "trap": "la sacoche — a satchel or pannier bag", "expl": "All four feminine. « Je peux laisser ma valise à la réception ? » is the phrase for the hours between check-out and your train."}, {"id": "fvc-hotel-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le coffre-fort", "en": "the safe", "format": "fr2en", "options": ["the safe in the room", "the car boot", "the chest of drawers", "the wardrobe"], "a": 0, "trap": "le coffre — on its own that is the boot of a car or a chest", "expl": "« Il y a un coffre-fort dans l'armoire. » Plural: des coffres-forts, both parts agree."}, {"id": "fvc-hotel-A2-24", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chauffage", "en": "the heating", "format": "cloze", "q": "Il fait froid dans la chambre : le ___ ne marche pas.", "options": ["chauffage", "climatiseur", "frigo", "ascenseur"], "a": 0, "trap": "le climatiseur — the air conditioner, which would make the room colder, not warmer", "expl": "All four are masculine nouns that fit after « le ». Cold room plus broken machine points to the heating. « Ça ne marche pas » is the everyday way to say something is not working."}, {"id": "fvc-hotel-A2-25", "level": "A2", "pos": "noun", "gender": "f", "fr": "la climatisation", "en": "the air conditioning", "format": "fr2en", "options": ["the air conditioning", "the heating", "the ventilation shaft", "the radiator"], "a": 0, "trap": "le chauffage — the heating; the two are constantly swapped by learners", "expl": "Shortened to « la clim » in speech: « Il n'y a pas la clim ? » Most older Brussels hotels genuinely don't have it."}, {"id": "fvc-hotel-A2-26", "level": "A2", "pos": "noun", "gender": "f", "fr": "la vue", "en": "the view", "format": "collocation", "q": "Which is the correct way to ask for a room looking onto the park?", "options": ["une chambre avec vue sur le parc", "une chambre avec vue au parc", "une chambre avec vue du parc", "une chambre à vue sur parc"], "a": 0, "trap": "« vue du parc » sounds right to an English ear but means the view belonging to the park", "expl": "The fixed preposition is « vue sur » : vue sur la mer, vue sur la rue, vue sur le jardin. Also « une chambre qui donne sur la cour »."}, {"id": "fvc-hotel-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'arrivée", "en": "the arrival / check-in", "format": "cloze", "q": "L'heure d'___ est fixée à quatorze heures.", "options": ["arrivée", "attente", "ouverture", "addition"], "a": 0, "trap": "l'ouverture — the opening time, plausible for a shop but not for a hotel room", "expl": "All four are feminine nouns starting with a vowel, so « d' » gives nothing away. Hotels say « l'heure d'arrivée » and « l'heure de départ »."}, {"id": "fvc-hotel-A2-28", "level": "A2", "pos": "noun", "gender": "m", "fr": "le départ", "en": "the departure / check-out", "format": "fr2en", "options": ["the check-out / departure", "the delay", "the stopover", "the arrival"], "a": 0, "trap": "l'arrivée — its exact opposite, and the word on the neighbouring line of every sign", "expl": "« Le départ se fait avant onze heures. » You can also hear the English « le check-out » in bigger chains."}, {"id": "fvc-hotel-A2-29", "level": "A2", "pos": "noun", "gender": "f", "fr": "la note", "en": "the hotel bill", "format": "fr2en", "options": ["the hotel bill", "the restaurant bill", "the banknote", "the receipt"], "a": 0, "trap": "l'addition — the bill, but only in a restaurant or café", "expl": "Hotel: « la note ». Restaurant: « l'addition ». Shop or company: « la facture ». Asking for « l'addition » at reception is a small but very audible slip."}, {"id": "fvc-hotel-A2-30", "level": "A2", "pos": "noun", "gender": "m", "fr": "le reçu", "en": "the receipt", "format": "en2fr", "options": ["le reçu", "le remboursement", "le rabais", "le bordereau"], "a": 0, "trap": "le remboursement — a refund, not a receipt", "expl": "All four masculine. « Je peux avoir un reçu ? » The little till slip is also « le ticket » ; a formal invoice is « une facture »."}, {"id": "fvc-hotel-A2-31", "level": "A2", "pos": "verb", "fr": "réserver", "en": "to book", "format": "fr2en", "options": ["to book", "to cancel", "to confirm", "to postpone"], "a": 0, "trap": "annuler — to cancel, the verb that appears in the same sentence", "expl": "« J'ai réservé sur internet. » / « Je n'ai pas réservé. » The noun is « une réservation »."}, {"id": "fvc-hotel-A2-32", "level": "A2", "pos": "verb", "fr": "annuler", "en": "to cancel", "format": "cloze", "q": "Je voudrais ___ ma réservation pour demain soir.", "options": ["annuler", "réserver", "confirmer", "commander"], "a": 0, "trap": "réserver — you cannot book a booking you already have", "expl": "All four infinitives follow « je voudrais » perfectly; only « annuler » works on a reservation you already hold."}, {"id": "fvc-hotel-A2-33", "level": "A2", "pos": "verb", "fr": "rester", "en": "to stay", "format": "fr2en", "options": ["to stay / remain", "to rest", "to go back", "to stop"], "a": 0, "trap": "'to rest' — a genuine false friend; that is « se reposer »", "expl": "« Je reste deux nuits. » Rester takes être in the passé composé: « je suis resté deux nuits »."}, {"id": "fvc-hotel-A2-34", "level": "A2", "pos": "verb", "fr": "se reposer", "en": "to rest", "format": "en2fr", "options": ["se reposer", "rester", "se lever", "se dépêcher"], "a": 0, "trap": "rester — to stay, the false friend running the other way", "expl": "All four are verbs. « Je vais me reposer un peu avant de sortir. » Reflexive: je me repose, vous vous reposez."}, {"id": "fvc-hotel-A2-35", "level": "A2", "pos": "verb", "fr": "remplir", "en": "to fill in (a form)", "format": "cloze", "q": "Vous pouvez ___ cette fiche et la signer, s'il vous plaît ?", "options": ["remplir", "signer", "acheter", "réserver"], "a": 0, "trap": "signer — already used later in the same sentence, so it cannot be the answer", "expl": "« Remplir un formulaire / une fiche » = to fill in a form. Reading the whole sentence, not just the gap, is what makes this one easy."}, {"id": "fvc-hotel-A2-36", "level": "A2", "pos": "verb", "fr": "monter", "en": "to go up / take up", "format": "fr2en", "options": ["to go up", "to show", "to go down", "to move house"], "a": 0, "trap": "montrer — to show; one letter apart and both very common", "expl": "« Je monte votre valise. » = I'll take your suitcase up. Opposite: « descendre »."}, {"id": "fvc-hotel-A2-37", "level": "A2", "pos": "verb", "fr": "coûter", "en": "to cost", "format": "cloze", "q": "La chambre ___ nonante-cinq euros la nuit.", "options": ["coûte", "paie", "achète", "dépense"], "a": 0, "trap": "paie — people pay, rooms don't; the subject decides", "expl": "All four are third-person singular verbs. Only « coûter » takes a price as its object with a thing as its subject: « ça coûte 95 € »."}, {"id": "fvc-hotel-A2-38", "level": "A2", "pos": "adj", "fr": "complet", "en": "fully booked", "format": "fr2en", "options": ["fully booked", "completed", "complicated", "free of charge"], "a": 0, "trap": "'complimentary' — the English word that sounds like it; free of charge is « gratuit »", "expl": "« Désolé, nous sommes complets ce soir. » On a hotel or car park sign, COMPLET means no space left."}, {"id": "fvc-hotel-A2-39", "level": "A2", "pos": "adj", "fr": "libre", "en": "free / available", "format": "fr2en", "options": ["available / vacant", "free of charge", "generous", "spacious"], "a": 0, "trap": "'free of charge' — that is « gratuit »; libre is about availability", "expl": "« Vous avez une chambre libre ? » = have you got a room free. A free-of-charge breakfast is « un petit déjeuner gratuit »."}, {"id": "fvc-hotel-A2-40", "level": "A2", "pos": "adj", "fr": "gratuit", "en": "free of charge", "format": "cloze", "q": "Le wifi est ___ dans tout l'hôtel.", "options": ["gratuit", "libre", "complet", "cher"], "a": 0, "trap": "libre — grammatically fine, but it would mean the wifi is 'vacant'", "expl": "All four are adjectives agreeing with « le wifi ». Costs nothing = gratuit; not occupied = libre."}, {"id": "fvc-hotel-A2-41", "level": "A2", "pos": "adj", "fr": "compris", "en": "included", "format": "cloze", "q": "Le petit déjeuner n'est pas ___ : c'est dix-huit euros en plus.", "options": ["compris", "cher", "ouvert", "libre"], "a": 0, "trap": "cher — expensive; it fits the grammar and half the meaning, which is what makes it tempting", "expl": "« compris » = included in the price. You will also see « petit déjeuner inclus » on booking sites — same idea."}, {"id": "fvc-hotel-A2-42", "level": "A2", "pos": "adj", "fr": "calme", "en": "quiet", "format": "fr2en", "options": ["quiet", "noisy", "narrow", "dark"], "a": 0, "trap": "bruyant — noisy; the word the receptionist will use about the street side", "expl": "« Je voudrais une chambre calme. » For a person, « calme » means relaxed. For a room it means away from the noise."}, {"id": "fvc-hotel-A2-43", "level": "A2", "pos": "adj", "fr": "bruyant", "en": "noisy", "format": "en2fr", "options": ["bruyant", "brumeux", "brûlant", "brillant"], "a": 0, "trap": "brillant — shiny/brilliant; all four look almost identical", "expl": "From « le bruit » (the noise). « La rue est un peu bruyante le vendredi soir. »"}, {"id": "fvc-hotel-A2-44", "level": "A2", "pos": "adj", "fr": "propre", "en": "clean", "format": "fr2en", "options": ["clean", "dirty", "proper / correct", "private"], "a": 0, "trap": "'proper' — the lookalike English word; and before the noun « ma propre chambre » means my own room", "expl": "After the noun = clean: « une chambre propre ». Before the noun = own: « ma propre voiture ». Opposite: « sale »."}, {"id": "fvc-hotel-A2-45", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "fr2en", "options": ["seventy", "seventeen", "seventy-seven", "ninety"], "a": 0, "trap": "soixante-dix — the French form of the same number, which is what you were taught at school", "expl": "« septante-cinq euros » = 75 €. Say it and hear it in Brussels; nobody will blink.", "note": "Belgian French. France says soixante-dix. Belgium keeps quatre-vingts, though — there is no 'octante'."}, {"id": "fvc-hotel-A2-46", "level": "A2", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "fr2en", "options": ["ninety", "nineteen", "ninety-nine", "seventy"], "a": 0, "trap": "quatre-vingt-dix — the French form; both are understood in Belgium but only nonante is said", "expl": "« nonante-cinq euros la nuit » = 95 € a night. Prices at the desk come at you fast, so train the Belgian numbers.", "note": "Belgian French. France says quatre-vingt-dix."}, {"id": "fvc-hotel-A2-47", "level": "A2", "pos": "expr", "fr": "s'il vous plaît", "en": "here you go (Belgian use)", "format": "collocation", "q": "A Brussels receptionist hands you your key and says « Voilà, s'il vous plaît ». What does s'il vous plaît mean here?", "options": ["here you go", "you're welcome", "excuse me", "please hurry"], "a": 0, "trap": "'please' — the meaning you already know, which is exactly why the handing-over use surprises learners", "expl": "Copied from Dutch « alstublieft », which does both jobs. You hear it every time something is handed to you in Belgium.", "note": "Belgian French. In France, handing something over you say « voilà » or « tenez » — never s'il vous plaît."}, {"id": "fvc-hotel-A2-48", "level": "A2", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile phone (Belgian French)", "format": "fr2en", "options": ["the mobile phone", "the landline", "the charger", "the satnav"], "a": 0, "trap": "le portable — the French word for the same object (and in Belgium often a laptop)", "expl": "Pronounced gé-esse-em. « Vous avez mon numéro de GSM ? » Forms in Belgium print « GSM » where French forms print « portable ».", "note": "Belgian French. France says le portable or le téléphone."}], "phrases": [{"id": "ph-hotel-A2-01", "fr": "Bonjour, je n'ai pas de réservation.", "en": "Hello, I don't have a reservation.", "note": "Say it first, before anything else — it changes everything the receptionist will do next. « Pas de » never becomes « pas d'une »."}, {"id": "ph-hotel-A2-02", "fr": "Est-ce que vous avez une chambre libre pour cette nuit ?", "en": "Do you have a room free for tonight?", "note": "The core walk-in question. « libre » = available; « gratuite » would mean free of charge."}, {"id": "ph-hotel-A2-03", "fr": "C'est pour une personne, pour deux nuits.", "en": "It's for one person, for two nights.", "note": "Give the two numbers unprompted; it saves a whole exchange. Hotels count nights, not days."}, {"id": "ph-hotel-A2-04", "fr": "Quel est le prix de la chambre par nuit ?", "en": "What's the price of the room per night?", "note": "« par nuit » — not « une nuit ». You can also say « C'est combien la nuit ? », which is more spoken."}, {"id": "ph-hotel-A2-05", "fr": "Est-ce que le petit déjeuner est compris ?", "en": "Is breakfast included?", "note": "In Belgium it very often is not. Ask before you sit down at the buffet — it is typically 15–20 € extra."}, {"id": "ph-hotel-A2-06", "fr": "Est-ce qu'il y a la taxe de séjour en plus ?", "en": "Is there city tax on top?", "note": "Brussels charges around 5 € per room per night in 2026 and hotels often add it at the desk. In France it is per person."}, {"id": "ph-hotel-A2-07", "fr": "Je voudrais une chambre calme, si c'est possible.", "en": "I'd like a quiet room, if possible.", "note": "« si c'est possible » softens any request in French and costs you nothing."}, {"id": "ph-hotel-A2-08", "fr": "Est-ce que la chambre donne sur la rue ?", "en": "Does the room look onto the street?", "note": "« donner sur » = to look onto. The other answer you want to hear is « sur la cour » (onto the courtyard)."}, {"id": "ph-hotel-A2-09", "fr": "Je peux payer par Bancontact ?", "en": "Can I pay by Bancontact?", "note": "Bancontact is the Belgian debit card network — say it, not « carte bleue », which is French. It pays the bill but usually can't serve as the guarantee."}, {"id": "ph-hotel-A2-10", "fr": "Je n'ai pas de carte de crédit, seulement une carte Bancontact.", "en": "I don't have a credit card, only a Bancontact card.", "note": "The sentence that unblocks the check-in: the desk will then ask you to pay the whole stay up front."}, {"id": "ph-hotel-A2-11", "fr": "Voilà ma carte d'identité.", "en": "Here's my ID card.", "note": "In Belgium you can also say « s'il vous plaît » as you hand it over — that is the local 'here you go'."}, {"id": "ph-hotel-A2-12", "fr": "À quelle heure est le petit déjeuner ?", "en": "What time is breakfast?", "note": "Answer usually comes as a range: « de sept heures à dix heures »."}, {"id": "ph-hotel-A2-13", "fr": "À quelle heure faut-il libérer la chambre ?", "en": "What time do we have to vacate the room?", "note": "« libérer la chambre » is what hotels say for check-out. Also heard: « Le départ se fait avant onze heures. »"}, {"id": "ph-hotel-A2-14", "fr": "Quel est le mot de passe du wifi ?", "en": "What's the wifi password?", "note": "Wifi is pronounced wee-fee. Some places say « le code wifi » instead."}, {"id": "ph-hotel-A2-15", "fr": "Il n'y a pas de serviette dans la salle de bains.", "en": "There's no towel in the bathroom.", "note": "After « il n'y a pas de » the article disappears: never « pas de la serviette »."}, {"id": "ph-hotel-A2-16", "fr": "Le chauffage ne marche pas dans la chambre 312.", "en": "The heating isn't working in room 312.", "note": "« ça ne marche pas » is the everyday way to report a fault; « ne fonctionne pas » is the written version."}, {"id": "ph-hotel-A2-17", "fr": "Est-ce que je peux laisser ma valise à la réception ?", "en": "Can I leave my suitcase at reception?", "note": "The check-out-day question. Say « jusqu'à quinze heures » to give a time."}, {"id": "ph-hotel-A2-18", "fr": "Vous avez un parking pour les clients ?", "en": "Do you have parking for guests?", "note": "A hotel guest is « un client ». Central Brussels parking is often an outside garage at 25–30 € a night."}, {"id": "ph-hotel-A2-19", "fr": "Je peux avoir la note, s'il vous plaît ?", "en": "Can I have the bill, please?", "note": "Hotel = « la note ». Restaurant = « l'addition ». If you need it for work, ask for « une facture au nom de… »."}, {"id": "ph-hotel-A2-20", "fr": "Merci beaucoup, bonne soirée.", "en": "Thank you very much, have a good evening.", "note": "« Bonne soirée » after about 17:00, « bonne journée » before. Both close a counter conversation neatly."}], "dialogue": [{"who": "receptionist", "fr": "Bonsoir monsieur, bienvenue à l'hôtel du Sablon. Je peux vous aider ?", "en": "Good evening sir, welcome to the Hôtel du Sablon. Can I help you?", "gloss": {"bienvenue": "welcome", "aider": "to help"}}, {"who": "you", "fr": "Bonsoir. Je n'ai pas de réservation. Est-ce que vous avez une chambre libre pour cette nuit ?", "en": "Good evening. I don't have a reservation. Do you have a room free for tonight?", "gloss": {"réservation": "booking", "libre": "free, available"}, "accept": ["bonsoir je n'ai pas de réservation est-ce que vous avez une chambre libre pour cette nuit", "bonsoir je n'ai pas de réservation vous avez une chambre libre pour cette nuit", "bonsoir je n'ai pas réservé est-ce que vous avez une chambre libre pour cette nuit", "bonsoir je n'ai pas de réservation avez-vous une chambre libre pour cette nuit", "je n'ai pas de réservation est-ce que vous avez une chambre libre ce soir", "bonsoir est-ce que vous avez une chambre libre pour cette nuit", "bonsoir vous avez une chambre pour cette nuit s'il vous plaît"]}, {"who": "receptionist", "fr": "C'est pour combien de personnes ?", "en": "How many people is it for?", "gloss": {"combien": "how many"}}, {"who": "you", "fr": "Pour une personne, s'il vous plaît. Et pour deux nuits, si c'est possible.", "en": "For one person, please. And for two nights, if possible.", "gloss": {"nuits": "nights"}, "accept": ["pour une personne s'il vous plaît et pour deux nuits si c'est possible", "pour une personne et pour deux nuits s'il vous plaît", "pour une personne deux nuits s'il vous plaît", "c'est pour une personne et deux nuits", "pour une personne pour deux nuits si c'est possible", "juste pour moi pour deux nuits s'il vous plaît"]}, {"who": "receptionist", "fr": "Alors, il me reste une chambre simple au troisième étage, à nonante-cinq euros la nuit.", "en": "Well, I have one single room left on the third floor, at ninety-five euros a night.", "gloss": {"il me reste": "I have left", "simple": "single", "étage": "floor", "nonante": "ninety (Belgian French; France: quatre-vingt-dix)"}}, {"who": "you", "fr": "D'accord. Est-ce que le petit déjeuner est compris dans le prix ?", "en": "All right. Is breakfast included in the price?", "gloss": {"compris": "included"}, "accept": ["d'accord est-ce que le petit déjeuner est compris dans le prix", "est-ce que le petit déjeuner est compris", "d'accord est-ce que le petit déjeuner est compris", "le petit déjeuner est compris", "est-ce que le petit déjeuner est inclus dans le prix", "d'accord et le petit déjeuner il est compris"]}, {"who": "receptionist", "fr": "Non, il est en supplément : dix-huit euros par personne. Le buffet est servi de sept heures à dix heures.", "en": "No, it's extra: eighteen euros per person. The buffet is served from seven to ten.", "gloss": {"en supplément": "extra, on top", "servi": "served"}}, {"who": "you", "fr": "Merci. Et est-ce que la chambre est calme ? Je voudrais une chambre qui donne sur la cour.", "en": "Thank you. And is the room quiet? I'd like a room looking onto the courtyard.", "gloss": {"calme": "quiet", "donne sur": "looks onto", "cour": "courtyard"}, "accept": ["merci et est-ce que la chambre est calme je voudrais une chambre qui donne sur la cour", "est-ce que la chambre est calme je voudrais une chambre qui donne sur la cour", "est-ce que la chambre est calme", "est-ce que vous avez une chambre calme qui donne sur la cour", "je voudrais une chambre calme sur la cour s'il vous plaît", "et la chambre est calme je préfère une chambre sur la cour"]}, {"who": "receptionist", "fr": "La chambre 312 donne sur la cour, oui. Elle est très calme, il n'y a pas de bruit.", "en": "Room 312 looks onto the courtyard, yes. It's very quiet, there's no noise.", "gloss": {"bruit": "noise"}}, {"who": "you", "fr": "Parfait, je la prends. Ça fait combien pour les deux nuits ?", "en": "Perfect, I'll take it. How much is it for the two nights?", "gloss": {"je la prends": "I'll take it", "Ça fait": "that comes to"}, "accept": ["parfait je la prends ça fait combien pour les deux nuits", "je la prends ça fait combien pour les deux nuits", "très bien je la prends c'est combien pour les deux nuits", "d'accord je la prends combien ça coûte pour deux nuits", "parfait je la prends combien je vous dois pour les deux nuits", "je la prends quel est le prix pour les deux nuits"]}, {"who": "receptionist", "fr": "Cent nonante euros, plus la taxe de séjour : cinq euros par nuit et par chambre. Donc deux cents euros au total.", "en": "One hundred and ninety euros, plus the city tax: five euros per night per room. So two hundred euros in total.", "gloss": {"taxe de séjour": "city tax", "au total": "in total"}}, {"who": "you", "fr": "Très bien. Est-ce que je peux payer par Bancontact ?", "en": "Very good. Can I pay by Bancontact?", "gloss": {"payer": "to pay"}, "accept": ["très bien est-ce que je peux payer par bancontact", "est-ce que je peux payer par bancontact", "je peux payer par bancontact", "d'accord est-ce que je peux payer par bancontact", "est-ce que je peux payer avec ma carte bancontact", "vous acceptez le bancontact"]}, {"who": "receptionist", "fr": "Pour le paiement, bien sûr. Mais pour la garantie, il me faut une carte de crédit. Et votre carte d'identité, s'il vous plaît.", "en": "For the payment, of course. But for the guarantee I need a credit card. And your ID card, please.", "gloss": {"garantie": "guarantee, deposit", "il me faut": "I need"}}, {"who": "you", "fr": "Voilà ma carte d'identité. Mais je n'ai pas de carte de crédit, seulement une carte Bancontact.", "en": "Here's my ID card. But I don't have a credit card, only a Bancontact card.", "gloss": {"Voilà": "here is"}, "accept": ["voilà ma carte d'identité mais je n'ai pas de carte de crédit seulement une carte bancontact", "voilà ma carte d'identité je n'ai pas de carte de crédit seulement une carte bancontact", "voici ma carte d'identité mais je n'ai pas de carte de crédit", "voilà ma carte d'identité je n'ai qu'une carte bancontact", "s'il vous plaît voilà ma carte d'identité mais je n'ai pas de carte de crédit", "je n'ai pas de carte de crédit j'ai seulement une carte bancontact"]}, {"who": "receptionist", "fr": "Pas de problème. Dans ce cas, je vous demande de payer les deux nuits maintenant. Vous pouvez remplir cette fiche ?", "en": "No problem. In that case I'll ask you to pay for the two nights now. Can you fill in this form?", "gloss": {"Dans ce cas": "in that case", "remplir": "to fill in", "fiche": "form, card"}}, {"who": "you", "fr": "Bien sûr. Est-ce qu'il y a un ascenseur ? Ma valise est assez lourde.", "en": "Of course. Is there a lift? My suitcase is quite heavy.", "gloss": {"ascenseur": "lift", "valise": "suitcase", "lourde": "heavy"}, "accept": ["bien sûr est-ce qu'il y a un ascenseur ma valise est assez lourde", "est-ce qu'il y a un ascenseur ma valise est assez lourde", "bien sûr est-ce qu'il y a un ascenseur", "il y a un ascenseur ma valise est lourde", "est-ce qu'il y a un ascenseur s'il vous plaît", "d'accord vous avez un ascenseur ma valise est très lourde"]}, {"who": "receptionist", "fr": "Oui, l'ascenseur est au fond du couloir, à droite. Voici votre clé, s'il vous plaît : chambre 312, troisième étage.", "en": "Yes, the lift is at the end of the corridor, on the right. Here's your key: room 312, third floor.", "gloss": {"au fond": "at the end", "couloir": "corridor", "clé": "key", "s'il vous plaît": "here you go (Belgian use when handing something over)"}}, {"who": "you", "fr": "Merci beaucoup. À quelle heure faut-il libérer la chambre demain ?", "en": "Thank you very much. What time do we have to vacate the room tomorrow?", "gloss": {"libérer": "to vacate, to free up"}, "accept": ["merci beaucoup à quelle heure faut-il libérer la chambre demain", "à quelle heure faut-il libérer la chambre demain", "merci à quelle heure est le départ demain", "merci beaucoup à quelle heure je dois libérer la chambre", "à quelle heure est le check-out demain", "merci et à quelle heure faut-il quitter la chambre"]}, {"who": "receptionist", "fr": "Le départ se fait avant onze heures. Si vous voulez, vous pouvez laisser votre valise ici après. Bonne soirée !", "en": "Check-out is before eleven. If you like, you can leave your suitcase here afterwards. Have a good evening!", "gloss": {"départ": "check-out, departure", "laisser": "to leave (something)"}}, {"who": "you", "fr": "C'est très gentil. Bonne soirée à vous aussi.", "en": "That's very kind. Have a good evening too.", "gloss": {"gentil": "kind"}, "accept": ["c'est très gentil bonne soirée à vous aussi", "c'est très gentil merci bonne soirée", "merci beaucoup bonne soirée", "c'est gentil bonne soirée à vous aussi", "parfait merci bonne soirée à vous", "merci bonne soirée à vous aussi"]}], "exercises": [{"id": "ex-hotel-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la note", "en": "the hotel bill", "format": "cloze", "q": "Je peux avoir ___, s'il vous plaît ? Je pars demain matin.", "options": ["la note", "l'addition", "la facture", "la recette"], "a": 0, "trap": "l'addition — correct in a restaurant, wrong at a hotel desk", "expl": "All four are feminine nouns. Hotel = la note, restaurant = l'addition, company invoice = la facture."}, {"id": "ex-hotel-A2-02", "level": "A2", "pos": "adj", "fr": "libre", "en": "available", "format": "cloze", "q": "Vous avez une chambre ___ pour ce soir ?", "options": ["libre", "gratuite", "propre", "chère"], "a": 0, "trap": "gratuite — free of charge; the hotel would love you to be wrong here", "expl": "All four are feminine adjectives agreeing with « chambre ». Availability = libre."}, {"id": "ex-hotel-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'étage", "en": "the floor", "format": "fr2en", "options": ["the floor / storey", "the internship", "the stage", "the shelf"], "a": 0, "trap": "le stage — internship; the false friend of English 'stage'", "expl": "« Votre chambre est au troisième étage. » An internship is « un stage », a shelf « une étagère »."}, {"id": "ex-hotel-A2-04", "level": "A2", "pos": "verb", "fr": "rester", "en": "to stay", "format": "cloze", "q": "Nous allons ___ trois nuits à Bruxelles.", "options": ["rester", "reposer", "arrêter", "quitter"], "a": 0, "trap": "reposer — 'to rest' looks like the answer to an English ear", "expl": "All four are infinitives after « aller ». To spend time somewhere = rester. To rest = se reposer, and it needs the reflexive pronoun."}, {"id": "ex-hotel-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la clé", "en": "the key", "format": "en2fr", "options": ["la clé", "la serrure", "la porte", "la poignée"], "a": 0, "trap": "la serrure — the lock, not the key", "expl": "All four feminine. « Voici votre clé » or « votre carte magnétique » in newer hotels."}, {"id": "ex-hotel-A2-06", "level": "A2", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "cloze", "q": "La chambre coûte ___-cinq euros la nuit, monsieur.", "options": ["nonante", "septante", "quarante", "soixante"], "a": 0, "trap": "septante — the other Belgian number word; both are Belgian, only one is ninety", "expl": "nonante = 90, septante = 70. So nonante-cinq = 95 €.", "note": "Belgian French. In France the same amounts are quatre-vingt-quinze and soixante-quinze."}, {"id": "ex-hotel-A2-07", "level": "A2", "pos": "noun", "gender": "f", "fr": "la taxe de séjour", "en": "the city tax", "format": "collocation", "q": "Which sentence is right about the Brussels city tax in 2026?", "options": ["C'est environ cinq euros par nuit et par chambre.", "C'est environ cinq euros par nuit et par personne.", "C'est un pourcentage du prix de la chambre.", "C'est compris dans le prix affiché sur internet."], "a": 0, "trap": "the per-person version — that is how France charges it, and it is the answer most learners pick", "expl": "Brussels taxes the room, not the head, and hotels frequently add it at the desk on top of the online rate."}, {"id": "ex-hotel-A2-08", "level": "A2", "pos": "verb", "fr": "remplir", "en": "to fill in", "format": "fr2en", "options": ["to fill in", "to empty", "to hand over", "to tear up"], "a": 0, "trap": "vider — to empty, its exact opposite", "expl": "« Vous pouvez remplir cette fiche ? » You fill in « un formulaire », « une fiche », « un document »."}, {"id": "ex-hotel-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "le petit déjeuner", "en": "breakfast", "format": "collocation", "q": "In Belgian French, which meal is « le dîner » ?", "options": ["le repas de midi", "le repas du soir", "le premier repas du matin", "un repas de fête"], "a": 0, "trap": "'the evening meal' — right in France, wrong in Belgium", "expl": "Belgium: déjeuner = breakfast, dîner = lunch, souper = evening meal. France shifts everything one step: petit-déjeuner, déjeuner, dîner.", "note": "Belgian French. Say « le repas du soir » if you want to be understood everywhere."}, {"id": "ex-hotel-A2-10", "level": "A2", "pos": "prep", "fr": "sur", "en": "onto (in « vue sur »)", "format": "cloze", "q": "Nous avons une chambre avec vue ___ le jardin.", "options": ["sur", "à", "de", "en"], "a": 0, "trap": "de — 'view of the garden' translates word for word and is wrong", "expl": "Fixed collocation: « vue sur ». Same idea with « donner sur » : « la chambre donne sur la cour »."}, {"id": "ex-hotel-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte de crédit", "en": "the credit card", "format": "collocation", "q": "The receptionist says « Pour la garantie, il me faut une carte de crédit. » Why won't your Bancontact card do?", "options": ["Une carte de débit ne permet pas de bloquer une empreinte.", "Bancontact ne marche pas dans les hôtels.", "Bancontact n'est pas accepté en Belgique.", "Il faut toujours payer en espèces à l'hôtel."], "a": 0, "trap": "'Bancontact isn't accepted' — it is accepted everywhere in Belgium, just not for a pre-authorisation", "expl": "The hotel wants to block a sum on a card without taking it. Debit cards can't do that, so you pay the stay up front instead."}, {"id": "ex-hotel-A2-12", "level": "A2", "pos": "verb", "fr": "libérer", "en": "to vacate", "format": "cloze", "q": "Il faut ___ la chambre avant onze heures.", "options": ["libérer", "réserver", "remplir", "monter"], "a": 0, "trap": "réserver — the verb from the start of the stay, not the end", "expl": "All four are infinitives after « il faut ». « Libérer la chambre » is the standard hotel phrase for checking out."}, {"id": "ex-hotel-A2-13", "level": "A2", "pos": "adj", "fr": "complet", "en": "fully booked", "format": "en2fr", "options": ["complet", "compliqué", "comparable", "compréhensif"], "a": 0, "trap": "compréhensif — 'understanding', and a false friend for 'comprehensive'", "expl": "All four masculine adjectives. « Nous sommes complets ce soir » = we're full tonight."}, {"id": "ex-hotel-A2-14", "level": "A2", "pos": "expr", "fr": "s'il vous plaît", "en": "here you go", "format": "cloze", "q": "Le réceptionniste vous donne la clé : « Voilà votre clé, ___. »", "options": ["s'il vous plaît", "de rien", "pardon", "à bientôt"], "a": 0, "trap": "de rien — 'you're welcome', which is the reply to thanks, not what you say while handing something over", "expl": "In Belgium « s'il vous plaît » doubles as 'here you go', from Dutch alstublieft.", "note": "Belgian French. In France you would hear « voilà » or « tenez »."}]},
  "hotel-B1": {"slug": "hotel", "level": "B1", "title": "Une chambre en pleine semaine de sommet", "place": "Hôtel du Sablon, rue de Rollebeek, Bruxelles", "register": "vous", "registerNote": "Vous throughout, and it stays vous even when you are complaining. In French, dropping to tu while unhappy reads as aggression; the way you raise the register of a complaint is with the conditional (« il faudrait », « je souhaiterais ») and not with the pronoun.", "vocab": [{"id": "fvc-hotel-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "la disponibilité", "en": "availability", "format": "fr2en", "options": ["availability", "willingness to help", "the vacancy rate", "the free time slot"], "a": 0, "trap": "'availability' as a personal quality — « sa disponibilité » about a person means their willingness to be there for you", "expl": "« sous réserve de disponibilité » = subject to availability, printed on every hotel confirmation."}, {"id": "fvc-hotel-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "le tarif", "en": "the rate / price list", "format": "fr2en", "options": ["the rate charged", "the price tag", "the customs duty", "the discount"], "a": 0, "trap": "l'étiquette — the price tag on an object; « tarif » is the scale of prices, not the label", "expl": "« le tarif haute saison », « le tarif préférentiel », « nos tarifs sont affichés à la réception »."}, {"id": "fvc-hotel-B1-03", "level": "B1", "pos": "noun", "gender": "m", "fr": "le supplément", "en": "the extra charge", "format": "cloze", "q": "Le petit déjeuner n'est pas compris : il est facturé en ___.", "options": ["supplément", "réduction", "remboursement", "acompte"], "a": 0, "trap": "l'acompte — a deposit paid in advance, not an add-on", "expl": "All four are masculine nouns fitting after « en ». « en supplément » = on top of the quoted price."}, {"id": "fvc-hotel-B1-04", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'acompte", "en": "the deposit paid up front", "format": "fr2en", "options": ["a part-payment made in advance", "a refundable security deposit", "the final balance", "a late-payment charge"], "a": 0, "trap": "la caution — refundable and held; an acompte is money actually spent against the price", "expl": "« Un acompte de trente pour cent est demandé à la réservation. » The rest is « le solde »."}, {"id": "fvc-hotel-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le solde", "en": "the balance to pay", "format": "fr2en", "options": ["the outstanding balance", "the sale (reduced prices)", "the sun deck", "the total turnover"], "a": 0, "trap": "les soldes (plural, masculine) — the January and July sales; same word, different number", "expl": "« Le solde est à régler à l'arrivée. » In the plural with an article: « les soldes commencent le 1er juillet »."}, {"id": "fvc-hotel-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la facture", "en": "the invoice", "format": "collocation", "q": "You need a document your employer can reclaim VAT on. What do you ask for?", "options": ["une facture au nom de la société, avec le numéro de TVA", "une note détaillée de la chambre", "un reçu de paiement Bancontact", "un ticket de caisse"], "a": 0, "trap": "« une note détaillée » is a perfectly real document — it just isn't a VAT invoice", "expl": "Only « une facture » carrying the company name and the BE VAT number lets an employer deduct the tax. Ask at check-in, not at check-out."}, {"id": "fvc-hotel-B1-07", "level": "B1", "pos": "noun", "gender": "m", "fr": "le numéro de TVA", "en": "the VAT number", "format": "en2fr", "options": ["le numéro de TVA", "le numéro de compte", "le numéro d'ordre", "le numéro de dossier"], "a": 0, "trap": "le numéro de compte — the bank account number, asked for in the same conversation", "expl": "Belgian VAT numbers run BE 0xxx.xxx.xxx. Pronounced « té-vé-a ». All four options are masculine « le numéro de … »."}, {"id": "fvc-hotel-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le geste commercial", "en": "a goodwill gesture", "format": "fr2en", "options": ["a goodwill discount or freebie", "a marketing campaign", "a handshake closing a deal", "a sales target"], "a": 0, "trap": "'a commercial gesture' read literally — it is compensation, not advertising", "expl": "The phrase to aim a complaint at: « Est-ce que vous pouvez faire un geste commercial ? » Usually gets you the breakfast or a discount."}, {"id": "fvc-hotel-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "le dédommagement", "en": "compensation", "format": "en2fr", "options": ["le dédommagement", "le déménagement", "le dérangement", "le remboursement"], "a": 0, "trap": "le dérangement — the inconvenience itself, not the money that makes up for it", "expl": "All four masculine. « à titre de dédommagement » = by way of compensation. The verb is « dédommager »."}, {"id": "fvc-hotel-B1-10", "level": "B1", "pos": "noun", "gender": "m", "fr": "le dérangement", "en": "the inconvenience", "format": "cloze", "q": "Je vous prie de nous excuser pour le ___ causé par les travaux.", "options": ["dérangement", "dédommagement", "changement", "renseignement"], "a": 0, "trap": "dédommagement — one syllable away and the opposite side of the transaction", "expl": "All four are masculine nouns in -ment. The set phrase is « désolé pour le dérangement »."}, {"id": "fvc-hotel-B1-11", "level": "B1", "pos": "noun", "gender": "f", "fr": "la réclamation", "en": "the formal complaint", "format": "fr2en", "options": ["a formal complaint", "an advertisement", "a claim on an inheritance", "a request for information"], "a": 0, "trap": "la réclame — old-fashioned French for an advert; and English 'reclamation' means something else again", "expl": "« déposer une réclamation », « le registre des réclamations ». For a spoken grumble, use « se plaindre »."}, {"id": "fvc-hotel-B1-12", "level": "B1", "pos": "noun", "gender": "m", "fr": "le chauffe-eau", "en": "the water heater", "format": "fr2en", "options": ["the water heater", "the central heating boiler", "the radiator", "the kettle"], "a": 0, "trap": "la chaudière — the boiler that heats the whole flat; a chauffe-eau only makes hot water", "expl": "Invariable in the plural: « des chauffe-eau ». « Il n'y a pas d'eau chaude, le chauffe-eau est en panne. »"}, {"id": "fvc-hotel-B1-13", "level": "B1", "pos": "noun", "gender": "f", "fr": "la panne", "en": "the breakdown", "format": "cloze", "q": "L'ascenseur est en ___ depuis ce matin.", "options": ["panne", "grève", "réparation", "vacances"], "a": 0, "trap": "réparation — « en réparation » is real French, but it means being fixed, not broken", "expl": "All four are feminine nouns that follow « en ». « tomber en panne » = to break down; « une panne de courant » = a power cut."}, {"id": "fvc-hotel-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fuite", "en": "the leak", "format": "fr2en", "options": ["a leak", "the escape of a prisoner", "the flow rate", "the drain"], "a": 0, "trap": "la fuite also means a flight/escape — same word, and the plumbing sense is the one you need here", "expl": "« Il y a une fuite sous le lavabo. » « une fuite d'eau », « une fuite de gaz » — call the hotel, then 1722 for non-urgent, 112 for gas."}, {"id": "fvc-hotel-B1-15", "level": "B1", "pos": "noun", "gender": "m", "fr": "le robinet", "en": "the tap", "format": "en2fr", "options": ["le robinet", "le lavabo", "le tuyau", "le bouchon"], "a": 0, "trap": "le lavabo — the basin the tap sits on", "expl": "All four masculine. « Le robinet d'eau chaude ne donne que de l'eau froide. »"}, {"id": "fvc-hotel-B1-16", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'essuie", "en": "the towel (Belgian French)", "format": "fr2en", "options": ["the towel", "the windscreen wiper", "the doormat", "the tissue"], "a": 0, "trap": "l'essuie-glace — the windscreen wiper, built on the same verb « essuyer »", "expl": "« Est-ce que je peux avoir un essuie de bain ? » Standard in Belgium and understood everywhere in the country.", "note": "Belgian French. France says « une serviette (de bain) » and would not understand « un essuie » on its own."}, {"id": "fvc-hotel-B1-17", "level": "B1", "pos": "noun", "gender": "f", "fr": "la literie", "en": "the bedding", "format": "fr2en", "options": ["the bedding (sheets, duvet, pillows)", "the bookshop trade", "the bed frame", "the bedroom furniture"], "a": 0, "trap": "la librairie — the bookshop; the two words are a classic pair for learners", "expl": "« La literie est changée tous les trois jours. » Includes « les draps », « la couette », « les oreillers »."}, {"id": "fvc-hotel-B1-18", "level": "B1", "pos": "noun", "gender": "f", "fr": "la couette", "en": "the duvet", "format": "en2fr", "options": ["la couette", "la couverture", "la nappe", "la housse"], "a": 0, "trap": "la couverture — a blanket, which is not the same thing on a Belgian bed", "expl": "All four feminine. « la housse de couette » = the duvet cover, and « la couverture » is also 'the cover' of a book."}, {"id": "fvc-hotel-B1-19", "level": "B1", "pos": "noun", "gender": "m", "fr": "le double vitrage", "en": "double glazing", "format": "fr2en", "options": ["double glazing", "a second coat of varnish", "a two-tier price", "a mezzanine"], "a": 0, "trap": "'double glazing' misheard as « double étage »; le vitrage is the glass", "expl": "The thing to ask about on a busy street: « Est-ce que les fenêtres ont le double vitrage ? »"}, {"id": "fvc-hotel-B1-20", "level": "B1", "pos": "noun", "gender": "f", "fr": "la nuisance sonore", "en": "noise nuisance", "format": "cloze", "q": "Les clients se plaignent des ___ sonores venant du bar d'en face.", "options": ["nuisances", "ambiances", "résonances", "distances"], "a": 0, "trap": "résonances — a real word, wrong register and wrong meaning", "expl": "All four are feminine plural nouns that fit before « sonores ». « les nuisances sonores » is the administrative phrase Brussels communes use."}, {"id": "fvc-hotel-B1-21", "level": "B1", "pos": "noun", "gender": "f", "fr": "la navette", "en": "the shuttle", "format": "fr2en", "options": ["the shuttle bus or train", "the weaving loom", "the taxi rank", "the transfer of a booking"], "a": 0, "trap": "le transfert — the transfer; « navette » is specifically the vehicle going back and forth", "expl": "« la navette de l'aéroport ». For Zaventem, the train from Bruxelles-Midi is usually faster than any shuttle."}, {"id": "fvc-hotel-B1-22", "level": "B1", "pos": "noun", "gender": "f", "fr": "la consigne", "en": "the left-luggage office", "format": "fr2en", "options": ["the left-luggage store", "the instruction given", "the deposit on a bottle", "the checkout counter"], "a": 0, "trap": "« la consigne » also means an instruction and a bottle deposit — three meanings, one word", "expl": "« Je peux laisser mes bagages à la consigne ? » Bruxelles-Midi has real lockers; a hotel just means the luggage room."}, {"id": "fvc-hotel-B1-23", "level": "B1", "pos": "noun", "gender": "f", "fr": "la drache", "en": "a downpour (Belgian French)", "format": "fr2en", "options": ["a sudden heavy downpour", "a light drizzle", "a hailstorm", "a puddle"], "a": 0, "trap": "la bruine — drizzle; a drache is the opposite of gentle", "expl": "« On a eu une drache en arrivant. » « la drache nationale » is the rain that traditionally falls on 21 July.", "note": "Belgian French, from Brussels dialect. France says « une averse » or « un déluge » and will not know 'drache'."}, {"id": "fvc-hotel-B1-24", "level": "B1", "pos": "verb", "fr": "disposer de", "en": "to have available", "format": "cloze", "q": "Nous ne ___ plus que d'une seule chambre ce soir.", "options": ["disposons", "profitons", "bénéficions", "jouissons"], "a": 0, "trap": "bénéficions — « bénéficier de » means to enjoy an advantage, not to have stock left", "expl": "All four are nous-form verbs taking « de ». « disposer de » = to have at one's disposal; it is the register hotels use."}, {"id": "fvc-hotel-B1-25", "level": "B1", "pos": "verb", "fr": "régler", "en": "to settle (a bill)", "format": "fr2en", "options": ["to settle up / pay", "to set a machine", "to sort out a problem", "to rule on a case"], "a": 0, "trap": "régler also means to adjust and to sort out; at a desk it means to pay", "expl": "« Vous réglez comment ? » = how are you paying? Answer: « par carte » or « en espèces »."}, {"id": "fvc-hotel-B1-26", "level": "B1", "pos": "verb", "fr": "prolonger", "en": "to extend (a stay)", "format": "en2fr", "options": ["prolonger", "avancer", "reporter", "raccourcir"], "a": 0, "trap": "reporter — to postpone to another date, not to make longer", "expl": "All four are infinitives. « Je voudrais prolonger d'une nuit. » Opposite: « raccourcir » or « écourter »."}, {"id": "fvc-hotel-B1-27", "level": "B1", "pos": "verb", "fr": "signaler", "en": "to report (a problem)", "format": "cloze", "q": "J'ai déjà ___ le problème hier soir à votre collègue.", "options": ["signalé", "signé", "souligné", "signifié"], "a": 0, "trap": "signé — 'signed'; the two verbs are one letter apart in the participle", "expl": "All four are past participles. « signaler un problème » is what you do at reception; « souligner » is to underline or stress a point."}, {"id": "fvc-hotel-B1-28", "level": "B1", "pos": "verb", "fr": "se plaindre", "en": "to complain", "format": "fr2en", "options": ["to complain", "to feel sorry for someone", "to apologise", "to plead in court"], "a": 0, "trap": "plaindre (without se) — to pity someone: « je le plains »", "expl": "« Je ne veux pas me plaindre, mais… » is the polite runway. Conjugation: je me plains, nous nous plaignons."}, {"id": "fvc-hotel-B1-29", "level": "B1", "pos": "verb", "fr": "patienter", "en": "to wait (politely)", "format": "en2fr", "options": ["patienter", "attendre", "espérer", "s'impatienter"], "a": 0, "trap": "s'impatienter — to grow impatient, the exact opposite behaviour", "expl": "All four are verbs. « Veuillez patienter un instant » is the counter-register version of « attendez »."}, {"id": "fvc-hotel-B1-30", "level": "B1", "pos": "verb", "fr": "savoir", "en": "to be able to (Belgian use)", "format": "collocation", "q": "A Brussels receptionist says « Je ne sais pas vous donner la chambre avant quatorze heures. » What does she mean?", "options": ["She is unable to give it to you before 2 p.m.", "She doesn't know which room it will be.", "She has forgotten the time.", "She refuses to tell you."], "a": 0, "trap": "the standard meaning of savoir — 'to know'; here it is standing in for pouvoir", "expl": "In Belgium « savoir » commonly replaces « pouvoir » for physical possibility. It is not a mistake here, but it is not said in France.", "note": "Belgian French. France would say « je ne peux pas vous donner… » and would hear the Belgian version as an error."}, {"id": "fvc-hotel-B1-31", "level": "B1", "pos": "verb", "fr": "majorer", "en": "to increase (a price)", "format": "fr2en", "options": ["to put a price up", "to reduce a price", "to round a price off", "to freeze a price"], "a": 0, "trap": "minorer — the opposite, and it exists", "expl": "« Les tarifs sont majorés pendant les sommets européens. » Related noun: « une majoration »."}, {"id": "fvc-hotel-B1-32", "level": "B1", "pos": "verb", "fr": "facturer", "en": "to charge / invoice", "format": "cloze", "q": "Le petit déjeuner vous sera ___ dix-huit euros par personne.", "options": ["facturé", "payé", "coûté", "compté"], "a": 0, "trap": "payé — the customer pays, the hotel invoices; the passive here belongs to the hotel", "expl": "All four past participles fit the passive « sera … ». « facturer » = to put on the bill."}, {"id": "fvc-hotel-B1-33", "level": "B1", "pos": "adj", "fr": "disponible", "en": "available", "format": "en2fr", "options": ["disponible", "libre", "vacant", "ouvert"], "a": 0, "trap": "libre — the everyday synonym; « disponible » is the word on the booking screen", "expl": "All four masculine adjectives. « Il n'y a plus rien de disponible en centre-ville » is what you will hear on a summit night."}, {"id": "fvc-hotel-B1-34", "level": "B1", "pos": "adj", "fr": "remboursable", "en": "refundable", "format": "cloze", "q": "Ce tarif est moins cher, mais il n'est pas ___ en cas d'annulation.", "options": ["remboursable", "raisonnable", "responsable", "renouvelable"], "a": 0, "trap": "renouvelable — 'renewable', and it looks almost the same", "expl": "All four adjectives fit the slot. « un tarif non remboursable » is the cheap, rigid rate on booking sites."}, {"id": "fvc-hotel-B1-35", "level": "B1", "pos": "adj", "fr": "insonorisé", "en": "soundproofed", "format": "fr2en", "options": ["soundproofed", "unheated", "unfurnished", "windowless"], "a": 0, "trap": "'insulated' — that is « isolé », about heat, not noise", "expl": "« Les chambres côté rue sont insonorisées. » Built from « le son ». Thermal insulation is « l'isolation »."}, {"id": "fvc-hotel-B1-36", "level": "B1", "pos": "adj", "fr": "mitoyen", "en": "adjoining / shared (wall)", "format": "fr2en", "options": ["sharing a common wall", "halfway along", "middle-of-the-range", "jointly owned by the commune"], "a": 0, "trap": "moyen — 'average'; mitoyen is about a party wall", "expl": "« un mur mitoyen » is the party wall between two Brussels town houses — and the reason you hear the neighbours."}, {"id": "fvc-hotel-B1-37", "level": "B1", "pos": "expr", "fr": "sous réserve de", "en": "subject to", "format": "cloze", "q": "Je peux vous garder la chambre, ___ réserve de disponibilité demain matin.", "options": ["sous", "en", "à", "par"], "a": 0, "trap": "en — « en réserve » exists, but it means 'in stock', which changes the sentence completely", "expl": "Fixed phrase: « sous réserve de ». Also « sous réserve que » + subjunctive: « sous réserve qu'il y ait de la place »."}, {"id": "fvc-hotel-B1-38", "level": "B1", "pos": "expr", "fr": "à titre exceptionnel", "en": "as a one-off", "format": "fr2en", "options": ["as a one-off exception", "in an emergency", "in principle", "with an official title"], "a": 0, "trap": "'exceptionally' meaning 'unusually well' — in French this phrase is purely administrative", "expl": "The phrase that precedes a favour: « À titre exceptionnel, je vous offre les petits déjeuners. »"}, {"id": "fvc-hotel-B1-39", "level": "B1", "pos": "expr", "fr": "dans la mesure du possible", "en": "as far as possible", "format": "en2fr", "options": ["dans la mesure du possible", "dans tous les cas", "dans l'ensemble", "dans un premier temps"], "a": 0, "trap": "dans l'ensemble — 'on the whole', a different hedge entirely", "expl": "All four are adverbial phrases with « dans ». Use it to make a request flexible: « Dans la mesure du possible, une chambre au calme. »"}, {"id": "fvc-hotel-B1-40", "level": "B1", "pos": "noun", "gender": "m", "fr": "le surclassement", "en": "the upgrade", "format": "fr2en", "options": ["an upgrade to a better room", "a reclassification of the hotel's stars", "a surcharge", "an overbooking"], "a": 0, "trap": "le surbooking — overbooking, which is usually the reason you are offered a surclassement", "expl": "« On vous surclasse » = we're upgrading you. Note that French built its own word rather than borrowing 'upgrade'."}, {"id": "fvc-hotel-B1-41", "level": "B1", "pos": "noun", "gender": "m", "fr": "le surbooking", "en": "overbooking", "format": "cloze", "q": "À cause du ___, l'hôtel a dû reloger deux clients dans un autre établissement.", "options": ["surbooking", "surclassement", "surplus", "supplément"], "a": 0, "trap": "surclassement — the remedy, not the problem", "expl": "All four masculine nouns. The formal French is « la surréservation », but the trade says « le surbooking »."}, {"id": "fvc-hotel-B1-42", "level": "B1", "pos": "verb", "fr": "reloger", "en": "to rehouse (elsewhere)", "format": "en2fr", "options": ["reloger", "déménager", "héberger", "loger"], "a": 0, "trap": "héberger — to put someone up, without the idea of moving them out of where they were", "expl": "All four verbs. « L'hôtel vous reloge à ses frais » = the hotel puts you elsewhere at its own expense — your right if they overbooked."}, {"id": "fvc-hotel-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "le sommet", "en": "the summit (meeting)", "format": "fr2en", "options": ["a summit meeting", "a mountain top only", "the peak season", "the top floor"], "a": 0, "trap": "'the peak season' — that is « la haute saison »", "expl": "In Brussels « un sommet européen » empties the hotels and doubles the rates. Same word as a mountain summit."}, {"id": "fvc-hotel-B1-44", "level": "B1", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "Le tarif de la deuxième nuit est de cent ___ euros.", "options": ["septante", "nonante", "quarante", "cinquante"], "a": 0, "trap": "nonante — the other Belgian number; both would be said in Brussels, only one is 70", "expl": "cent septante = 170. Belgians build it exactly like cent soixante: cent septante-cinq = 175.", "note": "Belgian French. France says cent soixante-dix."}, {"id": "fvc-hotel-B1-45", "level": "B1", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile (Belgian French)", "format": "collocation", "q": "The receptionist asks for a number to reach you on. Which is the natural Belgian phrasing?", "options": ["Vous avez un numéro de GSM ?", "Vous avez un numéro de portable ?", "Vous avez un numéro de mobile ?", "Vous avez un numéro de cellulaire ?"], "a": 0, "trap": "« portable » is perfect French — it is simply not the word used on Belgian forms", "expl": "Belgian forms print GSM. In Belgium « un portable » more often means a laptop, which is exactly where the confusion starts.", "note": "Belgian French. France says portable; Quebec says cellulaire."}, {"id": "fvc-hotel-B1-46", "level": "B1", "pos": "expr", "fr": "par écrit", "en": "in writing", "format": "cloze", "q": "Vous pouvez me confirmer ce tarif ___ écrit, par mail ?", "options": ["par", "en", "à", "sur"], "a": 0, "trap": "en — « en écrit » does not exist, although « en anglais », « en gras » make it feel possible", "expl": "« par écrit » is fixed. Getting an agreed rate « par mail » before you go up is the single most useful habit in this dialogue."}], "phrases": [{"id": "ph-hotel-B1-01", "fr": "Je sais qu'il y a un sommet cette semaine, mais est-ce qu'il vous resterait quelque chose ?", "en": "I know there's a summit this week, but would you have anything left?", "note": "The conditional « resterait » makes the question tentative and much more likely to get a helpful answer than « il reste »."}, {"id": "ph-hotel-B1-02", "fr": "Je n'ai rien réservé, j'espérais trouver une chambre sur place.", "en": "I haven't booked anything, I was hoping to find a room on the spot.", "note": "« sur place » = on the spot, in person. The imperfect « j'espérais » is the natural tense for a hope you had on the way here."}, {"id": "ph-hotel-B1-03", "fr": "Est-ce que vous disposez encore d'une chambre pour deux nuits ?", "en": "Do you still have a room available for two nights?", "note": "« disposer de » is the counter register. Note the « de » : disposer DE quelque chose."}, {"id": "ph-hotel-B1-04", "fr": "Si je comprends bien, je devrais changer de chambre demain matin.", "en": "If I understand correctly, I'd have to change rooms tomorrow morning.", "note": "« Si je comprends bien » buys you a reformulation and confirms it in one move — worth memorising for every counter in Belgium."}, {"id": "ph-hotel-B1-05", "fr": "Est-ce que ce serait possible de garder la même chambre les deux nuits ?", "en": "Would it be possible to keep the same room for both nights?", "note": "« Est-ce que ce serait possible de… » is the polite request frame; « c'est possible de » is the blunter version."}, {"id": "ph-hotel-B1-06", "fr": "Ce tarif me paraît élevé pour une chambre simple.", "en": "That rate seems high to me for a single room.", "note": "« me paraît » softens a judgement into an impression. Saying « c'est trop cher » closes the negotiation instead of opening it."}, {"id": "ph-hotel-B1-07", "fr": "Est-ce que vous pourriez faire un geste commercial ?", "en": "Could you do something on the price?", "note": "The standard, non-confrontational way to ask for a discount or a freebie. Expect breakfast to be offered rather than money taken off."}, {"id": "ph-hotel-B1-08", "fr": "Il me faudrait une facture au nom de mon employeur, avec le numéro de TVA.", "en": "I'd need an invoice in my employer's name, with the VAT number.", "note": "Ask at check-in: reissuing a Belgian invoice afterwards is a real administrative bother, and some hotels refuse."}, {"id": "ph-hotel-B1-09", "fr": "Vous pouvez me confirmer ce prix par écrit, par mail ?", "en": "Can you confirm that price to me in writing, by email?", "note": "« par écrit » and « par mail ». In Belgium « un mail » is the everyday word; « un courriel » sounds official."}, {"id": "ph-hotel-B1-10", "fr": "Il n'y a pas d'eau chaude dans la salle de bains depuis hier soir.", "en": "There's been no hot water in the bathroom since last night.", "note": "« depuis » + present for something still going on: French uses the present where English uses 'there has been'."}, {"id": "ph-hotel-B1-11", "fr": "J'ai déjà signalé le problème à votre collègue hier soir.", "en": "I already reported the problem to your colleague last night.", "note": "Establishing that this is the second time changes the answer you get. « signaler » is the right verb, not « dire »."}, {"id": "ph-hotel-B1-12", "fr": "Est-ce qu'un technicien peut passer dans la matinée ?", "en": "Can a technician come by during the morning?", "note": "« passer » = to come round. « dans la matinée » means at some point in the morning; « le matin » would be a habit."}, {"id": "ph-hotel-B1-13", "fr": "Je préférerais changer de chambre plutôt que d'attendre la réparation.", "en": "I'd rather change rooms than wait for the repair.", "note": "« plutôt que de » + infinitive. One word: « plutôt » (rather); two words « plus tôt » means earlier."}, {"id": "ph-hotel-B1-14", "fr": "Est-ce que la chambre est insonorisée ? La rue est assez bruyante le week-end.", "en": "Is the room soundproofed? The street is quite noisy at the weekend.", "note": "Around the Sablon and the rue du Marché au Charbon this is a genuine question, not small talk."}, {"id": "ph-hotel-B1-15", "fr": "Est-ce que je peux avoir un essuie de bain supplémentaire, s'il vous plaît ?", "en": "Could I have an extra bath towel, please?", "note": "« un essuie » is the Belgian word; in France you must say « une serviette de bain » or you will get a blank look."}, {"id": "ph-hotel-B1-16", "fr": "Je réglerai la note à mon départ, par Bancontact.", "en": "I'll settle the bill when I leave, by Bancontact.", "note": "Future simple « je réglerai » for a firm intention. « régler la note » is the hotel register for paying."}, {"id": "ph-hotel-B1-17", "fr": "Est-ce que l'annulation est gratuite jusqu'à dix-huit heures ?", "en": "Is cancellation free until six p.m.?", "note": "The 24-hour clock is normal in Belgium for anything official: dix-huit heures, not six heures du soir."}, {"id": "ph-hotel-B1-18", "fr": "Comme il drachait, j'ai pris un taxi depuis Bruxelles-Midi.", "en": "As it was pouring, I took a taxi from Bruxelles-Midi.", "note": "« drachait » from « dracher », the Belgian verb for pouring rain. In France you would say « comme il pleuvait à verse »."}, {"id": "ph-hotel-B1-19", "fr": "Je vous laisse mon numéro de GSM au cas où il y aurait un problème.", "en": "I'll leave you my mobile number in case there's a problem.", "note": "« au cas où » always takes the conditional: au cas où il y aurait, au cas où vous auriez besoin."}, {"id": "ph-hotel-B1-20", "fr": "Merci d'avoir trouvé une solution, c'est très aimable à vous.", "en": "Thank you for finding a solution, that's very kind of you.", "note": "« Merci d'avoir » + past infinitive thanks someone for a completed action. Ending well matters if you may come back."}], "dialogue": [{"who": "receptionist", "fr": "Bonsoir monsieur. Je vous préviens tout de suite, avec le sommet européen, nous affichons presque complet.", "en": "Good evening sir. I'll tell you straight away, with the European summit we're almost fully booked.", "gloss": {"préviens": "warn, tell in advance", "sommet": "summit", "affichons": "we are showing (on the board)", "complet": "fully booked"}}, {"who": "you", "fr": "Bonsoir. Je n'ai rien réservé, j'espérais trouver une chambre sur place. Est-ce qu'il vous resterait quelque chose pour deux nuits ?", "en": "Good evening. I haven't booked anything, I was hoping to find a room on the spot. Would you have anything left for two nights?", "gloss": {"réservé": "booked", "j'espérais": "I was hoping", "sur place": "on the spot", "resterait": "would be left"}, "accept": ["bonsoir je n'ai rien réservé j'espérais trouver une chambre sur place est-ce qu'il vous resterait quelque chose pour deux nuits", "bonsoir je n'ai rien réservé est-ce qu'il vous resterait quelque chose pour deux nuits", "bonsoir je n'ai pas de réservation est-ce qu'il vous reste une chambre pour deux nuits", "bonsoir j'espérais trouver une chambre sur place est-ce que vous avez encore quelque chose pour deux nuits", "bonsoir je n'ai rien réservé est-ce que vous disposez encore d'une chambre pour deux nuits", "bonsoir est-ce qu'il vous resterait une chambre pour deux nuits"]}, {"who": "receptionist", "fr": "Pour deux nuits, ça va être compliqué. Il me reste une chambre au premier, mais uniquement pour ce soir : elle est réservée à partir de demain.", "en": "Two nights is going to be complicated. I have one room left on the first floor, but only for tonight: it's booked from tomorrow.", "gloss": {"compliqué": "difficult", "uniquement": "only", "à partir de": "from"}}, {"who": "you", "fr": "Et pour la deuxième nuit, il n'y aurait vraiment aucune solution ?", "en": "And for the second night, would there really be no solution at all?", "gloss": {"aurait": "would there be", "aucune": "no, not any"}, "accept": ["et pour la deuxième nuit il n'y aurait vraiment aucune solution", "et pour la deuxième nuit il n'y a vraiment aucune solution", "et pour demain soir il n'y aurait vraiment aucune solution", "et pour la deuxième nuit vous n'auriez vraiment rien", "et pour la deuxième nuit est-ce qu'il y aurait une solution", "et la deuxième nuit ce ne serait vraiment pas possible"]}, {"who": "receptionist", "fr": "Attendez, je regarde… Une chambre se libère demain à onze heures, au troisième. Mais il faudrait que vous changiez de chambre dans la matinée.", "en": "Hold on, let me look… A room frees up tomorrow at eleven, on the third floor. But you'd have to change rooms during the morning.", "gloss": {"se libère": "becomes free", "il faudrait que": "you would have to (+ subjunctive)", "changiez": "change (subjunctive)", "matinée": "morning"}}, {"who": "you", "fr": "Si je comprends bien, je devrais faire ma valise avant onze heures et vous me la gardez jusqu'à l'après-midi ?", "en": "If I understand correctly, I'd have to pack before eleven and you'd keep it for me until the afternoon?", "gloss": {"devrais": "would have to", "gardez": "keep, look after"}, "accept": ["si je comprends bien je devrais faire ma valise avant onze heures et vous me la gardez jusqu'à l'après-midi", "si je comprends bien je dois faire ma valise avant onze heures et vous la gardez jusqu'à l'après-midi", "donc je devrais faire ma valise avant onze heures et vous me la gardez", "si je comprends bien je change de chambre le matin et vous gardez ma valise", "si je comprends bien il faut que je libère la chambre à onze heures et vous gardez mes bagages", "d'accord donc je fais ma valise avant onze heures et vous me la gardez à la réception"]}, {"who": "receptionist", "fr": "Exactement. On la met à la consigne et le personnel monte vos affaires dans la nouvelle chambre vers quatorze heures.", "en": "Exactly. We put it in the luggage room and staff take your things up to the new room around two.", "gloss": {"consigne": "left-luggage room", "personnel": "staff", "affaires": "belongings"}}, {"who": "you", "fr": "D'accord, ça me va. Et quel serait le tarif pour les deux nuits ?", "en": "All right, that works for me. And what would the rate be for the two nights?", "gloss": {"ça me va": "that works for me", "tarif": "rate"}, "accept": ["d'accord ça me va et quel serait le tarif pour les deux nuits", "d'accord et quel serait le tarif pour les deux nuits", "ça me va et quel est le tarif pour les deux nuits", "très bien ça me va et combien coûteraient les deux nuits", "d'accord ça me convient et quel serait le prix pour les deux nuits", "parfait et quel serait le prix total pour les deux nuits"]}, {"who": "receptionist", "fr": "Ce soir, les tarifs sont majorés à cause du sommet : cent quarante-cinq euros. Demain, on revient à cent septante. Plus cinq euros de taxe de séjour par nuit.", "en": "Tonight the rates are put up because of the summit: a hundred and forty-five euros. Tomorrow we're back to a hundred and seventy. Plus five euros city tax per night.", "gloss": {"majorés": "increased", "à cause du": "because of", "septante": "seventy (Belgian French; France: soixante-dix)", "taxe de séjour": "city tax"}}, {"who": "you", "fr": "Ce tarif me paraît élevé pour une chambre simple. Est-ce que vous pourriez faire un geste commercial ?", "en": "That rate seems high to me for a single room. Could you do something on the price?", "gloss": {"élevé": "high", "geste commercial": "goodwill gesture"}, "accept": ["ce tarif me paraît élevé pour une chambre simple est-ce que vous pourriez faire un geste commercial", "ce tarif me paraît élevé est-ce que vous pourriez faire un geste commercial", "c'est un peu cher pour une chambre simple est-ce que vous pouvez faire un geste commercial", "ce prix me semble élevé est-ce que vous pourriez faire un geste commercial", "ce tarif est élevé pour une chambre simple vous pouvez faire quelque chose sur le prix", "est-ce que vous pourriez faire un geste commercial vu que je dois changer de chambre"]}, {"who": "receptionist", "fr": "Écoutez, puisque vous devez changer de chambre, je vous offre les deux petits déjeuners. À titre exceptionnel.", "en": "Look, since you have to change rooms, I'll give you the two breakfasts. As a one-off.", "gloss": {"puisque": "since, given that", "je vous offre": "I'll give you free of charge", "À titre exceptionnel": "as a one-off"}}, {"who": "you", "fr": "C'est très aimable, merci. Il me faudrait aussi une facture au nom de mon employeur, avec le numéro de TVA. Je vous laisse mon numéro de GSM au cas où.", "en": "That's very kind, thank you. I'd also need an invoice in my employer's name, with the VAT number. I'll leave you my mobile number just in case.", "gloss": {"aimable": "kind", "facture": "invoice", "GSM": "mobile phone (Belgian French; France: portable)", "au cas où": "just in case", "Il me faudrait": "I would need"}, "accept": ["c'est très aimable merci il me faudrait aussi une facture au nom de mon employeur avec le numéro de tva je vous laisse mon numéro de gsm au cas où", "merci beaucoup il me faudrait aussi une facture au nom de mon employeur avec le numéro de tva je vous laisse mon numéro de gsm", "c'est très gentil merci est-ce que je peux avoir une facture au nom de mon employeur avec le numéro de tva", "merci il me faudrait une facture au nom de ma société avec le numéro de tva et je vous laisse mon numéro de gsm", "c'est très aimable merci j'aurais besoin d'une facture avec le numéro de tva de mon employeur", "merci et j'aurais aussi besoin d'une facture au nom de mon employeur je vous laisse mon gsm"]}, {"who": "receptionist", "fr": "C'est noté : je prépare la facture pour votre départ et je vous confirme les tarifs par mail. Voici votre clé, s'il vous plaît. Chambre 108, premier étage — et l'ascenseur est en panne, je suis désolée.", "en": "Noted: I'll prepare the invoice for your check-out and confirm the rates to you by email. Here's your key. Room 108, first floor — and the lift is out of order, I'm sorry.", "gloss": {"C'est noté": "noted, got it", "par mail": "by email", "s'il vous plaît": "here you go (Belgian use when handing something over)", "en panne": "out of order"}}, {"who": "you", "fr": "Excusez-moi de vous déranger, je redescends déjà : il n'y a pas d'eau chaude dans la salle de bains. Après la drache de tout à l'heure, une douche froide, ça fait beaucoup.", "en": "Sorry to bother you, I'm back down already: there's no hot water in the bathroom. After the downpour earlier, a cold shower is a bit much.", "gloss": {"déranger": "to bother", "redescends": "am coming back down", "eau chaude": "hot water", "drache": "downpour (Belgian French; France: averse)", "tout à l'heure": "earlier on"}, "accept": ["excusez-moi de vous déranger je redescends déjà il n'y a pas d'eau chaude dans la salle de bains après la drache de tout à l'heure une douche froide ça fait beaucoup", "excusez-moi de vous déranger il n'y a pas d'eau chaude dans la salle de bains", "désolé de vous déranger mais il n'y a pas d'eau chaude dans la salle de bains", "excusez-moi je redescends déjà il n'y a pas d'eau chaude dans ma chambre", "excusez-moi de vous déranger le robinet ne donne que de l'eau froide dans la salle de bains", "pardon de vous déranger mais il n'y a pas d'eau chaude après la drache de tout à l'heure une douche froide ça fait beaucoup"]}, {"who": "receptionist", "fr": "Je suis navrée, le chauffe-eau du premier a des ratés depuis la semaine dernière. Le technicien passe demain dans la matinée.", "en": "I'm very sorry, the water heater on the first floor has been playing up since last week. The technician is coming tomorrow morning.", "gloss": {"navrée": "very sorry", "chauffe-eau": "water heater", "des ratés": "misfires, playing up", "passe": "is coming round"}}, {"who": "you", "fr": "Si le problème dure depuis une semaine, je préférerais changer de chambre ce soir plutôt que d'attendre le technicien.", "en": "If the problem has been going on for a week, I'd rather change rooms tonight than wait for the technician.", "gloss": {"dure": "has been going on", "je préférerais": "I would rather", "plutôt que d'": "rather than"}, "accept": ["si le problème dure depuis une semaine je préférerais changer de chambre ce soir plutôt que d'attendre le technicien", "si le problème dure depuis une semaine je préférerais changer de chambre ce soir", "si ça dure depuis une semaine je préfère changer de chambre ce soir plutôt que d'attendre le technicien", "vu que le problème dure depuis une semaine je préférerais changer de chambre maintenant", "si c'est comme ça depuis une semaine je voudrais changer de chambre ce soir", "je préférerais changer de chambre ce soir plutôt que d'attendre demain"]}, {"who": "receptionist", "fr": "Je ne sais pas vous donner une autre chambre ce soir, nous sommes complets. Mais je vous propose d'utiliser la douche de la chambre 210, qui est libre jusqu'à demain midi.", "en": "I can't give you another room tonight, we're full. But I suggest you use the shower in room 210, which is free until midday tomorrow.", "gloss": {"Je ne sais pas": "I can't (Belgian use of savoir for pouvoir)", "je vous propose": "I suggest", "libre": "free, unoccupied"}}, {"who": "you", "fr": "D'accord, je veux bien. Et est-ce que vous pouvez noter la panne sur ma fiche ? Si elle n'est pas réparée demain, je vous demanderai un dédommagement.", "en": "All right, I'm happy with that. And can you note the fault on my file? If it isn't fixed tomorrow, I'll be asking for compensation.", "gloss": {"je veux bien": "I'm willing, that's fine by me", "noter": "to write down", "panne": "breakdown, fault", "dédommagement": "compensation"}, "accept": ["d'accord je veux bien et est-ce que vous pouvez noter la panne sur ma fiche si elle n'est pas réparée demain je vous demanderai un dédommagement", "d'accord je veux bien est-ce que vous pouvez noter la panne sur ma fiche", "très bien merci vous pouvez noter la panne sur ma fiche si ce n'est pas réparé demain je demanderai un dédommagement", "d'accord mais notez la panne s'il vous plaît si elle n'est pas réparée demain je demanderai un geste commercial", "j'accepte mais pouvez-vous noter le problème sur ma fiche", "d'accord je veux bien mais notez le problème et si ce n'est pas réglé demain je demanderai un dédommagement"]}, {"who": "receptionist", "fr": "C'est tout à fait normal, je le note et je préviens la direction. Encore toutes mes excuses, monsieur. Bonne nuit.", "en": "That's perfectly fair, I'm noting it and I'll tell the management. My apologies again, sir. Good night.", "gloss": {"tout à fait": "completely", "préviens": "will tell, inform", "direction": "management"}}, {"who": "you", "fr": "Merci d'avoir trouvé une solution. Bonne soirée, et à demain matin.", "en": "Thank you for finding a solution. Have a good evening, and see you tomorrow morning.", "gloss": {"Merci d'avoir": "thank you for having (+ past infinitive)"}, "accept": ["merci d'avoir trouvé une solution bonne soirée et à demain matin", "merci d'avoir trouvé une solution bonne soirée", "merci beaucoup d'avoir trouvé une solution à demain matin", "je vous remercie d'avoir trouvé une solution bonne soirée", "merci pour votre aide bonne soirée et à demain", "merci d'avoir trouvé une solution à demain"]}], "exercises": [{"id": "ex-hotel-B1-01", "level": "B1", "pos": "verb", "fr": "disposer de", "en": "to have available", "format": "cloze", "q": "Nous ne ___ plus que de deux chambres pour ce soir.", "options": ["disposons", "bénéficions", "profitons", "manquons"], "a": 0, "trap": "bénéficions — « bénéficier de » is about enjoying an advantage, not holding stock", "expl": "All four take « de ». « ne … plus que » = only … left, a structure worth stealing whole."}, {"id": "ex-hotel-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la facture", "en": "the invoice", "format": "collocation", "q": "Which request gets you a document your employer can use?", "options": ["Une facture au nom de la société, s'il vous plaît.", "Une note détaillée, s'il vous plaît.", "Un reçu, s'il vous plaît.", "Un ticket, s'il vous plaît."], "a": 0, "trap": "« une note détaillée » — it itemises the stay but carries no VAT number", "expl": "Only an invoice naming the company and its BE VAT number can be reclaimed. Ask on arrival, before the stay is closed."}, {"id": "ex-hotel-B1-03", "level": "B1", "pos": "expr", "fr": "sous réserve de", "en": "subject to", "format": "cloze", "q": "La chambre vous est réservée ___ réserve de confirmation avant midi.", "options": ["sous", "en", "par", "à"], "a": 0, "trap": "en — « en réserve » exists but means 'in stock'", "expl": "« sous réserve de » + noun, « sous réserve que » + subjunctive. Fixed, and very common in Belgian administrative letters."}, {"id": "ex-hotel-B1-04", "level": "B1", "pos": "verb", "fr": "savoir", "en": "to be able to (Belgian use)", "format": "fr2en", "options": ["to be able to, in Belgian usage", "to know a fact", "to taste of something", "to find out"], "a": 0, "trap": "'to know' — the meaning you learned, and the one a French speaker will hear", "expl": "« Je ne sais pas venir demain » in Brussels means I can't come. In Paris it would sound like a mistake.", "note": "Belgian French. France uses pouvoir for ability and keeps savoir for knowledge."}, {"id": "ex-hotel-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le chauffe-eau", "en": "the water heater", "format": "en2fr", "options": ["le chauffe-eau", "le radiateur", "le compteur", "le thermostat"], "a": 0, "trap": "le radiateur — the thing that got cold, not the thing that heats the water", "expl": "All four masculine. Hot water fails: chauffe-eau. Heating fails: chaudière or radiateur."}, {"id": "ex-hotel-B1-06", "level": "B1", "pos": "noun", "gender": "m", "fr": "le dédommagement", "en": "compensation", "format": "cloze", "q": "Nous vous offrons une nuit à titre de ___.", "options": ["dédommagement", "dérangement", "renseignement", "abonnement"], "a": 0, "trap": "dérangement — the inconvenience being compensated, not the compensation", "expl": "All four masculine -ment nouns. « à titre de dédommagement » is the phrase hotels and airlines use."}, {"id": "ex-hotel-B1-07", "level": "B1", "pos": "verb", "fr": "se plaindre", "en": "to complain", "format": "cloze", "q": "Je ne veux pas ___, mais c'est la deuxième nuit sans eau chaude.", "options": ["me plaindre", "me tromper", "me presser", "me taire"], "a": 0, "trap": "me taire — 'stay silent', which would flip the sentence on its head", "expl": "All four are reflexive infinitives. « Je ne veux pas me plaindre, mais… » is the standard polite runway into a complaint."}, {"id": "ex-hotel-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'essuie", "en": "the towel (Belgian French)", "format": "collocation", "q": "You want an extra bath towel in a Brussels hotel. Which will be understood locally AND in Paris?", "options": ["une serviette de bain supplémentaire", "un essuie de bain supplémentaire", "un torchon supplémentaire", "une lavette supplémentaire"], "a": 0, "trap": "« un essuie » is perfect Belgian French — it just does not travel to France", "expl": "Belgium: essuie (de bain / de vaisselle). France: serviette / torchon. And in Belgium « un torchon » is a floor cloth, not a tea towel.", "note": "Belgian French. Understand « essuie » in Brussels; say « serviette » if you are ever in France."}, {"id": "ex-hotel-B1-09", "level": "B1", "pos": "adj", "fr": "remboursable", "en": "refundable", "format": "fr2en", "options": ["refundable", "renewable", "reimbursable to the hotel", "reliable"], "a": 0, "trap": "renouvelable — 'renewable', a lookalike that turns up on the same booking page", "expl": "« un tarif non remboursable » is cheaper and rigid. « annulation gratuite » is the flexible one."}, {"id": "ex-hotel-B1-10", "level": "B1", "pos": "noun", "gender": "f", "fr": "la panne", "en": "the breakdown", "format": "collocation", "q": "Which pairing is wrong?", "options": ["une panne de chambre", "une panne de courant", "une panne d'ascenseur", "une panne de chauffage"], "a": 0, "trap": "all four look symmetrical; only machines and supplies break down, not rooms", "expl": "« une panne de X » needs X to be a system or a supply: courant, chauffage, réseau, ascenseur, moteur."}, {"id": "ex-hotel-B1-11", "level": "B1", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "Cela fait trois cent ___ euros pour les deux nuits, taxe comprise.", "options": ["septante", "nonante", "cinquante", "quarante"], "a": 0, "trap": "nonante — the other Belgian form; 370 and 390 sound almost identical at speed", "expl": "cent septante = 170; trois cent septante = 370. Belgians build these exactly like cent soixante.", "note": "Belgian French. France: trois cent soixante-dix."}, {"id": "ex-hotel-B1-12", "level": "B1", "pos": "verb", "fr": "signaler", "en": "to report", "format": "en2fr", "options": ["signaler", "signer", "désigner", "souligner"], "a": 0, "trap": "signer — to sign; separated from signaler by two letters and a world of meaning", "expl": "All four infinitives. « J'ai signalé la fuite hier soir. » Reporting it twice, on the record, is what earns the geste commercial."}, {"id": "ex-hotel-B1-13", "level": "B1", "pos": "expr", "fr": "au cas où", "en": "in case", "format": "cloze", "q": "Je vous laisse mon numéro au cas où il y ___ un problème.", "options": ["aurait", "a", "ait", "aura"], "a": 0, "trap": "ait — the subjunctive, which learners reach for automatically after « au cas où »", "expl": "« au cas où » is the one common conjunction that takes the conditional, never the subjunctive: au cas où il y aurait, au cas où vous seriez."}, {"id": "ex-hotel-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "la drache", "en": "a downpour", "format": "en2fr", "options": ["la drache", "la bruine", "la brume", "la rosée"], "a": 0, "trap": "la bruine — drizzle; the gentle end of the same weather", "expl": "All four feminine weather nouns. A drache soaks you in ninety seconds — the Brussels default between October and March.", "note": "Belgian French. France says « une averse » ; « drache » will not be understood there."}]},
  "restaurant-pro-A2": {"slug": "restaurant-pro", "level": "A2", "title": "Au restaurant : commander, signaler une erreur, partager l'addition", "place": "Brasserie de la Place, place Sainte-Catherine, Bruxelles", "register": "vous", "registerNote": "Vous with the waiter, both ways, in every Belgian brasserie. Waiters here are professionals doing a job, not students on a summer contract, and the vous is part of the service. You only hear tu between regulars and the patron.", "vocab": [{"id": "fvc-restaurant-pro-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte", "en": "the menu (the list of dishes)", "format": "fr2en", "options": ["the list of all the dishes", "a fixed-price set of courses", "the wine list only", "the bill"], "a": 0, "trap": "le menu — in French that is the fixed-price formula, not the list you read", "expl": "« Je peux avoir la carte ? » gets you the big folder. « à la carte » means choosing dish by dish."}, {"id": "fvc-restaurant-pro-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le menu", "en": "the set menu", "format": "fr2en", "options": ["a fixed-price set of courses", "the list of all the dishes", "the daily special", "the tasting portion"], "a": 0, "trap": "la carte — English 'menu' is la carte; French menu is the deal at a fixed price", "expl": "« le menu à 32 € : entrée, plat, dessert ». Ask « la carte » if you want to choose freely."}, {"id": "fvc-restaurant-pro-A2-03", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'entrée", "en": "the starter", "format": "fr2en", "options": ["the starter", "the main course", "the way in", "the second helping"], "a": 0, "trap": "'entrée' in American English means the main course — the reverse of the French word", "expl": "Order runs: l'entrée, le plat, le dessert. « l'entrée » does also mean the entrance of a building; context sorts it out."}, {"id": "fvc-restaurant-pro-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plat", "en": "the main course / the dish", "format": "fr2en", "options": ["the main course", "the plate you eat from", "the serving dish", "the flat surface"], "a": 0, "trap": "l'assiette — the physical plate; « plat » is what's on it", "expl": "« le plat principal » = the main course, usually shortened to « le plat ». As an adjective « plat » means flat: « de l'eau plate »."}, {"id": "fvc-restaurant-pro-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'assiette", "en": "the plate", "format": "en2fr", "options": ["l'assiette", "la soucoupe", "la casserole", "la nappe"], "a": 0, "trap": "la soucoupe — the saucer under a coffee cup", "expl": "All four feminine. « une assiette sale » is a dirty plate; « la nappe » is the tablecloth."}, {"id": "fvc-restaurant-pro-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plat du jour", "en": "the dish of the day", "format": "collocation", "q": "Which question asks what today's special is?", "options": ["Quel est le plat du jour ?", "Quel est le plat de la journée ?", "Quel est le plat d'aujourd'hui ?", "Quel est le plat du quotidien ?"], "a": 0, "trap": "« le plat de la journée » is word-for-word logical and simply not what anyone says", "expl": "Fixed phrase: « le plat du jour », written on the slate outside. It is nearly always the best value in the place."}, {"id": "fvc-restaurant-pro-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "le dessert", "en": "the dessert", "format": "en2fr", "options": ["le dessert", "le désert", "le service", "le dressage"], "a": 0, "trap": "le désert — one s, and it is the Sahara; the sweet course has two", "expl": "All four masculine. Memory hook: dessert has two s because you always want a second helping."}, {"id": "fvc-restaurant-pro-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la boisson", "en": "the drink", "format": "fr2en", "options": ["the drink", "the bottle", "the round of drinks", "the wine list"], "a": 0, "trap": "la bouteille — the bottle; the waiter asks « et comme boisson ? », not « et comme bouteille ? »", "expl": "« Et comme boisson ? » is the standard question after your food order. Answer with « pour moi, … »."}, {"id": "fvc-restaurant-pro-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'apéritif", "en": "the pre-dinner drink", "format": "fr2en", "options": ["a drink before the meal", "an appetiser to eat", "the wine served with the meal", "the digestif after the meal"], "a": 0, "trap": "the nibbles are « les amuse-bouches » ; l'apéritif is the drink itself", "expl": "Shortened to « l'apéro ». « On prend l'apéro ? » is one of the most-used invitations in Belgium."}, {"id": "fvc-restaurant-pro-A2-10", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carafe d'eau", "en": "the jug of tap water", "format": "collocation", "q": "You ask for « une carafe d'eau » in a Brussels brasserie. What normally happens?", "options": ["On vous propose une bouteille payante à la place.", "On vous l'apporte gratuitement, c'est obligatoire.", "On vous demande de payer un euro pour la carafe.", "On vous apporte de l'eau pétillante gratuite."], "a": 0, "trap": "the free-jug answer is right in France and simply wrong here", "expl": "France obliges restaurants to serve free tap water; Belgium does not, and most places sell you bottled water instead (4–5 € for 50 cl).", "note": "Belgian reality. In France « une carafe d'eau » is free and your legal right."}, {"id": "fvc-restaurant-pro-A2-11", "level": "A2", "pos": "adj", "fr": "plate", "en": "still (water)", "format": "cloze", "q": "Vous préférez de l'eau ___ ou pétillante ?", "options": ["plate", "chaude", "sucrée", "salée"], "a": 0, "trap": "chaude — grammatically identical and would order you a cup of hot water", "expl": "All four are feminine adjectives after « eau ». still = plate, sparkling = pétillante or gazeuse. Belgian brands: Spa Reine (plate), Spa Barisart (pétillante)."}, {"id": "fvc-restaurant-pro-A2-12", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pils", "en": "a standard lager", "format": "fr2en", "options": ["an ordinary lager", "a strong abbey beer", "a wheat beer", "a shandy"], "a": 0, "trap": "une bière blanche — the wheat beer (Hoegaarden); a pils is the plain lager", "expl": "« Une pils, s'il vous plaît » gets you a Jupiler or a Maes, 25 cl. Belgians also just say the brand.", "note": "Belgian French. In France you order « un demi » for a 25 cl draught; say « une pils » in Belgium."}, {"id": "fvc-restaurant-pro-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "les moules", "en": "mussels", "format": "collocation", "q": "Which is the classic Belgian pairing on the slate?", "options": ["moules-frites", "moules-riz", "moules-pain", "moules-salade"], "a": 0, "trap": "all four are edible; only one is the national dish", "expl": "« Une casserole de moules avec des frites. » Traditionally eaten in months with an R, though farmed mussels are sold all year."}, {"id": "fvc-restaurant-pro-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "les frites", "en": "chips / fries", "format": "fr2en", "options": ["hot chips", "crisps from a packet", "roast potatoes", "mashed potato"], "a": 0, "trap": "les chips — in French that means crisps in a bag, never hot chips", "expl": "Belgian frites are fried twice and sold at « une friterie » or « un fritkot ». Never « les French fries » in front of a Belgian."}, {"id": "fvc-restaurant-pro-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "les carbonnades", "en": "beef stewed in beer", "format": "fr2en", "options": ["beef slowly stewed in brown beer", "grilled ribs of beef", "a charcuterie board", "a beef and vegetable soup"], "a": 0, "trap": "'carbonara' or 'charcoal-grilled' — the name suggests grilling, the dish is a stew", "expl": "« Les carbonnades flamandes » — beef, onions, brown beer, a slice of bread with mustard on top. Served with frites."}, {"id": "fvc-restaurant-pro-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le waterzooi", "en": "a creamy Ghent stew", "format": "fr2en", "options": ["a creamy chicken or fish stew", "a cold seafood platter", "a beer soup", "a potato gratin"], "a": 0, "trap": "it sounds Dutch and fishy, but the common version is chicken", "expl": "« Le waterzooi de poulet » is Ghent's dish: chicken, vegetables, cream, served in a deep plate. Pronounced roughly va-ter-zoy."}, {"id": "fvc-restaurant-pro-A2-17", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chicon", "en": "chicory / endive (Belgian French)", "format": "fr2en", "options": ["the white chicory head", "the courgette", "the leek", "the cabbage"], "a": 0, "trap": "l'endive — the same vegetable, but that is the French word for it", "expl": "« un chicon au gratin » — chicory rolled in ham, baked in cheese sauce. A Belgian winter classic.", "note": "Belgian French. France says « une endive ». Confusingly, in Belgium « une endive » is curly frisée lettuce."}, {"id": "fvc-restaurant-pro-A2-18", "level": "A2", "pos": "noun", "gender": "f", "fr": "la croquette aux crevettes", "en": "the shrimp croquette", "format": "collocation", "q": "You are allergic to shellfish. Which starter must you avoid?", "options": ["la croquette aux crevettes grises", "la croquette au fromage", "le potage du jour", "la salade de chicons"], "a": 0, "trap": "« croquette » sounds harmless; the filling is the problem, and this one is grey shrimp", "expl": "Grey shrimp from the North Sea are a Belgian speciality — and they turn up in croquettes, tomatoes and sauces without warning."}, {"id": "fvc-restaurant-pro-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le vol-au-vent", "en": "chicken in puff pastry", "format": "fr2en", "options": ["chicken and mushroom in a pastry case", "a vegetable tart", "a cheese soufflé", "an ice-cream dessert"], "a": 0, "trap": "the name means 'flight in the wind', which tells you nothing about the chicken inside", "expl": "Belgian brasserie standard, always with frites. Also called « une bouchée à la reine » in France."}, {"id": "fvc-restaurant-pro-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le filet américain", "en": "raw minced beef", "format": "fr2en", "options": ["raw seasoned minced beef", "a grilled steak", "a beef burger", "an American-style club sandwich"], "a": 0, "trap": "the word 'américain' makes everyone expect a burger; it is served raw and cold", "expl": "« filet américain préparé » is raw beef with mayonnaise, capers and onion, usually with frites. Order it knowingly, not by accident.", "note": "Belgian speciality. In France the equivalent is « un steak tartare »."}, {"id": "fvc-restaurant-pro-A2-21", "level": "A2", "pos": "adj", "fr": "saignant", "en": "rare (of meat)", "format": "cloze", "q": "Vous voulez votre steak ___, à point ou bien cuit ?", "options": ["saignant", "salé", "sucré", "fumé"], "a": 0, "trap": "salé — 'salty', which fits the grammar and answers a different question entirely", "expl": "The three-step scale: saignant (rare), à point (medium), bien cuit (well done). « bleu » is barely cooked at all."}, {"id": "fvc-restaurant-pro-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "le serveur", "en": "the waiter", "format": "en2fr", "options": ["le serveur", "le serviteur", "le serrurier", "le sommelier"], "a": 0, "trap": "le serviteur — a servant, which is a very different job and a very rude thing to call someone", "expl": "All four masculine. Getting his attention: « Excusez-moi ! » or « S'il vous plaît ! » — never « Garçon ! », which is dated and rude."}, {"id": "fvc-restaurant-pro-A2-23", "level": "A2", "pos": "noun", "gender": "f", "fr": "la terrasse", "en": "the outdoor seating", "format": "fr2en", "options": ["the tables outside", "the roof terrace of a flat", "the pavement", "the awning"], "a": 0, "trap": "le trottoir — the pavement the terrasse stands on", "expl": "« Vous préférez en terrasse ou à l'intérieur ? » Brussels terraces come with gas heaters and blankets well into November."}, {"id": "fvc-restaurant-pro-A2-24", "level": "A2", "pos": "noun", "gender": "f", "fr": "la commande", "en": "the order", "format": "fr2en", "options": ["the order placed", "the command given to a soldier", "the remote control", "the counter"], "a": 0, "trap": "'command' — la commande in a restaurant is what you ordered, nothing military", "expl": "« Je prends votre commande ? » = shall I take your order? The verb is « commander »."}, {"id": "fvc-restaurant-pro-A2-25", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'addition", "en": "the bill", "format": "fr2en", "options": ["the restaurant bill", "the hotel bill", "the sum added at the end", "the extra portion"], "a": 0, "trap": "la note — that is the hotel bill; and « addition » literally means a sum, which is where the word comes from", "expl": "« L'addition, s'il vous plaît » — or catch the waiter's eye and mime signing. Hotel = la note, company invoice = la facture."}, {"id": "fvc-restaurant-pro-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pourboire", "en": "the tip", "format": "fr2en", "options": ["the tip left for service", "the change you get back", "the service charge on the bill", "the deposit"], "a": 0, "trap": "la monnaie — the change; the two get mixed up at exactly the moment you are paying", "expl": "Literally 'for drinking'. In Belgium service is included, so a tip is a genuine extra: round up, or 5 % if you were looked after."}, {"id": "fvc-restaurant-pro-A2-27", "level": "A2", "pos": "noun", "gender": "m", "fr": "le service", "en": "the service charge", "format": "collocation", "q": "A Belgian menu says « Service et TVA compris ». What does that mean for you?", "options": ["Le pourboire n'est pas obligatoire.", "Il faut ajouter 10 % au total.", "Le service sera facturé à la fin.", "La TVA sera ajoutée à l'addition."], "a": 0, "trap": "adding 10 % is the American habit and is not expected here", "expl": "Belgian prices are all-in: service and 12 % VAT on food are already inside the printed price. Tipping is a choice, not a duty.", "note": "Belgian and French practice alike. Tipping culture here is much lighter than in the US or the UK."}, {"id": "fvc-restaurant-pro-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'allergie", "en": "the allergy", "format": "en2fr", "options": ["l'allergie", "l'angine", "l'alerte", "l'anomalie"], "a": 0, "trap": "l'angine — tonsillitis, which sounds close and means something else", "expl": "All four feminine. The sentence that matters: « Je suis allergique aux fruits de mer. »"}, {"id": "fvc-restaurant-pro-A2-29", "level": "A2", "pos": "noun", "gender": "m", "fr": "les fruits de mer", "en": "seafood / shellfish", "format": "fr2en", "options": ["shellfish and seafood", "dried fruit and nuts", "fresh fruit salad", "sea fish such as cod"], "a": 0, "trap": "les fruits secs — dried fruit and nuts; the word « fruits » in both is a false lead", "expl": "Covers mussels, prawns, oysters, langoustines. Fish alone is « le poisson » and is not counted as fruits de mer."}, {"id": "fvc-restaurant-pro-A2-30", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'arachide", "en": "the peanut", "format": "fr2en", "options": ["the peanut", "the hazelnut", "the almond", "the walnut"], "a": 0, "trap": "la noisette — the hazelnut; on allergen lists the two sit next to each other", "expl": "Allergen lists print « arachides » ; in a bar the same thing is « des cacahuètes »."}, {"id": "fvc-restaurant-pro-A2-31", "level": "A2", "pos": "noun", "gender": "m", "fr": "le gluten", "en": "gluten", "format": "cloze", "q": "Ma sœur ne mange pas de ___ : elle est cœliaque.", "options": ["gluten", "lactose", "poivre", "sucre"], "a": 0, "trap": "lactose — the other big intolerance, and the one people confuse it with", "expl": "All four are masculine nouns after « pas de ». « sans gluten » on the menu; the illness is « la maladie cœliaque »."}, {"id": "fvc-restaurant-pro-A2-32", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'erreur", "en": "the mistake", "format": "en2fr", "options": ["l'erreur", "la faute", "la panne", "la plainte"], "a": 0, "trap": "la faute — also 'mistake', but it carries blame; « il y a une erreur » is neutral and polite", "expl": "All four feminine. Say « Je crois qu'il y a une erreur » — never « c'est votre faute »."}, {"id": "fvc-restaurant-pro-A2-33", "level": "A2", "pos": "verb", "fr": "se tromper", "en": "to make a mistake", "format": "fr2en", "options": ["to make a mistake", "to deceive someone", "to be unfaithful", "to find something"], "a": 0, "trap": "tromper without se — to deceive, or to cheat on a partner; the pronoun changes everything", "expl": "« Je me suis trompé » = I got it wrong. « On s'est trompé de table » = they mixed up the tables."}, {"id": "fvc-restaurant-pro-A2-34", "level": "A2", "pos": "verb", "fr": "commander", "en": "to order", "format": "cloze", "q": "J'ai ___ les carbonnades, pas le waterzooi.", "options": ["commandé", "demandé", "acheté", "choisi"], "a": 0, "trap": "demandé — 'asked for' works in life but is weaker than the standard restaurant verb", "expl": "All four are past participles fitting « j'ai ___ ». « commander un plat » is the fixed verb; « ordonner » would be giving orders."}, {"id": "fvc-restaurant-pro-A2-35", "level": "A2", "pos": "verb", "fr": "apporter", "en": "to bring (a thing)", "format": "en2fr", "options": ["apporter", "amener", "emporter", "rapporter"], "a": 0, "trap": "amener — you bring a person, not a plate; the classic four-way trap", "expl": "porter = things, mener = people. ap- = towards here, em- = away: « à emporter » is takeaway."}, {"id": "fvc-restaurant-pro-A2-36", "level": "A2", "pos": "verb", "fr": "goûter", "en": "to taste", "format": "fr2en", "options": ["to taste something", "to enjoy a holiday", "to smell", "to swallow"], "a": 0, "trap": "« le goûter » as a noun is the afternoon snack children have at four o'clock", "expl": "« Vous voulez goûter ? » Careful with « déguster », which is tasting seriously, as with wine."}, {"id": "fvc-restaurant-pro-A2-37", "level": "A2", "pos": "verb", "fr": "partager", "en": "to share / split", "format": "cloze", "q": "On peut ___ l'addition en deux ?", "options": ["partager", "payer", "diviser", "compter"], "a": 0, "trap": "diviser — mathematically correct, socially odd; nobody divides a bill in French", "expl": "All four are infinitives after « on peut ». Also « payer séparément » — Belgian brasseries usually agree without fuss."}, {"id": "fvc-restaurant-pro-A2-38", "level": "A2", "pos": "adv", "fr": "séparément", "en": "separately", "format": "en2fr", "options": ["séparément", "ensemble", "également", "directement"], "a": 0, "trap": "également — 'also/equally', which sounds like it should mean 'equally split'", "expl": "All four are adverbs. « On peut payer séparément ? » is the single most useful sentence at the end of a group meal."}, {"id": "fvc-restaurant-pro-A2-39", "level": "A2", "pos": "verb", "fr": "offrir", "en": "to give free of charge", "format": "fr2en", "options": ["to give something free of charge", "to put on sale", "to suggest a choice", "to promise"], "a": 0, "trap": "'to offer' in the sense of putting something up for sale — that is « proposer » or « vendre »", "expl": "« Le café, c'est offert. » = the coffee is on the house. « Je vous l'offre » is a gift, not a proposal."}, {"id": "fvc-restaurant-pro-A2-40", "level": "A2", "pos": "adj", "fr": "épicé", "en": "spicy", "format": "fr2en", "options": ["hot with spices", "salty", "sweet", "bitter"], "a": 0, "trap": "salé — 'salty'; « épicé » is specifically about spice and chilli heat", "expl": "« Ce n'est pas trop épicé ? » Belgian brasserie food rarely is; « relevé » is the milder word for well-seasoned."}, {"id": "fvc-restaurant-pro-A2-41", "level": "A2", "pos": "adj", "fr": "végétarien", "en": "vegetarian", "format": "en2fr", "options": ["végétarien", "végétal", "végétalien", "potager"], "a": 0, "trap": "végétalien — that is vegan, one syllable and a whole diet away", "expl": "All four masculine adjectives. « Vous avez un plat végétarien ? » Vegan is « végétalien » or « végan »."}, {"id": "fvc-restaurant-pro-A2-42", "level": "A2", "pos": "adj", "fr": "compris", "en": "included", "format": "cloze", "q": "Le service et la TVA sont ___ dans nos prix.", "options": ["compris", "comptés", "ajoutés", "réduits"], "a": 0, "trap": "ajoutés — 'added', the opposite arrangement and the one Americans expect", "expl": "All four are masculine plural participles. This exact line is printed at the bottom of Belgian menus."}, {"id": "fvc-restaurant-pro-A2-43", "level": "A2", "pos": "adj", "fr": "délicieux", "en": "delicious", "format": "en2fr", "options": ["délicieux", "délicat", "dégoûtant", "difficile"], "a": 0, "trap": "délicat — 'delicate' or 'tricky', not 'delicious'", "expl": "All four masculine adjectives. « C'était délicieux, merci » on your way out is worth more than a tip."}, {"id": "fvc-restaurant-pro-A2-44", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "Ça fait ___-huit euros pour vous deux.", "options": ["septante", "nonante", "soixante", "quarante"], "a": 0, "trap": "nonante — the other Belgian number word, and 90 is a very different bill", "expl": "septante-huit = 78 €. Learn to hear it fast: the total always arrives spoken, not written.", "note": "Belgian French. France says soixante-dix-huit."}, {"id": "fvc-restaurant-pro-A2-45", "level": "A2", "pos": "expr", "fr": "s'il vous plaît", "en": "here you go (Belgian use)", "format": "collocation", "q": "The waiter puts your plate down and says « Et le vol-au-vent, s'il vous plaît ». What is he doing?", "options": ["Il vous sert votre plat.", "Il vous demande de payer.", "Il vous demande de patienter.", "Il s'excuse du retard."], "a": 0, "trap": "hearing 'please' and assuming he is asking you for something", "expl": "In Belgium « s'il vous plaît » doubles as 'here you go' when handing something over, copied from Dutch alstublieft.", "note": "Belgian French. In France a waiter says « voilà » or « et voilà pour vous »."}, {"id": "fvc-restaurant-pro-A2-46", "level": "A2", "pos": "noun", "gender": "f", "fr": "la praline", "en": "a filled chocolate (Belgian French)", "format": "fr2en", "options": ["a filled chocolate", "a caramelised almond", "a small cake", "a sugared biscuit"], "a": 0, "trap": "in France « une praline » is a caramelised almond — a completely different sweet", "expl": "« une boîte de pralines » from Neuhaus or Leonidas is the standard Belgian gift. The shop is « une chocolaterie ».", "note": "Belgian French. France: praline = caramelised almond; a filled chocolate there is « un chocolat » or « un bonbon de chocolat »."}], "phrases": [{"id": "ph-restaurant-pro-A2-01", "fr": "Bonsoir, nous sommes deux. Vous avez une table libre ?", "en": "Good evening, there are two of us. Do you have a table free?", "note": "« Nous sommes deux » — never « nous sommes deux personnes ». The waiter may answer « en terrasse ou à l'intérieur ? »"}, {"id": "ph-restaurant-pro-A2-02", "fr": "Est-ce que je peux avoir la carte, s'il vous plaît ?", "en": "Could I have the menu, please?", "note": "« la carte » is the list of dishes. Asking for « le menu » gets you the fixed-price formula instead."}, {"id": "ph-restaurant-pro-A2-03", "fr": "Quel est le plat du jour ?", "en": "What's the dish of the day?", "note": "Fixed phrase, « du jour », not « de la journée ». Usually the best value and the freshest thing in the kitchen."}, {"id": "ph-restaurant-pro-A2-04", "fr": "Je suis allergique aux fruits de mer.", "en": "I'm allergic to seafood.", "note": "« allergique à » + article: aux fruits de mer, aux arachides, au lactose. Say it before you order, not after."}, {"id": "ph-restaurant-pro-A2-05", "fr": "Est-ce qu'il y a des crevettes dans ce plat ?", "en": "Are there prawns in this dish?", "note": "Grey shrimp hide in Belgian croquettes, tomatoes and sauces. Ask about the dish, not just the menu heading."}, {"id": "ph-restaurant-pro-A2-06", "fr": "En entrée, je prends le potage, et ensuite les carbonnades.", "en": "For a starter I'll have the soup, and then the carbonnades.", "note": "« en entrée … et ensuite … » is the natural way to lay out an order in one breath."}, {"id": "ph-restaurant-pro-A2-07", "fr": "Pour moi, une pils, s'il vous plaît.", "en": "A lager for me, please.", "note": "« Pour moi, … » saves you conjugating anything when the waiter goes round the table. Belgium: pils; France: un demi."}, {"id": "ph-restaurant-pro-A2-08", "fr": "Une bouteille d'eau plate, s'il vous plaît.", "en": "A bottle of still water, please.", "note": "In Belgium tap water is not served free, so expect a bottle at 4–5 €. Still = plate, sparkling = pétillante."}, {"id": "ph-restaurant-pro-A2-09", "fr": "Est-ce que vous avez un plat végétarien ?", "en": "Do you have a vegetarian dish?", "note": "Vegan is « végétalien ». In a traditional brasserie the honest answer is often just the chicon au gratin or an omelette."}, {"id": "ph-restaurant-pro-A2-10", "fr": "Excusez-moi, je crois qu'il y a une erreur.", "en": "Excuse me, I think there's a mistake.", "note": "The perfect opener for any complaint: « je crois » leaves the waiter room to fix it without losing face."}, {"id": "ph-restaurant-pro-A2-11", "fr": "J'ai commandé les carbonnades, pas le waterzooi.", "en": "I ordered the carbonnades, not the waterzooi.", "note": "State the facts flatly, no apology needed. « pas le … » is enough; no need for « ce n'est pas ce que j'ai demandé »."}, {"id": "ph-restaurant-pro-A2-12", "fr": "Ce n'est pas grave, mais pouvez-vous le changer ?", "en": "It's not a problem, but could you change it?", "note": "« Ce n'est pas grave » keeps the tone warm while you still ask for the fix. Very French, very useful."}, {"id": "ph-restaurant-pro-A2-13", "fr": "Le plat est froid, est-ce que vous pouvez le réchauffer ?", "en": "The dish is cold, could you heat it up?", "note": "« réchauffer » = to warm up again. « chauffer » alone would mean heating it for the first time."}, {"id": "ph-restaurant-pro-A2-14", "fr": "C'était très bon, merci.", "en": "That was very good, thank you.", "note": "Said as the plates are cleared. « C'était délicieux » is the warmer version and always lands well."}, {"id": "ph-restaurant-pro-A2-15", "fr": "L'addition, s'il vous plaît.", "en": "The bill, please.", "note": "Restaurant = l'addition. Hotel = la note. Company invoice = la facture. Never mix them up at the wrong counter."}, {"id": "ph-restaurant-pro-A2-16", "fr": "On peut payer séparément ?", "en": "Can we pay separately?", "note": "Standard and unproblematic in Belgian brasseries. « Chacun paie sa part » is the fuller version."}, {"id": "ph-restaurant-pro-A2-17", "fr": "Je paie par Bancontact, et mon ami paie en espèces.", "en": "I'll pay by Bancontact and my friend will pay cash.", "note": "« en espèces » = in cash; « en liquide » is equally common. The terminal is « le terminal » or just « la machine »."}, {"id": "ph-restaurant-pro-A2-18", "fr": "Est-ce que le service est compris ?", "en": "Is service included?", "note": "In Belgium it always is — the menu says « service et TVA compris ». The question mostly tells you a tip is optional."}, {"id": "ph-restaurant-pro-A2-19", "fr": "Gardez la monnaie, merci.", "en": "Keep the change, thank you.", "note": "The normal size of a Belgian tip: round the bill up to the next euro or two. No percentage calculation involved."}, {"id": "ph-restaurant-pro-A2-20", "fr": "Merci beaucoup, bonne soirée !", "en": "Thank you very much, have a good evening!", "note": "You will often get « merci, au revoir, bonne soirée » back — it is worth answering rather than just walking out."}], "dialogue": [{"who": "waiter", "fr": "Bonsoir. Vous avez réservé ?", "en": "Good evening. Have you booked?", "gloss": {"réservé": "booked"}}, {"who": "you", "fr": "Bonsoir, non. Nous sommes deux. Est-ce que vous avez une table libre ?", "en": "Good evening, no. There are two of us. Do you have a table free?", "gloss": {"libre": "free, available"}, "accept": ["bonsoir non nous sommes deux est-ce que vous avez une table libre", "bonsoir non nous sommes deux vous avez une table libre", "non nous sommes deux est-ce que vous avez une table", "bonsoir non nous n'avons pas réservé nous sommes deux", "bonsoir non est-ce que vous avez une table pour deux personnes", "bonsoir non vous auriez une table pour deux"]}, {"who": "waiter", "fr": "Oui, il y a une table près de la fenêtre. Voilà la carte, s'il vous plaît.", "en": "Yes, there's a table by the window. Here's the menu.", "gloss": {"près de": "near", "carte": "menu (list of dishes)", "s'il vous plaît": "here you go (Belgian use when handing something over)"}}, {"who": "you", "fr": "Merci. Est-ce qu'il y a un plat du jour ce soir ?", "en": "Thank you. Is there a dish of the day this evening?", "gloss": {"plat du jour": "dish of the day"}, "accept": ["merci est-ce qu'il y a un plat du jour ce soir", "merci est-ce qu'il y a un plat du jour", "merci quel est le plat du jour ce soir", "merci beaucoup quel est le plat du jour", "merci vous avez un plat du jour ce soir", "merci est-ce que vous avez un plat du jour"]}, {"who": "waiter", "fr": "Oui : carbonnades flamandes avec des frites, dix-neuf euros cinquante.", "en": "Yes: Flemish beef stew with chips, nineteen euros fifty.", "gloss": {"carbonnades": "beef stewed in brown beer", "frites": "chips"}}, {"who": "you", "fr": "Je suis allergique aux fruits de mer. Est-ce qu'il y a des crevettes dans les carbonnades ?", "en": "I'm allergic to seafood. Are there prawns in the carbonnades?", "gloss": {"allergique": "allergic", "fruits de mer": "seafood, shellfish", "crevettes": "prawns, shrimp"}, "accept": ["je suis allergique aux fruits de mer est-ce qu'il y a des crevettes dans les carbonnades", "je suis allergique aux fruits de mer est-ce qu'il y a des crevettes dedans", "je suis allergique aux fruits de mer il y a des crevettes dans les carbonnades", "attention je suis allergique aux fruits de mer est-ce qu'il y en a dans les carbonnades", "je suis allergique aux fruits de mer est-ce que ce plat contient des crevettes", "je suis allergique aux crevettes est-ce qu'il y en a dans les carbonnades"]}, {"who": "waiter", "fr": "Non, ce sont des carbonnades au bœuf et à la bière. Mais attention : les croquettes en entrée sont aux crevettes grises.", "en": "No, they're beef and beer carbonnades. But careful: the croquettes as a starter are grey shrimp.", "gloss": {"bœuf": "beef", "attention": "careful", "croquettes": "croquettes", "grises": "grey"}}, {"who": "you", "fr": "Merci de me prévenir. Alors, en entrée, un potage, et ensuite les carbonnades.", "en": "Thanks for the warning. So, a soup for a starter, and then the carbonnades.", "gloss": {"prévenir": "to warn", "en entrée": "as a starter", "potage": "soup", "ensuite": "then, next"}, "accept": ["merci de me prévenir alors en entrée un potage et ensuite les carbonnades", "merci alors en entrée un potage et ensuite les carbonnades", "merci de me prévenir je prends un potage en entrée et les carbonnades ensuite", "d'accord merci alors je prends le potage et après les carbonnades", "merci alors un potage en entrée et les carbonnades comme plat", "merci de m'avoir prévenu je vais prendre un potage et les carbonnades"]}, {"who": "waiter", "fr": "Très bien. Et comme boisson ?", "en": "Very good. And to drink?", "gloss": {"comme boisson": "to drink, as a drink"}}, {"who": "you", "fr": "Une pils, s'il vous plaît, et une carafe d'eau pour la table.", "en": "A lager, please, and a jug of water for the table.", "gloss": {"pils": "ordinary lager", "carafe d'eau": "jug of tap water"}, "accept": ["une pils s'il vous plaît et une carafe d'eau pour la table", "une pils et une carafe d'eau s'il vous plaît", "pour moi une pils s'il vous plaît et une carafe d'eau", "une bière s'il vous plaît et une carafe d'eau pour la table", "une pils s'il vous plaît et de l'eau pour la table", "je voudrais une pils et une carafe d'eau s'il vous plaît"]}, {"who": "waiter", "fr": "L'eau du robinet, on ne la sert pas, monsieur. J'ai de l'eau plate ou pétillante en bouteille, à quatre euros cinquante.", "en": "We don't serve tap water, sir. I have still or sparkling bottled water at four euros fifty.", "gloss": {"eau du robinet": "tap water", "sert": "serve", "plate": "still", "pétillante": "sparkling"}}, {"who": "you", "fr": "Ah, d'accord. Alors une bouteille d'eau plate, s'il vous plaît.", "en": "Ah, all right. A bottle of still water then, please.", "gloss": {"bouteille": "bottle"}, "accept": ["ah d'accord alors une bouteille d'eau plate s'il vous plaît", "d'accord alors une bouteille d'eau plate s'il vous plaît", "ah bon alors une petite bouteille d'eau plate s'il vous plaît", "d'accord une bouteille d'eau plate alors", "très bien alors de l'eau plate en bouteille s'il vous plaît", "d'accord je prends une bouteille d'eau plate"]}, {"who": "waiter", "fr": "Voilà, s'il vous plaît : le waterzooi et le vol-au-vent.", "en": "Here you go: the waterzooi and the vol-au-vent.", "gloss": {"waterzooi": "creamy Ghent chicken stew", "vol-au-vent": "chicken in a pastry case"}}, {"who": "you", "fr": "Excusez-moi, je crois qu'il y a une erreur : j'ai commandé les carbonnades, pas le waterzooi.", "en": "Excuse me, I think there's a mistake: I ordered the carbonnades, not the waterzooi.", "gloss": {"erreur": "mistake", "commandé": "ordered"}, "accept": ["excusez-moi je crois qu'il y a une erreur j'ai commandé les carbonnades pas le waterzooi", "excusez-moi il y a une erreur j'ai commandé les carbonnades pas le waterzooi", "excusez-moi je crois qu'il y a une erreur j'ai commandé les carbonnades", "pardon je crois qu'il y a une erreur ce n'est pas ce que j'ai commandé j'ai pris les carbonnades", "excusez-moi je n'ai pas commandé le waterzooi j'ai commandé les carbonnades", "excusez-moi il y a une petite erreur j'avais commandé les carbonnades"]}, {"who": "waiter", "fr": "Oh pardon, je me suis trompé de table. Je vous apporte ça tout de suite… Voilà. Vous avez terminé ? Je peux débarrasser ?", "en": "Oh sorry, I got the wrong table. I'll bring you that right away… There we are. Have you finished? May I clear the table?", "gloss": {"je me suis trompé": "I made a mistake", "apporte": "am bringing", "tout de suite": "right away", "terminé": "finished", "débarrasser": "to clear the table"}}, {"who": "you", "fr": "Oui, c'était très bon, merci. L'addition, s'il vous plaît. On peut payer séparément ?", "en": "Yes, it was very good, thank you. The bill, please. Can we pay separately?", "gloss": {"addition": "the bill", "séparément": "separately"}, "accept": ["oui c'était très bon merci l'addition s'il vous plaît on peut payer séparément", "oui c'était très bon merci l'addition s'il vous plaît", "oui merci c'était délicieux l'addition s'il vous plaît on peut payer séparément", "oui c'était très bon est-ce qu'on peut avoir l'addition et payer séparément", "oui merci l'addition s'il vous plaît et on peut payer chacun sa part", "oui c'était très bon merci est-ce qu'on peut payer séparément"]}, {"who": "waiter", "fr": "Pas de problème. Ça fait septante-huit euros en tout : trente-neuf chacun.", "en": "No problem. That comes to seventy-eight euros in all: thirty-nine each.", "gloss": {"septante": "seventy (Belgian French; France: soixante-dix)", "en tout": "in all", "chacun": "each"}}, {"who": "you", "fr": "Est-ce que le service est compris ? Je paie par Bancontact.", "en": "Is service included? I'm paying by Bancontact.", "gloss": {"service": "service charge", "compris": "included"}, "accept": ["est-ce que le service est compris je paie par bancontact", "est-ce que le service est compris je paye par bancontact", "le service est compris je paie par bancontact", "est-ce que le service est compris et je peux payer par bancontact", "est-ce que le service est compris dans le prix je paie par bancontact", "le service est-il compris je vais payer par bancontact"]}, {"who": "waiter", "fr": "Oui, le service et la TVA sont compris. Voilà le terminal, s'il vous plaît.", "en": "Yes, service and VAT are included. Here's the card machine.", "gloss": {"TVA": "VAT", "terminal": "card machine"}}, {"who": "you", "fr": "Parfait. Gardez la monnaie, merci beaucoup et bonne soirée.", "en": "Perfect. Keep the change, thank you very much and have a good evening.", "gloss": {"Gardez": "keep", "monnaie": "change (coins)"}, "accept": ["parfait gardez la monnaie merci beaucoup et bonne soirée", "gardez la monnaie merci beaucoup et bonne soirée", "parfait gardez la monnaie merci bonne soirée", "voilà gardez la monnaie merci et bonne soirée", "merci beaucoup gardez la monnaie bonne soirée", "parfait merci beaucoup bonne soirée"]}], "exercises": [{"id": "ex-restaurant-pro-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carte", "en": "the menu", "format": "cloze", "q": "Vous pouvez m'apporter ___, s'il vous plaît ? Je voudrais choisir.", "options": ["la carte", "le menu", "l'addition", "la note"], "a": 0, "trap": "le menu — asking for that gets you the fixed formula, not the choice", "expl": "la carte = the list you read; le menu = the set deal; l'addition = the bill at the end."}, {"id": "ex-restaurant-pro-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "les frites", "en": "chips", "format": "fr2en", "options": ["hot chips", "crisps in a packet", "potato wedges", "hash browns"], "a": 0, "trap": "les chips — that word means crisps in French, and the mix-up happens constantly", "expl": "Belgian frites are twice-fried and sold at a friterie. Ask for « une sauce andalouse » on top if you want the local experience."}, {"id": "ex-restaurant-pro-A2-03", "level": "A2", "pos": "verb", "fr": "se tromper", "en": "to make a mistake", "format": "cloze", "q": "Excusez-moi, je crois que vous vous êtes ___ de plat.", "options": ["trompé", "perdu", "excusé", "servi"], "a": 0, "trap": "servi — « vous vous êtes servi » is real French and means you helped yourself", "expl": "All four are past participles with être and a reflexive pronoun. « se tromper de + noun » = to get the wrong one."}, {"id": "ex-restaurant-pro-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chicon", "en": "chicory (Belgian French)", "format": "en2fr", "options": ["le chicon", "le poireau", "le potiron", "le champignon"], "a": 0, "trap": "le poireau — the leek; another white winter vegetable on the same menus", "expl": "All four masculine. « un chicon au gratin » is the Belgian classic; in France the same vegetable is « une endive ».", "note": "Belgian French. France says endive; Flemish says witloof."}, {"id": "ex-restaurant-pro-A2-05", "level": "A2", "pos": "noun", "gender": "m", "fr": "les fruits de mer", "en": "seafood", "format": "collocation", "q": "Which sentence correctly declares a shellfish allergy?", "options": ["Je suis allergique aux fruits de mer.", "Je suis allergique des fruits de mer.", "J'ai une allergie aux fruits de mer sur moi.", "Je suis allergie aux fruits de mer."], "a": 0, "trap": "« allergique de » copies the English 'allergic of' that some learners produce", "expl": "allergique + à + article: aux fruits de mer, aux arachides, au gluten, à la pénicilline."}, {"id": "ex-restaurant-pro-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le pourboire", "en": "the tip", "format": "collocation", "q": "In a Belgian brasserie, what is a normal tip on a 78 € bill?", "options": ["Arrondir à 80 €, ou rien du tout.", "Ajouter 15 %, comme aux États-Unis.", "Ajouter exactement 10 %.", "Laisser la moitié du service."], "a": 0, "trap": "the 15 % habit — imported from the US and out of place here", "expl": "Service and VAT are already in the price. Rounding up is the local gesture; nobody counts percentages.", "note": "Belgium and France work the same way here, unlike the US or the UK."}, {"id": "ex-restaurant-pro-A2-07", "level": "A2", "pos": "verb", "fr": "apporter", "en": "to bring", "format": "cloze", "q": "Vous pouvez m'___ une autre fourchette, s'il vous plaît ?", "options": ["apporter", "amener", "emporter", "emmener"], "a": 0, "trap": "amener — reserved for bringing people, though every learner uses it for objects", "expl": "porter = carry things, mener = lead people. « à emporter » is the takeaway sign in every Brussels sandwich shop."}, {"id": "ex-restaurant-pro-A2-08", "level": "A2", "pos": "adv", "fr": "séparément", "en": "separately", "format": "cloze", "q": "On peut payer ___, chacun sa part ?", "options": ["séparément", "ensemble", "directement", "rapidement"], "a": 0, "trap": "ensemble — 'together', the exact opposite of what « chacun sa part » announces", "expl": "All four adverbs fit. Belgian brasseries almost always agree; big groups may be asked to pay together instead."}, {"id": "ex-restaurant-pro-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la carafe d'eau", "en": "the jug of water", "format": "fr2en", "options": ["a jug of tap water", "a bottle of mineral water", "a wine decanter", "a water glass"], "a": 0, "trap": "la carafe is also a wine decanter — same object, different contents", "expl": "Worth asking for anyway; some Brussels places now serve it, but they are entitled to refuse and usually do.", "note": "Belgian reality: no legal right to free tap water, unlike France."}, {"id": "ex-restaurant-pro-A2-10", "level": "A2", "pos": "adj", "fr": "saignant", "en": "rare", "format": "en2fr", "options": ["saignant", "salé", "sanglant", "savoureux"], "a": 0, "trap": "sanglant — 'bloody' in the violent sense; you do not want that word on a menu", "expl": "All four masculine adjectives. The scale: bleu, saignant, à point, bien cuit."}, {"id": "ex-restaurant-pro-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le filet américain", "en": "raw minced beef", "format": "collocation", "q": "You order « un filet américain » in Brussels. What arrives?", "options": ["De la viande de bœuf crue, avec des frites.", "Un hamburger avec du bacon.", "Un steak grillé bien cuit.", "Un sandwich club à l'américaine."], "a": 0, "trap": "the word américain steers everyone towards a burger", "expl": "Raw seasoned minced beef, cold, with mayonnaise and capers. Excellent — but only if you meant to order it.", "note": "Belgian speciality; France calls the equivalent « un steak tartare »."}, {"id": "ex-restaurant-pro-A2-12", "level": "A2", "pos": "adj", "fr": "compris", "en": "included", "format": "cloze", "q": "Le service est ___ dans nos prix, monsieur.", "options": ["compris", "ajouté", "offert", "gratuit"], "a": 0, "trap": "offert — 'free / on the house', which sounds close but says something else about the service", "expl": "All four are masculine singular adjectives or participles. « Service et TVA compris » is the Belgian menu formula."}, {"id": "ex-restaurant-pro-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "la praline", "en": "a filled chocolate (Belgian French)", "format": "fr2en", "options": ["a filled chocolate", "a caramelised almond", "a praline-flavoured cream", "a small biscuit"], "a": 0, "trap": "the French meaning — a caramelised almond — is the same word with a different referent", "expl": "« une ballotin de pralines » is the standard Belgian present. Neuhaus invented the filled praline in Brussels in 1912.", "note": "Belgian French. In France « une praline » is the sugared almond you buy at a fair."}, {"id": "ex-restaurant-pro-A2-14", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "fr2en", "options": ["seventy", "seventeen", "sixty", "seventy-seven"], "a": 0, "trap": "soixante-dix — the number you learned; here you must recognise the Belgian form spoken fast", "expl": "septante-huit euros = 78 €. If in doubt at the till, ask « Vous pouvez me le montrer ? » and read the total.", "note": "Belgian French. France says soixante-dix."}]},
  "restaurant-pro-B1": {"slug": "restaurant-pro", "level": "B1", "title": "Dîner de travail : une allergie ignorée et une addition contestée", "place": "Brasserie de la Place, place Sainte-Catherine, Bruxelles", "register": "vous", "registerNote": "Vous with the waiter and with the maître d'hôtel, and vous with the colleague you are dining with too, since this is a work dinner and you have met twice. Complaining in vous with the conditional (« il faudrait », « je préférerais ») is firm; switching to tu would be read as losing your temper.", "vocab": [{"id": "fvc-restaurant-pro-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "la réservation", "en": "the booking", "format": "collocation", "q": "Which is the natural way to announce a booking on arrival?", "options": ["J'ai une réservation au nom de Vasileiadis.", "J'ai une réservation sous le nom de Vasileiadis.", "J'ai réservé par le nom de Vasileiadis.", "J'ai une réservation dans le nom de Vasileiadis."], "a": 0, "trap": "« sous le nom de » exists, but it suggests an assumed name — a stage name or an alias", "expl": "Fixed: « au nom de ». Spell it out afterwards: « Vasileiadis, V comme Victor »."}, {"id": "fvc-restaurant-pro-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la suggestion du chef", "en": "the chef's special", "format": "fr2en", "options": ["the chef's off-menu special", "the chef's advice on wine", "the tasting menu", "a customer suggestion box"], "a": 0, "trap": "« la carte des suggestions » is a real slate, but « la suggestion du chef » is one dish, announced aloud", "expl": "The waiter recites it: « Ce soir, en suggestion, nous avons… ». Always ask the price — it is rarely printed."}, {"id": "fvc-restaurant-pro-B1-03", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'accompagnement", "en": "the side dish", "format": "en2fr", "options": ["l'accompagnement", "l'assaisonnement", "l'arrangement", "l'aboutissement"], "a": 0, "trap": "l'assaisonnement — the seasoning, which is what goes on the dish rather than beside it", "expl": "All four masculine -ment nouns. Also « la garniture ». « Quel accompagnement avec l'entrecôte ? — Frites ou salade. »"}, {"id": "fvc-restaurant-pro-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "la cuisson", "en": "how it is cooked", "format": "fr2en", "options": ["the degree to which meat is cooked", "the kitchen", "the cooking time only", "the cooker"], "a": 0, "trap": "la cuisine — the kitchen and the cooking as an art; « la cuisson » is the doneness", "expl": "« Quelle cuisson pour votre entrecôte ? » Answer with saignant, à point or bien cuit — not with a number of minutes."}, {"id": "fvc-restaurant-pro-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'allergène", "en": "the allergen", "format": "fr2en", "options": ["a substance that triggers an allergy", "an allergic reaction", "an antihistamine", "an allergy test"], "a": 0, "trap": "l'allergie — the condition; l'allergène is the substance in the food", "expl": "EU rules oblige Belgian restaurants to be able to tell you which of the fourteen allergens a dish contains, in writing or orally."}, {"id": "fvc-restaurant-pro-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la trace", "en": "the trace amount", "format": "cloze", "q": "Est-ce qu'il peut y avoir des ___ de crevettes dans cette sauce ?", "options": ["traces", "gouttes", "miettes", "portions"], "a": 0, "trap": "gouttes — 'drops', physically plausible and not the allergy word", "expl": "All four are feminine plural nouns. « des traces de » is the standard allergen phrase, printed on every Belgian packet too."}, {"id": "fvc-restaurant-pro-B1-07", "level": "B1", "pos": "noun", "gender": "f", "fr": "la contamination croisée", "en": "cross-contamination", "format": "en2fr", "options": ["la contamination croisée", "la contamination directe", "la conservation croisée", "la contagion croisée"], "a": 0, "trap": "la contagion — that is for illnesses passing between people, not for a shared fryer", "expl": "All four feminine. The question that follows: « Est-ce que vous utilisez la même friteuse pour les croquettes ? »"}, {"id": "fvc-restaurant-pro-B1-08", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'intolérance", "en": "the intolerance", "format": "fr2en", "options": ["a digestive intolerance", "a life-threatening allergy", "a food preference", "a dietary religion"], "a": 0, "trap": "l'allergie — restaurants react very differently to the two words, so use the true one", "expl": "« Une intolérance au lactose » makes you ill; « une allergie aux arachides » can put you in hospital. Say which you have."}, {"id": "fvc-restaurant-pro-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "le malentendu", "en": "the misunderstanding", "format": "fr2en", "options": ["a misunderstanding", "a badly heard word", "a disagreement on principle", "a hearing problem"], "a": 0, "trap": "le désaccord — a disagreement, where a malentendu is nobody's deliberate fault", "expl": "The diplomatic word for a complaint: « Il y a eu un malentendu sur ma commande. » It lets everyone keep face."}, {"id": "fvc-restaurant-pro-B1-10", "level": "B1", "pos": "noun", "gender": "m", "fr": "le maître d'hôtel", "en": "the head waiter", "format": "en2fr", "options": ["le maître d'hôtel", "le directeur d'hôtel", "le chef de cuisine", "le sommelier"], "a": 0, "trap": "le directeur d'hôtel — a hotel manager; the maître d'hôtel runs the dining room", "expl": "All four masculine. « Je peux parler au maître d'hôtel ? » is the escalation step before asking for the patron."}, {"id": "fvc-restaurant-pro-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "le couvert", "en": "the place setting / cover charge", "format": "fr2en", "options": ["the place setting for one person", "the lid of a dish", "the tablecloth", "the roof terrace"], "a": 0, "trap": "« le couvercle » is the lid — near-identical word, different object", "expl": "« une table de quatre couverts » = a table for four. Belgian brasseries do not normally charge « le couvert » as a separate item."}, {"id": "fvc-restaurant-pro-B1-12", "level": "B1", "pos": "noun", "gender": "f", "fr": "la note de frais", "en": "the expense claim", "format": "fr2en", "options": ["an expense claim to your employer", "the restaurant bill", "a bank statement", "the fee note of a lawyer"], "a": 0, "trap": "la note — the bill itself; « la note de frais » is the internal form you fill in afterwards", "expl": "To claim it back you need « une facture » with the company name and BE VAT number, not just the till receipt."}, {"id": "fvc-restaurant-pro-B1-13", "level": "B1", "pos": "noun", "gender": "m", "fr": "le chèque-repas", "en": "the meal voucher", "format": "collocation", "q": "Which is true of Belgian chèques-repas in 2026?", "options": ["Ils sont électroniques et valent au maximum 10 € par jour presté.", "Ils sont en papier et valent au maximum 8 € par mois.", "Ils ne sont acceptés que dans les supermarchés.", "Ils remplacent le salaire net."], "a": 0, "trap": "the €8 ceiling — correct until the end of 2025 and out of date since January 2026", "expl": "Since 1 January 2026 the maximum face value is 10 €: employer up to 8,91 €, employee at least 1,09 € deducted from net pay. They are loaded onto a card and accepted in most restaurants and supermarkets.", "note": "Belgian institution with no French equivalent under that name — France has « les titres-restaurant »."}, {"id": "fvc-restaurant-pro-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "la remise", "en": "the discount", "format": "en2fr", "options": ["la remise", "la reprise", "la rentrée", "la retenue"], "a": 0, "trap": "la retenue — a deduction from your pay, or a detention at school", "expl": "All four feminine. « Je vous fais une remise de dix pour cent. » Also « un rabais », « une ristourne » (very Belgian in shops)."}, {"id": "fvc-restaurant-pro-B1-15", "level": "B1", "pos": "prep", "fr": "des", "en": "of the (de + les)", "format": "cloze", "q": "Je peux voir la carte ___ vins, s'il vous plaît ?", "options": ["des", "de", "du", "aux"], "a": 0, "trap": "du — you would be asking for the list of one particular wine", "expl": "« la carte des vins », « la carte des desserts », « la carte des bières » — de + les always contracts to des before a plural."}, {"id": "fvc-restaurant-pro-B1-16", "level": "B1", "pos": "noun", "gender": "m", "fr": "le vin de la maison", "en": "the house wine", "format": "fr2en", "options": ["the house wine sold by the glass or jug", "a wine made on the premises", "the most expensive wine", "a wine offered free"], "a": 0, "trap": "'made in-house' — a Brussels brasserie makes no wine; the phrase just means their default pour", "expl": "« Un verre de rouge, le vin de la maison » is the safe, cheap order. « en carafe » or « au pichet » for a jug."}, {"id": "fvc-restaurant-pro-B1-17", "level": "B1", "pos": "verb", "fr": "préciser", "en": "to specify", "format": "cloze", "q": "J'avais pourtant ___ au téléphone que j'étais allergique aux crevettes.", "options": ["précisé", "prévu", "prévenu", "présenté"], "a": 0, "trap": "prévenu — 'warned', which also works in life but loses the idea that you gave the detail explicitly", "expl": "All four are past participles. Note « j'avais précisé » — the pluperfect places it before the mistake, which is the whole point of saying it."}, {"id": "fvc-restaurant-pro-B1-18", "level": "B1", "pos": "verb", "fr": "remplacer", "en": "to replace", "format": "en2fr", "options": ["remplacer", "replacer", "rembourser", "renvoyer"], "a": 0, "trap": "replacer — to put something back in its place; one letter, another verb", "expl": "All four infinitives. « Est-ce que vous pouvez me remplacer ce plat ? » Sending it back is « renvoyer en cuisine »."}, {"id": "fvc-restaurant-pro-B1-19", "level": "B1", "pos": "verb", "fr": "retirer", "en": "to take off / remove", "format": "cloze", "q": "Est-ce que vous pouvez ___ cet apéritif de l'addition ? Nous n'en avons pris qu'un.", "options": ["retirer", "rendre", "reprendre", "rembourser"], "a": 0, "trap": "rembourser — refunding money already paid, whereas here the bill has not been settled yet", "expl": "All four infinitives. « retirer de l'addition » = take it off the bill; the polite escalation is « rectifier l'addition »."}, {"id": "fvc-restaurant-pro-B1-20", "level": "B1", "pos": "verb", "fr": "rectifier", "en": "to correct", "format": "fr2en", "options": ["to correct an error", "to make something stronger", "to rectify a wrong done to you", "to refill"], "a": 0, "trap": "'to rectify' in the moral sense — in French the word is administrative and neutral", "expl": "« Je rectifie l'addition tout de suite. » Also « corriger », which is what a teacher does to homework."}, {"id": "fvc-restaurant-pro-B1-21", "level": "B1", "pos": "verb", "fr": "se rendre compte", "en": "to realise", "format": "fr2en", "options": ["to realise something", "to give an account of something", "to count up", "to report back"], "a": 0, "trap": "'to realise' meaning 'to achieve' — that is « réaliser un projet »", "expl": "« Je viens de me rendre compte qu'il y a une erreur. » Takes de + noun, or que + indicative."}, {"id": "fvc-restaurant-pro-B1-22", "level": "B1", "pos": "verb", "fr": "déconseiller", "en": "to advise against", "format": "en2fr", "options": ["déconseiller", "recommander", "décommander", "conseiller"], "a": 0, "trap": "décommander — to cancel a booking or an order; near-identical shape, unrelated meaning", "expl": "All four infinitives. « Je vous le déconseille, il y a des crevettes dans la sauce. »"}, {"id": "fvc-restaurant-pro-B1-23", "level": "B1", "pos": "verb", "fr": "insister", "en": "to insist", "format": "cloze", "q": "Je ne veux pas ___, mais c'est la deuxième fois que je le signale.", "options": ["insister", "exister", "assister", "résister"], "a": 0, "trap": "assister — 'to attend' or 'to assist'; a false friend twice over", "expl": "All four are infinitives in -ister. « Je ne veux pas insister, mais… » is how you insist politely in French."}, {"id": "fvc-restaurant-pro-B1-24", "level": "B1", "pos": "verb", "fr": "arrondir", "en": "to round up", "format": "fr2en", "options": ["to round a sum up or down", "to hand out change", "to share equally", "to add a service charge"], "a": 0, "trap": "partager — to split; arrondir is about the final figure, not who pays it", "expl": "« On arrondit à cent euros ? » is how a Belgian table settles a tip: no percentages, just a rounder number."}, {"id": "fvc-restaurant-pro-B1-25", "level": "B1", "pos": "adj", "fr": "immangeable", "en": "inedible", "format": "en2fr", "options": ["immangeable", "inmangeable", "immanquable", "immuable"], "a": 0, "trap": "« inmangeable » — the form learners build by rule; French turns in- into im- before m", "expl": "All four masculine adjectives. Strong word: use « ce n'est pas très bon » unless you really mean it."}, {"id": "fvc-restaurant-pro-B1-26", "level": "B1", "pos": "adj", "fr": "tiède", "en": "lukewarm", "format": "fr2en", "options": ["lukewarm", "piping hot", "chilled", "frozen"], "a": 0, "trap": "'tepid' feels mild in English; in a French complaint « tiède » is a serious criticism of a hot dish", "expl": "« Mon plat est tiède, est-ce que vous pouvez le réchauffer ? » Between « froid » and « chaud »."}, {"id": "fvc-restaurant-pro-B1-27", "level": "B1", "pos": "adj", "fr": "copieux", "en": "generous (portion)", "format": "fr2en", "options": ["generously large", "richly sauced", "expensive", "shared between two"], "a": 0, "trap": "'copious' in English suggests quantity of liquid; here it is simply a big plate", "expl": "« Les portions sont copieuses » is a compliment in Belgium, where it is also usually true."}, {"id": "fvc-restaurant-pro-B1-28", "level": "B1", "pos": "adj", "fr": "corsé", "en": "full-bodied (wine)", "format": "en2fr", "options": ["corsé", "corsaire", "corrosif", "correct"], "a": 0, "trap": "corsaire — a privateer; the two words share nothing but their first five letters", "expl": "All four masculine adjectives. « un rouge assez corsé » — the opposite is « léger »."}, {"id": "fvc-restaurant-pro-B1-29", "level": "B1", "pos": "expr", "fr": "à la place de", "en": "instead of", "format": "cloze", "q": "Est-ce que je peux avoir une salade ___ la place des frites ?", "options": ["à", "en", "dans", "sur"], "a": 0, "trap": "en — « en place de » exists in old written French and sounds wrong here", "expl": "« à la place de » + noun. With a verb: « au lieu de commander », which is the same idea one register up."}, {"id": "fvc-restaurant-pro-B1-30", "level": "B1", "pos": "expr", "fr": "en ce qui me concerne", "en": "as far as I'm concerned", "format": "en2fr", "options": ["en ce qui me concerne", "en ce qui me regarde", "à ce qui me concerne", "pour ce que je concerne"], "a": 0, "trap": "« en ce qui me regarde » — regarder does mean 'to concern' («ça ne te regarde pas »), but the fixed phrase uses concerner", "expl": "Useful when a table is settling up: « En ce qui me concerne, j'ai pris l'entrecôte et un verre de vin. »"}, {"id": "fvc-restaurant-pro-B1-31", "level": "B1", "pos": "expr", "fr": "si cela ne vous dérange pas", "en": "if you don't mind", "format": "fr2en", "options": ["if it's not a bother to you", "if you're not too busy", "if you don't disagree", "if it's not too late"], "a": 0, "trap": "'if you don't mind' read as « si ça vous est égal » — that means 'if it's all the same to you', which is subtly ruder", "expl": "« Nous paierons séparément, si cela ne vous dérange pas. » In speech: « si ça ne vous dérange pas »."}, {"id": "fvc-restaurant-pro-B1-32", "level": "B1", "pos": "expr", "fr": "je me permets de", "en": "may I / I'll take the liberty of", "format": "cloze", "q": "Je me ___ de vous signaler qu'il y a une erreur sur l'addition.", "options": ["permets", "promets", "prépare", "présente"], "a": 0, "trap": "promets — 'I promise', which fits the grammar and changes the whole speech act", "expl": "« Je me permets de… » is the polite formula for raising something awkward, in speech and in emails alike."}, {"id": "fvc-restaurant-pro-B1-33", "level": "B1", "pos": "expr", "fr": "ce n'est pas la peine", "en": "there's no need", "format": "fr2en", "options": ["there's no need to bother", "it isn't painful", "it isn't worth the money", "it's not a punishment"], "a": 0, "trap": "la peine also means sorrow and a court sentence — none of that is in this phrase", "expl": "Turning down a fix you don't want: « Ce n'est pas la peine de le réchauffer, ça ira. »"}, {"id": "fvc-restaurant-pro-B1-34", "level": "B1", "pos": "noun", "gender": "f", "fr": "la friterie", "en": "the chip shop", "format": "fr2en", "options": ["a chip stand or shop", "a deep-fat fryer", "a fried-food factory", "a fry-up breakfast"], "a": 0, "trap": "la friteuse — the fryer itself, the machine in the kitchen", "expl": "Also « un fritkot » in Brussels, from the Flemish. UNESCO-adjacent national institution; sauces cost about 1 €.", "note": "Belgian French. France would say « une baraque à frites », and fritkot means nothing there."}, {"id": "fvc-restaurant-pro-B1-35", "level": "B1", "pos": "adv", "fr": "tantôt", "en": "earlier / later today (Belgian French)", "format": "fr2en", "options": ["earlier or later the same day", "sometimes", "immediately", "long ago"], "a": 0, "trap": "« tantôt… tantôt… » in standard French means 'sometimes… sometimes…', a completely different use", "expl": "« Je vous ai appelés tantôt pour l'allergie. » = I called you earlier today. Very common in Brussels speech.", "note": "Belgian French. In France « tantôt » sounds regional or archaic and mostly survives in « tantôt… tantôt… »."}, {"id": "fvc-restaurant-pro-B1-36", "level": "B1", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "cloze", "q": "L'addition s'élève à cent ___-quatre euros, service compris.", "options": ["nonante", "septante", "quatre-vingt", "soixante"], "a": 0, "trap": "septante — the other Belgian form; 70 and 90 are exactly the two that change", "expl": "cent nonante-quatre = 194 €. Belgium keeps quatre-vingts for 80: only 70 and 90 have their own words.", "note": "Belgian French. France says cent quatre-vingt-quatorze."}, {"id": "fvc-restaurant-pro-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "la TVA", "en": "VAT", "format": "collocation", "q": "Which is correct about VAT in a Belgian restaurant?", "options": ["La TVA est déjà comprise dans les prix affichés.", "La TVA est ajoutée à la fin, comme aux États-Unis.", "La TVA n'existe pas sur la restauration.", "La TVA est payée séparément par le client."], "a": 0, "trap": "the American habit of adding tax at the till, which does not exist in the EU retail price", "expl": "Belgian menus print all-in prices: 12 % VAT on food eaten in, 21 % on drinks, plus service. What you read is what you pay."}, {"id": "fvc-restaurant-pro-B1-38", "level": "B1", "pos": "noun", "gender": "f", "fr": "la facture", "en": "the VAT invoice", "format": "cloze", "q": "Il me faudrait une ___ au nom de la société, pour ma note de frais.", "options": ["facture", "addition", "monnaie", "commande"], "a": 0, "trap": "addition — what the waiter brings by default, and what your finance department will refuse", "expl": "All four feminine. Ask before you pay: some Belgian tills cannot reissue an invoice once the ticket is closed."}, {"id": "fvc-restaurant-pro-B1-39", "level": "B1", "pos": "verb", "fr": "régler", "en": "to settle up", "format": "collocation", "q": "Which is the waiter's normal question about payment?", "options": ["Vous réglez comment ?", "Vous réglez quoi ?", "Vous réglez avec quoi que ce soit ?", "Vous régularisez comment ?"], "a": 0, "trap": "« régulariser » is a real verb — it means sorting out an irregular situation with the authorities", "expl": "« Vous réglez comment ? — Par Bancontact. » Also « Ensemble ou séparément ? »"}, {"id": "fvc-restaurant-pro-B1-40", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'apéritif maison", "en": "the house aperitif", "format": "fr2en", "options": ["the bar's own aperitif of the day", "a free welcome drink", "a homemade liqueur for sale", "the digestif at the end"], "a": 0, "trap": "assuming « maison » means it is free — it means their own version, and it is on the bill", "expl": "« maison » = made or chosen here: l'apéritif maison, la terrine maison, les frites maison. Always priced."}, {"id": "fvc-restaurant-pro-B1-41", "level": "B1", "pos": "noun", "gender": "m", "fr": "le digestif", "en": "the after-dinner drink", "format": "en2fr", "options": ["le digestif", "l'apéritif", "le dessert", "le café"], "a": 0, "trap": "l'apéritif — the same ritual at the other end of the meal", "expl": "All four masculine. In Belgium a genièvre or an elixir d'Anvers; often « offert par la maison » at the end of a good dinner."}, {"id": "fvc-restaurant-pro-B1-42", "level": "B1", "pos": "verb", "fr": "patienter", "en": "to wait", "format": "cloze", "q": "Si vous voulez bien ___ deux minutes, je vérifie en cuisine.", "options": ["patienter", "attendre", "rester", "revenir"], "a": 0, "trap": "attendre — perfectly correct French, but « si vous voulez bien patienter » is the fixed service formula", "expl": "All four infinitives fit. « patienter » belongs to counters, phone queues and dining rooms."}, {"id": "fvc-restaurant-pro-B1-43", "level": "B1", "pos": "noun", "gender": "f", "fr": "la cuisine", "en": "the kitchen / the cooking", "format": "collocation", "q": "Which sentence means the kitchen has closed?", "options": ["La cuisine ferme à vingt-deux heures.", "La cuisson ferme à vingt-deux heures.", "Le cuisinier ferme à vingt-deux heures.", "La carte ferme à vingt-deux heures."], "a": 0, "trap": "« la cuisson » — the doneness of your steak, which cannot close", "expl": "In Belgium many brasserie kitchens stop at 22:00 sharp even if the bar stays open. Ask « La cuisine est encore ouverte ? »"}, {"id": "fvc-restaurant-pro-B1-44", "level": "B1", "pos": "verb", "fr": "signaler", "en": "to point out", "format": "en2fr", "options": ["signaler", "signifier", "souligner", "signer"], "a": 0, "trap": "signifier — 'to mean', or in law 'to serve notice on someone'", "expl": "All four infinitives. « Je vous signale qu'il y a une erreur » is neutral and firm; « je vous préviens » would sound like a threat."}, {"id": "fvc-restaurant-pro-B1-45", "level": "B1", "pos": "noun", "gender": "m", "fr": "le geste", "en": "the gesture (of goodwill)", "format": "cloze", "q": "Le patron a fait un ___ : il nous a offert les cafés.", "options": ["geste", "cadeau", "compliment", "effort"], "a": 0, "trap": "cadeau — a present, which is not what a restaurant does with a bill", "expl": "All four masculine. « faire un geste » = to knock something off or throw something in. Fuller form: « un geste commercial »."}, {"id": "fvc-restaurant-pro-B1-46", "level": "B1", "pos": "adj", "fr": "réchauffé", "en": "reheated", "format": "fr2en", "options": ["heated up again", "warmed for the first time", "overcooked", "kept warm under a lamp"], "a": 0, "trap": "chauffé — heated, with no idea of 'again'; the ré- prefix is doing all the work", "expl": "« Ce n'est pas la peine de le réchauffer » — the sentence that ends a complaint without escalating it."}], "phrases": [{"id": "ph-restaurant-pro-B1-01", "fr": "Bonsoir, j'ai une réservation au nom de Vasileiadis, pour deux personnes.", "en": "Good evening, I have a booking in the name of Vasileiadis, for two.", "note": "« au nom de », never « sous le nom de ». Be ready to spell it: « V comme Victor, A comme Anatole… »"}, {"id": "ph-restaurant-pro-B1-02", "fr": "J'avais précisé au téléphone que j'étais allergique aux crevettes.", "en": "I had specified on the phone that I was allergic to prawns.", "note": "The pluperfect « j'avais précisé » places it before tonight's mistake, which is exactly why you use it."}, {"id": "ph-restaurant-pro-B1-03", "fr": "Est-ce que ce plat peut contenir des traces de fruits de mer ?", "en": "Can this dish contain traces of shellfish?", "note": "Belgian restaurants must be able to answer on the fourteen EU allergens. « des traces de » is the standard wording."}, {"id": "ph-restaurant-pro-B1-04", "fr": "Est-ce que les frites sont cuites dans la même friteuse que les croquettes ?", "en": "Are the chips fried in the same fryer as the croquettes?", "note": "The cross-contamination question in plain kitchen language — far more useful than saying « contamination croisée »."}, {"id": "ph-restaurant-pro-B1-05", "fr": "Je préférerais une salade à la place des frites, si c'est possible.", "en": "I'd rather have a salad instead of the chips, if that's possible.", "note": "« à la place de » + noun; « au lieu de » + verb. The conditional makes it a request, not an instruction."}, {"id": "ph-restaurant-pro-B1-06", "fr": "Quelle cuisson me conseillez-vous pour l'entrecôte ?", "en": "How would you advise having the rib steak done?", "note": "Inversion « me conseillez-vous » is a register upgrade that costs nothing and always lands well with a waiter."}, {"id": "ph-restaurant-pro-B1-07", "fr": "Je me permets de vous signaler qu'il y a un problème avec mon plat.", "en": "May I point out that there's a problem with my dish.", "note": "« Je me permets de » is the polite opener for anything awkward, spoken or written. It buys goodwill instantly."}, {"id": "ph-restaurant-pro-B1-08", "fr": "Ce n'est pas ce que j'avais commandé, mais ce n'est pas grave.", "en": "That's not what I'd ordered, but it doesn't matter.", "note": "Say the facts, then release the pressure. The pluperfect « j'avais commandé » signals the order came first."}, {"id": "ph-restaurant-pro-B1-09", "fr": "Est-ce que vous pouvez le renvoyer en cuisine et me le remplacer ?", "en": "Could you send it back to the kitchen and replace it for me?", "note": "« renvoyer en cuisine » is the professional phrase. « remplacer » ≠ « replacer » (to put back in place)."}, {"id": "ph-restaurant-pro-B1-10", "fr": "Mon plat est tiède, est-ce que vous pouvez le réchauffer ?", "en": "My dish is lukewarm, could you heat it up?", "note": "« tiède » is a real criticism in French, stronger than the English 'lukewarm' sounds. Use it when you mean it."}, {"id": "ph-restaurant-pro-B1-11", "fr": "Nous voudrions l'addition, et nous paierons séparément si cela ne vous dérange pas.", "en": "We'd like the bill, and we'll pay separately if you don't mind.", "note": "Announce it before the bill is printed; once the ticket is closed some Belgian tills will not split it."}, {"id": "ph-restaurant-pro-B1-12", "fr": "En ce qui me concerne, j'ai pris l'entrecôte, un verre de rouge et un café.", "en": "As far as I'm concerned, I had the rib steak, a glass of red and a coffee.", "note": "The clean way to split a bill by item without arithmetic in front of the waiter."}, {"id": "ph-restaurant-pro-B1-13", "fr": "Je crois qu'il y a une erreur : nous n'avons pris qu'un seul apéritif.", "en": "I think there's a mistake: we only had one aperitif.", "note": "« ne … qu' » = only. « Je crois que » keeps it a possible misreading rather than an accusation."}, {"id": "ph-restaurant-pro-B1-14", "fr": "Est-ce que vous pouvez retirer cet article de l'addition ?", "en": "Could you take that item off the bill?", "note": "« retirer de l'addition » for something not yet paid; « rembourser » only once money has changed hands."}, {"id": "ph-restaurant-pro-B1-15", "fr": "Il me faudrait une facture au nom de la société, avec le numéro de TVA.", "en": "I'd need an invoice in the company's name, with the VAT number.", "note": "Belgian expense rules: the till receipt is not enough. Ask for the invoice before you pay, not after."}, {"id": "ph-restaurant-pro-B1-16", "fr": "Est-ce que vous acceptez les chèques-repas ?", "en": "Do you accept meal vouchers?", "note": "Most Belgian restaurants do. They are electronic, loaded on a card, and worth up to 10 € per working day since January 2026."}, {"id": "ph-restaurant-pro-B1-17", "fr": "On arrondit à deux cents euros, ça ira très bien.", "en": "Let's round it up to two hundred euros, that'll be fine.", "note": "How a tip is actually given in Belgium: no percentage, just a rounder figure. Service is already included."}, {"id": "ph-restaurant-pro-B1-18", "fr": "Je vous ai appelés tantôt, vers quinze heures, pour signaler l'allergie.", "en": "I called you earlier today, around three, to flag the allergy.", "note": "« tantôt » = earlier or later today in Belgium. In France it would be heard as regional or as « sometimes »."}, {"id": "ph-restaurant-pro-B1-19", "fr": "C'était très bien, malgré ce petit malentendu. Merci d'avoir arrangé ça.", "en": "It was very good, despite that small misunderstanding. Thanks for sorting it out.", "note": "« malgré » + noun. Ending on the fix rather than the fault is what gets you looked after next time."}, {"id": "ph-restaurant-pro-B1-20", "fr": "Est-ce que la cuisine est encore ouverte ? Nous arrivons vers vingt et une heures trente.", "en": "Is the kitchen still open? We'll be arriving around nine thirty.", "note": "Belgian brasserie kitchens often stop at 22:00 even when the bar is busy. Worth a phone call before you walk over."}], "dialogue": [{"who": "waiter", "fr": "Bonsoir messieurs. Vous avez réservé ?", "en": "Good evening gentlemen. Have you booked?", "gloss": {"réservé": "booked"}}, {"who": "you", "fr": "Bonsoir. Oui, j'ai une réservation au nom de Vasileiadis, pour deux personnes, à vingt heures.", "en": "Good evening. Yes, I have a booking in the name of Vasileiadis, for two, at eight o'clock.", "gloss": {"au nom de": "in the name of"}, "accept": ["bonsoir oui j'ai une réservation au nom de vasileiadis pour deux personnes à vingt heures", "bonsoir oui j'ai une réservation au nom de vasileiadis pour deux personnes", "bonsoir j'ai réservé au nom de vasileiadis pour deux personnes à vingt heures", "oui bonsoir une réservation au nom de vasileiadis pour deux", "bonsoir j'ai une table réservée au nom de vasileiadis à vingt heures", "bonsoir oui c'est une réservation au nom de vasileiadis"]}, {"who": "waiter", "fr": "Je vous en prie, suivez-moi. Voici la carte ; ce soir, en suggestion du chef, nous avons un waterzooi de poulet.", "en": "This way please, follow me. Here's the menu; tonight, as the chef's special, we have a chicken waterzooi.", "gloss": {"Je vous en prie": "please, do", "suivez-moi": "follow me", "suggestion du chef": "chef's special"}}, {"who": "you", "fr": "Merci. Je vous ai appelés tantôt pour signaler que je suis allergique aux crevettes — c'est bien noté ?", "en": "Thank you. I called you earlier today to flag that I'm allergic to prawns — has that been noted?", "gloss": {"tantôt": "earlier today (Belgian French; France: tout à l'heure)", "signaler": "to report, flag", "allergique": "allergic", "noté": "written down"}, "accept": ["merci je vous ai appelés tantôt pour signaler que je suis allergique aux crevettes c'est bien noté", "merci je vous ai appelés tantôt pour dire que je suis allergique aux crevettes c'est bien noté", "merci j'ai téléphoné tantôt pour signaler que je suis allergique aux crevettes", "merci je vous ai téléphoné cet après-midi pour signaler mon allergie aux crevettes c'est bien noté", "merci j'ai appelé tantôt au sujet de mon allergie aux crevettes est-ce que c'est noté", "merci je suis allergique aux crevettes je vous ai appelés tantôt pour le signaler"]}, {"who": "waiter", "fr": "Ah, je n'étais pas au courant, mais je le signale en cuisine. Vous voulez que je vérifie les plats un par un ?", "en": "Ah, I wasn't aware, but I'll tell the kitchen. Would you like me to check the dishes one by one?", "gloss": {"au courant": "aware, informed", "vérifie": "check", "un par un": "one by one"}}, {"who": "you", "fr": "Volontiers. Est-ce que les carbonnades peuvent contenir des traces de fruits de mer ? Et les frites, elles sont cuites dans la même friteuse que les croquettes ?", "en": "Gladly. Can the carbonnades contain traces of shellfish? And the chips — are they fried in the same fryer as the croquettes?", "gloss": {"Volontiers": "gladly", "traces": "traces", "friteuse": "deep fryer", "croquettes": "croquettes"}, "accept": ["volontiers est-ce que les carbonnades peuvent contenir des traces de fruits de mer et les frites elles sont cuites dans la même friteuse que les croquettes", "volontiers est-ce que les carbonnades peuvent contenir des traces de fruits de mer", "oui merci est-ce que les carbonnades contiennent des traces de fruits de mer et les frites sont cuites dans la même friteuse que les croquettes", "avec plaisir est-ce qu'il peut y avoir des traces de crevettes dans les carbonnades", "volontiers merci est-ce que les frites sont cuites dans la même friteuse que les croquettes", "oui s'il vous plaît est-ce que les carbonnades peuvent contenir des fruits de mer et les frites sont dans la même friteuse"]}, {"who": "waiter", "fr": "Les carbonnades, non, c'est du bœuf à la bière. Pour la friteuse, je vais me renseigner, mais je crois qu'elle est partagée.", "en": "The carbonnades, no, it's beef in beer. For the fryer, I'll go and find out, but I think it's shared.", "gloss": {"me renseigner": "find out", "partagée": "shared"}}, {"who": "you", "fr": "Alors je préférerais une salade à la place des frites, ce sera plus prudent.", "en": "Then I'd rather have a salad instead of the chips, that'll be safer.", "gloss": {"je préférerais": "I would rather", "à la place de": "instead of", "prudent": "cautious, safe"}, "accept": ["alors je préférerais une salade à la place des frites ce sera plus prudent", "alors je préférerais une salade à la place des frites", "dans ce cas je préfère une salade à la place des frites", "alors je vais prendre une salade au lieu des frites ce sera plus prudent", "alors est-ce que je peux avoir une salade à la place des frites", "je préférerais une salade plutôt que des frites ce sera plus prudent"]}, {"who": "waiter", "fr": "Très bien. Et comme entrée ? Le potage du jour est une crème de chicons.", "en": "Very good. And as a starter? The soup of the day is a cream of chicory.", "gloss": {"entrée": "starter", "potage": "soup", "chicons": "chicory (Belgian French; France: endives)"}}, {"who": "you", "fr": "Une crème de chicons pour moi, et un verre de rouge, le vin de la maison. Mon collègue prendra la suggestion du chef.", "en": "A cream of chicory for me, and a glass of red, the house wine. My colleague will have the chef's special.", "gloss": {"vin de la maison": "house wine", "prendra": "will have"}, "accept": ["une crème de chicons pour moi et un verre de rouge le vin de la maison mon collègue prendra la suggestion du chef", "une crème de chicons pour moi et un verre de vin rouge de la maison mon collègue prendra la suggestion du chef", "pour moi une crème de chicons et un verre de rouge mon collègue prend la suggestion du chef", "je prends la crème de chicons et un verre de vin de la maison et mon collègue la suggestion du chef", "une crème de chicons et un verre de rouge maison s'il vous plaît et pour mon collègue la suggestion du chef", "pour moi la crème de chicons avec un verre de rouge et pour mon collègue le waterzooi"]}, {"who": "waiter", "fr": "Voilà, s'il vous plaît. Une crème de chicons avec des crevettes grises, c'est notre présentation habituelle.", "en": "Here you go. A cream of chicory with grey shrimp, that's how we normally present it.", "gloss": {"s'il vous plaît": "here you go (Belgian use when handing something over)", "crevettes grises": "grey North Sea shrimp", "habituelle": "usual"}}, {"who": "you", "fr": "Attendez, il y a un malentendu : j'avais précisé que j'étais allergique aux crevettes. Je ne peux pas y toucher.", "en": "Wait, there's a misunderstanding: I had specified that I was allergic to prawns. I can't touch it.", "gloss": {"malentendu": "misunderstanding", "j'avais précisé": "I had specified", "y toucher": "touch it"}, "accept": ["attendez il y a un malentendu j'avais précisé que j'étais allergique aux crevettes je ne peux pas y toucher", "attendez il y a un malentendu j'avais précisé que j'étais allergique aux crevettes", "excusez-moi il y a un malentendu j'avais dit que j'étais allergique aux crevettes je ne peux pas manger ça", "attention j'avais précisé que j'étais allergique aux crevettes je ne peux pas y toucher", "il y a une erreur j'avais signalé mon allergie aux crevettes je ne peux pas manger cette assiette", "attendez j'avais précisé mon allergie aux crevettes je ne peux pas prendre ce plat"]}, {"who": "waiter", "fr": "Je suis vraiment désolé, c'est ma faute, je n'ai pas transmis l'information. Je vous le remplace tout de suite par un autre potage.", "en": "I'm really sorry, it's my fault, I didn't pass the information on. I'll replace it right away with another soup.", "gloss": {"ma faute": "my fault", "transmis": "passed on", "remplace": "am replacing"}}, {"who": "you", "fr": "Merci. Ce n'est pas la peine de vous presser, mais vérifiez bien avec la cuisine cette fois-ci.", "en": "Thank you. There's no need to rush, but do check with the kitchen this time.", "gloss": {"Ce n'est pas la peine": "there's no need", "vous presser": "to hurry", "cette fois-ci": "this time"}, "accept": ["merci ce n'est pas la peine de vous presser mais vérifiez bien avec la cuisine cette fois-ci", "merci ce n'est pas la peine de vous presser mais vérifiez avec la cuisine cette fois", "merci prenez votre temps mais vérifiez bien avec la cuisine cette fois-ci", "merci ce n'est pas grave mais vérifiez bien en cuisine cette fois-ci", "merci beaucoup mais vérifiez bien avec la cuisine cette fois", "d'accord merci ce n'est pas la peine de vous presser mais vérifiez cette fois-ci"]}, {"who": "waiter", "fr": "C'est noté. Et je vous offre les cafés, pour le dérangement.", "en": "Noted. And the coffees are on me, for the inconvenience.", "gloss": {"je vous offre": "I'll give you free of charge", "dérangement": "inconvenience"}}, {"who": "you", "fr": "C'est très aimable. Nous prendrons l'addition ensuite, et nous paierons séparément si cela ne vous dérange pas.", "en": "That's very kind. We'll take the bill afterwards, and we'll pay separately if you don't mind.", "gloss": {"aimable": "kind", "séparément": "separately", "si cela ne vous dérange pas": "if you don't mind"}, "accept": ["c'est très aimable nous prendrons l'addition ensuite et nous paierons séparément si cela ne vous dérange pas", "c'est très aimable merci nous prendrons l'addition ensuite et nous paierons séparément", "merci c'est très gentil on prendra l'addition après et on paiera séparément si ça ne vous dérange pas", "c'est très aimable merci est-ce qu'on pourra payer séparément", "merci beaucoup nous voudrions l'addition ensuite et payer séparément si possible", "c'est très aimable nous paierons séparément si cela ne vous dérange pas"]}, {"who": "waiter", "fr": "Bien sûr. Voici l'addition : cent nonante-quatre euros au total, service et TVA compris.", "en": "Of course. Here's the bill: a hundred and ninety-four euros in total, service and VAT included.", "gloss": {"nonante": "ninety (Belgian French; France: quatre-vingt-dix)", "TVA": "VAT", "compris": "included"}}, {"who": "you", "fr": "Je me permets de vous signaler une erreur : nous n'avons pris qu'un seul apéritif, et il y en a deux sur l'addition.", "en": "May I point out a mistake: we only had one aperitif, and there are two on the bill.", "gloss": {"Je me permets de": "may I, I'll take the liberty of", "n'avons pris qu'": "only had", "apéritif": "aperitif"}, "accept": ["je me permets de vous signaler une erreur nous n'avons pris qu'un seul apéritif et il y en a deux sur l'addition", "je me permets de vous signaler une erreur nous n'avons pris qu'un apéritif et il y en a deux", "excusez-moi il y a une erreur nous n'avons pris qu'un seul apéritif et il y en a deux sur l'addition", "je crois qu'il y a une erreur nous avons pris un seul apéritif pas deux", "il y a une erreur sur l'addition nous n'avons commandé qu'un apéritif", "je me permets de vous signaler qu'il y a deux apéritifs sur l'addition alors que nous n'en avons pris qu'un"]}, {"who": "waiter", "fr": "Vous avez tout à fait raison, je rectifie. Cela fait cent quatre-vingt-quatre euros. Vous réglez comment ?", "en": "You're quite right, I'll correct it. That comes to a hundred and eighty-four euros. How are you paying?", "gloss": {"rectifie": "am correcting", "Vous réglez comment": "how are you paying"}}, {"who": "you", "fr": "Par Bancontact, et il me faudrait une facture au nom de la société, avec le numéro de TVA, pour ma note de frais.", "en": "By Bancontact, and I'd need an invoice in the company's name, with the VAT number, for my expense claim.", "gloss": {"facture": "VAT invoice", "note de frais": "expense claim"}, "accept": ["par bancontact et il me faudrait une facture au nom de la société avec le numéro de tva pour ma note de frais", "par bancontact et il me faudrait une facture au nom de la société avec le numéro de tva", "je paie par bancontact et j'aurais besoin d'une facture au nom de la société avec le numéro de tva", "par bancontact et est-ce que je peux avoir une facture au nom de la société pour ma note de frais", "par bancontact s'il vous plaît et une facture avec le numéro de tva de la société", "je règle par bancontact et il me faut une facture au nom de mon employeur avec le numéro de tva"]}], "exercises": [{"id": "ex-restaurant-pro-B1-01", "level": "B1", "pos": "verb", "fr": "préciser", "en": "to specify", "format": "cloze", "q": "J'avais pourtant ___ mon allergie au moment de la réservation.", "options": ["précisé", "prévenu", "présenté", "prétendu"], "a": 0, "trap": "prétendu — 'claimed', which would suggest you were making it up", "expl": "All four past participles. Note the pluperfect: « j'avais précisé » puts your warning before their mistake."}, {"id": "ex-restaurant-pro-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "le chèque-repas", "en": "the meal voucher", "format": "collocation", "q": "What is the maximum value of a Belgian chèque-repas since 1 January 2026?", "options": ["10 € par jour presté", "8 € par jour presté", "6,91 € par jour presté", "10 € par semaine"], "a": 0, "trap": "8 € — the ceiling everyone quotes, correct until the end of 2025", "expl": "Since January 2026: 10 € maximum, made up of at most 8,91 € from the employer and at least 1,09 € withheld from the employee's net pay.", "note": "Belgian institution. France's nearest equivalent is « le titre-restaurant »."}, {"id": "ex-restaurant-pro-B1-03", "level": "B1", "pos": "verb", "fr": "retirer", "en": "to take off a bill", "format": "cloze", "q": "Est-ce que vous pouvez ___ ce plat de l'addition ? Nous ne l'avons pas commandé.", "options": ["retirer", "rembourser", "reprendre", "récupérer"], "a": 0, "trap": "rembourser — refunding, which only applies once you have already paid", "expl": "All four infinitives. Before payment: retirer de l'addition, or rectifier l'addition. After: se faire rembourser."}, {"id": "ex-restaurant-pro-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "la facture", "en": "the invoice", "format": "collocation", "q": "Your employer will reimburse the dinner. Which document do you need?", "options": ["Une facture au nom de la société avec le numéro de TVA.", "L'addition détaillée avec les plats.", "Le ticket du terminal Bancontact.", "Une copie de la carte."], "a": 0, "trap": "the itemised addition looks official and will still be refused", "expl": "Only an invoice naming the company and its BE VAT number supports a Belgian expense claim. Ask before you pay."}, {"id": "ex-restaurant-pro-B1-05", "level": "B1", "pos": "expr", "fr": "je me permets de", "en": "may I point out", "format": "fr2en", "options": ["I'll take the liberty of / may I", "I allow you to", "I give myself permission not to", "I am permitted to"], "a": 0, "trap": "reading « me permets » as granting permission to the other person", "expl": "« Je me permets de vous signaler… » is the polite Belgian and French office formula for raising a problem."}, {"id": "ex-restaurant-pro-B1-06", "level": "B1", "pos": "adj", "fr": "tiède", "en": "lukewarm", "format": "en2fr", "options": ["tiède", "tendre", "torride", "timide"], "a": 0, "trap": "tendre — 'tender', which is a compliment about the same steak", "expl": "All four masculine adjectives. « Mon plat est tiède » is a complaint; « ma viande est tendre » is praise."}, {"id": "ex-restaurant-pro-B1-07", "level": "B1", "pos": "noun", "gender": "f", "fr": "la cuisson", "en": "the doneness", "format": "fr2en", "options": ["how well the meat is cooked", "the kitchen", "the cooking pot", "the cooked dish"], "a": 0, "trap": "la cuisine — the kitchen; the two nouns come from the same verb and mean different things", "expl": "« Quelle cuisson ? — À point. » Answer on the scale, not with a temperature."}, {"id": "ex-restaurant-pro-B1-08", "level": "B1", "pos": "adv", "fr": "tantôt", "en": "earlier today (Belgian French)", "format": "collocation", "q": "In Brussels, « Je vous ai appelé tantôt » means:", "options": ["I called you earlier today.", "I call you from time to time.", "I'll call you shortly.", "I called you long ago."], "a": 0, "trap": "'from time to time' — the standard French value of « tantôt… tantôt… »", "expl": "Belgian « tantôt » points to another moment of the same day, before or after now. Context tells you which.", "note": "Belgian French. In France say « tout à l'heure » for both directions."}, {"id": "ex-restaurant-pro-B1-09", "level": "B1", "pos": "noun", "gender": "f", "fr": "la contamination croisée", "en": "cross-contamination", "format": "cloze", "q": "Le risque de contamination ___ vient de la friteuse partagée.", "options": ["croisée", "directe", "générale", "alimentaire"], "a": 0, "trap": "alimentaire — 'food contamination', true but not the technical phrase for a shared fryer", "expl": "All four feminine adjectives. In practice, ask the concrete question about the fryer rather than using the term."}, {"id": "ex-restaurant-pro-B1-10", "level": "B1", "pos": "verb", "fr": "arrondir", "en": "to round up", "format": "cloze", "q": "L'addition fait cent quatre-vingt-quatre euros : on ___ à cent nonante ?", "options": ["arrondit", "partage", "ajoute", "compte"], "a": 0, "trap": "partage — splitting, a different operation being discussed at the same table", "expl": "All four third-person verbs. Rounding up is the Belgian tip; there is no percentage involved.", "note": "« cent nonante » = 190. France: cent quatre-vingt-dix."}, {"id": "ex-restaurant-pro-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "le malentendu", "en": "the misunderstanding", "format": "en2fr", "options": ["le malentendu", "le mécontentement", "le mensonge", "le malaise"], "a": 0, "trap": "le mensonge — a lie, which is what you are carefully NOT accusing anyone of", "expl": "All four masculine. « Il y a eu un malentendu » lets the restaurant fix the problem without admitting bad faith."}, {"id": "ex-restaurant-pro-B1-12", "level": "B1", "pos": "noun", "gender": "f", "fr": "la TVA", "en": "VAT", "format": "fr2en", "options": ["value added tax", "the tourist tax", "the service charge", "the corporation tax"], "a": 0, "trap": "le service — the other thing printed as « compris » at the bottom of the menu", "expl": "Pronounced té-vé-a. In Belgian restaurants: 12 % on food eaten in, 21 % on drinks — both already inside the printed price."}, {"id": "ex-restaurant-pro-B1-13", "level": "B1", "pos": "verb", "fr": "remplacer", "en": "to replace", "format": "en2fr", "options": ["remplacer", "replacer", "déplacer", "emplacer"], "a": 0, "trap": "replacer — to put back where it was; the prefix changes everything and « emplacer » does not exist as a verb", "expl": "All four look like verbs of the same family. « Vous pouvez me le remplacer ? » is what you say when a dish is wrong."}, {"id": "ex-restaurant-pro-B1-14", "level": "B1", "pos": "expr", "fr": "à la place de", "en": "instead of", "format": "cloze", "q": "Je voudrais une salade ___ des frites.", "options": ["à la place", "au lieu", "en place", "à la façon"], "a": 0, "trap": "au lieu — « au lieu de » is right before a verb, not before a noun in this pattern", "expl": "« à la place de » + noun; « au lieu de » + verb: « au lieu de commander des frites »."}]},
  "trip-A2": {"slug": "trip", "level": "A2", "title": "Acheter un billet pour l'étranger", "place": "Guichet international, gare de Bruxelles-Midi", "register": "vous", "registerNote": "Vous at every railway counter, in both directions. SNCB staff say vous to passengers and expect it back; the queue behind you makes the exchange short, not familiar.", "vocab": [{"id": "fvc-trip-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le guichet", "en": "the ticket window", "format": "fr2en", "options": ["the ticket window", "the waiting room", "the ticket machine", "the platform gate"], "a": 0, "trap": "le distributeur — the machine; a guichet always has a human behind it", "expl": "At Bruxelles-Midi the international counter is signposted « billets internationaux ». « au guichet » = at the counter."}, {"id": "fvc-trip-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le billet", "en": "the ticket (train, plane)", "format": "fr2en", "options": ["a train or plane ticket", "a metro or bus ticket", "a till receipt", "a banknote only"], "a": 0, "trap": "le ticket — used for the metro, the bus and the till slip; trains take « un billet »", "expl": "SNCB and Eurostar sell « des billets ». STIB sells « un ticket » or loads your MOBIB card. « un billet » is also a banknote."}, {"id": "fvc-trip-A2-03", "level": "A2", "pos": "adj", "fr": "simple", "en": "single, one-way", "format": "cloze", "q": "Vous voulez un aller ___ ou un aller-retour ?", "options": ["simple", "seul", "unique", "direct"], "a": 0, "trap": "direct — a real word about trains, but it describes the route, not the ticket", "expl": "All four are masculine adjectives that fit after « aller ». One way = un aller simple; return = un aller-retour; « direct » describes the route, not the ticket."}, {"id": "fvc-trip-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'aller-retour", "en": "the return ticket", "format": "en2fr", "options": ["l'aller-retour", "le retour simple", "le trajet double", "le va-et-vient"], "a": 0, "trap": "le va-et-vient — a real phrase for coming and going, never a ticket", "expl": "All four masculine. « Un aller-retour Bruxelles-Paris, s'il vous plaît. » Plural: des allers-retours."}, {"id": "fvc-trip-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la place", "en": "the seat", "format": "fr2en", "options": ["the reserved seat", "the town square", "the room available", "the position in a queue"], "a": 0, "trap": "la place also means a town square (la Grand-Place) and space in general — three meanings, one word", "expl": "« une place côté fenêtre » = a window seat. « Il n'y a plus de place » = there's no room left."}, {"id": "fvc-trip-A2-06", "level": "A2", "pos": "noun", "gender": "f", "fr": "la voiture", "en": "the carriage", "format": "fr2en", "options": ["the carriage of a train", "the car you drive", "the freight wagon", "the driver's cab"], "a": 0, "trap": "le wagon — in French that is a goods wagon; passengers travel in « une voiture »", "expl": "Your ticket says « voiture 12, place 65 ». Yes, it is the same word as the car you park."}, {"id": "fvc-trip-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "le quai", "en": "the platform", "format": "en2fr", "options": ["le quai", "le trottoir", "le seuil", "le palier"], "a": 0, "trap": "le trottoir — the pavement in the street outside", "expl": "All four masculine. « le quai » is the physical platform; the number announced is usually « la voie »."}, {"id": "fvc-trip-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la voie", "en": "the track / platform number", "format": "collocation", "q": "Which is the normal Belgian station announcement?", "options": ["Le train partira de la voie 12.", "Le train partira du quai 12.", "Le train partira de la ligne 12.", "Le train partira de la plateforme 12."], "a": 0, "trap": "« quai » feels right because it is the platform you stand on — but the number belongs to the track", "expl": "SNCB announces « voie » (spoor in Dutch). The physical platform is « le quai », and one quai often serves two voies.", "note": "Belgian and French practice alike, but bilingual Brussels announcements alternate voie / spoor, so learn both."}, {"id": "fvc-trip-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'horaire", "en": "the timetable", "format": "fr2en", "options": ["the timetable", "the clock time", "the opening hours only", "the hourly rate"], "a": 0, "trap": "l'heure — the time of day; l'horaire is the whole schedule", "expl": "« Vous avez les horaires du dimanche ? » Also « l'horaire de travail » — a work schedule."}, {"id": "fvc-trip-A2-10", "level": "A2", "pos": "noun", "gender": "f", "fr": "la correspondance", "en": "the connection", "format": "fr2en", "options": ["the onward connection", "the letters you exchange", "the matching seat", "the ticket office"], "a": 0, "trap": "'correspondence' in the letter-writing sense — the same French word does both jobs", "expl": "« Vous avez une correspondance à Lille. » The metro uses it too: « correspondance ligne 2 »."}, {"id": "fvc-trip-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le trajet", "en": "the journey / route", "format": "fr2en", "options": ["the journey from A to B", "a long holiday trip", "the route map", "the fare"], "a": 0, "trap": "le voyage — the trip as an experience; « le trajet » is the practical run between two points", "expl": "« Le trajet dure une heure vingt-deux. » Your daily commute is « le trajet domicile-travail »."}, {"id": "fvc-trip-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le voyage", "en": "the trip", "format": "en2fr", "options": ["le voyage", "le trajet", "le déplacement", "le parcours"], "a": 0, "trap": "le trajet — the leg you travel; « le voyage » is the whole trip", "expl": "All four masculine. « Bon voyage ! » is what the person at the counter says as you leave."}, {"id": "fvc-trip-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "la classe", "en": "the travel class", "format": "cloze", "q": "Vous voyagez en première ou en seconde ___ ?", "options": ["classe", "voiture", "place", "catégorie"], "a": 0, "trap": "voiture — the carriage, which is numbered, not ranked", "expl": "All four feminine nouns fit. Belgium and France say « seconde classe », not « deuxième classe », on trains."}, {"id": "fvc-trip-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "la réduction", "en": "the discount", "format": "fr2en", "options": ["a reduction in price", "a shrinking of the train", "a refund", "a free upgrade"], "a": 0, "trap": "le remboursement — a refund of money already paid", "expl": "« Vous avez droit à une réduction ? » Since October 2025 SNCB fares run by distance, with percentage discounts off-peak and for frequent travellers."}, {"id": "fvc-trip-A2-15", "level": "A2", "pos": "noun", "gender": "f", "fr": "la grève", "en": "the strike", "format": "fr2en", "options": ["a strike", "a demonstration", "a public holiday", "a maintenance closure"], "a": 0, "trap": "la manifestation — a demonstration, which often happens on the same day but is a different thing", "expl": "« Il y a une grève en France jeudi. » Belgian rail strikes are announced days ahead with « un service minimum »."}, {"id": "fvc-trip-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le retard", "en": "the delay", "format": "collocation", "q": "Which sentence says the train is running late?", "options": ["Le train a du retard.", "Le train est en retard sur moi.", "Le train fait du retard.", "Le train prend en retard."], "a": 0, "trap": "« être en retard » is right for people — « je suis en retard » — but a train « a du retard »", "expl": "People are late: je suis en retard. Trains and flights have delay: le train a vingt minutes de retard."}, {"id": "fvc-trip-A2-17", "level": "A2", "pos": "noun", "gender": "m", "fr": "le remboursement", "en": "the refund", "format": "cloze", "q": "En cas d'annulation du train, vous avez droit au ___.", "options": ["remboursement", "renseignement", "règlement", "rangement"], "a": 0, "trap": "le règlement — the rules, or the act of paying; not getting your money back", "expl": "All four are masculine nouns in -ment. « demander le remboursement » = to claim a refund. The verb is « rembourser »."}, {"id": "fvc-trip-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'accompagnateur de train", "en": "the train conductor", "format": "fr2en", "options": ["the on-board conductor who checks tickets", "the train driver", "the station master", "the platform assistant"], "a": 0, "trap": "le conducteur — in Belgium that is the driver at the front, not the person checking your ticket", "expl": "SNCB's official title is « accompagnateur de train ». Everyday speech still says « le contrôleur ».", "note": "Belgian usage. In France you hear « le contrôleur » or « le chef de bord »."}, {"id": "fvc-trip-A2-19", "level": "A2", "pos": "noun", "gender": "f", "fr": "la pièce d'identité", "en": "proof of identity", "format": "en2fr", "options": ["la pièce d'identité", "la pièce de rechange", "la pièce jointe", "la pièce de théâtre"], "a": 0, "trap": "la pièce jointe — an email attachment; « pièce » has a whole family of meanings", "expl": "All four feminine. « une pièce d'identité » covers your carte d'identité or your passeport."}, {"id": "fvc-trip-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le passeport", "en": "the passport", "format": "collocation", "q": "You are travelling by train from Bruxelles-Midi. When do you need a passport rather than an ID card?", "options": ["Pour Londres, parce que le Royaume-Uni n'est pas dans Schengen.", "Pour Paris, parce que c'est l'étranger.", "Pour Amsterdam, parce qu'il faut passer une frontière.", "Pour Cologne, parce que c'est en Allemagne."], "a": 0, "trap": "'abroad means passport' — inside Schengen your Belgian ID card is enough", "expl": "Paris, Amsterdam and Cologne: carte d'identité. London by Eurostar: passport, and border checks at Bruxelles-Midi before boarding."}, {"id": "fvc-trip-A2-21", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bagage à main", "en": "the hand luggage", "format": "fr2en", "options": ["hand luggage", "checked luggage", "the luggage rack", "the luggage trolley"], "a": 0, "trap": "les bagages en soute — the hold luggage on a plane", "expl": "Trains have no weight limit worth worrying about; Eurostar asks for two bags plus one small one per person."}, {"id": "fvc-trip-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "le sac à dos", "en": "the backpack", "format": "en2fr", "options": ["le sac à dos", "le sac à main", "le sac de couchage", "le sac plastique"], "a": 0, "trap": "le sac à main — a handbag; the two are built the same way and mean different things", "expl": "All four masculine. Built as sac + à + use: sac à dos, sac à main, sac à provisions."}, {"id": "fvc-trip-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le distributeur", "en": "the ticket machine", "format": "fr2en", "options": ["a self-service machine", "the ticket office", "the distributor of a company", "the conveyor belt"], "a": 0, "trap": "the same word covers cash machines and drinks machines — « un distributeur de billets » is the cash point", "expl": "In a station « un distributeur » sells tickets; on the street the same word means an ATM. Context does the work."}, {"id": "fvc-trip-A2-24", "level": "A2", "pos": "noun", "gender": "f", "fr": "la gare", "en": "the railway station", "format": "cloze", "q": "Le train part de la ___ de Bruxelles-Midi à vingt heures treize.", "options": ["gare", "station", "arrêt", "halte"], "a": 0, "trap": "la station — right for the metro (station De Brouckère), wrong for a mainline station", "expl": "Trains: la gare. Metro: la station. Bus and tram: l'arrêt. Brussels has three big ones: Midi, Central, Nord."}, {"id": "fvc-trip-A2-25", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'aéroport", "en": "the airport", "format": "collocation", "q": "Your low-cost flight leaves from « Brussels South Charleroi ». Where is that?", "options": ["À Charleroi, à environ 50 km de Bruxelles.", "Au sud de Bruxelles, à 10 minutes du centre.", "À Zaventem, la deuxième aérogare.", "À Bruxelles-Midi, au-dessus de la gare."], "a": 0, "trap": "the name « Brussels South » is designed to make you think it is in Brussels", "expl": "Brussels Airport is at Zaventem, 20 minutes by train from Bruxelles-Midi. Charleroi is an hour away by shuttle bus.", "note": "Belgian reality worth knowing before you book a cheap flight."}, {"id": "fvc-trip-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "le vol", "en": "the flight", "format": "fr2en", "options": ["the flight", "the volume", "the will", "the flight of stairs"], "a": 0, "trap": "« le vol » also means a theft — « on m'a volé mon sac » — so the word does double duty", "expl": "« Mon vol part à six heures. » A stolen bag and a scheduled flight really are the same noun."}, {"id": "fvc-trip-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "la douane", "en": "customs", "format": "fr2en", "options": ["customs", "the tax office", "the border police", "the duty-free shop"], "a": 0, "trap": "la police des frontières — passport control, which is a separate desk from customs", "expl": "Inside Schengen there is normally neither. For the Eurostar to London you pass « le contrôle des passeports » at Bruxelles-Midi."}, {"id": "fvc-trip-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "la frontière", "en": "the border", "format": "en2fr", "options": ["la frontière", "la limite", "la bordure", "la barrière"], "a": 0, "trap": "la limite — a limit or boundary in the abstract sense", "expl": "All four feminine. « la frontière franco-belge ». Crossing it on the train, you will notice nothing at all."}, {"id": "fvc-trip-A2-29", "level": "A2", "pos": "verb", "fr": "partir", "en": "to leave / depart", "format": "cloze", "q": "Le train ___ à vingt heures treize, voie 4.", "options": ["part", "sort", "quitte", "laisse"], "a": 0, "trap": "quitte — « quitter » always needs an object: « le train quitte la gare »", "expl": "All four are third-person verbs. partir = to leave, no object needed. quitter = to leave something."}, {"id": "fvc-trip-A2-30", "level": "A2", "pos": "verb", "fr": "arriver", "en": "to arrive", "format": "collocation", "q": "Which is right?", "options": ["Le train arrive à Paris-Nord à vingt et une heures trente-cinq.", "Le train arrive en Paris-Nord.", "Le train arrive sur Paris-Nord.", "Le train arrive dans Paris-Nord."], "a": 0, "trap": "« sur Paris » is heard in French media and is criticised as sloppy; at a counter, say « à »", "expl": "arriver à + city or station. « en » is for feminine countries: arriver en France."}, {"id": "fvc-trip-A2-31", "level": "A2", "pos": "verb", "fr": "changer", "en": "to change (trains)", "format": "cloze", "q": "Il faut ___ à Lille-Europe, vous avez vingt minutes.", "options": ["changer", "descendre", "attendre", "monter"], "a": 0, "trap": "descendre — you do get off, but « changer » is the word for the whole operation", "expl": "All four are infinitives after « il faut ». « un train direct, sans changement » is the phrase to ask for."}, {"id": "fvc-trip-A2-32", "level": "A2", "pos": "verb", "fr": "descendre", "en": "to get off", "format": "fr2en", "options": ["to get off a train", "to get on a train", "to go down a street", "to take luggage down"], "a": 0, "trap": "descendre also means to go down and to take something down — the train sense needs « de »", "expl": "« Je descends à Anvers. » Opposite: « monter dans le train ». Both take être in the passé composé when intransitive."}, {"id": "fvc-trip-A2-33", "level": "A2", "pos": "verb", "fr": "valider", "en": "to validate", "format": "collocation", "q": "What do you do with your SNCB train ticket before boarding at Bruxelles-Midi?", "options": ["Rien — vous montez et vous le présentez à bord.", "Vous le compostez dans une machine jaune.", "Vous le faites tamponner au guichet.", "Vous le scannez au portique de sortie."], "a": 0, "trap": "the yellow validation machine, which belongs to France and to older memories", "expl": "Belgian trains have no validating machines: you board and show the ticket to the accompagnateur. Only the metro is validated, on the MOBIB reader.", "note": "Belgian practice. France had yellow composteurs for decades; SNCF removed them in 2023."}, {"id": "fvc-trip-A2-34", "level": "A2", "pos": "verb", "fr": "échanger", "en": "to exchange", "format": "cloze", "q": "Est-ce que je peux ___ mon billet si je rate le train ?", "options": ["échanger", "changer", "rembourser", "annuler"], "a": 0, "trap": "changer — you change trains, but you exchange a ticket; the verbs are not interchangeable here", "expl": "All four infinitives after « je peux ». « un billet échangeable » is the flexible fare; the cheap one is « non échangeable »."}, {"id": "fvc-trip-A2-35", "level": "A2", "pos": "verb", "fr": "rembourser", "en": "to refund", "format": "en2fr", "options": ["rembourser", "récupérer", "regretter", "renoncer"], "a": 0, "trap": "récupérer — to get something back, but not money from a company", "expl": "All four infinitives. « Le billet n'est pas remboursable » is the sentence to listen for before you pay."}, {"id": "fvc-trip-A2-36", "level": "A2", "pos": "verb", "fr": "imprimer", "en": "to print", "format": "fr2en", "options": ["to print", "to borrow", "to press down", "to impress someone"], "a": 0, "trap": "emprunter — to borrow; the two verbs look alike and are constantly swapped", "expl": "« Je dois l'imprimer ? — Non, le QR code sur le GSM suffit. » The printout is « un billet papier »."}, {"id": "fvc-trip-A2-37", "level": "A2", "pos": "adj", "fr": "direct", "en": "direct, without changes", "format": "cloze", "q": "Est-ce qu'il y a un train ___ pour Amsterdam ?", "options": ["direct", "droit", "rapide", "immédiat"], "a": 0, "trap": "droit — 'straight' in space, never 'direct' about a route", "expl": "All four masculine adjectives. « un train direct » = no changes; « sans changement » says the same thing."}, {"id": "fvc-trip-A2-38", "level": "A2", "pos": "adj", "fr": "valable", "en": "valid", "format": "fr2en", "options": ["valid", "valuable", "brave", "worth doing"], "a": 0, "trap": "'valuable' — that is « de valeur » or « précieux »", "expl": "« Le billet est valable un an. » For a passport: « valable jusqu'au 12 mars 2029 »."}, {"id": "fvc-trip-A2-39", "level": "A2", "pos": "adj", "fr": "obligatoire", "en": "compulsory", "format": "cloze", "q": "Sur l'Eurostar, la réservation est ___ : on ne peut pas monter sans place.", "options": ["obligatoire", "possible", "gratuite", "facultative"], "a": 0, "trap": "facultative — 'optional', its exact opposite, and the word printed on other services", "expl": "All four feminine adjectives agreeing with « réservation ». Eurostar and TGV: obligatoire. Belgian domestic trains: none at all."}, {"id": "fvc-trip-A2-40", "level": "A2", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "cloze", "q": "L'aller-retour vous revient à ___-neuf euros en seconde classe.", "options": ["nonante", "septante", "quarante", "cinquante"], "a": 0, "trap": "septante — the other Belgian number; 79 and 99 are one syllable apart in speech", "expl": "nonante-neuf = 99. Belgians say septante and nonante but keep quatre-vingts for 80.", "note": "Belgian French. France says quatre-vingt-dix-neuf."}, {"id": "fvc-trip-A2-41", "level": "A2", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile (Belgian French)", "format": "collocation", "q": "The clerk asks how you want your ticket. Which answer is natural in Brussels?", "options": ["Sur mon GSM, avec le QR code.", "Sur mon cellulaire, avec le QR code.", "Sur mon mobile, avec le QR code.", "Sur mon appareil, avec le QR code."], "a": 0, "trap": "« mobile » is understood but is not the Belgian default word", "expl": "GSM is what Belgian forms, staff and friends all say. In France the same sentence would use « portable ».", "note": "Belgian French. France: portable. Quebec: cellulaire."}, {"id": "fvc-trip-A2-42", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'Eurostar", "en": "the Eurostar", "format": "collocation", "q": "Which is true of trains from Bruxelles-Midi to Paris in 2026?", "options": ["Ils s'appellent Eurostar : la marque Thalys a disparu en 2023.", "Ils s'appellent Thalys : Eurostar ne va qu'à Londres.", "Ils s'appellent TGV Belgique.", "Ils s'appellent InterCity international."], "a": 0, "trap": "Thalys — the name everybody still uses out of habit, and the one on old guidebooks", "expl": "Thalys merged into Eurostar and the red trains were rebranded on 1 October 2023. Same trains, same route, one brand.", "note": "Belgian reality: say Eurostar at the counter and nobody will correct you; say Thalys and they will understand anyway."}, {"id": "fvc-trip-A2-43", "level": "A2", "pos": "noun", "gender": "f", "fr": "la SNCB", "en": "Belgian railways", "format": "fr2en", "options": ["the Belgian national railway company", "the Brussels metro operator", "the French national railway company", "the international ticket agency"], "a": 0, "trap": "la SNCF — the French one, one letter away", "expl": "SNCB in French, NMBS in Dutch, the same company. Brussels metro, tram and bus are STIB in French, MIVB in Dutch.", "note": "Belgian institution. Every Brussels sign carries both language versions."}, {"id": "fvc-trip-A2-44", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'heure de pointe", "en": "the rush hour", "format": "en2fr", "options": ["l'heure de pointe", "l'heure creuse", "l'heure d'été", "l'heure supplémentaire"], "a": 0, "trap": "l'heure creuse — the opposite, the quiet period when tickets are cheaper", "expl": "All four feminine. Since October 2025 SNCB prices are lower « en heures creuses » — outside 06:00–09:00 and 16:00–19:00 on weekdays."}, {"id": "fvc-trip-A2-45", "level": "A2", "pos": "expr", "fr": "en seconde", "en": "in second class", "format": "cloze", "q": "Je voyage ___ seconde, c'est moins cher.", "options": ["en", "à", "dans", "par"], "a": 0, "trap": "à — « à la seconde » means 'this very instant', which is a different sentence entirely", "expl": "« en première », « en seconde », « en classe affaires ». Belgian and French trains both say seconde, not deuxième."}, {"id": "fvc-trip-A2-46", "level": "A2", "pos": "expr", "fr": "bon voyage", "en": "have a good trip", "format": "fr2en", "options": ["have a good trip", "safe journey home", "enjoy your holiday", "see you on the train"], "a": 0, "trap": "« bonnes vacances » — for a holiday; « bon voyage » is for the journey itself", "expl": "The counter clerk will say it as you take your ticket. Answer « merci, à vous aussi » if they look like they are finishing their shift."}], "phrases": [{"id": "ph-trip-A2-01", "fr": "Bonjour, je voudrais un aller-retour pour Paris, s'il vous plaît.", "en": "Hello, I'd like a return to Paris, please.", "note": "« un aller-retour pour Paris », not « à Paris ». The destination takes pour on a ticket."}, {"id": "ph-trip-A2-02", "fr": "Je pars vendredi soir et je reviens dimanche en fin d'après-midi.", "en": "I'm leaving Friday evening and coming back Sunday late afternoon.", "note": "Give both legs at once — it halves the exchange. « en fin d'après-midi » = late afternoon."}, {"id": "ph-trip-A2-03", "fr": "Est-ce qu'il y a un train direct, sans changement ?", "en": "Is there a direct train, with no changes?", "note": "Brussels–Paris and Brussels–Amsterdam are direct. Further south you will change at Paris or Lille."}, {"id": "ph-trip-A2-04", "fr": "À quelle heure est-ce que le train arrive à Paris-Nord ?", "en": "What time does the train get into Paris-Nord?", "note": "arriver à + station. Eurostar takes about 1 h 25 from Bruxelles-Midi."}, {"id": "ph-trip-A2-05", "fr": "C'est un peu tôt pour moi. Vous avez quelque chose après dix-neuf heures ?", "en": "That's a bit early for me. Have you got anything after seven p.m.?", "note": "The 24-hour clock at every Belgian counter: dix-neuf heures, not sept heures du soir."}, {"id": "ph-trip-A2-06", "fr": "Combien coûte l'aller-retour en seconde classe ?", "en": "How much is the return in second class?", "note": "« en seconde » is enough on its own. Prices swing from 39 € to 180 € depending on how early you book."}, {"id": "ph-trip-A2-07", "fr": "Est-ce qu'il y a un tarif moins cher à un autre horaire ?", "en": "Is there a cheaper fare at another time?", "note": "Always worth asking: the fare depends on the train, not on the day you buy it."}, {"id": "ph-trip-A2-08", "fr": "Est-ce que le billet est remboursable ?", "en": "Is the ticket refundable?", "note": "The cheap Eurostar fares are neither refundable nor exchangeable. Ask before you pay, not after."}, {"id": "ph-trip-A2-09", "fr": "Et si je rate le train, qu'est-ce qui se passe ?", "en": "And if I miss the train, what happens?", "note": "« rater le train » = to miss it. « manquer le train » works too and sounds slightly more formal."}, {"id": "ph-trip-A2-10", "fr": "Est-ce que la réservation est obligatoire ?", "en": "Is a seat reservation compulsory?", "note": "Eurostar and TGV: yes, always. Belgian domestic trains: never — you just get on."}, {"id": "ph-trip-A2-11", "fr": "Je voudrais une place côté fenêtre, si c'est possible.", "en": "I'd like a window seat, if possible.", "note": "« côté fenêtre » or « côté couloir ». Also « dans le sens de la marche » — facing the direction of travel."}, {"id": "ph-trip-A2-12", "fr": "Est-ce que je dois imprimer le billet ?", "en": "Do I have to print the ticket?", "note": "Usually not: the QR code on your GSM is enough for SNCB and Eurostar alike."}, {"id": "ph-trip-A2-13", "fr": "Est-ce que ma carte d'identité suffit pour Paris ?", "en": "Is my ID card enough for Paris?", "note": "Inside Schengen, yes. For London by Eurostar you need a passport and you pass border control before boarding."}, {"id": "ph-trip-A2-14", "fr": "Le train part de quelle voie ?", "en": "Which platform does the train leave from?", "note": "Belgian announcements say « voie », the track number. The platform you stand on is « le quai »."}, {"id": "ph-trip-A2-15", "fr": "Il faut être là combien de temps à l'avance ?", "en": "How long beforehand do you have to be there?", "note": "Eurostar closes boarding 10 minutes before departure at Bruxelles-Midi — earlier for London, because of border control."}, {"id": "ph-trip-A2-16", "fr": "Est-ce qu'il y a une grève en France ce jour-là ?", "en": "Is there a strike in France that day?", "note": "A real question, not a joke: French strikes routinely cut Brussels–Paris services and are announced in advance."}, {"id": "ph-trip-A2-17", "fr": "Je peux payer par Bancontact ?", "en": "Can I pay by Bancontact?", "note": "Yes at every SNCB counter and machine. Some machines are card-only, with no cash accepted at all."}, {"id": "ph-trip-A2-18", "fr": "Est-ce que vous pouvez me l'envoyer sur mon GSM ?", "en": "Can you send it to my mobile?", "note": "GSM is the Belgian word for a mobile phone; France says portable. The e-ticket arrives by email or in the SNCB app."}, {"id": "ph-trip-A2-19", "fr": "Excusez-moi, je n'ai pas bien compris. Vous pouvez répéter, s'il vous plaît ?", "en": "Sorry, I didn't quite understand. Could you repeat that, please?", "note": "The most useful sentence at any counter. « plus lentement » if you need it slower — nobody will mind."}, {"id": "ph-trip-A2-20", "fr": "Merci beaucoup, bonne journée !", "en": "Thank you very much, have a good day!", "note": "You will often get « bon voyage ! » back. « bonne journée » before about 17:00, « bonne soirée » after."}], "dialogue": [{"who": "clerk", "fr": "Bonjour monsieur. C'est pour quelle destination ?", "en": "Good morning sir. Which destination is it for?", "gloss": {"destination": "destination"}}, {"who": "you", "fr": "Bonjour. Je voudrais un aller-retour pour Paris, s'il vous plaît.", "en": "Hello. I'd like a return to Paris, please.", "gloss": {"aller-retour": "return ticket"}, "accept": ["bonjour je voudrais un aller-retour pour paris s'il vous plaît", "bonjour je voudrais un aller-retour pour paris", "bonjour un aller-retour pour paris s'il vous plaît", "bonjour j'aimerais un aller-retour pour paris s'il vous plaît", "bonjour je cherche un aller-retour pour paris", "bonjour c'est pour un aller-retour bruxelles paris"]}, {"who": "clerk", "fr": "Très bien. Vous partez quand, et vous revenez quand ?", "en": "Very good. When are you leaving, and when are you coming back?", "gloss": {"partez": "are leaving", "revenez": "are coming back"}}, {"who": "you", "fr": "Je pars vendredi soir et je reviens dimanche en fin d'après-midi.", "en": "I'm leaving Friday evening and coming back Sunday late afternoon.", "gloss": {"en fin d'après-midi": "late in the afternoon"}, "accept": ["je pars vendredi soir et je reviens dimanche en fin d'après-midi", "je pars vendredi soir et je rentre dimanche en fin d'après-midi", "départ vendredi soir et retour dimanche en fin d'après-midi", "je pars vendredi soir et je reviens dimanche soir", "vendredi soir pour l'aller et dimanche en fin d'après-midi pour le retour", "je voudrais partir vendredi soir et revenir dimanche en fin d'après-midi"]}, {"who": "clerk", "fr": "J'ai un Eurostar à dix-huit heures cinquante-deux, arrivée à Paris-Nord à vingt heures dix-sept.", "en": "I have a Eurostar at six fifty-two p.m., arriving at Paris-Nord at eight seventeen.", "gloss": {"Eurostar": "the red Brussels–Paris train, called Thalys until 2023", "arrivée": "arrival"}}, {"who": "you", "fr": "C'est un peu tôt pour moi. Est-ce que vous avez quelque chose après dix-neuf heures trente ?", "en": "That's a bit early for me. Do you have anything after seven thirty?", "gloss": {"tôt": "early", "quelque chose": "something"}, "accept": ["c'est un peu tôt pour moi est-ce que vous avez quelque chose après dix-neuf heures trente", "c'est un peu tôt est-ce que vous avez quelque chose après dix-neuf heures trente", "c'est trop tôt pour moi vous avez un train plus tard", "c'est un peu tôt est-ce qu'il y a un train après dix-neuf heures trente", "je préférerais plus tard est-ce que vous avez quelque chose après dix-neuf heures trente", "c'est un peu tôt pour moi vous auriez quelque chose plus tard dans la soirée"]}, {"who": "clerk", "fr": "Alors, vingt heures treize, arrivée à vingt et une heures trente-cinq. C'est un train direct, sans changement.", "en": "In that case, eight thirteen p.m., arriving at nine thirty-five. It's a direct train, no changes.", "gloss": {"direct": "direct", "sans changement": "with no changes"}}, {"who": "you", "fr": "Parfait. Et combien coûte l'aller-retour en seconde classe ?", "en": "Perfect. And how much is the return in second class?", "gloss": {"coûte": "costs", "seconde classe": "second class"}, "accept": ["parfait et combien coûte l'aller-retour en seconde classe", "parfait combien coûte l'aller-retour en seconde classe", "très bien et combien coûte l'aller-retour en seconde", "parfait c'est combien l'aller-retour en seconde classe", "d'accord et quel est le prix de l'aller-retour en seconde", "parfait combien ça coûte l'aller-retour en seconde classe"]}, {"who": "clerk", "fr": "Cent nonante-neuf euros. Mais si vous partez à six heures du matin, l'aller ne coûte que trente-neuf euros.", "en": "One hundred and ninety-nine euros. But if you leave at six in the morning, the outward leg is only thirty-nine euros.", "gloss": {"nonante": "ninety (Belgian French; France: quatre-vingt-dix)", "ne coûte que": "only costs"}}, {"who": "you", "fr": "Six heures, c'est trop tôt. Je préfère le train de vingt heures treize. Est-ce que le billet est remboursable ?", "en": "Six is too early. I prefer the eight thirteen train. Is the ticket refundable?", "gloss": {"trop tôt": "too early", "remboursable": "refundable"}, "accept": ["six heures c'est trop tôt je préfère le train de vingt heures treize est-ce que le billet est remboursable", "six heures c'est trop tôt je préfère le train de vingt heures treize", "c'est trop tôt je prends le train de vingt heures treize est-ce que le billet est remboursable", "je préfère le train du soir est-ce que le billet est remboursable", "six heures c'est vraiment trop tôt je prends celui de vingt heures treize il est remboursable", "non c'est trop tôt je préfère vingt heures treize est-ce qu'on peut le rembourser"]}, {"who": "clerk", "fr": "Non, à ce tarif il n'est ni remboursable ni échangeable. Pour un billet flexible, c'est cinquante euros de plus.", "en": "No, at that fare it's neither refundable nor exchangeable. For a flexible ticket it's fifty euros more.", "gloss": {"échangeable": "exchangeable", "flexible": "flexible", "ni remboursable ni échangeable": "neither … nor"}}, {"who": "you", "fr": "Je prends le tarif normal, ce n'est pas grave. Est-ce que la réservation est obligatoire ?", "en": "I'll take the normal fare, it doesn't matter. Is a seat reservation compulsory?", "gloss": {"tarif": "fare", "obligatoire": "compulsory"}, "accept": ["je prends le tarif normal ce n'est pas grave est-ce que la réservation est obligatoire", "je prends le tarif normal est-ce que la réservation est obligatoire", "d'accord je prends le tarif normal la réservation est obligatoire", "ce n'est pas grave je prends le billet normal est-ce que la réservation est obligatoire", "je vais prendre le tarif normal et est-ce que la place est réservée", "je prends celui-là est-ce que la réservation est obligatoire"]}, {"who": "clerk", "fr": "Oui, sur l'Eurostar la place est toujours réservée. Vous préférez côté fenêtre ou côté couloir ?", "en": "Yes, on Eurostar the seat is always reserved. Do you prefer a window or an aisle seat?", "gloss": {"place": "seat", "côté fenêtre": "window side", "côté couloir": "aisle side"}}, {"who": "you", "fr": "Côté fenêtre, s'il vous plaît. Et est-ce que ma carte d'identité suffit pour Paris ?", "en": "Window, please. And is my ID card enough for Paris?", "gloss": {"suffit": "is enough"}, "accept": ["côté fenêtre s'il vous plaît et est-ce que ma carte d'identité suffit pour paris", "côté fenêtre s'il vous plaît et est-ce que ma carte d'identité suffit", "côté fenêtre et est-ce que ma carte d'identité suffit pour paris", "une place côté fenêtre s'il vous plaît est-ce que la carte d'identité suffit", "côté fenêtre merci et j'ai besoin d'un passeport ou la carte d'identité suffit", "côté fenêtre s'il vous plaît est-ce qu'il me faut un passeport pour paris"]}, {"who": "clerk", "fr": "Pour Paris oui, on est dans Schengen. Pour Londres, il vous faudrait un passeport et un contrôle avant l'embarquement.", "en": "For Paris yes, we're inside Schengen. For London you'd need a passport and a check before boarding.", "gloss": {"Schengen": "the Schengen area", "il vous faudrait": "you would need", "embarquement": "boarding"}}, {"who": "you", "fr": "D'accord. Est-ce que je dois imprimer le billet, ou est-ce que le QR code sur mon GSM suffit ?", "en": "All right. Do I have to print the ticket, or is the QR code on my mobile enough?", "gloss": {"imprimer": "to print", "GSM": "mobile phone (Belgian French; France: portable)"}, "accept": ["d'accord est-ce que je dois imprimer le billet ou est-ce que le qr code sur mon gsm suffit", "est-ce que je dois imprimer le billet ou le qr code sur mon gsm suffit", "d'accord est-ce que je dois imprimer le billet", "est-ce qu'il faut imprimer le billet ou je peux le garder sur mon gsm", "d'accord le qr code sur mon gsm suffit ou je dois imprimer le billet", "est-ce que je peux garder le billet sur mon gsm"]}, {"who": "clerk", "fr": "Le QR code suffit. Et en Belgique, on ne valide pas le billet : vous montez et vous le présentez à l'accompagnateur.", "en": "The QR code is enough. And in Belgium we don't validate the ticket: you get on and show it to the conductor.", "gloss": {"valide": "validate", "montez": "get on", "accompagnateur": "on-board conductor (SNCB's official term)"}}, {"who": "you", "fr": "Très bien. Je paie par Bancontact. Le train part de quelle voie ?", "en": "Very good. I'll pay by Bancontact. Which platform does the train leave from?", "gloss": {"voie": "track / platform number"}, "accept": ["très bien je paie par bancontact le train part de quelle voie", "très bien je paie par bancontact et le train part de quelle voie", "je paie par bancontact et de quelle voie part le train", "d'accord je paie par bancontact le train part de quelle voie", "je règle par bancontact et le train part de quelle voie", "je paie par bancontact merci et c'est quelle voie"]}, {"who": "clerk", "fr": "En général voie 3 ou 4, mais vérifiez les écrans le jour même. Soyez là vingt minutes à l'avance.", "en": "Usually track 3 or 4, but check the screens on the day. Be there twenty minutes early.", "gloss": {"écrans": "screens", "le jour même": "on the day itself", "à l'avance": "in advance"}}, {"who": "you", "fr": "C'est noté, merci beaucoup. Bonne journée !", "en": "Got it, thank you very much. Have a good day!", "gloss": {"C'est noté": "noted, got it"}, "accept": ["c'est noté merci beaucoup bonne journée", "c'est noté merci beaucoup et bonne journée", "merci beaucoup bonne journée", "d'accord c'est noté merci bonne journée", "parfait merci beaucoup bonne journée à vous", "très bien merci bonne journée"]}], "exercises": [{"id": "ex-trip-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le billet", "en": "the ticket", "format": "cloze", "q": "J'ai acheté mon ___ de train sur l'application de la SNCB.", "options": ["billet", "ticket", "reçu", "abonnement"], "a": 0, "trap": "ticket — right for the STIB metro, wrong for a train", "expl": "All four masculine. Trains take « un billet »; metro, bus and till slips take « un ticket »."}, {"id": "ex-trip-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "la voiture", "en": "the carriage", "format": "fr2en", "options": ["the carriage you sit in", "the goods wagon", "the driver's cab", "the restaurant trolley"], "a": 0, "trap": "le wagon — reserved for freight in French, though English 'wagon' pushes you the other way", "expl": "Your Eurostar ticket reads « voiture 12, place 65 ». Same word as the car in your street."}, {"id": "ex-trip-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "le retard", "en": "the delay", "format": "collocation", "q": "Which sentence is correct?", "options": ["Le train a vingt minutes de retard.", "Le train est vingt minutes en retard.", "Le train fait vingt minutes de retard.", "Le train tient vingt minutes de retard."], "a": 0, "trap": "« est en retard » is the version you use about yourself, and it transfers badly to trains", "expl": "Trains have delay: avoir X minutes de retard. People are late: je suis en retard."}, {"id": "ex-trip-A2-04", "level": "A2", "pos": "verb", "fr": "valider", "en": "to validate", "format": "collocation", "q": "Where DO you have to validate in Brussels?", "options": ["Sur le lecteur MOBIB du métro et du tram.", "Dans une machine jaune sur le quai du train.", "Au guichet international avant de monter.", "Nulle part, jamais."], "a": 0, "trap": "'nowhere ever' overcorrects: the metro really does need validating, every trip", "expl": "STIB: tap your MOBIB card at every boarding, including transfers. SNCB trains: no validation at all.", "note": "Belgian practice. France's yellow composteurs were scrapped in 2023."}, {"id": "ex-trip-A2-05", "level": "A2", "pos": "noun", "gender": "m", "fr": "le vol", "en": "the flight", "format": "fr2en", "options": ["the flight", "the volume", "the flight of stairs", "the volunteer"], "a": 0, "trap": "« le vol » also means a theft; the airline sense and the crime share one noun", "expl": "« Mon vol part de Zaventem à six heures. » « On m'a volé mon GSM » uses the same root."}, {"id": "ex-trip-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'aéroport", "en": "the airport", "format": "collocation", "q": "Which airport is actually in the Brussels region?", "options": ["Aucun des deux : Zaventem est en Flandre, Charleroi en Wallonie.", "Zaventem, qui est une commune bruxelloise.", "Charleroi, rebaptisé Brussels South.", "Les deux, puisqu'ils s'appellent Brussels."], "a": 0, "trap": "the names Brussels Airport and Brussels South are both marketing, not geography", "expl": "Zaventem is in Flemish Brabant, 20 min by train from Bruxelles-Midi. Charleroi is 55 km away, an hour by shuttle.", "note": "Belgian reality: budget flights leave from Charleroi and the transfer time is real."}, {"id": "ex-trip-A2-07", "level": "A2", "pos": "verb", "fr": "échanger", "en": "to exchange", "format": "cloze", "q": "Ce tarif ne permet pas d'___ le billet après le départ.", "options": ["échanger", "changer", "annuler", "acheter"], "a": 0, "trap": "changer — you change trains; you exchange a ticket", "expl": "All four infinitives after « permet d' ». « un billet échangeable » costs more and lets you move to another train."}, {"id": "ex-trip-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la gare", "en": "the station", "format": "cloze", "q": "Je descends à la ___ de Bruxelles-Central, pas à Midi.", "options": ["gare", "station", "halte", "borne"], "a": 0, "trap": "station — correct for the metro under the same building, wrong for the railway station above it", "expl": "All four feminine. Bruxelles-Central is « une gare »; De Brouckère is « une station de métro »."}, {"id": "ex-trip-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la SNCB", "en": "Belgian railways", "format": "collocation", "q": "Match the operator to the service.", "options": ["SNCB = les trains ; STIB = le métro bruxellois", "SNCB = le métro ; STIB = les trains", "SNCB = les trains ; SNCF = le métro bruxellois", "STIB = les trains ; MIVB = le métro"], "a": 0, "trap": "MIVB is simply STIB in Dutch — the same operator, not a second one", "expl": "SNCB/NMBS runs the trains; STIB/MIVB runs Brussels metro, tram and bus; SNCF is the French railway.", "note": "Belgian institutions: every name in Brussels comes in two languages."}, {"id": "ex-trip-A2-10", "level": "A2", "pos": "adj", "fr": "obligatoire", "en": "compulsory", "format": "en2fr", "options": ["obligatoire", "facultatif", "nécessaire", "réservé"], "a": 0, "trap": "facultatif — 'optional', the exact opposite and printed on the same kind of notice", "expl": "All four masculine adjectives. « La réservation est obligatoire sur l'Eurostar. »"}, {"id": "ex-trip-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la correspondance", "en": "the connection", "format": "en2fr", "options": ["la correspondance", "la connexion", "la liaison", "la jonction"], "a": 0, "trap": "la connexion — used for internet and electricity, not for changing trains", "expl": "All four feminine. « Vous avez une correspondance à Lille, vingt minutes d'attente. »"}, {"id": "ex-trip-A2-12", "level": "A2", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "fr2en", "options": ["ninety", "ninety-nine", "nineteen", "seventy"], "a": 0, "trap": "septante — the other word Belgium keeps; hearing them apart at speed takes practice", "expl": "« cent nonante-neuf euros » = 199 €. Counters say the total once and fast.", "note": "Belgian French. France says quatre-vingt-dix."}, {"id": "ex-trip-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'Eurostar", "en": "the Eurostar", "format": "fr2en", "options": ["the red high-speed train to Paris, Amsterdam and London", "the London service only", "the Belgian domestic express", "the German ICE service"], "a": 0, "trap": "'Eurostar means London' — true until Thalys was absorbed in October 2023", "expl": "One brand now covers Brussels–Paris, Brussels–Amsterdam, Brussels–Cologne and Brussels–London.", "note": "Belgian reality since 2023: the name Thalys no longer exists, but everyone still says it."}, {"id": "ex-trip-A2-14", "level": "A2", "pos": "verb", "fr": "imprimer", "en": "to print", "format": "en2fr", "options": ["imprimer", "emprunter", "empêcher", "employer"], "a": 0, "trap": "emprunter — 'to borrow'; it looks like 'imprimer' and turns up in the same beginner lists", "expl": "All four infinitives. « Je dois l'imprimer ? — Non, gardez le QR code sur votre GSM. »"}]},
  "trip-B1": {"slug": "trip", "level": "B1", "title": "Un préavis de grève sur un voyage déjà réservé", "place": "Guichet international, gare de Bruxelles-Midi", "register": "vous", "registerNote": "Vous at the counter throughout, including when you push back. The clerk has no power over the strike, so the tone that works is vous plus the conditional: « est-ce qu'il serait possible de… », « il faudrait que je… ». Firmness here comes from precision, not from familiarity.", "vocab": [{"id": "fvc-trip-B1-01", "level": "B1", "pos": "noun", "gender": "m", "fr": "le préavis de grève", "en": "the strike notice", "format": "fr2en", "options": ["formal notice that a strike may happen", "the strike itself", "the list of cancelled trains", "the union's demands"], "a": 0, "trap": "la grève — a préavis is only the warning, and it is often lifted before the date", "expl": "Belgian rail strikes are announced by a préavis filed days in advance, so the date is known long before anything stops running."}, {"id": "fvc-trip-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "le service garanti", "en": "the guaranteed service", "format": "collocation", "q": "What does « le service garanti » mean on an SNCB strike day?", "options": ["Une partie des trains circule, annoncée à l'avance.", "Tous les trains circulent normalement.", "Aucun train ne circule.", "Les billets sont automatiquement remboursés."], "a": 0, "trap": "assuming 'guaranteed' means everything runs — it guarantees a published reduced plan, nothing more", "expl": "Since the 2017 law, SNCB publishes a reduced strike timetable a couple of days ahead. Check it before you travel, not on the day.", "note": "Belgian term. France calls its equivalent « le service minimum »."}, {"id": "fvc-trip-B1-03", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'indemnisation", "en": "the compensation payment", "format": "en2fr", "options": ["l'indemnisation", "l'indemnité de licenciement", "l'imposition", "l'inscription"], "a": 0, "trap": "l'indemnité de licenciement — redundancy pay; same root, employment context", "expl": "All four feminine. EU rail rules: 25 % of the fare back for a 60–119 minute delay, 50 % from 120 minutes."}, {"id": "fvc-trip-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'attestation de retard", "en": "the delay certificate", "format": "fr2en", "options": ["a written proof that your train was late", "a warning that the train will be late", "a delay in issuing your ticket", "an apology letter"], "a": 0, "trap": "le justificatif d'absence — the note you give your employer, a different document", "expl": "Ask the accompagnateur or the station office for one on the spot: without it, a compensation claim is much harder."}, {"id": "fvc-trip-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le justificatif", "en": "the supporting document", "format": "cloze", "q": "Joignez tous les ___ à votre demande de remboursement.", "options": ["justificatifs", "documents", "papiers", "certificats"], "a": 0, "trap": "documents — true but vague; « justificatif » is the exact administrative word Belgian forms use", "expl": "All four are masculine plural nouns. « un justificatif de domicile », « un justificatif de paiement » — you will meet this word everywhere."}, {"id": "fvc-trip-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la correspondance garantie", "en": "the protected connection", "format": "collocation", "q": "Your Brussels–Paris and Paris–Milan legs are on two separate tickets. Your first train is late. What are you entitled to?", "options": ["Rien sur le deuxième billet : la correspondance n'est pas garantie.", "Un réacheminement gratuit sur le train suivant.", "Le remboursement automatique des deux billets.", "Une indemnisation de 50 % sur les deux trajets."], "a": 0, "trap": "assuming rail passenger rights follow the journey; they follow the contract, and two tickets are two contracts", "expl": "One through booking = one contract, and the carrier must re-route you. Two separate bookings and the second train is simply missed.", "note": "EU rail rule that applies in Belgium: always ask « c'est un seul billet ? » before you buy two legs."}, {"id": "fvc-trip-B1-07", "level": "B1", "pos": "noun", "gender": "m", "fr": "le réacheminement", "en": "the re-routing", "format": "fr2en", "options": ["being sent on by another route or train", "a refund of the ticket", "a change of platform", "a return to the departure station"], "a": 0, "trap": "le remboursement — money back; réacheminement is being physically got there another way", "expl": "The verb is « réacheminer ». On a delayed through booking you may choose between réacheminement and remboursement."}, {"id": "fvc-trip-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "les frais de dossier", "en": "the booking / admin fee", "format": "fr2en", "options": ["an administrative handling fee", "the file of your booking", "the cost of the ticket itself", "a late-payment penalty"], "a": 0, "trap": "le dossier — the file; « les frais de dossier » is the charge for handling it", "expl": "Always plural. Typically 5–15 € per change at a counter, and often waived when the change is the railway's fault."}, {"id": "fvc-trip-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'itinéraire", "en": "the route", "format": "en2fr", "options": ["l'itinéraire", "le trajet", "le parcours", "le circuit"], "a": 0, "trap": "le trajet — the journey made; l'itinéraire is the route chosen on the map", "expl": "All four masculine. « un itinéraire par Lille » avoids central Paris entirely — worth asking about on a strike day."}, {"id": "fvc-trip-B1-10", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'escale", "en": "the stopover", "format": "fr2en", "options": ["a stopover on the way", "the final destination", "the boarding gate", "an escalator"], "a": 0, "trap": "'escalator' — the shape of the word invites it; that is « un escalator » or « un escalier roulant »", "expl": "Used for flights and boats: « un vol avec escale à Munich ». For trains, say « une correspondance »."}, {"id": "fvc-trip-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "le titre de transport", "en": "the travel document / ticket", "format": "fr2en", "options": ["any valid ticket or pass", "the job title of a driver", "the transport company's licence", "the timetable"], "a": 0, "trap": "reading « titre » as a job title or a book title", "expl": "The formal umbrella term on notices and fines: « Tout voyageur doit être en possession d'un titre de transport valable. »"}, {"id": "fvc-trip-B1-12", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'assurance annulation", "en": "cancellation insurance", "format": "en2fr", "options": ["l'assurance annulation", "l'assurance assistance", "l'assurance bagages", "l'assurance responsabilité"], "a": 0, "trap": "l'assurance assistance — repatriation and medical help, which is a different cover on the same policy sheet", "expl": "All four feminine. It refunds the trip if you cancel for a listed reason — illness, a death, a dismissal — with a doctor's certificate."}, {"id": "fvc-trip-B1-13", "level": "B1", "pos": "noun", "gender": "f", "fr": "la franchise", "en": "the excess (insurance)", "format": "fr2en", "options": ["the part of a claim you pay yourself", "a full refund", "the insurance premium", "a duty-free allowance"], "a": 0, "trap": "'franchise' as a business licence, and « en franchise » meaning duty-free — three meanings, one word", "expl": "« une franchise de 50 € » = the first 50 € of any claim is yours. Check it before you pay for a policy."}, {"id": "fvc-trip-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "les conditions générales", "en": "the terms and conditions", "format": "cloze", "q": "C'est écrit dans les conditions ___ de vente, à l'article 7.", "options": ["générales", "normales", "habituelles", "principales"], "a": 0, "trap": "normales — plausible French, and simply not the fixed legal phrase", "expl": "All four are feminine plural adjectives. « les conditions générales (CG) » is the fixed term; the shorthand is « les CGV »."}, {"id": "fvc-trip-B1-15", "level": "B1", "pos": "noun", "gender": "f", "fr": "la farde", "en": "the folder (Belgian French)", "format": "fr2en", "options": ["a folder or wallet for documents", "a heavy suitcase", "a stack of paperwork", "a filing cabinet"], "a": 0, "trap": "le dossier — the contents; « la farde » is the physical folder they sit in", "expl": "« Je vous mets tout dans une farde. » Everyday Belgian office and school word.", "note": "Belgian French. France says « une chemise » (card folder) or « un classeur » (ring binder); « farde » is not used there."}, {"id": "fvc-trip-B1-16", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'heure creuse", "en": "the off-peak period", "format": "en2fr", "options": ["l'heure creuse", "l'heure de pointe", "l'heure légale", "l'heure d'arrivée"], "a": 0, "trap": "l'heure de pointe — rush hour, the expensive opposite", "expl": "All four feminine. Since the October 2025 fare reform, SNCB prices depend on distance and are lower en heures creuses."}, {"id": "fvc-trip-B1-17", "level": "B1", "pos": "verb", "fr": "reporter", "en": "to postpone", "format": "fr2en", "options": ["to put off to a later date", "to report something to someone", "to bring forward", "to cancel outright"], "a": 0, "trap": "'to report' — the English word sitting inside the French one; that is « signaler » or « rapporter »", "expl": "« Je voudrais reporter mon voyage à dimanche. » To bring it forward is « avancer »."}, {"id": "fvc-trip-B1-18", "level": "B1", "pos": "verb", "fr": "décaler", "en": "to shift (a time)", "format": "cloze", "q": "Est-ce qu'on peut ___ mon départ de deux heures ?", "options": ["décaler", "reculer", "retarder", "supprimer"], "a": 0, "trap": "retarder — it means making something late, which sounds like a fault rather than a choice", "expl": "All four infinitives. « décaler » moves a time in either direction; it is the neutral, practical verb."}, {"id": "fvc-trip-B1-19", "level": "B1", "pos": "verb", "fr": "supprimer", "en": "to cancel (a service)", "format": "collocation", "q": "The board says your train is « supprimé ». What has happened?", "options": ["Le train ne circulera pas du tout.", "Le train partira plus tard.", "Le train partira d'une autre voie.", "Le train est complet."], "a": 0, "trap": "'suppressed' sounds temporary; on a railway board it means the service is off", "expl": "« un train supprimé » is the standard word on SNCB screens and announcements. A late train is « retardé »."}, {"id": "fvc-trip-B1-20", "level": "B1", "pos": "verb", "fr": "réacheminer", "en": "to re-route", "format": "en2fr", "options": ["réacheminer", "rembourser", "renvoyer", "rapatrier"], "a": 0, "trap": "rapatrier — to repatriate someone, which belongs to insurance, not to a rail ticket", "expl": "All four infinitives. « La compagnie doit vous réacheminer par le train suivant » — your right on a single through booking."}, {"id": "fvc-trip-B1-21", "level": "B1", "pos": "verb", "fr": "souscrire", "en": "to take out (a policy)", "format": "cloze", "q": "Vous pouvez ___ une assurance annulation jusqu'à la veille du départ.", "options": ["souscrire", "signer", "acheter", "conclure"], "a": 0, "trap": "signer — you do sign, but « souscrire une assurance » is the fixed verb for taking out cover", "expl": "All four infinitives. « souscrire une assurance / un abonnement / un contrat ». Ending it is « résilier »."}, {"id": "fvc-trip-B1-22", "level": "B1", "pos": "verb", "fr": "résilier", "en": "to terminate (a contract)", "format": "fr2en", "options": ["to end a contract or subscription", "to cancel a single booking", "to resign from a job", "to reschedule"], "a": 0, "trap": "annuler — cancelling a booking; résilier is for ongoing contracts", "expl": "You résilie an insurance policy, a phone contract, a lease; you annule a train ticket or a dinner reservation."}, {"id": "fvc-trip-B1-23", "level": "B1", "pos": "verb", "fr": "prévoir", "en": "to allow for / plan", "format": "cloze", "q": "Il faut ___ au moins une heure pour traverser Paris.", "options": ["prévoir", "prendre", "passer", "profiter"], "a": 0, "trap": "prendre — « prendre une heure » is possible French and means something else: taking an hour off someone", "expl": "All four infinitives after « il faut ». « prévoir » = to plan for, to allow. Noun: « une prévision »."}, {"id": "fvc-trip-B1-24", "level": "B1", "pos": "verb", "fr": "s'y prendre", "en": "to go about it", "format": "fr2en", "options": ["to go about doing something", "to take something with you", "to be caught out", "to take part"], "a": 0, "trap": "prendre on its own — the y and the reflexive change the verb completely", "expl": "« Il faut s'y prendre à l'avance. » = you have to do it in good time. « Je m'y prends mal » = I'm going about it badly."}, {"id": "fvc-trip-B1-25", "level": "B1", "pos": "verb", "fr": "se renseigner", "en": "to find out / enquire", "format": "en2fr", "options": ["se renseigner", "s'inscrire", "s'informer de", "se présenter"], "a": 0, "trap": "s'inscrire — to register or sign up, which is what you do after you have found out", "expl": "All four are reflexive verbs. « Je me renseigne et je vous rappelle » is what a clerk says before disappearing."}, {"id": "fvc-trip-B1-26", "level": "B1", "pos": "verb", "fr": "tenir compte de", "en": "to take into account", "format": "cloze", "q": "Il faut tenir ___ du temps de correspondance à Paris.", "options": ["compte", "conte", "comptes", "calcul"], "a": 0, "trap": "conte — a fairy tale; identical in sound, hopeless in meaning", "expl": "Fixed: « tenir compte de » (singular, no article). « rendre des comptes » is a different expression entirely."}, {"id": "fvc-trip-B1-27", "level": "B1", "pos": "verb", "fr": "emprunter", "en": "to take (a route)", "format": "fr2en", "options": ["to take a particular route or road", "to print", "to lend", "to shorten"], "a": 0, "trap": "prêter — to lend, the mirror verb; and « imprimer » is the printing lookalike", "expl": "Two senses: to borrow money, and to take a route — « emprunter le RER D ». Both are common."}, {"id": "fvc-trip-B1-28", "level": "B1", "pos": "adj", "fr": "échangeable", "en": "exchangeable", "format": "cloze", "q": "Ce billet est ___ moyennant vingt euros de frais.", "options": ["échangeable", "remboursable", "disponible", "valable"], "a": 0, "trap": "remboursable — refundable, a different right and often not granted on the same fare", "expl": "All four adjectives fit. Fares come in three grades: ni l'un ni l'autre, échangeable seulement, ou entièrement flexible."}, {"id": "fvc-trip-B1-29", "level": "B1", "pos": "adj", "fr": "perturbé", "en": "disrupted", "format": "fr2en", "options": ["disrupted, running badly", "cancelled outright", "diverted", "overcrowded"], "a": 0, "trap": "supprimé — cancelled; « perturbé » means the service exists but is a mess", "expl": "« Le trafic sera fortement perturbé jeudi. » The noun is « une perturbation », used for weather too."}, {"id": "fvc-trip-B1-30", "level": "B1", "pos": "adj", "fr": "ferme", "en": "firm, definitive", "format": "fr2en", "options": ["definitive and binding", "closed", "solid to the touch", "strict"], "a": 0, "trap": "« fermé » — closed; one letter and a completely different word", "expl": "« une réservation ferme et définitive » = a booking that cannot be undone. Also « un prix ferme »."}, {"id": "fvc-trip-B1-31", "level": "B1", "pos": "expr", "fr": "en cas de", "en": "in the event of", "format": "cloze", "q": "___ cas de suppression du train, vous êtes remboursé intégralement.", "options": ["En", "Au", "Dans", "Par"], "a": 0, "trap": "Dans — « dans le cas où » exists, but it needs the article and a clause after it", "expl": "« en cas de » + bare noun; « au cas où » + conditional; « dans le cas où » + clause. Three shapes, one idea."}, {"id": "fvc-trip-B1-32", "level": "B1", "pos": "expr", "fr": "au plus tard", "en": "at the latest", "format": "en2fr", "options": ["au plus tard", "au plus tôt", "au maximum", "à la dernière minute"], "a": 0, "trap": "au plus tôt — 'at the earliest', the exact opposite deadline", "expl": "All four adverbial phrases. « La demande doit être introduite trois mois au plus tard après le voyage. »"}, {"id": "fvc-trip-B1-33", "level": "B1", "pos": "expr", "fr": "compte tenu de", "en": "given / in view of", "format": "fr2en", "options": ["given, in view of", "taking account only of money", "on condition that", "as long as"], "a": 0, "trap": "« à condition que » — a condition, where « compte tenu de » simply weighs a fact", "expl": "« Compte tenu de la grève, je vous fais l'échange gratuitement. » Invariable before the noun."}, {"id": "fvc-trip-B1-34", "level": "B1", "pos": "expr", "fr": "faute de quoi", "en": "failing which", "format": "cloze", "q": "Envoyez le formulaire dans les trois mois, ___ de quoi la demande sera refusée.", "options": ["faute", "défaut", "manque", "absence"], "a": 0, "trap": "défaut — « à défaut de quoi » also exists, but the everyday written form is « faute de quoi »", "expl": "Administrative French you will meet in every Belgian letter. Also « sous peine de refus »."}, {"id": "fvc-trip-B1-35", "level": "B1", "pos": "noun", "gender": "m", "fr": "le formulaire", "en": "the form", "format": "en2fr", "options": ["le formulaire", "le format", "le formulaire d'usage", "le formalisme"], "a": 0, "trap": "le format — the size or layout of a document, not the document you fill in", "expl": "All four masculine. « remplir un formulaire en ligne » — the SNCB compensation claim is one of these."}, {"id": "fvc-trip-B1-36", "level": "B1", "pos": "noun", "gender": "m", "fr": "le délai", "en": "the time limit", "format": "fr2en", "options": ["the time allowed or the deadline", "a delay to a train", "a postponement", "a waiting room"], "a": 0, "trap": "'delay' — the false friend that trips up every English speaker; a train delay is « un retard »", "expl": "« dans un délai de trois mois » = within three months. « le délai de correspondance » = the connection time."}, {"id": "fvc-trip-B1-37", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trafic", "en": "rail traffic / services", "format": "collocation", "q": "Which sentence would you actually hear at Bruxelles-Midi?", "options": ["Le trafic sera perturbé toute la journée de jeudi.", "La circulation sera perturbée toute la journée de jeudi.", "Le traffic sera perturbé toute la journée de jeudi.", "Le transport sera perturbé toute la journée de jeudi."], "a": 0, "trap": "« la circulation » is the right word for cars on the road, and the wrong one for trains", "expl": "Rail: « le trafic ferroviaire ». Roads: « la circulation ». And note the French spelling — one f."}, {"id": "fvc-trip-B1-38", "level": "B1", "pos": "noun", "gender": "f", "fr": "la veille", "en": "the day before", "format": "fr2en", "options": ["the day before", "the evening watch", "the eve of a festival only", "the day after"], "a": 0, "trap": "le lendemain — the day after, its mirror image, and the two are learned together and confused for years", "expl": "« la veille du départ » = the day before departure. « l'avant-veille » = two days before."}, {"id": "fvc-trip-B1-39", "level": "B1", "pos": "noun", "gender": "m", "fr": "le lendemain", "en": "the next day", "format": "cloze", "q": "Si le train est supprimé, je partirai le ___ matin.", "options": ["lendemain", "demain", "surlendemain", "matin"], "a": 0, "trap": "demain — « demain matin » exists, but « le demain matin » does not; the article forces « lendemain »", "expl": "demain = tomorrow, from today. le lendemain = the next day, from any point in a story. The article is the giveaway."}, {"id": "fvc-trip-B1-40", "level": "B1", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "La différence de tarif est de ___-cinq euros par personne.", "options": ["septante", "nonante", "soixante", "quatre-vingt"], "a": 0, "trap": "nonante — the other Belgian form; at a counter you get one chance to hear which", "expl": "septante-cinq = 75 €. Ask « Vous pouvez me l'écrire ? » if the total goes past you.", "note": "Belgian French. France says soixante-quinze."}, {"id": "fvc-trip-B1-41", "level": "B1", "pos": "noun", "gender": "f", "fr": "la demande de remboursement", "en": "the refund claim", "format": "collocation", "q": "Which is the correct phrase for lodging a refund claim?", "options": ["introduire une demande de remboursement", "introduire une demande pour remboursement", "faire une demande au remboursement", "poser une demande de remboursement"], "a": 0, "trap": "« poser une demande » sounds plausible and is not the administrative verb", "expl": "Belgian administrative French uses « introduire une demande » — you will meet it again for allowances, permits and appeals.", "note": "Belgian usage. France more often says « déposer une demande »."}, {"id": "fvc-trip-B1-42", "level": "B1", "pos": "noun", "gender": "m", "fr": "le bon de voyage", "en": "the travel voucher", "format": "fr2en", "options": ["a credit note usable on a future trip", "a discount card", "a boarding pass", "a good-value fare"], "a": 0, "trap": "« bon » as the adjective 'good' — here it is the noun for a voucher", "expl": "Railways prefer to give « un bon » rather than money. You can usually insist on cash if the delay meets the EU threshold."}, {"id": "fvc-trip-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "le RER", "en": "the Paris suburban express", "format": "collocation", "q": "You must get from Paris-Nord to Paris-Gare de Lyon on a strike day. What is the sensible plan?", "options": ["Prévoir large : RER D en direct, ou métro, en comptant une heure.", "Compter dix minutes, c'est la porte à côté.", "Prendre un taxi, c'est toujours plus rapide.", "Rester à Paris-Nord, les TGV pour Milan y passent aussi."], "a": 0, "trap": "the ten-minute answer is what the timetable suggests and what a strike destroys", "expl": "RER D links the two stations directly in about ten minutes when it runs. On a disrupted day, allow an hour and buy one through ticket if you can."}, {"id": "fvc-trip-B1-44", "level": "B1", "pos": "verb", "fr": "rater", "en": "to miss (a train)", "format": "en2fr", "options": ["rater", "manquer de", "perdre", "louper"], "a": 0, "trap": "manquer de — with de it means to lack something: « je manque de temps »", "expl": "« rater son train » and the slangier « louper son train » both work. « manquer son train » is the formal version, without de."}, {"id": "fvc-trip-B1-45", "level": "B1", "pos": "noun", "gender": "m", "fr": "le supplément", "en": "the surcharge", "format": "cloze", "q": "Le changement de date est possible moyennant un ___ de vingt euros.", "options": ["supplément", "complément", "règlement", "versement"], "a": 0, "trap": "complément — something that completes; a surcharge is « un supplément »", "expl": "All four masculine. « moyennant » = in return for, and it is the counter's favourite preposition."}, {"id": "fvc-trip-B1-46", "level": "B1", "pos": "expr", "fr": "moyennant", "en": "in return for / for a fee of", "format": "fr2en", "options": ["in return for", "on average", "by means of transport", "in the middle of"], "a": 0, "trap": "'on average' — that is « en moyenne », built on the same root and meaning something else", "expl": "« moyennant supplément », « moyennant finance », « moyennant quoi » — administrative, common, and worth recognising instantly."}], "phrases": [{"id": "ph-trip-B1-01", "fr": "J'ai une réservation pour samedi, Bruxelles-Milan via Paris, au nom de Vasileiadis.", "en": "I have a booking for Saturday, Brussels to Milan via Paris, in the name of Vasileiadis.", "note": "Lead with the date, the route and the name in one sentence — it is exactly what the clerk needs to type."}, {"id": "ph-trip-B1-02", "fr": "J'ai vu qu'il y avait un préavis de grève en France ce jour-là.", "en": "I saw there was a strike notice in France that day.", "note": "The imperfect « il y avait » in reported perception is standard: « j'ai vu qu'il y avait », « on m'a dit qu'il y avait »."}, {"id": "ph-trip-B1-03", "fr": "Est-ce que mon train est maintenu ou est-ce qu'il risque d'être supprimé ?", "en": "Is my train still running or is it likely to be cancelled?", "note": "« maintenu » is the word on the boards for a service that will run. « risquer de » = to be likely to, for bad outcomes only."}, {"id": "ph-trip-B1-04", "fr": "Est-ce que je peux reporter mon voyage au lendemain sans frais ?", "en": "Can I put my trip off to the next day free of charge?", "note": "« sans frais » is the phrase that matters. On a strike day, ask for it explicitly — it is often granted."}, {"id": "ph-trip-B1-05", "fr": "Est-ce que les deux trajets sont sur un seul billet ?", "en": "Are the two legs on a single ticket?", "note": "The single most valuable question of the conversation: one booking gives you re-routing rights, two do not."}, {"id": "ph-trip-B1-06", "fr": "Si je rate ma correspondance à Paris, qu'est-ce qui est prévu ?", "en": "If I miss my connection in Paris, what provision is there?", "note": "« Qu'est-ce qui est prévu ? » makes them state the rule rather than improvise a favour."}, {"id": "ph-trip-B1-07", "fr": "Combien de temps faut-il prévoir entre Paris-Nord et Gare de Lyon ?", "en": "How much time do you have to allow between Paris-Nord and Gare de Lyon?", "note": "« prévoir » = to allow for. Ten minutes on the RER on a good day; allow an hour on a disrupted one."}, {"id": "ph-trip-B1-08", "fr": "Est-ce qu'il existe un itinéraire qui évite Paris ?", "en": "Is there a route that avoids Paris?", "note": "Worth asking on a French strike day — via Lille or via Germany and Switzerland, depending on the destination."}, {"id": "ph-trip-B1-09", "fr": "Quels sont les frais de dossier pour un changement de date ?", "en": "What's the admin fee for a change of date?", "note": "« les frais de dossier » is always plural. Ask what is waived « compte tenu de la grève »."}, {"id": "ph-trip-B1-10", "fr": "En cas de retard de plus de deux heures, quelle indemnisation est prévue ?", "en": "In the event of a delay of more than two hours, what compensation applies?", "note": "EU rail rules: 25 % of the fare back for 60–119 minutes, 50 % from 120 minutes. Knowing the figures changes the answer you get."}, {"id": "ph-trip-B1-11", "fr": "Est-ce que vous pouvez me donner une attestation de retard ?", "en": "Can you give me a delay certificate?", "note": "Ask on the day, from the accompagnateur or the station desk. It is the document that makes the claim work."}, {"id": "ph-trip-B1-12", "fr": "Dans quel délai faut-il introduire la demande de remboursement ?", "en": "Within what time limit does the refund claim have to be lodged?", "note": "« un délai » is a time limit, not a delay. « introduire une demande » is the Belgian administrative verb."}, {"id": "ph-trip-B1-13", "fr": "Je préférerais être remboursé plutôt que de recevoir un bon de voyage.", "en": "I'd rather be refunded than receive a travel voucher.", "note": "Say it clearly: railways offer vouchers first. Where EU rules apply you are entitled to money."}, {"id": "ph-trip-B1-14", "fr": "Est-ce que ce billet est échangeable, et jusqu'à quand ?", "en": "Is this ticket exchangeable, and until when?", "note": "Two questions in one, and both matter. Many fares are exchangeable only up to the day before departure."}, {"id": "ph-trip-B1-15", "fr": "Est-ce que cela vaut la peine de souscrire une assurance annulation ?", "en": "Is it worth taking out cancellation insurance?", "note": "« valoir la peine de » + infinitive. Ask what the franchise (excess) is before you decide."}, {"id": "ph-trip-B1-16", "fr": "Compte tenu de la situation, est-ce que vous pouvez faire un geste sur les frais ?", "en": "Given the situation, could you do something about the fees?", "note": "« compte tenu de » + noun is the calm way to point at a reason. It works far better than complaining about the strike."}, {"id": "ph-trip-B1-17", "fr": "Vous pouvez me mettre les billets dans une farde, avec les conditions générales ?", "en": "Could you put the tickets in a folder for me, with the terms and conditions?", "note": "« une farde » is Belgian for a document folder; in France you would say « une chemise » or « un classeur »."}, {"id": "ph-trip-B1-18", "fr": "Envoyez-moi la confirmation par mail, je n'ai pas d'imprimante chez moi.", "en": "Send me the confirmation by email, I don't have a printer at home.", "note": "A neat way to ask for everything in writing without sounding like you distrust the person in front of you."}, {"id": "ph-trip-B1-19", "fr": "Si jamais la grève est levée, est-ce que je peux revenir sur ma décision ?", "en": "If the strike is called off, can I go back on my decision?", "note": "« si jamais » = if by any chance. « lever un préavis » is what unions do when negotiations succeed — it happens often."}, {"id": "ph-trip-B1-20", "fr": "Merci d'avoir pris le temps de tout vérifier.", "en": "Thank you for taking the time to check everything.", "note": "« Merci d'avoir » + past infinitive. Counter staff hear complaints all day; this one sentence is remembered."}], "dialogue": [{"who": "clerk", "fr": "Bonjour monsieur, qu'est-ce que je peux faire pour vous ?", "en": "Good morning sir, what can I do for you?", "gloss": {"qu'est-ce que": "what"}}, {"who": "you", "fr": "Bonjour. J'ai une réservation pour samedi, Bruxelles-Milan via Paris, et j'ai vu qu'il y avait un préavis de grève en France ce jour-là.", "en": "Good morning. I have a booking for Saturday, Brussels to Milan via Paris, and I saw there was a strike notice in France that day.", "gloss": {"réservation": "booking", "via": "via, through", "préavis de grève": "strike notice"}, "accept": ["bonjour j'ai une réservation pour samedi bruxelles milan via paris et j'ai vu qu'il y avait un préavis de grève en france ce jour-là", "bonjour j'ai une réservation pour samedi bruxelles milan via paris et il y a un préavis de grève en france ce jour-là", "bonjour j'ai réservé samedi pour milan via paris et j'ai vu qu'il y avait un préavis de grève en france", "bonjour j'ai un billet pour milan samedi via paris et j'ai vu qu'il y a une grève annoncée en france", "bonjour je pars samedi à milan via paris et j'ai vu qu'il y avait un préavis de grève", "bonjour j'ai une réservation samedi pour milan et j'ai vu qu'il y avait une grève en france ce jour-là"]}, {"who": "clerk", "fr": "Effectivement. L'Eurostar Bruxelles-Paris est maintenu, mais côté français le trafic sera fortement perturbé. Le TGV pour Milan risque d'être supprimé.", "en": "Indeed. The Brussels–Paris Eurostar is running, but on the French side services will be badly disrupted. The TGV to Milan may well be cancelled.", "gloss": {"Effectivement": "indeed", "maintenu": "still running", "perturbé": "disrupted", "supprimé": "cancelled"}}, {"who": "you", "fr": "Est-ce que les deux trajets sont sur un seul billet ? C'est important pour la correspondance.", "en": "Are the two legs on a single ticket? That matters for the connection.", "gloss": {"trajets": "legs, journeys", "correspondance": "connection"}, "accept": ["est-ce que les deux trajets sont sur un seul billet c'est important pour la correspondance", "est-ce que les deux trajets sont sur un seul billet", "est-ce que c'est un seul billet pour les deux trajets c'est important pour la correspondance", "les deux trajets sont sur le même billet", "est-ce que j'ai un seul billet pour les deux trains c'est important pour la correspondance", "est-ce que c'est un billet unique pour les deux trajets"]}, {"who": "clerk", "fr": "Non, malheureusement : vous avez acheté les deux séparément en ligne. Donc si le premier train a du retard, le deuxième n'est pas garanti.", "en": "No, unfortunately: you bought the two separately online. So if the first train is late, the second isn't protected.", "gloss": {"séparément": "separately", "en ligne": "online", "garanti": "guaranteed, protected"}}, {"who": "you", "fr": "Je ne le savais pas. Est-ce qu'il serait possible de tout regrouper sur un seul billet direct ?", "en": "I didn't know that. Would it be possible to put everything together on a single through ticket?", "gloss": {"regrouper": "to put together", "il serait possible": "would it be possible"}, "accept": ["je ne le savais pas est-ce qu'il serait possible de tout regrouper sur un seul billet direct", "je ne le savais pas est-ce qu'il serait possible de tout regrouper sur un seul billet", "je ne savais pas est-ce qu'on peut tout mettre sur un seul billet", "je l'ignorais est-ce qu'il serait possible d'avoir un seul billet pour tout le trajet", "je ne le savais pas est-ce que je peux racheter un billet unique pour les deux trajets", "je ne le savais pas serait-il possible de tout regrouper sur un billet unique"]}, {"who": "clerk", "fr": "Oui, mais il faudrait racheter les deux trajets. Compte tenu de la grève, je vous rembourse les anciens billets sans frais de dossier.", "en": "Yes, but you'd have to rebuy both legs. Given the strike, I'll refund the old tickets with no admin fee.", "gloss": {"racheter": "to buy again", "Compte tenu de": "given, in view of", "frais de dossier": "admin fee"}}, {"who": "you", "fr": "Et quelle serait la différence de prix ? Mon budget est déjà bien entamé.", "en": "And what would the price difference be? My budget is already well stretched.", "gloss": {"différence": "difference", "bien entamé": "well eaten into"}, "accept": ["et quelle serait la différence de prix mon budget est déjà bien entamé", "et quelle serait la différence de prix", "et quelle est la différence de prix mon budget est déjà bien entamé", "et ça coûterait combien de plus", "et quelle serait la différence de tarif entre les deux solutions", "et combien est-ce que ça me coûterait en plus"]}, {"who": "clerk", "fr": "Septante-cinq euros de plus par personne, mais vous êtes couvert pour la correspondance. Et l'aller-retour reste échangeable jusqu'à la veille du départ.", "en": "Seventy-five euros more per person, but you're covered for the connection. And the return stays exchangeable up to the day before departure.", "gloss": {"Septante": "seventy (Belgian French; France: soixante-dix)", "couvert": "covered", "échangeable": "exchangeable", "la veille": "the day before"}}, {"who": "you", "fr": "D'accord, ça vaut la peine. Et si le train est quand même supprimé, quelle indemnisation est prévue ?", "en": "All right, that's worth it. And if the train is cancelled anyway, what compensation applies?", "gloss": {"ça vaut la peine": "it's worth it", "quand même": "all the same, anyway", "indemnisation": "compensation"}, "accept": ["d'accord ça vaut la peine et si le train est quand même supprimé quelle indemnisation est prévue", "d'accord ça vaut la peine et si le train est supprimé quelle indemnisation est prévue", "très bien ça vaut la peine et s'il est quand même supprimé qu'est-ce qui est prévu comme indemnisation", "d'accord je prends et si le train est supprimé j'ai droit à quelle indemnisation", "ça vaut la peine et en cas de suppression du train quelle est l'indemnisation", "d'accord et si jamais le train est supprimé quelle indemnisation est prévue"]}, {"who": "clerk", "fr": "Si le train est supprimé, remboursement intégral ou réacheminement, à votre choix. En cas de retard, c'est vingt-cinq pour cent à partir d'une heure et cinquante pour cent à partir de deux heures.", "en": "If the train is cancelled, full refund or re-routing, your choice. For a delay, it's twenty-five per cent from one hour and fifty per cent from two hours.", "gloss": {"intégral": "full, complete", "réacheminement": "re-routing", "à partir de": "from"}}, {"who": "you", "fr": "Et dans quel délai faut-il introduire la demande de remboursement ?", "en": "And within what time limit does the refund claim have to be lodged?", "gloss": {"délai": "time limit (not 'delay')", "introduire la demande": "to lodge a claim"}, "accept": ["et dans quel délai faut-il introduire la demande de remboursement", "et dans quel délai faut-il introduire la demande", "et j'ai combien de temps pour introduire la demande de remboursement", "et dans quel délai est-ce que je dois faire la demande de remboursement", "et il faut introduire la demande de remboursement dans quel délai", "et jusqu'à quand est-ce que je peux demander le remboursement"]}, {"who": "clerk", "fr": "Trois mois au plus tard, avec le formulaire en ligne et les justificatifs. Demandez une attestation de retard à l'accompagnateur le jour même.", "en": "Three months at the latest, with the online form and the supporting documents. Ask the conductor for a delay certificate on the day.", "gloss": {"au plus tard": "at the latest", "justificatifs": "supporting documents", "attestation de retard": "delay certificate", "accompagnateur": "on-board conductor"}}, {"who": "you", "fr": "C'est noté. Autre chose : combien de temps faut-il prévoir entre Paris-Nord et Gare de Lyon un jour de grève ?", "en": "Noted. Another thing: how much time should I allow between Paris-Nord and Gare de Lyon on a strike day?", "gloss": {"Autre chose": "another thing", "prévoir": "to allow for"}, "accept": ["c'est noté autre chose combien de temps faut-il prévoir entre paris-nord et gare de lyon un jour de grève", "c'est noté combien de temps faut-il prévoir entre paris-nord et gare de lyon un jour de grève", "d'accord et combien de temps faut-il prévoir entre paris nord et gare de lyon", "c'est noté il faut prévoir combien de temps pour aller de paris-nord à gare de lyon", "merci et combien de temps faut-il compter entre paris-nord et gare de lyon un jour de grève", "c'est noté autre chose combien de temps entre paris-nord et gare de lyon"]}, {"who": "clerk", "fr": "Normalement dix minutes en RER D. Un jour de grève, prévoyez large : une heure, et prenez le métro si le RER ne circule pas.", "en": "Normally ten minutes on the RER D. On a strike day, allow plenty: an hour, and take the metro if the RER isn't running.", "gloss": {"RER D": "the direct Paris suburban line between the two stations", "prévoyez large": "allow plenty of time", "circule": "is running"}}, {"who": "you", "fr": "Très bien. Est-ce que cela vaut la peine de souscrire une assurance annulation, ou est-ce que la franchise est trop élevée ?", "en": "Very good. Is it worth taking out cancellation insurance, or is the excess too high?", "gloss": {"souscrire": "to take out (a policy)", "franchise": "excess (the part you pay yourself)", "élevée": "high"}, "accept": ["très bien est-ce que cela vaut la peine de souscrire une assurance annulation ou est-ce que la franchise est trop élevée", "est-ce que cela vaut la peine de souscrire une assurance annulation", "très bien est-ce que ça vaut la peine de prendre une assurance annulation", "est-ce que ça vaut la peine de souscrire une assurance annulation ou la franchise est trop élevée", "et l'assurance annulation ça vaut la peine ou la franchise est trop élevée", "très bien est-ce que vous me conseillez de souscrire une assurance annulation"]}, {"who": "clerk", "fr": "Pour un billet échangeable comme celui-ci, franchement, ce n'est pas indispensable. La franchise est de cinquante euros par personne.", "en": "For an exchangeable ticket like this one, frankly, it isn't essential. The excess is fifty euros per person.", "gloss": {"franchement": "frankly", "indispensable": "essential"}}, {"who": "you", "fr": "Alors je m'en passe. Je paie par Bancontact, et vous pouvez me mettre le tout dans une farde avec les conditions générales ?", "en": "Then I'll do without. I'll pay by Bancontact, and could you put it all in a folder with the terms and conditions?", "gloss": {"je m'en passe": "I'll do without it", "farde": "folder (Belgian French; France: chemise/classeur)", "conditions générales": "terms and conditions"}, "accept": ["alors je m'en passe je paie par bancontact et vous pouvez me mettre le tout dans une farde avec les conditions générales", "alors je m'en passe je paie par bancontact et vous pouvez me mettre tout dans une farde", "dans ce cas je m'en passe je paie par bancontact et vous me mettez tout dans une farde", "alors je ne la prends pas je paie par bancontact et je voudrais les conditions générales", "je m'en passe alors je règle par bancontact et vous pouvez tout mettre dans une farde", "alors je m'en passe je paie par bancontact merci et mettez-moi le tout dans une farde"]}, {"who": "clerk", "fr": "Voilà, s'il vous plaît. Je vous envoie aussi la confirmation par mail. Et si le préavis est levé d'ici jeudi, revenez me voir, on ajustera.", "en": "Here you go. I'll also send you the confirmation by email. And if the strike notice is lifted by Thursday, come back and see me, we'll adjust.", "gloss": {"s'il vous plaît": "here you go (Belgian use when handing something over)", "levé": "lifted, called off", "on ajustera": "we'll adjust"}}, {"who": "you", "fr": "Merci d'avoir pris le temps de tout vérifier. Bonne journée !", "en": "Thank you for taking the time to check everything. Have a good day!", "gloss": {"Merci d'avoir": "thank you for having (+ past infinitive)", "vérifier": "to check"}, "accept": ["merci d'avoir pris le temps de tout vérifier bonne journée", "merci d'avoir pris le temps de tout vérifier", "je vous remercie d'avoir pris le temps de tout vérifier bonne journée", "merci beaucoup d'avoir tout vérifié bonne journée", "merci pour votre aide et pour le temps que vous avez pris bonne journée", "merci d'avoir tout vérifié bonne journée à vous"]}], "exercises": [{"id": "ex-trip-B1-01", "level": "B1", "pos": "noun", "gender": "m", "fr": "le délai", "en": "the time limit", "format": "fr2en", "options": ["a time limit or period allowed", "a delay to a service", "a postponement", "a deadline that has passed"], "a": 0, "trap": "'delay' — the false friend; a train running late has « du retard », not « du délai »", "expl": "« dans un délai de trois mois » = within three months. « le délai de correspondance » = the time between two trains."}, {"id": "ex-trip-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la correspondance garantie", "en": "the protected connection", "format": "collocation", "q": "Why does it matter whether two legs are on one ticket?", "options": ["Un seul billet oblige le transporteur à vous réacheminer.", "Un seul billet coûte toujours moins cher.", "Un seul billet permet de changer de date gratuitement.", "Un seul billet donne droit à une place réservée."], "a": 0, "trap": "the price answer — sometimes true, and beside the point", "expl": "One booking is one contract of carriage: miss the connection through the railway's fault and they must get you there.", "note": "EU rule applied in Belgium — worth asking about every time you combine two operators."}, {"id": "ex-trip-B1-03", "level": "B1", "pos": "verb", "fr": "supprimer", "en": "to cancel a service", "format": "cloze", "q": "Trois trains sur quatre seront ___ jeudi à cause de la grève.", "options": ["supprimés", "retardés", "annulés", "reportés"], "a": 0, "trap": "annulés — correct for a booking you cancel yourself; the railway « supprime » its own trains", "expl": "All four are masculine plural participles. Boards read SUPPRIMÉ for a train that will not run and RETARDÉ for one that is late."}, {"id": "ex-trip-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'indemnisation", "en": "compensation", "format": "collocation", "q": "Your train arrives 2 h 15 late. What are you entitled to under EU rail rules?", "options": ["50 % du prix du billet", "25 % du prix du billet", "100 % du prix du billet", "Un bon de voyage uniquement"], "a": 0, "trap": "25 % — the right figure for the band below, 60 to 119 minutes", "expl": "60–119 minutes: 25 %. From 120 minutes: 50 %. And you can insist on money rather than a voucher."}, {"id": "ex-trip-B1-05", "level": "B1", "pos": "noun", "gender": "f", "fr": "la farde", "en": "the folder (Belgian French)", "format": "en2fr", "options": ["la farde", "la chemise", "la fardeau", "la farce"], "a": 0, "trap": "la chemise — the correct French word for the same object, and a shirt as well", "expl": "Belgian offices and schools run on « des fardes ». Note « le fardeau » (a burden) is masculine and unrelated.", "note": "Belgian French. France: une chemise (card folder) or un classeur (ring binder)."}, {"id": "ex-trip-B1-06", "level": "B1", "pos": "expr", "fr": "compte tenu de", "en": "given, in view of", "format": "cloze", "q": "___ tenu de la grève, je ne vous facture pas les frais de dossier.", "options": ["Compte", "Comptes", "Conte", "Compter"], "a": 0, "trap": "Conte — a fairy tale; identical sound, and the spelling is the whole test", "expl": "Invariable set phrase before a noun. « Compte tenu de la situation… » opens half the letters you will receive in Belgium."}, {"id": "ex-trip-B1-07", "level": "B1", "pos": "verb", "fr": "introduire", "en": "to lodge (a claim)", "format": "collocation", "q": "Which is Belgian administrative French for making a claim?", "options": ["introduire une demande", "poser une demande", "mettre une demande", "porter une demande"], "a": 0, "trap": "« déposer » is the French version and is also understood — but Belgian forms say introduire", "expl": "You will meet « introduire une demande » again for allowances, permits, appeals and reimbursements.", "note": "Belgian usage. France more often says « déposer une demande »."}, {"id": "ex-trip-B1-08", "level": "B1", "pos": "noun", "gender": "f", "fr": "la franchise", "en": "the excess", "format": "fr2en", "options": ["the amount you pay yourself on a claim", "the insurance premium", "a duty-free allowance", "a business licence"], "a": 0, "trap": "the duty-free and franchising senses are both real French — but not on an insurance policy", "expl": "« une franchise de 50 € » means a 60 € loss gets you 10 €. Always check it before buying cover."}, {"id": "ex-trip-B1-09", "level": "B1", "pos": "noun", "gender": "f", "fr": "la veille", "en": "the day before", "format": "cloze", "q": "Le billet est échangeable jusqu'à la ___ du départ.", "options": ["veille", "semaine", "journée", "soirée"], "a": 0, "trap": "journée — a plausible feminine noun that says nothing about which day", "expl": "la veille = the day before; le lendemain = the day after; l'avant-veille and le surlendemain go one step further out."}, {"id": "ex-trip-B1-10", "level": "B1", "pos": "verb", "fr": "reporter", "en": "to postpone", "format": "en2fr", "options": ["reporter", "rapporter", "supporter", "transporter"], "a": 0, "trap": "rapporter — to bring back or to report on something; the family of -porter verbs is a minefield", "expl": "All four infinitives. « reporter un voyage à dimanche » = move it later; « avancer » moves it earlier."}, {"id": "ex-trip-B1-11", "level": "B1", "pos": "expr", "fr": "moyennant", "en": "for a fee of", "format": "cloze", "q": "Le changement est possible ___ un supplément de vingt euros.", "options": ["moyennant", "en moyenne", "au moyen", "par moyen"], "a": 0, "trap": "en moyenne — 'on average', built on the same root and used constantly in the wrong slot", "expl": "« moyennant » + noun = in return for. Counters, contracts and estate agents all use it."}, {"id": "ex-trip-B1-12", "level": "B1", "pos": "noun", "gender": "m", "fr": "le service garanti", "en": "the guaranteed service", "format": "fr2en", "options": ["a published reduced timetable on a strike day", "a promise that all trains will run", "a refund guarantee", "a first-class service level"], "a": 0, "trap": "reading 'guaranteed' as 'everything runs' — it guarantees only that a plan is published", "expl": "Introduced by the 2017 Belgian law. Check the SNCB site two days ahead: the strike timetable is published there.", "note": "Belgian term. France says « service minimum »."}, {"id": "ex-trip-B1-13", "level": "B1", "pos": "verb", "fr": "rater", "en": "to miss (a train)", "format": "cloze", "q": "Si je ___ ma correspondance, je serai bloqué à Paris.", "options": ["rate", "manque de", "perds", "quitte"], "a": 0, "trap": "manque de — with de the verb means 'to lack', so the sentence would say you are short of connections", "expl": "rater / louper / manquer son train, all without de. « manquer de temps » is the other verb entirely."}, {"id": "ex-trip-B1-14", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trafic", "en": "rail services", "format": "cloze", "options": ["trafic", "transport", "passage", "mouvement"], "a": 0, "trap": "le transport — the activity of carrying people; « le trafic » is the running of the services", "expl": "Rail services: « le trafic ferroviaire ». Cars on the road: « la circulation ». Note the French spelling of trafic — one f.", "q": "Le ___ ferroviaire sera fortement perturbé jeudi."}]},
  "rent-A2": {"slug": "rent", "level": "A2", "title": "Appeler la propriétaire : un loyer en retard et un radiateur froid", "place": "Au téléphone, depuis un appartement rue Vandeweyer, Schaerbeek", "register": "vous", "registerNote": "Vous with your landlord, always, and in both directions — even after three years, even if she is friendly on the doorstep. This is a contract relationship: everything you say on the phone could end up in front of the juge de paix. Vous also keeps the conversation calm when the subject is money.", "vocab": [{"id": "fvc-rent-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le loyer", "en": "the rent", "format": "fr2en", "options": ["the rent you pay each month", "the tenant", "the lease contract", "the landlord"], "a": 0, "trap": "le locataire — the tenant; the two words come from the same root « louer »", "expl": "« Le loyer est de 850 € hors charges. » The verb is « payer le loyer » or, more formally, « s'acquitter du loyer »."}, {"id": "fvc-rent-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "les charges", "en": "the service charges", "format": "fr2en", "options": ["the building's running costs on top of the rent", "the rent itself", "a tax on the property", "the removal costs"], "a": 0, "trap": "le loyer — charges are separate, and Belgian ads always say « + charges » or « charges comprises »", "expl": "Cover the common areas, the lift, sometimes water and heating. You pay « une provision » monthly and settle up once a year."}, {"id": "fvc-rent-A2-03", "level": "A2", "pos": "noun", "gender": "f", "fr": "la provision pour charges", "en": "the monthly advance on charges", "format": "collocation", "q": "Your lease says « 850 € + 120 € de provision pour charges ». What does the 120 € mean?", "options": ["Une avance mensuelle, régularisée une fois par an.", "Un montant fixe et définitif.", "Une caution rendue à la fin du bail.", "Une assurance obligatoire."], "a": 0, "trap": "assuming it is a fixed price — it is an estimate, and the annual reckoning can go either way", "expl": "Once a year the landlord or the syndic produces « le décompte des charges »: you either owe more or get a credit.", "note": "Belgian practice. Ads say « charges comprises » (all in) or « + charges » (provision on top)."}, {"id": "fvc-rent-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le bail", "en": "the lease", "format": "fr2en", "options": ["the lease contract", "the landlord", "the yawn", "the estate agency"], "a": 0, "trap": "« le bâillement » is the yawn — and « bail » really is pronounced like the start of it", "expl": "Plural: « des baux ». A Brussels main-residence lease is normally 9 years, or « un bail de courte durée » of 3 years or less."}, {"id": "fvc-rent-A2-05", "level": "A2", "pos": "noun", "gender": "m", "fr": "le propriétaire", "en": "the owner / landlord", "format": "en2fr", "options": ["le propriétaire", "le locataire", "le concierge", "le voisin"], "a": 0, "trap": "le locataire — the tenant; the two are the two ends of the same contract", "expl": "All four masculine. In the lease itself the legal words are « le bailleur » (landlord) and « le preneur » (tenant)."}, {"id": "fvc-rent-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le locataire", "en": "the tenant", "format": "cloze", "q": "Je suis le ___ de l'appartement du deuxième étage.", "options": ["locataire", "propriétaire", "voisin", "gérant"], "a": 0, "trap": "propriétaire — the word most learners reach for first because it looks more official", "expl": "All four are masculine nouns. Opening a call: « Bonjour, je suis votre locataire de la rue Vandeweyer. »"}, {"id": "fvc-rent-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "le syndic", "en": "the building manager", "format": "fr2en", "options": ["the firm managing the shared parts of the building", "the trade union", "the caretaker who lives on site", "the estate agent who found you the flat"], "a": 0, "trap": "'syndicate' or 'syndicat' — in French « un syndicat » is a trade union, a completely different thing", "expl": "The syndic runs the copropriété: the lift, the hall, the boiler room, the annual meeting. Your contract is with the owner, not with them.", "note": "Belgian and French institution alike. In Brussels the syndic's number is usually posted in the entrance hall."}, {"id": "fvc-rent-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la garantie locative", "en": "the rent guarantee", "format": "collocation", "q": "How much can a Brussels landlord ask as a rent guarantee since November 2024?", "options": ["Deux mois de loyer maximum, quelle que soit la forme.", "Trois mois de loyer sur un compte bloqué.", "Trois mois si c'est une garantie bancaire.", "Il n'y a pas de maximum légal."], "a": 0, "trap": "the three-month figure — correct before the 2024 Brussels reform and still repeated everywhere", "expl": "Since the ordinance of 4 April 2024, in force on 1 November 2024, the Brussels cap is two months' rent excluding charges, whatever form the guarantee takes.", "note": "Brussels rule. Flanders and Wallonia have their own ceilings, so a Belgian friend from Ghent may tell you three."}, {"id": "fvc-rent-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "le compte bloqué", "en": "the blocked account", "format": "fr2en", "options": ["an account in your name that neither party can touch alone", "the landlord's own bank account", "an account frozen by the bank for debt", "a savings account for the rent"], "a": 0, "trap": "assuming the money goes to the landlord — it stays in your name, and the interest is yours", "expl": "The guarantee sits there for the whole lease and is released with both signatures, or by the juge de paix if you disagree."}, {"id": "fvc-rent-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'état des lieux", "en": "the inventory of condition", "format": "fr2en", "options": ["a detailed written record of the flat's condition", "the address of the property", "the list of furniture provided", "a survey of the building's structure"], "a": 0, "trap": "l'inventaire — a list of objects; the état des lieux is about the state of everything, walls included", "expl": "Compulsory in Belgium, drawn up jointly and at shared cost, either before you move in or during your first month, then registered with the lease.", "note": "Belgian institution. Without an état des lieux d'entrée you are presumed to have received the flat in good condition — take photos too."}, {"id": "fvc-rent-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le virement", "en": "the bank transfer", "format": "en2fr", "options": ["le virement", "le versement", "le prélèvement", "le paiement"], "a": 0, "trap": "le versement — a payment made into an account; « virement » is specifically the transfer between accounts", "expl": "All four masculine. « J'ai fait le virement hier. » In Belgium the rent is nearly always paid « par virement »."}, {"id": "fvc-rent-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'ordre permanent", "en": "the standing order", "format": "collocation", "q": "You want your bank to send the same rent automatically on the 5th of every month. What do you set up?", "options": ["un ordre permanent", "une domiciliation", "un virement instantané", "un prélèvement du propriétaire"], "a": 0, "trap": "une domiciliation — that is a direct debit, where the other party pulls the money; you never do that for rent", "expl": "Ordre permanent: you push a fixed amount on a fixed date. Domiciliation: the supplier pulls a variable amount — right for Proximus, wrong for a landlord.", "note": "Belgian French. France says « un virement permanent » and « un prélèvement automatique »."}, {"id": "fvc-rent-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "la communication structurée", "en": "the structured reference", "format": "fr2en", "options": ["a coded reference in +++…+++ that identifies the payment", "a free message to the recipient", "the IBAN of the account", "the name of the payer"], "a": 0, "trap": "« la communication libre » — the free-text message box just beside it on the same screen", "expl": "Belgian transfers offer both. A structured reference looks like +++090/9337/55493+++ and must be typed exactly.", "note": "Belgian banking. France has no direct equivalent; you write a free reference instead."}, {"id": "fvc-rent-A2-14", "level": "A2", "pos": "noun", "gender": "m", "fr": "le numéro de compte", "en": "the account number", "format": "cloze", "q": "Vous pouvez me redonner votre ___ de compte ? Je l'ai perdu.", "options": ["numéro", "chiffre", "code", "compte"], "a": 0, "trap": "chiffre — a single digit; a whole number is « un numéro »", "expl": "All four masculine. Belgian IBANs run BE68 5390 0754 7034 — sixteen characters, read out in pairs."}, {"id": "fvc-rent-A2-15", "level": "A2", "pos": "noun", "gender": "m", "fr": "le retard", "en": "the lateness", "format": "cloze", "q": "Je suis désolé pour le ___ de paiement, le virement est parti hier.", "options": ["retard", "problème", "changement", "rappel"], "a": 0, "trap": "le rappel — the reminder the landlord sends because of the retard", "expl": "All four masculine. « avoir du retard » / « être en retard de deux jours ». Announce it before she has to ask."}, {"id": "fvc-rent-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le rappel", "en": "the reminder", "format": "fr2en", "options": ["a reminder letter or message", "a repayment", "a recall of a product", "a refund"], "a": 0, "trap": "le remboursement — a refund; « rappel » is only the chasing message", "expl": "« Vous avez reçu mon rappel ? » The formal step after two reminders is « une mise en demeure », sent by registered post."}, {"id": "fvc-rent-A2-17", "level": "A2", "pos": "noun", "gender": "f", "fr": "la chaudière", "en": "the boiler", "format": "fr2en", "options": ["the boiler heating the flat", "the hot-water tank only", "the radiator", "the cooker"], "a": 0, "trap": "le chauffe-eau — the water heater; a chaudière normally does both heating and hot water", "expl": "« La chaudière est en panne. » In Brussels, gas boilers must have a PEB check every two years, oil ones every year."}, {"id": "fvc-rent-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "le radiateur", "en": "the radiator", "format": "cloze", "q": "Le ___ du salon ne chauffe plus depuis samedi.", "options": ["radiateur", "frigo", "compteur", "ascenseur"], "a": 0, "trap": "le compteur — the meter, also on the wall, also involved in heating bills", "expl": "All four masculine. « ne chauffe plus » = has stopped heating. « purger un radiateur » = to bleed it."}, {"id": "fvc-rent-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le compteur", "en": "the meter", "format": "fr2en", "options": ["the gas, water or electricity meter", "the counter in a shop", "the accountant", "the meter reading card"], "a": 0, "trap": "le comptoir — the counter you stand at; one letter apart", "expl": "« relever le compteur » = to read the meter. You do this at the état des lieux, on the way in and on the way out."}, {"id": "fvc-rent-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chauffagiste", "en": "the heating engineer", "format": "en2fr", "options": ["le chauffagiste", "le chauffeur", "le plombier", "le pompier"], "a": 0, "trap": "le chauffeur — a driver; both come from « chauffer », which is why the mistake is so easy", "expl": "All four masculine. In Brussels the boiler check must be done by « un technicien chaudière PEB agréé »."}, {"id": "fvc-rent-A2-21", "level": "A2", "pos": "noun", "gender": "m", "fr": "le plombier", "en": "the plumber", "format": "cloze", "q": "Il y a une fuite sous l'évier, il faut appeler un ___.", "options": ["plombier", "électricien", "peintre", "serrurier"], "a": 0, "trap": "le serrurier — the locksmith; the other emergency trade you call in a panic", "expl": "All four masculine trades. « une fuite d'eau » → plombier; « une panne de courant » → électricien; « clé perdue » → serrurier."}, {"id": "fvc-rent-A2-22", "level": "A2", "pos": "noun", "gender": "f", "fr": "la fuite", "en": "the leak", "format": "fr2en", "options": ["a water leak", "the drain", "the tap", "the flow"], "a": 0, "trap": "« la fuite » also means an escape — the plumbing sense is the one you need on the phone", "expl": "« une fuite d'eau sous l'évier ». Report it fast: water damage between flats is the most expensive thing that can go wrong."}, {"id": "fvc-rent-A2-23", "level": "A2", "pos": "noun", "gender": "f", "fr": "la panne", "en": "the breakdown", "format": "cloze", "q": "La chaudière est en ___ depuis vendredi soir.", "options": ["panne", "retard", "route", "marche"], "a": 0, "trap": "en marche — 'working'; grammatically identical and the opposite of what you mean", "expl": "All four feminine nouns after « en ». « en panne » = out of order; « en marche » = running."}, {"id": "fvc-rent-A2-24", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'eau chaude", "en": "the hot water", "format": "collocation", "q": "Which sentence reports that only the heating has failed?", "options": ["L'eau chaude fonctionne, c'est seulement le radiateur.", "L'eau chaude ne fonctionne plus non plus.", "Il n'y a ni eau chaude ni chauffage.", "La chaudière est complètement arrêtée."], "a": 0, "trap": "the other three all say more is broken than you meant — and change who has to come out, and how fast", "expl": "Being precise about what still works is what gets the right tradesman sent. Hot water fine + cold radiator often means air in the system."}, {"id": "fvc-rent-A2-25", "level": "A2", "pos": "noun", "gender": "f", "fr": "la cave", "en": "the cellar", "format": "fr2en", "options": ["the cellar or basement storage", "the cave in a hillside", "the attic", "the courtyard"], "a": 0, "trap": "'cave' in English — a false friend; a real cave is « une grotte »", "expl": "Brussels flats usually come with « une cave » in the basement, numbered like the flat. The attic is « le grenier »."}, {"id": "fvc-rent-A2-26", "level": "A2", "pos": "noun", "gender": "f", "fr": "la boîte aux lettres", "en": "the letterbox", "format": "en2fr", "options": ["la boîte aux lettres", "la boîte à outils", "la boîte de nuit", "la boîte vocale"], "a": 0, "trap": "la boîte vocale — voicemail, which is where this phone call may well end up", "expl": "All four feminine. Put your name on it: bpost will not deliver to an unnamed box, including your lease and your commune's letters."}, {"id": "fvc-rent-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'assurance incendie", "en": "fire / home insurance", "format": "fr2en", "options": ["household insurance covering fire and water damage", "insurance for the landlord only", "insurance against burglary only", "the fire brigade's callout charge"], "a": 0, "trap": "assuming the landlord's policy covers you — his covers the building, not your things or your liability", "expl": "In Brussels the tenant must insure against fire and water damage; ask your insurer for « l'abandon de recours » in the policy.", "note": "Belgian rule since the 2018 housing reform. Estate agents will ask for the certificate before handing over the keys."}, {"id": "fvc-rent-A2-28", "level": "A2", "pos": "noun", "gender": "f", "fr": "la commune", "en": "the local council area", "format": "fr2en", "options": ["the municipality you are registered in", "the community centre", "a shared flat", "the neighbourhood association"], "a": 0, "trap": "'commune' in English suggests people living together — in Belgium it is your local authority", "expl": "Brussels is nineteen communes. You must register at yours within eight days of moving in; a police officer then calls to check you live there.", "note": "Belgian institution: Schaerbeek, Ixelles, Saint-Gilles and sixteen others, each with its own town hall."}, {"id": "fvc-rent-A2-29", "level": "A2", "pos": "noun", "gender": "m", "fr": "le voisin", "en": "the neighbour", "format": "en2fr", "options": ["le voisin", "le visiteur", "le vendeur", "le veilleur"], "a": 0, "trap": "le visiteur — a visitor; the two share a shape and nothing else", "expl": "All four masculine. « le voisin du dessus » = the neighbour upstairs, and the most likely source of « le bruit »."}, {"id": "fvc-rent-A2-30", "level": "A2", "pos": "verb", "fr": "payer", "en": "to pay", "format": "collocation", "q": "Which is right?", "options": ["Je paie le loyer le cinq de chaque mois.", "Je paie pour le loyer le cinq de chaque mois.", "Je paie au loyer le cinq de chaque mois.", "Je paie du loyer le cinq de chaque mois."], "a": 0, "trap": "« payer pour » exists but means paying on someone else's behalf, or paying the price for a mistake", "expl": "payer + direct object: payer le loyer, payer les charges, payer la facture. « payer pour quelqu'un » is the exception."}, {"id": "fvc-rent-A2-31", "level": "A2", "pos": "verb", "fr": "verser", "en": "to pay in / transfer", "format": "fr2en", "options": ["to pay a sum into an account", "to pour a drink", "to spill", "to owe"], "a": 0, "trap": "the everyday meaning of « verser » is to pour — and it really is the same verb", "expl": "« verser la garantie locative sur un compte bloqué ». Formal and standard in Belgian banking letters."}, {"id": "fvc-rent-A2-32", "level": "A2", "pos": "verb", "fr": "prévenir", "en": "to let someone know", "format": "cloze", "q": "Je vous appelle pour vous ___ que le virement partira demain.", "options": ["prévenir", "prévoir", "prier", "présenter"], "a": 0, "trap": "prévoir — to foresee or plan; one letter apart and constantly confused", "expl": "All four infinitives. « prévenir quelqu'un de quelque chose » = to warn or inform. Doing it before the deadline changes everything."}, {"id": "fvc-rent-A2-33", "level": "A2", "pos": "verb", "fr": "réparer", "en": "to repair", "format": "en2fr", "options": ["réparer", "préparer", "repérer", "replacer"], "a": 0, "trap": "repérer — 'to spot' or locate; a lookalike that changes the whole sentence", "expl": "All four infinitives. « faire réparer la chaudière » — note « faire + infinitive » when someone else does the work."}, {"id": "fvc-rent-A2-34", "level": "A2", "pos": "verb", "fr": "chauffer", "en": "to heat", "format": "cloze", "q": "Le radiateur ne ___ plus, même quand je monte le thermostat.", "options": ["chauffe", "marche", "brûle", "fonctionne"], "a": 0, "trap": "marche — « ne marche plus » is perfect French, but it says nothing about heat", "expl": "All four are third-person verbs. Be specific: a radiator that turns on but stays cold is a different fault from one that is dead."}, {"id": "fvc-rent-A2-35", "level": "A2", "pos": "verb", "fr": "purger", "en": "to bleed (a radiator)", "format": "fr2en", "options": ["to let the air out of a radiator", "to drain the whole system", "to clean a filter", "to turn the heating off"], "a": 0, "trap": "vidanger — draining the system, which is a job for the chauffagiste, not for you with a key", "expl": "« Il faut purger le radiateur, il y a de l'air. » A five-minute job with « une clé de purge » — but ask before you try."}, {"id": "fvc-rent-A2-36", "level": "A2", "pos": "verb", "fr": "envoyer", "en": "to send", "format": "cloze", "q": "Est-ce que vous pouvez m'___ un mail pour confirmer ?", "options": ["envoyer", "apporter", "amener", "emporter"], "a": 0, "trap": "apporter — to bring in person, which is not how emails travel", "expl": "All four infinitives. « envoyer un mail / un courrier / un recommandé ». In Belgium « un mail » is the everyday word."}, {"id": "fvc-rent-A2-37", "level": "A2", "pos": "verb", "fr": "déménager", "en": "to move out", "format": "en2fr", "options": ["déménager", "emménager", "aménager", "ménager"], "a": 0, "trap": "emménager — to move IN; the prefix is the whole difference and it is one letter", "expl": "All four infinitives. dé- = out, em- = in, a- = to fit out a room. « J'ai emménagé en mars et je déménage en juin. »"}, {"id": "fvc-rent-A2-38", "level": "A2", "pos": "adj", "fr": "mensuel", "en": "monthly", "format": "fr2en", "options": ["monthly", "weekly", "yearly", "quarterly"], "a": 0, "trap": "hebdomadaire is weekly and annuel is yearly — the -el ending gives nothing away", "expl": "« le loyer mensuel », « la provision mensuelle ». The adverb is « mensuellement »."}, {"id": "fvc-rent-A2-39", "level": "A2", "pos": "adj", "fr": "urgent", "en": "urgent", "format": "cloze", "q": "Ce n'est pas ___, mais j'aimerais que ce soit réparé cette semaine.", "options": ["urgent", "important", "possible", "normal"], "a": 0, "trap": "important — true and much weaker; « urgent » is about time, « important » about weight", "expl": "All four masculine adjectives. Saying it is not urgent buys goodwill; saying it is, when it is not, spends it."}, {"id": "fvc-rent-A2-40", "level": "A2", "pos": "adj", "fr": "cassé", "en": "broken", "format": "en2fr", "options": ["cassé", "casé", "classé", "cassant"], "a": 0, "trap": "cassant — 'brittle', or of a person, curt; same root, different job", "expl": "All four masculine adjectives. Machines are « en panne »; objects are « cassés »; a window is « brisée »."}, {"id": "fvc-rent-A2-41", "level": "A2", "pos": "adj", "fr": "hors charges", "en": "excluding charges", "format": "collocation", "q": "An ad says « 850 € hors charges ». What will you actually pay each month?", "options": ["850 € plus une provision pour charges", "850 € tout compris", "850 € moins les charges", "850 € une seule fois"], "a": 0, "trap": "reading « hors » as 'including' — it means outside, excluded", "expl": "« hors charges » (HC) = charges on top. « charges comprises » (CC) = all in. Two letters in an ad, a hundred euros a month.", "note": "Belgian property ads use HC and CC constantly — check which one before you visit."}, {"id": "fvc-rent-A2-42", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "Le loyer est de huit cent ___ euros par mois, hors charges.", "options": ["septante", "nonante", "soixante", "quarante"], "a": 0, "trap": "nonante — the other Belgian form, and a twenty-euro difference every month", "expl": "huit cent septante = 870. Rents in Schaerbeek for a one-bedroom flat sit around 800–950 € in 2026.", "note": "Belgian French. France says huit cent soixante-dix."}, {"id": "fvc-rent-A2-43", "level": "A2", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile (Belgian French)", "format": "cloze", "q": "Vous pouvez me joindre sur mon ___, je ne suis pas souvent chez moi.", "options": ["GSM", "fixe", "bureau", "mail"], "a": 0, "trap": "le fixe — the landline, which is exactly the phone you are not at", "expl": "All four masculine. « le GSM » is the Belgian word for a mobile; « le fixe » is the landline.", "note": "Belgian French. France says « mon portable »."}, {"id": "fvc-rent-A2-44", "level": "A2", "pos": "noun", "gender": "f", "fr": "la chambre", "en": "the bedroom", "format": "collocation", "q": "How is a two-bedroom flat advertised in Brussels?", "options": ["un appartement deux chambres", "un appartement trois pièces", "un T3", "un F3"], "a": 0, "trap": "T3 and F3 — the French system, counting all rooms including the living room", "expl": "Belgium counts bedrooms: « un deux chambres » has two bedrooms plus a living room. France counts rooms: T3 = living room + 2 bedrooms.", "note": "Belgian convention. Same flat, two different labels either side of the border."}, {"id": "fvc-rent-A2-45", "level": "A2", "pos": "noun", "gender": "m", "fr": "le kot", "en": "the student room (Belgian French)", "format": "fr2en", "options": ["a rented student room", "a small flat for a couple", "a shared house", "a storage room"], "a": 0, "trap": "un studio — a self-contained small flat; a kot is a room in a shared student house", "expl": "From Flemish. « koter » = to live in one. Special short leases exist for student koten in Brussels.", "note": "Belgian French, unknown in France, where students rent « une chambre » or « un studio »."}, {"id": "fvc-rent-A2-46", "level": "A2", "pos": "expr", "fr": "je suis désolé", "en": "I'm sorry", "format": "collocation", "q": "Which opening handles a late rent payment best on the phone?", "options": ["Je suis désolé, le virement est parti avec deux jours de retard.", "Ce n'est pas ma faute, la banque a eu un problème.", "Vous avez reçu l'argent ou pas ?", "Je pensais que c'était le dix."], "a": 0, "trap": "blaming the bank first — even when it is true, it reads as an excuse and hardens the conversation", "expl": "Apologise, state the fact, give the date. Explanations come after, if she asks for them."}], "phrases": [{"id": "ph-rent-A2-01", "fr": "Bonjour madame, c'est Orestis Vasileiadis, votre locataire de la rue Vandeweyer.", "en": "Hello, this is Orestis Vasileiadis, your tenant from rue Vandeweyer.", "note": "On the phone French says « c'est … » to identify yourself, not « je suis … ». Give the address: landlords have several tenants."}, {"id": "ph-rent-A2-02", "fr": "Je vous appelle pour le loyer de ce mois-ci.", "en": "I'm calling about this month's rent.", "note": "Say the subject in the second sentence. « ce mois-ci » = this month; « le mois passé » = last month (Belgium often prefers this to « dernier »)."}, {"id": "ph-rent-A2-03", "fr": "Je suis désolé, le virement est parti avec deux jours de retard.", "en": "I'm sorry, the transfer went two days late.", "note": "« le virement est parti » — the transfer left. Announce it yourself before she chases you; it costs one phone call and saves a rappel."}, {"id": "ph-rent-A2-04", "fr": "Vous devriez le recevoir demain ou après-demain.", "en": "You should get it tomorrow or the day after.", "note": "The conditional « devriez » softens a promise you can't fully control. Belgian transfers between banks take one working day."}, {"id": "ph-rent-A2-05", "fr": "J'ai bien mis la communication structurée du bail.", "en": "I did put in the structured reference from the lease.", "note": "« bien » here means 'did indeed'. The structured reference is the +++…+++ code; type it exactly or the payment lands unidentified."}, {"id": "ph-rent-A2-06", "fr": "Je vais faire un ordre permanent pour ne plus oublier.", "en": "I'm going to set up a standing order so I don't forget again.", "note": "« un ordre permanent » is Belgian for a standing order — you push the money. Never accept « une domiciliation » for rent."}, {"id": "ph-rent-A2-07", "fr": "Est-ce que vous pouvez me redonner votre numéro de compte ?", "en": "Could you give me your account number again?", "note": "« re- » on a verb means doing it again: redonner, redire, revenir. Belgian IBANs start BE and have sixteen characters."}, {"id": "ph-rent-A2-08", "fr": "Le loyer est dû le cinq de chaque mois, c'est bien ça ?", "en": "The rent is due on the fifth of each month, is that right?", "note": "« c'est bien ça ? » is the everyday way to confirm a detail. « être dû » = to be due; feminine « due »."}, {"id": "ph-rent-A2-09", "fr": "Il y a aussi un autre problème dans l'appartement.", "en": "There's also another problem in the flat.", "note": "Signal the change of subject before you launch into it — it gives the other person time to pick up a pen."}, {"id": "ph-rent-A2-10", "fr": "Le radiateur du salon ne chauffe plus depuis samedi.", "en": "The living-room radiator has stopped heating since Saturday.", "note": "« depuis » + present for a situation still going on. Give the day: it shows you are not calling about something from last winter."}, {"id": "ph-rent-A2-11", "fr": "L'eau chaude fonctionne, c'est seulement le radiateur.", "en": "The hot water works, it's only the radiator.", "note": "Saying what still works is as useful as saying what doesn't: it tells the landlord which tradesman to call."}, {"id": "ph-rent-A2-12", "fr": "Est-ce que je dois purger le radiateur moi-même ?", "en": "Should I bleed the radiator myself?", "note": "Ask before you touch anything. Small maintenance is the tenant's job in Belgium, real repairs are the landlord's."}, {"id": "ph-rent-A2-13", "fr": "Est-ce que vous pouvez envoyer un chauffagiste cette semaine ?", "en": "Could you send a heating engineer this week?", "note": "Name the trade and the timeframe. « un chauffagiste » for heating; « un plombier » for water; « un électricien » for power."}, {"id": "ph-rent-A2-14", "fr": "Ce n'est pas urgent, mais il commence à faire froid.", "en": "It's not urgent, but it's starting to get cold.", "note": "Understatement works on Belgian landlords. « il commence à faire froid » in November is a complete argument."}, {"id": "ph-rent-A2-15", "fr": "Est-ce que vous pouvez me confirmer par mail, s'il vous plaît ?", "en": "Could you confirm that to me by email, please?", "note": "The most valuable sentence in the call. Anything about repairs or money should exist in writing."}, {"id": "ph-rent-A2-16", "fr": "Je préfère avoir une trace écrite, pour nous deux.", "en": "I'd rather have a written record, for both of us.", "note": "« une trace écrite » — a written trace. Framing it as being for both of you makes it sound practical, not suspicious."}, {"id": "ph-rent-A2-17", "fr": "Vous pouvez me joindre sur mon GSM, je ne suis pas souvent chez moi.", "en": "You can reach me on my mobile, I'm not often at home.", "note": "« joindre quelqu'un » = to reach someone. GSM is Belgian for a mobile; a landline is « un fixe »."}, {"id": "ph-rent-A2-18", "fr": "Quand est-ce que le décompte des charges arrive, en général ?", "en": "When does the charges statement usually come?", "note": "Once a year, from the landlord or the syndic. It either refunds you or asks for more — worth knowing which month to expect it."}, {"id": "ph-rent-A2-19", "fr": "Je m'excuse encore pour le retard, ça n'arrivera plus.", "en": "Sorry again for the delay, it won't happen again.", "note": "« ça n'arrivera plus » (future) is a real commitment in French. Say it only if you are setting up that standing order."}, {"id": "ph-rent-A2-20", "fr": "Merci beaucoup, bonne journée madame.", "en": "Thank you very much, have a good day.", "note": "Adding « madame » at the end of a phone call is normal and warm in Belgium — never « madame Dubois », just « madame »."}], "dialogue": [{"who": "landlord", "fr": "Allô, oui ?", "en": "Hello?", "gloss": {"Allô": "hello (on the phone only)"}}, {"who": "you", "fr": "Bonjour madame, c'est Orestis Vasileiadis, votre locataire de la rue Vandeweyer.", "en": "Hello, this is Orestis Vasileiadis, your tenant from rue Vandeweyer.", "gloss": {"c'est": "this is (on the phone)", "locataire": "tenant"}, "accept": ["bonjour madame c'est orestis vasileiadis votre locataire de la rue vandeweyer", "bonjour madame c'est monsieur vasileiadis votre locataire de la rue vandeweyer", "bonjour madame c'est orestis vasileiadis votre locataire", "bonjour madame ici orestis vasileiadis votre locataire de la rue vandeweyer", "bonjour madame c'est votre locataire de la rue vandeweyer monsieur vasileiadis", "bonjour madame c'est orestis vasileiadis l'appartement de la rue vandeweyer"]}, {"who": "landlord", "fr": "Ah bonjour monsieur. Justement, je voulais vous appeler pour le loyer.", "en": "Ah hello. As it happens, I was about to call you about the rent.", "gloss": {"Justement": "as it happens, precisely", "voulais": "was meaning to"}}, {"who": "you", "fr": "Oui, je vous appelle pour ça. Je suis désolé, le virement est parti avec deux jours de retard.", "en": "Yes, that's what I'm calling about. I'm sorry, the transfer went two days late.", "gloss": {"virement": "bank transfer", "est parti": "went, left", "retard": "lateness"}, "accept": ["oui je vous appelle pour ça je suis désolé le virement est parti avec deux jours de retard", "oui je vous appelle pour ça je suis désolé le virement est parti en retard", "oui c'est pour ça que j'appelle je suis désolé le virement est parti avec deux jours de retard", "oui justement je suis désolé le virement est parti en retard de deux jours", "oui je suis désolé pour le retard le virement est parti avant-hier", "oui je vous appelle pour le loyer je suis désolé du retard le virement est parti"]}, {"who": "landlord", "fr": "Ce n'est pas très grave, mais prévenez-moi la prochaine fois. Vous avez bien mis la communication structurée ?", "en": "It's not too serious, but let me know next time. Did you put in the structured reference?", "gloss": {"prévenez-moi": "let me know", "communication structurée": "the +++…+++ payment reference used on Belgian transfers"}}, {"who": "you", "fr": "Oui, celle qui est écrite sur le bail. Vous devriez recevoir l'argent demain.", "en": "Yes, the one written on the lease. You should get the money tomorrow.", "gloss": {"celle": "the one", "bail": "lease", "devriez": "should"}, "accept": ["oui celle qui est écrite sur le bail vous devriez recevoir l'argent demain", "oui celle qui est écrite sur le bail vous devriez le recevoir demain", "oui celle du bail vous devriez recevoir l'argent demain", "oui j'ai mis la communication structurée du bail vous devriez recevoir l'argent demain", "oui celle qui est sur le contrat vous devriez avoir l'argent demain", "oui bien sûr celle du bail l'argent devrait arriver demain"]}, {"who": "landlord", "fr": "D'accord. Vous savez, le plus simple, c'est de faire un ordre permanent à votre banque.", "en": "All right. You know, the simplest thing is to set up a standing order at your bank.", "gloss": {"le plus simple": "the simplest thing", "ordre permanent": "standing order (Belgian French)"}}, {"who": "you", "fr": "Vous avez raison, je vais le faire cette semaine. Le loyer est dû le cinq de chaque mois, c'est bien ça ?", "en": "You're right, I'll do it this week. The rent is due on the fifth of each month, is that right?", "gloss": {"dû": "due", "c'est bien ça": "is that right"}, "accept": ["vous avez raison je vais le faire cette semaine le loyer est dû le cinq de chaque mois c'est bien ça", "vous avez raison je vais le faire cette semaine le loyer est dû le cinq c'est bien ça", "d'accord je vais faire un ordre permanent cette semaine le loyer est dû le cinq de chaque mois", "vous avez raison je vais m'en occuper cette semaine c'est bien le cinq de chaque mois", "oui je vais le faire cette semaine le loyer c'est bien le cinq du mois", "je vais le faire cette semaine et le loyer est dû le cinq c'est bien ça"]}, {"who": "landlord", "fr": "C'est ça, le cinq. Huit cent septante euros, plus cent vingt euros de provision pour charges.", "en": "That's it, the fifth. Eight hundred and seventy euros, plus a hundred and twenty euros advance on charges.", "gloss": {"septante": "seventy (Belgian French; France: soixante-dix)", "provision pour charges": "monthly advance on the service charges"}}, {"who": "you", "fr": "C'est noté. Il y a aussi un autre problème dans l'appartement.", "en": "Noted. There's also another problem in the flat.", "gloss": {"C'est noté": "noted", "problème": "problem"}, "accept": ["c'est noté il y a aussi un autre problème dans l'appartement", "c'est noté il y a aussi un autre problème", "d'accord c'est noté il y a aussi un autre problème dans l'appartement", "très bien et il y a aussi un autre problème dans l'appartement", "c'est noté merci il y a autre chose aussi dans l'appartement", "d'accord et j'ai aussi un autre problème à vous signaler"]}, {"who": "landlord", "fr": "Dites-moi.", "en": "Tell me.", "gloss": {"Dites-moi": "tell me, go ahead"}}, {"who": "you", "fr": "Le radiateur du salon ne chauffe plus depuis samedi. Il commence à faire froid le soir.", "en": "The living-room radiator has stopped heating since Saturday. It's starting to get cold in the evenings.", "gloss": {"radiateur": "radiator", "ne chauffe plus": "no longer heats", "depuis": "since"}, "accept": ["le radiateur du salon ne chauffe plus depuis samedi il commence à faire froid le soir", "le radiateur du salon ne chauffe plus depuis samedi", "le radiateur du salon ne chauffe plus depuis samedi et il commence à faire froid", "depuis samedi le radiateur du salon ne chauffe plus il fait froid le soir", "le radiateur du living ne chauffe plus depuis samedi il commence à faire froid", "le radiateur du salon est froid depuis samedi il commence à faire froid le soir"]}, {"who": "landlord", "fr": "Et l'eau chaude, elle fonctionne toujours ?", "en": "And the hot water, is it still working?", "gloss": {"eau chaude": "hot water", "fonctionne": "works", "toujours": "still"}}, {"who": "you", "fr": "Oui, l'eau chaude fonctionne normalement. C'est seulement le radiateur du salon, les autres chauffent bien.", "en": "Yes, the hot water is working normally. It's only the living-room radiator, the others heat fine.", "gloss": {"normalement": "normally", "seulement": "only"}, "accept": ["oui l'eau chaude fonctionne normalement c'est seulement le radiateur du salon les autres chauffent bien", "oui l'eau chaude fonctionne c'est seulement le radiateur du salon", "oui l'eau chaude marche normalement c'est seulement le radiateur du salon les autres chauffent", "oui l'eau chaude fonctionne bien il n'y a que le radiateur du salon", "oui l'eau chaude est normale c'est uniquement le radiateur du salon", "oui l'eau chaude fonctionne normalement les autres radiateurs chauffent bien"]}, {"who": "landlord", "fr": "Alors c'est sans doute de l'air dans le circuit. Il faut purger le radiateur : c'est l'entretien du locataire, normalement.", "en": "Then it's probably air in the system. The radiator needs bleeding: that's normally the tenant's maintenance.", "gloss": {"sans doute": "probably", "purger": "to bleed", "entretien": "upkeep, maintenance"}}, {"who": "you", "fr": "Je ne l'ai jamais fait et je n'ai pas la clé de purge. Est-ce que vous pouvez envoyer un chauffagiste ?", "en": "I've never done it and I don't have the bleed key. Could you send a heating engineer?", "gloss": {"jamais": "never", "clé de purge": "radiator bleed key", "chauffagiste": "heating engineer"}, "accept": ["je ne l'ai jamais fait et je n'ai pas la clé de purge est-ce que vous pouvez envoyer un chauffagiste", "je ne l'ai jamais fait et je n'ai pas la clé de purge est-ce que vous pouvez envoyer quelqu'un", "je n'ai jamais fait ça et je n'ai pas la clé de purge pouvez-vous envoyer un chauffagiste", "je ne sais pas comment faire et je n'ai pas la clé de purge est-ce que vous pouvez envoyer un chauffagiste", "je ne l'ai jamais fait est-ce que vous pouvez envoyer un chauffagiste", "je n'ai pas la clé de purge est-ce que vous pourriez envoyer un chauffagiste cette semaine"]}, {"who": "landlord", "fr": "Bon, d'accord. J'appelle monsieur Peeters, il passe souvent dans le quartier. Vous êtes là jeudi après-midi ?", "en": "Fine, all right. I'll call Mr Peeters, he's often round the area. Are you in on Thursday afternoon?", "gloss": {"quartier": "neighbourhood", "jeudi": "Thursday"}}, {"who": "you", "fr": "Jeudi après-midi, oui, à partir de quatorze heures. Vous pouvez me confirmer par mail, s'il vous plaît ?", "en": "Thursday afternoon, yes, from two o'clock. Could you confirm to me by email, please?", "gloss": {"à partir de": "from", "confirmer": "to confirm"}, "accept": ["jeudi après-midi oui à partir de quatorze heures vous pouvez me confirmer par mail s'il vous plaît", "jeudi après-midi oui à partir de quatorze heures vous pouvez me confirmer par mail", "oui jeudi après-midi à partir de quatorze heures est-ce que vous pouvez me confirmer par mail", "jeudi après-midi ça va à partir de deux heures vous pouvez me confirmer par mail", "oui je suis là jeudi après-midi vous pouvez me le confirmer par mail s'il vous plaît", "jeudi après-midi c'est bon pour moi merci de me confirmer par mail"]}, {"who": "landlord", "fr": "Je vous envoie un petit mail ce soir avec l'heure. Et n'oubliez pas l'ordre permanent, hein !", "en": "I'll send you a short email this evening with the time. And don't forget the standing order!", "gloss": {"un petit mail": "a quick email", "n'oubliez pas": "don't forget", "hein": "eh (friendly tag at the end of a sentence)"}}, {"who": "you", "fr": "Promis, je le fais demain à la banque. Merci beaucoup, bonne journée madame.", "en": "I promise, I'll do it tomorrow at the bank. Thank you very much, have a good day.", "gloss": {"Promis": "I promise", "à la banque": "at the bank"}, "accept": ["promis je le fais demain à la banque merci beaucoup bonne journée madame", "promis je le fais demain à la banque merci beaucoup bonne journée", "c'est promis je le fais demain merci beaucoup bonne journée madame", "promis je m'en occupe demain merci beaucoup bonne journée", "je vous le promets je le fais demain à la banque merci et bonne journée", "promis je le ferai demain merci beaucoup bonne journée madame"]}], "exercises": [{"id": "ex-rent-A2-01", "level": "A2", "pos": "noun", "gender": "f", "fr": "la garantie locative", "en": "the rent guarantee", "format": "collocation", "q": "Where does a Brussels rent guarantee normally sit?", "options": ["Sur un compte bloqué au nom du locataire.", "Sur le compte courant du propriétaire.", "Chez le notaire, pendant tout le bail.", "À la commune, avec le bail."], "a": 0, "trap": "the landlord's own account — never acceptable, and a warning sign if it is asked for", "expl": "It stays in your name, blocked, and is released within two months of you handing back the keys.", "note": "Brussels rule since November 2024: two months' rent maximum, and a 10 % penalty per month if it is released late."}, {"id": "ex-rent-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'état des lieux", "en": "the inventory of condition", "format": "collocation", "q": "When must the état des lieux d'entrée be drawn up in Belgium?", "options": ["Avant l'emménagement ou pendant le premier mois d'occupation.", "Dans les trois mois qui suivent l'emménagement.", "Seulement à la fin du bail.", "Uniquement si le locataire le demande."], "a": 0, "trap": "'only at the end' — that is the état des lieux DE SORTIE, and comparing the two is the whole point", "expl": "Drawn up jointly and at shared cost, annexed to the lease and registered with it. Without it you are presumed to have received the flat in perfect condition.", "note": "Belgian institution: take dated photos of every room as well."}, {"id": "ex-rent-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'ordre permanent", "en": "the standing order", "format": "cloze", "q": "Je vais faire un ___ permanent pour le loyer, comme ça je n'oublierai plus.", "options": ["ordre", "accord", "virement", "compte"], "a": 0, "trap": "virement — a single transfer; the automatic monthly one is « un ordre permanent »", "expl": "All four masculine. You push the money (ordre permanent); a supplier pulls it (domiciliation).", "note": "Belgian French. France: « un virement permanent » and « un prélèvement automatique »."}, {"id": "ex-rent-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le syndic", "en": "the building manager", "format": "fr2en", "options": ["the manager of the shared parts of the building", "a trade union", "the owner of the whole building", "the caretaker who cleans the stairs"], "a": 0, "trap": "le syndicat — the trade union, one syllable away", "expl": "The syndic answers to the owners, not to you. For anything inside your flat, call the landlord instead."}, {"id": "ex-rent-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "la communication structurée", "en": "the structured reference", "format": "collocation", "q": "Why does the structured reference matter on your rent transfer?", "options": ["Elle identifie automatiquement le paiement chez le bénéficiaire.", "Elle rend le virement plus rapide.", "Elle est obligatoire pour tout virement belge.", "Elle remplace le numéro de compte."], "a": 0, "trap": "'it makes it faster' — it doesn't; it makes it findable", "expl": "Written +++090/9337/55493+++, it lets the recipient's system match your money to your file without a human looking.", "note": "Belgian banking feature. France uses a free-text reference instead."}, {"id": "ex-rent-A2-06", "level": "A2", "pos": "verb", "fr": "prévenir", "en": "to let know", "format": "en2fr", "options": ["prévenir", "prévoir", "provenir", "parvenir"], "a": 0, "trap": "prévoir — 'to foresee, to plan'; the two verbs differ by one letter and by everything else", "expl": "All four infinitives. « Prévenez-moi la prochaine fois » is what your landlord will actually ask of you."}, {"id": "ex-rent-A2-07", "level": "A2", "pos": "adj", "fr": "hors charges", "en": "excluding charges", "format": "fr2en", "options": ["not including the service charges", "including everything", "without a guarantee", "outside the lease"], "a": 0, "trap": "reading « hors » as 'including' — it is the opposite, and it costs about 120 € a month in Brussels", "expl": "HC = hors charges, CC = charges comprises. Check which one an advert means before you go and see the flat.", "note": "Belgian property ads use both abbreviations constantly."}, {"id": "ex-rent-A2-08", "level": "A2", "pos": "verb", "fr": "purger", "en": "to bleed a radiator", "format": "cloze", "q": "Il y a de l'air dans le circuit, il faut ___ le radiateur.", "options": ["purger", "réparer", "remplacer", "nettoyer"], "a": 0, "trap": "réparer — a repair, which would put the cost on the landlord rather than on your five minutes", "expl": "All four infinitives. Bleeding is small maintenance and falls to the tenant; a real repair falls to the owner."}, {"id": "ex-rent-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "la panne", "en": "the breakdown", "format": "en2fr", "options": ["la panne", "la pente", "la peine", "la pause"], "a": 0, "trap": "la peine — trouble or sorrow, and part of « ce n'est pas la peine »", "expl": "All four feminine. « La chaudière est en panne » — the sentence that gets a tradesman sent."}, {"id": "ex-rent-A2-10", "level": "A2", "pos": "noun", "gender": "m", "fr": "le chauffagiste", "en": "the heating engineer", "format": "collocation", "q": "Who do you call for each problem?", "options": ["Chaudière → chauffagiste ; fuite d'eau → plombier", "Chaudière → plombier ; fuite d'eau → chauffagiste", "Chaudière → électricien ; fuite d'eau → syndic", "Chaudière → syndic ; fuite d'eau → commune"], "a": 0, "trap": "plumbers and heating engineers overlap in Belgium, but the boiler is the chauffagiste's", "expl": "In Brussels a gas boiler must be checked every two years by an approved « technicien chaudière PEB », at the tenant's cost.", "note": "Belgian rule: gas every 2 years, oil every year, and the certificate must be kept."}, {"id": "ex-rent-A2-11", "level": "A2", "pos": "noun", "gender": "f", "fr": "la commune", "en": "the municipality", "format": "cloze", "q": "Il faut s'inscrire à la ___ dans les huit jours après le déménagement.", "options": ["commune", "province", "région", "police"], "a": 0, "trap": "la région — Brussels-Capital is a Region, but registration happens at your commune", "expl": "All four feminine. Schaerbeek, Ixelles, Saint-Gilles: nineteen communes, nineteen town halls, nineteen sets of opening hours.", "note": "Belgian obligation: a police officer then visits to confirm you actually live there."}, {"id": "ex-rent-A2-12", "level": "A2", "pos": "noun", "gender": "f", "fr": "la chambre", "en": "the bedroom", "format": "fr2en", "options": ["the bedroom, the unit Belgian ads count", "any room of the flat", "the living room", "the shared room in a house"], "a": 0, "trap": "counting rooms the French way — « un T2 » in Paris is « un une chambre » in Brussels", "expl": "« un appartement deux chambres » = two bedrooms plus a living room. Belgium counts bedrooms; France counts rooms.", "note": "Belgian convention on every immoweb listing."}, {"id": "ex-rent-A2-13", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "fr2en", "options": ["seventy", "seventeen", "seventy-seven", "ninety"], "a": 0, "trap": "nonante — the other Belgian number word, ninety, and the one you will confuse it with on the phone", "expl": "« huit cent septante euros » = 870 €. Ask her to repeat rather than guessing at your own rent.", "note": "Belgian French. France says soixante-dix."}, {"id": "ex-rent-A2-14", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'assurance incendie", "en": "home insurance", "format": "collocation", "q": "Who insures what in a Brussels rental?", "options": ["Le locataire doit s'assurer ; le propriétaire assure le bâtiment.", "Le propriétaire assure tout, y compris vos meubles.", "L'assurance est facultative pour les deux.", "C'est le syndic qui assure les appartements."], "a": 0, "trap": "assuming the landlord's building policy covers your things — it does not", "expl": "Since the 2018 reform tenants in Brussels must cover fire and water damage. Ask your insurer about « l'abandon de recours ».", "note": "Belgian rule: agents often ask for the certificate before handing over the keys."}]},
  "rent-B1": {"slug": "rent", "level": "B1", "title": "Une chaudière en panne depuis huit jours et une lettre d'indexation", "place": "Au téléphone, depuis un appartement rue Vandeweyer, Schaerbeek", "register": "vous", "registerNote": "Vous, and here it is doing real work. You are about to say that you will send a registered letter and, if necessary, go to the juge de paix; in French that only sounds measured if the pronoun stays formal. Tu in this call would turn a legal step into a quarrel.", "vocab": [{"id": "fvc-rent-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'indexation", "en": "the annual rent indexation", "format": "collocation", "q": "When can a Belgian landlord index the rent?", "options": ["Une fois par an, à la date anniversaire de l'entrée en vigueur du bail, sur demande écrite.", "Automatiquement chaque mois de janvier.", "Chaque fois que l'inflation dépasse 2 %.", "À n'importe quel moment, avec un préavis d'un mois."], "a": 0, "trap": "'automatically in January' — indexation is never automatic; the landlord must ask, in writing", "expl": "Once a year, on the lease anniversary, and only if requested. Arrears can be claimed for at most the three months before the written request.", "note": "Belgian rule (art. 1728bis of the Civil Code), applied in all three regions with regional variations."}, {"id": "fvc-rent-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'indice santé", "en": "the health index", "format": "fr2en", "options": ["the inflation index used to index rents and wages", "a public-health statistic", "the energy performance score", "the cost of a health insurance policy"], "a": 0, "trap": "it sounds medical; it is the consumer price index minus tobacco, alcohol and motor fuel", "expl": "Formula: loyer de base × indice santé du mois précédant l'anniversaire ÷ indice santé du mois précédant la signature.", "note": "Belgian institution: the indice santé also drives the automatic indexation of Belgian salaries."}, {"id": "fvc-rent-B1-03", "level": "B1", "pos": "noun", "gender": "m", "fr": "le certificat PEB", "en": "the energy performance certificate", "format": "collocation", "q": "In Brussels, what happens if the landlord never gave you a valid PEB certificate?", "options": ["Il ne peut pas indexer le loyer.", "Il doit vous rembourser les charges.", "Le bail est nul.", "Il doit baisser le loyer de 10 %."], "a": 0, "trap": "assuming a missing certificate is a paperwork detail with no consequence", "expl": "No valid PEB communicated to the tenant, no indexation — whatever the flat's energy class. Ask for the certificate before you accept an increase.", "note": "Brussels rule. Leases that started before 14 October 2022 with a poor PEB can also face a correction factor."}, {"id": "fvc-rent-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "la mise en demeure", "en": "the formal notice to comply", "format": "fr2en", "options": ["a formal written demand giving a deadline to act", "an eviction order", "a reminder invoice", "a court summons"], "a": 0, "trap": "'a summons' — that is « une citation »; a mise en demeure comes before any judge is involved", "expl": "Sent « par recommandé », it fixes a date and starts the clock. Most Belgian disputes stop right here.", "note": "Belgian standard step: keep the bpost proof of posting — it is what proves the date."}, {"id": "fvc-rent-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le recommandé", "en": "the registered letter", "format": "cloze", "q": "Je vous enverrai une mise en demeure par ___ si rien n'est fait.", "options": ["recommandé", "courrier", "colis", "exprès"], "a": 0, "trap": "courrier — ordinary post, which proves nothing about when it arrived", "expl": "All four masculine. « un envoi recommandé » at bpost costs a few euros and is worth every cent in a dispute."}, {"id": "fvc-rent-B1-06", "level": "B1", "pos": "noun", "gender": "m", "fr": "le juge de paix", "en": "the local magistrate", "format": "fr2en", "options": ["the magistrate who hears rent disputes, canton by canton", "a mediator appointed by the commune", "the arbitrator chosen by both parties", "the judge who handles criminal cases"], "a": 0, "trap": "'justice of the peace' as a ceremonial figure — in Belgium this is the real court for tenancy matters", "expl": "Every Belgian canton has one. Rent, charges, repairs and guarantees all go to « la justice de paix » of the place where the flat is.", "note": "Belgian institution: proceedings can start with a simple written request, and conciliation is free."}, {"id": "fvc-rent-B1-07", "level": "B1", "pos": "noun", "gender": "m", "fr": "le congé", "en": "the notice to quit", "format": "fr2en", "options": ["notice given to end a lease", "a public holiday", "paid leave from work", "a farewell party"], "a": 0, "trap": "« les congés » means holidays — the same word does both jobs and the housing sense catches everyone out", "expl": "« donner son congé » = to give notice on a lease. « prendre congé » = to take one's leave; « les congés payés » = paid holidays."}, {"id": "fvc-rent-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le préavis", "en": "the notice period", "format": "cloze", "q": "Le ___ est de trois mois, et il commence le premier du mois suivant.", "options": ["préavis", "délai", "congé", "terme"], "a": 0, "trap": "le congé — the act of giving notice; « le préavis » is the length of it", "expl": "All four masculine. A tenant on a nine-year Brussels lease can leave at any time with three months' notice, plus an indemnity in the first three years."}, {"id": "fvc-rent-B1-09", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'indemnité de rupture", "en": "the early-termination indemnity", "format": "fr2en", "options": ["compensation paid for leaving a lease early", "a deposit returned at the end", "damages for a badly kept flat", "the last month's rent"], "a": 0, "trap": "la garantie locative — the guarantee, which is a different sum with a different fate", "expl": "On a nine-year lease ended by the tenant: three months' rent in year one, two in year two, one in year three, nothing afterwards.", "note": "Belgian rule, and one of the most useful numbers to know before you sign anything."}, {"id": "fvc-rent-B1-10", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'état des lieux de sortie", "en": "the exit inventory", "format": "collocation", "q": "What is the exit inventory compared against?", "options": ["L'état des lieux d'entrée, en tenant compte de l'usure normale.", "Le prix du loyer payé pendant le bail.", "Les photos prises par le propriétaire.", "L'état des autres appartements de l'immeuble."], "a": 0, "trap": "assuming any mark is chargeable — normal wear over years of living there is not", "expl": "Drawn up « contradictoirement » — both parties present or represented — and compared line by line with the entry document.", "note": "Belgian institution: no entry inventory means you are presumed to have received the flat in good condition."}, {"id": "fvc-rent-B1-11", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'usure normale", "en": "fair wear and tear", "format": "en2fr", "options": ["l'usure normale", "la casse volontaire", "la dégradation locative", "la remise en état"], "a": 0, "trap": "la dégradation locative — damage the tenant IS liable for; the exact thing usure normale is not", "expl": "All four feminine. Faded paint after six years is usure normale; a hole in the door is not. Also « la vétusté »."}, {"id": "fvc-rent-B1-12", "level": "B1", "pos": "noun", "gender": "m", "fr": "les dégâts locatifs", "en": "tenant damage", "format": "fr2en", "options": ["damage the tenant must pay for", "damage caused by the building itself", "storm damage", "damage found before moving in"], "a": 0, "trap": "« les dégâts des eaux » — water damage, which is usually an insurance matter rather than yours", "expl": "Deducted from the guarantee at the exit inventory, on the basis of quotes: « sur devis » or « sur facture »."}, {"id": "fvc-rent-B1-13", "level": "B1", "pos": "noun", "gender": "m", "fr": "le devis", "en": "the written quote", "format": "cloze", "q": "Le chauffagiste va établir un ___ avant de commander la pièce.", "options": ["devis", "reçu", "bilan", "relevé"], "a": 0, "trap": "le relevé — a statement or a meter reading, which is what comes later", "expl": "All four masculine. « demander trois devis » is standard practice, and free, before any significant work."}, {"id": "fvc-rent-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "les grosses réparations", "en": "major repairs", "format": "collocation", "q": "Who pays for what in a Belgian rental?", "options": ["Grosses réparations : le bailleur. Entretien courant : le preneur.", "Tout est à charge du locataire.", "Tout est à charge du propriétaire.", "Les deux partagent chaque facture par moitié."], "a": 0, "trap": "assuming the landlord covers everything because he owns the boiler — the periodic service is yours", "expl": "A dead boiler is a grosse réparation and is his. The two-yearly gas check is entretien and is yours.", "note": "Belgian rule: in Brussels the periodic PEB boiler check is the tenant's, unless the lease says otherwise."}, {"id": "fvc-rent-B1-15", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'entretien locatif", "en": "the tenant's upkeep", "format": "fr2en", "options": ["the small maintenance the tenant owes", "the interview before signing a lease", "the cleaning of the common parts", "the annual inspection by the owner"], "a": 0, "trap": "'entretien' also means an interview — the same noun does both, and you will meet the other sense in the interview topic", "expl": "Bleeding radiators, replacing seals and washers, unblocking a sink, servicing the boiler: yours. Replacing the boiler: his."}, {"id": "fvc-rent-B1-16", "level": "B1", "pos": "noun", "gender": "m", "fr": "le décompte des charges", "en": "the annual charges statement", "format": "fr2en", "options": ["the yearly reckoning of what the charges actually cost", "the monthly advance", "the rent receipt", "the bank statement"], "a": 0, "trap": "la provision — the monthly advance the décompte settles up against", "expl": "You can ask to see the supporting invoices. If the provisions were too high, the difference must be paid back to you."}, {"id": "fvc-rent-B1-17", "level": "B1", "pos": "noun", "gender": "f", "fr": "la régularisation", "en": "the settling-up", "format": "cloze", "q": "La ___ des charges se fait une fois par an, en général en mars.", "options": ["régularisation", "réglementation", "réalisation", "répartition"], "a": 0, "trap": "la réglementation — the rules; one of a family of look-alike -ation nouns", "expl": "All four feminine. « régulariser » = to bring into line, whether it is charges, a payment or an administrative situation."}, {"id": "fvc-rent-B1-18", "level": "B1", "pos": "noun", "gender": "m", "fr": "le précompte immobilier", "en": "the property tax", "format": "collocation", "q": "Who pays the précompte immobilier on a Brussels flat you rent as your home?", "options": ["Le propriétaire, et il ne peut pas vous le refacturer.", "Le locataire, avec les charges.", "Les deux, par moitié.", "Le syndic, pour tout l'immeuble."], "a": 0, "trap": "seeing it appear on a charges statement and assuming it is legitimate — for a residential lease it is not", "expl": "For housing it is the owner's tax. Only commercial leases can shift it to the tenant.", "note": "Belgian tax: if you see it in your décompte, query it in writing."}, {"id": "fvc-rent-B1-19", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'enregistrement du bail", "en": "the registration of the lease", "format": "fr2en", "options": ["the free registration of the lease by the landlord at the tax office", "the signature of the lease", "the entry in the commune's population register", "the notarial deed"], "a": 0, "trap": "the commune registration of your address — a different obligation, and yours rather than his", "expl": "For a main-residence lease it is free, it is the landlord's duty, and it protects you if the flat is sold.", "note": "Belgian obligation: an unregistered nine-year lease lets the tenant leave without notice or indemnity."}, {"id": "fvc-rent-B1-20", "level": "B1", "pos": "noun", "gender": "f", "fr": "la réduction de loyer", "en": "the rent reduction", "format": "cloze", "q": "Le juge de paix peut accorder une ___ de loyer tant que le logement n'est pas réparé.", "options": ["réduction", "suppression", "suspension", "restitution"], "a": 0, "trap": "suppression — you cannot simply stop paying, and doing so puts you in the wrong", "expl": "All four feminine. Never withhold the rent yourself: ask the juge de paix, who can reduce it or order the works."}, {"id": "fvc-rent-B1-21", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trouble de jouissance", "en": "loss of quiet enjoyment", "format": "fr2en", "options": ["an interference with your normal use of the home", "a noisy neighbour only", "a psychological problem", "a break in the lease"], "a": 0, "trap": "hearing « jouissance » as pleasure; in law it is simply the use and enjoyment of the property", "expl": "A flat without heating for weeks is a classic trouble de jouissance, and the basis for asking a rent reduction."}, {"id": "fvc-rent-B1-22", "level": "B1", "pos": "verb", "fr": "indexer", "en": "to index (the rent)", "format": "en2fr", "options": ["indexer", "augmenter", "majorer", "réviser"], "a": 0, "trap": "augmenter — a landlord cannot simply raise the rent mid-lease; indexation is the only routine mechanism", "expl": "All four infinitives. « indexer le loyer » follows a formula; « augmenter le loyer » requires a new agreement or major works."}, {"id": "fvc-rent-B1-23", "level": "B1", "pos": "verb", "fr": "remédier à", "en": "to put right", "format": "cloze", "q": "Je vous demande de ___ à ce problème dans les quinze jours.", "options": ["remédier", "résoudre", "réparer", "régler"], "a": 0, "trap": "résoudre — correct French but it takes a direct object, so the « à » in the sentence rules it out", "expl": "« remédier à » always takes à. The others are transitive: résoudre un problème, réparer la chaudière, régler la question."}, {"id": "fvc-rent-B1-24", "level": "B1", "pos": "verb", "fr": "constater", "en": "to record / establish (a fact)", "format": "fr2en", "options": ["to note officially that something is the case", "to protest about something", "to build something", "to remain constant"], "a": 0, "trap": "'to constate' does not exist in English, so learners reach for 'to complain' — which is « se plaindre »", "expl": "« faire constater les dégâts par un expert ». The noun « un constat » is also what you fill in after a car accident."}, {"id": "fvc-rent-B1-25", "level": "B1", "pos": "verb", "fr": "s'engager à", "en": "to undertake to", "format": "cloze", "q": "Vous vous étiez ___ à faire venir le chauffagiste avant le week-end.", "options": ["engagée", "obligée", "promise", "décidée"], "a": 0, "trap": "promise — French does not say « se promettre à » in this sense; « promettre de » is the shape", "expl": "All four past participles agreeing with a female subject. « s'engager à » + infinitive is the verb for a commitment made."}, {"id": "fvc-rent-B1-26", "level": "B1", "pos": "verb", "fr": "saisir", "en": "to bring a matter before (a court)", "format": "fr2en", "options": ["to refer a case to a court", "to seize property", "to grasp an idea", "to type in data"], "a": 0, "trap": "'to seize' — the same verb does that too, which is why the legal sense reads as threatening if you mistranslate it", "expl": "« saisir le juge de paix » = to put the matter to the magistrate. Neutral, procedural, and free to say out loud."}, {"id": "fvc-rent-B1-27", "level": "B1", "pos": "verb", "fr": "exiger", "en": "to demand", "format": "en2fr", "options": ["exiger", "demander", "réclamer", "solliciter"], "a": 0, "trap": "réclamer — to claim something you are owed, a notch softer and often the better word on the phone", "expl": "All four infinitives, from softest to hardest: solliciter, demander, réclamer, exiger. Choose deliberately."}, {"id": "fvc-rent-B1-28", "level": "B1", "pos": "verb", "fr": "prendre en charge", "en": "to cover the cost of", "format": "cloze", "q": "C'est au propriétaire de prendre en ___ le remplacement de la chaudière.", "options": ["charge", "compte", "main", "considération"], "a": 0, "trap": "compte — « prendre en compte » means to take into account, a completely different act", "expl": "prendre en charge = to cover or take responsibility for. prendre en compte = to take into account."}, {"id": "fvc-rent-B1-29", "level": "B1", "pos": "verb", "fr": "dénoncer", "en": "to give notice on (a lease)", "format": "fr2en", "options": ["to give formal notice ending a contract", "to report someone to the police", "to criticise publicly", "to renew a contract"], "a": 0, "trap": "'to denounce' — the everyday sense really is that, which makes the contractual use startling", "expl": "« dénoncer le bail » = to terminate it by notice. In a lease context nobody is being informed on."}, {"id": "fvc-rent-B1-30", "level": "B1", "pos": "adj", "fr": "contradictoire", "en": "carried out with both parties present", "format": "collocation", "q": "What does « un état des lieux contradictoire » mean?", "options": ["Établi en présence des deux parties, ou de leurs représentants.", "Un document qui contredit le bail.", "Un état des lieux contesté devant le juge.", "Un document rédigé par un expert indépendant."], "a": 0, "trap": "the everyday meaning of 'contradictory' — in law it means adversarial, both sides present", "expl": "The same adjective runs through Belgian procedure: « une expertise contradictoire », « un débat contradictoire »."}, {"id": "fvc-rent-B1-31", "level": "B1", "pos": "adj", "fr": "amiable", "en": "amicable, out of court", "format": "fr2en", "options": ["settled between the parties without a judge", "friendly in tone", "provisional", "unofficial and unwritten"], "a": 0, "trap": "'amiable' as a personality trait — in French this word is procedural", "expl": "« un règlement à l'amiable » = an out-of-court settlement. It can still be perfectly written and signed."}, {"id": "fvc-rent-B1-32", "level": "B1", "pos": "adj", "fr": "imputable", "en": "attributable (to someone)", "format": "cloze", "q": "Cette tache n'est pas ___ au locataire : elle vient d'une infiltration.", "options": ["imputable", "responsable", "coupable", "attribuable"], "a": 0, "trap": "responsable — people are responsible; damage is imputable to them", "expl": "All four masculine adjectives. « imputable à » is the word used in exit inventories to allocate each mark."}, {"id": "fvc-rent-B1-33", "level": "B1", "pos": "adj", "fr": "échu", "en": "fallen due", "format": "fr2en", "options": ["due and payable", "cancelled", "escaped", "overdue by more than a month"], "a": 0, "trap": "'escheated' or 'escaped' — the shape suggests échapper; it is the past participle of échoir", "expl": "« le loyer échu » = the rent now due. « le terme échu » = payment at the end of the period rather than in advance."}, {"id": "fvc-rent-B1-34", "level": "B1", "pos": "expr", "fr": "dans les meilleurs délais", "en": "as soon as possible", "format": "en2fr", "options": ["dans les meilleurs délais", "dans les plus brefs retards", "dans le meilleur délai possible", "aux meilleures dates"], "a": 0, "trap": "« dans les plus brefs retards » — a plausible-sounding invention; the real variant is « dans les plus brefs délais »", "expl": "Two fixed forms only: « dans les meilleurs délais » and « dans les plus brefs délais ». Both belong in a written mise en demeure."}, {"id": "fvc-rent-B1-35", "level": "B1", "pos": "expr", "fr": "à défaut", "en": "failing that", "format": "cloze", "q": "Merci d'intervenir avant le 15 ; ___ défaut, je saisirai le juge de paix.", "options": ["à", "en", "par", "au"], "a": 0, "trap": "au — « au défaut de » exists in old French and is not this phrase", "expl": "« à défaut » alone = failing that. « à défaut de » + noun = in the absence of. Standard in Belgian letters."}, {"id": "fvc-rent-B1-36", "level": "B1", "pos": "expr", "fr": "avoir difficile", "en": "to find something hard (Belgian French)", "format": "fr2en", "options": ["to have a hard time doing something", "to be difficult as a person", "to have a difficulty explained to you", "to make things difficult for others"], "a": 0, "trap": "standard French would need « avoir du mal à » — « avoir difficile » is not built the same way", "expl": "« J'ai difficile à dormir dans un appartement à 15 degrés. » Very common in Brussels and Wallonia.", "note": "Belgian French. France says « j'ai du mal à… » and would find « j'ai difficile » ungrammatical."}, {"id": "fvc-rent-B1-37", "level": "B1", "pos": "noun", "gender": "f", "fr": "la copropriété", "en": "the co-ownership", "format": "fr2en", "options": ["the joint ownership of a block of flats", "a jointly rented flat", "a housing cooperative", "a shared bank account"], "a": 0, "trap": "la colocation — flat-sharing between tenants, which is a different arrangement entirely", "expl": "Owners meet once a year at « l'assemblée générale » and the syndic executes the decisions. Tenants are not invited."}, {"id": "fvc-rent-B1-38", "level": "B1", "pos": "noun", "gender": "f", "fr": "les parties communes", "en": "the common parts", "format": "cloze", "q": "L'ascenseur et la cage d'escalier font partie des parties ___.", "options": ["communes", "privatives", "collectives", "publiques"], "a": 0, "trap": "privatives — the technical opposite, meaning the bits that belong to one owner alone", "expl": "All four feminine plural adjectives. Charges for the common parts are what your provision mensuelle pays for."}, {"id": "fvc-rent-B1-39", "level": "B1", "pos": "noun", "gender": "f", "fr": "la vétusté", "en": "ageing / dilapidation over time", "format": "en2fr", "options": ["la vétusté", "la vieillesse", "la vétérinaire", "la vacuité"], "a": 0, "trap": "la vieillesse — old age, of a person", "expl": "All four feminine. « un coefficient de vétusté » is applied at the exit inventory: a ten-year-old carpet is not charged as new."}, {"id": "fvc-rent-B1-40", "level": "B1", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "cloze", "q": "Avec l'indexation, le loyer passerait de huit cent septante à huit cent ___ euros.", "options": ["nonante", "septante", "quarante", "soixante"], "a": 0, "trap": "septante — it is the figure in the first half of the sentence, so choosing it makes the increase zero", "expl": "870 → 890 is about a 2,3 % indexation, a realistic Belgian year.", "note": "Belgian French. France: huit cent soixante-dix → huit cent quatre-vingt-dix."}, {"id": "fvc-rent-B1-41", "level": "B1", "pos": "noun", "gender": "f", "fr": "la date anniversaire", "en": "the anniversary date", "format": "collocation", "q": "Which date is the anniversary that matters for indexation?", "options": ["Celle de l'entrée en vigueur du bail.", "Celle de la signature du bail.", "Le 1er janvier de chaque année.", "Celle de l'état des lieux d'entrée."], "a": 0, "trap": "the signature date — often a different month, and the one landlords quote when they get it wrong", "expl": "A lease signed in March but starting in June is indexed each June. The starting index, though, is the month before signature.", "note": "Belgian rule worth checking on your own lease before you accept an indexation letter."}, {"id": "fvc-rent-B1-42", "level": "B1", "pos": "verb", "fr": "réclamer", "en": "to claim / ask for what is owed", "format": "cloze", "q": "Il ne peut pas ___ l'indexation pour toute l'année écoulée.", "options": ["réclamer", "exiger", "demander", "obtenir"], "a": 0, "trap": "exiger — grammatically fine and stronger than the law allows him to be", "expl": "All four infinitives. Arrears of indexation can only be claimed for the three months preceding the written request."}, {"id": "fvc-rent-B1-43", "level": "B1", "pos": "noun", "gender": "f", "fr": "la restitution de la garantie", "en": "the release of the guarantee", "format": "collocation", "q": "In Brussels, when must the rent guarantee be released?", "options": ["Dans les deux mois de la remise des clés, sinon 10 % du loyer par mois de retard.", "Dans les six mois de la fin du bail.", "Dès la signature de l'état des lieux de sortie.", "Il n'y a pas de délai légal."], "a": 0, "trap": "'no legal deadline' — true before the 2024 reform and the reason landlords still delay", "expl": "Two months from the handover of the keys, with a penalty of 10 % of the monthly rent for each month of delay.", "note": "Brussels rule since 1 November 2024."}, {"id": "fvc-rent-B1-44", "level": "B1", "pos": "noun", "gender": "m", "fr": "le locataire sortant", "en": "the outgoing tenant", "format": "en2fr", "options": ["le locataire sortant", "le locataire entrant", "le colocataire", "le sous-locataire"], "a": 0, "trap": "le locataire entrant — the person moving in, whose entry inventory is the mirror of your exit one", "expl": "All four masculine. « le locataire sortant » remits the keys; from that date the two-month guarantee clock runs."}, {"id": "fvc-rent-B1-45", "level": "B1", "pos": "expr", "fr": "par courrier recommandé", "en": "by registered post", "format": "cloze", "q": "Toute résiliation doit se faire ___ courrier recommandé.", "options": ["par", "en", "avec", "sur"], "a": 0, "trap": "en — « en recommandé » is heard in speech, but the written form in a lease is « par »", "expl": "« par courrier recommandé », « par voie recommandée », « par lettre recommandée » — all fine; the preposition is par."}, {"id": "fvc-rent-B1-46", "level": "B1", "pos": "noun", "gender": "f", "fr": "la trace écrite", "en": "the written record", "format": "fr2en", "options": ["written evidence of what was agreed", "a handwritten signature", "a rough draft", "a paper trail left by a bank"], "a": 0, "trap": "'a written trace' sounds informal in English; in French it is exactly what people say about keeping proof", "expl": "« Je préfère avoir une trace écrite » — the politest possible way to insist on an email confirmation."}], "phrases": [{"id": "ph-rent-B1-01", "fr": "Je vous rappelle au sujet de la chaudière, qui est toujours en panne.", "en": "I'm calling you back about the boiler, which is still out of order.", "note": "« au sujet de » is neutral and precise. « toujours » here means 'still', not 'always' — context decides."}, {"id": "ph-rent-B1-02", "fr": "Cela fait huit jours que je suis sans chauffage.", "en": "It's been eight days now that I've had no heating.", "note": "« Cela fait X que » + present is the standard way to count how long a situation has lasted. « Ça fait » in speech."}, {"id": "ph-rent-B1-03", "fr": "Je vous avais déjà signalé le problème mardi dernier, puis vendredi.", "en": "I had already reported the problem to you last Tuesday, then on Friday.", "note": "The pluperfect « je vous avais signalé » plus two dates is the whole argument. Keep a note of when you called."}, {"id": "ph-rent-B1-04", "fr": "Vous vous étiez engagée à faire venir un chauffagiste avant le week-end.", "en": "You had undertaken to get a heating engineer out before the weekend.", "note": "« s'engager à » + infinitive. Said calmly, this is the most effective sentence in the call."}, {"id": "ph-rent-B1-05", "fr": "Le remplacement de la chaudière est une grosse réparation, donc à votre charge.", "en": "Replacing the boiler is a major repair, so it's for you to pay.", "note": "Belgian split: grosses réparations to the landlord, entretien courant to the tenant. Naming the category ends the argument."}, {"id": "ph-rent-B1-06", "fr": "J'ai bien fait entretenir la chaudière l'an dernier, j'ai l'attestation.", "en": "I did have the boiler serviced last year, I have the certificate.", "note": "Brussels requires a PEB check every two years for gas, every year for oil — normally at the tenant's cost. Keep the certificate."}, {"id": "ph-rent-B1-07", "fr": "Si rien n'est fait d'ici vendredi, je vous enverrai une mise en demeure par recommandé.", "en": "If nothing is done by Friday, I'll send you a formal notice by registered post.", "note": "Say it once, without heat, with a date. « d'ici vendredi » = by Friday at the latest."}, {"id": "ph-rent-B1-08", "fr": "Je ne veux pas en arriver là, mais je dois pouvoir me chauffer.", "en": "I don't want it to come to that, but I have to be able to heat the place.", "note": "« en arriver là » = to reach that point. It softens the threat while leaving it standing."}, {"id": "ph-rent-B1-09", "fr": "Je continuerai bien sûr à payer le loyer, comme d'habitude.", "en": "I'll of course carry on paying the rent, as usual.", "note": "Important legally and tactically: never stop paying. A rent reduction is granted by the juge de paix, not taken by you."}, {"id": "ph-rent-B1-10", "fr": "J'ai reçu votre lettre d'indexation, mais je voudrais vérifier le calcul.", "en": "I received your indexation letter, but I'd like to check the calculation.", "note": "Perfectly normal and expected. The formula is public: base rent × new health index ÷ starting health index."}, {"id": "ph-rent-B1-11", "fr": "L'indexation se fait à la date anniversaire de l'entrée en vigueur du bail, pas à la signature.", "en": "Indexation happens on the anniversary of the lease taking effect, not of the signature.", "note": "A very common landlord error when the two dates differ by a few months. Check your own lease."}, {"id": "ph-rent-B1-12", "fr": "Je n'ai jamais reçu de certificat PEB pour l'appartement.", "en": "I've never received an energy performance certificate for the flat.", "note": "In Brussels, no valid PEB communicated to the tenant means no indexation at all. Say it early in that conversation."}, {"id": "ph-rent-B1-13", "fr": "Est-ce que vous pouvez m'envoyer une copie du décompte des charges ?", "en": "Could you send me a copy of the charges statement?", "note": "You may also ask to see the underlying invoices. If the provisions were too high, the surplus comes back to you."}, {"id": "ph-rent-B1-14", "fr": "Le précompte immobilier ne peut pas être mis à ma charge, c'est un bail d'habitation.", "en": "The property tax can't be charged to me, this is a residential lease.", "note": "Accurate and worth knowing: only commercial leases can pass it to the tenant. Query it in writing if it appears."}, {"id": "ph-rent-B1-15", "fr": "Mon bail se termine en juin ; je vous donnerai mon congé par recommandé.", "en": "My lease ends in June; I'll give you notice by registered post.", "note": "« donner son congé » = to give notice. « le congé » here has nothing to do with holidays."}, {"id": "ph-rent-B1-16", "fr": "On fixe l'état des lieux de sortie ensemble, une fois l'appartement vide ?", "en": "Shall we arrange the exit inventory together, once the flat is empty?", "note": "It must be « contradictoire » — both parties present. Do it after the removal, not before, and read every line."}, {"id": "ph-rent-B1-17", "fr": "Cette trace sur le mur relève de l'usure normale, pas des dégâts locatifs.", "en": "That mark on the wall is fair wear and tear, not tenant damage.", "note": "« relever de » = to fall under. The distinction decides how much of your guarantee comes back."}, {"id": "ph-rent-B1-18", "fr": "La garantie doit être libérée dans les deux mois de la remise des clés.", "en": "The guarantee has to be released within two months of the keys being handed back.", "note": "Brussels rule since November 2024, with a 10 % penalty per month of delay. Worth quoting politely."}, {"id": "ph-rent-B1-19", "fr": "Je préfère qu'on règle ça à l'amiable, mais je veux une trace écrite.", "en": "I'd rather we settle this amicably, but I want it in writing.", "note": "« régler à l'amiable » = to settle out of court. Wanting a written record is not hostile; it is Belgian."}, {"id": "ph-rent-B1-20", "fr": "Merci de me confirmer tout cela par mail dans les meilleurs délais.", "en": "Please confirm all that to me by email as soon as possible.", "note": "« Merci de » + infinitive is the polite imperative of Belgian and French business writing. Firm without being rude."}], "dialogue": [{"who": "landlord", "fr": "Allô ? Ah, monsieur Vasileiadis. Vous avez reçu ma lettre pour l'indexation ?", "en": "Hello? Ah, Mr Vasileiadis. Did you get my letter about the indexation?", "gloss": {"indexation": "annual rent indexation"}}, {"who": "you", "fr": "Oui, je l'ai reçue, et j'y viendrai. Mais je vous rappelle d'abord au sujet de la chaudière : cela fait huit jours que je suis sans chauffage.", "en": "Yes, I got it, and I'll come to it. But I'm calling you back first about the boiler: it's been eight days now that I've had no heating.", "gloss": {"j'y viendrai": "I'll come to it", "au sujet de": "about", "cela fait huit jours que": "it's been eight days that"}, "accept": ["oui je l'ai reçue et j'y viendrai mais je vous rappelle d'abord au sujet de la chaudière cela fait huit jours que je suis sans chauffage", "oui je l'ai reçue mais je vous rappelle d'abord au sujet de la chaudière cela fait huit jours que je suis sans chauffage", "oui je l'ai bien reçue mais d'abord la chaudière ça fait huit jours que je suis sans chauffage", "oui je l'ai reçue on en reparlera mais je vous appelle surtout pour la chaudière cela fait huit jours que je n'ai plus de chauffage", "oui mais avant tout je vous rappelle pour la chaudière cela fait huit jours que je suis sans chauffage", "je l'ai reçue oui mais je vous rappelle d'abord pour la chaudière je suis sans chauffage depuis huit jours"]}, {"who": "landlord", "fr": "Ah oui, la chaudière… J'ai essayé d'appeler le chauffagiste, mais il ne répond pas.", "en": "Ah yes, the boiler… I tried to call the heating engineer, but he isn't answering.", "gloss": {"essayé": "tried", "répond": "answers"}}, {"who": "you", "fr": "Je vous avais déjà signalé le problème mardi dernier, puis vendredi. Vous vous étiez engagée à faire venir quelqu'un avant le week-end.", "en": "I had already reported the problem to you last Tuesday, then on Friday. You had undertaken to get someone out before the weekend.", "gloss": {"faire venir": "to get someone to come", "avais déjà signalé": "had reported", "Vous vous étiez engagée": "you had undertaken"}, "accept": ["je vous avais déjà signalé le problème mardi dernier puis vendredi vous vous étiez engagée à faire venir quelqu'un avant le week-end", "je vous avais déjà signalé le problème mardi dernier puis vendredi", "je vous avais signalé le problème mardi et vendredi et vous vous étiez engagée à envoyer quelqu'un avant le week-end", "je vous ai déjà appelée mardi et vendredi vous vous étiez engagée à faire venir un chauffagiste", "je vous avais prévenue mardi dernier et vendredi vous aviez promis d'envoyer quelqu'un avant le week-end", "c'est la troisième fois je vous avais signalé le problème mardi puis vendredi"]}, {"who": "landlord", "fr": "Je sais, je sais. Mais vous savez, une chaudière, ce n'est pas moi qui peux la réparer.", "en": "I know, I know. But you know, a boiler isn't something I can repair myself.", "gloss": {"vous savez": "you know", "réparer": "to repair"}}, {"who": "you", "fr": "Bien sûr. Mais le remplacement de la chaudière est une grosse réparation : c'est à votre charge, et il faut y remédier dans un délai raisonnable.", "en": "Of course. But replacing the boiler is a major repair: it's for you to pay, and it has to be put right within a reasonable time.", "gloss": {"grosse réparation": "major repair", "à votre charge": "for you to pay", "y remédier": "to put it right", "délai raisonnable": "reasonable time"}, "accept": ["bien sûr mais le remplacement de la chaudière est une grosse réparation c'est à votre charge et il faut y remédier dans un délai raisonnable", "bien sûr mais le remplacement de la chaudière est une grosse réparation c'est à votre charge", "je comprends mais la chaudière c'est une grosse réparation donc c'est à votre charge", "bien sûr mais les grosses réparations sont à charge du propriétaire et il faut y remédier dans un délai raisonnable", "je sais mais la chaudière est une grosse réparation elle est à votre charge il faut la faire réparer rapidement", "bien entendu mais c'est une grosse réparation donc à votre charge et dans un délai raisonnable"]}, {"who": "landlord", "fr": "Et l'entretien, vous l'avez fait, vous ? Parce que si la panne vient d'un manque d'entretien…", "en": "And the servicing, have you had it done? Because if the breakdown comes from a lack of maintenance…", "gloss": {"entretien": "servicing, upkeep", "manque": "lack"}}, {"who": "you", "fr": "J'ai fait entretenir la chaudière l'an dernier, comme prévu, et j'ai l'attestation du technicien. Je peux vous l'envoyer par mail.", "en": "I had the boiler serviced last year, as required, and I have the technician's certificate. I can send it to you by email.", "gloss": {"fait entretenir": "had it serviced", "comme prévu": "as required, as planned", "attestation": "certificate"}, "accept": ["j'ai fait entretenir la chaudière l'an dernier comme prévu et j'ai l'attestation du technicien je peux vous l'envoyer par mail", "j'ai fait entretenir la chaudière l'an dernier et j'ai l'attestation du technicien", "oui j'ai fait l'entretien l'an dernier et j'ai l'attestation je peux vous l'envoyer par mail", "j'ai fait entretenir la chaudière l'année dernière j'ai le document du technicien", "oui l'entretien a été fait l'an dernier j'ai l'attestation et je peux vous l'envoyer", "j'ai bien fait entretenir la chaudière l'an dernier j'ai l'attestation du chauffagiste"]}, {"who": "landlord", "fr": "Bon. Alors je vais rappeler quelqu'un d'autre demain matin, promis.", "en": "Right. Then I'll call someone else tomorrow morning, I promise.", "gloss": {"quelqu'un d'autre": "someone else", "promis": "I promise"}}, {"who": "you", "fr": "Merci. Je vous le dis sans agressivité : si rien n'est fait d'ici vendredi, je vous enverrai une mise en demeure par recommandé.", "en": "Thank you. I'm saying this without any aggression: if nothing is done by Friday, I'll send you a formal notice by registered post.", "gloss": {"sans agressivité": "without aggression", "d'ici vendredi": "by Friday", "mise en demeure": "formal notice to comply", "recommandé": "registered letter"}, "accept": ["merci je vous le dis sans agressivité si rien n'est fait d'ici vendredi je vous enverrai une mise en demeure par recommandé", "merci si rien n'est fait d'ici vendredi je vous enverrai une mise en demeure par recommandé", "merci je vous préviens sans agressivité si rien n'est fait d'ici vendredi j'enverrai une mise en demeure par recommandé", "merci je ne veux pas être désagréable mais si rien n'est fait vendredi j'enverrai une mise en demeure par recommandé", "merci beaucoup mais si rien n'est fait d'ici vendredi je devrai vous envoyer une mise en demeure par recommandé", "merci je vous le dis calmement si personne ne vient d'ici vendredi je vous enverrai un recommandé"]}, {"who": "landlord", "fr": "Oh là, ce n'est pas la peine d'aller jusque-là, monsieur.", "en": "Oh dear, there's no need to go that far.", "gloss": {"ce n'est pas la peine": "there's no need", "jusque-là": "that far"}}, {"who": "you", "fr": "Je ne veux pas en arriver là non plus. Et je continuerai bien sûr à payer le loyer, comme d'habitude — mais j'ai difficile à dormir à quinze degrés.", "en": "I don't want it to come to that either. And I'll of course carry on paying the rent, as usual — but I'm finding it hard to sleep at fifteen degrees.", "gloss": {"en arriver là": "to reach that point", "comme d'habitude": "as usual", "j'ai difficile": "I find it hard (Belgian French; France: j'ai du mal)"}, "accept": ["je ne veux pas en arriver là non plus et je continuerai bien sûr à payer le loyer comme d'habitude mais j'ai difficile à dormir à quinze degrés", "je ne veux pas en arriver là non plus et je continuerai à payer le loyer comme d'habitude", "moi non plus je ne veux pas en arriver là je paierai le loyer comme d'habitude mais j'ai difficile à dormir à quinze degrés", "je ne veux pas en arriver là je continue à payer le loyer normalement mais il fait quinze degrés chez moi", "je préfère éviter ça et je continuerai à payer le loyer mais j'ai difficile à dormir dans le froid", "moi non plus mais je continue à payer le loyer comme d'habitude et j'ai vraiment difficile à dormir"]}, {"who": "landlord", "fr": "Je comprends. Bon, et pour l'indexation, vous êtes d'accord ? Huit cent nonante euros à partir du mois prochain.", "en": "I understand. Right, and about the indexation, are you all right with it? Eight hundred and ninety euros from next month.", "gloss": {"nonante": "ninety (Belgian French; France: quatre-vingt-dix)", "à partir du": "from"}}, {"who": "you", "fr": "Je voudrais d'abord vérifier deux choses. D'une part, la date anniversaire du bail, c'est l'entrée en vigueur, donc juin, et pas la signature en mars. D'autre part, je n'ai jamais reçu de certificat PEB : à Bruxelles, sans certificat valable, l'indexation n'est pas possible.", "en": "I'd like to check two things first. On the one hand, the lease anniversary is when it took effect, so June, not the signature in March. On the other hand, I've never received an energy performance certificate: in Brussels, without a valid certificate, indexation isn't possible.", "gloss": {"vérifier": "to check", "date anniversaire": "anniversary date", "entrée en vigueur": "date it took effect", "certificat PEB": "energy performance certificate", "valable": "valid"}, "accept": ["je voudrais d'abord vérifier deux choses d'une part la date anniversaire du bail c'est l'entrée en vigueur donc juin et pas la signature en mars d'autre part je n'ai jamais reçu de certificat peb à bruxelles sans certificat valable l'indexation n'est pas possible", "je voudrais vérifier deux choses la date anniversaire c'est l'entrée en vigueur en juin pas la signature et je n'ai jamais reçu de certificat peb", "j'aimerais vérifier deux choses d'abord la date anniversaire du bail c'est juin et ensuite je n'ai jamais reçu de certificat peb sans lequel l'indexation n'est pas possible", "avant d'accepter je voudrais vérifier la date anniversaire c'est l'entrée en vigueur en juin et je n'ai jamais reçu de certificat peb", "je voudrais d'abord vérifier deux choses la date anniversaire du bail et le certificat peb que je n'ai jamais reçu", "deux choses la date anniversaire c'est l'entrée en vigueur donc juin et je n'ai jamais reçu de certificat peb donc vous ne pouvez pas indexer"]}, {"who": "landlord", "fr": "Alors ça, je ne le savais pas du tout. Je vais me renseigner auprès de mon agence.", "en": "Now that, I really didn't know. I'll check with my agency.", "gloss": {"du tout": "at all", "me renseigner": "to find out", "auprès de": "with, from"}}, {"who": "you", "fr": "C'est le plus simple. Je préfère qu'on règle tout ça à l'amiable, mais j'aimerais une trace écrite : vous pouvez me confirmer par mail dans les meilleurs délais ?", "en": "That's the simplest thing. I'd rather we settled all this amicably, but I'd like a written record: could you confirm to me by email as soon as possible?", "gloss": {"à l'amiable": "amicably, out of court", "trace écrite": "written record", "dans les meilleurs délais": "as soon as possible"}, "accept": ["c'est le plus simple je préfère qu'on règle tout ça à l'amiable mais j'aimerais une trace écrite vous pouvez me confirmer par mail dans les meilleurs délais", "je préfère qu'on règle tout ça à l'amiable mais j'aimerais une trace écrite vous pouvez me confirmer par mail", "c'est le plus simple je préfère régler ça à l'amiable mais je voudrais une confirmation par mail", "d'accord je préfère un arrangement à l'amiable mais avec une trace écrite pouvez-vous me confirmer par mail", "c'est mieux comme ça je préfère l'amiable mais merci de me confirmer tout cela par mail rapidement", "c'est le plus simple mais j'aimerais une trace écrite confirmez-moi tout ça par mail s'il vous plaît"]}, {"who": "landlord", "fr": "D'accord, je vous écris demain avec le nom du chauffagiste et la réponse de l'agence pour le PEB.", "en": "All right, I'll write to you tomorrow with the heating engineer's name and the agency's answer about the PEB.", "gloss": {"je vous écris": "I'll write to you", "réponse": "answer"}}, {"who": "you", "fr": "Parfait, merci. Une dernière chose : mon bail se termine en juin, on fixera l'état des lieux de sortie une fois l'appartement vide.", "en": "Perfect, thank you. One last thing: my lease ends in June, we'll arrange the exit inventory once the flat is empty.", "gloss": {"se termine": "ends", "on fixera": "we'll arrange", "état des lieux de sortie": "exit inventory", "vide": "empty"}, "accept": ["parfait merci une dernière chose mon bail se termine en juin on fixera l'état des lieux de sortie une fois l'appartement vide", "parfait merci mon bail se termine en juin on fixera l'état des lieux de sortie une fois l'appartement vide", "merci et dernière chose mon bail se termine en juin il faudra fixer l'état des lieux de sortie", "parfait merci beaucoup et mon bail se termine en juin on fera l'état des lieux de sortie quand l'appartement sera vide", "merci une dernière chose pour la fin du bail en juin on fixera l'état des lieux de sortie ensemble", "parfait merci et pour juin on fixera l'état des lieux de sortie une fois que j'aurai déménagé"]}, {"who": "landlord", "fr": "Très bien. On fera ça ensemble, avec le relevé des compteurs. Bonne soirée, monsieur.", "en": "Very good. We'll do it together, with the meter readings. Have a good evening.", "gloss": {"relevé des compteurs": "meter readings", "ensemble": "together"}}, {"who": "you", "fr": "Bonne soirée à vous aussi. Et merci de vous en occuper pour la chaudière.", "en": "Have a good evening too. And thank you for dealing with the boiler.", "gloss": {"vous en occuper": "to deal with it"}, "accept": ["bonne soirée à vous aussi et merci de vous en occuper pour la chaudière", "bonne soirée à vous aussi merci de vous en occuper", "bonne soirée madame et merci de vous occuper de la chaudière", "merci de vous en occuper bonne soirée à vous aussi", "bonne soirée à vous et merci beaucoup de vous en occuper pour la chaudière", "merci d'avance pour la chaudière bonne soirée à vous"]}], "exercises": [{"id": "ex-rent-B1-01", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'indexation", "en": "the rent indexation", "format": "collocation", "q": "Your landlord asks for twelve months of back-dated indexation. What can he actually claim?", "options": ["Au maximum les trois mois précédant sa demande écrite.", "Les douze mois, l'indexation étant automatique.", "Rien du tout, l'indexation étant interdite en cours de bail.", "Six mois, comme pour les charges."], "a": 0, "trap": "'it's automatic so he can claim it all' — the most common belief and the wrong one", "expl": "Indexation must be requested; arrears go back three months from the written request, no further.", "note": "Belgian rule (art. 1728bis). Check the date on his letter before you pay anything."}, {"id": "ex-rent-B1-02", "level": "B1", "pos": "noun", "gender": "m", "fr": "le certificat PEB", "en": "the energy certificate", "format": "cloze", "q": "Sans ___ valable, le bailleur bruxellois ne peut pas indexer le loyer.", "options": ["certificat PEB", "état des lieux", "décompte de charges", "contrat d'assurance"], "a": 0, "trap": "l'état des lieux — compulsory for the lease, but not the condition attached to indexation", "expl": "PEB = performance énergétique des bâtiments. It must actually have been communicated to the tenant, not merely exist.", "note": "Brussels rule; the other regions handle poor energy classes differently."}, {"id": "ex-rent-B1-03", "level": "B1", "pos": "noun", "gender": "f", "fr": "la mise en demeure", "en": "the formal notice", "format": "en2fr", "options": ["la mise en demeure", "la mise à jour", "la mise en garde", "la mise au point"], "a": 0, "trap": "la mise en garde — a warning, which is close in feel and has no legal effect", "expl": "All four feminine « mise en/à » phrases. Only the mise en demeure sets a deadline and starts the legal clock.", "note": "Belgian practice: send it par recommandé and keep the bpost receipt."}, {"id": "ex-rent-B1-04", "level": "B1", "pos": "noun", "gender": "m", "fr": "le juge de paix", "en": "the local magistrate", "format": "collocation", "q": "Your flat has had no heating for a month. What is the correct step?", "options": ["Mise en demeure, puis saisir le juge de paix pour obtenir les travaux ou une réduction de loyer.", "Arrêter de payer le loyer jusqu'aux réparations.", "Payer la réparation et déduire la facture du loyer sans accord.", "Résilier le bail immédiatement sans préavis."], "a": 0, "trap": "withholding the rent — it feels like leverage and it puts you in breach of your own obligation", "expl": "Keep paying, document everything, then let the juge de paix reduce the rent or order the work.", "note": "Belgian procedure: the justice de paix of the flat's canton, and conciliation there is free."}, {"id": "ex-rent-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le congé", "en": "notice to quit", "format": "fr2en", "options": ["formal notice ending a lease", "annual holiday", "a day off", "a leaving party"], "a": 0, "trap": "'holiday' — the sense you already know, and useless in a lease conversation", "expl": "« donner son congé » = to give notice. Belgian nine-year lease: three months' notice, plus an indemnity in the first three years."}, {"id": "ex-rent-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'usure normale", "en": "fair wear and tear", "format": "collocation", "q": "Which one can be deducted from your guarantee at the exit inventory?", "options": ["Un trou dans la porte de la cuisine", "La peinture ternie après six ans", "Un joint de silicone jauni", "Une moquette usée par le passage"], "a": 0, "trap": "the last three all look like damage and are all normal ageing after several years", "expl": "Wear from ordinary living is not chargeable; a « coefficient de vétusté » is applied to anything that is.", "note": "Belgian exit-inventory practice: disagree in writing on the document itself rather than signing and complaining later."}, {"id": "ex-rent-B1-07", "level": "B1", "pos": "verb", "fr": "remédier à", "en": "to put right", "format": "cloze", "q": "Je vous demande de remédier ___ cette situation avant le 15.", "options": ["à", "de", "pour", "sur"], "a": 0, "trap": "de — the preposition most learners default to after a verb of asking", "expl": "« remédier à » always takes à: remédier à un problème, à une situation, à un défaut."}, {"id": "ex-rent-B1-08", "level": "B1", "pos": "noun", "gender": "f", "fr": "les grosses réparations", "en": "major repairs", "format": "cloze", "q": "Les grosses réparations sont à charge du ___, l'entretien courant à charge du preneur.", "options": ["bailleur", "preneur", "syndic", "locataire"], "a": 0, "trap": "locataire — the same person as « le preneur », so choosing it makes the sentence say both halves are yours", "expl": "In lease language: le bailleur = landlord, le preneur = tenant. The two words are worth learning as a pair.", "note": "Belgian split confirmed by the Civil Code and by every Brussels lease."}, {"id": "ex-rent-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "le précompte immobilier", "en": "the property tax", "format": "fr2en", "options": ["the annual tax on property, payable by the owner", "the withholding tax on your salary", "the registration fee for the lease", "the municipal waste tax"], "a": 0, "trap": "le précompte professionnel — the payroll withholding tax; the two share a word and nothing else", "expl": "For a residential lease it cannot be passed to the tenant. Only commercial leases can shift it.", "note": "Belgian tax: query it in writing if it ever appears in your décompte des charges."}, {"id": "ex-rent-B1-10", "level": "B1", "pos": "expr", "fr": "avoir difficile", "en": "to find it hard (Belgian French)", "format": "collocation", "q": "« J'ai difficile à me chauffer » — how would you say this in France?", "options": ["J'ai du mal à me chauffer.", "Je suis difficile à me chauffer.", "J'ai difficulté de me chauffer.", "Il m'est difficile me chauffer."], "a": 0, "trap": "trying to keep « difficile » in the sentence — standard French rebuilds it around « du mal »", "expl": "Belgian: avoir difficile / avoir facile. Standard: avoir du mal à, ou trouver cela facile.", "note": "Belgian French, extremely common in Brussels and Wallonia, unknown in France."}, {"id": "ex-rent-B1-11", "level": "B1", "pos": "noun", "gender": "f", "fr": "la restitution de la garantie", "en": "release of the guarantee", "format": "cloze", "q": "La garantie doit être libérée dans les ___ mois de la remise des clés.", "options": ["deux", "six", "trois", "douze"], "a": 0, "trap": "three months — the figure people remember from older leases and from other regions", "expl": "Brussels, since 1 November 2024: two months, then a penalty of 10 % of the monthly rent for each month of delay.", "note": "Brussels rule; Flanders and Wallonia differ."}, {"id": "ex-rent-B1-12", "level": "B1", "pos": "verb", "fr": "s'engager à", "en": "to undertake to", "format": "en2fr", "options": ["s'engager à", "s'occuper de", "se charger que", "s'obliger pour"], "a": 0, "trap": "s'occuper de — 'to deal with', which describes the action rather than the promise", "expl": "« Vous vous étiez engagée à… » puts a promise on the record without accusing anyone of lying."}, {"id": "ex-rent-B1-13", "level": "B1", "pos": "adj", "fr": "contradictoire", "en": "with both parties present", "format": "fr2en", "options": ["carried out with both sides present", "self-contradictory", "disputed in court", "written by an independent expert"], "a": 0, "trap": "the everyday English meaning, which is right about words and wrong about procedure", "expl": "« un état des lieux contradictoire » is the only kind that protects you. Never accept one drawn up in your absence."}, {"id": "ex-rent-B1-14", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'enregistrement du bail", "en": "registration of the lease", "format": "collocation", "q": "Who must register a Belgian main-residence lease, and at what cost?", "options": ["Le bailleur, gratuitement.", "Le locataire, gratuitement.", "Les deux, à frais partagés.", "Le notaire, contre honoraires."], "a": 0, "trap": "assuming a shared cost, as with the état des lieux — the registration itself is free and his job", "expl": "The état des lieux is annexed and registered with it. An unregistered nine-year lease lets the tenant leave without notice or indemnity.", "note": "Belgian obligation on the landlord; the tenant may register it himself if the landlord will not."}]},
  "interview-A2": {"slug": "interview", "level": "A2", "title": "Un premier entretien d'embauche", "place": "Bureaux de Verbeeck & Partners, avenue Louise, Ixelles", "register": "vous", "registerNote": "Vous throughout, in both directions, and it stays vous even if the recruiter is your age and the office has table football. In Belgium tu may appear on your first day among colleagues; it never appears in an interview. Wait for the other person to propose it, and only after you are hired.", "vocab": [{"id": "fvc-interview-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'entretien", "en": "the interview", "format": "fr2en", "options": ["a job interview or formal meeting", "the maintenance of a machine", "a conversation between friends", "a press article"], "a": 0, "trap": "« l'entretien » also means upkeep — « l'entretien de la chaudière »; one noun, two worlds", "expl": "« un entretien d'embauche » = a job interview. A journalist's interview is « une interview », borrowed from English."}, {"id": "fvc-interview-A2-02", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'embauche", "en": "the hiring", "format": "en2fr", "options": ["l'embauche", "l'ébauche", "l'embouchure", "l'emballage"], "a": 0, "trap": "l'ébauche — a rough draft or outline; one letter and a different world", "expl": "All four feminine. « un entretien d'embauche ». The verb is « embaucher » or, in Belgium more often, « engager »."}, {"id": "fvc-interview-A2-03", "level": "A2", "pos": "verb", "fr": "engager", "en": "to hire (Belgian usage)", "format": "collocation", "q": "Which sentence would a Brussels employer be most likely to say?", "options": ["Nous cherchons à engager un gestionnaire de dossiers.", "Nous cherchons à embaucher un gestionnaire de dossiers.", "Nous cherchons à recruter à engager un gestionnaire.", "Nous cherchons à employer un gestionnaire de dossiers."], "a": 0, "trap": "« embaucher » is perfectly correct French and is simply less used in Belgian job ads", "expl": "Belgian ads and HR people say « engager » and « une entrée en fonction ». All the others are understood.", "note": "Belgian usage. France leans on « embaucher » and « recruter »."}, {"id": "fvc-interview-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le poste", "en": "the position / job", "format": "fr2en", "options": ["the job or position", "the post office", "the postal delivery", "the workstation only"], "a": 0, "trap": "la poste — feminine, the post office; « le poste » masculine is the job (and also a TV set)", "expl": "Gender changes the meaning: LE poste = the job; LA poste = the post office. Belgium's postal operator is bpost."}, {"id": "fvc-interview-A2-05", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'offre d'emploi", "en": "the job advert", "format": "en2fr", "options": ["l'offre d'emploi", "la demande d'emploi", "la recherche d'emploi", "la perte d'emploi"], "a": 0, "trap": "la demande d'emploi — that is the jobseeker's side; the advert is the employer's offer", "expl": "All four feminine. « J'ai vu votre offre d'emploi sur le site d'Actiris. »"}, {"id": "fvc-interview-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "Actiris", "en": "the Brussels employment service", "format": "collocation", "q": "You are looking for work in Brussels. Which service do you register with?", "options": ["Actiris", "Le Forem", "Le VDAB", "L'ONEM seul"], "a": 0, "trap": "Le Forem — the right answer if you lived in Namur or Liège, and the wrong one in Brussels", "expl": "Actiris covers the Brussels-Capital Region, Le Forem covers Wallonia, VDAB covers Flanders. ONEM/RVA pays the benefit, but you register with the regional service.", "note": "Belgian institutions with no French equivalent — France has France Travail (ex-Pôle emploi)."}, {"id": "fvc-interview-A2-07", "level": "A2", "pos": "noun", "gender": "m", "fr": "le CV", "en": "the CV", "format": "cloze", "q": "J'ai envoyé mon ___ et une lettre de motivation par mail.", "options": ["CV", "diplôme", "contrat", "dossier"], "a": 0, "trap": "le dossier — the whole file, which is what the two documents together become", "expl": "All four masculine. Pronounced « cé-vé ». In Belgium a CV is two pages, no photo required, and languages come near the top."}, {"id": "fvc-interview-A2-08", "level": "A2", "pos": "noun", "gender": "f", "fr": "la lettre de motivation", "en": "the covering letter", "format": "fr2en", "options": ["the covering letter", "a reference from a former boss", "a motivational speech", "the acceptance letter"], "a": 0, "trap": "« une lettre de recommandation » — a reference, written by someone else about you", "expl": "Belgian practice: one page, addressed to a named person, and it should say why this employer, not just why you."}, {"id": "fvc-interview-A2-09", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'expérience", "en": "the experience", "format": "cloze", "q": "J'ai trois ans d'___ dans la gestion de dossiers.", "options": ["expérience", "expertise", "expression", "exigence"], "a": 0, "trap": "l'expertise — a real word, and it claims far more than three years usually justifies", "expl": "All four feminine nouns starting with a vowel. « avoir de l'expérience dans / en » + field."}, {"id": "fvc-interview-A2-10", "level": "A2", "pos": "noun", "gender": "f", "fr": "la formation", "en": "the education / training", "format": "fr2en", "options": ["your education and training", "the shape of something", "the team line-up", "a training session only"], "a": 0, "trap": "'formation' in the military or geological sense — French uses the word almost entirely for education", "expl": "« Quelle est votre formation ? » asks about your studies. « une formation continue » is ongoing professional training."}, {"id": "fvc-interview-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le diplôme", "en": "the degree / diploma", "format": "en2fr", "options": ["le diplôme", "le certificat", "le brevet", "le bulletin"], "a": 0, "trap": "le bulletin — the school report with your marks on it, not the qualification", "expl": "All four masculine. Foreign degrees often need « une équivalence » from the Fédération Wallonie-Bruxelles to count for Belgian public jobs.", "note": "Belgian procedure: the equivalence file takes months, so start it before you need it."}, {"id": "fvc-interview-A2-12", "level": "A2", "pos": "noun", "gender": "m", "fr": "le stage", "en": "the internship", "format": "fr2en", "options": ["an internship or work placement", "a stage in a theatre", "a step in a process", "a training course you attend"], "a": 0, "trap": "the English 'stage' — a genuine false friend, and the theatre one is « la scène »", "expl": "« J'ai fait un stage de six mois à la Commission. » The person doing it is « un stagiaire »."}, {"id": "fvc-interview-A2-13", "level": "A2", "pos": "noun", "gender": "f", "fr": "les compétences", "en": "the skills", "format": "fr2en", "options": ["the skills you bring", "the competitors", "the responsibilities of a court", "the qualifications on paper"], "a": 0, "trap": "les concurrents — competitors; and in law « la compétence » is jurisdiction, which is a third meaning", "expl": "« Quelles sont vos principales compétences ? » Answer with verbs: « je sais gérer », « je maîtrise Excel »."}, {"id": "fvc-interview-A2-14", "level": "A2", "pos": "noun", "gender": "m", "fr": "le néerlandais", "en": "Dutch", "format": "collocation", "q": "Which combination is the real advantage on the Brussels job market?", "options": ["français + néerlandais + anglais", "français + espagnol + italien", "français + anglais seulement", "néerlandais + allemand seulement"], "a": 0, "trap": "assuming English is enough — in Brussels it is the Dutch that opens doors and raises salaries", "expl": "Brussels is officially bilingual French–Dutch. Many jobs ask for « une bonne connaissance du néerlandais », and public-sector posts pay a language bonus.", "note": "Belgian reality: say « le néerlandais », not « le flamand », in a professional setting."}, {"id": "fvc-interview-A2-15", "level": "A2", "pos": "adj", "fr": "bilingue", "en": "bilingual", "format": "cloze", "q": "Le poste est ouvert à un candidat ___ français-néerlandais.", "options": ["bilingue", "bilatéral", "binational", "biannuel"], "a": 0, "trap": "binational — about nationality, not about languages", "expl": "All four adjectives. Belgian ads grade language levels: « notions », « bonne connaissance », « bilingue »."}, {"id": "fvc-interview-A2-16", "level": "A2", "pos": "noun", "gender": "m", "fr": "le contrat", "en": "the contract", "format": "cloze", "q": "Est-ce que c'est un ___ à durée indéterminée ?", "options": ["contrat", "accord", "engagement", "document"], "a": 0, "trap": "l'engagement — the commitment or the hiring itself; the paper is « le contrat »", "expl": "All four masculine. CDI = contrat à durée indéterminée; CDD = contrat à durée déterminée."}, {"id": "fvc-interview-A2-17", "level": "A2", "pos": "noun", "gender": "m", "fr": "le CDI", "en": "the permanent contract", "format": "fr2en", "options": ["an open-ended, permanent contract", "a fixed-term contract", "a temporary agency contract", "a freelance arrangement"], "a": 0, "trap": "le CDD — the fixed-term one; two letters apart and a completely different life", "expl": "CDI = contrat à durée indéterminée. In Belgium it is the standard contract and the one banks want to see for a mortgage."}, {"id": "fvc-interview-A2-18", "level": "A2", "pos": "noun", "gender": "m", "fr": "le salaire brut", "en": "the gross salary", "format": "collocation", "q": "A Belgian ad offers 3 000 € brut per month. Roughly what lands in your account?", "options": ["Environ 2 000 € net", "Environ 2 700 € net", "Exactement 3 000 € net", "Environ 1 500 € net"], "a": 0, "trap": "assuming a small deduction — Belgian gross-to-net is one of the steepest in Europe", "expl": "Social security plus précompte professionnel take roughly a third for a single person with no dependants. Always ask whether a figure is brut or net.", "note": "Belgian reality: salaries are always quoted brut, monthly, and are automatically indexed to the indice santé."}, {"id": "fvc-interview-A2-19", "level": "A2", "pos": "noun", "gender": "m", "fr": "le précompte professionnel", "en": "payroll withholding tax", "format": "fr2en", "options": ["income tax deducted from your pay each month", "the property tax", "the employer's social contribution", "an advance on your salary"], "a": 0, "trap": "le précompte immobilier — the property tax; the shared word « précompte » is the trap", "expl": "Taken at source and shown on your « fiche de paie ». You settle the difference the following year in your tax return.", "note": "Belgian institution: the equivalent of PAYE, and the biggest single line between brut and net."}, {"id": "fvc-interview-A2-20", "level": "A2", "pos": "noun", "gender": "m", "fr": "les chèques-repas", "en": "the meal vouchers", "format": "fr2en", "options": ["electronic meal vouchers loaded on a card", "restaurant receipts you claim back", "a canteen subsidy paid in cash", "a monthly food allowance in your salary"], "a": 0, "trap": "assuming they are cash — they are a separate, largely untaxed benefit and cannot be paid as salary", "expl": "One per day worked, up to 10 € each since January 2026, of which at least 1,09 € is deducted from your net pay. Accepted in supermarkets and most restaurants.", "note": "Belgian institution. France's nearest equivalent is « les titres-restaurant »."}, {"id": "fvc-interview-A2-21", "level": "A2", "pos": "noun", "gender": "m", "fr": "le treizième mois", "en": "the thirteenth month", "format": "en2fr", "options": ["le treizième mois", "le double pécule", "le mois supplémentaire", "le pécule de sortie"], "a": 0, "trap": "le double pécule de vacances — a different Belgian extra, paid in May or June with your holiday", "expl": "All four masculine. « la prime de fin d'année » (13th month) arrives in December; « le double pécule » arrives with the summer holidays.", "note": "Belgian pay structure: both exist, both depend on your sector's collective agreement."}, {"id": "fvc-interview-A2-22", "level": "A2", "pos": "noun", "gender": "m", "fr": "l'abonnement STIB", "en": "the STIB travel pass", "format": "collocation", "q": "What does a Belgian employer usually do about your commuting?", "options": ["Il intervient dans l'abonnement de transport en commun.", "Il paie tous vos taxis.", "Il ne participe jamais aux frais de déplacement.", "Il vous donne une voiture, quel que soit le poste."], "a": 0, "trap": "the company car — real in Belgium, but for specific roles, not by default", "expl": "Employers must contribute to public-transport season tickets; many pay 100 % of the STIB or SNCB pass.", "note": "Belgian rule set by collective agreement; ask what the exact share is."}, {"id": "fvc-interview-A2-23", "level": "A2", "pos": "noun", "gender": "m", "fr": "le télétravail", "en": "working from home", "format": "cloze", "q": "Est-ce que le ___ est possible deux jours par semaine ?", "options": ["télétravail", "téléphone", "temps partiel", "trajet"], "a": 0, "trap": "le temps partiel — part-time work, a different question with a different salary", "expl": "All four masculine. « le télétravail structurel » is the version written into your contract, usually two days a week in Brussels."}, {"id": "fvc-interview-A2-24", "level": "A2", "pos": "noun", "gender": "m", "fr": "le temps plein", "en": "full time", "format": "fr2en", "options": ["full-time work", "overtime", "flexible hours", "a full year of service"], "a": 0, "trap": "les heures supplémentaires — overtime; « temps plein » is just the normal week", "expl": "A Belgian full week is usually 38 hours. « un quatre cinquièmes » (4/5) is the very common four-day arrangement."}, {"id": "fvc-interview-A2-25", "level": "A2", "pos": "noun", "gender": "m", "fr": "les horaires", "en": "the working hours", "format": "cloze", "q": "Quels sont les ___ de travail, en général ?", "options": ["horaires", "heures", "temps", "moments"], "a": 0, "trap": "les heures — the hours as units; « les horaires » is the schedule you work to", "expl": "All four masculine plural. « l'horaire flottant » is flexitime, common in Brussels offices."}, {"id": "fvc-interview-A2-26", "level": "A2", "pos": "noun", "gender": "m", "fr": "les congés", "en": "the annual leave", "format": "collocation", "q": "How many days of statutory annual leave does a Belgian full-time employee get?", "options": ["20 jours, plus 10 jours fériés", "25 jours, plus 10 jours fériés", "30 jours, jours fériés compris", "15 jours seulement"], "a": 0, "trap": "25 days — the French figure, and a natural guess for anyone who has worked there", "expl": "Twenty legal days for a five-day week, plus the ten public holidays. Many sectors add extra days by collective agreement.", "note": "Belgian statutory minimum. France gives 25 working days plus public holidays."}, {"id": "fvc-interview-A2-27", "level": "A2", "pos": "noun", "gender": "f", "fr": "l'équipe", "en": "the team", "format": "en2fr", "options": ["l'équipe", "l'équipée", "l'étape", "l'équerre"], "a": 0, "trap": "l'équipée — an escapade or a jaunt; the extra e changes everything", "expl": "All four feminine. « Vous travaillerez dans une équipe de six personnes. » « un esprit d'équipe » = team spirit."}, {"id": "fvc-interview-A2-28", "level": "A2", "pos": "noun", "gender": "m", "fr": "le collègue", "en": "the colleague", "format": "cloze", "q": "Je m'entends bien avec mes ___ et j'aime le travail en équipe.", "options": ["collègues", "concurrents", "clients", "candidats"], "a": 0, "trap": "les concurrents — competitors; getting on well with them is not what the recruiter is asking about", "expl": "All four masculine plural. « s'entendre bien avec quelqu'un » = to get on well with someone."}, {"id": "fvc-interview-A2-29", "level": "A2", "pos": "noun", "gender": "m", "fr": "le service", "en": "the department", "format": "fr2en", "options": ["a department within a company", "the service charge", "military service", "a favour done for someone"], "a": 0, "trap": "all three other meanings are real French — the office sense is the one in an interview", "expl": "« le service comptabilité », « le service du personnel ». Bigger organisations say « le département » or « l'unité »."}, {"id": "fvc-interview-A2-30", "level": "A2", "pos": "verb", "fr": "postuler", "en": "to apply", "format": "fr2en", "options": ["to apply for a job", "to postpone", "to assume something", "to post a letter"], "a": 0, "trap": "'to postulate' — the academic English cousin, which French keeps only in mathematics", "expl": "« J'ai postulé pour le poste d'assistant. » Also « poser sa candidature », which is one register up."}, {"id": "fvc-interview-A2-31", "level": "A2", "pos": "verb", "fr": "se présenter", "en": "to introduce oneself", "format": "cloze", "q": "Est-ce que vous pouvez vous ___ en quelques mots ?", "options": ["présenter", "expliquer", "raconter", "décrire"], "a": 0, "trap": "décrire — « se décrire » exists but sounds like a personality test rather than an introduction", "expl": "All four infinitives after « vous ». The classic opening question; prepare ninety seconds and stop there."}, {"id": "fvc-interview-A2-32", "level": "A2", "pos": "verb", "fr": "gérer", "en": "to manage / handle", "format": "en2fr", "options": ["gérer", "générer", "gêner", "guérir"], "a": 0, "trap": "générer — to generate; one letter, and the two are pronounced very similarly", "expl": "All four infinitives. « gérer des dossiers », « gérer une équipe », « gérer son temps »."}, {"id": "fvc-interview-A2-33", "level": "A2", "pos": "verb", "fr": "s'occuper de", "en": "to be in charge of", "format": "cloze", "q": "Dans mon poste actuel, je m'occupe ___ la gestion des dossiers.", "options": ["de", "à", "pour", "avec"], "a": 0, "trap": "à — « s'occuper à faire quelque chose » exists and means keeping yourself busy", "expl": "« s'occuper de » + noun = to handle, to look after. Useful for describing a job without exaggerating your rank."}, {"id": "fvc-interview-A2-34", "level": "A2", "pos": "verb", "fr": "commencer", "en": "to start", "format": "collocation", "q": "Which is the natural Belgian HR phrasing?", "options": ["Vous pourriez entrer en fonction quand ?", "Vous pourriez commencer à fonctionner quand ?", "Vous pourriez démarrer la fonction quand ?", "Vous pourriez ouvrir la fonction quand ?"], "a": 0, "trap": "the other three are literal translations that no Belgian HR department has ever said", "expl": "« l'entrée en fonction » = the start date. Everyday answer: « Je suis disponible à partir du 1er septembre. »", "note": "Belgian HR vocabulary; France says « la prise de poste » just as often."}, {"id": "fvc-interview-A2-35", "level": "A2", "pos": "verb", "fr": "apprendre", "en": "to learn", "format": "cloze", "q": "J'___ le néerlandais depuis un an, deux soirs par semaine.", "options": ["apprends", "enseigne", "comprends", "entends"], "a": 0, "trap": "enseigne — 'I teach'; « apprendre » can mean to teach too, but only with « à quelqu'un »", "expl": "All four first-person verbs. « J'apprends le néerlandais » is a sentence worth having ready in any Brussels interview."}, {"id": "fvc-interview-A2-36", "level": "A2", "pos": "adj", "fr": "motivé", "en": "motivated", "format": "en2fr", "options": ["motivé", "motif", "mobile", "modeste"], "a": 0, "trap": "le motif — the reason or motive, a noun rather than an adjective describing you", "expl": "All four are masculine words, but only « motivé » is the adjective for a person. Better still: show it, don't say it."}, {"id": "fvc-interview-A2-37", "level": "A2", "pos": "adj", "fr": "disponible", "en": "available", "format": "cloze", "q": "Je suis ___ à partir du premier septembre.", "options": ["disponible", "possible", "capable", "responsable"], "a": 0, "trap": "capable — true and irrelevant; the question was about dates", "expl": "All four adjectives fit the slot. « la disponibilité » is one of the last questions in almost every Belgian interview."}, {"id": "fvc-interview-A2-38", "level": "A2", "pos": "adj", "fr": "autonome", "en": "able to work independently", "format": "fr2en", "options": ["able to work on your own", "self-employed", "isolated from the team", "in charge of others"], "a": 0, "trap": "'autonomous' as self-employed — that is « indépendant », a legal status in Belgium", "expl": "« Je suis autonome mais j'aime le travail en équipe » is the standard, and honest, answer to this question."}, {"id": "fvc-interview-A2-39", "level": "A2", "pos": "adj", "fr": "ponctuel", "en": "punctual", "format": "fr2en", "options": ["punctual, on time", "occasional, one-off", "precise in detail", "polite"], "a": 0, "trap": "« ponctuel » also means one-off: « une aide ponctuelle » — the second meaning is very common at work", "expl": "About a person: on time. About a task: occasional. Context does all the work."}, {"id": "fvc-interview-A2-40", "level": "A2", "pos": "noun", "gender": "m", "fr": "le point fort", "en": "the strength", "format": "cloze", "q": "Quel est votre principal ___ fort ?", "options": ["point", "côté", "aspect", "trait"], "a": 0, "trap": "le côté — « un bon côté » exists, but the interview formula is « point fort / point faible »", "expl": "All four masculine. « mes points forts » / « mes points faibles » — prepare two of each, with an example."}, {"id": "fvc-interview-A2-41", "level": "A2", "pos": "noun", "gender": "f", "fr": "la fiche de paie", "en": "the payslip", "format": "en2fr", "options": ["la fiche de paie", "la fiche de poste", "la feuille de route", "la carte de pointage"], "a": 0, "trap": "la fiche de poste — the job description, another document you will be handed", "expl": "All four feminine. Also « la fiche de salaire ». It shows brut, ONSS, précompte professionnel and net."}, {"id": "fvc-interview-A2-42", "level": "A2", "pos": "adj", "fr": "septante", "en": "seventy", "format": "cloze", "q": "Le salaire proposé est de trois mille ___ euros brut par mois.", "options": ["septante", "nonante", "soixante", "quarante"], "a": 0, "trap": "nonante — the other Belgian number, and a twenty-euro difference every month", "expl": "trois mille septante = 3 070. Salary figures come fast in interviews: train the Belgian numbers before you go.", "note": "Belgian French. France says trois mille soixante-dix."}, {"id": "fvc-interview-A2-43", "level": "A2", "pos": "noun", "gender": "m", "fr": "le GSM", "en": "the mobile (Belgian French)", "format": "cloze", "q": "Vous pouvez me joindre sur mon ___ pendant la journée.", "options": ["GSM", "bureau", "mail", "fixe"], "a": 0, "trap": "le fixe — the landline, which is exactly the number you cannot be reached on during the day", "expl": "All four masculine. Belgian application forms print « GSM » where French ones print « portable ».", "note": "Belgian French. France: mon portable."}, {"id": "fvc-interview-A2-44", "level": "A2", "pos": "noun", "gender": "m", "fr": "le numéro national", "en": "the national register number", "format": "fr2en", "options": ["the 11-digit number identifying you in Belgium", "your tax reference only", "your social security card number in another country", "the company registration number"], "a": 0, "trap": "le numéro d'entreprise — the company's number, which looks similar and belongs to your employer", "expl": "Printed on the back of your Belgian eID and built from your date of birth. Every employer, bank and mutuelle will ask for it.", "note": "Belgian institution: the single key to your whole administrative life here."}, {"id": "fvc-interview-A2-45", "level": "A2", "pos": "expr", "fr": "je vous remercie", "en": "thank you", "format": "collocation", "q": "Which closing line fits the end of a Belgian job interview?", "options": ["Je vous remercie de m'avoir reçu.", "Merci de m'avoir accepté.", "Je vous remercie pour recevoir moi.", "Merci pour m'avoir écouté beaucoup."], "a": 0, "trap": "« m'avoir accepté » says you have already got the job, which is not yet true", "expl": "« recevoir quelqu'un » = to see someone, for a meeting. « Je vous remercie de m'avoir reçu » is the standard closing formula."}, {"id": "fvc-interview-A2-46", "level": "A2", "pos": "expr", "fr": "de rien", "en": "you're welcome", "format": "en2fr", "options": ["de rien", "s'il vous plaît", "je vous en prie", "avec plaisir"], "a": 0, "trap": "« je vous en prie » is also correct and more formal — but in Belgium « s'il vous plaît » can mean 'here you go', not 'you're welcome'", "expl": "All four are set expressions. In an interview « je vous en prie » is the safer, more formal choice.", "note": "Belgian French: watch out for « s'il vous plaît » used when handing something over — it is not a reply to thanks."}], "phrases": [{"id": "ph-interview-A2-01", "fr": "Bonjour, je suis Orestis Vasileiadis, j'ai rendez-vous à quatorze heures.", "en": "Hello, I'm Orestis Vasileiadis, I have an appointment at two o'clock.", "note": "At reception, « je suis » is right; on the phone it would be « c'est ». The 24-hour clock is standard here."}, {"id": "ph-interview-A2-02", "fr": "J'ai vu votre offre d'emploi sur le site d'Actiris.", "en": "I saw your job advert on the Actiris site.", "note": "Actiris is the Brussels employment service. Naming where you saw the advert is a normal opening detail."}, {"id": "ph-interview-A2-03", "fr": "J'ai fait mes études en Grèce et un master à Bruxelles.", "en": "I studied in Greece and did a master's in Brussels.", "note": "« faire ses études » is the fixed phrase. Foreign degrees may need « une équivalence » for public-sector posts."}, {"id": "ph-interview-A2-04", "fr": "J'ai trois ans d'expérience dans la gestion de dossiers.", "en": "I have three years' experience in file management.", "note": "« d'expérience » with no article after a number. Say the field straight afterwards."}, {"id": "ph-interview-A2-05", "fr": "Dans mon poste actuel, je m'occupe des dossiers clients.", "en": "In my current job I handle the client files.", "note": "« s'occuper de » describes what you do without overstating your rank — useful and honest."}, {"id": "ph-interview-A2-06", "fr": "Je parle grec, anglais et français, et j'apprends le néerlandais.", "en": "I speak Greek, English and French, and I'm learning Dutch.", "note": "In Brussels this last clause matters. Say « le néerlandais », never « le flamand », in a professional setting."}, {"id": "ph-interview-A2-07", "fr": "Je suis au niveau A2, mais je progresse vite.", "en": "I'm at A2 level, but I'm improving fast.", "note": "Belgians know the CEFR levels and respect an honest one far more than a vague « je me débrouille »."}, {"id": "ph-interview-A2-08", "fr": "Ce qui m'intéresse dans ce poste, c'est le contact avec les clients.", "en": "What interests me about this job is the contact with clients.", "note": "« Ce qui m'intéresse, c'est… » is a clean structure for the 'why this job' question."}, {"id": "ph-interview-A2-09", "fr": "Je suis autonome, mais j'aime aussi le travail en équipe.", "en": "I can work independently, but I also like working in a team.", "note": "The expected answer, and it is fine to give it — just add one concrete example straight after."}, {"id": "ph-interview-A2-10", "fr": "Mon point faible, c'est que je veux parfois tout vérifier deux fois.", "en": "My weak point is that I sometimes want to check everything twice.", "note": "Give a real one with a small correction. « Je suis perfectionniste » on its own is heard as a non-answer."}, {"id": "ph-interview-A2-11", "fr": "Est-ce que c'est un contrat à durée indéterminée ?", "en": "Is it a permanent contract?", "note": "A completely normal question in Belgium and worth asking early. CDI = permanent; CDD = fixed term."}, {"id": "ph-interview-A2-12", "fr": "Quel est le salaire brut proposé pour ce poste ?", "en": "What's the gross salary offered for this position?", "note": "Always specify « brut » — Belgian salaries are quoted gross and monthly, and net is roughly a third less."}, {"id": "ph-interview-A2-13", "fr": "Est-ce qu'il y a des chèques-repas et un treizième mois ?", "en": "Are there meal vouchers and a thirteenth month?", "note": "Standard Belgian benefits questions, and asking them makes you look informed rather than greedy."}, {"id": "ph-interview-A2-14", "fr": "Est-ce que l'abonnement STIB est remboursé ?", "en": "Is the STIB pass reimbursed?", "note": "Employers must contribute to public transport costs; many pay it in full. Worth 500 € a year."}, {"id": "ph-interview-A2-15", "fr": "Est-ce que le télétravail est possible ?", "en": "Is working from home possible?", "note": "Two days a week is the Brussels norm for office jobs. Ask whether it is « structurel » — written into the contract."}, {"id": "ph-interview-A2-16", "fr": "Quels sont les horaires de travail ?", "en": "What are the working hours?", "note": "A Belgian full week is usually 38 hours. Ask about « l'horaire flottant » (flexitime) if that matters to you."}, {"id": "ph-interview-A2-17", "fr": "Je suis disponible à partir du premier septembre.", "en": "I'm available from the first of September.", "note": "Give a date, not a vague answer. If you are in a job, say « j'ai un préavis à respecter »."}, {"id": "ph-interview-A2-18", "fr": "Est-ce que vous avez d'autres questions sur mon parcours ?", "en": "Do you have any other questions about my background?", "note": "« mon parcours » = my career path so far. A useful word, and warmer than « mon CV »."}, {"id": "ph-interview-A2-19", "fr": "Quand est-ce que vous pensez donner une réponse ?", "en": "When do you expect to give an answer?", "note": "Ask it before you leave. It sets a date, which makes a polite follow-up email natural rather than pushy."}, {"id": "ph-interview-A2-20", "fr": "Je vous remercie de m'avoir reçu.", "en": "Thank you for seeing me.", "note": "« recevoir quelqu'un » = to see someone for a meeting. The standard, expected closing line."}], "dialogue": [{"who": "recruiter", "fr": "Bonjour monsieur Vasileiadis, asseyez-vous. Vous avez trouvé facilement ?", "en": "Hello Mr Vasileiadis, do sit down. Did you find us easily?", "gloss": {"asseyez-vous": "sit down", "facilement": "easily"}}, {"who": "you", "fr": "Bonjour madame, merci. Oui, très facilement, je suis venu en métro.", "en": "Hello, thank you. Yes, very easily, I came by metro.", "gloss": {"en métro": "by metro"}, "accept": ["bonjour madame merci oui très facilement je suis venu en métro", "bonjour madame merci oui sans problème je suis venu en métro", "bonjour merci oui très facilement je suis venu en métro", "bonjour madame merci oui c'était facile je suis venu en métro", "bonjour madame merci beaucoup oui j'ai trouvé facilement", "bonjour madame oui très facilement merci je suis venu en métro"]}, {"who": "recruiter", "fr": "Parfait. Alors, pour commencer, est-ce que vous pouvez vous présenter en quelques mots ?", "en": "Perfect. So, to start, could you introduce yourself in a few words?", "gloss": {"vous présenter": "introduce yourself", "quelques mots": "a few words"}}, {"who": "you", "fr": "Bien sûr. Je m'appelle Orestis Vasileiadis, je suis grec et j'habite à Bruxelles depuis quatre ans. J'ai fait un master en administration publique.", "en": "Of course. My name is Orestis Vasileiadis, I'm Greek and I've been living in Brussels for four years. I did a master's in public administration.", "gloss": {"depuis": "for, since", "master": "master's degree"}, "accept": ["bien sûr je m'appelle orestis vasileiadis je suis grec et j'habite à bruxelles depuis quatre ans j'ai fait un master en administration publique", "bien sûr je m'appelle orestis vasileiadis je suis grec j'habite à bruxelles depuis quatre ans et j'ai fait un master en administration publique", "oui bien sûr je suis orestis vasileiadis je suis grec et je vis à bruxelles depuis quatre ans j'ai un master en administration publique", "bien sûr je m'appelle orestis vasileiadis j'habite à bruxelles depuis quatre ans et j'ai fait un master en administration publique", "avec plaisir je m'appelle orestis vasileiadis je suis grec j'habite à bruxelles depuis quatre ans", "bien sûr je suis grec j'habite à bruxelles depuis quatre ans et j'ai fait un master en administration publique"]}, {"who": "recruiter", "fr": "Et qu'est-ce que vous faites actuellement ?", "en": "And what are you doing at the moment?", "gloss": {"actuellement": "at the moment, currently"}}, {"who": "you", "fr": "Je travaille dans une petite société de conseil. Je m'occupe des dossiers clients et j'ai trois ans d'expérience.", "en": "I work in a small consultancy. I handle the client files and I have three years' experience.", "gloss": {"société de conseil": "consultancy firm", "expérience": "experience", "Je m'occupe des": "I handle, I look after"}, "accept": ["je travaille dans une petite société de conseil je m'occupe des dossiers clients et j'ai trois ans d'expérience", "je travaille dans une petite société de conseil je m'occupe des dossiers clients", "actuellement je travaille dans une société de conseil et je m'occupe des dossiers clients", "je travaille dans une petite société de conseil où je gère les dossiers clients depuis trois ans", "je suis dans une société de conseil je m'occupe des dossiers clients j'ai trois ans d'expérience", "je travaille actuellement dans une petite société de conseil je gère les dossiers des clients"]}, {"who": "recruiter", "fr": "Très bien. Et pourquoi est-ce que vous voulez changer ?", "en": "Very good. And why do you want to change?", "gloss": {"changer": "to change (jobs)"}}, {"who": "you", "fr": "Ce qui m'intéresse ici, c'est le contact avec les clients européens. Et je voudrais travailler dans une équipe plus grande.", "en": "What interests me here is the contact with European clients. And I'd like to work in a bigger team.", "gloss": {"Ce qui m'intéresse": "what interests me", "équipe": "team"}, "accept": ["ce qui m'intéresse ici c'est le contact avec les clients européens et je voudrais travailler dans une équipe plus grande", "ce qui m'intéresse ici c'est le contact avec les clients européens", "ce qui m'intéresse dans ce poste c'est le contact avec les clients européens et une plus grande équipe", "j'aimerais travailler dans une équipe plus grande et le contact avec les clients européens m'intéresse", "ce qui m'intéresse c'est le contact avec les clients européens et je cherche une équipe plus grande", "parce que le contact avec les clients européens m'intéresse et je voudrais une équipe plus grande"]}, {"who": "recruiter", "fr": "Ici, on travaille beaucoup en néerlandais avec nos collègues d'Anvers. Vous parlez néerlandais ?", "en": "Here we work a lot in Dutch with our colleagues in Antwerp. Do you speak Dutch?", "gloss": {"néerlandais": "Dutch", "collègues": "colleagues"}}, {"who": "you", "fr": "Pas encore bien. J'apprends le néerlandais depuis un an, deux soirs par semaine. Je suis au niveau A2.", "en": "Not well yet. I've been learning Dutch for a year, two evenings a week. I'm at A2 level.", "gloss": {"Pas encore": "not yet", "niveau": "level", "J'apprends": "I'm learning"}, "accept": ["pas encore bien j'apprends le néerlandais depuis un an deux soirs par semaine je suis au niveau a2", "pas encore bien j'apprends le néerlandais depuis un an je suis au niveau a2", "pas encore j'apprends le néerlandais depuis un an deux soirs par semaine", "pas très bien mais j'apprends le néerlandais depuis un an je suis au niveau a2", "je commence j'apprends le néerlandais depuis un an deux soirs par semaine", "pas encore bien mais je prends des cours de néerlandais depuis un an"]}, {"who": "recruiter", "fr": "C'est déjà bien. Et quel est votre point faible, selon vous ?", "en": "That's already good. And what would you say your weak point is?", "gloss": {"point faible": "weak point", "selon vous": "in your opinion"}}, {"who": "you", "fr": "Je veux parfois tout vérifier deux fois, donc je suis un peu lent au début. Mais je m'améliore avec l'expérience.", "en": "I sometimes want to check everything twice, so I'm a bit slow at the start. But I'm getting better with experience.", "gloss": {"vérifier": "to check", "lent": "slow", "je m'améliore": "I'm improving"}, "accept": ["je veux parfois tout vérifier deux fois donc je suis un peu lent au début mais je m'améliore avec l'expérience", "je veux parfois tout vérifier deux fois donc je suis un peu lent au début", "parfois je vérifie tout deux fois et je suis un peu lent au début mais je m'améliore", "j'ai tendance à tout vérifier deux fois donc je suis lent au début mais ça s'améliore", "mon point faible c'est que je vérifie tout deux fois donc je suis un peu lent au début", "je veux parfois trop vérifier donc je suis un peu lent mais je progresse avec l'expérience"]}, {"who": "recruiter", "fr": "Merci pour votre franchise. Est-ce que vous avez des questions sur le poste ?", "en": "Thank you for your honesty. Do you have any questions about the job?", "gloss": {"franchise": "frankness, honesty", "questions": "questions"}}, {"who": "you", "fr": "Oui. Est-ce que c'est un contrat à durée indéterminée, et quel est le salaire brut proposé ?", "en": "Yes. Is it a permanent contract, and what's the gross salary offered?", "gloss": {"contrat à durée indéterminée": "permanent contract (CDI)", "salaire brut": "gross salary"}, "accept": ["oui est-ce que c'est un contrat à durée indéterminée et quel est le salaire brut proposé", "oui est-ce que c'est un cdi et quel est le salaire brut proposé", "oui est-ce que c'est un contrat à durée indéterminée et quel salaire brut est proposé", "oui j'aimerais savoir si c'est un cdi et quel est le salaire brut", "oui est-ce que le contrat est à durée indéterminée et combien est le salaire brut", "oui c'est bien un contrat à durée indéterminée et quel est le salaire brut proposé"]}, {"who": "recruiter", "fr": "C'est un CDI, temps plein, trente-huit heures. Le salaire est de trois mille septante euros brut par mois.", "en": "It's a permanent contract, full time, thirty-eight hours. The salary is three thousand and seventy euros gross a month.", "gloss": {"CDI": "permanent contract", "temps plein": "full time", "septante": "seventy (Belgian French; France: soixante-dix)", "brut": "gross"}}, {"who": "you", "fr": "D'accord. Est-ce qu'il y a des chèques-repas, et est-ce que l'abonnement STIB est remboursé ?", "en": "All right. Are there meal vouchers, and is the STIB pass reimbursed?", "gloss": {"chèques-repas": "meal vouchers", "abonnement": "season ticket", "remboursé": "reimbursed"}, "accept": ["d'accord est-ce qu'il y a des chèques-repas et est-ce que l'abonnement stib est remboursé", "d'accord est-ce qu'il y a des chèques-repas et est-ce que l'abonnement stib est remboursé aussi", "d'accord et est-ce qu'il y a des chèques-repas et un remboursement de l'abonnement stib", "très bien est-ce qu'il y a des chèques-repas et l'abonnement stib est-il remboursé", "d'accord merci et les chèques-repas et l'abonnement stib sont-ils prévus", "d'accord est-ce que vous donnez des chèques-repas et est-ce que vous remboursez l'abonnement stib"]}, {"who": "recruiter", "fr": "Oui : chèques-repas de huit euros par jour presté, abonnement remboursé à cent pour cent, et un treizième mois en décembre.", "en": "Yes: eight-euro meal vouchers per day worked, the pass reimbursed in full, and a thirteenth month in December.", "gloss": {"jour presté": "day actually worked", "à cent pour cent": "in full", "treizième mois": "thirteenth month, the December bonus"}}, {"who": "you", "fr": "C'est très clair, merci. Une dernière chose : est-ce que le télétravail est possible ?", "en": "That's very clear, thank you. One last thing: is working from home possible?", "gloss": {"clair": "clear", "télétravail": "working from home"}, "accept": ["c'est très clair merci une dernière chose est-ce que le télétravail est possible", "c'est très clair merci est-ce que le télétravail est possible", "merci c'est très clair et une dernière question est-ce que le télétravail est possible", "c'est clair merci et est-ce que le télétravail est possible", "merci beaucoup c'est très clair dernière chose est-ce que le télétravail est possible", "c'est très clair merci et le télétravail est-il possible"]}, {"who": "recruiter", "fr": "Deux jours par semaine, après les trois premiers mois. Vous seriez disponible quand ?", "en": "Two days a week, after the first three months. When would you be available?", "gloss": {"par semaine": "a week", "disponible": "available"}}, {"who": "you", "fr": "À partir du premier septembre. Je vous remercie de m'avoir reçu.", "en": "From the first of September. Thank you for seeing me.", "gloss": {"À partir du": "from", "de m'avoir reçu": "for seeing me"}, "accept": ["à partir du premier septembre je vous remercie de m'avoir reçu", "je suis disponible à partir du premier septembre je vous remercie de m'avoir reçu", "à partir du premier septembre merci de m'avoir reçu", "je serais disponible à partir du premier septembre je vous remercie de m'avoir reçu", "à partir du premier septembre merci beaucoup de m'avoir reçu", "je peux commencer le premier septembre je vous remercie de m'avoir reçu"]}], "exercises": [{"id": "ex-interview-A2-01", "level": "A2", "pos": "noun", "gender": "m", "fr": "le stage", "en": "the internship", "format": "fr2en", "options": ["an internship", "a theatre stage", "a step in a process", "a stopover"], "a": 0, "trap": "the English 'stage' — one of the most persistent false friends there is", "expl": "« J'ai fait un stage de six mois. » The person is « un stagiaire »; the theatre stage is « la scène »."}, {"id": "ex-interview-A2-02", "level": "A2", "pos": "noun", "gender": "m", "fr": "le poste", "en": "the job", "format": "cloze", "q": "Je postule pour le ___ d'assistant administratif.", "options": ["poste", "travail", "métier", "bureau"], "a": 0, "trap": "le métier — a trade or profession as a whole, not one vacancy", "expl": "All four masculine. LE poste = the position; LA poste = the post office. Gender carries the meaning."}, {"id": "ex-interview-A2-03", "level": "A2", "pos": "noun", "gender": "m", "fr": "Actiris", "en": "the Brussels employment service", "format": "collocation", "q": "Match the region to the employment service.", "options": ["Bruxelles = Actiris ; Wallonie = Le Forem ; Flandre = VDAB", "Bruxelles = Le Forem ; Wallonie = Actiris", "Bruxelles = VDAB ; Flandre = Actiris", "Partout = l'ONEM"], "a": 0, "trap": "l'ONEM — federal, and it pays unemployment benefit rather than finding you work", "expl": "You register with your region's service; ONEM/RVA handles the benefit itself.", "note": "Belgian institutions: three regions, three services, one federal payer."}, {"id": "ex-interview-A2-04", "level": "A2", "pos": "noun", "gender": "m", "fr": "le salaire brut", "en": "the gross salary", "format": "collocation", "q": "Which question should you ask about any Belgian salary figure?", "options": ["C'est brut ou net ?", "C'est par semaine ou par mois ?", "C'est avant ou après les vacances ?", "C'est en euros ou en francs ?"], "a": 0, "trap": "the weekly/monthly question — Belgian salaries are always monthly, so it wastes your one question", "expl": "Ads quote brut mensuel. Between brut and net sit ONSS contributions and the précompte professionnel — roughly a third.", "note": "Belgian pay culture: also ask about the sector's commission paritaire, which sets the minimum scales."}, {"id": "ex-interview-A2-05", "level": "A2", "pos": "adj", "fr": "presté", "en": "actually worked (of a day)", "format": "cloze", "q": "Nous offrons des chèques-repas de huit euros par jour ___.", "options": ["presté", "travaillé", "ouvré", "complet"], "a": 0, "trap": "travaillé — logical and not the term on Belgian payslips", "expl": "All four are masculine adjectives or participles. « un jour presté » = a day actually worked; vouchers are not given for holidays or sick days.", "note": "Belgian payroll vocabulary; « jours prestés » appears on every fiche de paie."}, {"id": "ex-interview-A2-06", "level": "A2", "pos": "noun", "gender": "m", "fr": "le CDI", "en": "the permanent contract", "format": "en2fr", "options": ["le CDI", "le CDD", "l'intérim", "le CDI-CDD"], "a": 0, "trap": "le CDD — fixed term; two letters apart on paper and years apart in practice", "expl": "CDI = contrat à durée indéterminée, the standard Belgian contract and the one a bank wants for a mortgage."}, {"id": "ex-interview-A2-07", "level": "A2", "pos": "verb", "fr": "postuler", "en": "to apply", "format": "cloze", "q": "J'ai ___ pour le poste il y a deux semaines.", "options": ["postulé", "posté", "posé", "proposé"], "a": 0, "trap": "posté — 'posted'; the two verbs sit next to each other in the same sentence about a job application", "expl": "All four past participles. « postuler pour / à un poste », or « poser sa candidature »."}, {"id": "ex-interview-A2-08", "level": "A2", "pos": "noun", "gender": "m", "fr": "le précompte professionnel", "en": "payroll tax", "format": "fr2en", "options": ["the income tax withheld from your monthly pay", "the property tax on your flat", "the employer's social security contribution", "a bonus paid in December"], "a": 0, "trap": "le précompte immobilier — the property tax; the shared word « précompte » is the whole trap", "expl": "Withheld at source, listed on your fiche de paie, and reconciled the following year in your tax return.", "note": "Belgian institution: the single biggest gap between your brut and your net."}, {"id": "ex-interview-A2-09", "level": "A2", "pos": "noun", "gender": "m", "fr": "les congés", "en": "annual leave", "format": "cloze", "q": "En Belgique, un temps plein a droit à vingt jours de ___ par an, plus dix jours fériés.", "options": ["congés", "repos", "arrêts", "absences"], "a": 0, "trap": "les arrêts — « un arrêt de travail » is sick leave, which is not holiday", "expl": "All four masculine plural. Twenty legal days plus ten public holidays; many sectors add more by agreement.", "note": "Belgian statutory minimum; France gives 25 working days."}, {"id": "ex-interview-A2-10", "level": "A2", "pos": "verb", "fr": "engager", "en": "to hire (Belgian usage)", "format": "fr2en", "options": ["to take someone on as an employee", "to start an argument", "to spend money", "to commit oneself only"], "a": 0, "trap": "« s'engager » — to commit oneself, which is the reflexive and a different act", "expl": "Belgian job ads say « nous engageons » where French ones say « nous recrutons » or « nous embauchons ».", "note": "Belgian usage; both are understood everywhere."}, {"id": "ex-interview-A2-11", "level": "A2", "pos": "noun", "gender": "m", "fr": "le néerlandais", "en": "Dutch", "format": "collocation", "q": "How should you refer to the language in a Brussels interview?", "options": ["le néerlandais", "le flamand", "le belge", "le hollandais"], "a": 0, "trap": "« le flamand » — used casually, but it names a set of dialects and can sound dismissive at work", "expl": "The official language is Dutch: « le néerlandais ». There is no such thing as « le belge ».", "note": "Belgian sensitivity worth respecting on the first day as much as at the interview."}, {"id": "ex-interview-A2-12", "level": "A2", "pos": "adj", "fr": "disponible", "en": "available", "format": "fr2en", "options": ["available to start", "willing to help", "reachable by phone", "free of charge"], "a": 0, "trap": "'free of charge' — that is « gratuit », and this is the last word you want to attach to yourself in a salary conversation", "expl": "« Vous seriez disponible quand ? » = when could you start? Answer with a date."}, {"id": "ex-interview-A2-13", "level": "A2", "pos": "noun", "gender": "m", "fr": "le numéro national", "en": "the national register number", "format": "cloze", "q": "Vous trouverez votre ___ national au dos de votre carte d'identité.", "options": ["numéro", "code", "matricule", "chiffre"], "a": 0, "trap": "le matricule — a real word for a staff number, but not what a Belgian eID carries", "expl": "All four masculine. Eleven digits built from your date of birth, and the key to every Belgian administration.", "note": "Belgian institution: your employer, bank and mutuelle will all ask for it."}, {"id": "ex-interview-A2-14", "level": "A2", "pos": "expr", "fr": "je vous remercie de m'avoir reçu", "en": "thank you for seeing me", "format": "collocation", "q": "Which closing line is correct?", "options": ["Je vous remercie de m'avoir reçu.", "Je vous remercie de m'avoir recevoir.", "Je vous remercie pour me recevoir.", "Je vous remercie de m'avoir accepté."], "a": 0, "trap": "« de m'avoir accepté » says you already have the job", "expl": "« remercier quelqu'un de + past infinitive » is the pattern: de m'avoir reçu, de m'avoir répondu, de m'avoir aidé."}]},
  "interview-B1": {"slug": "interview", "level": "B1", "title": "Deuxième entretien : un trou dans le CV et une négociation salariale", "place": "Bureaux de Verbeeck & Partners, avenue Louise, Ixelles", "register": "vous", "registerNote": "Vous with the HR manager and with the head of department, and vous even while you are negotiating money. Belgian interviews stay formal to the end of the process; the first tu usually arrives on your first working day, proposed by a colleague, not by you.", "vocab": [{"id": "fvc-interview-B1-01", "level": "B1", "pos": "noun", "gender": "m", "fr": "le parcours", "en": "the career path", "format": "fr2en", "options": ["your career path so far", "a training course", "a running track", "a job description"], "a": 0, "trap": "le cursus — the academic track; « le parcours » covers studies and jobs together", "expl": "« Parlez-moi de votre parcours » is the standard second-interview opener: tell it as a line, not as a list."}, {"id": "fvc-interview-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la période d'inactivité", "en": "the gap in employment", "format": "en2fr", "options": ["la période d'inactivité", "la période d'essai", "la période de préavis", "la période de référence"], "a": 0, "trap": "la période d'essai — the trial period, which is about to matter in this same conversation", "expl": "All four feminine. Recruiters say « un trou dans le CV » informally. Name what you did in it; never leave it unexplained."}, {"id": "fvc-interview-B1-03", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fin de contrat", "en": "the end of a fixed-term contract", "format": "fr2en", "options": ["a contract simply running to its term", "a dismissal", "a resignation", "a mutual termination"], "a": 0, "trap": "le licenciement — a dismissal; the difference matters to a recruiter and to ONEM", "expl": "« C'était une fin de CDD, pas un licenciement. » Neutral, verifiable, and it closes the question."}, {"id": "fvc-interview-B1-04", "level": "B1", "pos": "noun", "gender": "m", "fr": "le licenciement", "en": "the dismissal", "format": "fr2en", "options": ["dismissal decided by the employer", "resignation decided by the employee", "the notice period served afterwards", "the end of a fixed-term contract"], "a": 0, "trap": "la démission — a resignation, the same departure decided from the other side", "expl": "« le licenciement » is the employer's decision; « la démission » is yours; « la fin de contrat » is neither. All three end up on a C4 with a different reason."}, {"id": "fvc-interview-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "le C4", "en": "the end-of-employment form", "format": "collocation", "q": "What is a Belgian C4?", "options": ["Le document que l'employeur remet à la fin du contrat, pour l'ONEM.", "Le contrat de travail lui-même.", "La fiche de paie du dernier mois.", "Le certificat médical d'aptitude."], "a": 0, "trap": "assuming it is the contract — the C4 is what ends it and what unlocks unemployment benefit", "expl": "It states the dates and the reason for leaving. Read it before you sign: the stated reason affects your right to benefit.", "note": "Belgian institution with no French equivalent; « avoir son C4 » is everyday slang for being sacked."}, {"id": "fvc-interview-B1-06", "level": "B1", "pos": "noun", "gender": "f", "fr": "la commission paritaire", "en": "the joint committee", "format": "fr2en", "options": ["the sectoral body that sets minimum pay and conditions", "the interview panel", "an equal-opportunities committee", "the works council of a company"], "a": 0, "trap": "'parity committee' read as gender parity — « paritaire » here means employers and unions in equal number", "expl": "Every Belgian employer belongs to one, numbered (CP 200 is the big white-collar one). It fixes « les barèmes », holidays and premiums.", "note": "Belgian institution: ask which CP applies — it tells you the legal minimum for the job."}, {"id": "fvc-interview-B1-07", "level": "B1", "pos": "noun", "gender": "m", "fr": "le barème", "en": "the pay scale", "format": "cloze", "q": "Le salaire suit le ___ de la commission paritaire, selon l'ancienneté.", "options": ["barème", "budget", "bilan", "bulletin"], "a": 0, "trap": "le bulletin — the payslip in some contexts, and a school report in others", "expl": "All four masculine. « le barème » is the published grid: function classification on one axis, years of experience on the other."}, {"id": "fvc-interview-B1-08", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'ancienneté", "en": "length of service", "format": "fr2en", "options": ["years of service or recognised experience", "old age", "seniority in rank", "an antique"], "a": 0, "trap": "'seniority' as rank — in Belgian pay it is purely a count of years", "expl": "« reprise d'ancienneté » = getting your previous years recognised on the new employer's scale. Ask for it explicitly."}, {"id": "fvc-interview-B1-09", "level": "B1", "pos": "noun", "gender": "m", "fr": "le package salarial", "en": "the total package", "format": "collocation", "q": "Which of these is NOT normally part of a Belgian package salarial?", "options": ["le précompte immobilier", "l'assurance groupe", "les éco-chèques", "l'assurance hospitalisation"], "a": 0, "trap": "all four sound administrative; only one is a property tax and has nothing to do with your pay", "expl": "A Belgian package is brut + chèques-repas + éco-chèques + assurance groupe + hospitalisation + transport, sometimes a car or a mobility budget."}, {"id": "fvc-interview-B1-10", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'assurance groupe", "en": "the occupational pension scheme", "format": "fr2en", "options": ["an employer-funded supplementary pension", "group health cover", "collective liability insurance", "insurance for the whole team's equipment"], "a": 0, "trap": "l'assurance hospitalisation — the health cover, which is a separate benefit in the same list", "expl": "The second pillar of the Belgian pension system, funded by the employer, sometimes with a small employee share.", "note": "Belgian institution: ask what percentage of your brut goes in, since that is what varies."}, {"id": "fvc-interview-B1-11", "level": "B1", "pos": "noun", "gender": "m", "fr": "les éco-chèques", "en": "eco-vouchers", "format": "fr2en", "options": ["annual vouchers for ecological products and services", "a bonus for cycling to work", "a discount on your energy bill", "a company car allowance"], "a": 0, "trap": "les chèques-repas — the daily meal vouchers; éco-chèques come once a year and buy different things", "expl": "Up to 250 € a year in most sectors, untaxed, spendable on a defined list: appliances, bikes, insulation, public transport.", "note": "Belgian institution: check the expiry date, they lapse after 24 months."}, {"id": "fvc-interview-B1-12", "level": "B1", "pos": "noun", "gender": "m", "fr": "le budget mobilité", "en": "the mobility budget", "format": "collocation", "q": "What can a Belgian budget mobilité be spent on?", "options": ["Une voiture plus petite, les transports en commun, un vélo, ou du cash imposé.", "Uniquement une voiture de société.", "Uniquement l'abonnement STIB.", "N'importe quel achat personnel."], "a": 0, "trap": "assuming it is just a car budget — the point of the scheme is to let you swap the car for something else", "expl": "It converts the cost of a company car into three pillars: a greener car, sustainable transport, or the balance in cash.", "note": "Belgian scheme, increasingly offered instead of a voiture de société in Brussels."}, {"id": "fvc-interview-B1-13", "level": "B1", "pos": "noun", "gender": "f", "fr": "la fourchette salariale", "en": "the salary range", "format": "cloze", "q": "Quelle est la ___ salariale prévue pour ce poste ?", "options": ["fourchette", "grille", "échelle", "marge"], "a": 0, "trap": "la grille — the pay grid, which is the whole table rather than the range for this job", "expl": "All four feminine. « une fourchette entre 3 200 et 3 600 € brut » is how a Belgian recruiter states it."}, {"id": "fvc-interview-B1-14", "level": "B1", "pos": "noun", "gender": "f", "fr": "la marge de négociation", "en": "room for negotiation", "format": "fr2en", "options": ["how much movement there is on the offer", "the profit margin of the company", "the deadline for answering", "the difference between brut and net"], "a": 0, "trap": "la marge bénéficiaire — the profit margin, a different accounting word", "expl": "« Il y a une marge de négociation ? » is a fair, normal question in Belgium — asked once, calmly, and then dropped."}, {"id": "fvc-interview-B1-15", "level": "B1", "pos": "noun", "gender": "f", "fr": "la clause d'essai", "en": "the trial clause", "format": "collocation", "q": "What changed for Belgian employment contracts on 1 August 2026?", "options": ["Pendant les six premiers mois, chaque partie peut rompre avec une semaine de préavis.", "La période d'essai de trois mois est revenue telle quelle.", "Le préavis a été supprimé pendant six mois.", "Les CDD sont devenus des CDI automatiquement."], "a": 0, "trap": "the classic three-month trial period — abolished in 2014 and not what came back", "expl": "The law of 2026 shortens notice at the start instead: one week either way during the first six months, for contracts starting on or after 1 August 2026.", "note": "Belgian rule, brand new. Contracts already running are unaffected."}, {"id": "fvc-interview-B1-16", "level": "B1", "pos": "noun", "gender": "m", "fr": "le préavis", "en": "the notice period", "format": "cloze", "q": "Je dois respecter un ___ de six semaines chez mon employeur actuel.", "options": ["préavis", "délai", "engagement", "contrat"], "a": 0, "trap": "le délai — a time limit in general; the one you serve before leaving a job is « le préavis »", "expl": "Under the statut unique, the notice an employee gives is about half of what the employer would give, capped at 13 weeks.", "note": "Belgian rule since 2014: notice is counted in weeks and starts on the Monday after notification."}, {"id": "fvc-interview-B1-17", "level": "B1", "pos": "noun", "gender": "f", "fr": "la clause de non-concurrence", "en": "the non-compete clause", "format": "fr2en", "options": ["a clause restricting where you may work next", "a clause about competition between colleagues", "a confidentiality clause", "an exclusivity clause on your time"], "a": 0, "trap": "la clause de confidentialité — about information, not about your next employer", "expl": "In Belgium it is valid only above a salary threshold, limited in time and geography, and must be paid for by the employer."}, {"id": "fvc-interview-B1-18", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'entrée en fonction", "en": "the start date", "format": "en2fr", "options": ["l'entrée en fonction", "l'entrée en vigueur", "l'entrée en matière", "l'entrée en scène"], "a": 0, "trap": "l'entrée en vigueur — when a rule or a lease takes effect, not when a person starts a job", "expl": "All four feminine. « Une entrée en fonction souhaitée au 1er septembre » is standard Belgian HR phrasing.", "note": "Belgian usage; France often says « la prise de poste »."}, {"id": "fvc-interview-B1-19", "level": "B1", "pos": "noun", "gender": "f", "fr": "la prise de références", "en": "the reference check", "format": "fr2en", "options": ["contacting your former employers", "collecting your certificates", "checking your criminal record", "verifying your diplomas"], "a": 0, "trap": "l'extrait de casier judiciaire — the criminal record extract, a separate step for some jobs", "expl": "In Belgium references are usually taken only with your agreement and at the end. Warn the people you name."}, {"id": "fvc-interview-B1-20", "level": "B1", "pos": "noun", "gender": "f", "fr": "la promesse d'embauche", "en": "the written job offer", "format": "cloze", "q": "Est-ce que je peux recevoir une ___ d'embauche par écrit ?", "options": ["promesse", "preuve", "proposition", "présentation"], "a": 0, "trap": "une proposition — real and weaker; a promesse d'embauche binds the employer", "expl": "All four feminine. Never resign from your current job on a verbal offer: ask for the promesse d'embauche or the signed contract first."}, {"id": "fvc-interview-B1-21", "level": "B1", "pos": "noun", "gender": "m", "fr": "l'entretien d'évaluation", "en": "the appraisal", "format": "en2fr", "options": ["l'entretien d'évaluation", "l'entretien d'embauche", "l'entretien préalable", "l'entretien téléphonique"], "a": 0, "trap": "l'entretien d'embauche — the interview you are sitting in right now", "expl": "All four masculine. « une évaluation annuelle » is where a salary review is normally decided, so ask when it falls."}, {"id": "fvc-interview-B1-22", "level": "B1", "pos": "noun", "gender": "m", "fr": "le supérieur hiérarchique", "en": "the line manager", "format": "fr2en", "options": ["the person you report to", "the head of the whole company", "a colleague with more experience", "the HR manager"], "a": 0, "trap": "le chef d'entreprise — the head of the company, which is not usually who you report to", "expl": "« À qui est-ce que je rapporterais ? » is the practical version of the question, and it tells you a lot about the job."}, {"id": "fvc-interview-B1-23", "level": "B1", "pos": "noun", "gender": "f", "fr": "la charge de travail", "en": "the workload", "format": "cloze", "q": "Comment est-ce que la ___ de travail est répartie dans l'équipe ?", "options": ["charge", "quantité", "somme", "part"], "a": 0, "trap": "la quantité — grammatically fine, and it turns a professional question into an accusation", "expl": "All four feminine. « la charge de travail » is the neutral HR term; asking how it is shared is a fair question."}, {"id": "fvc-interview-B1-24", "level": "B1", "pos": "verb", "fr": "encadrer", "en": "to supervise (people)", "format": "fr2en", "options": ["to supervise and support a team", "to frame a picture", "to set boundaries for a project", "to train someone from scratch"], "a": 0, "trap": "the literal sense — encadrer really does mean to frame, and both meanings are alive", "expl": "« J'ai encadré deux stagiaires » is a strong, modest way to show responsibility without claiming to be a manager."}, {"id": "fvc-interview-B1-25", "level": "B1", "pos": "verb", "fr": "coordonner", "en": "to coordinate", "format": "en2fr", "options": ["coordonner", "ordonner", "commander", "administrer"], "a": 0, "trap": "ordonner — to order someone to do something; a very different picture of how you work", "expl": "All four infinitives. « coordonner un projet entre trois services » is the phrase that describes most office jobs honestly."}, {"id": "fvc-interview-B1-26", "level": "B1", "pos": "verb", "fr": "mettre en place", "en": "to set up / introduce", "format": "cloze", "q": "J'ai ___ en place un nouveau système de suivi des dossiers.", "options": ["mis", "pris", "fait", "remis"], "a": 0, "trap": "fait — « faire en place » does not exist, though it feels like it should", "expl": "« mettre en place » is the standard verb for introducing a process. In the passé composé: j'ai mis en place."}, {"id": "fvc-interview-B1-27", "level": "B1", "pos": "verb", "fr": "faire face à", "en": "to cope with", "format": "fr2en", "options": ["to deal with a difficulty", "to face someone physically", "to confront a colleague", "to look like someone"], "a": 0, "trap": "'to face off against' — in French this phrase is about coping, not about confrontation", "expl": "« faire face à une charge de travail importante » — good material for the 'difficult situation' question."}, {"id": "fvc-interview-B1-28", "level": "B1", "pos": "verb", "fr": "se former", "en": "to train oneself", "format": "cloze", "q": "Pendant cette période, je me suis ___ au néerlandais et à la comptabilité.", "options": ["formé", "informé", "présenté", "occupé"], "a": 0, "trap": "informé — 'informed myself about', which sounds like reading rather than studying", "expl": "All four are past participles with être. « se former à quelque chose » is the verb that turns a gap into a choice."}, {"id": "fvc-interview-B1-29", "level": "B1", "pos": "verb", "fr": "justifier", "en": "to account for / to justify", "format": "fr2en", "options": ["to give a reason or evidence for something", "to prove someone wrong", "to align text on a page", "to excuse oneself"], "a": 0, "trap": "'to justify' as self-defence; in a Belgian job ad « justifier de trois ans d'expérience » simply means to have it and show it", "expl": "Two uses: « justifier une absence » (account for) and « justifier de cinq ans d'expérience » (to be able to show)."}, {"id": "fvc-interview-B1-30", "level": "B1", "pos": "verb", "fr": "valoriser", "en": "to make the most of", "format": "en2fr", "options": ["valoriser", "évaluer", "valider", "valser"], "a": 0, "trap": "évaluer — to assess; « valoriser » is to bring value out of something", "expl": "All four infinitives. « valoriser mon expérience à l'étranger » — the verb Belgian recruiters use about a CV."}, {"id": "fvc-interview-B1-31", "level": "B1", "pos": "adj", "fr": "négociable", "en": "negotiable", "format": "cloze", "q": "Est-ce que le montant est ___, ou est-ce qu'il est fixé par le barème ?", "options": ["négociable", "négligeable", "nécessaire", "négatif"], "a": 0, "trap": "négligeable — 'negligible', a lookalike that would insult the offer rather than question it", "expl": "All four are masculine adjectives. « Est-ce que c'est négociable ? » is the neutral way to open a salary discussion; the noun is « la marge de négociation »."}, {"id": "fvc-interview-B1-32", "level": "B1", "pos": "verb", "fr": "revoir à la hausse", "en": "to revise upwards", "format": "fr2en", "options": ["to increase after a review", "to look at something again", "to raise a hand", "to review downwards"], "a": 0, "trap": "« revoir à la baisse » — the same structure going the other way, and the one you do not want", "expl": "« Le salaire sera revu à la hausse après l'évaluation annuelle » — get the review date in writing, not just the promise."}, {"id": "fvc-interview-B1-33", "level": "B1", "pos": "adj", "fr": "polyvalent", "en": "versatile", "format": "fr2en", "options": ["able to do several different jobs", "highly specialised", "flexible about working hours", "multilingual"], "a": 0, "trap": "'polyvalent' misread as multilingual — that is « polyglotte »", "expl": "« un profil polyvalent » is a compliment in a small Belgian company and a warning about workload in a large one."}, {"id": "fvc-interview-B1-34", "level": "B1", "pos": "adj", "fr": "rigoureux", "en": "thorough, methodical", "format": "en2fr", "options": ["rigoureux", "rigide", "sévère", "strict"], "a": 0, "trap": "rigide — inflexible, which is what you sound like if you pick the wrong word about yourself", "expl": "All four masculine adjectives. « rigoureux » praises method; « rigide » criticises character."}, {"id": "fvc-interview-B1-35", "level": "B1", "pos": "adj", "fr": "opérationnel", "en": "up and running / effective", "format": "cloze", "q": "Je serai ___ dès les premières semaines, le logiciel m'est familier.", "options": ["opérationnel", "optionnel", "occasionnel", "officiel"], "a": 0, "trap": "optionnel — 'optional', which is an unfortunate thing to call yourself", "expl": "All four masculine adjectives. « être opérationnel rapidement » is exactly what a recruiter wants to hear and to believe."}, {"id": "fvc-interview-B1-36", "level": "B1", "pos": "expr", "fr": "à mon sens", "en": "in my view", "format": "en2fr", "options": ["à mon sens", "à mon avis de moi", "dans mon sens", "selon moi-même"], "a": 0, "trap": "« dans mon sens » exists but means 'in my direction' — as in « aller dans mon sens », to agree with me", "expl": "All four look like opinion phrases; only « à mon sens » and « à mon avis » are real. The first is slightly more formal."}, {"id": "fvc-interview-B1-37", "level": "B1", "pos": "expr", "fr": "dans un premier temps", "en": "to begin with", "format": "fr2en", "options": ["initially, in the first stage", "at the same time", "in the past", "as soon as possible"], "a": 0, "trap": "'in first time' read literally; the phrase is about sequence, not about speed", "expl": "« Dans un premier temps, je m'occuperais des dossiers ; dans un second temps, du contact client. » Structures an answer in one move."}, {"id": "fvc-interview-B1-38", "level": "B1", "pos": "expr", "fr": "ce qui explique que", "en": "which is why", "format": "cloze", "q": "J'ai suivi une formation intensive, ce qui explique ___ je n'ai pas travaillé pendant six mois.", "options": ["que", "qui", "pourquoi", "dont"], "a": 0, "trap": "pourquoi — « ce qui explique pourquoi » is heard, and is redundant in careful French", "expl": "« ce qui explique que » + clause, normally with the subjunctive: « ce qui explique que je n'aie pas travaillé ». Elegant, neutral, and exactly the tool for a gap in a CV."}, {"id": "fvc-interview-B1-39", "level": "B1", "pos": "expr", "fr": "je me permets d'insister", "en": "if I may press the point", "format": "fr2en", "options": ["if I may come back to this once more", "I refuse to move", "I would like to change the subject", "I insist on being paid"], "a": 0, "trap": "hearing 'insist' as an ultimatum; the « je me permets » turns it into a courtesy", "expl": "Use it once in a salary conversation, never twice. After that, ask for the offer in writing and think about it."}, {"id": "fvc-interview-B1-40", "level": "B1", "pos": "noun", "gender": "m", "fr": "Le Forem", "en": "the Walloon employment service", "format": "collocation", "q": "You apply for a job in Namur while living in Brussels. Which service covers that job's region?", "options": ["Le Forem", "Actiris", "Le VDAB", "L'ONEM"], "a": 0, "trap": "Actiris — where you are registered, which is not the same as where the job is", "expl": "Le Forem for Wallonia, Actiris for Brussels, VDAB for Flanders, ADG for the German-speaking Community. All four publish separate vacancies.", "note": "Belgian institutions: worth searching all three sites if you are in Brussels, since commuting is easy."}, {"id": "fvc-interview-B1-41", "level": "B1", "pos": "noun", "gender": "f", "fr": "la reprise d'ancienneté", "en": "recognition of previous service", "format": "fr2en", "options": ["counting your previous years on the new employer's pay scale", "returning to a previous employer", "a pay rise after one year", "the transfer of your pension rights"], "a": 0, "trap": "le transfert de l'assurance groupe — moving your pension pot, which is a separate operation", "expl": "It can be worth several hundred euros a month on a barème. Ask for it by name, and ask for it in writing."}, {"id": "fvc-interview-B1-42", "level": "B1", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "cloze", "q": "Nous pouvons monter à trois mille trois cent ___ euros brut.", "options": ["nonante", "septante", "quarante", "cinquante"], "a": 0, "trap": "septante — the other Belgian form; in a salary negotiation the twenty euros are real money", "expl": "trois mille trois cent nonante = 3 390 €. Repeat the figure back before you agree to it.", "note": "Belgian French. France: trois mille trois cent quatre-vingt-dix."}, {"id": "fvc-interview-B1-43", "level": "B1", "pos": "noun", "gender": "m", "fr": "le délai de réflexion", "en": "time to think it over", "format": "cloze", "q": "Est-ce que je peux avoir un ___ de réflexion de quelques jours ?", "options": ["délai", "temps", "moment", "retard"], "a": 0, "trap": "le retard — a delay in the sense of lateness, which is not what you are asking for", "expl": "All four masculine. Asking for two or three days is normal in Belgium and does not weaken your position."}, {"id": "fvc-interview-B1-44", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trou dans le CV", "en": "the gap in the CV", "format": "collocation", "q": "How do you best handle a six-month gap in a Belgian interview?", "options": ["Le nommer, dire ce que vous y avez fait, puis passer à la suite.", "Ne pas en parler et espérer que personne ne remarque.", "Dire que vous étiez malade, même si c'est faux.", "Modifier les dates sur le CV pour le faire disparaître."], "a": 0, "trap": "hiding it — the dates are on the C4 and on your ONEM record, so it will be visible anyway", "expl": "Name it, fill it with something real (a course, a language, a family reason, freelance work), and move on in two sentences."}, {"id": "fvc-interview-B1-45", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'allocation de chômage", "en": "the unemployment benefit", "format": "en2fr", "options": ["l'allocation de chômage", "l'allocation familiale", "l'indemnité de préavis", "l'assurance maladie"], "a": 0, "trap": "l'indemnité de préavis — pay in lieu of notice, which comes from the employer rather than from the state", "expl": "All four feminine. Paid by ONEM/RVA through your union or the CAPAC, on the basis of your C4.", "note": "Belgian system: you register with Actiris, but the payment comes through ONEM."}, {"id": "fvc-interview-B1-46", "level": "B1", "pos": "expr", "fr": "par écrit", "en": "in writing", "format": "cloze", "q": "Je préférerais recevoir l'offre ___ écrit avant de donner ma démission.", "options": ["par", "en", "sur", "à"], "a": 0, "trap": "en — « en écrit » does not exist, although « en anglais » and « en gras » make it feel possible", "expl": "« par écrit » is fixed. Never resign on a verbal promise: ask for the promesse d'embauche or the signed contract."}], "phrases": [{"id": "ph-interview-B1-01", "fr": "Merci de me recevoir une deuxième fois.", "en": "Thank you for seeing me a second time.", "note": "« recevoir quelqu'un » = to see someone for a meeting. A one-line opener that sets a professional tone."}, {"id": "ph-interview-B1-02", "fr": "Entre mars et septembre dernier, j'ai suivi une formation intensive en néerlandais.", "en": "Between last March and September I did an intensive Dutch course.", "note": "Name the gap with dates before they do, and fill it with something specific. « suivre une formation » is the fixed verb."}, {"id": "ph-interview-B1-03", "fr": "C'était une fin de contrat à durée déterminée, pas un licenciement.", "en": "It was the end of a fixed-term contract, not a dismissal.", "note": "The distinction matters in Belgium: it appears on your C4 and it changes how a recruiter reads the gap."}, {"id": "ph-interview-B1-04", "fr": "J'ai mon C4 si vous souhaitez le consulter.", "en": "I have my C4 if you'd like to see it.", "note": "Offering it closes the subject instantly. The C4 states the dates and the reason for the end of the contract."}, {"id": "ph-interview-B1-05", "fr": "Ce qui explique que je n'aie pas travaillé pendant six mois.", "en": "Which is why I didn't work for six months.", "note": "« ce qui explique que » is normally followed by the subjunctive: que je n'aie pas travaillé. You will hear the indicative too, but this is the safer form."}, {"id": "ph-interview-B1-06", "fr": "Dans mon poste précédent, j'ai mis en place un nouveau système de suivi.", "en": "In my previous job I set up a new tracking system.", "note": "« mettre en place » — the standard verb for introducing a process. One concrete example beats three adjectives."}, {"id": "ph-interview-B1-07", "fr": "J'ai encadré deux stagiaires pendant six mois.", "en": "I supervised two interns for six months.", "note": "« encadrer » shows responsibility without claiming a title you did not have. « un stagiaire » is an intern."}, {"id": "ph-interview-B1-08", "fr": "J'ai dû faire face à une charge de travail importante après un départ.", "en": "I had to cope with a heavy workload after someone left.", "note": "« faire face à » = to cope with. Perfect material for the « une situation difficile » question."}, {"id": "ph-interview-B1-09", "fr": "Je serais opérationnel rapidement, le logiciel m'est familier.", "en": "I'd be up and running quickly, the software is familiar to me.", "note": "The conditional « je serais » is the right tense for a job you do not have yet. « m'est familier » avoids « je connais bien »."}, {"id": "ph-interview-B1-10", "fr": "Quelle est la fourchette salariale prévue pour ce poste ?", "en": "What's the salary range planned for this position?", "note": "Ask for the range rather than announcing a number first. Belgian recruiters expect the question."}, {"id": "ph-interview-B1-11", "fr": "À quelle commission paritaire est-ce que l'entreprise appartient ?", "en": "Which joint committee does the company belong to?", "note": "It tells you the legal minimum scales, the holidays and the premiums for the whole sector. A very Belgian question to be able to ask."}, {"id": "ph-interview-B1-12", "fr": "Est-ce qu'une reprise d'ancienneté est possible pour mes trois années d'expérience ?", "en": "Is it possible to have my three years of experience recognised on the scale?", "note": "Ask by name. It can be worth more than a negotiated bonus, and it stays with you for the whole career."}, {"id": "ph-interview-B1-13", "fr": "Compte tenu de mon expérience, je visais plutôt trois mille cinq cents euros brut.", "en": "Given my experience, I was aiming rather at three thousand five hundred gross.", "note": "The imperfect « je visais » softens a figure into an expectation. « compte tenu de » gives it a reason."}, {"id": "ph-interview-B1-14", "fr": "Est-ce qu'il y a une marge de négociation, ou est-ce que le barème est fixe ?", "en": "Is there room for negotiation, or is the scale fixed?", "note": "Asking it this way gives the recruiter an honourable way out and keeps the conversation friendly."}, {"id": "ph-interview-B1-15", "fr": "Qu'est-ce que comprend le package : assurance groupe, éco-chèques, hospitalisation ?", "en": "What does the package include: pension scheme, eco-vouchers, health cover?", "note": "Naming the three shows you know the Belgian market. The package is often where the real difference sits."}, {"id": "ph-interview-B1-16", "fr": "Est-ce que le salaire est revu à la hausse après l'évaluation annuelle ?", "en": "Is the salary revised upwards after the annual appraisal?", "note": "Ask when the appraisal falls, not just whether there is one. A date makes the promise real."}, {"id": "ph-interview-B1-17", "fr": "Si je comprends bien, pendant les six premiers mois le préavis est d'une semaine.", "en": "If I understand correctly, during the first six months the notice period is one week.", "note": "The rule for contracts starting on or after 1 August 2026 in Belgium. Reformulating it shows you follow — and checks it."}, {"id": "ph-interview-B1-18", "fr": "Je dois respecter un préavis de six semaines chez mon employeur actuel.", "en": "I have to serve six weeks' notice with my current employer.", "note": "Belgian notice runs in weeks and starts the Monday after you notify. Know your figure before the interview."}, {"id": "ph-interview-B1-19", "fr": "Est-ce que je peux avoir un délai de réflexion de quelques jours ?", "en": "Could I have a few days to think it over?", "note": "Normal and expected. Nobody in Belgium holds it against a candidate; a same-day yes is not a sign of enthusiasm."}, {"id": "ph-interview-B1-20", "fr": "Je préférerais recevoir l'offre par écrit avant de donner ma démission.", "en": "I'd rather have the offer in writing before I resign.", "note": "The single most important sentence of the whole process. Verbal offers evaporate; a promesse d'embauche binds."}], "dialogue": [{"who": "recruiter", "fr": "Rebonjour, monsieur Vasileiadis. Je suis accompagnée aujourd'hui de monsieur Dumont, qui dirige le service.", "en": "Hello again, Mr Vasileiadis. Today I'm joined by Mr Dumont, who heads the department.", "gloss": {"accompagnée": "accompanied", "dirige": "heads, runs", "service": "department"}}, {"who": "you", "fr": "Bonjour madame, bonjour monsieur. Merci de me recevoir une deuxième fois.", "en": "Hello, hello. Thank you for seeing me a second time.", "gloss": {"de me recevoir": "for seeing me"}, "accept": ["bonjour madame bonjour monsieur merci de me recevoir une deuxième fois", "bonjour madame bonjour monsieur merci de me recevoir", "bonjour à tous les deux merci de me recevoir une deuxième fois", "bonjour madame bonjour monsieur je vous remercie de me recevoir une deuxième fois", "bonjour merci beaucoup de me recevoir une deuxième fois", "bonjour madame bonjour monsieur enchanté merci de me recevoir"]}, {"who": "recruiter", "fr": "J'ai repris votre CV. Il y a une période entre mars et septembre de l'an dernier où vous n'avez pas travaillé. Vous pouvez m'en dire un mot ?", "en": "I went back over your CV. There's a period between March and September last year when you weren't working. Could you say a word about it?", "gloss": {"repris": "gone back over", "période": "period", "m'en dire un mot": "say a word to me about it"}}, {"who": "you", "fr": "Bien sûr. Mon contrat à durée déterminée est arrivé à son terme fin février. J'ai suivi une formation intensive en néerlandais, ce qui explique que je n'aie pas travaillé pendant six mois.", "en": "Of course. My fixed-term contract came to its end at the end of February. I did an intensive Dutch course, which is why I didn't work for six months.", "gloss": {"à son terme": "to its end", "suivi une formation": "did a course", "ce qui explique que": "which is why"}, "accept": ["bien sûr mon contrat à durée déterminée est arrivé à son terme fin février j'ai suivi une formation intensive en néerlandais ce qui explique que je n'aie pas travaillé pendant six mois", "bien sûr mon contrat à durée déterminée est arrivé à son terme fin février et j'ai suivi une formation intensive en néerlandais", "oui bien sûr mon cdd s'est terminé fin février et j'ai suivi une formation intensive en néerlandais pendant six mois", "bien sûr c'était la fin de mon contrat à durée déterminée et j'ai suivi une formation en néerlandais", "avec plaisir mon cdd est arrivé à son terme fin février ensuite j'ai fait une formation intensive en néerlandais", "bien sûr après la fin de mon contrat à durée déterminée j'ai suivi une formation intensive en néerlandais ce qui explique cette période"]}, {"who": "recruiter", "fr": "C'était donc une fin de contrat, pas un licenciement ?", "en": "So it was the end of a contract, not a dismissal?", "gloss": {"fin de contrat": "the contract simply running out", "licenciement": "dismissal"}}, {"who": "you", "fr": "Exactement, une fin de CDD. J'ai mon C4 si vous souhaitez le consulter, et j'étais inscrit chez Actiris pendant cette période.", "en": "Exactly, the end of a fixed-term contract. I have my C4 if you'd like to see it, and I was registered with Actiris during that period.", "gloss": {"CDD": "fixed-term contract", "C4": "the Belgian end-of-employment form", "inscrit": "registered", "Actiris": "the Brussels employment service"}, "accept": ["exactement une fin de cdd j'ai mon c4 si vous souhaitez le consulter et j'étais inscrit chez actiris pendant cette période", "exactement une fin de cdd j'ai mon c4 si vous voulez le consulter", "oui exactement c'était une fin de contrat à durée déterminée j'ai mon c4 et j'étais inscrit chez actiris", "c'est exact une fin de cdd je peux vous montrer mon c4 si vous le souhaitez", "exactement ce n'était pas un licenciement j'ai mon c4 et j'étais inscrit chez actiris", "tout à fait une fin de cdd j'ai le c4 avec moi si vous voulez le voir"]}, {"who": "head", "fr": "Parlons du travail lui-même. Racontez-moi une situation difficile que vous avez dû gérer.", "en": "Let's talk about the work itself. Tell me about a difficult situation you had to handle.", "gloss": {"Racontez-moi": "tell me about", "gérer": "to handle"}}, {"who": "you", "fr": "Après le départ d'une collègue, j'ai dû faire face à une charge de travail importante pendant trois mois. J'ai mis en place un système de suivi des dossiers, et nous avons tenu les délais.", "en": "After a colleague left, I had to cope with a heavy workload for three months. I set up a file-tracking system, and we met the deadlines.", "gloss": {"faire face à": "to cope with", "charge de travail": "workload", "mis en place": "set up", "tenu les délais": "met the deadlines"}, "accept": ["après le départ d'une collègue j'ai dû faire face à une charge de travail importante pendant trois mois j'ai mis en place un système de suivi des dossiers et nous avons tenu les délais", "après le départ d'une collègue j'ai dû faire face à une charge de travail importante j'ai mis en place un système de suivi des dossiers", "quand une collègue est partie j'ai dû gérer une charge de travail importante et j'ai mis en place un système de suivi", "une collègue est partie et j'ai dû faire face à beaucoup de travail j'ai mis en place un nouveau suivi des dossiers", "après le départ d'une collègue la charge de travail est devenue importante j'ai mis en place un système de suivi et nous avons tenu les délais", "j'ai dû faire face à une charge de travail importante après un départ et j'ai mis en place un système de suivi des dossiers"]}, {"who": "head", "fr": "Bien. Et concrètement, en néerlandais, vous en êtes où aujourd'hui ?", "en": "Good. And in practical terms, where are you with your Dutch today?", "gloss": {"concrètement": "in practical terms", "vous en êtes où": "where have you got to"}}, {"who": "you", "fr": "Je suis passé de A2 à B1 grâce à la formation. Je comprends les réunions, mais j'ai encore difficile à répondre vite. Je continue les cours deux soirs par semaine.", "en": "I went from A2 to B1 thanks to the course. I understand meetings, but I still find it hard to answer quickly. I'm carrying on with classes two evenings a week.", "gloss": {"grâce à": "thanks to", "j'ai encore difficile": "I still find it hard (Belgian French; France: j'ai encore du mal)", "réunions": "meetings"}, "accept": ["je suis passé de a2 à b1 grâce à la formation je comprends les réunions mais j'ai encore difficile à répondre vite je continue les cours deux soirs par semaine", "je suis passé de a2 à b1 grâce à la formation je comprends les réunions mais j'ai encore difficile à répondre vite", "je suis passé de a2 à b1 je comprends les réunions mais j'ai encore du mal à répondre rapidement", "grâce à la formation je suis passé de a2 à b1 je comprends les réunions et je continue les cours", "je suis au niveau b1 maintenant je comprends les réunions mais répondre vite est encore difficile", "je suis passé de a2 à b1 je comprends bien mais j'ai encore difficile à répondre vite en réunion"]}, {"who": "recruiter", "fr": "Venons-en au salaire. Le poste suit le barème de la commission paritaire : nous proposons trois mille deux cents euros brut.", "en": "Let's come to the salary. The job follows the joint committee's scale: we're offering three thousand two hundred euros gross.", "gloss": {"barème": "pay scale", "commission paritaire": "sectoral joint committee", "Venons-en au": "let's come to"}}, {"who": "you", "fr": "Compte tenu de mes trois années d'expérience, je visais plutôt trois mille cinq cents. Est-ce qu'une reprise d'ancienneté est possible ?", "en": "Given my three years of experience, I was aiming rather at three thousand five hundred. Is recognition of previous service possible?", "gloss": {"Compte tenu de": "given", "je visais": "I was aiming at", "reprise d'ancienneté": "recognition of previous years on the pay scale"}, "accept": ["compte tenu de mes trois années d'expérience je visais plutôt trois mille cinq cents est-ce qu'une reprise d'ancienneté est possible", "compte tenu de mes trois années d'expérience je visais plutôt trois mille cinq cents", "vu mes trois années d'expérience je visais plutôt trois mille cinq cents euros est-ce qu'une reprise d'ancienneté est possible", "avec mes trois ans d'expérience j'espérais plutôt trois mille cinq cents euros brut", "compte tenu de mon expérience je visais trois mille cinq cents et je voulais savoir si une reprise d'ancienneté est possible", "j'avais plutôt en tête trois mille cinq cents euros brut est-ce qu'une reprise d'ancienneté est prévue"]}, {"who": "recruiter", "fr": "La reprise d'ancienneté, oui, sur trois ans. Cela nous amène à trois mille trois cent nonante. Au-delà, il n'y a pas de marge.", "en": "Recognition of service, yes, over three years. That brings us to three thousand three hundred and ninety. Beyond that there's no room.", "gloss": {"amène": "brings", "nonante": "ninety (Belgian French; France: quatre-vingt-dix)", "marge": "room, margin"}}, {"who": "you", "fr": "Je comprends. Et qu'est-ce que comprend le package : assurance groupe, éco-chèques, hospitalisation ? Et je me permets d'insister une seule fois : est-ce que le salaire pourrait être revu à la hausse après la première évaluation ?", "en": "I understand. And what does the package include: pension scheme, eco-vouchers, health cover? And if I may press the point just once: could the salary be revised upwards after the first appraisal?", "gloss": {"comprend": "includes", "assurance groupe": "occupational pension scheme", "éco-chèques": "annual eco-vouchers", "revu à la hausse": "revised upwards", "évaluation": "appraisal", "je me permets d'insister": "if I may press the point"}, "accept": ["je comprends et qu'est-ce que comprend le package assurance groupe éco-chèques hospitalisation et je me permets d'insister une seule fois est-ce que le salaire pourrait être revu à la hausse après la première évaluation", "je comprends et qu'est-ce que comprend le package assurance groupe éco-chèques hospitalisation", "d'accord qu'est-ce qu'il y a dans le package et est-ce que le salaire pourrait être revu à la hausse après la première évaluation", "je comprends et le package comprend quoi une assurance groupe des éco-chèques une hospitalisation", "je comprends et est-ce qu'il y a une assurance groupe des éco-chèques et est-ce que le salaire sera revu à la hausse après l'évaluation", "d'accord et qu'est-ce que comprend le package et est-ce qu'une révision à la hausse est possible après la première évaluation"]}, {"who": "recruiter", "fr": "Assurance groupe à quatre pour cent du brut, assurance hospitalisation pour vous et votre famille, deux cent cinquante euros d'éco-chèques par an, et le treizième mois. L'évaluation a lieu après douze mois, et une révision est possible à ce moment-là : je le noterai dans la proposition.", "en": "Pension scheme at four per cent of gross, health cover for you and your family, two hundred and fifty euros of eco-vouchers a year, and the thirteenth month. The appraisal takes place after twelve months, and a review is possible then: I'll note it in the offer.", "gloss": {"pour cent": "per cent", "hospitalisation": "hospital insurance", "treizième mois": "the December bonus", "a lieu": "takes place", "proposition": "offer"}}, {"who": "you", "fr": "Merci. Une question sur le contrat : si je comprends bien, pour les contrats qui commencent après le premier août 2026, le préavis est d'une semaine pendant les six premiers mois ?", "en": "Thank you. A question about the contract: if I understand correctly, for contracts starting after 1 August 2026, the notice period is one week during the first six months?", "gloss": {"préavis": "notice period", "les six premiers mois": "the first six months"}, "accept": ["merci une question sur le contrat si je comprends bien pour les contrats qui commencent après le premier août 2026 le préavis est d'une semaine pendant les six premiers mois", "merci une question sur le contrat si je comprends bien le préavis est d'une semaine pendant les six premiers mois", "merci et une question sur le contrat pour les contrats qui commencent après le premier août le préavis est bien d'une semaine pendant six mois", "merci si je comprends bien pendant les six premiers mois chacun peut rompre avec une semaine de préavis", "merci une question le préavis est bien d'une semaine pendant les six premiers mois pour les nouveaux contrats", "merci j'ai une question sur le contrat le nouveau régime prévoit une semaine de préavis pendant les six premiers mois c'est bien ça"]}, {"who": "recruiter", "fr": "C'est exact, des deux côtés. Ce n'est plus l'ancienne période d'essai, mais l'effet est comparable. Et chez votre employeur actuel, quel préavis devez-vous prester ?", "en": "That's right, on both sides. It isn't the old trial period any more, but the effect is comparable. And with your current employer, what notice do you have to work?", "gloss": {"des deux côtés": "on both sides", "période d'essai": "trial period", "prester": "to work, to serve (Belgian usage)"}}, {"who": "you", "fr": "Six semaines, qui commencent le lundi suivant ma démission. Je pourrais donc entrer en fonction début octobre.", "en": "Six weeks, which start on the Monday after I resign. So I could start at the beginning of October.", "gloss": {"démission": "resignation", "entrer en fonction": "to start the job"}, "accept": ["six semaines qui commencent le lundi suivant ma démission je pourrais donc entrer en fonction début octobre", "six semaines qui commencent le lundi suivant ma démission je pourrais entrer en fonction début octobre", "un préavis de six semaines qui commence le lundi après ma démission donc je serais disponible début octobre", "six semaines de préavis à partir du lundi suivant donc entrée en fonction début octobre", "je dois prester six semaines de préavis donc je pourrais commencer début octobre", "six semaines de préavis ce qui me permettrait d'entrer en fonction début octobre"]}, {"who": "recruiter", "fr": "Parfait. Nous prenons deux références, avec votre accord, et je reviens vers vous vendredi.", "en": "Perfect. We'll take two references, with your agreement, and I'll get back to you on Friday.", "gloss": {"références": "references", "avec votre accord": "with your agreement", "je reviens vers vous": "I'll get back to you"}}, {"who": "you", "fr": "Pas de problème, je vous envoie les coordonnées ce soir. Et je préférerais recevoir l'offre par écrit avant de donner ma démission.", "en": "No problem, I'll send you the contact details this evening. And I'd rather have the offer in writing before I resign.", "gloss": {"coordonnées": "contact details", "par écrit": "in writing", "démission": "resignation"}, "accept": ["pas de problème je vous envoie les coordonnées ce soir et je préférerais recevoir l'offre par écrit avant de donner ma démission", "pas de problème je vous envoie les coordonnées ce soir et je préférerais recevoir l'offre par écrit", "bien sûr je vous envoie les coordonnées ce soir et j'aimerais recevoir l'offre par écrit avant de démissionner", "d'accord je vous transmets les coordonnées ce soir et je voudrais l'offre par écrit avant de donner ma démission", "pas de problème je vous enverrai les coordonnées ce soir merci de m'envoyer l'offre par écrit avant que je démissionne", "très bien je vous envoie les coordonnées ce soir et je préfère avoir une promesse d'embauche écrite avant de démissionner"]}], "exercises": [{"id": "ex-interview-B1-01", "level": "B1", "pos": "noun", "gender": "m", "fr": "le C4", "en": "the end-of-employment form", "format": "collocation", "q": "Why does the C4 matter to you and not only to your employer?", "options": ["Le motif inscrit dessus conditionne votre droit aux allocations de chômage.", "Il fixe le montant de votre prochain salaire.", "Il remplace votre contrat de travail.", "Il sert de lettre de recommandation."], "a": 0, "trap": "treating it as a formality — the stated reason for leaving is the part that matters", "expl": "Read it before signing. A wrong or vague reason can delay or reduce your benefit from ONEM.", "note": "Belgian institution; there is no French equivalent document."}, {"id": "ex-interview-B1-02", "level": "B1", "pos": "noun", "gender": "f", "fr": "la commission paritaire", "en": "the joint committee", "format": "fr2en", "options": ["the sectoral body fixing minimum pay and conditions", "the company's works council", "a gender-parity committee", "the panel interviewing you"], "a": 0, "trap": "le conseil d'entreprise — the works council, which exists inside the company", "expl": "Employers and unions in equal number, per sector. CP 200 covers most white-collar staff and sets the scales.", "note": "Belgian institution: knowing your CP number tells you the legal minimum for the job."}, {"id": "ex-interview-B1-03", "level": "B1", "pos": "noun", "gender": "f", "fr": "la clause d'essai", "en": "the trial clause", "format": "cloze", "q": "Depuis le 1er août 2026, le préavis est d'une ___ pendant les six premiers mois.", "options": ["semaine", "quinzaine", "journée", "année"], "a": 0, "trap": "quinzaine — a fortnight, and the figure people expect from the pre-2014 rules", "expl": "One week, either side, for contracts whose execution starts on or after 1 August 2026. Contracts already running keep the old notice periods.", "note": "Belgian rule, in force since August 2026 — check which regime your contract falls under."}, {"id": "ex-interview-B1-04", "level": "B1", "pos": "noun", "gender": "f", "fr": "la reprise d'ancienneté", "en": "recognition of previous service", "format": "en2fr", "options": ["la reprise d'ancienneté", "la reprise du travail", "la prime d'ancienneté", "la reprise de contrat"], "a": 0, "trap": "la prime d'ancienneté — a long-service bonus, which is a different thing paid later", "expl": "Ask for it by name at the offer stage: it moves you up the barème permanently, which a one-off bonus never does.", "note": "Belgian negotiation lever, and often more valuable than the headline figure."}, {"id": "ex-interview-B1-05", "level": "B1", "pos": "noun", "gender": "m", "fr": "les éco-chèques", "en": "eco-vouchers", "format": "collocation", "q": "Which pair is right?", "options": ["Chèques-repas : par jour presté. Éco-chèques : une fois par an.", "Chèques-repas : une fois par an. Éco-chèques : par jour presté.", "Les deux sont payés avec le salaire en cash.", "Les deux servent uniquement au supermarché."], "a": 0, "trap": "swapping the two — they look alike, arrive on the same card and work completely differently", "expl": "Meal vouchers up to 10 € per day worked since January 2026; eco-vouchers up to 250 € a year on a restricted list of goods.", "note": "Belgian benefits: both are largely untaxed, which is why employers like them."}, {"id": "ex-interview-B1-06", "level": "B1", "pos": "expr", "fr": "ce qui explique que", "en": "which is why", "format": "cloze", "q": "J'ai suivi une formation, ce qui explique que je n'___ pas travaillé pendant six mois.", "options": ["aie", "ai", "avais", "aurai"], "a": 0, "trap": "ai — the indicative, which you will also hear; the subjunctive is the careful written choice", "expl": "After « ce qui explique que », French hesitates between the two, and the subjunctive is the safer, more polished option: que je n'aie pas travaillé, qu'il soit parti. « Le fait que » works the same way."}, {"id": "ex-interview-B1-07", "level": "B1", "pos": "verb", "fr": "prester", "en": "to work (hours), Belgian usage", "format": "fr2en", "options": ["to work or serve a period of time", "to lend money", "to give a speech", "to be prestigious"], "a": 0, "trap": "prêter — to lend; the two are close in sound and unrelated", "expl": "« prester un préavis », « les jours prestés » on a payslip. Standard in Belgian administration and payroll.", "note": "Belgian French. In France you would say « effectuer son préavis » and « les jours travaillés »."}, {"id": "ex-interview-B1-08", "level": "B1", "pos": "noun", "gender": "m", "fr": "le préavis", "en": "the notice period", "format": "collocation", "q": "In Belgium, how does an employee's notice compare to the employer's?", "options": ["Environ la moitié, avec un maximum de 13 semaines.", "Exactement la même durée.", "Le double, pour compenser.", "Il n'y en a pas pour le travailleur."], "a": 0, "trap": "'the same either way' — symmetrical and wrong under the statut unique", "expl": "Notice is counted in weeks by seniority and starts the Monday after notification. The employee's is roughly half, capped at 13 weeks.", "note": "Belgian rule since the statut unique of 2014."}, {"id": "ex-interview-B1-09", "level": "B1", "pos": "noun", "gender": "f", "fr": "la promesse d'embauche", "en": "the written job offer", "format": "cloze", "q": "Ne démissionnez jamais avant d'avoir reçu une ___ d'embauche écrite.", "options": ["promesse", "proposition", "prévision", "présentation"], "a": 0, "trap": "proposition — softer and non-binding; the binding document is « la promesse d'embauche »", "expl": "It commits the employer. A verbal yes on a Friday afternoon commits nobody at all."}, {"id": "ex-interview-B1-10", "level": "B1", "pos": "verb", "fr": "encadrer", "en": "to supervise", "format": "en2fr", "options": ["encadrer", "entourer", "endosser", "encourager"], "a": 0, "trap": "entourer — to surround; a physical verb that says nothing about responsibility", "expl": "All four infinitives. « J'ai encadré deux stagiaires » claims exactly the right amount of authority."}, {"id": "ex-interview-B1-11", "level": "B1", "pos": "noun", "gender": "f", "fr": "l'assurance groupe", "en": "the occupational pension", "format": "fr2en", "options": ["an employer-funded supplementary pension", "insurance for the whole staff's health", "collective liability cover", "insurance against redundancy"], "a": 0, "trap": "l'assurance hospitalisation — the health cover offered in the same breath", "expl": "The second pillar of the Belgian pension. Ask what percentage of your brut the employer pays in — that is what varies.", "note": "Belgian institution: the first pillar is the state pension, the third is private saving with a tax break."}, {"id": "ex-interview-B1-12", "level": "B1", "pos": "adj", "fr": "nonante", "en": "ninety", "format": "fr2en", "options": ["ninety", "nineteen", "seventy", "ninety-nine"], "a": 0, "trap": "septante — seventy, and in a salary that is a difference you will live with for years", "expl": "« trois mille trois cent nonante euros » = 3 390 €. Repeat any figure back before agreeing to it.", "note": "Belgian French. France says quatre-vingt-dix."}, {"id": "ex-interview-B1-13", "level": "B1", "pos": "noun", "gender": "m", "fr": "le trou dans le CV", "en": "the gap in the CV", "format": "collocation", "q": "Which explanation of a gap is strongest in a Belgian interview?", "options": ["Une formation suivie, avec les dates et l'attestation.", "« J'ai pris du temps pour moi. »", "« Je cherchais, mais le marché était difficile. »", "Ne rien dire et changer de sujet."], "a": 0, "trap": "the honest-sounding vague answers — they are true and they leave nothing for the recruiter to hold on to", "expl": "Name the period, say what you did in it, offer evidence, then move on. Two sentences is the right length."}, {"id": "ex-interview-B1-14", "level": "B1", "pos": "expr", "fr": "avoir difficile", "en": "to find it hard (Belgian French)", "format": "fr2en", "options": ["to find something hard to do", "to be a difficult person", "to make life hard for others", "to have a hard life"], "a": 0, "trap": "standard French would need « avoir du mal à » — the Belgian construction drops the noun entirely", "expl": "« J'ai encore difficile à répondre vite en néerlandais » is perfectly normal in a Brussels interview.", "note": "Belgian French. France says « j'ai encore du mal à… » and would hear the Belgian form as an error."}]}
};
